public class ExtrusionInteractionRestrictions : PlayerInteractionRestriction
{
	private Extrusion thisExtrusion;

	protected override void Awake()
	{
		base.Awake();
		thisExtrusion = GetComponent<Extrusion>();
	}

	public override bool PlayerInteractionAllowed(PhotonPlayer player)
	{
		if (thisExtrusion == null || thisExtrusion.IsExtrudingMesh)
		{
			return false;
		}
		return base.PlayerInteractionAllowed(player);
	}
}
public class PhysicsButtonVisual : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float releaseSpeed = 0.5f;

	[SerializeField]
	private Transform unpressedTransform;

	[SerializeField]
	private Transform pressedTransform;

	private Rigidbody rigidbody;

	private Vector3 buttonDownDirection;

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
		buttonDownDirection = (pressedTransform.position - unpressedTransform.position).normalized;
		rigidbody.position = unpressedTransform.position;
		rigidbody.velocity = Vector3.zero;
	}

	private void FixedUpdate()
	{
		Vector3 lhs = unpressedTransform.position - rigidbody.position;
		if (Vector3.Dot(lhs, buttonDownDirection) >= 0f - Mathf.Epsilon)
		{
			rigidbody.position = unpressedTransform.position;
			rigidbody.velocity = Vector3.zero;
			return;
		}
		rigidbody.velocity = -buttonDownDirection * releaseSpeed;
		Vector3 lhs2 = pressedTransform.position - rigidbody.position;
		if (Vector3.Dot(lhs2, buttonDownDirection) <= Mathf.Epsilon)
		{
			rigidbody.position = pressedTransform.position;
		}
	}
}
public class SinglePlayerInteractionRestriction : PlayerInteractionRestriction
{
	private int allowedPhotonPlayerID = PhotonPlayer.Invalid;

	public override bool PlayerInteractionAllowed(PhotonPlayer player)
	{
		return base.PlayerInteractionAllowed(player) && (allowedPhotonPlayerID == PhotonPlayer.Invalid || allowedPhotonPlayerID == player.ID);
	}

	public void SetPlayer(PhotonPlayer player)
	{
		if (player != null)
		{
			allowedPhotonPlayerID = player.ID;
		}
		else
		{
			ClearPlayer();
		}
	}

	public void ClearPlayer()
	{
		allowedPhotonPlayerID = PhotonPlayer.Invalid;
	}
}
public class TimerText : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private TextMesh[] timerTextMeshes;

	[SerializeField]
	private Text[] timerTexts;

	private GameManager gameManager;

	private void Start()
	{
		OnTimerUpdate(0f);
		gameManager = RecRoomSceneManager.Instance.GameManager;
	}

	private void Update()
	{
		float timer = 0f;
		if (gameManager != null)
		{
			timer = gameManager.GameTimerManager.TimeRemaining;
		}
		OnTimerUpdate(timer);
	}

	private void OnTimerUpdate(float timer)
	{
		string text = timer.ToTimeString();
		Text[] array = timerTexts;
		foreach (Text text2 in array)
		{
			text2.text = text;
		}
		TextMesh[] array2 = timerTextMeshes;
		foreach (TextMesh textMesh in array2)
		{
			textMesh.text = text;
		}
	}
}
public class DiscGolfGoal : Photon.MonoBehaviour
{
	[Header("Hole")]
	[SerializeField]
	private DiscGolfHole hole = DiscGolfHole.INVALID;

	[SerializeField]
	private int par = 3;

	[Header("Feedback")]
	[SerializeField]
	private Renderer beamRenderer;

	public DiscGolfHole Hole => hole;

	public int Par => par;

	public bool BeamEnabled
	{
		get
		{
			return beamRenderer.gameObject.activeSelf;
		}
		set
		{
			beamRenderer.gameObject.SetActive(value);
		}
	}
}
public enum DiscGolfHole
{
	INVALID = -1,
	HOLE_1,
	HOLE_2,
	HOLE_3,
	HOLE_4,
	HOLE_5,
	HOLE_6,
	HOLE_7,
	HOLE_8,
	HOLE_9,
	HOLE_10,
	HOLE_11,
	HOLE_12,
	HOLE_13,
	HOLE_14,
	HOLE_15,
	HOLE_16,
	HOLE_17,
	HOLE_18
}
public class DiscGolfManager : GameManager
{
	private enum DiscGolfGameStates
	{
		HOLE_RUNNING = 0,
		HOLE_FINISHED = 1,
		INVALID = 65535
	}

	private class TeamData
	{
		private SynchronizedField<int> _stroke;

		private SynchronizedField<Vector3> _anchor;

		private SynchronizedField<bool> _holeFinished;

		private SynchronizedField<bool> _powerupUsed;

		public int Stroke
		{
			get
			{
				return _stroke.Get();
			}
			set
			{
				_stroke.ForceSet(value);
			}
		}

		public Vector3 Anchor
		{
			get
			{
				return _anchor.Get();
			}
			set
			{
				_anchor.ForceSet(value);
			}
		}

		public bool HoleFinished
		{
			get
			{
				return _holeFinished.Get();
			}
			set
			{
				_holeFinished.ForceSet(value);
			}
		}

		public bool PowerupUsed
		{
			get
			{
				return _powerupUsed.Get();
			}
			set
			{
				_powerupUsed.ForceSet(value);
			}
		}

		public TeamData(GameTeam team, DiscGolfManager manager)
		{
			_stroke = new SynchronizedField<int>(manager, GetTeamKey(team, "HOLE_STROKE"), 0, SetterPermissionMode.ANYONE);
			_anchor = new SynchronizedField<Vector3>(manager, GetTeamKey(team, "ANCHOR"), Vector3.zero, SetterPermissionMode.ANYONE);
			_holeFinished = new SynchronizedField<bool>(manager, GetTeamKey(team, "HOLE_FINISHED"), defaultValue: false, SetterPermissionMode.ANYONE);
			_powerupUsed = new SynchronizedField<bool>(manager, GetTeamKey(team, "HOLE_USED_POWERUP"), defaultValue: false, SetterPermissionMode.ANYONE);
		}

		private static string GetTeamKey(GameTeam team, string subkey)
		{
			return $"{(int)team}.{subkey}";
		}
	}

	[Header("Disc Golf")]
	[SerializeField]
	private float strokeIncrementThreshold = 3f;

	[SerializeField]
	private float mercyRuleHoleScore = 7f;

	[Header("Holes")]
	[SerializeField]
	private DiscGolfHole firstHole;

	[SerializeField]
	private DiscGolfHole lastHole = DiscGolfHole.HOLE_9;

	[Header("Score Notifications")]
	[SerializeField]
	private string scoreHoleInOne = "Hole In One!";

	[SerializeField]
	private string scoreLessThanNeg2 = "Albatross";

	[SerializeField]
	private string scoreNeg2 = "Eagle";

	[SerializeField]
	private string scoreNeg1 = "Birdie";

	[SerializeField]
	private string scoreZero = "Par";

	[SerializeField]
	private string scorePos1 = "Bogey";

	[SerializeField]
	private string scorePos2 = "Double Bogey";

	[SerializeField]
	private string scorePos3 = "Triple Bogey";

	private const float HOLE_FINISHED_STATE_DURATION = 6f;

	private const int DEFAULT_HOLE_PAR = 3;

	private SynchronizedStateMachine discGolfStateMachine;

	private SynchronizedTimer masterDiscGolfStateTimer;

	private List<DiscGolfDisc> gameplayDiscs = new List<DiscGolfDisc>();

	private DiscGolfGoal[] goals;

	private DiscGolfTee[] tees;

	private DiscGolfPowerUp[] powerups;

	private SynchronizedField<int> _currentHoleId;

	private SynchronizedField<int> _firstHoleId;

	private SynchronizedField<int> _lastHoleId;

	private Dictionary<GameTeam, TeamData> teamData = new Dictionary<GameTeam, TeamData>();

	private DiscGolfHole CurrentHole
	{
		get
		{
			return (DiscGolfHole)_currentHoleId.Get();
		}
		set
		{
			_currentHoleId.ForceSet((int)value);
		}
	}

	private int CurrentHoleNumber => (int)(CurrentHole + 1);

	private DiscGolfHole FirstHole
	{
		get
		{
			return (DiscGolfHole)_firstHoleId.Get();
		}
		set
		{
			_firstHoleId.ForceSet((int)value);
		}
	}

	private DiscGolfHole LastHole
	{
		get
		{
			return (DiscGolfHole)_lastHoleId.Get();
		}
		set
		{
			_lastHoleId.ForceSet((int)value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_currentHoleId = new SynchronizedField<int>(this, "CURRENT_HOLE_ID", -1, SetterPermissionMode.MASTER);
		_firstHoleId = new SynchronizedField<int>(this, "FIRST_HOLE_ID", -1, SetterPermissionMode.MASTER);
		_lastHoleId = new SynchronizedField<int>(this, "LAST_HOLE_ID", -1, SetterPermissionMode.MASTER);
		discGolfStateMachine = new SynchronizedStateMachine("DISC_GOLF", SetterPermissionMode.MASTER);
		discGolfStateMachine.AddState(ushort.MaxValue, null, null, null);
		discGolfStateMachine.AddState(0, OnEnterHoleRunningState, null, OnUpdateHoleRunningState);
		discGolfStateMachine.AddState(1, OnEnterHoleFinishedState, null, OnUpdateHoleFinishedState);
		masterDiscGolfStateTimer = new SynchronizedTimer(this, "DISC_GOLF_TIMER", SetterPermissionMode.MASTER);
		goals = UnityEngine.Object.FindObjectsOfType<DiscGolfGoal>();
		tees = UnityEngine.Object.FindObjectsOfType<DiscGolfTee>();
		DiscGolfDisc[] array = UnityEngine.Object.FindObjectsOfType<DiscGolfDisc>();
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SuppressesTeleport = true;
			array[i].SupportsKillzones = true;
			if (array[i].GetComponent<GamePracticeObject>() == null)
			{
				DiscGolfDisc discGolfDisc = array[i];
				discGolfDisc.DiscPickupEvent = (DiscGolfDisc.DiscPickup)Delegate.Combine(discGolfDisc.DiscPickupEvent, new DiscGolfDisc.DiscPickup(OnDiscPickup));
				discGolfDisc.DiscScoreEvent = (DiscGolfDisc.DiscScore)Delegate.Combine(discGolfDisc.DiscScoreEvent, new DiscGolfDisc.DiscScore(OnDiscScore));
				discGolfDisc.DiscHazardEvent = (DiscGolfDisc.DiscHazard)Delegate.Combine(discGolfDisc.DiscHazardEvent, new DiscGolfDisc.DiscHazard(OnDiscHazard));
				discGolfDisc.DiscStopMovingEvent += OnDiscStopMoving;
				gameplayDiscs.Add(discGolfDisc);
			}
		}
		powerups = UnityEngine.Object.FindObjectsOfType<DiscGolfPowerUp>();
		for (int j = 0; j < powerups.Length; j++)
		{
			DiscGolfPowerUp obj = powerups[j];
			obj.PickupEvent = (DiscGolfPowerUp.Pickup)Delegate.Combine(obj.PickupEvent, new DiscGolfPowerUp.Pickup(OnPowerupPickup));
		}
	}

	protected override void Initialize()
	{
		base.Initialize();
		discGolfStateMachine.Initialize(this, ushort.MaxValue);
	}

	protected override void Update()
	{
		base.Update();
		discGolfStateMachine.Update();
		masterDiscGolfStateTimer.UpdateCallbacks();
	}

	protected override void OnGameStart()
	{
		if (PhotonNetwork.isMasterClient)
		{
			FirstHole = firstHole;
			LastHole = lastHole;
			CurrentHole = firstHole;
			discGolfStateMachine.EnterState(0);
		}
	}

	protected override void OnGameEnd()
	{
		if (PhotonNetwork.isMasterClient)
		{
			discGolfStateMachine.EnterState(ushort.MaxValue);
		}
	}

	protected override void ResetScene()
	{
		base.ResetScene();
		if (PhotonNetwork.isMasterClient)
		{
			MasterDisableGameplayDiscs();
		}
		UpdateHelpBeams();
	}

	private void OnDiscScore(DiscGolfDisc disc, DiscGolfGoal goal, Player thrower)
	{
		if (thrower.PhotonPlayer.isLocal && IsValidScore(disc, goal, thrower.PhotonPlayer))
		{
			base.photonView.RPC("RpcMasterFinishHole", PhotonTargets.MasterClient, disc.photonView.viewID, goal.photonView.viewID, thrower.PhotonPlayer, false);
		}
	}

	private void OnDiscPickup(DiscGolfDisc disc, Player pickupPlayer)
	{
		if (pickupPlayer.PhotonPlayer.isLocal && IsValidThrow(disc, pickupPlayer.PhotonPlayer))
		{
			IncrementTeamStroke(disc, pickupPlayer);
			int teamStroke = GetTeamStroke(disc.Team);
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Stroke " + teamStroke, 1.5f);
		}
	}

	private void OnDiscHazard(DiscGolfDisc disc, Killzone hazard, Player throwPlayer)
	{
		if (throwPlayer.PhotonPlayer.isLocal && IsValidThrow(disc, throwPlayer.PhotonPlayer))
		{
			IncrementTeamStroke(disc, throwPlayer, checkDistance: false);
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Hazard", 1.5f);
		}
	}

	private void OnDiscStopMoving(DiscGolfDisc disc, Player throwPlayer)
	{
		if (throwPlayer.PhotonPlayer.isLocal && IsValidThrow(disc, throwPlayer.PhotonPlayer))
		{
			IncrementTeamStroke(disc, throwPlayer);
		}
	}

	private void MasterFinishHole(DiscGolfDisc disc, DiscGolfGoal goal, PhotonPlayer thrower, bool forfeit)
	{
		if (PhotonNetwork.isMasterClient && IsValidScore(disc, goal, thrower))
		{
			disc.Disable();
			SetTeamHoleFinished(disc.Team, isHoleFinished: true);
			int teamStroke = GetTeamStroke(disc.Team);
			int deltaScore = teamStroke - goal.Par;
			base.StatsManager.AddScore(base.TeamManager.GetPlayerTeam(thrower), deltaScore);
			base.photonView.RPC("RpcOnFinishHole", PhotonTargets.All, goal.photonView.viewID, thrower, forfeit, teamStroke);
		}
	}

	private void OnFinishHole(DiscGolfGoal goal, PhotonPlayer thrower, bool forfeit, int throwerHoleStrokeCount)
	{
		int score = GetScore(goal.Par, throwerHoleStrokeCount);
		string strokeCountString = GetStrokeCountString(throwerHoleStrokeCount, score);
		GameTeam playerTeam = base.TeamManager.GetPlayerTeam(thrower);
		ScreenSpaceNotificationManager.NotificationType style = ((!thrower.isLocal) ? ScreenSpaceNotificationManager.NotificationType.Minor : ScreenSpaceNotificationManager.NotificationType.Medium);
		if (forfeit)
		{
			ScreenSpaceNotificationManager.Instance.Play(style, "Mercy Rule: " + base.TeamManager.GetTeamName(playerTeam), strokeCountString, 1.5f);
		}
		else
		{
			ScreenSpaceNotificationManager.Instance.Play(style, base.TeamManager.GetTeamName(playerTeam) + " Scores!", strokeCountString, 1.5f);
			base.FxManager.PlayFX(FxType.GOAL, goal.transform.position, goal.transform.rotation);
		}
		if (thrower.isLocal)
		{
			Player.LocalPlayer.PlayerEvents.DiscGolfCompletedHole(score);
			Profiles.LocalAddScore(RecRoomSceneManager.CurrentSceneName, CurrentHole.ToString(), score, "Par " + goal.Par, base.StatsManager.GetScore(playerTeam));
		}
	}

	private bool IsValidScore(DiscGolfDisc disc, DiscGolfGoal goal, PhotonPlayer thrower)
	{
		return discGolfStateMachine.CurrentStateId == 0 && CurrentHole == goal.Hole && !base.TeamManager.IsPlayerSpectator(thrower) && !GetTeamHoleFinished(disc.Team);
	}

	private bool IsValidThrow(DiscGolfDisc disc, PhotonPlayer player)
	{
		return discGolfStateMachine.CurrentStateId == 0 && !base.TeamManager.IsPlayerSpectator(player) && !GetTeamHoleFinished(disc.Team);
	}

	private void IncrementTeamStroke(DiscGolfDisc disc, Player thrower, bool checkDistance = true)
	{
		Vector3 vector = Vector3.ProjectOnPlane(disc.transform.position - GetTeamAnchorPoint(disc.Team), Vector3.up);
		if (checkDistance && !(vector.magnitude >= strokeIncrementThreshold))
		{
			return;
		}
		AddTeamStroke(disc.Team, 1);
		SetTeamAnchorPoint(disc.Team, disc.transform.position);
		int teamStroke = GetTeamStroke(disc.Team);
		DiscGolfGoal currentGoal = GetCurrentGoal();
		if (currentGoal != null)
		{
			int score = GetScore(GetCurrentGoal().Par, teamStroke);
			if ((float)score >= mercyRuleHoleScore)
			{
				base.photonView.RPC("RpcMasterFinishHole", PhotonTargets.MasterClient, disc.photonView.viewID, currentGoal.photonView.viewID, thrower.PhotonPlayer, true);
			}
		}
	}

	private DiscGolfDisc GetTeamDisc(GameTeam team)
	{
		for (int i = 0; i < gameplayDiscs.Count; i++)
		{
			if (gameplayDiscs[i].Team == team)
			{
				return gameplayDiscs[i];
			}
		}
		return null;
	}

	private void MasterDisableGameplayDiscs()
	{
		if (PhotonNetwork.isMasterClient)
		{
			for (int i = 0; i < gameplayDiscs.Count; i++)
			{
				gameplayDiscs[i].Disable();
			}
		}
	}

	private void OnPowerupPickup(DiscGolfPowerUp powerup, DiscGolfDisc disc, Player discThrower)
	{
		if (discThrower.PhotonPlayer.isLocal && IsValidPowerup(disc, powerup, discThrower.PhotonPlayer))
		{
			base.photonView.RPC("RpcMasterRequestPowerup", PhotonTargets.MasterClient, disc.photonView.viewID, powerup.photonView.viewID, discThrower.PhotonPlayer);
		}
	}

	private void MasterRequestPowerup(DiscGolfDisc disc, DiscGolfPowerUp powerup, PhotonPlayer discThrower)
	{
		if (PhotonNetwork.isMasterClient && IsValidPowerup(disc, powerup, discThrower))
		{
			SetTeamPowerupUsed(disc.Team, isPowerupUsed: true);
			AddTeamStroke(disc.Team, powerup.ScoreAdjust);
			base.photonView.RPC("RpcOnPowerup", PhotonTargets.All, powerup.photonView.viewID, discThrower);
		}
	}

	private void OnPowerup(DiscGolfPowerUp powerup, PhotonPlayer discThrower)
	{
		base.FxManager.PlayFX(FxType.POWERUP_PICKUP, powerup.transform.position, powerup.transform.rotation);
		powerup.OnPickup();
		if (discThrower.isLocal)
		{
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Bonus!", "Stroke " + powerup.ScoreAdjust, 1.5f);
		}
	}

	private bool IsValidPowerup(DiscGolfDisc disc, DiscGolfPowerUp powerup, PhotonPlayer discThrower)
	{
		return discGolfStateMachine.CurrentStateId == 0 && CurrentHole == powerup.Hole && !base.TeamManager.IsPlayerSpectator(discThrower) && !GetTeamHoleFinished(disc.Team) && !GetTeamPowerupUsed(disc.Team);
	}

	private DiscGolfGoal GetCurrentGoal()
	{
		DiscGolfHole currentHole = CurrentHole;
		for (int i = 0; i < goals.Length; i++)
		{
			if (goals[i].Hole == currentHole)
			{
				return goals[i];
			}
		}
		return null;
	}

	private DiscGolfTee GetTee(GameTeam team)
	{
		DiscGolfHole currentHole = CurrentHole;
		for (int i = 0; i < tees.Length; i++)
		{
			if (tees[i].Hole == currentHole && tees[i].Team == team)
			{
				return tees[i];
			}
		}
		return null;
	}

	private void UpdateHelpBeams()
	{
		DiscGolfHole currentHole = CurrentHole;
		bool flag = discGolfStateMachine.CurrentStateId == 0;
		for (int i = 0; i < goals.Length; i++)
		{
			goals[i].BeamEnabled = flag && goals[i].Hole == currentHole;
		}
		if (!base.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			GameTeam playerTeam = base.TeamManager.GetPlayerTeam(PhotonNetwork.player);
			for (int j = 0; j < gameplayDiscs.Count; j++)
			{
				gameplayDiscs[j].BeamEnabled = flag && gameplayDiscs[j].Team == playerTeam;
			}
		}
	}

	private void OnEnterHoleRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterInitializeHole();
		}
		UpdateHelpBeams();
		DiscGolfGoal currentGoal = GetCurrentGoal();
		base.PresenceSettings.CurrentPresenceString = "Hole " + CurrentHoleNumber + " Par " + currentGoal.Par;
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Hole " + CurrentHoleNumber, "Par " + currentGoal.Par, 3f);
	}

	private void OnUpdateHoleRunningState()
	{
		if (PhotonNetwork.isMasterClient && IsHoleFinished())
		{
			discGolfStateMachine.EnterState(1);
		}
	}

	private bool IsHoleFinished()
	{
		GameTeam[] activeTeams = base.TeamManager.GetActiveTeams();
		for (int i = 0; i < activeTeams.Length; i++)
		{
			if (!GetTeamHoleFinished(activeTeams[i]))
			{
				return false;
			}
		}
		return true;
	}

	private void OnEnterHoleFinishedState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterDiscGolfStateTimer.StartTimer(6f);
		}
		masterDiscGolfStateTimer.AddTimeRemainingCallback(4.5f, PlayHoleCompletedFeedback);
	}

	private void OnUpdateHoleFinishedState()
	{
		if (PhotonNetwork.isMasterClient && masterDiscGolfStateTimer.TimerOver)
		{
			if (CurrentHole >= LastHole)
			{
				MasterStopGame();
				return;
			}
			CurrentHole++;
			discGolfStateMachine.EnterState(0);
		}
	}

	private void PlayHoleCompletedFeedback()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Hole " + CurrentHoleNumber + " Completed!", 3f);
	}

	private TeamData GetTeamData(GameTeam team)
	{
		if (!teamData.TryGetValue(team, out var value))
		{
			value = new TeamData(team, this);
			teamData[team] = value;
		}
		return value;
	}

	private int GetScore(int par, int strokeCount)
	{
		return strokeCount - par;
	}

	private int GetTeamStroke(GameTeam team)
	{
		return GetTeamData(team).Stroke;
	}

	private void SetTeamStroke(GameTeam team, int strokeCount)
	{
		GetTeamData(team).Stroke = strokeCount;
	}

	private void AddTeamStroke(GameTeam team, int deltaScore)
	{
		GetTeamData(team).Stroke += deltaScore;
	}

	private Vector3 GetTeamAnchorPoint(GameTeam team)
	{
		return GetTeamData(team).Anchor;
	}

	private void SetTeamAnchorPoint(GameTeam team, Vector3 anchorPoint)
	{
		GetTeamData(team).Anchor = anchorPoint;
	}

	private bool GetTeamHoleFinished(GameTeam team)
	{
		return GetTeamData(team).HoleFinished;
	}

	private void SetTeamHoleFinished(GameTeam team, bool isHoleFinished)
	{
		GetTeamData(team).HoleFinished = isHoleFinished;
	}

	private bool GetTeamPowerupUsed(GameTeam team)
	{
		return GetTeamData(team).PowerupUsed;
	}

	private void SetTeamPowerupUsed(GameTeam team, bool isPowerupUsed)
	{
		GetTeamData(team).PowerupUsed = isPowerupUsed;
	}

	private void MasterInitializeHole()
	{
		GameTeam[] activeTeams = base.TeamManager.GetActiveTeams();
		for (int i = 0; i < activeTeams.Length; i++)
		{
			DiscGolfTee tee = GetTee(activeTeams[i]);
			DiscGolfDisc teamDisc = GetTeamDisc(activeTeams[i]);
			if (tee == null || teamDisc == null)
			{
				UnityEngine.Debug.LogError("Could not spawn " + GameTeamSettings.GetTeamName(activeTeams[i]) + " Team disc on Hole " + CurrentHoleNumber);
			}
			else
			{
				teamDisc.MasterResetToDefault(tee.transform.position, tee.transform.rotation);
				SetTeamAnchorPoint(activeTeams[i], tee.transform.position);
			}
			SetTeamHoleFinished(activeTeams[i], isHoleFinished: false);
			SetTeamStroke(activeTeams[i], 1);
			SetTeamPowerupUsed(activeTeams[i], isPowerupUsed: false);
		}
	}

	private string GetStrokeCountString(int strokeCount, int score)
	{
		string empty = string.Empty;
		if (strokeCount == 1)
		{
			return scoreHoleInOne;
		}
		if (score < -2)
		{
			return scoreLessThanNeg2;
		}
		return score switch
		{
			-2 => scoreNeg2, 
			-1 => scoreNeg1, 
			0 => scoreZero, 
			1 => scorePos1, 
			2 => scorePos2, 
			3 => scorePos3, 
			_ => "+" + score, 
		};
	}

	[PunRPC]
	private void RpcMasterFinishHole(int discPhotonViewId, int goalPhotonViewId, PhotonPlayer thrower, bool forfeit)
	{
		PhotonView photonView = PhotonView.Find(discPhotonViewId);
		DiscGolfDisc discGolfDisc = ((!(photonView != null)) ? null : photonView.GetComponent<DiscGolfDisc>());
		PhotonView photonView2 = PhotonView.Find(goalPhotonViewId);
		DiscGolfGoal discGolfGoal = ((!(photonView2 != null)) ? null : photonView2.GetComponent<DiscGolfGoal>());
		if (discGolfDisc != null && discGolfGoal != null)
		{
			MasterFinishHole(discGolfDisc, discGolfGoal, thrower, forfeit);
		}
	}

	[PunRPC]
	private void RpcOnFinishHole(int goalPhotonViewId, PhotonPlayer thrower, bool forfeit, int throwerHoleStrokeCount)
	{
		PhotonView photonView = PhotonView.Find(goalPhotonViewId);
		DiscGolfGoal discGolfGoal = ((!(photonView != null)) ? null : photonView.GetComponent<DiscGolfGoal>());
		if (discGolfGoal != null)
		{
			OnFinishHole(discGolfGoal, thrower, forfeit, throwerHoleStrokeCount);
		}
	}

	[PunRPC]
	private void RpcMasterRequestPowerup(int discPhotonViewId, int powerupPhotonViewId, PhotonPlayer discThrower)
	{
		PhotonView photonView = PhotonView.Find(discPhotonViewId);
		DiscGolfDisc discGolfDisc = ((!(photonView != null)) ? null : photonView.GetComponent<DiscGolfDisc>());
		PhotonView photonView2 = PhotonView.Find(powerupPhotonViewId);
		DiscGolfPowerUp discGolfPowerUp = ((!(photonView2 != null)) ? null : photonView2.GetComponent<DiscGolfPowerUp>());
		if (discGolfDisc != null && discGolfPowerUp != null)
		{
			MasterRequestPowerup(discGolfDisc, discGolfPowerUp, discThrower);
		}
	}

	[PunRPC]
	private void RpcOnPowerup(int powerupPhotonViewId, PhotonPlayer discThrower)
	{
		PhotonView photonView = PhotonView.Find(powerupPhotonViewId);
		DiscGolfPowerUp discGolfPowerUp = ((!(photonView != null)) ? null : photonView.GetComponent<DiscGolfPowerUp>());
		if (discGolfPowerUp != null)
		{
			OnPowerup(discGolfPowerUp, discThrower);
		}
	}

	protected override void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (PhotonNetwork.isMasterClient && discGolfStateMachine.CurrentStateId == 0 && !base.TeamManager.IsPlayerSpectator(player))
		{
			GameTeam playerTeam = base.TeamManager.GetPlayerTeam(player);
			DiscGolfDisc teamDisc = GetTeamDisc(playerTeam);
			teamDisc.Disable();
		}
		base.OnPhotonPlayerDisconnected(player);
	}
}
public class DiscGolfPowerUp : Powerup
{
	public delegate void Pickup(DiscGolfPowerUp thisPowerup, DiscGolfDisc disc, Player discThrower);

	[Header("Hole")]
	[SerializeField]
	private DiscGolfHole hole = DiscGolfHole.INVALID;

	[SerializeField]
	private int scoreAdjust = -1;

	[SerializeField]
	private ParticleSystem hitParticles;

	[SerializeField]
	private RecRoomAudioClip onHit;

	private CollisionForwarder collisionForwarder;

	public Pickup PickupEvent;

	public DiscGolfHole Hole => hole;

	public int ScoreAdjust => scoreAdjust;

	protected override void Awake()
	{
		base.Awake();
		collisionForwarder = GetComponentInChildren<CollisionForwarder>();
		if (collisionForwarder != null)
		{
			collisionForwarder.TriggerEnter += OnTriggerEnter;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (collisionForwarder != null)
		{
			collisionForwarder.TriggerEnter -= OnTriggerEnter;
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		Tool colliderTool = collider.GetColliderTool();
		DiscGolfDisc discGolfDisc = ((!(colliderTool != null)) ? null : colliderTool.GetComponent<DiscGolfDisc>());
		if (base.IsAlive && discGolfDisc != null && discGolfDisc.Thrower != null && discGolfDisc.Thrower.isLocal && PickupEvent != null)
		{
			PickupEvent(this, discGolfDisc, discGolfDisc.Thrower.ToPlayer());
		}
	}

	public void OnPickup()
	{
		if (hitParticles != null)
		{
			hitParticles.Play();
			AudioManager.Play3DSFX(onHit, base.transform.position);
		}
	}
}
public class DiscGolfTee : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private GameTeam team = GameTeam.INVALID;

	[SerializeField]
	private DiscGolfHole hole = DiscGolfHole.INVALID;

	public GameTeam Team => team;

	public DiscGolfHole Hole => hole;
}
public class Basketball : Ball
{
	[Header("Basketball")]
	public ParticleSystem FireTrail;

	public PooledParticle PassedRimParticle;

	public RecRoomAudioClip PassedRimAudio;

	public void PassedRim()
	{
		AudioManager.Play3DSFX(PassedRimAudio, base.transform);
		PooledParticle pooledParticle = ObjectPool.Instance.Acquire(PassedRimParticle);
		if (pooledParticle != null)
		{
			pooledParticle.transform.position = base.transform.position;
			pooledParticle.transform.rotation = base.transform.rotation;
			pooledParticle.Play();
		}
		if (FireTrail.gameObject.activeSelf)
		{
			CancelInvoke("HideFireTrail");
		}
		FireTrail.gameObject.SetActive(value: true);
		FireTrail.Play();
		Invoke("HideFireTrail", 1f);
	}

	private void HideFireTrail()
	{
		FireTrail.gameObject.SetActive(value: false);
	}
}
public class BasketballRim : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private CollisionForwarder rimTop;

	[SerializeField]
	private CollisionForwarder rimBottom;

	private List<Basketball> trackedBalls = new List<Basketball>();

	private void Start()
	{
		rimTop.TriggerEnter += RimTop_TriggerEnter;
		rimBottom.TriggerEnter += RimBottom_TriggerEnter;
	}

	private void RimTop_TriggerEnter(Collider trigger)
	{
		Basketball basketballTool = GetBasketballTool(trigger);
		if (basketballTool != null && !trackedBalls.Contains(basketballTool))
		{
			trackedBalls.Add(basketballTool);
		}
	}

	private void RimBottom_TriggerEnter(Collider trigger)
	{
		Basketball basketballTool = GetBasketballTool(trigger);
		if (basketballTool != null && trackedBalls.Contains(basketballTool))
		{
			trackedBalls.Remove(basketballTool);
			basketballTool.PassedRim();
		}
	}

	private Basketball GetBasketballTool(Collider collider)
	{
		ToolCollider component = collider.GetComponent<ToolCollider>();
		if (component != null)
		{
			return component.Tool as Basketball;
		}
		return null;
	}

	private void Update()
	{
		for (int num = trackedBalls.Count - 1; num >= 0; num--)
		{
			if (trackedBalls[num].transform.position.y < rimBottom.transform.position.y)
			{
				trackedBalls.RemoveAt(num);
			}
		}
	}
}
public class Dodgeball : Ball
{
	public delegate void DodgeballCatch(Dodgeball thisDodgeball, Player catchPlayer, Player thrower, Vector3 catchPoint);

	public delegate void DodgeballHitPlayer(Dodgeball thisDodgeball, Player thrower, Player hitPlayer, Vector3 hitPoint);

	[SerializeField]
	private ParticleSystem fireTrailParticles;

	private SynchronizedField<bool> isAlive;

	private SynchronizedField<int> throwerId;

	private SynchronizedField<int> firstHitPlayerId;

	private SynchronizedField<Vector3> firstHitPlayerPoint;

	public DodgeballCatch DodgeballCatchEvent;

	public DodgeballHitPlayer DodgeballPlayerOutEvent;

	public DodgeballHitPlayer DodgeballPlayerHitEvent;

	private bool IsAlive
	{
		get
		{
			return isAlive.Get();
		}
		set
		{
			isAlive.ForceSet(value);
		}
	}

	private PhotonPlayer Thrower
	{
		get
		{
			return PhotonPlayer.Find(throwerId.Get());
		}
		set
		{
			throwerId.ForceSet(value?.ID ?? PhotonPlayer.Invalid);
		}
	}

	private PhotonPlayer FirstHitPlayer
	{
		get
		{
			return PhotonPlayer.Find(firstHitPlayerId.Get());
		}
		set
		{
			firstHitPlayerId.ForceSet(value?.ID ?? PhotonPlayer.Invalid);
		}
	}

	private Vector3 FirstHitPlayerPoint
	{
		get
		{
			return firstHitPlayerPoint.Get();
		}
		set
		{
			firstHitPlayerPoint.ForceSet(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		isAlive = new SynchronizedField<bool>(this, "IS_ALIVE", defaultValue: true, SetterPermissionMode.AUTHORITY, UpdateAliveDeadState);
		throwerId = new SynchronizedField<int>(this, "THROWER_ID", PhotonPlayer.Invalid, SetterPermissionMode.AUTHORITY);
		firstHitPlayerId = new SynchronizedField<int>(this, "FIRST_HIT_ID", PhotonPlayer.Invalid, SetterPermissionMode.AUTHORITY);
		firstHitPlayerPoint = new SynchronizedField<Vector3>(this, "FIRST_HIT_POINT", Vector3.zero, SetterPermissionMode.AUTHORITY);
	}

	protected override void Start()
	{
		base.Start();
		UpdateAliveDeadState();
	}

	protected override void OnReset(Vector3 position, Quaternion rotation, bool wasEnabled, Vector3 oldPosition, bool wasCleanedUp)
	{
		base.OnReset(position, rotation, wasEnabled, oldPosition, wasCleanedUp);
		if (base.hasAuthority)
		{
			Thrower = null;
			FirstHitPlayer = null;
			IsAlive = false;
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
		if (base.hasAuthority)
		{
			if (IsAlive && Thrower != player.PhotonPlayer && DodgeballCatchEvent != null)
			{
				DodgeballCatchEvent(this, player, Thrower.ToPlayer(), base.transform.position);
			}
			Thrower = null;
			FirstHitPlayer = null;
			IsAlive = false;
		}
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		if (base.hasAuthority)
		{
			Thrower = player.PhotonPlayer;
			FirstHitPlayer = null;
			IsAlive = true;
		}
	}

	protected override void OnPlayerCollisionEnter(Player hitPlayer, Player.BodyPart bodyPart, Vector3 point, Collision collision)
	{
		base.OnPlayerCollisionEnter(hitPlayer, bodyPart, point, collision);
		if (!base.hasAuthority || base.IsHeld || !IsAlive || Thrower == null)
		{
			return;
		}
		if (FirstHitPlayer == null)
		{
			FirstHitPlayer = hitPlayer.PhotonPlayer;
			FirstHitPlayerPoint = point;
			if (FirstHitPlayer != null && DodgeballPlayerHitEvent != null)
			{
				DodgeballPlayerHitEvent(this, Thrower.ToPlayer(), FirstHitPlayer.ToPlayer(), FirstHitPlayerPoint);
			}
		}
		else if (hitPlayer.PhotonPlayer != FirstHitPlayer)
		{
			if (DodgeballPlayerOutEvent != null)
			{
				DodgeballPlayerOutEvent(this, Thrower.ToPlayer(), FirstHitPlayer.ToPlayer(), FirstHitPlayerPoint);
			}
			IsAlive = false;
		}
	}

	protected override void OnToolCollisionEnter(Tool hitTool, Vector3 point, Collision collision)
	{
		base.OnToolCollisionEnter(hitTool, point, collision);
		if (base.hasAuthority)
		{
			if (FirstHitPlayer != null && DodgeballPlayerOutEvent != null)
			{
				DodgeballPlayerOutEvent(this, Thrower.ToPlayer(), FirstHitPlayer.ToPlayer(), FirstHitPlayerPoint);
			}
			IsAlive = false;
		}
	}

	protected override void OnOtherCollisionEnter(Layers hitLayer, Vector3 point, Collision collision)
	{
		base.OnOtherCollisionEnter(hitLayer, point, collision);
		if (base.hasAuthority)
		{
			if (FirstHitPlayer != null && DodgeballPlayerOutEvent != null)
			{
				DodgeballPlayerOutEvent(this, Thrower.ToPlayer(), FirstHitPlayer.ToPlayer(), FirstHitPlayerPoint);
			}
			IsAlive = false;
		}
	}

	private void UpdateAliveDeadState()
	{
		bool flag = IsAlive;
		SupportsAssistedCatching = !flag;
		if (flag)
		{
			fireTrailParticles.Play();
		}
		else
		{
			fireTrailParticles.Stop();
		}
	}
}
public class DodgeballManager : GameManager
{
	private enum DodgeballGameStates
	{
		ROUND_START = 0,
		ROUND_RUNNING = 1,
		ROUND_OVER = 2,
		INVALID = 65535
	}

	private enum DodgeballSpawnPointTags
	{
		Court,
		Sidelines
	}

	private enum DodgeballTeleportRegionTags
	{
		Court,
		Sidelines
	}

	private class PlayerData
	{
		private SynchronizedField<bool> _onSidelines;

		public bool OnSidelines
		{
			get
			{
				return _onSidelines.Get();
			}
			set
			{
				_onSidelines.ForceSet(value);
			}
		}

		public PlayerData(PhotonPlayer player)
		{
			_onSidelines = new SynchronizedField<bool>(player, "ON_SIDELINES", defaultValue: false, SetterPermissionMode.ANYONE);
		}
	}

	[Header("Rounds")]
	[SerializeField]
	private int maxRounds = 5;

	private SynchronizedStateMachine dodgeballStateMachine;

	private SynchronizedTimer masterDodgeballStateTimer;

	private Dodgeball[] balls;

	private const float ROUND_NOTIFICATION_DURATION = 3f;

	private const float DEATH_NOTIFICATION_DURATION = 3f;

	private const float HIT_NOTIFICATION_OFFSET_DISTANCE = 0.35f;

	private Dictionary<int, PlayerData> playerData = new Dictionary<int, PlayerData>();

	private int ScoreToWin => maxRounds / 2 + 1;

	protected override void Awake()
	{
		base.Awake();
		dodgeballStateMachine = new SynchronizedStateMachine("DODGEBALL", SetterPermissionMode.MASTER);
		dodgeballStateMachine.AddState(ushort.MaxValue, null, null, null);
		dodgeballStateMachine.AddState(0, OnEnterRoundStartState, null, OnUpdateRoundStartState);
		dodgeballStateMachine.AddState(1, OnEnterRoundRunningState, null, OnUpdateRoundRunningState);
		dodgeballStateMachine.AddState(2, OnEnterRoundOverState, OnExitRoundOverState, OnUpdateRoundOverState);
		masterDodgeballStateTimer = new SynchronizedTimer(this, "DODGEBALL_TIMER", SetterPermissionMode.MASTER);
		balls = UnityEngine.Object.FindObjectsOfType<Dodgeball>();
		for (int i = 0; i < balls.Length; i++)
		{
			Dodgeball obj = balls[i];
			obj.DodgeballCatchEvent = (Dodgeball.DodgeballCatch)Delegate.Combine(obj.DodgeballCatchEvent, new Dodgeball.DodgeballCatch(OnDodgeballCatch));
			Dodgeball obj2 = balls[i];
			obj2.DodgeballPlayerOutEvent = (Dodgeball.DodgeballHitPlayer)Delegate.Combine(obj2.DodgeballPlayerOutEvent, new Dodgeball.DodgeballHitPlayer(OnDodgeballPlayerOut));
			Dodgeball obj3 = balls[i];
			obj3.DodgeballPlayerHitEvent = (Dodgeball.DodgeballHitPlayer)Delegate.Combine(obj3.DodgeballPlayerHitEvent, new Dodgeball.DodgeballHitPlayer(OnDodgeballPlayerHit));
			balls[i].SupportsKillzones = true;
		}
	}

	protected override void Initialize()
	{
		base.Initialize();
		dodgeballStateMachine.Initialize(this, ushort.MaxValue);
	}

	protected override void Update()
	{
		base.Update();
		dodgeballStateMachine.Update();
		masterDodgeballStateTimer.UpdateCallbacks();
	}

	protected override void ResetScene()
	{
		base.ResetScene();
		if (PhotonNetwork.isMasterClient)
		{
			MasterResetAllBalls();
		}
	}

	protected override void OnGameStart()
	{
		if (PhotonNetwork.isMasterClient)
		{
			dodgeballStateMachine.EnterState(0);
		}
		base.PresenceSettings.CurrentPresenceString = "Best " + ScoreToWin + " of " + maxRounds + " Rounds";
	}

	protected override void OnGameEnd()
	{
		if (PhotonNetwork.isMasterClient)
		{
			dodgeballStateMachine.EnterState(ushort.MaxValue);
		}
	}

	protected override void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
		base.InitializeLocalPlayer(localPlayerIsSpectator);
		if (!localPlayerIsSpectator)
		{
			LocalPlayerSetOnSidelines(isOnSidelines: false);
		}
	}

	protected override void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		base.ResetLocalPlayer(localPlayerIsSpectator);
		if (!localPlayerIsSpectator)
		{
			LocalPlayerSetOnSidelines(isOnSidelines: false);
		}
	}

	private void OnEnterRoundStartState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterDisableAllBalls();
			masterDodgeballStateTimer.StartTimer(5f);
		}
		masterDodgeballStateTimer.AddTimeRemainingCallback(3f, PlayRoundStartEffect);
		if (!base.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = false;
		}
	}

	private void OnUpdateRoundStartState()
	{
		if (PhotonNetwork.isMasterClient && masterDodgeballStateTimer.TimerOver)
		{
			dodgeballStateMachine.EnterState(1);
		}
	}

	private void PlayRoundStartEffect()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Round Starting", 3f);
	}

	private void OnEnterRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (!base.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = true;
		}
		if (PhotonNetwork.isMasterClient)
		{
			MasterResetAllBalls();
		}
		base.FxManager.PlayFX(FxType.ROUND_START);
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Go!", 2f);
	}

	private void OnUpdateRoundRunningState()
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		GameTeam[] allTeams = base.TeamManager.GetAllTeams();
		for (int i = 0; i < allTeams.Length; i++)
		{
			if (IsEntireTeamOnSidelines(allTeams[i]))
			{
				GameTeam anotherTeam = base.TeamManager.GetAnotherTeam(allTeams[i]);
				base.StatsManager.AddScore(anotherTeam, 1);
				dodgeballStateMachine.EnterState(2);
			}
		}
	}

	private void OnEnterRoundOverState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterDodgeballStateTimer.StartTimer(base.CombatManager.RespawnDuration + 3f);
		}
		masterDodgeballStateTimer.AddTimeElapsedCallback(base.CombatManager.RespawnDuration, PlayRoundOverEffect);
	}

	private void OnExitRoundOverState(ushort nextStateId, ushort nextSubStateId)
	{
		if (nextStateId == 0 && !base.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			LocalPlayerSetOnSidelines(isOnSidelines: false);
			base.SpawnManager.LocalPlayerRequestRespawn();
		}
	}

	private void OnUpdateRoundOverState()
	{
		if (PhotonNetwork.isMasterClient && masterDodgeballStateTimer.TimerOver)
		{
			if (base.StatsManager.GetWinningScore(out var _) >= ScoreToWin)
			{
				MasterStopGame();
			}
			else
			{
				dodgeballStateMachine.EnterState(0);
			}
		}
	}

	private void PlayRoundOverEffect()
	{
		base.FxManager.PlayFX(FxType.ROUND_OVER);
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Round Over!", 3f);
	}

	private void OnDodgeballPlayerOut(Dodgeball dodgeball, Player thrower, Player outPlayer, Vector3 hitPoint)
	{
		if (dodgeball.Owner.isLocal && IsValidHit(thrower.PhotonPlayer, outPlayer.PhotonPlayer))
		{
			base.photonView.RPC("RpcMasterRequestPlayerOut", PhotonTargets.MasterClient, thrower.PhotonPlayer, outPlayer.PhotonPlayer, hitPoint);
		}
	}

	private void OnDodgeballPlayerHit(Dodgeball dodgeball, Player thrower, Player hitPlayer, Vector3 hitPoint)
	{
		if (dodgeball.Owner.isLocal && IsValidHit(thrower.PhotonPlayer, hitPlayer.PhotonPlayer))
		{
			base.photonView.RPC("RpcOnPlayerHit", PhotonTargets.All, thrower.PhotonPlayer, hitPlayer.PhotonPlayer, hitPoint);
		}
	}

	private void MasterRequestPlayerOut(PhotonPlayer thrower, PhotonPlayer outPlayer, Vector3 outPoint)
	{
		if (PhotonNetwork.isMasterClient && IsValidHit(thrower, outPlayer))
		{
			base.CombatManager.MasterSetPlayerHealth(outPlayer, 0);
			base.photonView.RPC("RpcOnPlayerOut", PhotonTargets.All, thrower, outPlayer, outPoint);
		}
	}

	private bool IsValidHit(PhotonPlayer thrower, PhotonPlayer outPlayer)
	{
		return dodgeballStateMachine.CurrentStateId == 1 && base.CombatManager.PlayerIsAlive(outPlayer) && !IsPlayerOnSidelines(thrower) && !IsPlayerOnSidelines(outPlayer) && !base.TeamManager.PlayersAreTeammates(thrower, outPlayer);
	}

	private void OnPlayerOut(PhotonPlayer thrower, PhotonPlayer outPlayer, Vector3 outPoint)
	{
		if (outPlayer.isLocal)
		{
			LocalPlayerSetOnSidelines(isOnSidelines: true);
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You're Out!", "Hit by " + thrower.name, 3f);
			base.FxManager.PlayFX(FxType.PLAYER_OUT);
		}
		else if (thrower.isLocal)
		{
			Vector3 vector = 0.35f * ((Player.LocalPlayer.Head.transform.position - outPoint).normalized + Vector3.up);
			MenuNotification.PlayNext("Out!", 3f, null, followPlayer: false, outPoint + vector);
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You Hit " + outPlayer.name, 3f);
			base.FxManager.PlayFX(FxType.PLAYER_HIT);
			Player.LocalPlayer.PlayerEvents.DodgeballOut();
		}
	}

	private void OnPlayerHit(PhotonPlayer thrower, PhotonPlayer hitPlayer, Vector3 hitPoint)
	{
		base.FxManager.PlayFX(FxType.PLAYER_DAMAGED, hitPoint);
	}

	private void OnDodgeballCatch(Dodgeball dodgeball, Player catcher, Player thrower, Vector3 catchPoint)
	{
		if (catcher.PhotonPlayer.isLocal && IsValidCatch(catcher.PhotonPlayer, thrower.PhotonPlayer))
		{
			base.photonView.RPC("RpcMasterRequestPlayerCatch", PhotonTargets.MasterClient, catcher.PhotonPlayer, thrower.PhotonPlayer, catchPoint);
		}
	}

	private void MasterRequestPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		if (PhotonNetwork.isMasterClient && IsValidCatch(catcher, thrower))
		{
			base.photonView.RPC("RpcOnPlayerCatch", PhotonTargets.All, catcher, thrower, catchPoint);
		}
	}

	private bool IsValidCatch(PhotonPlayer catcher, PhotonPlayer thrower)
	{
		return dodgeballStateMachine.CurrentStateId == 1 && !IsPlayerOnSidelines(catcher) && !IsPlayerOnSidelines(thrower) && !base.TeamManager.PlayersAreTeammates(catcher, thrower);
	}

	private void OnPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		Vector3 vector = 0.35f * ((Player.LocalPlayer.Head.transform.position - catchPoint).normalized + Vector3.up);
		MenuNotification.PlayNext("Catch!", 3f, null, followPlayer: false, catchPoint + vector);
	}

	private bool IsEntireTeamOnSidelines(GameTeam team)
	{
		PhotonPlayer[] teamPlayers = base.TeamManager.GetTeamPlayers(team);
		for (int i = 0; i < teamPlayers.Length; i++)
		{
			if (!IsPlayerOnSidelines(teamPlayers[i]))
			{
				return false;
			}
		}
		return true;
	}

	private PlayerData GetPlayerData(PhotonPlayer player)
	{
		if (!playerData.TryGetValue(player.ID, out var value))
		{
			value = new PlayerData(player);
			playerData[player.ID] = value;
		}
		return value;
	}

	private bool IsPlayerOnSidelines(PhotonPlayer player)
	{
		return GetPlayerData(player).OnSidelines;
	}

	private void LocalPlayerSetOnSidelines(bool isOnSidelines)
	{
		GetPlayerData(PhotonNetwork.player).OnSidelines = isOnSidelines;
		SpawnPointTagType localPlayerSpawnPointTag = SpawnPointTagType.TAG_1;
		TeleportRegionTagType localPlayerTeleportRegionTag = TeleportRegionTagType.TAG_1;
		if (isOnSidelines)
		{
			localPlayerSpawnPointTag = SpawnPointTagType.TAG_2;
			localPlayerTeleportRegionTag = TeleportRegionTagType.TAG_2;
		}
		base.SpawnManager.SetLocalPlayerSpawnPointTag(localPlayerSpawnPointTag);
		base.TeleportManager.SetLocalPlayerTeleportRegionTag(localPlayerTeleportRegionTag);
	}

	private void MasterResetAllBalls()
	{
		if (PhotonNetwork.isMasterClient)
		{
			for (int i = 0; i < balls.Length; i++)
			{
				balls[i].MasterResetToLastSpawnPosition();
			}
		}
	}

	private void MasterDisableAllBalls()
	{
		if (PhotonNetwork.isMasterClient)
		{
			for (int i = 0; i < balls.Length; i++)
			{
				balls[i].Disable();
			}
		}
	}

	[PunRPC]
	private void RpcMasterRequestPlayerOut(PhotonPlayer thrower, PhotonPlayer outPlayer, Vector3 outPoint)
	{
		MasterRequestPlayerOut(thrower, outPlayer, outPoint);
	}

	[PunRPC]
	private void RpcOnPlayerHit(PhotonPlayer thrower, PhotonPlayer hitPlayer, Vector3 hitPoint)
	{
		OnPlayerHit(thrower, hitPlayer, hitPoint);
	}

	[PunRPC]
	private void RpcOnPlayerOut(PhotonPlayer thrower, PhotonPlayer outPlayer, Vector3 outPoint)
	{
		OnPlayerOut(thrower, outPlayer, outPoint);
	}

	[PunRPC]
	private void RpcMasterRequestPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		MasterRequestPlayerCatch(catcher, thrower, catchPoint);
	}

	[PunRPC]
	private void RpcOnPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		OnPlayerCatch(catcher, thrower, catchPoint);
	}
}
public class ChangingRoomMenu : UnityEngine.MonoBehaviour
{
	private void Start()
	{
		if (ViveControllerInput.Instance != null)
		{
			GetComponent<Canvas>().worldCamera = ViveControllerInput.Instance.ControllerCamera;
		}
	}

	public void Button_ResetOutfitSelection()
	{
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.PlayerOutfit.RestoreSelection();
			AnalyticsHelper.AvatarChangingRoomResetButton();
		}
	}

	public void Button_RandomizeOutfitSelection()
