	private TutorialManager.VOClip unlockToolVO;

	[SerializeField]
	private TutorialManager.VOClip unlockToolHelpVO;

	[SerializeField]
	private TutorialManager.VOClip firstDayChecklistVO;

	[SerializeField]
	private TutorialManager.VOClip seeTheChecklistVO;

	[SerializeField]
	private TutorialManager.VOClip checkYourProgressVO;

	[SerializeField]
	private TutorialManager.VOClip closeMenuHelpVO;

	[SerializeField]
	private TutorialManager.VOClip customizeAvatarVO;

	[SerializeField]
	private TutorialManager.VOClip feelFreeToPlayAroundVO;

	[SerializeField]
	private TutorialManager.VOClip whenReadyTeleportThroughTheDoorVO;

	[SerializeField]
	private TutorialManager.VOClip useThumbstickToTurnAroundVO;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip logoRezClip;

	[SerializeField]
	private AudioSource introAudio;

	private Tool[] tools;

	private ChangingRoomMenu changingRoomMenu;

	private OutfitToolSpawner outfitToolSpawner;

	private void Start()
	{
		if (TutorialManager.OOBEState < TutorialManager.OOBEFlowState.Dormroom)
		{
			StartCoroutine(RunOOBEFlow());
		}
	}

	private IEnumerator RunOOBEFlow()
	{
		SetupDormForOOBE();
		yield return RunWaitForPlayerSpawn();
		Player player = Player.LocalPlayer;
		player.PlayerUI.MenuInteractionAllowed = false;
		yield return new WaitForSeconds(1.5f);
		AudioManager.Play3DSFX(logoRezClip, Map3D.transform.position);
		StartCoroutine(RunAnimateInOut(Logo, enable: true));
		yield return RunAnimateInOut(Map3D, enable: true);
		SingletonMonoBehaviour<TutorialManager>.Instance.PlayAttentionHelper(youAreHereIndicator.position, playAudio: false);
		yield return new WaitForSeconds(1.75f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(welcomeVO);
		StartCoroutine(RunAnimateInOut(Map3D, enable: false));
		yield return RunAnimateInOut(Logo, enable: false);
		if (introAudio != null)
		{
			introAudio.Play();
		}
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(thisIsYourDormVO);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(letsGoOverBasicsVO);
		VibrateBothHands(player);
		ShowNotes(teleport: true, grab: false, menu: false);
		userTeleported = false;
		player.PlayerEvents.TeleportEvent += base.PlayerEvents_TeleportEvent;
		yield return RunInterractionFlow(() => userTeleported, useTeleportButtonVO, null, useTeleportButtonHelpVO, 5f, 5, teleportNote.transform);
		player.PlayerEvents.TeleportEvent -= base.PlayerEvents_TeleportEvent;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(greatVO);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(weHaveNeatStuffVO);
		ShowNotes(teleport: false, grab: true, menu: false);
		VibrateBothHands(player);
		Tool[] array = interactionTools;
		foreach (Tool tool in array)
		{
			tool.gameObject.SetActive(value: true);
			SingletonMonoBehaviour<ToolCleanupManager>.Instance.RemoveTool(tool);
			yield return new WaitForSeconds(0.2f);
		}
		userPickedUpTool = false;
		player.PlayerEvents.ToolPickupEvent += base.PlayerEvents_ToolPickupEvent;
		yield return RunInterractionFlow(() => userPickedUpTool, giveItaShotVO, null, pickupToolHelpVO, 5f, 5, interactionTools[0].transform);
		player.PlayerEvents.ToolPickupEvent -= base.PlayerEvents_ToolPickupEvent;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(greatVO);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(firstDayChecklistVO);
		player.ObjectiveTracker.ClearStaleProgress(forciblyClear: true);
		player.PlayerUI.MenuInteractionAllowed = true;
		VibrateBothHands(player);
		ShowNotes(teleport: false, grab: false, menu: true);
		yield return RunInterractionFlow(() => player.PlayerUI.Menu.Visible, seeTheChecklistVO, null, seeTheChecklistVO, 5f, 10, menuNote.transform);
		TutorialManager.OOBEState = TutorialManager.OOBEFlowState.Dormroom;
		yield return RunInterractionFlow(() => !player.PlayerUI.Menu.Visible, checkYourProgressVO, null, closeMenuHelpVO, 5f);
		changingRoomMenu.gameObject.SetActive(value: true);
		outfitToolSpawner.DrawersMenu.gameObject.SetActive(value: true);
		ShowNotes(teleport: false, grab: false, menu: false);
		Tool[] array2 = interactionTools;
		foreach (Tool tool2 in array2)
		{
			tool2.gameObject.SetActive(value: false);
		}
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(feelFreeToPlayAroundVO);
		StartCoroutine(RunStopIntroAudio(8));
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(whenReadyTeleportThroughTheDoorVO);
		lockerRoomDoor.gameObject.SetActive(value: true);
		StartCoroutine(RunSpawnTools());
		yield return new WaitForSeconds(1f);
		SingletonMonoBehaviour<TutorialManager>.Instance.PlayAttentionHelper(doorHandle.position);
		if (PlatformManager.Instance.CurrentHardwareType == PlatformManager.HardwareType.OCULUS)
		{
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(useThumbstickToTurnAroundVO);
		}
	}

	private IEnumerator RunStopIntroAudio(int duration)
	{
		if (introAudio != null)
		{
			yield return SingletonMonoBehaviour<AudioManager>.Instance.RunChangeAudioVolume(introAudio, introAudio.volume, 0f, duration);
			introAudio.Stop();
		}
	}

	private IEnumerator RunSpawnTools()
	{
		Tool[] array = tools;
		foreach (Tool tool in array)
		{
			tool.gameObject.SetActive(value: true);
			yield return new WaitForSeconds(0.15f);
		}
	}

	private void SetupDormForOOBE()
	{
		Map3D.gameObject.SetActive(value: false);
		Logo.gameObject.SetActive(value: false);
		if (tools == null)
		{
			tools = UnityEngine.Object.FindObjectsOfType<Tool>();
		}
		Tool[] array = tools;
		foreach (Tool tool in array)
		{
			tool.gameObject.SetActive(value: false);
		}
		ShowNotes(teleport: false, grab: false, menu: false);
		Tool[] array2 = interactionTools;
		foreach (Tool tool2 in array2)
		{
			tool2.gameObject.SetActive(value: false);
		}
		lockerRoomDoor.gameObject.SetActive(value: false);
		if (changingRoomMenu == null)
		{
			changingRoomMenu = UnityEngine.Object.FindObjectOfType<ChangingRoomMenu>();
		}
		changingRoomMenu.gameObject.SetActive(value: false);
		if (outfitToolSpawner == null)
		{
			outfitToolSpawner = UnityEngine.Object.FindObjectOfType<OutfitToolSpawner>();
		}
		outfitToolSpawner.DrawersMenu.gameObject.SetActive(value: false);
	}

	private void ShowNotes(bool teleport, bool grab, bool menu)
	{
		teleportNote.gameObject.SetActive(teleport);
		grabNote.gameObject.SetActive(grab);
		menuNote.gameObject.SetActive(menu);
	}
}
public class DormroomSceneManager : RecRoomSceneManager
{
	[SerializeField]
	private string blockedUserMessage = "You are currently blocked.\nYou can rejoin in {0}mins {1}secs.";

	protected override void Start()
	{
		base.Start();
		int userBlockedDurationSecondsRemaning = SingletonMonoBehaviour<SettingsManager>.Instance.GetUserBlockedDurationSecondsRemaning();
		if (userBlockedDurationSecondsRemaning > 0)
		{
			StartCoroutine(BlockedCoroutine(userBlockedDurationSecondsRemaning));
		}
	}

	private IEnumerator BlockedCoroutine(int durationSeconds)
	{
		TeleportationPortal[] exitTeleportationPortals = UnityEngine.Object.FindObjectsOfType<TeleportationPortal>();
		if (!SessionManager.IsDeveloper)
		{
			TeleportationPortal[] array = exitTeleportationPortals;
			foreach (TeleportationPortal teleportationPortal in array)
			{
				if (teleportationPortal.Target == null)
				{
					teleportationPortal.gameObject.SetActive(value: false);
				}
			}
		}
		while (Player.LocalPlayer == null || Player.LocalPlayer.PlayerUI.Menu == null)
		{
			yield return null;
		}
		PlayerMenu menu = Player.LocalPlayer.PlayerUI.Menu;
		menu.SetHeaderButtonsInteractable(interactable: false);
		while (!menu.Visible)
		{
			yield return null;
		}
		if (menu.IsAlertMessageActive)
		{
			yield return new WaitForSeconds(3f);
		}
		for (durationSeconds = SingletonMonoBehaviour<SettingsManager>.Instance.GetUserBlockedDurationSecondsRemaning(); durationSeconds > 0; durationSeconds--)
		{
			menu.ShowAlertMessage(message: string.Format(blockedUserMessage, durationSeconds / 60, durationSeconds % 60), title: string.Empty, persistent: true, notificationEffects: (PlayerMenu.NotificationEffectFlag)0);
			yield return new WaitForSeconds(1f);
		}
		menu.StopShowAlertMessage();
		menu.SetHeaderButtonsInteractable(interactable: true);
		menu.Visible = false;
		TeleportationPortal[] array2 = exitTeleportationPortals;
		foreach (TeleportationPortal teleportationPortal2 in array2)
		{
			if (teleportationPortal2.Target == null)
			{
				teleportationPortal2.gameObject.SetActive(value: true);
			}
		}
	}
}
