public class PlayingCard : GroupableTool
{
	public enum PlayingCardValue
	{
		ACE,
		TWO,
		THREE,
		FOUR,
		FIVE,
		SIX,
		SEVEN,
		EIGHT,
		NINE,
		TEN,
		JACK,
		QUEEN,
		KING
	}

	public enum PlayingCardSuit
	{
		HEARTS,
		SPADES,
		CLUBS,
		DIAMONDS
	}

	[Header("Playing Card")]
	[SerializeField]
	private PlayingCardSuit suit = PlayingCardSuit.CLUBS;

	[SerializeField]
	private PlayingCardValue value;

	private SynchronizedField<int> _suit;

	private SynchronizedField<int> _value;

	private PlayingCardVisual visual;

	private GroupableTool insertionPreviewCard;

	private bool wasSleeping;

	public PlayingCardSuit Suit
	{
		get
		{
			return (PlayingCardSuit)_suit.Get();
		}
		set
		{
			_suit.ForceSet((int)value);
		}
	}

	public PlayingCardValue Value
	{
		get
		{
			return (PlayingCardValue)_value.Get();
		}
		set
		{
			_value.ForceSet((int)value);
		}
	}

	protected override string GroupPrefabName => "[PlayingCardGroup]";

	protected override void Awake()
	{
		base.Awake();
		visual = GetComponentInChildren<PlayingCardVisual>();
		_suit = new SynchronizedField<int>(this, "SUIT", (int)suit, SetterPermissionMode.MASTER_OR_AUTHORITY, OnSuitChange);
		_value = new SynchronizedField<int>(this, "VALUE", (int)value, SetterPermissionMode.AUTHORITY, OnValueChange);
		OnSuitChange();
		OnValueChange();
		base.Rigidbody.isKinematic = true;
	}

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		if (insertionPreviewCard != null && insertionPreviewCard.IsHeld)
		{
			bool flag = (base.FrontAddHighlightEnabled = IsAbove(insertionPreviewCard));
			base.BackAddHighlightEnabled = !flag;
		}
		bool flag3 = base.Rigidbody.IsSleeping();
		if (!base.IsHeld && flag3 && !wasSleeping)
		{
			if (!base.Rigidbody.isKinematic)
			{
				base.Rigidbody.isKinematic = true;
			}
			if (base.hoveredGroup != null && ((base.hoveredGroup is PlayingCardGroup && (base.hoveredGroup as PlayingCardGroup).IsDeck) || (base.hoveredGroupableTool is PlayingCard && (base.hoveredGroupableTool as PlayingCard).IsHeld)))
			{
				TryAddToHoveredGroup();
			}
		}
		wasSleeping = flag3;
	}

	public override bool CanAddTool(GroupableTool tool)
	{
		return tool != null && tool.GetComponent<PlayingCard>() != null;
	}

	public override void DisplayAddToolHighlight(GroupableTool toolToAdd)
	{
		insertionPreviewCard = null;
		if (toolToAdd == null)
		{
			base.DisplayAddToolHighlight(toolToAdd);
		}
		else
		{
			insertionPreviewCard = toolToAdd;
		}
	}

	private bool IsAbove(GroupableTool newTool)
	{
		return Vector3.Dot(newTool.transform.position - base.transform.position, base.transform.up) >= 0f;
	}

	private void OnSuitChange()
	{
		visual.Suit = Suit;
	}

	private void OnValueChange()
	{
		visual.Value = Value;
	}
}
public class PlayingCardDeck : Photon.MonoBehaviour
{
	private const int DECK_SIZE = 52;

	[SerializeField]
	private PhysicalButton recallCardsButton;

	private PlayingCard[] cards;

	private List<PlayingCard> recalledCards = new List<PlayingCard>();

	private HashSet<ToolGroup> recalledGroups = new HashSet<ToolGroup>();

	private Vector3 initialPosition = Vector3.zero;

	private Quaternion initialRotation = Quaternion.identity;

	protected override void Awake()
	{
		initialPosition = base.transform.position;
		initialRotation = base.transform.rotation;
		cards = GetComponentsInChildren<PlayingCard>();
		if (cards.Length != 52)
		{
			UnityEngine.Debug.LogError("Deck does not have the correct number of cards.  Has " + cards.Length + " and requires " + 52 + " cards.");
		}
		if (recallCardsButton != null)
		{
			recallCardsButton.PushEvent += OnRecallButtonPressed;
		}
	}

	private void Start()
	{
		if (!base.hasAuthority)
		{
			return;
		}
		for (int i = 0; i < 4; i++)
		{
			for (int j = 0; j < 13; j++)
			{
				cards[i * 13 + j].Suit = (PlayingCard.PlayingCardSuit)i;
				cards[i * 13 + j].Value = (PlayingCard.PlayingCardValue)j;
			}
		}
		CreateGroup(cards);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (recallCardsButton != null)
		{
			recallCardsButton.PushEvent -= OnRecallButtonPressed;
		}
	}

	private void CreateGroup(PlayingCard[] cardsToAdd)
	{
		PlayingCardGroup playingCardGroup = cardsToAdd[0].CreateNewGroup() as PlayingCardGroup;
		playingCardGroup.IsDeck = true;
		playingCardGroup.AuthorityAddTools(cardsToAdd);
		playingCardGroup.AuthorityShuffle();
		playingCardGroup.transform.position = initialPosition;
		playingCardGroup.transform.rotation = initialRotation;
	}

	private void OnRecallButtonPressed(PhysicalButton thisButton, Player pushPlayer)
	{
		if (pushPlayer.isLocal)
		{
			RequestRecall();
		}
	}

	private void RequestRecall()
	{
		base.photonView.RPC("RpcMasterRecall", PhotonTargets.MasterClient);
	}

	private void MasterRecall()
	{
		recalledCards.Clear();
		recalledGroups.Clear();
		for (int i = 0; i < cards.Length; i++)
		{
			if (cards[i].IsInGroup && !cards[i].Group.IsHeld && !recalledGroups.Contains(cards[i].Group))
			{
				recalledGroups.Add(cards[i].Group);
			}
		}
		foreach (ToolGroup recalledGroup in recalledGroups)
		{
			if (!recalledGroup.hasAuthority)
			{
				recalledGroup.photonView.TransferOwnership(PhotonNetwork.player);
			}
			recalledGroup.AuthorityClearTools();
			recalledGroup.AuthorityDestroy();
		}
		for (int j = 0; j < cards.Length; j++)
		{
			if (!cards[j].IsInGroup && !cards[j].IsHeld)
			{
				recalledCards.Add(cards[j]);
			}
		}
		CreateGroup(recalledCards.ToArray());
	}

	[PunRPC]
	private void RpcMasterRecall()
	{
		MasterRecall();
	}
}
public class PlayingCardGroup : ToolGroup
{
	private struct LayoutTransform
	{
		public Vector3 Position;

		public Quaternion Rotation;

		public static LayoutTransform Default
		{
			get
			{
				LayoutTransform result = default(LayoutTransform);
				result.Position = Vector3.zero;
				result.Rotation = Quaternion.identity;
				return result;
			}
		}

		public void Clear()
		{
			Position = Vector3.zero;
			Rotation = Quaternion.identity;
		}

		public LayoutTransform Mirror(Vector3 surfaceNormal)
		{
			LayoutTransform result = default(LayoutTransform);
			result.Position = 2f * Vector3.Project(Position, surfaceNormal) - Position;
			result.Rotation = Quaternion.Inverse(Rotation);
			return result;
		}
	}

	[Header("Playing Card Group")]
	[SerializeField]
	private RecRoomAudioClip shuffleSound;

	[Header("Deck Select")]
	[SerializeField]
	private float deckDwellTime = 1.5f;

	[Header("Deck Offset Transforms")]
	[SerializeField]
	private Transform deckNeighborTransform;

	[SerializeField]
	private Transform deckHighlightTransform;

	[SerializeField]
	private Transform entireDeckHighlightTransform;

	[Header("Stack Offset Transforms")]
	[SerializeField]
	private Transform stackNeighborTransform;

	[SerializeField]
	private Transform stackHighlightTransform;

	[SerializeField]
	private Transform stackAfterHighlightTransform;

	[SerializeField]
	private Transform entireStackHighlightTransform;

	private bool wasSleeping;

	private GroupableTool hoveredCard;

	private bool hoverEntireGroup;

	private GroupableTool insertionPreviewCard;

	private SynchronizedField<bool> _isDeck;

	private bool dwellingOnDeck;

	private float deckDwellStartTime;

	private int hoveredCardIndex = -1;

	private LayoutTransform neighborTransform;

	private LayoutTransform defaultCardTransform;

	private LayoutTransform cardHighlightTransform;

	private LayoutTransform entireGroupHighlightTransform;

	private LayoutTransform cardBeforeHighlightTransform;

	private LayoutTransform cardAfterHighlightTransform;

	public bool IsDeck
	{
		get
		{
			return _isDeck.Get();
		}
		set
		{
			_isDeck.ForceSet(value);
		}
	}

	private bool IsUpsideDown => Vector3.Dot(base.transform.up, Vector3.up) <= 0f;

	private GroupableTool TopCard
	{
		get
		{
			if (base.Size == 0)
			{
				return null;
			}
			if (IsUpsideDown)
			{
				return tools[0];
			}
			return tools[tools.Count - 1];
		}
	}

	private bool DwellingLongEnoughToSelectDeck => dwellingOnDeck && Time.time - deckDwellStartTime >= deckDwellTime;

	private Vector3 RandomCardPositionOffset
	{
		get
		{
			Vector3 result = Vector3.zero;
			if (IsDeck)
			{
				Vector2 insideUnitCircle = UnityEngine.Random.insideUnitCircle;
				result = new Vector3(insideUnitCircle.x, 0f, insideUnitCircle.y) * 0.001f;
			}
			return result;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_isDeck = new SynchronizedField<bool>(this, "IS_DECK", defaultValue: false, SetterPermissionMode.AUTHORITY, OnIsDeckChange);
	}

	public void AuthorityShuffle()
	{
		int[] array = tools.Select((GroupableTool x) => x.photonView.viewID).ToArray();
		UnityExtensions.ShuffleArray(array);
		AuthorityReorderTools(array);
		base.photonView.RPC("RpcPlayShuffleSound", PhotonTargets.All);
	}

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		if (insertionPreviewCard != null && (insertionPreviewCard.IsHeld || (insertionPreviewCard.IsInGroup && insertionPreviewCard.Group.IsHeld)))
		{
			int num = 0;
			bool flag = true;
			int desiredNewToolIndex = GetDesiredNewToolIndex(insertionPreviewCard, Vector3.zero, Quaternion.identity);
			if (desiredNewToolIndex > 0)
			{
				num = desiredNewToolIndex - 1;
				flag = false;
			}
			for (int i = 0; i < tools.Count; i++)
			{
				if (i != num)
				{
					tools[i].FrontAddHighlightEnabled = false;
					tools[i].BackAddHighlightEnabled = false;
				}
				else
				{
					tools[i].FrontAddHighlightEnabled = !flag;
					tools[i].BackAddHighlightEnabled = flag;
				}
			}
		}
		bool flag2 = base.Rigidbody.IsSleeping();
		if (!base.IsHeld && flag2 && !wasSleeping)
		{
			if (!base.Rigidbody.isKinematic)
			{
				base.Rigidbody.isKinematic = true;
			}
			if (base.hoveredGroup != null && (base.hoveredGroup.IsHeld || (base.hoveredGroup is PlayingCardGroup && (base.hoveredGroup as PlayingCardGroup).IsDeck)))
			{
				TryAddToHoveredGroup();
			}
		}
		wasSleeping = flag2;
	}

	public override void OnInputDown()
	{
		base.OnInputDown();
		if (base.hasAuthority)
		{
			IsDeck = !IsDeck;
		}
	}

	public override void OnShake()
	{
		base.OnShake();
		AuthorityShuffle();
		base.HolderHand.Vibrate(200, 1000);
	}

	public override void DisplayAddGroupHighlight(ToolGroup groupToAdd)
	{
		insertionPreviewCard = null;
		PlayingCardGroup playingCardGroup = ((!(groupToAdd != null)) ? null : groupToAdd.GetComponent<PlayingCardGroup>());
		if (playingCardGroup == null || playingCardGroup.Size == 0)
		{
			base.DisplayAddGroupHighlight(groupToAdd);
		}
		else
		{
			DisplayAddToolHighlight(playingCardGroup.tools[0]);
		}
	}

	public override void DisplayAddToolHighlight(GroupableTool toolToAdd)
	{
		insertionPreviewCard = null;
		if (toolToAdd == null)
		{
			base.DisplayAddToolHighlight(toolToAdd);
		}
		else
		{
			insertionPreviewCard = toolToAdd;
		}
	}

	public override bool CanAddGroup(ToolGroup group)
	{
		return group != null && group.GetComponent<PlayingCardGroup>() != null;
	}

	public override bool CanAddTool(GroupableTool tool)
	{
		return tool != null && tool.GetComponent<PlayingCard>() != null;
