	private PokerChipVisual visual;

	private bool wasSleeping;

	private SynchronizedField<int> _value;

	public PokerChipValue Value
	{
		get
		{
			return (PokerChipValue)_value.Get();
		}
		set
		{
			_value.ForceSet((int)value);
