public class Dartboard : UnityEngine.MonoBehaviour
{
	public float bullseyeRadius = 0.07f;

	public float innerRadius = 0.15f;

	public float outerRadius = 0.3f;

	public PooledParticle HitParticleOuter;

	public PooledParticle HitParticleInner;

	public PooledParticle HitParticleBullseye;

	public RecRoomAudioClip HitAudio;

	private void OnTriggerEnter(Collider collider)
	{
		Tool colliderTool = collider.GetColliderTool();
		Dart dart = ((!(colliderTool != null)) ? null : colliderTool.GetComponent<Dart>());
		if (!(dart != null))
		{
			return;
		}
		float num = Vector2.Distance(base.transform.position, collider.transform.position);
		PooledParticle pooledParticle = ObjectPool.Instance.Acquire(HitParticleOuter);
		if (num < bullseyeRadius)
		{
			pooledParticle = ObjectPool.Instance.Acquire(HitParticleBullseye);
		}
		else if (num < innerRadius)
		{
			pooledParticle = ObjectPool.Instance.Acquire(HitParticleInner);
		}
		if (num < outerRadius)
		{
			if (pooledParticle != null)
			{
				pooledParticle.transform.position = collider.transform.position;
				pooledParticle.transform.rotation = collider.transform.rotation;
				pooledParticle.Play();
			}
			AudioManager.Play3DSFX(HitAudio, base.transform);
		}
	}
}
public class LockerroomOOBEFlow : OOBEFlowBase
{
	[Header("VO")]
	[SerializeField]
	private TutorialManager.VOClip welcomeToLockerroomVO;

	[SerializeField]
	private TutorialManager.VOClip whenYouAreReadyToPlayFollowGoPlayVO;

	[SerializeField]
	private TutorialManager.VOClip letsGoPlayVO;

	[SerializeField]
	private RecRoomAudioClip lockerRoomNotificationClip;

	private void Start()
	{
		if (TutorialManager.OOBEState <= TutorialManager.OOBEFlowState.Lockerroom)
		{
			StartCoroutine(RunOOBEFlow());
		}
	}

	private IEnumerator RunOOBEFlow()
	{
		yield return RunWaitForPlayerSpawn();
		Player player = Player.LocalPlayer;
		yield return new WaitForSeconds(0.75f);
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, RecRoomSceneManager.CurrentSceneFriendlyName, 3f);
		AudioManager.Play2DSFX(lockerRoomNotificationClip);
		yield return new WaitForSeconds(0.75f);
		if (TutorialManager.OOBEState < TutorialManager.OOBEFlowState.Lockerroom)
		{
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(welcomeToLockerroomVO);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(letsGoPlayVO);
		}
		while (!ActivityBounds.PointInBounds(player.Head.transform.position))
		{
			yield return null;
		}
		TutorialManager.OOBEState = TutorialManager.OOBEFlowState.Lockerroom;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(whenYouAreReadyToPlayFollowGoPlayVO);
	}
}
public class SlideshowScreen : PunBehaviour
{
	[SerializeField]
	private Texture2D[] slideshow;

	[SerializeField]
	private Renderer screenRenderer;

	[SerializeField]
	private Button rightButton;

	[SerializeField]
	private Button leftButton;

	[SerializeField]
	private bool loop = true;

	private int slideIndex;

	private bool _isVisible;

	public bool IsVisible
	{
		get
		{
			return _isVisible;
		}
		private set
		{
			_isVisible = value;
			screenRenderer.gameObject.SetActive(_isVisible);
			leftButton.gameObject.SetActive(_isVisible);
			rightButton.gameObject.SetActive(_isVisible);
		}
	}

	private void Start()
	{
		IsVisible = false;
		UpdateMaterial();
		rightButton.GetComponentInParent<Canvas>().worldCamera = ViveControllerInput.Instance.ControllerCamera;
		leftButton.GetComponentInParent<Canvas>().worldCamera = ViveControllerInput.Instance.ControllerCamera;
	}

	public void Button_NextSlide()
	{
		slideIndex++;
		if (slideIndex >= slideshow.Length)
		{
			if (loop)
			{
				slideIndex %= slideshow.Length;
			}
			else
			{
				slideIndex = slideshow.Length - 1;
			}
		}
		base.photonView.RPC("RpcSetIndex", PhotonTargets.All, slideIndex);
	}

	public void Button_PrevSlide()
	{
		slideIndex--;
		if (slideIndex < 0)
		{
			if (loop)
			{
				slideIndex += slideshow.Length;
			}
			else
			{
				slideIndex = 0;
			}
		}
		base.photonView.RPC("RpcSetIndex", PhotonTargets.All, slideIndex);
	}

	public void SetVisibility(bool visible)
	{
		if (IsVisible != visible)
		{
			base.photonView.RPC("RpcSetVisibility", PhotonTargets.All, visible);
		}
	}

	private void UpdateMaterial()
	{
		screenRenderer.material.mainTexture = slideshow[slideIndex];
	}

	public override void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		base.OnPhotonPlayerConnected(newPlayer);
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcSetIndex", newPlayer, slideIndex);
			base.photonView.RPC("RpcSetVisibility", newPlayer, IsVisible);
		}
	}

	[PunRPC]
	public void RpcSetIndex(int currentIndex)
	{
		slideIndex = currentIndex;
		UpdateMaterial();
	}

	[PunRPC]
	public void RpcSetVisibility(bool visible)
	{
		IsVisible = visible;
	}
}
