public class Pistol : Gun
{
	protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 direction, float chargeAmount, bool isMisfire)
	{
		base.FireShot(position, rotation, direction, chargeAmount, isMisfire);
		if (!isMisfire)
		{
			FireBullet(position, rotation, direction * bulletFireSpeed, 1f);
		}
	}
}
public class Shotgun : Gun
{
	[Header("Spray")]
	[SerializeField]
	private float maxDistance = 3f;

	[SerializeField]
	private Transform sprayTargetRoot;

	private Transform[] sprayTargets;

	protected override void Awake()
	{
		base.Awake();
		sprayTargets = new Transform[sprayTargetRoot.childCount];
		for (int i = 0; i < sprayTargetRoot.childCount; i++)
		{
			sprayTargets[i] = sprayTargetRoot.GetChild(i);
		}
	}

	protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 direction, float chargeAmount, bool isMisfire)
	{
		base.FireShot(position, rotation, direction, chargeAmount, isMisfire);
		if (!isMisfire)
		{
			float maxLifetime = maxDistance / bulletFireSpeed;
			sprayTargetRoot.localPosition = new Vector3(0f, 0f, maxDistance);
			for (int i = 0; i < sprayTargets.Length; i++)
			{
				FireBullet(position, rotation, (sprayTargets[i].position - position).normalized * bulletFireSpeed, 1f, maxLifetime);
			}
		}
	}
}
public class SniperScope : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Renderer scopeRenderer;

	[SerializeField]
	private Camera scopeCamera;

	[SerializeField]
	private float fov = 5f;

	[SerializeField]
	private int resolution = 256;

	private RenderTexture renderTexture;

	private Tool tool;

	private bool RenderingEnabled
	{
		set
		{
			if (scopeCamera != null)
			{
				scopeCamera.enabled = value;
			}
			if (tool != null && tool.ToolRenderer != null)
			{
				for (int i = 0; i < tool.ToolRenderer.Renderers.Count; i++)
				{
					tool.ToolRenderer.Renderers[i].gameObject.layer = ((!value) ? 10 : 16);
				}
			}
		}
	}

	private void Awake()
	{
		renderTexture = new RenderTexture(resolution, resolution, 24);
		if (scopeCamera == null || scopeRenderer == null)
		{
			UnityEngine.Debug.LogError("SniperScope: Missing camera or renderer.");
			return;
		}
		scopeCamera.fieldOfView = fov;
		scopeCamera.targetTexture = renderTexture;
		scopeRenderer.material.mainTexture = renderTexture;
		tool = GetComponent<Tool>();
		if (tool != null)
		{
			tool.PickupEvent += OnToolPickup;
			tool.ReleaseEvent += OnToolRelease;
			RenderingEnabled = false;
		}
		else
		{
			RenderingEnabled = true;
		}
	}

	private void OnDestroy()
	{
		if (tool != null)
		{
			tool.PickupEvent -= OnToolPickup;
			tool.ReleaseEvent -= OnToolRelease;
		}
	}

	private void OnToolPickup(Tool tool)
	{
		if (tool.Owner.isLocal)
		{
			RenderingEnabled = true;
		}
	}

	private void OnToolRelease(Tool tool)
	{
		RenderingEnabled = false;
	}
}
