public class BreakableLootContainer : BreakableObject
{
	[Header("Loot")]
	[SerializeField]
	private LootDropper lootDrops;

	private List<PhotonPlayer> playerHitInstances = new List<PhotonPlayer>();

	public override void OnToolForceApplied(Player hittingPlayer, Vector3 position, Vector3 force)
	{
		base.OnToolForceApplied(hittingPlayer, position, force);
		playerHitInstances.Add(hittingPlayer.PhotonPlayer);
		if (base.hasAuthority)
		{
			AuthorityApplyHit(position, force, 1);
		}
	}

	protected override void Fracture()
	{
		base.Fracture();
		if (lootDrops != null && playerHitInstances.Count > 0)
		{
			lootDrops.DropLoot(playerHitInstances.ToArray());
		}
	}
}
public class BreakableObject : Tool
{
	[Header("Meshes")]
	[SerializeField]
	private GameObject wholeObject;

	[SerializeField]
	private GameObject fracturedObject;

	[Header("Destruction")]
	[SerializeField]
	private int maxHitPoints = 1;

	[SerializeField]
	private float timeBeforeCleanup = 3f;

	private SynchronizedField<int> _hitPoints;

	private SynchronizedField<Vector3> _lastHitPoint;

	private SynchronizedField<Vector3> _lastHitForce;

	public int HitPoints
	{
		get
		{
			return _hitPoints.Get();
		}
		set
		{
			_hitPoints.ForceSet(value);
		}
	}

	public Vector3 LastHitPoint
	{
		get
		{
			return _lastHitPoint.Get();
		}
		set
		{
			_lastHitPoint.ForceSet(value);
		}
	}

	public Vector3 LastHitForce
	{
		get
		{
			return _lastHitForce.Get();
		}
		set
		{
			_lastHitForce.ForceSet(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_hitPoints = new SynchronizedField<int>(this, "HP", maxHitPoints, SetterPermissionMode.AUTHORITY, OnHitPointsChanged);
		_lastHitPoint = new SynchronizedField<Vector3>(this, "LASTHIT_POINT", Vector3.zero, SetterPermissionMode.AUTHORITY);
		_lastHitForce = new SynchronizedField<Vector3>(this, "LASTHIT_FORCE", Vector3.zero, SetterPermissionMode.AUTHORITY);
	}

	protected void AuthorityApplyHit(Vector3 hitPoint, Vector3 hitForce, int damage)
	{
		if (base.hasAuthority)
		{
			LastHitPoint = hitPoint;
			LastHitForce = hitForce;
			HitPoints -= damage;
		}
	}

	protected void OnHitPointsChanged()
	{
		if (HitPoints <= 0)
		{
			Fracture();
		}
	}

	protected virtual void Fracture()
	{
		if (wholeObject != null)
		{
			wholeObject.SetActive(value: false);
		}
		if (!(fracturedObject != null))
		{
			return;
		}
		fracturedObject.SetActive(value: true);
		if (LastHitPoint != Vector3.zero)
		{
			base.Rigidbody.velocity = Vector3.zero;
			float num = Mathf.Min(10f, LastHitForce.magnitude);
			Rigidbody[] componentsInChildren = fracturedObject.GetComponentsInChildren<Rigidbody>();
			foreach (Rigidbody rigidbody in componentsInChildren)
			{
				rigidbody.AddForce((rigidbody.transform.position - LastHitPoint).normalized * num, ForceMode.VelocityChange);
			}
		}
	}

	protected override void OnReset(Vector3 position, Quaternion rotation, bool wasEnabled, Vector3 oldPosition, bool wasCleanedUp)
	{
		base.OnReset(position, rotation, wasEnabled, oldPosition, wasCleanedUp);
		if (base.Owner.isLocal)
		{
			PhotonNetwork.Destroy(base.photonView);
		}
	}
}
public class Crossbow : Gun
{
	[Header("Crossbow")]
	[SerializeField]
	private FloatValueCurve speedOverDrawTime;

	[SerializeField]
	private Transform boltNockingTransform;

	[SerializeField]
	private Transform maxPullTransform;

	private bool chargingShot;

	private float chargeStartTime;

	private CrossbowBolt chargingBolt;

	private float maxDrawDistance;

	protected override void Awake()
	{
		base.Awake();
		if (boltNockingTransform != null && maxPullTransform != null)
		{
			maxDrawDistance = (maxPullTransform.position - boltNockingTransform.position).magnitude;
		}
	}

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		if (chargingBolt != null)
		{
			chargingBolt.transform.position = boltNockingTransform.position + (maxPullTransform.position - boltNockingTransform.position) / maxDrawDistance * Mathf.Min(maxDrawDistance, maxDrawDistance * (Time.time - chargeStartTime) / speedOverDrawTime.Duration);
			chargingBolt.transform.rotation = boltNockingTransform.rotation;
		}
	}

	protected override void Update()
	{
		base.Update();
		if (chargingShot && Time.time - chargeStartTime >= speedOverDrawTime.Duration && Time.time - chargeStartTime - Time.fixedDeltaTime < speedOverDrawTime.Duration)
		{
			base.HolderHand.Vibrate(500, 1000);
		}
	}

	public override void OnInputDown()
	{
		if (base.hasAuthority)
		{
			if (maximumFiringRate >= 0f && base.TimeSinceLastFire >= 1f / maximumFiringRate)
			{
				ChargeShot();
			}
			else
			{
				gunAudio.OnMisfire();
			}
		}
	}

	public override void OnInputUp()
	{
		base.OnInputUp();
		if (base.hasAuthority && chargingShot)
		{
			float chargeAmount = Mathf.InverseLerp(chargeStartTime, chargeStartTime + speedOverDrawTime.Duration, Time.time);
			Fire(chargeAmount);
			chargingShot = false;
		}
	}

	private void ChargeShot()
	{
		chargingShot = true;
		chargeStartTime = Time.time;
		chargingBolt = AcquireBullet() as CrossbowBolt;
		chargingBolt.transform.position = boltNockingTransform.position;
		chargingBolt.transform.rotation = boltNockingTransform.rotation;
	}

	protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 direction, float chargeAmount, bool isMisfire)
	{
		base.FireShot(position, rotation, direction, chargeAmount, isMisfire);
		if (!isMisfire)
		{
			Vector3 velocity = direction * speedOverDrawTime.Evaluate(chargeAmount);
			FireBullet(position, rotation, velocity, chargeAmount);
		}
	}

	protected override void FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount)
	{
		if (chargingBolt != null)
		{
			if (chargingBolt.maxChargedParticleTrail != null && chargeAmount >= 0.99f)
			{
				chargingBolt.maxChargedParticleTrail.Play();
			}
			chargingBolt.Fire(position, rotation, velocity, chargeAmount, base.Rigidbody);
			chargingBolt = null;
		}
	}
}
