			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(lootDropParticlePrefab);
			if (pooledParticle != null)
			{
				pooledParticle.transform.position = base.transform.position + Vector3.up * dropParticleOffset;
				pooledParticle.Play();
			}
		}
	}
