public abstract class QuestEnemy : Enemy
{
	protected enum BehaviorState
	{
		INVALID,
		ALIVE,
		RECOIL,
		DEAD
	}

	[Header("Target Search")]
	[SerializeField]
	protected float targetSearchRadius = 20f;

	[Header("Combat Behavior")]
	[SerializeField]
	private float recoilDuration = 1f;

	[SerializeField]
	private float deathDuration = 2f;

	protected GameManager gameManager;

	protected SynchronizedField<float> _movementSpeedVarietyScalar;

	protected SynchronizedField<int> _targetPlayerId;

	protected SynchronizedField<int> _lastAttackerId;

	protected int pathNodeCount;

	protected int pathNodeIndex;

	protected Vector3 pathTargetPosition = Vector3.zero;

	protected Vector3[] pathNodes;

	protected NavMeshPath navMeshPath;

	private List<PhotonPlayer> playerScratchSpace = new List<PhotonPlayer>();

	protected LootDropper lootDrops;

	protected List<PhotonPlayer> damageInstancesReceived;

	protected const RigidbodyConstraints RECOIL_RIGIDBODY_CONSTRAINTS = (RigidbodyConstraints)80;

	protected float MovementSpeedVarietyScalar
	{
		get
		{
			return _movementSpeedVarietyScalar.Get();
		}
		set
		{
			_movementSpeedVarietyScalar.ForceSet(value);
		}
	}

	protected PhotonPlayer TargetPlayer
	{
		get
		{
			return PhotonPlayer.Find(_targetPlayerId.Get());
		}
		set
		{
			_targetPlayerId.ForceSet(value?.ID ?? PhotonPlayer.Invalid);
		}
	}

	protected PhotonPlayer LastAttacker
	{
		get
		{
			return PhotonPlayer.Find(_lastAttackerId.Get());
		}
		set
		{
			_lastAttackerId.ForceSet(value?.ID ?? PhotonPlayer.Invalid);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_movementSpeedVarietyScalar = new SynchronizedField<float>(this, "SPEED", 1f, SetterPermissionMode.AUTHORITY);
		_targetPlayerId = new SynchronizedField<int>(this, "PLAYER_TARGET_ID", -1, SetterPermissionMode.AUTHORITY);
		_lastAttackerId = new SynchronizedField<int>(this, "LAST_ATTACKER_ID", -1, SetterPermissionMode.AUTHORITY);
		behaviorStateMachine.AddState(0, null, null, null);
		behaviorStateMachine.AddState(1, OnEnterAliveState, OnExitAliveState, OnUpdateAliveState);
		behaviorStateMachine.AddState(2, OnEnterRecoilState, OnExitRecoilState, OnUpdateRecoilState);
		behaviorStateMachine.AddState(3, OnEnterDeadState, null, OnUpdateDeadState);
		navMeshPath = new NavMeshPath();
		pathNodes = new Vector3[16];
		pathNodeIndex = 0;
		pathNodeCount = 0;
		damageInstancesReceived = new List<PhotonPlayer>();
		lootDrops = GetComponent<LootDropper>();
	}

	protected virtual void Start()
	{
		gameManager = RecRoomSceneManager.Instance.GameManager;
		if (base.hasAuthority)
		{
			MovementSpeedVarietyScalar = UnityEngine.Random.Range(0.9f, 1.1f);
		}
		rigidbody.constraints = RigidbodyConstraints.None;
	}

	protected bool PathIsInvalid(Vector3 targetPosition)
	{
		return PathIsInvalid() || (targetPosition - pathTargetPosition).sqrMagnitude > 1f;
	}

	protected bool PathCompleted(Vector3 currentPosition)
	{
		return !PathIsInvalid() && (pathNodeIndex >= pathNodeCount || (currentPosition - pathNodes[pathNodeCount - 1]).sqrMagnitude <= 0.1f);
	}

	protected void ClearPath()
	{
		pathNodeCount = 0;
		pathNodeIndex = -1;
	}

	protected void CalculateNewPath(Vector3 currentPosition, Vector3 targetPosition)
	{
		NavMesh.CalculatePath(currentPosition, targetPosition, -1, navMeshPath);
		if (navMeshPath.status != NavMeshPathStatus.PathInvalid)
		{
			pathNodeCount = navMeshPath.GetCornersNonAlloc(pathNodes);
			pathNodeIndex = 0;
			pathTargetPosition = targetPosition;
		}
	}

	protected Vector3 GetNextPathNode(Vector3 currentPosition)
	{
		if ((pathNodes[pathNodeIndex] - currentPosition).sqrMagnitude <= 0.25f)
		{
			pathNodeIndex++;
		}
		return pathNodes[pathNodeIndex];
	}

	protected Vector3 GetPathPosition(Vector3 position)
	{
		if (NavMesh.SamplePosition(position, out var hit, float.MaxValue, -1))
		{
			return hit.position;
		}
		return position;
	}

	private bool PathIsInvalid()
	{
		return navMeshPath.status == NavMeshPathStatus.PathInvalid || pathNodeCount <= 0;
	}

	protected virtual void OnRecoilStart()
	{
		steering.StopAll();
		rigidbody.constraints = (RigidbodyConstraints)80;
	}

	protected virtual void OnRecoilEnd()
	{
		rigidbody.ClearVelocity();
		rigidbody.constraints = RigidbodyConstraints.None;
	}

	protected abstract void AuthorityEnterStateAfterRecoil();

	private void OnEnterRecoilState(ushort previousStateId, ushort previousSubStateId)
	{
		OnRecoilStart();
		if (base.hasAuthority)
		{
			behaviorTimer.StartTimer(recoilDuration);
		}
	}

	private void OnUpdateRecoilState()
	{
		if (base.hasAuthority && behaviorTimer.TimerOver)
		{
			AuthorityEnterStateAfterRecoil();
		}
	}

	private void OnExitRecoilState(ushort nextStateId, ushort nextSubStateId)
	{
		OnRecoilEnd();
	}

	protected virtual void OnAliveStart()
	{
	}

	protected virtual void OnAliveEnd()
	{
	}

	private void OnEnterAliveState(ushort previousStateId, ushort previousSubStateId)
	{
		OnAliveStart();
	}

	private void OnUpdateAliveState()
	{
		if (base.hasAuthority && base.Health <= 0)
		{
			behaviorStateMachine.EnterState(3);
		}
	}

	private void OnExitAliveState(ushort nextStateId, ushort nextSubStateId)
	{
		OnAliveEnd();
	}

	protected override void OnTookDamage(int damage, PhotonPlayer attacker)
	{
		base.OnTookDamage(damage, attacker);
		if (base.hasAuthority)
		{
			LastAttacker = attacker;
		}
		if (!damageInstancesReceived.Contains(attacker))
		{
			damageInstancesReceived.Add(attacker);
		}
	}

	protected override void OnHealthChanged()
	{
		base.OnHealthChanged();
		if (base.hasAuthority)
		{
			if (base.Health <= 0 && behaviorStateMachine.CurrentStateId != 3)
			{
				behaviorStateMachine.EnterState(3);
			}
			else if (base.Health > 0 && behaviorStateMachine.CurrentStateId != 2)
			{
				behaviorStateMachine.EnterState(2);
			}
		}
	}

	protected virtual void OnDeath()
	{
		steering.StopAll();
		rigidbody.constraints = RigidbodyConstraints.None;
		if (lootDrops != null && damageInstancesReceived.Count > 0)
		{
			lootDrops.DropLoot(damageInstancesReceived.ToArray());
		}
	}

	private void OnEnterDeadState(ushort previousStateId, ushort previousSubStateId)
	{
		OnDeath();
		if (base.hasAuthority)
		{
			behaviorTimer.StartTimer(deathDuration);
		}
	}

	private void OnUpdateDeadState()
	{
		if (base.hasAuthority && behaviorTimer.TimerOver)
		{
			base.IsAlive = false;
			behaviorStateMachine.EnterState(0);
		}
	}

	protected PhotonPlayer GetRandomPlayer(bool onlySearchActivePlayers = true)
	{
		PhotonPlayer[] array = null;
		array = ((!onlySearchActivePlayers) ? PhotonNetwork.playerList : ((!(gameManager != null)) ? null : gameManager.TeamManager.GetActivePlayers()));
		PhotonPlayer result = null;
		if (array != null && array.Length > 0)
		{
			playerScratchSpace.Clear();
			float num = targetSearchRadius * targetSearchRadius;
			for (int i = 0; i < array.Length; i++)
			{
				if ((GetPlayerPosition(array[i]) - base.transform.position).sqrMagnitude <= num)
				{
					playerScratchSpace.Add(array[i]);
				}
			}
			if (playerScratchSpace.Count > 0)
			{
				result = playerScratchSpace[UnityEngine.Random.Range(0, playerScratchSpace.Count - 1)];
			}
		}
		return result;
	}

	protected PhotonPlayer GetClosestPlayer(bool onlySearchInXZPlane, bool onlySearchActivePlayers = true)
	{
		PhotonPlayer result = null;
		float num = float.MaxValue;
		PhotonPlayer[] array = null;
		array = ((!onlySearchActivePlayers) ? PhotonNetwork.playerList : ((!(gameManager != null)) ? null : gameManager.TeamManager.GetActivePlayers()));
		if (array != null)
		{
			for (int i = 0; i < array.Length; i++)
			{
				Vector3 vector = GetPlayerPosition(array[i]) - base.transform.position;
				if (onlySearchInXZPlane)
				{
					vector = Vector3.ProjectOnPlane(vector, Vector3.up);
				}
				float sqrMagnitude = vector.sqrMagnitude;
				if (sqrMagnitude <= num)
				{
					num = sqrMagnitude;
					result = array[i];
				}
			}
		}
		return result;
	}

	protected Vector3 GetPlayerPosition(PhotonPlayer photonPlayer)
	{
		Player player = photonPlayer?.ToPlayer();
		return (!(player != null)) ? Vector3.zero : player.CurrentFloorPosition;
	}

	protected Vector3 GetPlayerPosition(PhotonPlayer photonPlayer, Vector3 offset)
	{
		Player player = photonPlayer?.ToPlayer();
		if (player == null)
		{
			return Vector3.zero;
		}
		Vector3 normalized = Vector3.ProjectOnPlane(player.Head.transform.forward, Vector3.up).normalized;
		Vector3 up = Vector3.up;
		Vector3 normalized2 = Vector3.Cross(up, normalized).normalized;
		return player.CurrentFloorPosition + offset.x * normalized2 + offset.y * up + offset.z * normalized;
	}

	protected Vector3 GetPlayerForward(PhotonPlayer photonPlayer)
	{
		Player player = photonPlayer?.ToPlayer();
		return (!(player != null)) ? Vector3.forward : Vector3.ProjectOnPlane(player.Head.transform.forward, Vector3.up).normalized;
	}

	protected Transform GetPlayerHead(PhotonPlayer photonPlayer)
	{
		Player player = photonPlayer?.ToPlayer();
		return (!(player != null)) ? null : player.Head.transform;
	}

	protected Vector3 GetPlayerHeadPosition(PhotonPlayer photonPlayer)
	{
		Player player = photonPlayer?.ToPlayer();
		return (!(player != null)) ? Vector3.zero : player.Head.transform.position;
	}

	private void OnDrawGizmos()
	{
		if (pathNodeCount > 0 && pathNodeIndex < pathNodeCount)
		{
			Gizmos.color = Color.blue;
			Gizmos.DrawLine(base.transform.position, pathNodes[pathNodeIndex]);
			Gizmos.color = Color.red;
			for (int i = 0; i < pathNodeCount - 1; i += 2)
			{
				Gizmos.DrawLine(pathNodes[i], pathNodes[i + 1]);
			}
		}
	}
}
public class QuestFlyingEnemy : QuestEnemy
{
	private enum AliveBehaviorSubState
	{
		FIND_TARGET,
		FOLLOW_TARGET,
		CHARGE_ATTACK,
		ATTACK_TARGET,
		FLEE,
		POST_FLEE
	}

	[Header("Hovering")]
	[SerializeField]
	private float hoverHeight = 3f;

	[Header("Behavior Timing")]
	[SerializeField]
	private float attackChargeDuration = 1f;

	[SerializeField]
	private float attackDuration = 3f;

	[SerializeField]
	private float postFleeDuration = 0.5f;

	[Header("Behavior Movement Speeds")]
	[SerializeField]
	private float followPlayerSpeed = 3.5f;

	[SerializeField]
	private float fleeSpeed = 6f;

	[Header("Behavior Distances")]
	[SerializeField]
	private float desiredAttackDistance = 3f;

	[SerializeField]
	private float maxFleeDistance = 6f;

	[Header("Projectile")]
	[SerializeField]
	private Bullet projectilePrefab;

	[SerializeField]
	private Color projectileColor = Color.red;

	[SerializeField]
	private Transform projectileOriginTransform;

	[SerializeField]
	private float projectileSpeed = 2f;

	protected override void Awake()
	{
		base.Awake();
		behaviorStateMachine.AddState(1, 0, null, null, OnUpdateFindTargetState);
		behaviorStateMachine.AddState(1, 1, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
		behaviorStateMachine.AddState(1, 2, OnEnterChargeAttackState, OnExitChargeAttackState, OnUpdateChargeAttackState);
		behaviorStateMachine.AddState(1, 3, OnEnterAttackTargetState, OnExitAttackTargetState, OnUpdateAttackTargetState);
		behaviorStateMachine.AddState(1, 4, OnEnterFleeState, OnExitFleeState, OnUpdateFleeState);
		behaviorStateMachine.AddState(1, 5, OnEnterPostFleeState, OnExitPostFleeState, OnUpdatePostFleeState);
	}

	protected override void Start()
	{
		base.Start();
		rigidbody.constraints = RigidbodyConstraints.None;
		behaviorStateMachine.Initialize(this, 1, 0);
	}

	private void OnUpdateFindTargetState()
	{
		if (base.hasAuthority)
		{
			PhotonPlayer photonPlayer = null;
			if (base.LastAttacker != null)
			{
				photonPlayer = base.LastAttacker;
				base.LastAttacker = null;
			}
			else
			{
				photonPlayer = GetRandomPlayer();
			}
			if (photonPlayer != null)
			{
				base.TargetPlayer = photonPlayer;
				behaviorStateMachine.EnterState(1, 1);
			}
		}
	}

	private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
	{
		if (base.hasAuthority)
		{
			steering.MaxLinearSpeed = followPlayerSpeed * base.MovementSpeedVarietyScalar;
			rigidbody.ClearVelocity();
		}
	}

	private void OnUpdateFollowTargetState()
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (base.TargetPlayer == null || !gameManager.CombatManager.PlayerIsAlive(base.TargetPlayer))
		{
			behaviorStateMachine.EnterState(1, 0);
			return;
		}
		Vector3 surfacePosition = GetSurfacePosition();
		Vector3 playerPosition = GetPlayerPosition(base.TargetPlayer);
		if (PathIsInvalid(playerPosition))
		{
			CalculateNewPath(surfacePosition, playerPosition);
		}
		bool flag = (playerPosition - surfacePosition).sqrMagnitude <= desiredAttackDistance * desiredAttackDistance;
		Vector3 vector = playerPosition - rigidbody.position;
		Vector3 hitPoint;
		bool flag2 = !TryGetRaycastHitPoint(rigidbody.position, vector.normalized, vector.magnitude, out hitPoint);
		if ((flag && flag2) || PathCompleted(surfacePosition))
		{
			behaviorStateMachine.EnterState(1, 2);
		}
		else
		{
			steering.Seek(GetNextPathNode(surfacePosition) + Vector3.up * hoverHeight);
		}
	}

	private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
	{
		steering.StopSeeking();
		if (base.hasAuthority)
		{
			ClearPath();
		}
	}

	private Vector3 GetSurfacePosition()
	{
		if (!TryGetRaycastHitPoint(rigidbody.position, -Vector3.up, float.MaxValue, out var hitPoint))
		{
			return rigidbody.position;
		}
		return hitPoint;
	}

	private bool TryGetRaycastHitPoint(Vector3 origin, Vector3 direction, float distance, out Vector3 hitPoint)
	{
		bool result = false;
		if (Physics.Raycast(origin, direction, out var hitInfo, distance, 2048))
		{
			hitPoint = hitInfo.point;
			result = true;
		}
		else
		{
			hitPoint = origin + direction * distance;
		}
		return result;
	}

	private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
	{
		if (base.hasAuthority)
		{
			behaviorTimer.StartTimer(attackChargeDuration);
		}
	}

	private void OnUpdateChargeAttackState()
	{
		if (base.hasAuthority)
		{
			if (base.TargetPlayer != null)
			{
				steering.Look((GetPlayerHead(base.TargetPlayer).position - base.transform.position).normalized);
			}
			if (behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(1, 3);
			}
		}
	}

	private void OnExitChargeAttackState(ushort nextStateId, ushort nextSubStateId)
	{
		steering.StopLooking();
	}

	private void OnEnterAttackTargetState(ushort previousStateId, ushort previousSubStateId)
	{
		if (base.hasAuthority)
		{
			behaviorTimer.StartTimer(attackDuration);
			if (base.TargetPlayer != null)
			{
				AuthorityFireProjectile(projectileOriginTransform.position, GetPlayerHeadPosition(base.TargetPlayer));
			}
		}
		rigidbody.ClearVelocity();
	}

	private void OnUpdateAttackTargetState()
	{
		if (base.hasAuthority)
		{
			if (base.TargetPlayer != null)
			{
				steering.Look((GetPlayerHead(base.TargetPlayer).position - base.transform.position).normalized);
			}
			if (behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(1, 4);
			}
		}
	}

	private void OnExitAttackTargetState(ushort nextStateId, ushort nextSubStateId)
	{
		steering.StopLooking();
	}

	private void OnEnterFleeState(ushort previousStateId, ushort previousSubStateId)
	{
		steering.MaxLinearSpeed = fleeSpeed * base.MovementSpeedVarietyScalar;
		if (base.hasAuthority)
		{
			Vector3 surfacePosition = GetSurfacePosition();
			CalculateNewPath(surfacePosition, GetFleePosition());
		}
	}

	private void OnUpdateFleeState()
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (base.TargetPlayer == null || !gameManager.CombatManager.PlayerIsAlive(base.TargetPlayer))
		{
			behaviorStateMachine.EnterState(1, 0);
			return;
		}
		Vector3 surfacePosition = GetSurfacePosition();
		if (PathCompleted(surfacePosition))
		{
			behaviorStateMachine.EnterState(1, 5);
		}
		else
		{
			steering.Seek(GetNextPathNode(surfacePosition) + Vector3.up * hoverHeight);
		}
	}

	private void OnExitFleeState(ushort nextStateId, ushort nextSubStateId)
	{
		steering.StopAll();
		if (base.hasAuthority)
		{
			ClearPath();
		}
	}

	private Vector3 GetFleePosition()
	{
		Vector2 insideUnitCircle = UnityEngine.Random.insideUnitCircle;
		Vector3 vector = new Vector3(insideUnitCircle.x, 0f, insideUnitCircle.y) * maxFleeDistance;
		return GetPathPosition(rigidbody.position + vector);
	}

	private void OnEnterPostFleeState(ushort previousStateId, ushort previousSubStateId)
	{
		if (base.hasAuthority)
		{
			behaviorTimer.StartTimer(postFleeDuration);
		}
	}

	private void OnUpdatePostFleeState()
	{
		if (base.hasAuthority && behaviorTimer.TimerOver)
		{
			behaviorStateMachine.EnterState(1, 1);
		}
	}

	private void OnExitPostFleeState(ushort nextStateId, ushort nextSubStateId)
	{
	}

	protected override void OnRecoilStart()
	{
		base.OnRecoilStart();
		rigidbody.useGravity = true;
	}

	protected override void OnRecoilEnd()
	{
		base.OnRecoilEnd();
		rigidbody.useGravity = false;
	}

	protected override void AuthorityEnterStateAfterRecoil()
	{
		behaviorStateMachine.EnterState(1, 0);
	}

	protected override void OnDeath()
	{
		base.OnDeath();
		rigidbody.useGravity = true;
	}

	private void AuthorityFireProjectile(Vector3 originPosition, Vector3 targetPosition)
	{
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcFireProjectile", PhotonTargets.All, originPosition, targetPosition);
		}
	}

	private void FireProjectile(Vector3 origin, Vector3 target)
	{
		Vector3 normalized = (target - origin).normalized;
		Bullet bullet = AcquireProjectile();
		if (bullet != null)
		{
			bullet.Fire(origin, Quaternion.LookRotation(normalized, Vector3.up), normalized * projectileSpeed, 1f, rigidbody);
		}
	}

	private Bullet AcquireProjectile()
	{
		Bullet bullet = null;
		if (projectilePrefab != null)
		{
			bullet = ObjectPool.Instance.Acquire(projectilePrefab);
			if (bullet != null)
			{
				bullet.DestroyEvent += OnProjectileDestroy;
				bullet.PlayerImpactEvent += OnProjectilePlayerImpact;
				bullet.EnemyImpactEvent += OnProjectileEnemyImpact;
				bullet.ToolImpactEvent += OnProjectileToolImpact;
				bullet.OtherImpactEvent += OnProjectileOtherImpact;
				bullet.Color = projectileColor;
			}
		}
		return bullet;
	}

	private void OnProjectileDestroy(Bullet projectile)
	{
		projectile.DestroyEvent -= OnProjectileDestroy;
		projectile.PlayerImpactEvent -= OnProjectilePlayerImpact;
		projectile.EnemyImpactEvent -= OnProjectileEnemyImpact;
		projectile.ToolImpactEvent -= OnProjectileToolImpact;
		projectile.OtherImpactEvent -= OnProjectileOtherImpact;
	}

	private void OnProjectilePlayerImpact(Bullet bullet, Vector3 fireDirection, Player player, Player.BodyPart bodyPart, float chargeAmount, GameObject hitGameObject, Vector3 position, Vector3 surfaceNormal)
	{
		PlayerHit(null, this, player, bodyPart, position);
	}

	private void OnProjectileEnemyImpact(Bullet bullet, Vector3 fireDirection, Enemy enemy, float chargeAmount, Vector3 collisionForce, GameObject hitGameObject, Vector3 position, Vector3 surfaceNormal)
	{
	}

	private void OnProjectileToolImpact(Bullet bullet, Vector3 fireDirection, Tool hitTool, float chargeAmount, Vector3 collisionForce, GameObject hitGameObject, Vector3 position, Vector3 surfaceNormal)
	{
	}

	private void OnProjectileOtherImpact(Bullet bullet, Vector3 fireDirection, float chargeAmount, GameObject hitGameObject, Vector3 position, Vector3 surfaceNormal)
	{
	}

	[PunRPC]
	private void RpcFireProjectile(Vector3 origin, Vector3 target)
	{
		FireProjectile(origin, target);
	}
}
public class QuestGroundEnemy : QuestEnemy
{
	private enum AliveBehaviorSubState
	{
		FIND_TARGET,
		FOLLOW_TARGET,
		ATTACK_TARGET
	}

	[Header("Movement")]
	[SerializeField]
	private float movementSpeed = 4f;

	[SerializeField]
	private float desiredTargetDistance = 1f;

	[Header("Attack")]
	[SerializeField]
	private float attackDuration = 1.5f;

	private static readonly Vector3[] surfaceQueryOffsets = new Vector3[2]
	{
		new Vector3(0f, 0f, 0.1f),
		new Vector3(0f, 0f, -0.1f)
	};

	protected override void Awake()
	{
		base.Awake();
		behaviorStateMachine.AddState(1, 0, null, null, OnUpdateFindTargetState);
		behaviorStateMachine.AddState(1, 1, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
		behaviorStateMachine.AddState(1, 2, OnEnterAttackTargetState, null, OnUpdateAttackTargetState);
	}

	protected override void Start()
	{
		base.Start();
		behaviorStateMachine.Initialize(this, 1, 0);
	}

	private void OnUpdateFindTargetState()
	{
		if (base.hasAuthority)
		{
			PhotonPlayer photonPlayer = null;
			if (base.LastAttacker != null)
			{
				photonPlayer = base.LastAttacker;
				base.LastAttacker = null;
			}
			else
			{
				photonPlayer = GetRandomPlayer();
			}
			if (photonPlayer != null)
			{
				base.TargetPlayer = photonPlayer;
				behaviorStateMachine.EnterState(1, 1);
			}
		}
	}

	private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
	{
		steering.MaxLinearSpeed = movementSpeed * base.MovementSpeedVarietyScalar;
	}

	private void OnUpdateFollowTargetState()
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (base.TargetPlayer == null || !gameManager.CombatManager.PlayerIsAlive(base.TargetPlayer))
		{
			behaviorStateMachine.EnterState(1, 0);
			return;
		}
		Vector3 targetPosition = GetTargetPosition();
		if (PathIsInvalid(targetPosition))
		{
			CalculateNewPath(base.transform.position, targetPosition);
		}
		if (PathCompleted(base.transform.position))
		{
			behaviorStateMachine.EnterState(1, 2);
		}
		else
		{
			steering.Seek(GetNextPathNode(base.transform.position));
		}
	}

	private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
	{
		steering.StopSeeking();
		if (base.hasAuthority)
		{
			ClearPath();
		}
	}

	private Vector3 GetTargetPosition()
	{
		Vector3 vector = Vector3.zero;
		if (base.TargetPlayer != null)
		{
			vector = GetPlayerPosition(base.TargetPlayer);
			Vector3 normalized = Vector3.ProjectOnPlane(vector - base.transform.position, Vector3.up).normalized;
			vector += normalized * desiredTargetDistance;
		}
		return vector;
	}

	private void OnEnterAttackTargetState(ushort previousStateId, ushort previousSubStateId)
	{
		if (base.hasAuthority)
		{
			behaviorTimer.StartTimer(attackDuration);
		}
	}

	private void OnUpdateAttackTargetState()
	{
		if (base.hasAuthority && behaviorTimer.TimerOver)
		{
			behaviorStateMachine.EnterState(1, 1);
		}
	}

	protected override void AuthorityEnterStateAfterRecoil()
	{
		behaviorStateMachine.EnterState(1, 0);
	}
}
public class QuestKnightEnemy : QuestGroundEnemy
{
	public override void AuthorityApplyDamage(int damage, Vector3 collisionForce, Vector3 collisionPosition)
	{
		if (Vector3.Dot((collisionPosition - rigidbody.position).normalized, base.transform.forward) <= 0f)
		{
			damage = 0;
			collisionForce *= 0.25f;
		}
		base.AuthorityApplyDamage(damage, collisionForce, collisionPosition);
	}
}
public class QuestManager : GameManager
{
	private enum QuestGameState
	{
		INVALID,
		ROOM_RUNNING,
		ROOM_CLEARED
	}

	private enum QuestPlayerStats
	{
		GOLD
	}

	[Serializable]
	private struct RunFlowRoom
	{
		public string Name;

		public QuestRoom.QuestRoomType RoomType;
	}

	[Header("Run Flow")]
	[SerializeField]
	private RunFlowRoom[] runFlowRooms;

	[Header("Health and Damage")]
	[SerializeField]
	private float invincibilityAfterHit = 2f;

	[SerializeField]
	private HealthBar healthBarPrefab;

	[SerializeField]
	private float monochromeTimeOnHit = 1f;

	[SerializeField]
	private PlayerHandGestures.Gesture reviveGesture;

	[Header("Room Completion Timing")]
	[SerializeField]
	private float roomClearedDuration = 4f;

	private QuestRoom[] rooms;

	private QuestRoom startingRoom;

	private SynchronizedStateMachine questStateMachine;

	private SynchronizedTimer masterQuestStateTimer;

	private SynchronizedField<int> _enemiesAlive;

	private SynchronizedField<int> _roomsCompleted;

	private SynchronizedField<int> _currentRoomId;

	private SynchronizedField<int> _previousRoomId;

	private Dictionary<Player, float> playerHitTimes;

	private Dictionary<PhotonPlayer, HealthBar> healthBars;

	private int EnemiesAlive
	{
		get
		{
			return _enemiesAlive.Get();
		}
		set
		{
			_enemiesAlive.ForceSet(value);
		}
	}

	private QuestRoom PreviousRoom
	{
		get
		{
			PhotonView photonView = PhotonView.Find(_previousRoomId.Get());
			return (!(photonView != null)) ? null : photonView.GetComponent<QuestRoom>();
		}
		set
		{
			_previousRoomId.ForceSet((!(value != null)) ? (-1) : value.photonView.viewID);
		}
	}

	private QuestRoom CurrentRoom
	{
		get
		{
			PhotonView photonView = PhotonView.Find(_currentRoomId.Get());
			return (!(photonView != null)) ? null : photonView.GetComponent<QuestRoom>();
		}
		set
		{
			_currentRoomId.ForceSet((!(value != null)) ? (-1) : value.photonView.viewID);
		}
	}

	private int RoomsCompleted
	{
		get
		{
			return _roomsCompleted.Get();
		}
		set
		{
			_roomsCompleted.ForceSet(value);
		}
	}

	private bool CurrentRoomAllEncounterSpacesStarted
	{
		get
		{
			bool result = true;
			QuestRoom currentRoom = CurrentRoom;
			if (currentRoom != null)
			{
				for (int i = 0; i < currentRoom.EncounterSpaces.Length; i++)
				{
					if (!currentRoom.EncounterSpaces[i].HasStarted)
					{
						result = false;
						break;
					}
				}
			}
			return result;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		rooms = UnityEngine.Object.FindObjectsOfType<QuestRoom>();
		if (rooms == null || rooms.Length == 0)
		{
			UnityEngine.Debug.LogError("Quest Manager has no rooms.  At least one room is required.");
		}
		else
		{
			QuestRoom[] array = rooms;
			foreach (QuestRoom questRoom in array)
			{
				questRoom.PlayerSpawnPointsEnabled = false;
			}
		}
		startingRoom = FindRoom(QuestRoom.QuestRoomType.STARTING_ROOM);
		if (startingRoom == null)
		{
			UnityEngine.Debug.LogError("Quest scene does not have a room marked as starting room.  There must be a starting room.");
		}
		else
		{
			startingRoom.PlayerSpawnPointsEnabled = true;
		}
		questStateMachine = new SynchronizedStateMachine("QUEST", SetterPermissionMode.MASTER);
		questStateMachine.AddState(0, null, null, null);
		questStateMachine.AddState(1, OnEnterRoomRunningState, null, OnUpdateRoomRunningState);
		questStateMachine.AddState(2, OnEnterRoomClearedState, OnExitRoomClearedState, OnUpdateRoomClearedState);
		masterQuestStateTimer = new SynchronizedTimer(this, "QUEST_TIMER", SetterPermissionMode.MASTER);
		_enemiesAlive = new SynchronizedField<int>(this, "ENEMIES_ALIVE", 0, SetterPermissionMode.MASTER);
		_roomsCompleted = new SynchronizedField<int>(this, "ROOMS_COMPLETED", 0, SetterPermissionMode.MASTER);
		_currentRoomId = new SynchronizedField<int>(this, "CURRENT_ROOM_ID", -1, SetterPermissionMode.MASTER);
		_previousRoomId = new SynchronizedField<int>(this, "PREVIOUS_ROOM_ID", -1, SetterPermissionMode.MASTER);
		playerHitTimes = new Dictionary<Player, float>();
		healthBars = new Dictionary<PhotonPlayer, HealthBar>();
	}

	protected override void Initialize()
	{
		base.Initialize();
		questStateMachine.Initialize(this, 0);
	}

	protected override void Update()
	{
		base.Update();
		questStateMachine.Update();
		masterQuestStateTimer.UpdateCallbacks();
	}

	protected override void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
		base.InitializeLocalPlayer(localPlayerIsSpectator);
		if (!localPlayerIsSpectator)
		{
			Player.LocalPlayer.PlayerUI.NameVisible = true;
			Player.LocalPlayer.BothHands.ForEach(delegate(PlayerHand x)
			{
				x.Gestures.GestureDetected += OnHandGestureDetected;
			});
		}
	}

	protected override void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		base.ResetLocalPlayer(localPlayerIsSpectator);
		if (!localPlayerIsSpectator)
		{
			Player.LocalPlayer.PlayerUI.NameVisible = false;
			Player.LocalPlayer.BothHands.ForEach(delegate(PlayerHand x)
			{
				x.Gestures.GestureDetected -= OnHandGestureDetected;
			});
			SingletonMonoBehaviour<CameraRig>.Instance.MonochromeImageEffect.FadeOut(0f);
		}
	}

	protected override void OnGameStart()
	{
		if (PhotonNetwork.isMasterClient)
		{
			RoomsCompleted = 0;
			PreviousRoom = null;
			CurrentRoom = startingRoom;
			PhotonPlayer[] activePlayers = base.TeamManager.GetActivePlayers();
			foreach (PhotonPlayer player in activePlayers)
			{
				base.CombatManager.MasterResetPlayerHealth(player);
			}
			base.photonView.RPC("RpcOnMultipleHealthChanges", PhotonTargets.All);
			questStateMachine.EnterState(1);
		}
	}

	protected override void OnGameEnd()
	{
		startingRoom.DoorsLocked = true;
		startingRoom.DoorTriggerActive = false;
		startingRoom.PlayerSpawnPointsEnabled = true;
		PhotonPlayer[] activePlayers = base.TeamManager.GetActivePlayers();
		foreach (PhotonPlayer key in activePlayers)
		{
			healthBars[key].Active = false;
		}
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		questStateMachine.EnterState(0);
		Enemy[] array = UnityEngine.Object.FindObjectsOfType<Enemy>();
		for (int j = 0; j < array.Length; j++)
		{
			if (!array[j].hasAuthority)
			{
				array[j].photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (array[j].IsAlive && array[j].Health > 0)
			{
				array[j].AuthorityApplyDamage(array[j].MaxHealth, Vector3.zero, Vector3.zero);
			}
		}
	}

	private void InitializeHealthBar(PhotonPlayer photonPlayer)
	{
		Player player = photonPlayer.ToPlayer();
		HealthBar value = null;
		if (player != null && !healthBars.TryGetValue(photonPlayer, out value))
		{
			value = UnityEngine.Object.Instantiate(healthBarPrefab, player.PlayerUI.LabelTransform, worldPositionStays: false);
			value.Initialize(photonPlayer, base.CombatManager.GetPlayerHealth(photonPlayer));
			value.Active = base.IsGameRunning;
			healthBars[photonPlayer] = value;
		}
	}

	public void RequestEncounterStart(QuestEncounterSpace encounterSpace)
	{
		if (!encounterSpace.HasStarted && CanStartEncounter(encounterSpace))
		{
			base.photonView.RPC("RpcMasterRequestEncounterStart", PhotonTargets.MasterClient, encounterSpace.photonView.viewID);
		}
	}

	private void MasterRequestEncounterStart(QuestEncounterSpace encounterSpace)
	{
		if (PhotonNetwork.isMasterClient && CanStartEncounter(encounterSpace))
		{
			encounterSpace.HasStarted = true;
			QuestEncounter encounter = CurrentRoom.PossibleEncounters[UnityEngine.Random.Range(0, CurrentRoom.PossibleEncounters.Length)];
			MasterSpawnEncounter(encounter, encounterSpace);
		}
	}

	private bool CanStartEncounter(QuestEncounterSpace encounterSpace)
	{
		return CurrentRoom != null && encounterSpace.Room == CurrentRoom && !encounterSpace.HasStarted;
	}

	private void MasterSpawnEncounter(QuestEncounter encounter, QuestEncounterSpace encounterSpace)
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		int num = 0;
		for (int i = 0; i < encounter.Enemies.Length; i++)
		{
			EnemyType enemyType = encounter.Enemies[i];
			EnemySpawnPoint enemySpawnPoint = encounterSpace.TryGetNextSpawnPoint(enemyType);
			if (enemySpawnPoint != null)
			{
				SpawnEnemy(enemyType, enemySpawnPoint);
				num++;
			}
		}
		EnemiesAlive += num;
	}

	private QuestRoom MasterGetNextRoom(QuestRoom roomToAvoid = null)
	{
		QuestRoom result = null;
		if (PhotonNetwork.isMasterClient)
		{
			int roomsCompleted = RoomsCompleted;
			if (roomsCompleted >= 0 && roomsCompleted < runFlowRooms.Length)
			{
				QuestRoom.QuestRoomType roomType = runFlowRooms[roomsCompleted].RoomType;
				return FindRoom(roomType);
			}
		}
		return result;
	}

	private QuestRoom FindRoom(QuestRoom.QuestRoomType roomType)
	{
		QuestRoom[] array = rooms;
		foreach (QuestRoom questRoom in array)
		{
			if (questRoom.RoomType == roomType)
			{
				return questRoom;
			}
		}
		return null;
	}

	private void SpawnEnemy(EnemyType enemyType, EnemySpawnPoint spawnPoint)
	{
		string enemyPrefabName = EnemyPrefabSettings.GetEnemyPrefabName(enemyType);
		GameObject gameObject = PhotonNetwork.InstantiateSceneObject(enemyPrefabName, spawnPoint.transform.position, spawnPoint.transform.rotation, 0, null);
		spawnPoint.MasterUse();
		if (gameObject != null)
		{
			Enemy component = gameObject.GetComponent<Enemy>();
			if (component != null)
			{
				PhotonNetwork.RPC(base.photonView, "RpcEnemySpawned", PhotonTargets.All, false, component.photonView.viewID);
			}
		}
	}

	private void OnEnemySpawned(Enemy spawnedEnemy)
	{
		if (spawnedEnemy != null)
		{
			spawnedEnemy.DeathEvent += OnEnemyDied;
			spawnedEnemy.PlayerHitEvent += OnEnemyHitPlayer;
		}
	}

	private void OnEnemyDied(Enemy deadEnemy)
	{
		if (!(deadEnemy == null))
		{
			deadEnemy.DeathEvent -= OnEnemyDied;
			deadEnemy.PlayerHitEvent -= OnEnemyHitPlayer;
			if (deadEnemy.hasAuthority)
			{
				PhotonNetwork.Destroy(deadEnemy.photonView);
			}
			if (PhotonNetwork.isMasterClient)
			{
				EnemiesAlive--;
			}
		}
	}

	protected override void OnTeamChange()
	{
		base.OnTeamChange();
		PhotonPlayer[] activePlayers = base.TeamManager.GetActivePlayers();
		foreach (PhotonPlayer photonPlayer in activePlayers)
		{
			HealthBar value = null;
			if (!healthBars.TryGetValue(photonPlayer, out value))
			{
				InitializeHealthBar(photonPlayer);
			}
		}
	}

	private void OnPlayerHealthChanged(PhotonPlayer player)
	{
		healthBars[player].Active = base.IsGameRunning;
		healthBars[player].UpdateHealth(base.CombatManager.GetPlayerHealth(player));
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		bool flag = true;
		PhotonPlayer[] activePlayers = base.TeamManager.GetActivePlayers();
		foreach (PhotonPlayer player2 in activePlayers)
		{
			if (base.CombatManager.PlayerIsAlive(player2))
			{
				flag = false;
				break;
			}
		}
		if (flag)
		{
			MasterStopGame();
		}
		else if (base.CombatManager.GetPlayerHealth(player) == 0)
		{
			base.photonView.RPC("RpcOnPlayerDown", PhotonTargets.All, player);
		}
	}

	private void OnPlayerRevived(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer)
	{
		OnPlayerHealthChanged(revivedPlayer);
		if (revivedPlayer.isLocal)
		{
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You've been revived by " + revivingPlayer.name + "!", 2f);
			SingletonMonoBehaviour<CameraRig>.Instance.MonochromeImageEffect.FadeOut(0.5f);
		}
	}

	private void OnEnemyHitPlayer(Weapon weapon, Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, Vector3 impactPoint)
	{
		if (hitPlayer.PhotonPlayer.isLocal && IsValidPlayerHit(enemy.photonView, hitPlayer.PhotonPlayer))
		{
			base.photonView.RPC("RpcMasterRequestPlayerHit", PhotonTargets.MasterClient, (!(weapon != null)) ? (-1) : weapon.photonView.viewID, enemy.photonView.viewID, hitPlayer.PhotonPlayer, (int)hitBodyPart, impactPoint);
		}
	}

	private void MasterRequestPlayerHit(Weapon weapon, Enemy enemy, PhotonPlayer hitPlayer, Player.BodyPart hitBodyPart, Vector3 impactPoint)
	{
		if (PhotonNetwork.isMasterClient && IsValidPlayerHit(enemy.photonView, hitPlayer))
		{
			playerHitTimes[hitPlayer.ToPlayer()] = Time.time;
			int num = ((!(weapon != null)) ? 1 : weapon.GetPlayerImpactDamage(hitBodyPart));
			base.CombatManager.MasterAddPlayerHealth(hitPlayer, -num);
			playerHitTimes[hitPlayer.ToPlayer()] = Time.time;
			base.photonView.RPC("RpcOnPlayerHit", PhotonTargets.All, (!(weapon != null)) ? (-1) : weapon.photonView.viewID, enemy.photonView.viewID, hitPlayer, hitBodyPart, impactPoint);
		}
	}

	private void OnPlayerHit(Weapon weapon, Enemy enemy, PhotonPlayer hitPlayer, Player.BodyPart hitBodyPart, Vector3 impactPoint)
	{
		base.FxManager.PlayFX(FxType.PLAYER_DAMAGED, impactPoint);
		OnPlayerHealthChanged(hitPlayer);
		if (!hitPlayer.isLocal)
		{
			return;
		}
		if (base.CombatManager.GetPlayerHealth(hitPlayer) > 0)
		{
			StartCoroutine(PlayLocalPlayerOnHitEffects());
		}
		foreach (PlayerHand bothHand in hitPlayer.ToPlayer().BothHands)
		{
			bothHand.Vibrate(200, 1000);
		}
	}

	private IEnumerator PlayLocalPlayerOnHitEffects()
	{
		SingletonMonoBehaviour<CameraRig>.Instance.MonochromeImageEffect.FadeIn(0.1f);
		yield return new WaitForSeconds(monochromeTimeOnHit);
		SingletonMonoBehaviour<CameraRig>.Instance.MonochromeImageEffect.FadeOut(0.5f);
	}

	private bool IsValidPlayerHit(PhotonView enemyPhotonView, PhotonPlayer photonPlayerHit)
	{
		bool result = true;
		float value = -1f;
		if (playerHitTimes.TryGetValue(photonPlayerHit.ToPlayer(), out value) && Time.time - value < invincibilityAfterHit)
		{
			result = false;
		}
		return result;
	}

	private void OnPlayerDown(PhotonPlayer downedPlayer)
	{
		if (downedPlayer.isLocal)
		{
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "You're Down!", "Shake a buddy's hand to revive.", 5f);
			SingletonMonoBehaviour<CameraRig>.Instance.MonochromeImageEffect.FadeIn(0.2f);
		}
		else
		{
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, downedPlayer.name + " is Down!", "Shake their hand to revive them.", 3f);
		}
	}

	private void OnHandGestureDetected(PlayerHand localHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		if (gesture == reviveGesture && !base.CombatManager.PlayerIsAlive(Player.LocalPlayer.PhotonPlayer) && otherHand != null && base.CombatManager.PlayerIsAlive(otherHand.ThisPlayer.PhotonPlayer))
		{
			base.photonView.RPC("RpcMasterRequestRevivePlayer", PhotonTargets.MasterClient, Player.LocalPlayer.PhotonPlayer, otherHand.ThisPlayer.PhotonPlayer);
		}
	}

