public class PlayerBodyBubble : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float playerHeadHeight = 0.4f;

	private float radius;

	private const int MAX_RAYCAST_HITS = 256;

	private static RaycastHit[] hits = new RaycastHit[256];

	public Player ThisPlayer { get; set; }

	public float Radius
	{
		get
		{
			return radius;
		}
		set
		{
			radius = value;
			base.transform.localScale = radius * 2f * Vector3.one;
		}
	}

	public Vector3 PlayerHeadOffset => Vector3.up * (playerHeadHeight - Radius);

	private void FixedUpdate()
	{
		base.transform.position = ThisPlayer.Head.transform.position + PlayerHeadOffset;
	}

	public Tool RunTeleportCollision(Vector3 teleportStart, Vector3 teleportEnd, float hitForce)
	{
		Vector3 vector = teleportEnd - teleportStart;
		float magnitude = vector.magnitude;
		if (magnitude < Mathf.Epsilon)
		{
			vector = Vector3.zero;
		}
		else
		{
			vector /= magnitude;
		}
		Tool tool = null;
		Vector3 origin = teleportStart + ThisPlayer.Head.HeightOffset + PlayerHeadOffset;
		int num = Physics.SphereCastNonAlloc(origin, radius, vector, hits, magnitude, 226894848, QueryTriggerInteraction.Ignore);
		for (int i = 0; i < num; i++)
		{
			tool = hits[i].collider.GetColliderTool();
			if (tool != null && tool.SupportsTeleportHits)
			{
				tool.ApplyForce(hits[i].point, vector * hitForce, playVFX: false);
				break;
			}
		}
		return tool;
	}
}
public class PlayerLineTrail : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private int maxHistoricalSegments = 3;

	[SerializeField]
	private float vertexSpacing = 0.25f;

	[SerializeField]
	private Vector2 alphas = new Vector2(0f, 1f);

	[SerializeField]
	private Vector2 widths = new Vector2(0.2f, 0.8f);

	private LineRenderer lineRenderer;

	private BezierPath bezierPath = new BezierPath();

	private Queue<Vector3> points = new Queue<Vector3>();

	public Color Color
	{
		set
		{
			if (lineRenderer != null)
			{
				Color startColor = value;
				startColor.a = alphas.x;
				Color endColor = value;
				endColor.a = alphas.y;
				lineRenderer.startColor = startColor;
				lineRenderer.endColor = endColor;
			}
		}
	}

	private void Awake()
	{
		lineRenderer = GetComponent<LineRenderer>();
		if (lineRenderer != null)
		{
			lineRenderer.startWidth = widths.x;
			lineRenderer.endWidth = widths.y;
		}
		Color = Color.white;
		lineRenderer.enabled = false;
	}

	public void Clear()
	{
		points.Clear();
		UpdatePath();
	}

	public void SetLatestPlayerPosition(Vector3 sourcePlayerPosition, Vector3 destinationPlayerPosition)
	{
		Vector3 vector = Vector3.up * widths.y / 2f;
		if (points.Count == 0)
		{
			points.Enqueue(sourcePlayerPosition + vector);
		}
		while (points.Count > maxHistoricalSegments)
		{
			points.Dequeue();
		}
		points.Enqueue(destinationPlayerPosition + vector);
		UpdatePath();
	}

	private void UpdatePath()
	{
		bezierPath.Clear();
		Vector3[] array = points.ToArray();
		for (int i = 0; i < array.Length - 1; i++)
		{
			Vector3 vector = array[i];
			Vector3 vector2 = array[i + 1];
			Vector3 vector3 = vector2 - vector;
			float magnitude = vector3.magnitude;
			Vector3 normalized = vector3.normalized;
			Vector3 zero = Vector3.zero;
			zero = ((i + 1 != array.Length - 1) ? (vector2 - array[i + 2]).normalized : (-normalized));
			Vector3 controlPoint = vector + normalized * 0.5f * magnitude;
			Vector3 controlPoint2 = vector2 + zero * 0.5f * magnitude;
			if (bezierPath.CurveCount == 0)
			{
				bezierPath.AddCurve(vector, controlPoint, controlPoint2, vector2);
			}
			else
			{
				bezierPath.AddCurve(controlPoint, controlPoint2, vector2);
			}
		}
		if (bezierPath.CurveCount == 0)
		{
			lineRenderer.enabled = false;
			return;
		}
		int num = Mathf.RoundToInt(bezierPath.PathLength / vertexSpacing);
		Vector3[] array2 = new Vector3[num];
		for (int j = 0; j < num; j++)
		{
			ref Vector3 reference = ref array2[j];
			reference = bezierPath.EvaluatePath((float)j / (float)(num - 1));
		}
		lineRenderer.enabled = true;
		lineRenderer.numPositions = num;
		lineRenderer.SetPositions(array2);
	}
}
public class SoccerBall : Ball
{
	public delegate void Score(SoccerBall thisBall, SoccerGoal goal, Vector3 scorePoint);

	public ParticleSystem FireTrail;

	private Dictionary<GameTeam, PhotonPlayer> lastHitPlayerByTeam = new Dictionary<GameTeam, PhotonPlayer>();

	public event Score ScoreEvent;

	protected override void Start()
	{
		base.Start();
		base.photonView.OwnerChangedEvent += PhotonView_OwnerChangedEvent;
		UpdateLastHitPlayerByTeam(PhotonNetwork.masterClient);
	}

	protected override void OnTriggerEnter(Collider collider)
	{
		base.OnTriggerEnter(collider);
		SoccerGoal component = collider.GetComponent<SoccerGoal>();
		if (component != null && base.hasAuthority && this.ScoreEvent != null)
		{
			this.ScoreEvent(this, component, base.transform.position);
		}
	}

	public override void OnOwnerRoleUpdated()
	{
		base.OnOwnerRoleUpdated();
		UpdateLastHitPlayerByTeam(base.Owner.PhotonPlayer);
	}

	protected override void OnApplyForceVFX(PhotonPlayer photonPlayer, Vector3 position, Vector3 force)
	{
		base.OnApplyForceVFX(photonPlayer, position, force);
		FireTrail.Play();
	}

	private void PhotonView_OwnerChangedEvent(int newOwnerId)
	{
		UpdateLastHitPlayerByTeam(PhotonPlayer.Find(newOwnerId));
	}

	private void UpdateLastHitPlayerByTeam(PhotonPlayer pPlayer)
	{
		if (pPlayer == null)
		{
			return;
		}
		GameTeam playerTeam = RecRoomSceneManager.Instance.GameManager.TeamManager.GetPlayerTeam(pPlayer);
		if (playerTeam != GameTeam.INVALID)
		{
			lastHitPlayerByTeam[playerTeam] = pPlayer;
		}
		GameTeam? gameTeam = null;
		foreach (KeyValuePair<GameTeam, PhotonPlayer> item in lastHitPlayerByTeam)
		{
			if (item.Value == pPlayer && item.Key != playerTeam)
			{
				gameTeam = item.Key;
				break;
			}
		}
		if (gameTeam.HasValue)
		{
			lastHitPlayerByTeam[gameTeam.Value] = null;
		}
	}

	public PhotonPlayer GetLastHitPlayer(GameTeam team)
	{
		PhotonPlayer value = null;
		lastHitPlayerByTeam.TryGetValue(team, out value);
		return value;
	}
}
