public interface IQuantizer
{
	bool UseColor32 { get; }

	Color[] Palette { get; }

	void Train(Color[] colors);

	void Train(Color32[] colors);
}
public class NeuQuantQuantizer : IQuantizer
{
	public bool UseColor32 => true;

	public Color[] Palette { get; private set; }

	public void Train(Color[] colors)
	{
		Color32[] array = new Color32[colors.Length];
		for (int i = 0; i < colors.Length; i++)
		{
			ref Color32 reference = ref array[i];
			reference = colors[i];
		}
	}

	public void Train(Color32[] colors)
	{
		byte[] array = new byte[colors.Length * 3];
		for (int i = 0; i < colors.Length; i++)
		{
			array[i * 3] = colors[i].b;
			array[i * 3 + 1] = colors[i].g;
			array[i * 3 + 2] = colors[i].r;
		}
		NeuQuant neuQuant = new NeuQuant(array, array.Length, 10);
		byte[] array2 = neuQuant.Process();
		Color[] array3 = new Color[array2.Length / 3];
		for (int j = 0; j < array3.Length; j++)
		{
			float b = (float)(int)array2[j * 3] / 256f;
			float g = (float)(int)array2[j * 3 + 1] / 256f;
			float r = (float)(int)array2[j * 3 + 2] / 256f;
			ref Color reference = ref array3[j];
			reference = new Color(r, g, b);
		}
		Palette = array3;
	}
}
public class QuantTest : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Texture2D src;

	public Texture2D dstQuant;

	public Texture2D dstGray;

	private void Start()
	{
		Color32[] pixels = src.GetPixels32();
		NeuQuantQuantizer neuQuantQuantizer = new NeuQuantQuantizer();
		neuQuantQuantizer.Train(pixels);
		Color[] palette = neuQuantQuantizer.Palette;
		int[] array = new int[pixels.Length];
		Color32[] array2 = new Color32[pixels.Length];
		for (int i = 0; i < pixels.Length; i++)
		{
			Color color = pixels[i];
			float num = 100f;
			int num2 = 0;
			for (int j = 0; j < palette.Length; j++)
			{
				Color color2 = palette[j];
				float num3 = Mathf.Abs(color2.r - color.r) + Mathf.Abs(color2.g - color.g) + Mathf.Abs(color2.b - color.b);
				if (num3 < num)
				{
					num = num3;
					num2 = j;
				}
			}
			array[i] = num2;
			ref Color32 reference = ref pixels[i];
			reference = palette[num2];
			ref Color32 reference2 = ref array2[i];
			reference2 = new Color32((byte)num2, (byte)num2, (byte)num2, byte.MaxValue);
		}
		dstQuant = new Texture2D(src.width, src.height);
		dstQuant.SetPixels32(pixels);
		dstQuant.Apply();
		dstGray = new Texture2D(src.width, src.height);
		dstGray.SetPixels32(array2);
		dstGray.Apply();
	}
}
public class CaptureGifOnKey : UnityEngine.MonoBehaviour
{
	public enum ButtonType
	{
		KeyCode,
		InputManager,
		Mobile
	}

	public string buttonName = "p";

	public ButtonType buttonType;

	public string dir = "gifs";

	public new string name = "gif";

	public int frames = 30;

	public float frameRate = 10f;

	public int height = 480;

	public float aspect = 1.3333334f;

	public bool lockFramerate;

	[Range(2f, 256f)]
	public int paletteSize = 256;

	public CaptureTheGIF.PaletteMode paletteMode;

	public int maxGifSize;

	public bool restrictDuplicateCaptures = true;

	private void Update()
	{
		bool flag = false;
		switch (buttonType)
		{
		case ButtonType.KeyCode:
		{
			KeyCode key = (KeyCode)Enum.Parse(typeof(KeyCode), buttonName, ignoreCase: true);
			flag = Input.GetKeyDown(key);
			break;
		}
		case ButtonType.InputManager:
			flag = Input.GetButtonDown(buttonName);
			break;
		default:
			throw new NotImplementedException("unknown button type: " + buttonType);
		}
		if (flag && (!restrictDuplicateCaptures || !CaptureTheGIF.running))
		{
			CaptureTheGIF.Instance.Capture(frames, (int)(aspect * (float)height), height, frameRate, dir, name, lockFramerate, paletteSize, paletteMode, maxGifSize);
		}
	}
}
public class CaptureGifOnStart : UnityEngine.MonoBehaviour
{
	public string dir = "gifs";

	public new string name = "gif";

	public int frames = 30;

	public float frameRate = 10f;

	public int height = 640;

	public float aspect = 1.3333334f;

	[Range(2f, 256f)]
	public int paletteSize = 256;

	public CaptureTheGIF.PaletteMode paletteMode;

	public int maxGifSize;

	private void Start()
	{
		CaptureTheGIF.Instance.Capture(frames, (int)(aspect * (float)height), height, frameRate, dir, name, lockFramerate: false, paletteSize, paletteMode, maxGifSize);
	}
}
public class CaptureTheGIF : UnityEngine.MonoBehaviour
{
	public enum PaletteMode
	{
		EveryFrame,
		FirstFrame
	}

	private static CaptureTheGIF instance;

	public static bool running;

	public static CaptureTheGIF Instance
	{
		get
		{
			if (!instance)
			{
				GameObject gameObject = new GameObject("CaptureTheGIF");
				gameObject.AddComponent<CaptureTheGIF>();
			}
			return instance;
		}
	}

	private void Awake()
	{
		if ((bool)instance)
		{
			UnityEngine.Debug.LogError("there is already an instance of CaptureTheGIF");
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			instance = this;
		}
	}

	public static FileStream MakeFile(string dirName, string name)
	{
		string text = Path.Combine(UnityEngine.Application.persistentDataPath, dirName);
		if (!Directory.Exists(text))
		{
			Directory.CreateDirectory(text);
		}
		string text2 = Path.Combine(text, name + ".gif");
		int num = 0;
		while (File.Exists(text2))
		{
			text2 = Path.Combine(text, name + num + ".gif");
			num++;
		}
		UnityEngine.Debug.Log("Creating File @: " + text2);
		return File.Create(text2);
	}

	public static RenderTexture Snapshot(int width, int height)
	{
		RenderTexture temporary = RenderTexture.GetTemporary(width, height, 24);
		foreach (Camera item in Camera.allCameras.OrderBy((Camera c) => c.depth))
		{
			RenderTexture targetTexture = item.targetTexture;
			item.targetTexture = temporary;
			item.Render();
			item.targetTexture = targetTexture;
			item.ResetAspect();
		}
		return temporary;
	}

	public Coroutine Capture(int frames, int width, int height, float frameRate, string dir, string name, bool lockFramerate = false, int paletteSize = 256, PaletteMode paletteMode = PaletteMode.EveryFrame, int maxGifSize = 0)
	{
		return StartCoroutine(CaptureRoutine(frames, width, height, frameRate, dir, name, lockFramerate, paletteSize, paletteMode, maxGifSize));
	}

	private IEnumerator CaptureRoutine(int frames, int width, int height, float frameRate, string dir, string name, bool lockFramerate, int paletteSize, PaletteMode paletteMode, int maxGifSize)
	{
		running = true;
		MemoryStream memStream = new MemoryStream();
		IEnumerator capRoutine = CaptureRoutine(frames, width, height, frameRate, memStream, closeWhenDone: false, lockFramerate, paletteSize, paletteMode, maxGifSize);
		while (capRoutine.MoveNext())
		{
			yield return capRoutine.Current;
		}
		FileStream file = MakeFile(dir, name);
		try
		{
			Thread thread = new Thread((ThreadStart)delegate
			{
				memStream.WriteTo(file);
				file.Flush();
				file.Close();
			});
			thread.Start();
			while (thread.ThreadState == System.Threading.ThreadState.Running)
			{
				yield return null;
			}
			running = false;
		}
		finally
		{
			if (file != null)
			{
				((IDisposable)file).Dispose();
			}
		}
	}

	public Coroutine Capture(int frames, int width, int height, float frameRate, Stream stream, bool closeWhenDone, bool lockFramerate = false, int paletteSize = 256, PaletteMode paletteMode = PaletteMode.EveryFrame, int maxGifSize = 0)
	{
		return StartCoroutine(CaptureRoutine(frames, width, height, frameRate, stream, closeWhenDone, lockFramerate, paletteSize, paletteMode, maxGifSize));
	}

	private IEnumerator CaptureRoutine(int frames, int width, int height, float frameRate, Stream stream, bool closeWhenDone, bool lockFramerate, int paletteSize, PaletteMode paletteMode, int maxGifSize)
	{
		List<RenderTexture> textures = new List<RenderTexture>();
		float t = Time.time;
		float waitUntil = t;
		if (lockFramerate)
		{
			Time.captureFramerate = (int)frameRate;
		}
		for (int f = 0; f < frames; f++)
		{
			if (!lockFramerate)
			{
				while (waitUntil > Time.time)
				{
					yield return null;
				}
			}
			yield return new WaitForEndOfFrame();
			waitUntil += 1f / frameRate;
			textures.Add(Snapshot(width, height));
		}
		Time.captureFramerate = 0;
		float period = 1f / frameRate;
		yield return MakeGif(textures, period, stream, closeWhenDone, paletteSize, paletteMode, maxGifSize);
	}

	public Coroutine MakeGif(List<RenderTexture> textures, float frameLength, Stream output, bool closeWhenDone, int paletteSize = 256, PaletteMode paletteMode = PaletteMode.EveryFrame, int maxGifSize = 0)
	{
		return StartCoroutine(MakeGifRoutine(textures, frameLength, output, closeWhenDone, paletteSize, paletteMode, maxGifSize));
	}

	public Coroutine MakeGif(List<Texture2D> textures, float frameLength, Stream output, bool closeWhenDone, int paletteSize = 256, PaletteMode paletteMode = PaletteMode.EveryFrame, int maxGifSize = 0)
	{
		return StartCoroutine(MakeGifRoutine(textures, frameLength, output, closeWhenDone, paletteSize, paletteMode, maxGifSize));
	}

	private static IEnumerator MakeGifRoutine(List<Texture2D> textures, float frameLength, Stream output, bool closeWhenDone, int paletteSize, PaletteMode paletteMode, int maxGifSize)
	{
		AnimatedGifEncoder gifEncoder = new AnimatedGifEncoder();
		gifEncoder.SetPaletteSize(paletteSize);
		gifEncoder.SetQuality(10);
		gifEncoder.SetStaticColorPaletteMode(paletteMode == PaletteMode.FirstFrame);
		gifEncoder.SetRepeat(0);
		gifEncoder.SetDelay((int)(frameLength * 1000f));
		gifEncoder.SetMaxSize(maxGifSize);
		gifEncoder.Start(output);
		ManualResetEvent imageStart = new ManualResetEvent(initialState: false);
		Gif.Components.Image image = null;
		bool done = false;
		bool processed = false;
		Thread worker = new Thread((ThreadStart)delegate
		{
			while (!done)
			{
				imageStart.WaitOne();
				imageStart.Reset();
				try
				{
					if (!gifEncoder.AddFrame(image))
					{
						done = true;
					}
				}
				catch (Exception message)
				{
					UnityEngine.Debug.Log(message);
					break;
				}
				Thread.MemoryBarrier();
				processed = true;
			}
		});
		worker.Start();
		foreach (Texture2D tex in textures)
		{
			if (done)
			{
				break;
			}
			image = new Gif.Components.Image(tex);
			processed = false;
			imageStart.Set();
			while (!processed && !done)
			{
				yield return null;
			}
		}
		done = true;
		textures.Clear();
		gifEncoder.Finish();
		output.Flush();
		if (closeWhenDone)
		{
			output.Close();
		}
	}

	private static IEnumerator MakeGifRoutine(List<RenderTexture> textures, float frameLength, Stream output, bool closeWhenDone, int paletteSize, PaletteMode paletteMode, int maxGifSize)
	{
		AnimatedGifEncoder gifEncoder = new AnimatedGifEncoder();
		gifEncoder.SetPaletteSize(paletteSize);
		gifEncoder.SetQuality(10);
		gifEncoder.SetStaticColorPaletteMode(paletteMode == PaletteMode.FirstFrame);
		gifEncoder.SetRepeat(0);
		gifEncoder.SetDelay((int)(frameLength * 1000f));
		gifEncoder.SetMaxSize(maxGifSize);
		gifEncoder.Start(output);
		int w = textures[0].width;
		int h = textures[0].height;
		Texture2D tex = new Texture2D(w, h, TextureFormat.ARGB32, mipmap: false, linear: true);
		ManualResetEvent imageStart = new ManualResetEvent(initialState: false);
		Gif.Components.Image image = null;
		bool done = false;
		bool processed = false;
		Thread worker = new Thread((ThreadStart)delegate
		{
			while (!done)
			{
				imageStart.WaitOne();
				imageStart.Reset();
				try
				{
					if (!gifEncoder.AddFrame(image))
					{
						done = true;
					}
				}
				catch (Exception message)
				{
					UnityEngine.Debug.Log(message);
					break;
				}
				Thread.MemoryBarrier();
				processed = true;
			}
		});
		worker.Start();
		for (int picCount = 0; picCount < textures.Count; picCount++)
		{
			if (done)
			{
				break;
			}
			RenderTexture tempTex = textures[picCount];
			RenderTexture oldActive = RenderTexture.active;
			RenderTexture.active = tempTex;
			tex.ReadPixels(new Rect(0f, 0f, w, h), 0, 0);
			RenderTexture.active = oldActive;
			RenderTexture.ReleaseTemporary(tempTex);
			image = new Gif.Components.Image(tex);
			processed = false;
			imageStart.Set();
			while (!processed && !done)
			{
				yield return null;
			}
		}
		done = true;
		textures.Clear();
		gifEncoder.Finish();
		UnityEngine.Object.DestroyImmediate(tex);
		output.Flush();
		if (closeWhenDone)
		{
			output.Close();
		}
	}
}
public class TimeTravelGifRecorder : UnityEngine.MonoBehaviour
{
	public KeyCode key = KeyCode.P;

	public string dir = "gifs";

	public new string name = "gif";

	public int width = 640;

	public int height = 480;

	public int frames = 30;

	public int frameRate = 15;

	[Range(2f, 256f)]
	public int paletteSize = 256;

	public CaptureTheGIF.PaletteMode paletteMode;

	public int maxGifSize;

	private List<RenderTexture> snapshots = new List<RenderTexture>();

	private float lastSnapshot;

	private void Start()
	{
		lastSnapshot = Time.time;
	}

	private void Update()
	{
		if (Time.time >= lastSnapshot + (float)(1 / frameRate))
		{
			lastSnapshot = Time.time;
			Snapshot();
		}
		if (Input.GetKeyDown(key))
		{
			FileStream output = CaptureTheGIF.MakeFile(dir, name);
			CaptureTheGIF.Instance.MakeGif(snapshots.ToList(), 1 / frameRate, output, closeWhenDone: true, paletteSize, paletteMode, maxGifSize);
			snapshots.Clear();
		}
	}

	private void Snapshot()
	{
		snapshots.Add(CaptureTheGIF.Snapshot(width, height));
		if (snapshots.Count > frames)
		{
			RenderTexture.ReleaseTemporary(snapshots[0]);
			snapshots.RemoveAt(0);
		}
	}
}
