}
public abstract class SA_Singleton<T> : UnityEngine.MonoBehaviour where T : UnityEngine.MonoBehaviour
{
	private static T _instance;

	private static bool applicationIsQuitting;

	[Obsolete("instance is deprectaed, plase use Instance instaed")]
	public static T instance => Instance;

	public static T Instance
	{
		get
		{
			if (applicationIsQuitting)
			{
				return (T)null;
			}
			if (_instance == null)
			{
				_instance = UnityEngine.Object.FindObjectOfType(typeof(T)) as T;
				if (_instance == null)
				{
					_instance = new GameObject().AddComponent<T>();
					_instance.gameObject.name = _instance.GetType().Name;
				}
			}
			return _instance;
		}
	}

	public static bool HasInstance => !IsDestroyed;

	public static bool IsDestroyed
	{
		get
		{
			if (_instance == null)
			{
				return true;
			}
			return false;
		}
	}

	protected virtual void OnDestroy()
	{
		_instance = (T)null;
		applicationIsQuitting = true;
	}

	protected virtual void OnApplicationQuit()
	{
		_instance = (T)null;
		applicationIsQuitting = true;
	}
}
[ExecuteInEditMode]
[RequireComponent(typeof(Light))]
public class LightShafts : UnityEngine.MonoBehaviour
{
	public LightShaftsShadowmapMode m_ShadowmapMode;

	private LightShaftsShadowmapMode m_ShadowmapModeOld;

	public Camera[] m_Cameras;

	public Camera m_CurrentCamera;

	private bool m_ShadowmapDirty = true;

	public Vector3 m_Size = new Vector3(10f, 10f, 20f);

	public float m_SpotNear = 0.1f;

	public float m_SpotFar = 1f;

	public LayerMask m_CullingMask = -1;

	public LayerMask m_ColorFilterMask = 0;

	public float m_Brightness = 5f;

	public float m_BrightnessColored = 5f;

	public float m_Extinction = 0.5f;

	public float m_MinDistFromCamera;

	public int m_ShadowmapRes = 1024;

	private Camera m_ShadowmapCamera;

	private RenderTexture m_Shadowmap;

	public Shader m_DepthShader;

	private RenderTexture m_ColorFilter;

	public Shader m_ColorFilterShader;

	public bool m_Colored;

	public float m_ColorBalance = 1f;

	public int m_EpipolarLines = 256;

	public int m_EpipolarSamples = 512;

	private RenderTexture m_CoordEpi;

	private RenderTexture m_DepthEpi;

	public Shader m_CoordShader;

	private Material m_CoordMaterial;

	private Camera m_CoordsCamera;

	private RenderTexture m_InterpolationEpi;

	public Shader m_DepthBreaksShader;

	private Material m_DepthBreaksMaterial;

	private RenderTexture m_RaymarchedLightEpi;

	private Material m_RaymarchMaterial;

	public Shader m_RaymarchShader;

	private RenderTexture m_InterpolateAlongRaysEpi;

	public Shader m_InterpolateAlongRaysShader;

	private Material m_InterpolateAlongRaysMaterial;

	private RenderTexture m_SamplePositions;

	public Shader m_SamplePositionsShader;

	private Material m_SamplePositionsMaterial;

	private bool m_SamplePositionsShaderCompiles;

	public Shader m_FinalInterpolationShader;

	private Material m_FinalInterpolationMaterial;

	public float m_DepthThreshold = 0.5f;

	public int m_InterpolationStep = 32;

	public bool m_ShowSamples;

	public bool m_ShowInterpolatedSamples;

	public float m_ShowSamplesBackgroundFade = 0.8f;

	public bool m_AttenuationCurveOn;

	public AnimationCurve m_AttenuationCurve;

	private Texture2D m_AttenuationCurveTex;

	private Light m_Light;

	private LightType m_LightType = LightType.Directional;

	private bool m_DX11Support;

	private bool m_MinRequirements;

	private Mesh m_SpotMesh;

	private float m_SpotMeshNear = -1f;

	private float m_SpotMeshFar = -1f;

	private float m_SpotMeshAngle = -1f;

	private float m_SpotMeshRange = -1f;

	public bool directional => m_LightType == LightType.Directional;

	public bool spot => m_LightType == LightType.Spot;

	private void InitLUTs()
	{
		if (!m_AttenuationCurveTex)
		{
			m_AttenuationCurveTex = new Texture2D(256, 1, TextureFormat.ARGB32, mipmap: false, linear: true);
			m_AttenuationCurveTex.wrapMode = TextureWrapMode.Clamp;
			m_AttenuationCurveTex.hideFlags = HideFlags.HideAndDontSave;
			if (m_AttenuationCurve == null || m_AttenuationCurve.length == 0)
			{
				m_AttenuationCurve = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(1f, 1f));
			}
			if ((bool)m_AttenuationCurveTex)
			{
				UpdateLUTs();
			}
		}
	}

	public void UpdateLUTs()
	{
		InitLUTs();
		if (m_AttenuationCurve != null)
		{
			for (int i = 0; i < 256; i++)
			{
				float num = Mathf.Clamp(m_AttenuationCurve.Evaluate((float)i / 255f), 0f, 1f);
				m_AttenuationCurveTex.SetPixel(i, 0, new Color(num, num, num, num));
			}
			m_AttenuationCurveTex.Apply();
		}
	}

	private void InitRenderTexture(ref RenderTexture rt, int width, int height, int depth, RenderTextureFormat format, bool temp = true)
	{
		if (temp)
		{
			rt = RenderTexture.GetTemporary(width, height, depth, format);
			return;
		}
		if (rt != null)
		{
			if (rt.width == width && rt.height == height && rt.depth == depth && rt.format == format)
			{
				return;
			}
			rt.Release();
			UnityEngine.Object.DestroyImmediate(rt);
		}
		rt = new RenderTexture(width, height, depth, format);
		rt.hideFlags = HideFlags.HideAndDontSave;
	}

	private void InitShadowmap()
	{
		bool flag = m_ShadowmapMode == LightShaftsShadowmapMode.Dynamic;
		if (flag && m_ShadowmapMode != m_ShadowmapModeOld)
		{
			if ((bool)m_Shadowmap)
			{
				m_Shadowmap.Release();
			}
			if ((bool)m_ColorFilter)
			{
				m_ColorFilter.Release();
			}
		}
		InitRenderTexture(ref m_Shadowmap, m_ShadowmapRes, m_ShadowmapRes, 24, RenderTextureFormat.RFloat, flag);
		m_Shadowmap.filterMode = FilterMode.Point;
		m_Shadowmap.wrapMode = TextureWrapMode.Clamp;
		if (m_Colored)
		{
			InitRenderTexture(ref m_ColorFilter, m_ShadowmapRes, m_ShadowmapRes, 0, RenderTextureFormat.ARGB32, flag);
		}
		m_ShadowmapModeOld = m_ShadowmapMode;
	}

	private void ReleaseShadowmap()
	{
		if (m_ShadowmapMode != LightShaftsShadowmapMode.Static)
		{
			RenderTexture.ReleaseTemporary(m_Shadowmap);
			RenderTexture.ReleaseTemporary(m_ColorFilter);
		}
	}

	private void InitEpipolarTextures()
	{
		m_EpipolarLines = ((m_EpipolarLines >= 8) ? m_EpipolarLines : 8);
		m_EpipolarSamples = ((m_EpipolarSamples >= 4) ? m_EpipolarSamples : 4);
		InitRenderTexture(ref m_CoordEpi, m_EpipolarSamples, m_EpipolarLines, 0, RenderTextureFormat.RGFloat);
		m_CoordEpi.filterMode = FilterMode.Point;
		InitRenderTexture(ref m_DepthEpi, m_EpipolarSamples, m_EpipolarLines, 0, RenderTextureFormat.RFloat);
		m_DepthEpi.filterMode = FilterMode.Point;
		InitRenderTexture(ref m_InterpolationEpi, m_EpipolarSamples, m_EpipolarLines, 0, (!m_DX11Support) ? RenderTextureFormat.RGFloat : RenderTextureFormat.RGInt);
		m_InterpolationEpi.filterMode = FilterMode.Point;
		InitRenderTexture(ref m_RaymarchedLightEpi, m_EpipolarSamples, m_EpipolarLines, 24, RenderTextureFormat.ARGBFloat);
		m_RaymarchedLightEpi.filterMode = FilterMode.Point;
		InitRenderTexture(ref m_InterpolateAlongRaysEpi, m_EpipolarSamples, m_EpipolarLines, 0, RenderTextureFormat.ARGBFloat);
		m_InterpolateAlongRaysEpi.filterMode = FilterMode.Point;
	}

	private void InitMaterial(ref Material material, Shader shader)
	{
		if (!material && (bool)shader)
		{
			material = new Material(shader);
			material.hideFlags = HideFlags.HideAndDontSave;
		}
	}

	private void InitMaterials()
	{
		InitMaterial(ref m_FinalInterpolationMaterial, m_FinalInterpolationShader);
		InitMaterial(ref m_CoordMaterial, m_CoordShader);
		InitMaterial(ref m_SamplePositionsMaterial, m_SamplePositionsShader);
		InitMaterial(ref m_RaymarchMaterial, m_RaymarchShader);
		InitMaterial(ref m_DepthBreaksMaterial, m_DepthBreaksShader);
		InitMaterial(ref m_InterpolateAlongRaysMaterial, m_InterpolateAlongRaysShader);
	}

	private void InitSpotFrustumMesh()
	{
		if (!m_SpotMesh)
		{
			m_SpotMesh = new Mesh();
			m_SpotMesh.hideFlags = HideFlags.HideAndDontSave;
		}
		Light light = m_Light;
		if (m_SpotMeshNear != m_SpotNear || m_SpotMeshFar != m_SpotFar || m_SpotMeshAngle != light.spotAngle || m_SpotMeshRange != light.range)
		{
			float num = light.range * m_SpotFar;
			float num2 = light.range * m_SpotNear;
			float num3 = Mathf.Tan(light.spotAngle * ((float)Math.PI / 180f) * 0.5f);
			float num4 = num * num3;
			float num5 = num2 * num3;
			Vector3[] array = ((m_SpotMesh.vertices == null || m_SpotMesh.vertices.Length != 8) ? new Vector3[8] : m_SpotMesh.vertices);
			ref Vector3 reference = ref array[0];
			reference = new Vector3(0f - num4, 0f - num4, num);
			ref Vector3 reference2 = ref array[1];
			reference2 = new Vector3(num4, 0f - num4, num);
			ref Vector3 reference3 = ref array[2];
			reference3 = new Vector3(num4, num4, num);
			ref Vector3 reference4 = ref array[3];
			reference4 = new Vector3(0f - num4, num4, num);
			ref Vector3 reference5 = ref array[4];
			reference5 = new Vector3(0f - num5, 0f - num5, num2);
			ref Vector3 reference6 = ref array[5];
			reference6 = new Vector3(num5, 0f - num5, num2);
			ref Vector3 reference7 = ref array[6];
			reference7 = new Vector3(num5, num5, num2);
			ref Vector3 reference8 = ref array[7];
			reference8 = new Vector3(0f - num5, num5, num2);
			m_SpotMesh.vertices = array;
			if (m_SpotMesh.GetTopology(0) != MeshTopology.Triangles || m_SpotMesh.triangles == null || m_SpotMesh.triangles.Length != 36)
			{
				int[] triangles = new int[36]
				{
					0, 1, 2, 0, 2, 3, 6, 5, 4, 7,
					6, 4, 3, 2, 6, 3, 6, 7, 2, 1,
					5, 2, 5, 6, 0, 3, 7, 0, 7, 4,
					5, 1, 0, 5, 0, 4
				};
				m_SpotMesh.triangles = triangles;
			}
			m_SpotMeshNear = m_SpotNear;
			m_SpotMeshFar = m_SpotFar;
			m_SpotMeshAngle = light.spotAngle;
			m_SpotMeshRange = light.range;
		}
	}

	public void UpdateLightType()
	{
		if (m_Light == null)
		{
			m_Light = GetComponent<Light>();
		}
		m_LightType = m_Light.type;
	}

	private bool ShaderCompiles(Shader shader)
	{
		if (!shader.isSupported)
		{
			UnityEngine.Debug.LogError("LightShafts' " + shader.name + " didn't compile on this platform.");
			return false;
		}
		return true;
	}

	public bool CheckMinRequirements()
	{
		m_DX11Support = SystemInfo.graphicsShaderLevel >= 50;
		m_MinRequirements = SystemInfo.graphicsShaderLevel >= 30;
		m_MinRequirements &= SystemInfo.SupportsRenderTextureFormat(RenderTextureFormat.RGFloat);
		m_MinRequirements &= SystemInfo.SupportsRenderTextureFormat(RenderTextureFormat.RFloat);
		if (!m_MinRequirements)
		{
			UnityEngine.Debug.LogError("LightShafts require Shader Model 3.0 and render textures (including the RGFloat and RFloat) formats. Disabling.");
		}
		bool flag = ShaderCompiles(m_DepthShader) && ShaderCompiles(m_ColorFilterShader) && ShaderCompiles(m_CoordShader) && ShaderCompiles(m_DepthBreaksShader) && ShaderCompiles(m_RaymarchShader) && ShaderCompiles(m_InterpolateAlongRaysShader) && ShaderCompiles(m_FinalInterpolationShader);
		if (!flag)
		{
			UnityEngine.Debug.LogError("LightShafts require above shaders. Disabling.");
		}
		m_MinRequirements &= flag;
		m_SamplePositionsShaderCompiles = m_SamplePositionsShader.isSupported;
		return m_MinRequirements;
	}

	private void InitResources()
	{
		UpdateLightType();
		InitMaterials();
		InitEpipolarTextures();
		InitLUTs();
		InitSpotFrustumMesh();
	}

	private void ReleaseResources()
	{
		ReleaseShadowmap();
		RenderTexture.ReleaseTemporary(m_CoordEpi);
		RenderTexture.ReleaseTemporary(m_DepthEpi);
		RenderTexture.ReleaseTemporary(m_InterpolationEpi);
		RenderTexture.ReleaseTemporary(m_RaymarchedLightEpi);
		RenderTexture.ReleaseTemporary(m_InterpolateAlongRaysEpi);
	}

	private Bounds GetBoundsLocal()
	{
		if (directional)
		{
			return new Bounds(new Vector3(0f, 0f, m_Size.z * 0.5f), m_Size);
		}
		Light light = m_Light;
		Vector3 center = new Vector3(0f, 0f, light.range * (m_SpotFar + m_SpotNear) * 0.5f);
		float z = (m_SpotFar - m_SpotNear) * light.range;
		float num = Mathf.Tan(light.spotAngle * ((float)Math.PI / 180f) * 0.5f) * m_SpotFar * light.range * 2f;
		return new Bounds(center, new Vector3(num, num, z));
	}

	private Matrix4x4 GetBoundsMatrix()
	{
		Bounds boundsLocal = GetBoundsLocal();
		Transform transform = base.transform;
		return Matrix4x4.TRS(transform.position + transform.forward * boundsLocal.center.z, transform.rotation, boundsLocal.size);
	}

	private float GetFrustumApex()
	{
		return (0f - m_SpotNear) / (m_SpotFar - m_SpotNear) - 0.5f;
	}

	private void OnDrawGizmosSelected()
	{
		UpdateLightType();
		Gizmos.color = Color.yellow;
		if (directional)
		{
			Gizmos.matrix = GetBoundsMatrix();
			Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
		}
		else if (spot)
		{
			Transform transform = base.transform;
			Light light = m_Light;
			Gizmos.matrix = Matrix4x4.TRS(transform.position, transform.rotation, Vector3.one);
			Gizmos.DrawFrustum(transform.position, light.spotAngle, light.range * m_SpotFar, light.range * m_SpotNear, 1f);
		}
	}

	private void RenderQuadSections(Vector4 lightPos)
	{
		for (int i = 0; i < 4; i++)
		{
			if ((i != 0 || !(lightPos.y > 1f)) && (i != 1 || !(lightPos.x > 1f)) && (i != 2 || !(lightPos.y < -1f)) && (i != 3 || !(lightPos.x < -1f)))
			{
				float num = (float)i / 2f - 1f;
				float y = num + 0.5f;
				GL.Begin(7);
				GL.Vertex3(-1f, num, 0f);
				GL.Vertex3(1f, num, 0f);
				GL.Vertex3(1f, y, 0f);
				GL.Vertex3(-1f, y, 0f);
				GL.End();
			}
		}
	}

	private void RenderQuad()
	{
		GL.Begin(7);
		GL.TexCoord2(0f, 0f);
		GL.Vertex3(-1f, -1f, 0f);
		GL.TexCoord2(0f, 1f);
		GL.Vertex3(-1f, 1f, 0f);
		GL.TexCoord2(1f, 1f);
		GL.Vertex3(1f, 1f, 0f);
		GL.TexCoord2(1f, 0f);
		GL.Vertex3(1f, -1f, 0f);
		GL.End();
	}

	private void RenderSpotFrustum()
	{
		Graphics.DrawMeshNow(m_SpotMesh, base.transform.position, base.transform.rotation);
	}

	private Vector4 GetLightViewportPos()
	{
		Vector3 position = base.transform.position;
		if (directional)
		{
			position = m_CurrentCamera.transform.position + base.transform.forward;
		}
		Vector3 vector = m_CurrentCamera.WorldToViewportPoint(position);
		return new Vector4(vector.x * 2f - 1f, vector.y * 2f - 1f, 0f, 0f);
	}

	private bool IsVisible()
	{
		Matrix4x4 worldToProjectionMatrix = m_CurrentCamera.projectionMatrix * m_CurrentCamera.worldToCameraMatrix * base.transform.localToWorldMatrix;
		return GeometryUtility.TestPlanesAABB(GeometryUtility.CalculateFrustumPlanes(worldToProjectionMatrix), GetBoundsLocal());
	}

	private bool IntersectsNearPlane()
	{
		Vector3[] vertices = m_SpotMesh.vertices;
		float num = m_CurrentCamera.nearClipPlane - 0.001f;
		Transform transform = base.transform;
		for (int i = 0; i < vertices.Length; i++)
		{
			float z = m_CurrentCamera.WorldToViewportPoint(transform.TransformPoint(vertices[i])).z;
			if (z < num)
			{
				return true;
			}
		}
		return false;
	}

	private void SetKeyword(bool firstOn, string firstKeyword, string secondKeyword)
	{
		Shader.EnableKeyword((!firstOn) ? secondKeyword : firstKeyword);
		Shader.DisableKeyword((!firstOn) ? firstKeyword : secondKeyword);
	}

	public void SetShadowmapDirty()
	{
		m_ShadowmapDirty = true;
	}

	private void GetFrustumRays(out Matrix4x4 frustumRays, out Vector3 cameraPosLocal)
	{
		float farClipPlane = m_CurrentCamera.farClipPlane;
		Vector3 position = m_CurrentCamera.transform.position;
		Matrix4x4 inverse = GetBoundsMatrix().inverse;
		Vector2[] array = new Vector2[4]
		{
			new Vector2(0f, 0f),
			new Vector2(1f, 0f),
			new Vector2(1f, 1f),
			new Vector2(0f, 1f)
		};
		frustumRays = default(Matrix4x4);
		for (int i = 0; i < 4; i++)
		{
			Vector3 v = m_CurrentCamera.ViewportToWorldPoint(new Vector3(array[i].x, array[i].y, farClipPlane)) - position;
			v = inverse.MultiplyVector(v);
			frustumRays.SetRow(i, v);
		}
		cameraPosLocal = inverse.MultiplyPoint3x4(position);
	}

	private void SetFrustumRays(Material material)
	{
		GetFrustumRays(out var frustumRays, out var cameraPosLocal);
		material.SetVector("_CameraPosLocal", cameraPosLocal);
		material.SetMatrix("_FrustumRays", frustumRays);
		material.SetFloat("_FrustumApex", GetFrustumApex());
	}

	private float GetDepthThresholdAdjusted()
	{
		return m_DepthThreshold / m_CurrentCamera.farClipPlane;
	}

	private bool CheckCamera()
	{
		if (m_Cameras == null)
		{
			return false;
		}
		Camera[] cameras = m_Cameras;
		foreach (Camera camera in cameras)
		{
			if (camera == m_CurrentCamera)
			{
				return true;
			}
		}
		return false;
	}

	public void UpdateCameraDepthMode()
	{
		if (m_Cameras == null)
		{
			return;
		}
		Camera[] cameras = m_Cameras;
		foreach (Camera camera in cameras)
		{
			if ((bool)camera)
			{
				camera.depthTextureMode |= DepthTextureMode.Depth;
			}
		}
	}

	public void Start()
	{
		CheckMinRequirements();
		if (m_Cameras == null || m_Cameras.Length == 0)
		{
			m_Cameras = new Camera[1] { Camera.main };
		}
		UpdateCameraDepthMode();
	}

	private void UpdateShadowmap()
	{
		if (m_ShadowmapMode != LightShaftsShadowmapMode.Static || m_ShadowmapDirty)
		{
			InitShadowmap();
			if (m_ShadowmapCamera == null)
			{
				GameObject gameObject = new GameObject("Depth Camera");
				gameObject.AddComponent(typeof(Camera));
				m_ShadowmapCamera = gameObject.GetComponent<Camera>();
				gameObject.hideFlags = HideFlags.HideAndDontSave;
				m_ShadowmapCamera.enabled = false;
				m_ShadowmapCamera.clearFlags = CameraClearFlags.Color;
			}
			Transform transform = m_ShadowmapCamera.transform;
			transform.position = base.transform.position;
			transform.rotation = base.transform.rotation;
			if (directional)
			{
				m_ShadowmapCamera.orthographic = true;
				m_ShadowmapCamera.nearClipPlane = 0f;
				m_ShadowmapCamera.farClipPlane = m_Size.z;
				m_ShadowmapCamera.orthographicSize = m_Size.y * 0.5f;
				m_ShadowmapCamera.aspect = m_Size.x / m_Size.y;
			}
			else
			{
				m_ShadowmapCamera.orthographic = false;
				m_ShadowmapCamera.nearClipPlane = m_SpotNear * m_Light.range;
				m_ShadowmapCamera.farClipPlane = m_SpotFar * m_Light.range;
				m_ShadowmapCamera.fieldOfView = m_Light.spotAngle;
				m_ShadowmapCamera.aspect = 1f;
			}
			m_ShadowmapCamera.renderingPath = RenderingPath.Forward;
			m_ShadowmapCamera.targetTexture = m_Shadowmap;
			m_ShadowmapCamera.cullingMask = m_CullingMask;
			m_ShadowmapCamera.backgroundColor = Color.white;
			m_ShadowmapCamera.RenderWithShader(m_DepthShader, "RenderType");
			if (m_Colored)
			{
				m_ShadowmapCamera.targetTexture = m_ColorFilter;
				m_ShadowmapCamera.cullingMask = m_ColorFilterMask;
				m_ShadowmapCamera.backgroundColor = new Color(m_ColorBalance, m_ColorBalance, m_ColorBalance);
				m_ShadowmapCamera.RenderWithShader(m_ColorFilterShader, string.Empty);
			}
			m_ShadowmapDirty = false;
		}
	}

	private void RenderCoords(int width, int height, Vector4 lightPos)
	{
		SetFrustumRays(m_CoordMaterial);
		RenderBuffer[] colorBuffers = new RenderBuffer[2] { m_CoordEpi.colorBuffer, m_DepthEpi.colorBuffer };
		Graphics.SetRenderTarget(colorBuffers, m_DepthEpi.depthBuffer);
		m_CoordMaterial.SetVector("_LightPos", lightPos);
		m_CoordMaterial.SetVector("_CoordTexDim", new Vector4(m_CoordEpi.width, m_CoordEpi.height, 1f / (float)m_CoordEpi.width, 1f / (float)m_CoordEpi.height));
		m_CoordMaterial.SetVector("_ScreenTexDim", new Vector4(width, height, 1f / (float)width, 1f / (float)height));
		m_CoordMaterial.SetPass(0);
		RenderQuad();
	}

	private void RenderInterpolationTexture(Vector4 lightPos)
	{
		Graphics.SetRenderTarget(m_InterpolationEpi.colorBuffer, m_RaymarchedLightEpi.depthBuffer);
		if (!m_DX11Support && (UnityEngine.Application.platform == RuntimePlatform.WindowsEditor || UnityEngine.Application.platform == RuntimePlatform.WindowsPlayer))
		{
			m_DepthBreaksMaterial.SetPass(1);
			RenderQuad();
		}
		else
		{
			GL.Clear(clearDepth: true, clearColor: true, new Color(0f, 0f, 0f, 1f));
		}
		m_DepthBreaksMaterial.SetFloat("_InterpolationStep", m_InterpolationStep);
		m_DepthBreaksMaterial.SetFloat("_DepthThreshold", GetDepthThresholdAdjusted());
		m_DepthBreaksMaterial.SetTexture("_DepthEpi", m_DepthEpi);
		m_DepthBreaksMaterial.SetVector("_DepthEpiTexDim", new Vector4(m_DepthEpi.width, m_DepthEpi.height, 1f / (float)m_DepthEpi.width, 1f / (float)m_DepthEpi.height));
		m_DepthBreaksMaterial.SetPass(0);
		RenderQuadSections(lightPos);
	}

	private void InterpolateAlongRays(Vector4 lightPos)
	{
		Graphics.SetRenderTarget(m_InterpolateAlongRaysEpi);
		m_InterpolateAlongRaysMaterial.SetFloat("_InterpolationStep", m_InterpolationStep);
		m_InterpolateAlongRaysMaterial.SetTexture("_InterpolationEpi", m_InterpolationEpi);
		m_InterpolateAlongRaysMaterial.SetTexture("_RaymarchedLightEpi", m_RaymarchedLightEpi);
		m_InterpolateAlongRaysMaterial.SetVector("_RaymarchedLightEpiTexDim", new Vector4(m_RaymarchedLightEpi.width, m_RaymarchedLightEpi.height, 1f / (float)m_RaymarchedLightEpi.width, 1f / (float)m_RaymarchedLightEpi.height));
		m_InterpolateAlongRaysMaterial.SetPass(0);
		RenderQuadSections(lightPos);
	}

	private void RenderSamplePositions(int width, int height, Vector4 lightPos)
	{
		InitRenderTexture(ref m_SamplePositions, width, height, 0, RenderTextureFormat.ARGB32, temp: false);
		m_SamplePositions.enableRandomWrite = true;
		m_SamplePositions.filterMode = FilterMode.Point;
		Graphics.SetRenderTarget(m_SamplePositions);
		GL.Clear(clearDepth: false, clearColor: true, new Color(0f, 0f, 0f, 1f));
		Graphics.ClearRandomWriteTargets();
		Graphics.SetRandomWriteTarget(1, m_SamplePositions);
		Graphics.SetRenderTarget(m_RaymarchedLightEpi);
		m_SamplePositionsMaterial.SetVector("_OutputTexDim", new Vector4(width - 1, height - 1, 0f, 0f));
		m_SamplePositionsMaterial.SetVector("_CoordTexDim", new Vector4(m_CoordEpi.width, m_CoordEpi.height, 0f, 0f));
		m_SamplePositionsMaterial.SetTexture("_Coord", m_CoordEpi);
		m_SamplePositionsMaterial.SetTexture("_InterpolationEpi", m_InterpolationEpi);
		if (m_ShowInterpolatedSamples)
		{
			m_SamplePositionsMaterial.SetFloat("_SampleType", 1f);
			m_SamplePositionsMaterial.SetVector("_Color", new Vector4(0.4f, 0.4f, 0f, 0f));
			m_SamplePositionsMaterial.SetPass(0);
			RenderQuad();
		}
		m_SamplePositionsMaterial.SetFloat("_SampleType", 0f);
		m_SamplePositionsMaterial.SetVector("_Color", new Vector4(1f, 0f, 0f, 0f));
		m_SamplePositionsMaterial.SetPass(0);
		RenderQuadSections(lightPos);
		Graphics.ClearRandomWriteTargets();
	}

	private void ShowSamples(int width, int height, Vector4 lightPos)
	{
		bool flag = m_ShowSamples && m_DX11Support && m_SamplePositionsShaderCompiles;
		SetKeyword(flag, "SHOW_SAMPLES_ON", "SHOW_SAMPLES_OFF");
		if (flag)
		{
			RenderSamplePositions(width, height, lightPos);
		}
		m_FinalInterpolationMaterial.SetFloat("_ShowSamplesBackgroundFade", m_ShowSamplesBackgroundFade);
	}

	private void Raymarch(int width, int height, Vector4 lightPos)
	{
		SetFrustumRays(m_RaymarchMaterial);
		int width2 = m_Shadowmap.width;
		int height2 = m_Shadowmap.height;
		Graphics.SetRenderTarget(m_RaymarchedLightEpi.colorBuffer, m_RaymarchedLightEpi.depthBuffer);
		GL.Clear(clearDepth: false, clearColor: true, new Color(0f, 0f, 0f, 1f));
		m_RaymarchMaterial.SetTexture("_Coord", m_CoordEpi);
		m_RaymarchMaterial.SetTexture("_InterpolationEpi", m_InterpolationEpi);
		m_RaymarchMaterial.SetTexture("_Shadowmap", m_Shadowmap);
		float num = ((!m_Colored) ? m_Brightness : (m_BrightnessColored / m_ColorBalance));
		num *= m_Light.intensity;
		m_RaymarchMaterial.SetFloat("_Brightness", num);
		m_RaymarchMaterial.SetFloat("_Extinction", 0f - m_Extinction);
		m_RaymarchMaterial.SetVector("_ShadowmapDim", new Vector4(width2, height2, 1f / (float)width2, 1f / (float)height2));
		m_RaymarchMaterial.SetVector("_ScreenTexDim", new Vector4(width, height, 1f / (float)width, 1f / (float)height));
		m_RaymarchMaterial.SetVector("_LightColor", m_Light.color.linear);
		m_RaymarchMaterial.SetFloat("_MinDistFromCamera", m_MinDistFromCamera);
		SetKeyword(m_Colored, "COLORED_ON", "COLORED_OFF");
		m_RaymarchMaterial.SetTexture("_ColorFilter", m_ColorFilter);
		SetKeyword(m_AttenuationCurveOn, "ATTENUATION_CURVE_ON", "ATTENUATION_CURVE_OFF");
		m_RaymarchMaterial.SetTexture("_AttenuationCurveTex", m_AttenuationCurveTex);
		Texture cookie = m_Light.cookie;
		SetKeyword(cookie != null, "COOKIE_TEX_ON", "COOKIE_TEX_OFF");
		if (cookie != null)
		{
			m_RaymarchMaterial.SetTexture("_Cookie", cookie);
		}
		m_RaymarchMaterial.SetPass(0);
		RenderQuadSections(lightPos);
	}

	public void OnRenderObject()
	{
		m_CurrentCamera = Camera.current;
		if (m_MinRequirements && CheckCamera() && IsVisible())
		{
			RenderBuffer activeDepthBuffer = Graphics.activeDepthBuffer;
			RenderBuffer activeColorBuffer = Graphics.activeColorBuffer;
			InitResources();
			Vector4 lightViewportPos = GetLightViewportPos();
			bool firstOn = lightViewportPos.x >= -1f && lightViewportPos.x <= 1f && lightViewportPos.y >= -1f && lightViewportPos.y <= 1f;
			SetKeyword(firstOn, "LIGHT_ON_SCREEN", "LIGHT_OFF_SCREEN");
			int width = Screen.width;
			int height = Screen.height;
			UpdateShadowmap();
			SetKeyword(directional, "DIRECTIONAL_SHAFTS", "SPOT_SHAFTS");
			RenderCoords(width, height, lightViewportPos);
			RenderInterpolationTexture(lightViewportPos);
			Raymarch(width, height, lightViewportPos);
			InterpolateAlongRays(lightViewportPos);
			ShowSamples(width, height, lightViewportPos);
			SetFrustumRays(m_FinalInterpolationMaterial);
			m_FinalInterpolationMaterial.SetTexture("_InterpolationEpi", m_InterpolationEpi);
			m_FinalInterpolationMaterial.SetTexture("_DepthEpi", m_DepthEpi);
			m_FinalInterpolationMaterial.SetTexture("_Shadowmap", m_Shadowmap);
			m_FinalInterpolationMaterial.SetTexture("_Coord", m_CoordEpi);
			m_FinalInterpolationMaterial.SetTexture("_SamplePositions", m_SamplePositions);
			m_FinalInterpolationMaterial.SetTexture("_RaymarchedLight", m_InterpolateAlongRaysEpi);
			m_FinalInterpolationMaterial.SetVector("_CoordTexDim", new Vector4(m_CoordEpi.width, m_CoordEpi.height, 1f / (float)m_CoordEpi.width, 1f / (float)m_CoordEpi.height));
			m_FinalInterpolationMaterial.SetVector("_ScreenTexDim", new Vector4(width, height, 1f / (float)width, 1f / (float)height));
			m_FinalInterpolationMaterial.SetVector("_LightPos", lightViewportPos);
			m_FinalInterpolationMaterial.SetFloat("_DepthThreshold", GetDepthThresholdAdjusted());
			bool flag = directional || IntersectsNearPlane();
			m_FinalInterpolationMaterial.SetFloat("_ZTest", (!flag) ? 2 : 8);
			SetKeyword(flag, "QUAD_SHAFTS", "FRUSTUM_SHAFTS");
			Graphics.SetRenderTarget(activeColorBuffer, activeDepthBuffer);
			m_FinalInterpolationMaterial.SetPass(0);
			if (flag)
			{
				RenderQuad();
			}
			else
			{
				RenderSpotFrustum();
			}
			ReleaseResources();
		}
	}
}
public enum LightShaftsShadowmapMode
{
	Dynamic,
	Static
}
public class OVRBoundary
{
	public enum Node
	{
		HandLeft = 3,
		HandRight = 4,
		Head = 9
	}

	public enum BoundaryType
	{
		OuterBoundary = 1,
		PlayArea = 0x100
	}

	public struct BoundaryTestResult
	{
		public bool IsTriggering;

		public float ClosestDistance;

		public Vector3 ClosestPoint;

		public Vector3 ClosestPointNormal;
	}

	public struct BoundaryLookAndFeel
	{
		public Color Color;
	}

	private static int cachedVector3fSize = Marshal.SizeOf(typeof(OVRPlugin.Vector3f));

	private static OVRNativeBuffer cachedGeometryNativeBuffer = new OVRNativeBuffer(0);

	private static float[] cachedGeometryManagedBuffer = new float[0];

	public bool GetConfigured()
	{
		return OVRPlugin.GetBoundaryConfigured();
	}

	public BoundaryTestResult TestNode(Node node, BoundaryType boundaryType)
	{
		OVRPlugin.BoundaryTestResult boundaryTestResult = OVRPlugin.TestBoundaryNode((OVRPlugin.Node)node, (OVRPlugin.BoundaryType)boundaryType);
		return new BoundaryTestResult
		{
			IsTriggering = (boundaryTestResult.IsTriggering == OVRPlugin.Bool.True),
			ClosestDistance = boundaryTestResult.ClosestDistance,
			ClosestPoint = boundaryTestResult.ClosestPoint.FromFlippedZVector3f(),
			ClosestPointNormal = boundaryTestResult.ClosestPointNormal.FromFlippedZVector3f()
		};
	}

	public BoundaryTestResult TestPoint(Vector3 point, BoundaryType boundaryType)
	{
		OVRPlugin.BoundaryTestResult boundaryTestResult = OVRPlugin.TestBoundaryPoint(point.ToFlippedZVector3f(), (OVRPlugin.BoundaryType)boundaryType);
		return new BoundaryTestResult
		{
			IsTriggering = (boundaryTestResult.IsTriggering == OVRPlugin.Bool.True),
			ClosestDistance = boundaryTestResult.ClosestDistance,
			ClosestPoint = boundaryTestResult.ClosestPoint.FromFlippedZVector3f(),
			ClosestPointNormal = boundaryTestResult.ClosestPointNormal.FromFlippedZVector3f()
		};
	}

	public void SetLookAndFeel(BoundaryLookAndFeel lookAndFeel)
	{
		OVRPlugin.BoundaryLookAndFeel boundaryLookAndFeel = new OVRPlugin.BoundaryLookAndFeel
		{
			Color = lookAndFeel.Color.ToColorf()
		};
		OVRPlugin.SetBoundaryLookAndFeel(boundaryLookAndFeel);
	}

	public void ResetLookAndFeel()
	{
		OVRPlugin.ResetBoundaryLookAndFeel();
	}

	public Vector3[] GetGeometry(BoundaryType boundaryType)
	{
		int pointsCount = 0;
		if (OVRPlugin.GetBoundaryGeometry2((OVRPlugin.BoundaryType)boundaryType, IntPtr.Zero, ref pointsCount))
		{
			int num = pointsCount * cachedVector3fSize;
			if (cachedGeometryNativeBuffer.GetCapacity() < num)
			{
				cachedGeometryNativeBuffer.Reset(num);
			}
			int num2 = pointsCount * 3;
			if (cachedGeometryManagedBuffer.Length < num2)
			{
				cachedGeometryManagedBuffer = new float[num2];
			}
			if (OVRPlugin.GetBoundaryGeometry2((OVRPlugin.BoundaryType)boundaryType, cachedGeometryNativeBuffer.GetPointer(), ref pointsCount))
			{
				Marshal.Copy(cachedGeometryNativeBuffer.GetPointer(), cachedGeometryManagedBuffer, 0, num2);
				Vector3[] array = new Vector3[pointsCount];
				for (int i = 0; i < pointsCount; i++)
				{
					ref Vector3 reference = ref array[i];
					reference = new OVRPlugin.Vector3f
					{
						x = cachedGeometryManagedBuffer[3 * i],
						y = cachedGeometryManagedBuffer[3 * i + 1],
						z = cachedGeometryManagedBuffer[3 * i + 2]
					}.FromFlippedZVector3f();
				}
				return array;
			}
		}
		return new Vector3[0];
	}

	public Vector3 GetDimensions(BoundaryType boundaryType)
	{
		return OVRPlugin.GetBoundaryDimensions((OVRPlugin.BoundaryType)boundaryType).FromVector3f();
	}

	public bool GetVisible()
	{
		return OVRPlugin.GetBoundaryVisible();
	}

	public void SetVisible(bool value)
	{
		OVRPlugin.SetBoundaryVisible(value);
	}
}
[ExecuteInEditMode]
public class OVRCameraRig : UnityEngine.MonoBehaviour
{
	public bool usePerEyeCameras;

	private readonly string trackingSpaceName = "TrackingSpace";

	private readonly string trackerAnchorName = "TrackerAnchor";

	private readonly string eyeAnchorName = "EyeAnchor";

	private readonly string handAnchorName = "HandAnchor";

	private readonly string legacyEyeAnchorName = "Camera";

	private Camera _centerEyeCamera;

	private Camera _leftEyeCamera;

	private Camera _rightEyeCamera;

	public Camera leftEyeCamera => (!usePerEyeCameras) ? _centerEyeCamera : _leftEyeCamera;

	public Camera rightEyeCamera => (!usePerEyeCameras) ? _centerEyeCamera : _rightEyeCamera;

	public Transform trackingSpace { get; private set; }

	public Transform leftEyeAnchor { get; private set; }

	public Transform centerEyeAnchor { get; private set; }

	public Transform rightEyeAnchor { get; private set; }

	public Transform leftHandAnchor { get; private set; }

	public Transform rightHandAnchor { get; private set; }

	public Transform trackerAnchor { get; private set; }

	public event Action<OVRCameraRig> UpdatedAnchors;

	private void Awake()
	{
		EnsureGameObjectIntegrity();
	}

	private void Start()
	{
		EnsureGameObjectIntegrity();
		if (UnityEngine.Application.isPlaying)
		{
			UpdateAnchors();
		}
	}

	private void Update()
	{
		EnsureGameObjectIntegrity();
		if (UnityEngine.Application.isPlaying)
		{
			UpdateAnchors();
		}
	}

	private void UpdateAnchors()
	{
		bool monoscopic = OVRManager.instance.monoscopic;
		OVRPose pose = OVRManager.tracker.GetPose();
		trackerAnchor.localRotation = pose.orientation;
		centerEyeAnchor.localRotation = InputTracking.GetLocalRotation(VRNode.CenterEye);
		leftEyeAnchor.localRotation = ((!monoscopic) ? InputTracking.GetLocalRotation(VRNode.LeftEye) : centerEyeAnchor.localRotation);
		rightEyeAnchor.localRotation = ((!monoscopic) ? InputTracking.GetLocalRotation(VRNode.RightEye) : centerEyeAnchor.localRotation);
		leftHandAnchor.localRotation = OVRInput.GetLocalControllerRotation(OVRInput.Controller.LTouch);
		rightHandAnchor.localRotation = OVRInput.GetLocalControllerRotation(OVRInput.Controller.RTouch);
		trackerAnchor.localPosition = pose.position;
		centerEyeAnchor.localPosition = InputTracking.GetLocalPosition(VRNode.CenterEye);
		leftEyeAnchor.localPosition = ((!monoscopic) ? InputTracking.GetLocalPosition(VRNode.LeftEye) : centerEyeAnchor.localPosition);
		rightEyeAnchor.localPosition = ((!monoscopic) ? InputTracking.GetLocalPosition(VRNode.RightEye) : centerEyeAnchor.localPosition);
		leftHandAnchor.localPosition = OVRInput.GetLocalControllerPosition(OVRInput.Controller.LTouch);
		rightHandAnchor.localPosition = OVRInput.GetLocalControllerPosition(OVRInput.Controller.RTouch);
		if (this.UpdatedAnchors != null)
		{
			this.UpdatedAnchors(this);
		}
	}

	public void EnsureGameObjectIntegrity()
	{
		if (trackingSpace == null)
		{
			trackingSpace = ConfigureRootAnchor(trackingSpaceName);
		}
		if (leftEyeAnchor == null)
		{
			leftEyeAnchor = ConfigureEyeAnchor(trackingSpace, VRNode.LeftEye);
		}
		if (centerEyeAnchor == null)
		{
			centerEyeAnchor = ConfigureEyeAnchor(trackingSpace, VRNode.CenterEye);
		}
		if (rightEyeAnchor == null)
		{
			rightEyeAnchor = ConfigureEyeAnchor(trackingSpace, VRNode.RightEye);
		}
		if (leftHandAnchor == null)
		{
			leftHandAnchor = ConfigureHandAnchor(trackingSpace, OVRPlugin.Node.HandLeft);
		}
		if (rightHandAnchor == null)
		{
			rightHandAnchor = ConfigureHandAnchor(trackingSpace, OVRPlugin.Node.HandRight);
		}
		if (trackerAnchor == null)
		{
			trackerAnchor = ConfigureTrackerAnchor(trackingSpace);
		}
		if (_centerEyeCamera == null || _leftEyeCamera == null || _rightEyeCamera == null)
		{
			_centerEyeCamera = centerEyeAnchor.GetComponent<Camera>();
			_leftEyeCamera = leftEyeAnchor.GetComponent<Camera>();
			_rightEyeCamera = rightEyeAnchor.GetComponent<Camera>();
			if (_centerEyeCamera == null)
			{
				_centerEyeCamera = centerEyeAnchor.gameObject.AddComponent<Camera>();
				_centerEyeCamera.tag = "MainCamera";
			}
			if (_leftEyeCamera == null)
			{
				_leftEyeCamera = leftEyeAnchor.gameObject.AddComponent<Camera>();
				_leftEyeCamera.tag = "MainCamera";
			}
			if (_rightEyeCamera == null)
			{
				_rightEyeCamera = rightEyeAnchor.gameObject.AddComponent<Camera>();
				_rightEyeCamera.tag = "MainCamera";
			}
			_centerEyeCamera.stereoTargetEye = StereoTargetEyeMask.Both;
			_leftEyeCamera.stereoTargetEye = StereoTargetEyeMask.Left;
			_rightEyeCamera.stereoTargetEye = StereoTargetEyeMask.Right;
		}
		_centerEyeCamera.enabled = !usePerEyeCameras;
		_leftEyeCamera.enabled = usePerEyeCameras;
		_rightEyeCamera.enabled = usePerEyeCameras;
	}

	private Transform ConfigureRootAnchor(string name)
	{
		Transform transform = base.transform.Find(name);
		if (transform == null)
		{
			transform = new GameObject(name).transform;
		}
		transform.parent = base.transform;
		transform.localScale = Vector3.one;
		transform.localPosition = Vector3.zero;
		transform.localRotation = Quaternion.identity;
		return transform;
	}

	private Transform ConfigureEyeAnchor(Transform root, VRNode eye)
	{
		string text = eye switch
		{
			VRNode.CenterEye => "Center", 
			VRNode.LeftEye => "Left", 
			_ => "Right", 
		} + eyeAnchorName;
		Transform transform = base.transform.Find(root.name + "/" + text);
		if (transform == null)
		{
			transform = base.transform.Find(text);
		}
		if (transform == null)
		{
			string text2 = legacyEyeAnchorName + eye;
			transform = base.transform.Find(text2);
		}
		if (transform == null)
		{
			transform = new GameObject(text).transform;
		}
		transform.name = text;
		transform.parent = root;
		transform.localScale = Vector3.one;
		transform.localPosition = Vector3.zero;
		transform.localRotation = Quaternion.identity;
		return transform;
	}

	private Transform ConfigureHandAnchor(Transform root, OVRPlugin.Node hand)
	{
		string text = ((hand != OVRPlugin.Node.HandLeft) ? "Right" : "Left");
		string text2 = text + handAnchorName;
		Transform transform = base.transform.Find(root.name + "/" + text2);
		if (transform == null)
		{
			transform = base.transform.Find(text2);
		}
		if (transform == null)
		{
			transform = new GameObject(text2).transform;
		}
		transform.name = text2;
		transform.parent = root;
		transform.localScale = Vector3.one;
		transform.localPosition = Vector3.zero;
		transform.localRotation = Quaternion.identity;
		return transform;
	}

	private Transform ConfigureTrackerAnchor(Transform root)
	{
		string text = trackerAnchorName;
		Transform transform = base.transform.Find(root.name + "/" + text);
		if (transform == null)
		{
			transform = new GameObject(text).transform;
		}
		transform.parent = root;
		transform.localScale = Vector3.one;
		transform.localPosition = Vector3.zero;
		transform.localRotation = Quaternion.identity;
		return transform;
	}
}
public static class OVRExtensions
{
	public static OVRPose ToTrackingSpacePose(this Transform transform)
	{
		OVRPose oVRPose = default(OVRPose);
		oVRPose.position = InputTracking.GetLocalPosition(VRNode.Head);
		oVRPose.orientation = InputTracking.GetLocalRotation(VRNode.Head);
		return oVRPose * transform.ToHeadSpacePose();
	}

	public static OVRPose ToHeadSpacePose(this Transform transform)
	{
		return Camera.current.transform.ToOVRPose().Inverse() * transform.ToOVRPose();
	}

	internal static OVRPose ToOVRPose(this Transform t, bool isLocal = false)
	{
		OVRPose result = default(OVRPose);
		result.orientation = ((!isLocal) ? t.rotation : t.localRotation);
		result.position = ((!isLocal) ? t.position : t.localPosition);
		return result;
	}

	internal static void FromOVRPose(this Transform t, OVRPose pose, bool isLocal = false)
	{
		if (isLocal)
		{
			t.localRotation = pose.orientation;
			t.localPosition = pose.position;
		}
		else
		{
			t.rotation = pose.orientation;
			t.position = pose.position;
		}
	}

	internal static OVRPose ToOVRPose(this OVRPlugin.Posef p)
	{
		return new OVRPose
		{
			position = new Vector3(p.Position.x, p.Position.y, 0f - p.Position.z),
			orientation = new Quaternion(0f - p.Orientation.x, 0f - p.Orientation.y, p.Orientation.z, p.Orientation.w)
		};
	}

	internal static OVRTracker.Frustum ToFrustum(this OVRPlugin.Frustumf f)
	{
		return new OVRTracker.Frustum
		{
			nearZ = f.zNear,
			farZ = f.zFar,
			fov = new Vector2
			{
				x = 57.29578f * f.fovX,
				y = 57.29578f * f.fovY
			}
		};
	}

	internal static Color FromColorf(this OVRPlugin.Colorf c)
	{
		return new Color
		{
			r = c.r,
			g = c.g,
			b = c.b,
			a = c.a
		};
	}

	internal static OVRPlugin.Colorf ToColorf(this Color c)
	{
		return new OVRPlugin.Colorf
		{
			r = c.r,
			g = c.g,
			b = c.b,
			a = c.a
		};
	}

	internal static Vector3 FromVector3f(this OVRPlugin.Vector3f v)
	{
		return new Vector3
		{
			x = v.x,
			y = v.y,
			z = v.z
		};
	}

	internal static Vector3 FromFlippedZVector3f(this OVRPlugin.Vector3f v)
	{
		return new Vector3
		{
			x = v.x,
			y = v.y,
			z = 0f - v.z
		};
	}

	internal static OVRPlugin.Vector3f ToVector3f(this Vector3 v)
	{
		return new OVRPlugin.Vector3f
		{
			x = v.x,
			y = v.y,
			z = v.z
		};
	}

	internal static OVRPlugin.Vector3f ToFlippedZVector3f(this Vector3 v)
	{
		return new OVRPlugin.Vector3f
		{
			x = v.x,
			y = v.y,
			z = 0f - v.z
		};
	}

	internal static Quaternion FromQuatf(this OVRPlugin.Quatf q)
	{
		return new Quaternion
		{
			x = q.x,
			y = q.y,
			z = q.z,
			w = q.w
		};
	}

	internal static OVRPlugin.Quatf ToQuatf(this Quaternion q)
	{
		return new OVRPlugin.Quatf
		{
			x = q.x,
			y = q.y,
			z = q.z,
			w = q.w
		};
	}
}
[Serializable]
public struct OVRPose
{
	public Vector3 position;

	public Quaternion orientation;

	public static OVRPose identity => new OVRPose
	{
		position = Vector3.zero,
		orientation = Quaternion.identity
	};

	public override bool Equals(object obj)
	{
		return obj is OVRPose && this == (OVRPose)obj;
	}

	public override int GetHashCode()
	{
		return position.GetHashCode() ^ orientation.GetHashCode();
	}

	public static bool operator ==(OVRPose x, OVRPose y)
	{
		return x.position == y.position && x.orientation == y.orientation;
	}

	public static bool operator !=(OVRPose x, OVRPose y)
	{
		return !(x == y);
	}

	public static OVRPose operator *(OVRPose lhs, OVRPose rhs)
	{
		return new OVRPose
		{
			position = lhs.position + lhs.orientation * rhs.position,
			orientation = lhs.orientation * rhs.orientation
		};
	}

	public OVRPose Inverse()
	{
		OVRPose result = default(OVRPose);
		result.orientation = Quaternion.Inverse(orientation);
		result.position = result.orientation * -position;
		return result;
	}

	internal OVRPose flipZ()
	{
		OVRPose result = this;
		result.position.z = 0f - result.position.z;
		result.orientation.z = 0f - result.orientation.z;
		result.orientation.w = 0f - result.orientation.w;
		return result;
	}

	internal OVRPlugin.Posef ToPosef()
	{
		return new OVRPlugin.Posef
		{
			Position = position.ToVector3f(),
			Orientation = orientation.ToQuatf()
		};
	}
}
public class OVRNativeBuffer : IDisposable
{
	private bool disposed;

	private int m_numBytes;

	private IntPtr m_ptr = IntPtr.Zero;

	public OVRNativeBuffer(int numBytes)
	{
		Reallocate(numBytes);
	}

	~OVRNativeBuffer()
	{
		Dispose(disposing: false);
	}

	public void Reset(int numBytes)
	{
		Reallocate(numBytes);
	}

	public int GetCapacity()
	{
		return m_numBytes;
	}

	public IntPtr GetPointer(int byteOffset = 0)
	{
		if (byteOffset < 0 || byteOffset >= m_numBytes)
		{
			return IntPtr.Zero;
		}
		return (byteOffset != 0) ? new IntPtr(m_ptr.ToInt64() + byteOffset) : m_ptr;
	}

	public void Dispose()
	{
		Dispose(disposing: true);
		GC.SuppressFinalize(this);
	}

	private void Dispose(bool disposing)
	{
		if (!disposed)
		{
			if (disposing)
			{
			}
			Release();
			disposed = true;
		}
	}

	private void Reallocate(int numBytes)
	{
		Release();
		if (numBytes > 0)
		{
			m_ptr = Marshal.AllocHGlobal(numBytes);
			m_numBytes = numBytes;
		}
		else
		{
			m_ptr = IntPtr.Zero;
			m_numBytes = 0;
		}
	}

	private void Release()
	{
		if (m_ptr != IntPtr.Zero)
		{
			Marshal.FreeHGlobal(m_ptr);
			m_ptr = IntPtr.Zero;
			m_numBytes = 0;
		}
	}
}
public class OVRDebugHeadController : UnityEngine.MonoBehaviour
{
	[SerializeField]
	public bool AllowPitchLook;

	[SerializeField]
	public bool AllowYawLook = true;

	[SerializeField]
	public bool InvertPitch;

	[SerializeField]
	public float GamePad_PitchDegreesPerSec = 90f;

	[SerializeField]
	public float GamePad_YawDegreesPerSec = 90f;

	[SerializeField]
	public bool AllowMovement;

	[SerializeField]
	public float ForwardSpeed = 2f;

	[SerializeField]
	public float StrafeSpeed = 2f;

	protected OVRCameraRig CameraRig;

	private void Awake()
	{
		OVRCameraRig[] componentsInChildren = base.gameObject.GetComponentsInChildren<OVRCameraRig>();
		if (componentsInChildren.Length == 0)
		{
			UnityEngine.Debug.LogWarning("OVRCamParent: No OVRCameraRig attached.");
		}
		else if (componentsInChildren.Length > 1)
		{
			UnityEngine.Debug.LogWarning("OVRCamParent: More then 1 OVRCameraRig attached.");
		}
		else
		{
			CameraRig = componentsInChildren[0];
		}
	}

	private void Start()
	{
	}

	private void Update()
	{
		if (AllowMovement)
		{
			float y = OVRInput.Get(OVRInput.RawAxis2D.LThumbstick).y;
			float x = OVRInput.Get(OVRInput.RawAxis2D.LThumbstick).x;
			Vector3 vector = CameraRig.centerEyeAnchor.rotation * Vector3.forward * y * Time.deltaTime * ForwardSpeed;
			Vector3 vector2 = CameraRig.centerEyeAnchor.rotation * Vector3.right * x * Time.deltaTime * StrafeSpeed;
			base.transform.position += vector + vector2;
		}
		if (VRDevice.isPresent || (!AllowYawLook && !AllowPitchLook))
		{
			return;
		}
		Quaternion quaternion = base.transform.rotation;
		if (AllowYawLook)
		{
			float x2 = OVRInput.Get(OVRInput.RawAxis2D.RThumbstick).x;
			float angle = x2 * Time.deltaTime * GamePad_YawDegreesPerSec;
			Quaternion quaternion2 = Quaternion.AngleAxis(angle, Vector3.up);
			quaternion = quaternion2 * quaternion;
		}
		if (AllowPitchLook)
		{
			float num = OVRInput.Get(OVRInput.RawAxis2D.RThumbstick).y;
			if (Mathf.Abs(num) > 0.0001f)
			{
				if (InvertPitch)
				{
					num *= -1f;
				}
				float angle2 = num * Time.deltaTime * GamePad_PitchDegreesPerSec;
				Quaternion quaternion3 = Quaternion.AngleAxis(angle2, Vector3.left);
				quaternion *= quaternion3;
			}
		}
		base.transform.rotation = quaternion;
	}
}
public class OVRDisplay
{
	public struct EyeRenderDesc
	{
		public Vector2 resolution;

		public Vector2 fov;
	}

	public struct LatencyData
	{
		public float render;

		public float timeWarp;

		public float postPresent;

		public float renderError;

		public float timeWarpError;
	}

	private bool needsConfigureTexture;

	private EyeRenderDesc[] eyeDescs = new EyeRenderDesc[2];

	public Vector3 acceleration
	{
		get
		{
			if (!OVRManager.isHmdPresent)
			{
				return Vector3.zero;
			}
			return OVRPlugin.GetEyeAcceleration(OVRPlugin.Eye.None).ToOVRPose().position;
		}
	}

	public Quaternion angularAcceleration
	{
		get
		{
			if (!OVRManager.isHmdPresent)
			{
				return Quaternion.identity;
			}
			return OVRPlugin.GetEyeAcceleration(OVRPlugin.Eye.None).ToOVRPose().orientation;
		}
	}

	public Vector3 velocity
	{
		get
		{
			if (!OVRManager.isHmdPresent)
			{
				return Vector3.zero;
			}
			return OVRPlugin.GetEyeVelocity(OVRPlugin.Eye.None).ToOVRPose().position;
		}
	}

	public Quaternion angularVelocity
	{
		get
		{
			if (!OVRManager.isHmdPresent)
			{
				return Quaternion.identity;
			}
			return OVRPlugin.GetEyeVelocity(OVRPlugin.Eye.None).ToOVRPose().orientation;
		}
	}

	public LatencyData latency
	{
		get
		{
			if (!OVRManager.isHmdPresent)
			{
				return default(LatencyData);
			}
			string input = OVRPlugin.latency;
			Regex regex = new Regex("Render: ([0-9]+[.][0-9]+)ms, TimeWarp: ([0-9]+[.][0-9]+)ms, PostPresent: ([0-9]+[.][0-9]+)ms", RegexOptions.None);
			LatencyData result = default(LatencyData);
			Match match = regex.Match(input);
			if (match.Success)
			{
				result.render = float.Parse(match.Groups[1].Value);
				result.timeWarp = float.Parse(match.Groups[2].Value);
				result.postPresent = float.Parse(match.Groups[3].Value);
			}
			return result;
		}
	}

	public int recommendedMSAALevel
	{
		get
		{
			int num = OVRPlugin.recommendedMSAALevel;
			if (num == 1)
			{
				num = 0;
			}
			return num;
		}
	}

	public event Action RecenteredPose;

	public OVRDisplay()
	{
		UpdateTextures();
	}

	public void Update()
	{
		UpdateTextures();
	}

	public void RecenterPose()
	{
		InputTracking.Recenter();
		if (this.RecenteredPose != null)
		{
			this.RecenteredPose();
		}
	}

	public EyeRenderDesc GetEyeRenderDesc(VRNode eye)
	{
		return eyeDescs[(int)eye];
	}

	private void UpdateTextures()
	{
		ConfigureEyeDesc(VRNode.LeftEye);
		ConfigureEyeDesc(VRNode.RightEye);
	}

	private void ConfigureEyeDesc(VRNode eye)
	{
		if (OVRManager.isHmdPresent)
		{
			OVRPlugin.Sizei eyeTextureSize = OVRPlugin.GetEyeTextureSize((OVRPlugin.Eye)eye);
			OVRPlugin.Frustumf eyeFrustum = OVRPlugin.GetEyeFrustum((OVRPlugin.Eye)eye);
			ref EyeRenderDesc reference = ref eyeDescs[(int)eye];
			reference = new EyeRenderDesc
			{
				resolution = new Vector2(eyeTextureSize.w, eyeTextureSize.h),
				fov = 57.29578f * new Vector2(eyeFrustum.fovX, eyeFrustum.fovY)
			};
		}
	}
}
public static class OVRHaptics
{
	public static class Config
	{
		public static int SampleRateHz { get; private set; }

		public static int SampleSizeInBytes { get; private set; }

		public static int MinimumSafeSamplesQueued { get; private set; }

		public static int MinimumBufferSamplesCount { get; private set; }

		public static int OptimalBufferSamplesCount { get; private set; }

		public static int MaximumBufferSamplesCount { get; private set; }

		static Config()
		{
			Load();
		}

		public static void Load()
		{
			OVRPlugin.HapticsDesc controllerHapticsDesc = OVRPlugin.GetControllerHapticsDesc(2u);
			SampleRateHz = controllerHapticsDesc.SampleRateHz;
			SampleSizeInBytes = controllerHapticsDesc.SampleSizeInBytes;
			MinimumSafeSamplesQueued = controllerHapticsDesc.MinimumSafeSamplesQueued;
			MinimumBufferSamplesCount = controllerHapticsDesc.MinimumBufferSamplesCount;
			OptimalBufferSamplesCount = controllerHapticsDesc.OptimalBufferSamplesCount;
			MaximumBufferSamplesCount = controllerHapticsDesc.MaximumBufferSamplesCount;
		}
	}

	public class OVRHapticsChannel
	{
		private OVRHapticsOutput m_output;

		public OVRHapticsChannel(uint outputIndex)
		{
			m_output = m_outputs[outputIndex];
		}

		public void Preempt(OVRHapticsClip clip)
		{
			m_output.Preempt(clip);
		}

		public void Queue(OVRHapticsClip clip)
		{
			m_output.Queue(clip);
		}

		public void Mix(OVRHapticsClip clip)
		{
			m_output.Mix(clip);
		}

		public void Clear()
		{
			m_output.Clear();
		}
	}

	private class OVRHapticsOutput
	{
		private class ClipPlaybackTracker
		{
			public int ReadCount { get; set; }

			public OVRHapticsClip Clip { get; set; }

			public ClipPlaybackTracker(OVRHapticsClip clip)
			{
				Clip = clip;
			}
		}

		private bool m_lowLatencyMode = true;

		private int m_prevSamplesQueued;

		private float m_prevSamplesQueuedTime;

		private int m_numPredictionHits;

		private int m_numPredictionMisses;

		private int m_numUnderruns;

		private List<ClipPlaybackTracker> m_pendingClips = new List<ClipPlaybackTracker>();

		private uint m_controller;

		private OVRNativeBuffer m_nativeBuffer = new OVRNativeBuffer(Config.MaximumBufferSamplesCount * Config.SampleSizeInBytes);

		private OVRHapticsClip m_paddingClip = new OVRHapticsClip();

		public OVRHapticsOutput(uint controller)
		{
			m_controller = controller;
		}

		public void Process()
		{
			OVRPlugin.HapticsState controllerHapticsState = OVRPlugin.GetControllerHapticsState(m_controller);
			float num = Time.realtimeSinceStartup - m_prevSamplesQueuedTime;
			if (m_prevSamplesQueued > 0)
			{
				int num2 = m_prevSamplesQueued - (int)(num * (float)Config.SampleRateHz + 0.5f);
				if (num2 < 0)
				{
					num2 = 0;
				}
				if (controllerHapticsState.SamplesQueued - num2 == 0)
				{
					m_numPredictionHits++;
				}
				else
				{
					m_numPredictionMisses++;
				}
				if (num2 > 0 && controllerHapticsState.SamplesQueued == 0)
				{
					m_numUnderruns++;
				}
				m_prevSamplesQueued = controllerHapticsState.SamplesQueued;
				m_prevSamplesQueuedTime = Time.realtimeSinceStartup;
			}
			int num3 = Config.OptimalBufferSamplesCount;
			if (m_lowLatencyMode)
			{
				float num4 = 1000f / (float)Config.SampleRateHz;
				float num5 = num * 1000f;
				int num6 = (int)Mathf.Ceil(num5 / num4);
				int num7 = Config.MinimumSafeSamplesQueued + num6;
				if (num7 < num3)
				{
					num3 = num7;
				}
			}
			if (controllerHapticsState.SamplesQueued > num3)
			{
				return;
			}
			if (num3 > Config.MaximumBufferSamplesCount)
			{
				num3 = Config.MaximumBufferSamplesCount;
			}
			if (num3 > controllerHapticsState.SamplesAvailable)
			{
				num3 = controllerHapticsState.SamplesAvailable;
			}
			int num8 = 0;
			int num9 = 0;
			while (num8 < num3 && num9 < m_pendingClips.Count)
			{
				int num10 = num3 - num8;
				int num11 = m_pendingClips[num9].Clip.Count - m_pendingClips[num9].ReadCount;
				if (num10 > num11)
				{
					num10 = num11;
				}
				if (num10 > 0)
				{
					int length = num10 * Config.SampleSizeInBytes;
					int byteOffset = num8 * Config.SampleSizeInBytes;
					int startIndex = m_pendingClips[num9].ReadCount * Config.SampleSizeInBytes;
					Marshal.Copy(m_pendingClips[num9].Clip.Samples, startIndex, m_nativeBuffer.GetPointer(byteOffset), length);
					m_pendingClips[num9].ReadCount += num10;
					num8 += num10;
				}
				num9++;
			}
			int num12 = m_pendingClips.Count - 1;
			while (num12 >= 0 && m_pendingClips.Count > 0)
			{
				if (m_pendingClips[num12].ReadCount >= m_pendingClips[num12].Clip.Count)
				{
					m_pendingClips.RemoveAt(num12);
				}
				num12--;
			}
			int num13 = num3 - (controllerHapticsState.SamplesQueued + num8);
			if (num13 < Config.MinimumBufferSamplesCount - num8)
			{
				num13 = Config.MinimumBufferSamplesCount - num8;
			}
			if (num13 > controllerHapticsState.SamplesAvailable)
			{
				num13 = controllerHapticsState.SamplesAvailable;
			}
			if (num13 > 0)
			{
				int length2 = num13 * Config.SampleSizeInBytes;
				int byteOffset2 = num8 * Config.SampleSizeInBytes;
				int startIndex2 = 0;
				Marshal.Copy(m_paddingClip.Samples, startIndex2, m_nativeBuffer.GetPointer(byteOffset2), length2);
				num8 += num13;
			}
			if (num8 > 0)
			{
				OVRPlugin.HapticsBuffer hapticsBuffer = default(OVRPlugin.HapticsBuffer);
				hapticsBuffer.Samples = m_nativeBuffer.GetPointer();
				hapticsBuffer.SamplesCount = num8;
				OVRPlugin.SetControllerHaptics(m_controller, hapticsBuffer);
				m_prevSamplesQueued = OVRPlugin.GetControllerHapticsState(m_controller).SamplesQueued;
				m_prevSamplesQueuedTime = Time.realtimeSinceStartup;
			}
		}

		public void Preempt(OVRHapticsClip clip)
		{
			m_pendingClips.Clear();
			m_pendingClips.Add(new ClipPlaybackTracker(clip));
		}

		public void Queue(OVRHapticsClip clip)
		{
			m_pendingClips.Add(new ClipPlaybackTracker(clip));
		}

		public void Mix(OVRHapticsClip clip)
		{
			int num = 0;
			int num2 = 0;
			int num3 = clip.Count;
			while (num3 > 0 && num < m_pendingClips.Count)
			{
				int num4 = m_pendingClips[num].Clip.Count - m_pendingClips[num].ReadCount;
				num3 -= num4;
				num2 += num4;
				num++;
			}
			if (num3 > 0)
			{
				num2 += num3;
				num3 = 0;
			}
			if (num > 0)
			{
				OVRHapticsClip oVRHapticsClip = new OVRHapticsClip(num2);
				int i = 0;
				for (int j = 0; j < num; j++)
				{
					OVRHapticsClip clip2 = m_pendingClips[j].Clip;
					for (int k = m_pendingClips[j].ReadCount; k < clip2.Count; k++)
					{
						if (Config.SampleSizeInBytes == 1)
						{
							byte sample = 0;
							if (i < clip.Count && k < clip2.Count)
							{
								sample = (byte)Mathf.Clamp(clip.Samples[i] + clip2.Samples[k], 0, 255);
								i++;
							}
							else if (k < clip2.Count)
							{
								sample = clip2.Samples[k];
							}
							oVRHapticsClip.WriteSample(sample);
						}
					}
				}
				for (; i < clip.Count; i++)
				{
					if (Config.SampleSizeInBytes == 1)
					{
						oVRHapticsClip.WriteSample(clip.Samples[i]);
					}
				}
				m_pendingClips[0] = new ClipPlaybackTracker(oVRHapticsClip);
				for (int l = 1; l < num; l++)
				{
					m_pendingClips.RemoveAt(1);
				}
			}
			else
			{
				m_pendingClips.Add(new ClipPlaybackTracker(clip));
			}
		}

		public void Clear()
		{
			m_pendingClips.Clear();
		}
	}

	public static readonly OVRHapticsChannel[] Channels;

	public static readonly OVRHapticsChannel LeftChannel;

	public static readonly OVRHapticsChannel RightChannel;

	private static readonly OVRHapticsOutput[] m_outputs;

	static OVRHaptics()
	{
		Config.Load();
		m_outputs = new OVRHapticsOutput[2]
		{
			new OVRHapticsOutput(1u),
			new OVRHapticsOutput(2u)
		};
		Channels = new OVRHapticsChannel[2]
		{
			LeftChannel = new OVRHapticsChannel(0u),
			RightChannel = new OVRHapticsChannel(1u)
		};
	}

	public static void Process()
	{
		Config.Load();
		for (int i = 0; i < m_outputs.Length; i++)
		{
			m_outputs[i].Process();
		}
	}
}
public class OVRHapticsClip
{
	public int Count { get; private set; }

	public int Capacity { get; private set; }

	public byte[] Samples { get; private set; }

	public OVRHapticsClip()
	{
		Capacity = OVRHaptics.Config.MaximumBufferSamplesCount;
		Samples = new byte[Capacity * OVRHaptics.Config.SampleSizeInBytes];
	}

	public OVRHapticsClip(int capacity)
	{
		Capacity = ((capacity >= 0) ? capacity : 0);
		Samples = new byte[Capacity * OVRHaptics.Config.SampleSizeInBytes];
	}

	public OVRHapticsClip(byte[] samples, int samplesCount)
	{
		Samples = samples;
		Capacity = Samples.Length / OVRHaptics.Config.SampleSizeInBytes;
		Count = ((samplesCount >= 0) ? samplesCount : 0);
	}

	public OVRHapticsClip(OVRHapticsClip a, OVRHapticsClip b)
	{
		int count = a.Count;
		if (b.Count > count)
		{
			count = b.Count;
		}
		Capacity = count;
		Samples = new byte[Capacity * OVRHaptics.Config.SampleSizeInBytes];
		for (int i = 0; i < a.Count || i < b.Count; i++)
		{
			if (OVRHaptics.Config.SampleSizeInBytes == 1)
			{
				byte sample = 0;
				if (i < a.Count && i < b.Count)
				{
					sample = (byte)Mathf.Clamp(a.Samples[i] + b.Samples[i], 0, 255);
				}
				else if (i < a.Count)
				{
					sample = a.Samples[i];
				}
				else if (i < b.Count)
				{
					sample = b.Samples[i];
				}
				WriteSample(sample);
			}
		}
	}

	public OVRHapticsClip(AudioClip audioClip, int channel = 0)
	{
		float[] array = new float[audioClip.samples * audioClip.channels];
		audioClip.GetData(array, 0);
		InitializeFromAudioFloatTrack(array, audioClip.frequency, audioClip.channels, channel);
	}

	public void WriteSample(byte sample)
	{
		if (Count < Capacity)
		{
			if (OVRHaptics.Config.SampleSizeInBytes == 1)
			{
				Samples[Count * OVRHaptics.Config.SampleSizeInBytes] = sample;
			}
			Count++;
		}
	}

	public void Reset()
	{
		Count = 0;
	}

	private void InitializeFromAudioFloatTrack(float[] sourceData, double sourceFrequency, int sourceChannelCount, int sourceChannel)
	{
		double num = sourceFrequency / (double)OVRHaptics.Config.SampleRateHz;
		int num2 = (int)num;
		double num3 = num - (double)num2;
		double num4 = 0.0;
		int num5 = sourceData.Length;
		Count = 0;
		Capacity = num5 / sourceChannelCount / num2 + 1;
		Samples = new byte[Capacity * OVRHaptics.Config.SampleSizeInBytes];
		int num6 = sourceChannel % sourceChannelCount;
		while (num6 < num5)
		{
			if (OVRHaptics.Config.SampleSizeInBytes == 1)
			{
				WriteSample((byte)(Mathf.Clamp01(Mathf.Abs(sourceData[num6])) * 255f));
			}
			num6 += num2 * sourceChannelCount;
			num4 += num3;
			if ((int)num4 > 0)
			{
				num6 += (int)num4 * sourceChannelCount;
				num4 -= (double)(int)num4;
			}
		}
	}
}
