	public class MicrophoneInput : IMicrophone
	{
		private AudioClip microphoneClip;

		private int lastMicrophoneSample;

		private int micBufferSizeSamples;

		public MicrophoneInput()
		{
			int num = 1;
			int num2 = 48000;
			microphoneClip = Microphone.Start(null, loop: true, num, num2);
			micBufferSizeSamples = num * num2;
		}

		public void Start()
		{
		}

		public void Stop()
		{
		}

		public float[] Update()
		{
			int position = Microphone.GetPosition(null);
			if (position == 0 && lastMicrophoneSample == 0)
			{
				UnityEngine.Debug.LogWarning("Possible microphone error");
			}
			int num = 0;
			if (position < lastMicrophoneSample)
			{
				int num2 = micBufferSizeSamples - lastMicrophoneSample;
				num = num2 + position;
			}
			else
			{
				num = position - lastMicrophoneSample;
			}
			if (num == 0)
			{
				return null;
			}
			float[] array = new float[num];
			microphoneClip.GetData(array, lastMicrophoneSample);
			lastMicrophoneSample = position;
			return array;
		}
	}
	public class MicrophoneInputNative : IMicrophone
	{
		private IntPtr mic;

		private int tempBufferSize = 9600;

		private float[] tempBuffer;

		public MicrophoneInputNative()
		{
			mic = CAPI.ovr_Microphone_Create();
			CAPI.ovr_Microphone_Start(mic);
			tempBuffer = new float[tempBufferSize];
			UnityEngine.Debug.Log(mic);
		}

		public float[] Update()
		{
			ulong num = (ulong)CAPI.ovr_Microphone_ReadData(mic, tempBuffer, (UIntPtr)(ulong)tempBufferSize);
			if (num != 0)
			{
				float[] array = new float[num];
				Array.Copy(tempBuffer, array, (int)num);
				return array;
			}
			return null;
		}

		public void Start()
		{
		}

		public void Stop()
		{
			CAPI.ovr_Microphone_Stop(mic);
			CAPI.ovr_Microphone_Destroy(mic);
		}
	}
