		public void SendVoicesInfo(object content, int channelId, int targetPlayerId)
		{
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			if (targetPlayerId != 0)
			{
				raiseEventOptions.TargetActors = new int[1] { targetPlayerId };
			}
			else if (DebugEchoMode)
			{
				raiseEventOptions.Receivers = ExitGames.Client.Photon.LoadBalancing.ReceiverGroup.All;
			}
			OpRaiseEvent(201, content, sendReliable: true, raiseEventOptions);
		}

		public void SendVoiceRemove(object content, int channelId)
		{
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			if (DebugEchoMode)
			{
				raiseEventOptions.Receivers = ExitGames.Client.Photon.LoadBalancing.ReceiverGroup.All;
			}
			OpRaiseEvent(201, content, sendReliable: true, raiseEventOptions);
		}

		public void SendFrame(object content, int channelId, byte audioGroup)
		{
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			if (DebugEchoMode)
			{
				raiseEventOptions.Receivers = ExitGames.Client.Photon.LoadBalancing.ReceiverGroup.All;
			}
			raiseEventOptions.InterestGroup = audioGroup;
			OpRaiseEvent(201, content, sendReliable: false, raiseEventOptions);
			loadBalancingPeer.SendOutgoingCommands();
		}

		public string ChannelIdStr(int channelId)
		{
			return null;
		}

		public string PlayerIdStr(int playerId)
		{
			return null;
		}

		private void onEventActionVoiceClient(EventData ev)
		{
			switch (ev.Code)
			{
			case byte.MaxValue:
			{
				int num = (int)ev[254];
				if (num == base.LocalPlayer.ID)
				{
					voiceClient.clearRemoteVoices();
					voiceClient.sendChannelVoicesInfo(1, 0);
					if (voiceClient.GlobalAudioGroup != 0)
					{
						loadBalancingPeer.OpChangeGroups(new byte[0], new byte[1] { voiceClient.GlobalAudioGroup });
					}
				}
				else
				{
					voiceClient.sendChannelVoicesInfo(1, num);
				}
				break;
			}
			case 254:
			{
				int num = (int)ev[254];
				if (num == base.LocalPlayer.ID)
				{
					voiceClient.clearRemoteVoices();
				}
				else
				{
					onPlayerLeave(num);
				}
				break;
			}
			case 201:
				voiceClient.onVoiceEvent(ev[245], 1, (int)ev[254], base.LocalPlayer.ID);
				break;
			}
			if (OnEventAction != null)
			{
				OnEventAction(ev);
			}
		}

		private void onPlayerLeave(int playerId)
		{
			if (voiceClient.removePlayerVoices(1, playerId))
			{
				DebugReturn(DebugLevel.INFO, "[PV] Player " + playerId + " voices removed on leave");
			}
			else
			{
				DebugReturn(DebugLevel.WARNING, "[PV] Voices of player " + playerId + " not found when trying to remove on player leave");
			}
		}
	}
}
internal class AudioClipWrapper : IAudioStream
{
	private AudioClip audioClip;

	private int readPos;

	private float startTime;

	private bool playing = true;

	public int SamplingRate => audioClip.frequency;

	public bool Loop { get; set; }

	public AudioClipWrapper(AudioClip audioClip)
	{
		this.audioClip = audioClip;
		startTime = Time.time;
	}

	public bool GetData(float[] buffer)
	{
		if (!playing)
		{
			return false;
		}
		int num = (int)((Time.time - startTime) * (float)audioClip.frequency);
		int num2 = buffer.Length / audioClip.channels;
		if (num > readPos + num2)
		{
			audioClip.GetData(buffer, readPos);
			readPos += num2;
			if (readPos >= audioClip.samples)
			{
				if (Loop)
				{
					readPos = 0;
					startTime = Time.time;
				}
				else
				{
					playing = false;
				}
			}
			return true;
		}
		return false;
	}
}
public class AudioStreamPlayer
{
	private const int maxPlayLagMs = 100;

	private int maxPlayLagSamples;

	private int playDelaySamples;

	private int frameSize;

	private int frameSamples;

	private int streamSamplePos;

	private int streamSamplePosAvg;

	private AudioSource source;

	private string logPrefix;

	private bool debugInfo;

	private int sourceTimeSamplesPrev;

	private int playLoopCount;

	public int CurrentBufferLag { get; private set; }

	public AudioSource AudioSource => source;

	private int playSamplePos
	{
		get
		{
			return (source.clip != null) ? (playLoopCount * source.clip.samples + source.timeSamples) : 0;
		}
		set
		{
			if (source.clip != null)
			{
				int num = value % source.clip.samples;
				if (num < 0)
				{
					num += source.clip.samples;
				}
				source.timeSamples = num;
				playLoopCount = value / source.clip.samples;
				sourceTimeSamplesPrev = source.timeSamples;
			}
		}
	}

	public bool IsPlaying => source.isPlaying;

	public bool IsStarted => source.clip != null;

	public AudioStreamPlayer(AudioSource audioSource, string logPrefix, bool debugInfo)
	{
		source = audioSource;
		this.logPrefix = logPrefix;
		this.debugInfo = debugInfo;
	}

	internal void Start(int frequency, int channels, int frameSamples, int playDelayMs)
	{
		int lengthSamples = (100 + playDelayMs) * frequency / 1000 + frameSamples + frequency;
		this.frameSamples = frameSamples;
		frameSize = frameSamples * channels;
		maxPlayLagSamples = 100 * frequency / 1000 + this.frameSamples;
		playDelaySamples = playDelayMs * frequency / 1000 + this.frameSamples;
		CurrentBufferLag = playDelaySamples;
		streamSamplePosAvg = playDelaySamples;
		source.loop = true;
		source.clip = AudioClip.Create("AudioStreamPlayer", lengthSamples, channels, frequency, stream: false);
		streamSamplePos = 0;
		playSamplePos = 0;
		source.Play();
		source.Pause();
	}

	public void Update()
	{
		if (!(source.clip != null))
		{
			return;
		}
		if (source.isPlaying)
		{
			if (source.timeSamples < sourceTimeSamplesPrev)
			{
				playLoopCount++;
			}
			sourceTimeSamplesPrev = source.timeSamples;
		}
		int num = playSamplePos;
		CurrentBufferLag = (CurrentBufferLag * 39 + (streamSamplePos - num)) / 40;
		streamSamplePosAvg = num + CurrentBufferLag;
		if (streamSamplePosAvg > streamSamplePos)
		{
			streamSamplePosAvg = streamSamplePos;
		}
		if (num < streamSamplePos - playDelaySamples && !source.isPlaying)
		{
			source.UnPause();
		}
		if (num > streamSamplePos - frameSamples && source.isPlaying)
		{
			if (debugInfo)
			{
				UnityEngine.Debug.LogWarningFormat("{0} player overrun: {1}/{2}({3}) = {4}", logPrefix, num, streamSamplePos, streamSamplePosAvg, streamSamplePos - num);
			}
			source.Pause();
			num = (playSamplePos = streamSamplePos - playDelaySamples);
			CurrentBufferLag = playDelaySamples;
		}
		if (!source.isPlaying)
		{
			return;
		}
		int num3 = streamSamplePos - playDelaySamples - maxPlayLagSamples;
		if (num < num3)
		{
			if (debugInfo)
			{
				UnityEngine.Debug.LogWarningFormat("{0} player underrun: {1}/{2}({3}) = {4}", logPrefix, num, streamSamplePos, streamSamplePosAvg, streamSamplePos - num);
			}
			num = streamSamplePos - playDelaySamples;
			playSamplePos = num;
			CurrentBufferLag = playDelaySamples;
		}
	}

	internal void OnAudioFrame(float[] frame)
	{
		if (frame.Length != 0)
		{
			if (frame.Length != frameSize)
			{
				UnityEngine.Debug.LogErrorFormat("{0} Audio frames are not of  size: {1} != {2}", logPrefix, frame.Length, frameSize);
			}
			else
			{
				source.clip.SetData(frame, streamSamplePos % source.clip.samples);
				streamSamplePos += frame.Length / source.clip.channels;
			}
		}
	}

	public void Stop()
	{
		source.Stop();
		source.clip = null;
	}

	public void Pause()
	{
		if ((bool)source)
		{
			source.Pause();
		}
	}
}
internal class MicWrapper : IAudioStream
{
	private AudioClip mic;

	private string device;

	private int micPrevPos;

	private int micLoopCnt;

	private int readAbsPos;

	public int SamplingRate => mic.frequency;

	public int Channels => mic.channels;

	public MicWrapper(string device, int suggestedFrequency)
	{
		if (Microphone.devices.Length >= 1)
		{
			this.device = device;
			Microphone.GetDeviceCaps(device, out var minFreq, out var maxFreq);
			int suggestedFrequency2 = suggestedFrequency;
			if (suggestedFrequency < minFreq || (maxFreq != 0 && suggestedFrequency > maxFreq))
			{
				UnityEngine.Debug.LogWarningFormat("PUNVoice: MicWrapper does not support suggested frequency {0} (min: {1}, max: {2}). Setting to {2}", suggestedFrequency, minFreq, maxFreq);
				suggestedFrequency2 = maxFreq;
			}
			mic = SharedMicrophone.GetMicrophone(device, suggestedFrequency2);
		}
	}

	public bool GetData(float[] buffer)
	{
		int position = Microphone.GetPosition(device);
		if (position < micPrevPos)
		{
			micLoopCnt++;
		}
		micPrevPos = position;
		int num = micLoopCnt * mic.samples + position;
		int num2 = buffer.Length / mic.channels;
		int num3 = readAbsPos + num2;
		if (num3 < num)
		{
			mic.GetData(buffer, readAbsPos % mic.samples);
			readAbsPos = num3;
			return true;
		}
		return false;
	}
}
public class PhotonVoiceNetwork : UnityEngine.MonoBehaviour
{
	private static PhotonVoiceNetwork _instance;

	private static GameObject _singleton;

	private static object instanceLock = new object();

	private static bool destroyed = false;

	internal UnityVoiceFrontend client;

	private static string microphoneDevice = null;

	internal static PhotonVoiceNetwork instance => getInstance();

	public static UnityVoiceFrontend Client => instance.client;

	public static ExitGames.Client.Photon.LoadBalancing.ClientState ClientState => instance.client.State;

	public static string CurrentRoomName => (instance.client.CurrentRoom != null) ? instance.client.CurrentRoom.Name : string.Empty;

	public static string MicrophoneDevice
	{
		get
		{
			return microphoneDevice;
		}
		set
		{
			if (value != null && !Microphone.devices.Contains(value))
			{
				UnityEngine.Debug.LogError("PUNVoice: " + value + " is not a valid microphone device");
				return;
			}
			microphoneDevice = value;
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.LogFormat("PUNVoice: Setting global microphone device to {0}", microphoneDevice);
			}
			PhotonVoiceRecorder[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceRecorder>();
			foreach (PhotonVoiceRecorder photonVoiceRecorder in array)
			{
				if (photonVoiceRecorder.photonView.isMine && photonVoiceRecorder.MicrophoneDevice == null)
				{
					photonVoiceRecorder.MicrophoneDevice = null;
				}
			}
		}
	}

	private PhotonVoiceNetwork()
	{
		client = new UnityVoiceFrontend(this);
	}

	internal static PhotonVoiceNetwork getInstance()
	{
		lock (instanceLock)
		{
			if (destroyed)
			{
				return null;
			}
			if (_instance == null)
			{
				_singleton = new GameObject();
				_instance = _singleton.AddComponent<PhotonVoiceNetwork>();
				_singleton.name = "PhotonVoiceNetworkSingleton";
				UnityEngine.Object.DontDestroyOnLoad(_singleton);
			}
			return _instance;
		}
	}

	private void OnDestroy()
	{
		if (!(this != _instance))
		{
			destroyed = true;
		}
	}

	[RuntimeInitializeOnLoadMethod]
	public static void RuntimeInitializeOnLoad()
	{
		getInstance();
	}

	public void Awake()
	{
		if (Microphone.devices.Length < 1)
		{
			UnityEngine.Debug.LogError("PUNVoice: No microphone device found");
		}
	}

	public static bool Connect()
	{
		instance.client.AppId = PhotonNetwork.PhotonServerSettings.VoiceAppID;
		instance.client.AppVersion = "1.0";
		if (PhotonNetwork.PhotonServerSettings.HostType == ServerSettings.HostingOption.SelfHosted)
		{
			string masterServerAddress = $"{PhotonNetwork.PhotonServerSettings.ServerAddress}:{PhotonNetwork.PhotonServerSettings.VoiceServerPort}";
			return instance.client.Connect(masterServerAddress, null, null, null, null);
		}
		return instance.client.ConnectToRegionMaster(PhotonNetwork.networkingPeer.CloudRegion.ToString());
	}

	public static void Disconnect()
	{
		instance.client.Disconnect();
	}

	protected void OnEnable()
	{
		if (!(this != _instance))
		{
			UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
		}
	}

	protected void OnApplicationQuit()
	{
		if (!(this != _instance))
		{
			client.Disconnect();
		}
	}

	protected void Update()
	{
		if (!(this != _instance))
		{
			client.DebugLostPercent = PhotonVoiceSettings.Instance.DebugLostPercent;
			client.Service();
		}
	}

	public static LocalVoice CreateLocalVoice(IAudioStream audioClip, VoiceInfo voiceInfo)
	{
		return instance.client.CreateLocalVoice(audioClip, voiceInfo);
	}

	public static void RemoveLocalVoice(LocalVoice voice)
	{
		if (!destroyed)
		{
			instance.client.RemoveLocalVoice(voice);
		}
	}

	private void OnJoinedRoom()
	{
		if (this != _instance)
		{
			return;
		}
		ExitGames.Client.Photon.LoadBalancing.ClientState state = client.State;
		if (state == ExitGames.Client.Photon.LoadBalancing.ClientState.Joined)
		{
			if (PhotonVoiceSettings.Instance.AutoConnect)
			{
				client.OpLeaveRoom();
			}
		}
		else if (PhotonVoiceSettings.Instance.AutoConnect)
		{
			client.Reconnect();
		}
	}

	private void OnLeftRoom()
	{
		if (!(this != _instance) && PhotonVoiceSettings.Instance.AutoDisconnect)
		{
			client.Disconnect();
		}
	}

	private void OnDisconnectedFromPhoton()
	{
		if (!(this != _instance) && PhotonVoiceSettings.Instance.AutoDisconnect)
		{
			client.Disconnect();
		}
	}

	internal static void LinkSpeakerToRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		instance.client.LinkSpeakerToRemoteVoice(speaker);
	}

	internal static void UnlinkSpeakerFromRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		if (!destroyed)
		{
			instance.client.UnlinkSpeakerFromRemoteVoice(speaker);
		}
	}
}
public class UnityVoiceFrontend : LoadBalancingFrontend
{
	private Dictionary<KeyValuePair<int, byte>, PhotonVoiceSpeaker> voiceSpeakers = new Dictionary<KeyValuePair<int, byte>, PhotonVoiceSpeaker>();

	private bool reconnect;

	public new Action<int, byte, VoiceInfo> OnRemoteVoiceInfoAction { get; set; }

	public new Action<int, byte> OnRemoteVoiceRemoveAction { get; set; }

	public new Action<int, byte, float[]> OnAudioFrameAction { get; set; }

	public new Action<ExitGames.Client.Photon.LoadBalancing.ClientState> OnStateChangeAction { get; set; }

	public new Action<OperationResponse> OnOpResponseAction { get; set; }

	internal UnityVoiceFrontend(PhotonVoiceNetwork network)
	{
		base.OnRemoteVoiceInfoAction = (Action<int, int, byte, VoiceInfo>)Delegate.Combine(base.OnRemoteVoiceInfoAction, new Action<int, int, byte, VoiceInfo>(OnRemoteVoiceInfo));
		base.OnRemoteVoiceRemoveAction = (Action<int, int, byte>)Delegate.Combine(base.OnRemoteVoiceRemoveAction, new Action<int, int, byte>(OnRemoteVoiceRemove));
		base.OnAudioFrameAction = (Action<int, int, byte, float[]>)Delegate.Combine(base.OnAudioFrameAction, new Action<int, int, byte, float[]>(OnAudioFrame));
		base.OnStateChangeAction += OnStateChange;
		base.OnOpResponseAction += OnOpResponse;
		loadBalancingPeer.DebugOut = DebugLevel.INFO;
	}

	public void Reconnect()
	{
		if (base.State == ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected)
		{
			PhotonVoiceNetwork.Connect();
			return;
		}
		reconnect = true;
		Disconnect();
	}

	public override void DebugReturn(DebugLevel level, string message)
	{
		message = $"PUNVoice: {message}";
		if (level == DebugLevel.ERROR)
		{
			UnityEngine.Debug.LogError(message);
		}
	}

	public void OnOpResponse(OperationResponse resp)
	{
		if (resp.ReturnCode == 0)
		{
			byte operationCode = resp.OperationCode;
			if (operationCode == 226)
			{
				PhotonVoiceRecorder[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceRecorder>();
				PhotonVoiceRecorder[] array2 = array;
				foreach (PhotonVoiceRecorder photonVoiceRecorder in array2)
				{
					photonVoiceRecorder.SendMessage("OnJoinedVoiceRoom");
				}
			}
		}
		if (OnOpResponseAction != null)
		{
			OnOpResponseAction(resp);
		}
	}

	private void linkVoice(int playerId, byte voiceId, VoiceInfo voiceInfo, PhotonVoiceSpeaker speaker)
	{
		speaker.OnVoiceLinked(voiceInfo.SamplingRate, voiceInfo.Channels, voiceInfo.FrameDurationSamples, PhotonVoiceSettings.Instance.PlayDelayMs);
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (voiceSpeakers.TryGetValue(key, out var value))
		{
			if (value == speaker)
			{
				return;
			}
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice #{1} speaker replaced.", playerId, voiceId);
			}
		}
		else if (PhotonVoiceSettings.Instance.DebugInfo)
		{
			UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice #{1} speaker created.", playerId, voiceId);
		}
		voiceSpeakers[key] = speaker;
	}

	public void OnRemoteVoiceInfo(int channelId, int playerId, byte voiceId, VoiceInfo voiceInfo)
	{
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (voiceSpeakers.ContainsKey(key))
		{
			UnityEngine.Debug.LogWarningFormat("PUNVoice: Info duplicate for voice #{0} of player {1}", voiceId, playerId);
		}
		PhotonVoiceSpeaker photonVoiceSpeaker = null;
		PhotonVoiceSpeaker[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceSpeaker>();
		PhotonVoiceSpeaker[] array2 = array;
		foreach (PhotonVoiceSpeaker photonVoiceSpeaker2 in array2)
		{
			if (photonVoiceSpeaker2.photonView.viewID == (int)voiceInfo.UserData)
			{
				photonVoiceSpeaker = photonVoiceSpeaker2;
				break;
			}
		}
		if (!(photonVoiceSpeaker == null))
		{
			linkVoice(playerId, voiceId, voiceInfo, photonVoiceSpeaker);
		}
		if (OnRemoteVoiceInfoAction != null)
		{
			OnRemoteVoiceInfoAction(playerId, voiceId, voiceInfo);
		}
	}

	public void LinkSpeakerToRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		foreach (RemoteVoiceInfo remoteVoiceInfo in base.RemoteVoiceInfos)
		{
			if (speaker.photonView.viewID == (int)remoteVoiceInfo.Info.UserData)
			{
				linkVoice(remoteVoiceInfo.PlayerId, remoteVoiceInfo.VoiceId, remoteVoiceInfo.Info, speaker);
			}
		}
	}

	public void OnRemoteVoiceRemove(int channelId, int playerId, byte voiceId)
	{
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (!unlinkSpeaker(key))
		{
			UnityEngine.Debug.LogWarningFormat("PUNVoice: Voice #{0} of player {1} not found.", voiceId, playerId);
		}
		else if (PhotonVoiceSettings.Instance.DebugInfo)
		{
			UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice # {1} speaker unlinked.", playerId, voiceId);
		}
		if (OnRemoteVoiceRemoveAction != null)
		{
			OnRemoteVoiceRemoveAction(playerId, voiceId);
		}
	}

	private bool unlinkSpeaker(KeyValuePair<int, byte> key)
	{
		if (voiceSpeakers.TryGetValue(key, out var value))
		{
			value.OnVoiceUnlinked();
		}
		return voiceSpeakers.Remove(key);
	}

	public void UnlinkSpeakerFromRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		List<KeyValuePair<int, byte>> list = new List<KeyValuePair<int, byte>>();
		foreach (KeyValuePair<KeyValuePair<int, byte>, PhotonVoiceSpeaker> voiceSpeaker in voiceSpeakers)
		{
			if (voiceSpeaker.Value == speaker)
			{
				list.Add(voiceSpeaker.Key);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice # {1} speaker unlinked.", voiceSpeaker.Key.Key, voiceSpeaker.Key.Value);
				}
			}
		}
		foreach (KeyValuePair<int, byte> item in list)
		{
			unlinkSpeaker(item);
		}
	}

	public void OnAudioFrame(int channelId, int playerId, byte voiceId, float[] frame)
	{
		PhotonVoiceSpeaker value = null;
		if (voiceSpeakers.TryGetValue(new KeyValuePair<int, byte>(playerId, voiceId), out value))
		{
			value.OnAudioFrame(frame);
		}
		else
		{
			UnityEngine.Debug.LogWarningFormat("PUNVoice: Audio Frame event for not existing speaker for voice #{0} of player {1}.", voiceId, playerId);
		}
		if (OnAudioFrameAction != null)
		{
			OnAudioFrameAction(playerId, voiceId, frame);
		}
	}

	public void OnStateChange(ExitGames.Client.Photon.LoadBalancing.ClientState state)
	{
		if (PhotonNetwork.logLevel >= PhotonLogLevel.Informational)
		{
			UnityEngine.Debug.LogFormat("PUNVoice: Voice Client state: {0}", state);
		}
		switch (state)
		{
		case ExitGames.Client.Photon.LoadBalancing.ClientState.JoinedLobby:
			if (PhotonNetwork.inRoom)
			{
				OpJoinOrCreateRoom($"{PhotonNetwork.room.name}_voice_", new ExitGames.Client.Photon.LoadBalancing.RoomOptions
				{
					IsVisible = false
				}, null);
			}
			else
			{
				UnityEngine.Debug.LogWarning("PUNVoice: PUN client is not in room yet. Disconnecting voice client.");
				Disconnect();
			}
			break;
		case ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected:
			if (reconnect)
			{
				PhotonVoiceNetwork.Connect();
			}
			reconnect = false;
			break;
		}
		if (OnStateChangeAction != null)
		{
			OnStateChangeAction(state);
		}
	}
}
[RequireComponent(typeof(PhotonVoiceSpeaker))]
[DisallowMultipleComponent]
public class PhotonVoiceRecorder : Photon.MonoBehaviour
{
	private LocalVoice voice = LocalVoice.Dummy;

	private string microphoneDevice;

	public AudioClip AudioClip;

	public bool LoopAudioClip = true;

	private string log0;

	private string log1;

	public VoiceDetector VoiceDetector => (!base.photonView.isMine) ? null : voice.VoiceDetector;

	public string MicrophoneDevice
	{
		get
		{
			return microphoneDevice;
		}
		set
		{
			if (value != null && !Microphone.devices.Contains(value))
			{
				UnityEngine.Debug.LogError("PUNVoice: " + value + " is not a valid microphone device");
				return;
			}
			microphoneDevice = value;
			if (voice != LocalVoice.Dummy && AudioClip == null)
			{
				PhotonVoiceSettings instance = PhotonVoiceSettings.Instance;
				UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
				string text = ((MicrophoneDevice == null) ? PhotonVoiceNetwork.MicrophoneDevice : MicrophoneDevice);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.LogFormat("PUNVoice: Setting recorder's microphone device to {0}", text);
				}
				MicWrapper micWrapper = new MicWrapper(text, (int)instance.SamplingRate);
				bool debugEchoMode = PhotonVoiceNetwork.Client.DebugEchoMode;
				PhotonVoiceNetwork.Client.DebugEchoMode = false;
				VoiceInfo voiceInfo = new VoiceInfo((int)instance.SamplingRate, micWrapper.Channels, (int)instance.FrameDuration, instance.Bitrate, base.photonView.viewID);
				PhotonVoiceNetwork.RemoveLocalVoice(voice);
				LocalVoice localVoice = voice;
				voice = PhotonVoiceNetwork.CreateLocalVoice(micWrapper, voiceInfo);
				voice.AudioGroup = localVoice.AudioGroup;
				voice.Transmit = localVoice.Transmit;
				voice.VoiceDetector.On = localVoice.VoiceDetector.On;
				voice.VoiceDetector.Threshold = localVoice.VoiceDetector.Threshold;
				PhotonVoiceNetwork.Client.DebugEchoMode = debugEchoMode;
			}
		}
	}

	public byte AudioGroup
	{
		get
		{
			return voice.AudioGroup;
		}
		set
		{
			voice.AudioGroup = value;
		}
	}

	public bool IsTransmitting => voice.IsTransmitting;

	public LevelMeter LevelMeter => voice.LevelMeter;

	public bool Transmit
	{
		get
		{
			return voice.Transmit;
		}
		set
		{
			voice.Transmit = value;
		}
	}

	public bool Detect
	{
		get
		{
			return voice.VoiceDetector.On;
		}
		set
		{
			voice.VoiceDetector.On = value;
		}
	}

	public bool VoiceDetectorCalibrating => voice.VoiceDetectorCalibrating;

	private void Start()
	{
		if (Microphone.devices.Length < 1)
		{
			return;
		}
		if (base.photonView.isMine)
		{
			PhotonVoiceSettings instance = PhotonVoiceSettings.Instance;
			if (MicrophoneDevice == null && PhotonVoiceNetwork.MicrophoneDevice == null)
			{
				UnityEngine.Debug.LogWarning("PUNVoice : PhotonVoiceRecorder is disabled since we do not have a microphone.");
				base.enabled = false;
				return;
			}
			UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
			int num = 0;
			IAudioStream audioStream;
			if (AudioClip == null)
			{
				string text = ((MicrophoneDevice == null) ? PhotonVoiceNetwork.MicrophoneDevice : MicrophoneDevice);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.LogFormat("PUNVoice: Setting recorder's microphone device to {0}", text);
				}
				MicWrapper micWrapper = new MicWrapper(text, (int)instance.SamplingRate);
				num = micWrapper.Channels;
				audioStream = micWrapper;
			}
			else
			{
				audioStream = new AudioClipWrapper(AudioClip);
				num = AudioClip.channels;
				if (LoopAudioClip)
				{
					((AudioClipWrapper)audioStream).Loop = true;
				}
			}
			VoiceInfo voiceInfo = new VoiceInfo((int)instance.SamplingRate, num, (int)instance.FrameDuration, instance.Bitrate, base.photonView.viewID);
			voice = PhotonVoiceNetwork.CreateLocalVoice(audioStream, voiceInfo);
			VoiceDetector.On = PhotonVoiceSettings.Instance.VoiceDetection;
			VoiceDetector.Threshold = PhotonVoiceSettings.Instance.VoiceDetectionThreshold;
			if (voice != LocalVoice.Dummy)
			{
				voice.Transmit = PhotonVoiceSettings.Instance.AutoTransmit && SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.AlwaysOn;
			}
			else if (PhotonVoiceSettings.Instance.AutoTransmit)
			{
				UnityEngine.Debug.LogWarning("PUNVoice: Cannot Transmit.");
			}
		}
		else
		{
			base.enabled = false;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (voice != LocalVoice.Dummy)
		{
			PhotonVoiceNetwork.RemoveLocalVoice(voice);
		}
	}

	private void OnEnable()
	{
		UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
	}

	private void OnJoinedVoiceRoom()
	{
	}

	public void VoiceDetectorCalibrate(int durationMs)
	{
		if (base.photonView.isMine)
		{
			voice.VoiceDetectorCalibrate(durationMs);
		}
	}

	private string tostr<T>(T[] x, int lim = 10)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < ((x.Length >= lim) ? lim : x.Length); i++)
		{
			stringBuilder.Append("-");
			stringBuilder.Append(x[i]);
		}
		return stringBuilder.ToString();
	}

	public string ToStringFull()
	{
		int minFreq = 0;
		int maxFreq = 0;
		Microphone.GetDeviceCaps(MicrophoneDevice, out minFreq, out maxFreq);
		return $"Mic '{MicrophoneDevice}': {minFreq}..{maxFreq} Hz";
	}
}
public class PhotonVoiceSettings : UnityEngine.MonoBehaviour
{
	public bool AutoConnect = true;

	public bool AutoDisconnect;

	public bool AutoTransmit = true;

	public SamplingRate SamplingRate = SamplingRate.Sampling24000;

	public FrameDuration FrameDuration = FrameDuration.Frame20ms;

	public int Bitrate = 30000;

	public bool VoiceDetection;

	public float VoiceDetectionThreshold = 0.01f;

	public int PlayDelayMs = 200;

	public int DebugLostPercent;

	public bool DebugInfo;

	private static PhotonVoiceSettings instance;

	private static object instanceLock = new object();

	public static PhotonVoiceSettings Instance
	{
		get
		{
			if (instance == null)
			{
				instance = PhotonVoiceNetwork.instance.gameObject.AddComponent<PhotonVoiceSettings>();
			}
			return instance;
		}
	}

	private void Awake()
	{
		lock (instanceLock)
		{
			if (instance == null)
			{
				instance = this;
			}
			else
			{
				UnityEngine.Debug.LogError("PUNVoice: Attempt to create multiple instances of PhotonVoiceSettings");
			}
		}
	}
}
[RequireComponent(typeof(AudioSource))]
[DisallowMultipleComponent]
public class PhotonVoiceSpeaker : Photon.MonoBehaviour
{
	private AudioStreamPlayer player;

	public float LastRecvTime { get; private set; }

	public bool IsPlaying => player.IsPlaying;

	public int CurrentBufferLag => player.CurrentBufferLag;

	public bool IsVoiceLinked => player != null && player.IsStarted;

	public bool IsVoiceDetected { get; private set; }

	public float MaxAudioSample { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		player = new AudioStreamPlayer(GetComponent<AudioSource>(), "PUNVoice: PhotonVoiceSpeaker:", PhotonVoiceSettings.Instance.DebugInfo);
		PhotonVoiceNetwork.LinkSpeakerToRemoteVoice(this);
	}

	internal void OnVoiceLinked(int frequency, int channels, int frameSamplesPerChannel, int playDelayMs)
	{
		player.Start(frequency, channels, frameSamplesPerChannel, playDelayMs);
	}

	public void Pause()
	{
		player.Pause();
	}

	internal void OnVoiceUnlinked()
	{
		player.Stop();
	}

	private void Update()
	{
		player.Update();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		PhotonVoiceNetwork.UnlinkSpeakerFromRemoteVoice(this);
		player.Stop();
	}

	private void OnApplicationQuit()
	{
		player.Stop();
	}

	internal void OnAudioFrame(float[] frame)
	{
		LastRecvTime = Time.time;
		player.OnAudioFrame(frame);
		float num = 0f;
		foreach (float f in frame)
		{
			num = Mathf.Max(Mathf.Abs(f), num);
		}
		IsVoiceDetected = num > PhotonVoiceSettings.Instance.VoiceDetectionThreshold;
		MaxAudioSample = num;
	}
}
namespace ExitGames.Client.Photon.Chat
{
	public class ChatChannel
	{
		public readonly string Name;

		public readonly List<string> Senders = new List<string>();

		public readonly List<object> Messages = new List<object>();

		public int MessageLimit;

		public bool IsPrivate { get; protected internal set; }

		public int MessageCount => Messages.Count;

		public ChatChannel(string name)
		{
			Name = name;
		}

		public void Add(string sender, object message)
		{
			Senders.Add(sender);
			Messages.Add(message);
			TruncateMessages();
		}

		public void Add(string[] senders, object[] messages)
		{
			Senders.AddRange(senders);
			Messages.AddRange(messages);
			TruncateMessages();
		}

		public void TruncateMessages()
		{
			if (MessageLimit > 0 && Messages.Count > MessageLimit)
			{
				int count = Messages.Count - MessageLimit;
				Senders.RemoveRange(0, count);
				Messages.RemoveRange(0, count);
			}
		}

		public void ClearMessages()
		{
			Senders.Clear();
			Messages.Clear();
		}

		public string ToStringMessages()
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < Messages.Count; i++)
			{
				stringBuilder.AppendLine($"{Senders[i]}: {Messages[i]}");
			}
			return stringBuilder.ToString();
		}
	}
	public class ChatClient : IPhotonPeerListener
	{
		private const int FriendRequestListMax = 1024;

		private string chatRegion = "EU";

		public int MessageLimit;

		public readonly Dictionary<string, ChatChannel> PublicChannels;

		public readonly Dictionary<string, ChatChannel> PrivateChannels;

		private readonly HashSet<string> PublicChannelsUnsubscribing;

		private readonly IChatClientListener listener;

		public ChatPeer chatPeer;

		private bool didAuthenticate;

		private int msDeltaForServiceCalls = 50;

		private int msTimestampOfLastServiceCall;

		private const string ChatAppName = "chat";

		public string NameServerAddress { get; private set; }

		public string FrontendAddress { get; private set; }

		public string ChatRegion
		{
			get
			{
				return chatRegion;
			}
			set
			{
				chatRegion = value;
			}
		}

		public ChatState State { get; private set; }

		public ChatDisconnectCause DisconnectedCause { get; private set; }

		public bool CanChat => State == ChatState.ConnectedToFrontEnd && HasPeer;

		private bool HasPeer => chatPeer != null;

		public string AppVersion { get; private set; }

		public string AppId { get; private set; }

		public AuthenticationValues AuthValues { get; set; }

		public string UserId
		{
			get
			{
				return (AuthValues == null) ? null : AuthValues.UserId;
			}
			private set
			{
				if (AuthValues == null)
				{
					AuthValues = new AuthenticationValues();
				}
				AuthValues.UserId = value;
			}
		}

		public DebugLevel DebugOut
		{
			get
			{
				return chatPeer.DebugOut;
			}
			set
			{
				chatPeer.DebugOut = value;
			}
		}

		public ChatClient(IChatClientListener listener, ConnectionProtocol protocol = ConnectionProtocol.Udp)
		{
			this.listener = listener;
			State = ChatState.Uninitialized;
			chatPeer = new ChatPeer(this, protocol);
			PublicChannels = new Dictionary<string, ChatChannel>();
			PrivateChannels = new Dictionary<string, ChatChannel>();
			PublicChannelsUnsubscribing = new HashSet<string>();
		}

		public bool CanChatInChannel(string channelName)
		{
			return CanChat && PublicChannels.ContainsKey(channelName) && !PublicChannelsUnsubscribing.Contains(channelName);
		}

		public bool Connect(string appId, string appVersion, AuthenticationValues authValues)
		{
			chatPeer.TimePingInterval = 3000;
			DisconnectedCause = ChatDisconnectCause.None;
			if (authValues != null)
			{
				AuthValues = authValues;
				if (AuthValues.UserId == null || AuthValues.UserId == string.Empty)
				{
					if ((int)DebugOut >= 1)
					{
						listener.DebugReturn(DebugLevel.ERROR, "Connect failed: no UserId specified in authentication values");
					}
					return false;
				}
				AppId = appId;
				AppVersion = appVersion;
				didAuthenticate = false;
				msDeltaForServiceCalls = 100;
				chatPeer.QuickResendAttempts = 2;
				chatPeer.SentCountAllowance = 7;
				PublicChannels.Clear();
				PrivateChannels.Clear();
				PublicChannelsUnsubscribing.Clear();
				NameServerAddress = chatPeer.NameServerAddress;
				bool flag = chatPeer.Connect();
				if (flag)
				{
					State = ChatState.ConnectingToNameServer;
				}
				return flag;
			}
			if ((int)DebugOut >= 1)
			{
				listener.DebugReturn(DebugLevel.ERROR, "Connect failed: no authentication values specified");
			}
			return false;
		}

		public void Service()
		{
			if (HasPeer && (Environment.TickCount - msTimestampOfLastServiceCall > msDeltaForServiceCalls || msTimestampOfLastServiceCall == 0))
			{
				msTimestampOfLastServiceCall = Environment.TickCount;
				chatPeer.Service();
			}
		}

		public void Disconnect()
		{
			if (HasPeer && chatPeer.PeerState != PeerStateValue.Disconnected)
			{
				chatPeer.Disconnect();
			}
		}

		public void StopThread()
		{
			if (HasPeer)
			{
				chatPeer.StopThread();
			}
		}

		public bool Subscribe(string[] channels)
		{
			return Subscribe(channels, 0);
		}

		public bool Subscribe(string[] channels, int messagesFromHistory)
		{
			if (!CanChat)
			{
				if ((int)DebugOut >= 1)
				{
					listener.DebugReturn(DebugLevel.ERROR, "Subscribe called while not connected to front end server.");
				}
				return false;
			}
			if (channels == null || channels.Length == 0)
			{
				if ((int)DebugOut >= 2)
				{
					listener.DebugReturn(DebugLevel.WARNING, "Subscribe can't be called for empty or null channels-list.");
				}
				return false;
			}
			return SendChannelOperation(channels, 0, messagesFromHistory);
		}

		public bool Unsubscribe(string[] channels)
		{
			if (!CanChat)
			{
				if ((int)DebugOut >= 1)
				{
					listener.DebugReturn(DebugLevel.ERROR, "Unsubscribe called while not connected to front end server.");
				}
				return false;
			}
			if (channels == null || channels.Length == 0)
			{
				if ((int)DebugOut >= 2)
				{
					listener.DebugReturn(DebugLevel.WARNING, "Unsubscribe can't be called for empty or null channels-list.");
				}
				return false;
			}
			foreach (string item in channels)
			{
				PublicChannelsUnsubscribing.Add(item);
			}
			return SendChannelOperation(channels, 1, 0);
		}

		public bool PublishMessage(string channelName, object message)
		{
			return publishMessage(channelName, message, reliable: true);
		}

		internal bool PublishMessageUnreliable(string channelName, object message)
		{
			return publishMessage(channelName, message, reliable: false);
		}

		private bool publishMessage(string channelName, object message, bool reliable)
		{
			if (!CanChat)
			{
				if ((int)DebugOut >= 1)
				{
					listener.DebugReturn(DebugLevel.ERROR, "PublishMessage called while not connected to front end server.");
				}
				return false;
			}
			if (string.IsNullOrEmpty(channelName) || message == null)
			{
				if ((int)DebugOut >= 2)
				{
					listener.DebugReturn(DebugLevel.WARNING, "PublishMessage parameters must be non-null and not empty.");
				}
				return false;
			}
			Dictionary<byte, object> dictionary = new Dictionary<byte, object>();
			dictionary.Add(1, channelName);
			dictionary.Add(3, message);
			Dictionary<byte, object> customOpParameters = dictionary;
			return chatPeer.OpCustom(2, customOpParameters, reliable);
		}

		public bool SendPrivateMessage(string target, object message)
		{
			return SendPrivateMessage(target, message, encrypt: false);
		}

		public bool SendPrivateMessage(string target, object message, bool encrypt)
		{
			return sendPrivateMessage(target, message, encrypt, reliable: true);
		}

		internal bool SendPrivateMessageUnreliable(string target, object message, bool encrypt)
		{
			return sendPrivateMessage(target, message, encrypt, reliable: false);
		}

		private bool sendPrivateMessage(string target, object message, bool encrypt, bool reliable)
		{
			if (!CanChat)
			{
				if ((int)DebugOut >= 1)
				{
					listener.DebugReturn(DebugLevel.ERROR, "SendPrivateMessage called while not connected to front end server.");
				}
				return false;
			}
			if (string.IsNullOrEmpty(target) || message == null)
			{
				if ((int)DebugOut >= 2)
				{
					listener.DebugReturn(DebugLevel.WARNING, "SendPrivateMessage parameters must be non-null and not empty.");
				}
				return false;
			}
			Dictionary<byte, object> dictionary = new Dictionary<byte, object>();
			dictionary.Add(225, target);
			dictionary.Add(3, message);
			Dictionary<byte, object> customOpParameters = dictionary;
			return chatPeer.OpCustom(3, customOpParameters, reliable, 0, encrypt);
		}

		private bool SetOnlineStatus(int status, object message, bool skipMessage)
		{
			if (!CanChat)
			{
				if ((int)DebugOut >= 1)
				{
					listener.DebugReturn(DebugLevel.ERROR, "SetOnlineStatus called while not connected to front end server.");
				}
				return false;
			}
			Dictionary<byte, object> dictionary = new Dictionary<byte, object>();
			dictionary.Add(10, status);
			Dictionary<byte, object> dictionary2 = dictionary;
			if (skipMessage)
			{
				dictionary2[12] = true;
			}
			else
			{
				dictionary2[3] = message;
			}
			return chatPeer.OpCustom(5, dictionary2, sendReliable: true);
		}

