namespace ProBuilder2.Examples
{
	public class CameraControls : UnityEngine.MonoBehaviour
	{
		private const string INPUT_MOUSE_SCROLLWHEEL = "Mouse ScrollWheel";

		private const string INPUT_MOUSE_X = "Mouse X";

		private const string INPUT_MOUSE_Y = "Mouse Y";

		private const float MIN_CAM_DISTANCE = 10f;

		private const float MAX_CAM_DISTANCE = 40f;

		[Range(2f, 15f)]
		public float orbitSpeed = 6f;

		[Range(0.3f, 2f)]
		public float zoomSpeed = 0.8f;

		private float distance;

		public float idleRotation = 1f;

		private Vector2 dir = new Vector2(0.8f, 0.2f);

		private void Start()
		{
			distance = Vector3.Distance(base.transform.position, Vector3.zero);
		}

		private void LateUpdate()
		{
			Vector3 eulerAngles = base.transform.localRotation.eulerAngles;
			eulerAngles.z = 0f;
			if (Input.GetMouseButton(0))
			{
				float axis = Input.GetAxis("Mouse X");
				float num = 0f - Input.GetAxis("Mouse Y");
				eulerAngles.x += num * orbitSpeed;
				eulerAngles.y += axis * orbitSpeed;
				dir.x = axis;
				dir.y = num;
				dir.Normalize();
			}
			else
			{
				eulerAngles.y += Time.deltaTime * idleRotation * dir.x;
				eulerAngles.x += Time.deltaTime * Mathf.PerlinNoise(Time.time, 0f) * idleRotation * dir.y;
			}
			base.transform.localRotation = Quaternion.Euler(eulerAngles);
			base.transform.position = base.transform.localRotation * (Vector3.forward * (0f - distance));
			if (Input.GetAxis("Mouse ScrollWheel") != 0f)
			{
				float axis2 = Input.GetAxis("Mouse ScrollWheel");
				distance -= axis2 * (distance / 40f) * (zoomSpeed * 1000f) * Time.deltaTime;
				distance = Mathf.Clamp(distance, 10f, 40f);
				base.transform.position = base.transform.localRotation * (Vector3.forward * (0f - distance));
			}
		}
	}
	[RequireComponent(typeof(AudioSource))]
	public class IcoBumpin : UnityEngine.MonoBehaviour
	{
		private struct FaceRef
		{
			public pb_Face face;

			public Vector3 nrm;

			public int[] indices;

			public FaceRef(pb_Face f, Vector3 n, int[] i)
			{
				face = f;
				nrm = n;
				indices = i;
			}
		}

		private pb_Object ico;

		private Mesh icoMesh;

		private Transform icoTransform;

		private AudioSource audioSource;

		private FaceRef[] outsides;

		private Vector3[] original_vertices;

		private Vector3[] displaced_vertices;

		[Range(1f, 10f)]
		public float icoRadius = 2f;

		[Range(0f, 3f)]
		public int icoSubdivisions = 2;

		[Range(0f, 1f)]
		public float startingExtrusion = 0.1f;

		public Material material;

		[Range(1f, 50f)]
		public float extrusion = 30f;

		[Range(8f, 128f)]
		public int fftBounds = 32;

		[Range(0f, 10f)]
		public float verticalBounce = 4f;

		public AnimationCurve frequencyCurve;

		public LineRenderer waveform;

		public float waveformHeight = 2f;

		public float waveformRadius = 20f;

		public float waveformSpeed = 0.1f;

		public bool rotateWaveformRing;

		public bool bounceWaveform;

		public GameObject missingClipWarning;

		private Vector3 icoPosition = Vector3.zero;

		private float faces_length;

		private const float TWOPI = 6.283185f;

		private const int WAVEFORM_SAMPLES = 1024;

		private const int FFT_SAMPLES = 4096;

		private float[] fft = new float[4096];

		private float[] fft_history = new float[4096];

		private float[] data = new float[1024];

		private float[] data_history = new float[1024];

		private float rms;

		private float rms_history;

		private void Start()
		{
			audioSource = GetComponent<AudioSource>();
			if (audioSource.clip == null)
			{
				missingClipWarning.SetActive(value: true);
			}
			ico = pb_ShapeGenerator.IcosahedronGenerator(icoRadius, icoSubdivisions);
			pb_Face[] faces = ico.faces;
			pb_Face[] array = faces;
			foreach (pb_Face pb_Face in array)
			{
				pb_Face.material = material;
			}
			ico.Extrude(faces, startingExtrusion, extrudeAsGroup: false, out var _);
			ico.ToMesh();
			ico.Refresh();
			outsides = new FaceRef[faces.Length];
			Dictionary<int, int> lookup = ico.sharedIndices.ToDictionary();
			for (int j = 0; j < faces.Length; j++)
			{
				ref FaceRef reference = ref outsides[j];
				reference = new FaceRef(faces[j], pb_Math.Normal(ico, faces[j]), ico.sharedIndices.AllIndicesWithValues(lookup, faces[j].distinctIndices).ToArray());
			}
			original_vertices = new Vector3[ico.vertices.Length];
			Array.Copy(ico.vertices, original_vertices, ico.vertices.Length);
			displaced_vertices = ico.vertices;
			icoMesh = ico.msh;
			icoTransform = ico.transform;
			faces_length = outsides.Length;
			icoPosition = icoTransform.position;
			waveform.numPositions = 1024;
			if (bounceWaveform)
			{
				waveform.transform.parent = icoTransform;
			}
			audioSource.Play();
		}

		private void Update()
		{
			audioSource.GetSpectrumData(fft, 0, FFTWindow.BlackmanHarris);
			audioSource.GetOutputData(data, 0);
			rms = RMS(data);
			for (int i = 0; i < outsides.Length; i++)
			{
				float num = (float)i / faces_length;
				int num2 = (int)(num * (float)fftBounds);
				Vector3 vector = outsides[i].nrm * ((fft[num2] + fft_history[num2]) * 0.5f * (frequencyCurve.Evaluate(num) * 0.5f + 0.5f)) * extrusion;
				int[] indices = outsides[i].indices;
				foreach (int num3 in indices)
				{
					ref Vector3 reference = ref displaced_vertices[num3];
					reference = original_vertices[num3] + vector;
				}
			}
			Vector3 zero = Vector3.zero;
			for (int k = 0; k < 1024; k++)
			{
				int num4 = ((k < 1023) ? k : 0);
				zero.x = Mathf.Cos((float)num4 / 1024f * 6.283185f) * (waveformRadius + (data[num4] + data_history[num4]) * 0.5f * waveformHeight);
				zero.z = Mathf.Sin((float)num4 / 1024f * 6.283185f) * (waveformRadius + (data[num4] + data_history[num4]) * 0.5f * waveformHeight);
				zero.y = 0f;
				waveform.SetPosition(k, zero);
			}
			if (rotateWaveformRing)
			{
				Vector3 eulerAngles = waveform.transform.localRotation.eulerAngles;
				eulerAngles.x = Mathf.PerlinNoise(Time.time * waveformSpeed, 0f) * 360f;
				eulerAngles.y = Mathf.PerlinNoise(0f, Time.time * waveformSpeed) * 360f;
				waveform.transform.localRotation = Quaternion.Euler(eulerAngles);
			}
			icoPosition.y = 0f - verticalBounce + (rms + rms_history) * verticalBounce;
			icoTransform.position = icoPosition;
			Array.Copy(fft, fft_history, 4096);
			Array.Copy(data, data_history, 1024);
			rms_history = rms;
			icoMesh.vertices = displaced_vertices;
		}

		private float RMS(float[] arr)
		{
			float num = 0f;
			float num2 = arr.Length;
			for (int i = 0; (float)i < num2; i++)
			{
				num += Mathf.Abs(arr[i]);
			}
			return Mathf.Sqrt(num / num2);
		}
	}
	public class HueCube : UnityEngine.MonoBehaviour
	{
		private pb_Object pb;

		private void Start()
		{
			pb = pb_ShapeGenerator.CubeGenerator(Vector3.one);
			int num = pb.sharedIndices.Length;
			Color[] array = new Color[num];
			for (int i = 0; i < num; i++)
			{
				ref Color reference = ref array[i];
				reference = HSVtoRGB((float)i / (float)num * 360f, 1f, 1f);
			}
			Color[] colors = pb.colors;
			for (int j = 0; j < pb.sharedIndices.Length; j++)
			{
				int[] array2 = pb.sharedIndices[j].array;
				foreach (int num2 in array2)
				{
					ref Color reference2 = ref colors[num2];
					reference2 = array[j];
				}
			}
			pb.SetColors(colors);
			pb.Refresh();
		}

		private static Color HSVtoRGB(float h, float s, float v)
		{
			if (s == 0f)
			{
				return new Color(v, v, v, 1f);
			}
			h /= 60f;
			int num = (int)Mathf.Floor(h);
			float num2 = h - (float)num;
			float num3 = v * (1f - s);
			float num4 = v * (1f - s * num2);
			float num5 = v * (1f - s * (1f - num2));
			float r;
			float g;
			float b;
			switch (num)
			{
			case 0:
				r = v;
				g = num5;
				b = num3;
				break;
			case 1:
				r = num4;
				g = v;
				b = num3;
				break;
			case 2:
				r = num3;
				g = v;
				b = num5;
				break;
			case 3:
				r = num3;
				g = num4;
				b = v;
				break;
			case 4:
				r = num5;
				g = num3;
				b = v;
				break;
			default:
				r = v;
				g = num3;
				b = num4;
				break;
			}
			return new Color(r, g, b, 1f);
		}
	}
}
public class ExtrudeRandomEdges : UnityEngine.MonoBehaviour
{
	private pb_Object pb;

	private pb_Face lastExtrudedFace;

	public float distance = 1f;

	private void Start()
	{
		pb = pb_ShapeGenerator.PlaneGenerator(1f, 1f, 0, 0, Axis.Up, smooth: false);
		lastExtrudedFace = pb.faces[0];
	}

	private void OnGUI()
	{
		if (GUILayout.Button("Extrude Random Edge"))
		{
			ExtrudeEdge();
		}
	}

	private void ExtrudeEdge()
	{
		pb_Face sourceFace = lastExtrudedFace;
		List<pb_WingedEdge> wingedEdges = pb_WingedEdge.GetWingedEdges(pb);
		IEnumerable<pb_WingedEdge> source = wingedEdges.Where((pb_WingedEdge x) => x.face == sourceFace);
		List<pb_Edge> list = (from y in source
			where y.opposite == null
			select y.edge.local).ToList();
		int index = UnityEngine.Random.Range(0, list.Count);
		pb_Edge pb_Edge = list[index];
		Vector3 vector = (pb.vertices[pb_Edge.x] + pb.vertices[pb_Edge.y]) * 0.5f - sourceFace.distinctIndices.Average((int x) => pb.vertices[x]);
		vector.Normalize();
		pb.Extrude(new pb_Edge[1] { pb_Edge }, 0f, extrudeAsGroup: false, enableManifoldExtrude: true, out var extrudedEdges);
		lastExtrudedFace = pb.faces.Last();
		pb.SetSelectedEdges(extrudedEdges);
		pb.TranslateVertices(pb.SelectedTriangles, vector * distance);
		pb.ToMesh();
		pb.Refresh();
	}
}
namespace ProBuilder2.Examples
{
	public class RuntimeEdit : UnityEngine.MonoBehaviour
	{
		private class pb_Selection
		{
			public pb_Object pb;

			public pb_Face face;

			public pb_Selection(pb_Object _pb, pb_Face _face)
			{
				pb = _pb;
				face = _face;
			}

			public bool HasObject()
			{
				return pb != null;
			}

			public bool IsValid()
			{
				return pb != null && face != null;
			}

			public bool Equals(pb_Selection sel)
			{
				if (sel != null && sel.IsValid())
				{
					return pb == sel.pb && face == sel.face;
				}
				return false;
			}

			public void Destroy()
			{
				if (pb != null)
				{
					UnityEngine.Object.Destroy(pb.gameObject);
				}
			}

			public override string ToString()
			{
				return ("pb_Object: " + pb != null) ? (pb.name + "\npb_Face: " + ((face != null) ? face.ToString() : "Null")) : "Null";
			}
		}

		private pb_Selection currentSelection;

		private pb_Selection previousSelection;

		private pb_Object preview;

		public Material previewMaterial;

		private Vector2 mousePosition_initial = Vector2.zero;

		private bool dragging;

		public float rotateSpeed = 100f;

		private void Awake()
		{
			SpawnCube();
		}

		private void OnGUI()
		{
			if (GUI.Button(new Rect(5f, Screen.height - 25, 80f, 20f), "Reset"))
			{
				currentSelection.Destroy();
				UnityEngine.Object.Destroy(preview.gameObject);
				SpawnCube();
			}
		}

		private void SpawnCube()
		{
			pb_Object pb_Object = pb_ShapeGenerator.CubeGenerator(Vector3.one);
			pb_Object.gameObject.AddComponent<MeshCollider>().convex = false;
			currentSelection = new pb_Selection(pb_Object, null);
		}

		public void LateUpdate()
		{
			if (!currentSelection.HasObject())
			{
				return;
			}
			if (Input.GetMouseButtonDown(1) || (Input.GetMouseButtonDown(0) && Input.GetKey(KeyCode.LeftAlt)))
			{
				mousePosition_initial = Input.mousePosition;
				dragging = true;
			}
			if (dragging)
			{
				Vector2 vector = (Vector3)mousePosition_initial - Input.mousePosition;
				Vector3 axis = new Vector3(vector.y, vector.x, 0f);
				currentSelection.pb.gameObject.transform.RotateAround(Vector3.zero, axis, rotateSpeed * Time.deltaTime);
				if (currentSelection.IsValid())
				{
					RefreshSelectedFacePreview();
				}
			}
			if (Input.GetMouseButtonUp(1) || Input.GetMouseButtonUp(0))
			{
				dragging = false;
			}
		}

		public void Update()
		{
			if (!Input.GetMouseButtonUp(0) || Input.GetKey(KeyCode.LeftAlt) || !FaceCheck(Input.mousePosition) || !currentSelection.IsValid())
			{
				return;
			}
			if (!currentSelection.Equals(previousSelection))
			{
				previousSelection = new pb_Selection(currentSelection.pb, currentSelection.face);
				RefreshSelectedFacePreview();
				return;
			}
			Vector3 vector = pb_Math.Normal(currentSelection.pb.vertices.ValuesWithIndices(currentSelection.face.distinctIndices));
			if (Input.GetKey(KeyCode.LeftShift))
			{
				currentSelection.pb.TranslateVertices(currentSelection.face.distinctIndices, vector.normalized * -0.5f);
			}
			else
			{
				currentSelection.pb.TranslateVertices(currentSelection.face.distinctIndices, vector.normalized * 0.5f);
			}
			currentSelection.pb.Refresh();
			RefreshSelectedFacePreview();
		}

		public bool FaceCheck(Vector3 pos)
		{
			Ray ray = Camera.main.ScreenPointToRay(pos);
			if (Physics.Raycast(ray.origin, ray.direction, out var hitInfo))
			{
				pb_Object component = hitInfo.transform.gameObject.GetComponent<pb_Object>();
				if (component == null)
				{
					return false;
				}
				Mesh msh = component.msh;
				int[] tri = new int[3]
				{
					msh.triangles[hitInfo.triangleIndex * 3],
					msh.triangles[hitInfo.triangleIndex * 3 + 1],
					msh.triangles[hitInfo.triangleIndex * 3 + 2]
				};
				currentSelection.pb = component;
				return component.FaceWithTriangle(tri, out currentSelection.face);
			}
			return false;
		}

		private void RefreshSelectedFacePreview()
		{
			pb_Face pb_Face = new pb_Face(currentSelection.face);
			pb_Face.ShiftIndicesToZero();
			Vector3[] array = currentSelection.pb.VerticesInWorldSpace(currentSelection.face.distinctIndices);
			Vector3 vector = pb_Math.Normal(array);
			for (int i = 0; i < array.Length; i++)
			{
				array[i] += vector.normalized * 0.01f;
			}
			if ((bool)preview)
			{
				UnityEngine.Object.Destroy(preview.gameObject);
			}
			preview = pb_Object.CreateInstanceWithVerticesFaces(array, new pb_Face[1] { pb_Face });
			preview.SetFaceMaterial(preview.faces, previewMaterial);
			preview.ToMesh();
			preview.Refresh();
		}
	}
}
public struct GazeEventArgs
{
	public float distance;
}
public delegate void GazeEventHandler(object sender, GazeEventArgs e);
public class SteamVR_GazeTracker : UnityEngine.MonoBehaviour
{
	public bool isInGaze;

	public float gazeInCutoff = 0.15f;

	public float gazeOutCutoff = 0.4f;

	private Transform hmdTrackedObject;

	public event GazeEventHandler GazeOn;

	public event GazeEventHandler GazeOff;

	private void Start()
	{
	}

	public virtual void OnGazeOn(GazeEventArgs e)
	{
		if (this.GazeOn != null)
		{
			this.GazeOn(this, e);
		}
	}

	public virtual void OnGazeOff(GazeEventArgs e)
	{
		if (this.GazeOff != null)
		{
			this.GazeOff(this, e);
		}
	}

	private void Update()
	{
		if (hmdTrackedObject == null)
		{
			SteamVR_TrackedObject[] array = UnityEngine.Object.FindObjectsOfType<SteamVR_TrackedObject>();
			SteamVR_TrackedObject[] array2 = array;
			foreach (SteamVR_TrackedObject steamVR_TrackedObject in array2)
			{
				if (steamVR_TrackedObject.index == SteamVR_TrackedObject.EIndex.Hmd)
				{
					hmdTrackedObject = steamVR_TrackedObject.transform;
					break;
				}
			}
		}
		if (!hmdTrackedObject)
		{
			return;
		}
		Ray ray = new Ray(hmdTrackedObject.position, hmdTrackedObject.forward);
		Plane plane = new Plane(hmdTrackedObject.forward, base.transform.position);
		float enter = 0f;
		if (plane.Raycast(ray, out enter))
		{
			Vector3 a = hmdTrackedObject.position + hmdTrackedObject.forward * enter;
			float num = Vector3.Distance(a, base.transform.position);
			if (num < gazeInCutoff && !isInGaze)
			{
				isInGaze = true;
				GazeEventArgs e = default(GazeEventArgs);
				e.distance = num;
				OnGazeOn(e);
			}
			else if (num >= gazeOutCutoff && isInGaze)
			{
				isInGaze = false;
				GazeEventArgs e2 = default(GazeEventArgs);
				e2.distance = num;
				OnGazeOff(e2);
			}
		}
	}
}
