	public float distance;

	public Transform target;
}
public delegate void PointerEventHandler(object sender, PointerEventArgs e);
public class SteamVR_LaserPointer : UnityEngine.MonoBehaviour
{
	public bool active = true;

	public Color color;

	public float thickness = 0.002f;

	public GameObject holder;

	public GameObject pointer;

	private bool isActive;

	public bool addRigidBody;

	public Transform reference;

	private Transform previousContact;

	public event PointerEventHandler PointerIn;

	public event PointerEventHandler PointerOut;

	private void Start()
	{
		holder = new GameObject();
		holder.transform.parent = base.transform;
		holder.transform.localPosition = Vector3.zero;
		pointer = GameObject.CreatePrimitive(PrimitiveType.Cube);
		pointer.transform.parent = holder.transform;
		pointer.transform.localScale = new Vector3(thickness, thickness, 100f);
		pointer.transform.localPosition = new Vector3(0f, 0f, 50f);
		BoxCollider component = pointer.GetComponent<BoxCollider>();
		if (addRigidBody)
		{
			if ((bool)component)
			{
				component.isTrigger = true;
			}
			Rigidbody rigidbody = pointer.AddComponent<Rigidbody>();
			rigidbody.isKinematic = true;
		}
		else if ((bool)component)
		{
			UnityEngine.Object.Destroy(component);
		}
		Material material = new Material(Shader.Find("Unlit/Color"));
		material.SetColor("_Color", color);
		pointer.GetComponent<MeshRenderer>().material = material;
	}

	public virtual void OnPointerIn(PointerEventArgs e)
	{
		if (this.PointerIn != null)
		{
			this.PointerIn(this, e);
		}
	}

	public virtual void OnPointerOut(PointerEventArgs e)
	{
		if (this.PointerOut != null)
		{
			this.PointerOut(this, e);
		}
	}

	private void Update()
	{
		if (!isActive)
		{
			isActive = true;
			base.transform.GetChild(0).gameObject.SetActive(value: true);
		}
		float num = 100f;
		SteamVR_TrackedController component = GetComponent<SteamVR_TrackedController>();
		Ray ray = new Ray(base.transform.position, base.transform.forward);
		RaycastHit hitInfo;
		bool flag = Physics.Raycast(ray, out hitInfo);
		if ((bool)previousContact && previousContact != hitInfo.transform)
		{
			PointerEventArgs e = default(PointerEventArgs);
			if (component != null)
			{
				e.controllerIndex = component.controllerIndex;
			}
			e.distance = 0f;
			e.flags = 0u;
			e.target = previousContact;
			OnPointerOut(e);
			previousContact = null;
		}
		if (flag && previousContact != hitInfo.transform)
		{
			PointerEventArgs e2 = default(PointerEventArgs);
			if (component != null)
			{
				e2.controllerIndex = component.controllerIndex;
			}
			e2.distance = hitInfo.distance;
			e2.flags = 0u;
			e2.target = hitInfo.transform;
			OnPointerIn(e2);
			previousContact = hitInfo.transform;
		}
		if (!flag)
		{
			previousContact = null;
		}
		if (flag && hitInfo.distance < 100f)
		{
			num = hitInfo.distance;
		}
		if (component != null && component.triggerPressed)
		{
			pointer.transform.localScale = new Vector3(thickness * 5f, thickness * 5f, num);
		}
		else
		{
			pointer.transform.localScale = new Vector3(thickness, thickness, num);
		}
		pointer.transform.localPosition = new Vector3(0f, 0f, num / 2f);
	}
}
public class SteamVR_Teleporter : UnityEngine.MonoBehaviour
{
	public enum TeleportType
	{
		TeleportTypeUseTerrain,
		TeleportTypeUseCollider,
		TeleportTypeUseZeroY
	}

	public bool teleportOnClick;

	public TeleportType teleportType = TeleportType.TeleportTypeUseZeroY;

	private Transform reference
	{
		get
		{
			SteamVR_Camera steamVR_Camera = SteamVR_Render.Top();
			return (!(steamVR_Camera != null)) ? null : steamVR_Camera.origin;
		}
	}

	private void Start()
	{
		SteamVR_TrackedController steamVR_TrackedController = GetComponent<SteamVR_TrackedController>();
		if (steamVR_TrackedController == null)
		{
			steamVR_TrackedController = base.gameObject.AddComponent<SteamVR_TrackedController>();
		}
		steamVR_TrackedController.TriggerClicked += DoClick;
		if (teleportType == TeleportType.TeleportTypeUseTerrain)
		{
			Transform transform = reference;
			if (transform != null)
			{
				transform.position = new Vector3(transform.position.x, Terrain.activeTerrain.SampleHeight(transform.position), transform.position.z);
			}
		}
	}

	private void DoClick(object sender, ClickedEventArgs e)
	{
		if (!teleportOnClick)
		{
			return;
		}
		Transform transform = reference;
		if (!(transform == null))
		{
			float y = transform.position.y;
			Plane plane = new Plane(Vector3.up, 0f - y);
			Ray ray = new Ray(base.transform.position, base.transform.forward);
			bool flag = false;
			float enter = 0f;
			if (teleportType == TeleportType.TeleportTypeUseTerrain)
			{
				TerrainCollider component = Terrain.activeTerrain.GetComponent<TerrainCollider>();
				flag = component.Raycast(ray, out var hitInfo, 1000f);
				enter = hitInfo.distance;
			}
			else if (teleportType == TeleportType.TeleportTypeUseCollider)
			{
				Physics.Raycast(ray, out var hitInfo2);
				enter = hitInfo2.distance;
			}
			else
			{
				flag = plane.Raycast(ray, out enter);
			}
			if (flag)
			{
				Vector3 vector = new Vector3(SteamVR_Render.Top().head.localPosition.x, 0f, SteamVR_Render.Top().head.localPosition.z);
				transform.position = ray.origin + ray.direction * enter - new Vector3(transform.GetChild(0).localPosition.x, 0f, transform.GetChild(0).localPosition.z) - vector;
			}
		}
	}
}
[RequireComponent(typeof(SteamVR_TrackedObject))]
public class SteamVR_TestThrow : UnityEngine.MonoBehaviour
{
	public GameObject prefab;

	public Rigidbody attachPoint;

	private SteamVR_TrackedObject trackedObj;

	private FixedJoint joint;

	private void Awake()
	{
		trackedObj = GetComponent<SteamVR_TrackedObject>();
	}

	private void FixedUpdate()
	{
		SteamVR_Controller.Device device = SteamVR_Controller.Input((int)trackedObj.index);
		if (joint == null && device.GetTouchDown(8589934592uL))
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(prefab);
			gameObject.transform.position = attachPoint.transform.position;
			joint = gameObject.AddComponent<FixedJoint>();
			joint.connectedBody = attachPoint;
		}
		else if (joint != null && device.GetTouchUp(8589934592uL))
		{
			GameObject gameObject2 = joint.gameObject;
			Rigidbody component = gameObject2.GetComponent<Rigidbody>();
			UnityEngine.Object.DestroyImmediate(joint);
			joint = null;
			UnityEngine.Object.Destroy(gameObject2, 15f);
			Transform transform = ((!trackedObj.origin) ? trackedObj.transform.parent : trackedObj.origin);
			if (transform != null)
			{
				component.velocity = transform.TransformVector(device.velocity);
				component.angularVelocity = transform.TransformVector(device.angularVelocity);
			}
			else
			{
				component.velocity = device.velocity;
				component.angularVelocity = device.angularVelocity;
			}
			component.maxAngularVelocity = component.angularVelocity.magnitude;
		}
	}
}
