[Serializable]
public class GameTeleportManager : IGameComponent
{
	[Serializable]
	private struct TeleportRegionTagMetadata
	{
		public TeleportRegionTagType TagType;

		public string Name;
	}

	[Serializable]
	private struct TeleportCooldownMetadata
	{
		public TeleportCooldownType cooldownType;

		public float customTeleportCooldown;
	}

	[Header("Cooldown")]
	[SerializeField]
	private TeleportCooldownMetadata[] customTeleportCooldowns;

	[SerializeField]
	private TeleportCooldownType defaultCooldownType = TeleportCooldownType.DEFAULT;

	[Header("Min Teleport Buffer")]
	[SerializeField]
	private bool supportsCustomTeleportBufferDistance;

	[SerializeField]
	private float customTeleportBufferDistance = 0.5f;

	[Header("Teleport Region Tags")]
	[SerializeField]
	private TeleportRegionTagMetadata[] teleportRegionTags;

	private const string TELEPORT_REGION_TAG_KEY = "TELEPORT_REGION_TAG";

	private GameManager gameManager;

	private GameTeleportRestriction[] teleportRestrictions;

	private TeleportRegionTagType localPlayerTeleportRegionTag = TeleportRegionTagType.DEFAULT;

	public TeleportCooldownType DefaultCooldownType => defaultCooldownType;

	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
	}

	public void OnStart()
	{
		teleportRestrictions = UnityEngine.Object.FindObjectsOfType<GameTeleportRestriction>();
		UpdateRestrictions();
	}

	public void OnDestroy()
	{
	}

	public void OnUpdate()
	{
	}

	public void OnPlayerDisconnected(PhotonPlayer player)
	{
	}

	public void SetLocalPlayerTeleportRegionTag(TeleportRegionTagType tag)
	{
		localPlayerTeleportRegionTag = tag;
		UpdateRestrictions();
	}

	public string GetTagName(TeleportRegionTagType tagType)
	{
		for (int i = 0; i < teleportRegionTags.Length; i++)
		{
			if (teleportRegionTags[i].TagType == tagType)
			{
				return teleportRegionTags[i].Name;
			}
		}
		return null;
	}

	private TeleportRegionTagType GetLocalPlayerTeleportRegionTag()
	{
		return localPlayerTeleportRegionTag;
	}

	public void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
		SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.DEFAULT);
		if (!localPlayerIsSpectator)
		{
			SetLocalPlayerCustomTeleportCooldown(defaultCooldownType);
			if (supportsCustomTeleportBufferDistance)
			{
				Player.LocalPlayer.PlayerLocomotion.HasOverrideTeleportBuffer = true;
				Player.LocalPlayer.PlayerLocomotion.OverrideTeleportBuffer = customTeleportBufferDistance;
			}
		}
		UpdateRestrictions();
	}

	public void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		if (!localPlayerIsSpectator)
		{
			SetLocalPlayerCustomTeleportCooldown(TeleportCooldownType.DEFAULT);
			Player.LocalPlayer.PlayerLocomotion.HasOverrideTeleportBuffer = false;
		}
		UpdateRestrictions();
	}

	private void UpdateRestrictions()
	{
		bool isGameRunning = gameManager.CurrentState == GameStates.GAME_RUNNING;
		bool flag = gameManager.TeamManager.IsPlayerSpectator(PhotonNetwork.player);
		GameTeam localPlayerTeam = ((!flag) ? gameManager.TeamManager.GetPlayerTeam(PhotonNetwork.player) : GameTeam.INVALID);
		for (int i = 0; i < teleportRestrictions.Length; i++)
		{
			teleportRestrictions[i].UpdateRestrictions(isGameRunning, flag, localPlayerTeam, GetLocalPlayerTeleportRegionTag());
		}
	}

	public void SetLocalPlayerCustomTeleportCooldown(TeleportCooldownType cooldownType)
	{
		if (customTeleportCooldowns.Length <= 0)
		{
			return;
		}
		if (cooldownType != TeleportCooldownType.DEFAULT)
		{
			float num = -1f;
			for (int i = 0; i < customTeleportCooldowns.Length; i++)
			{
				if (customTeleportCooldowns[i].cooldownType == cooldownType)
				{
					num = customTeleportCooldowns[i].customTeleportCooldown;
				}
			}
			if (num >= 0f)
			{
				Player.LocalPlayer.PlayerLocomotion.AddTeleportCooldown(cooldownType, num);
			}
		}
		else
		{
			for (int j = 0; j < customTeleportCooldowns.Length; j++)
			{
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportCooldown(customTeleportCooldowns[j].cooldownType);
			}
		}
	}

	public void RemoveLocalPlayerCustomTeleportCooldown(TeleportCooldownType cooldownType)
	{
		Player.LocalPlayer.PlayerLocomotion.RemoveTeleportCooldown(cooldownType);
	}
}
[Serializable]
public class GameTimerManager : IGameComponent
{
	[SerializeField]
	private bool supportsGameTimer;

	[SerializeField]
	private float gameDuration;

	private GameManager gameManager;

	private SynchronizedTimer timer;

	public float GameDuration => gameDuration;

	public bool SupportsGameTimer => supportsGameTimer;

	public bool TimerOver => supportsGameTimer && timer.TimeRemaining <= 0f;

	public float TimeElapsed => timer.TimeElapsed;

	public float TimeRemaining => (!supportsGameTimer) ? 0f : timer.TimeRemaining;

	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		timer = new SynchronizedTimer(gameManager, "GAME", SetterPermissionMode.MASTER);
		timer.StartTimerEvent += OnStartTimer;
	}

	public void OnStart()
	{
	}

	public void OnDestroy()
	{
	}

	public void OnPlayerDisconnected(PhotonPlayer player)
	{
	}

	public void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
	}

	public void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
	}

	public void StartTimer()
	{
		if (timer == null)
		{
			UnityEngine.Debug.LogError("GameTimerManager has not been initialized.");
		}
		if (PhotonNetwork.isMasterClient)
		{
			if (supportsGameTimer)
			{
				timer.StartTimer(gameDuration);
			}
			else
			{
				timer.StartTimerWithoutMaxRunningTime();
			}
		}
	}

	public void Pause()
	{
		if (PhotonNetwork.isMasterClient)
		{
			timer.Pause();
		}
	}

	public void Resume()
	{
		if (PhotonNetwork.isMasterClient)
		{
			timer.Resume();
		}
	}

	public void OnUpdate()
	{
		if (timer != null)
		{
			timer.UpdateCallbacks();
		}
	}

	public void AddTimeElapsedCallback(float timeElapsed, Timer.Callback callback)
	{
		if (timer != null)
		{
			timer.AddTimeElapsedCallback(timeElapsed, callback);
		}
	}

	public void AddTimeRemainingCallback(float timeRemaining, Timer.Callback callback)
	{
		if (timer != null)
		{
			timer.AddTimeRemainingCallback(timeRemaining, callback);
		}
	}

	private void OnStartTimer()
	{
		timer.ClearCallbacks();
		if (TimeRemaining >= 60f)
		{
			timer.AddTimeRemainingCallback(60f, OnOneMinuteRemaining);
		}
		if (TimeRemaining >= 10f)
		{
			timer.AddTimeRemainingCallback(10f, OnTenSecondsRemaining);
			timer.AddTimeRemainingCallback(5f, OnFiveSecondsRemaining);
			timer.AddTimeRemainingCallback(4f, OnFourSecondsRemaining);
			timer.AddTimeRemainingCallback(3f, OnThreeSecondsRemaining);
			timer.AddTimeRemainingCallback(2f, OnTwoSecondsRemaining);
			timer.AddTimeRemainingCallback(1f, OnOneSecondRemaining);
		}
	}

	private void OnOneMinuteRemaining()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "1 Minute Remaining", 3f);
		gameManager.FxManager.PlaySFX(FxType.ONE_MINUTE_REMAINING);
	}

	private void OnTenSecondsRemaining()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "10 Seconds Remaining", 3f);
		gameManager.FxManager.PlaySFX(FxType.TEN_SECONDS_REMAINING);
	}

	private void OnFiveSecondsRemaining()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "5", 1f);
		gameManager.FxManager.PlaySFX(FxType.FIVE);
	}

	private void OnFourSecondsRemaining()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "4", 1f);
		gameManager.FxManager.PlaySFX(FxType.FOUR);
	}

	private void OnThreeSecondsRemaining()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "3", 1f);
		gameManager.FxManager.PlaySFX(FxType.THREE);
	}

	private void OnTwoSecondsRemaining()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "2", 1f);
		gameManager.FxManager.PlayFX(FxType.TWO);
	}

	private void OnOneSecondRemaining()
	{
		ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "1", 1f);
		gameManager.FxManager.PlayFX(FxType.ONE);
	}
}
public class GameUIDataModel
{
	public string Name = string.Empty;

	public string PresenceString = string.Empty;

	public bool InviteOnly;

	public bool SupportsPreviousGameResults;

	public bool SupportsTeamSwitching;

	public bool SupportsModeSwitching;

	public bool SupportsScore;

	public string WinCondition;

	public string ModeName;

	public string[] StatNames;

	public GameUITeamDataModel[] TeamModels;

	public GameUILocalPlayerDataModel LocalPlayer;

	public static void DeepCopy(GameUIDataModel source, GameUIDataModel dest)
	{
		dest.Name = source.Name;
		dest.PresenceString = source.PresenceString;
		dest.InviteOnly = source.InviteOnly;
		dest.SupportsPreviousGameResults = source.SupportsPreviousGameResults;
		dest.SupportsTeamSwitching = source.SupportsTeamSwitching;
		dest.SupportsModeSwitching = source.SupportsModeSwitching;
		dest.SupportsScore = source.SupportsScore;
		dest.ModeName = source.ModeName;
		if (dest.StatNames == null || dest.StatNames.Length != source.StatNames.Length)
		{
			dest.StatNames = new string[source.StatNames.Length];
		}
		Array.Copy(source.StatNames, dest.StatNames, source.StatNames.Length);
		if (dest.TeamModels == null || source.TeamModels.Length != dest.TeamModels.Length)
		{
			dest.TeamModels = new GameUITeamDataModel[source.TeamModels.Length];
		}
		for (int i = 0; i < dest.TeamModels.Length; i++)
		{
			if (dest.TeamModels[i] == null)
			{
				dest.TeamModels[i] = new GameUITeamDataModel();
			}
			GameUITeamDataModel.DeepCopy(source.TeamModels[i], dest.TeamModels[i]);
		}
		if (dest.LocalPlayer == null)
		{
			dest.LocalPlayer = new GameUILocalPlayerDataModel();
		}
		GameUILocalPlayerDataModel.DeepCopy(source.LocalPlayer, dest.LocalPlayer);
	}
}
public class GameUITeamDataModel
{
	public bool Active;

	public bool IsLocal;

	public Color Color = Color.white;

	public int Score;

	public GameUIPlayerDataModel[] PlayerModels;

	public static void DeepCopy(GameUITeamDataModel source, GameUITeamDataModel dest)
	{
		dest.Active = source.Active;
		dest.IsLocal = source.IsLocal;
		dest.Color = source.Color;
		dest.Score = source.Score;
		if (dest.PlayerModels == null || dest.PlayerModels.Length != source.PlayerModels.Length)
		{
			dest.PlayerModels = new GameUIPlayerDataModel[source.PlayerModels.Length];
		}
		for (int i = 0; i < source.PlayerModels.Length; i++)
		{
			if (dest.PlayerModels[i] == null)
			{
				dest.PlayerModels[i] = new GameUIPlayerDataModel();
			}
			GameUIPlayerDataModel.DeepCopy(source.PlayerModels[i], dest.PlayerModels[i]);
		}
	}
}
public class GameUIPlayerDataModel
{
	public bool Active;

	public bool IsLocal;

	public string Name = string.Empty;

	public int[] Stats;

	public static void DeepCopy(GameUIPlayerDataModel source, GameUIPlayerDataModel dest)
	{
		dest.Active = source.Active;
		dest.IsLocal = source.IsLocal;
		dest.Name = source.Name;
		if (dest.Stats == null || dest.Stats.Length != source.Stats.Length)
		{
			dest.Stats = new int[source.Stats.Length];
		}
		Array.Copy(source.Stats, dest.Stats, source.Stats.Length);
	}
}
public class GameUILocalPlayerDataModel
{
	public bool IsSpectator = true;

	public bool CanSwitchTeams;

	public bool CanJoinGame;

	public bool CanLeaveGame;

	public static void DeepCopy(GameUILocalPlayerDataModel source, GameUILocalPlayerDataModel dest)
	{
		dest.IsSpectator = source.IsSpectator;
		dest.CanSwitchTeams = source.CanSwitchTeams;
		dest.CanJoinGame = source.CanJoinGame;
		dest.CanLeaveGame = source.CanLeaveGame;
	}
}
public class GameUITimerDataModel
{
	public float GameTimeRemaining;

	public float GameDuration;

	public float GameStateTransitionTimeRemaining;

	public static void DeepCopy(GameUITimerDataModel source, GameUITimerDataModel dest)
	{
		dest.GameTimeRemaining = source.GameTimeRemaining;
		dest.GameDuration = source.GameDuration;
		dest.GameStateTransitionTimeRemaining = source.GameStateTransitionTimeRemaining;
	}
}
public enum GameUIState
{
	PRE_GAME,
	WAITING_FOR_PLAYERS,
	GAME_STARTING,
	GAME_ON,
	GAME_RUNNING,
	GAME_OVER,
	RESULTS_LOCKED,
	RESULTS
}
public class GameUIManager : IGameComponent
{
	private GameManager gameManager;

	private GameUIView[] uiViews;

	private GameUIState uiState;

	private GameUIDataModel currentDataModel;

	private GameUIDataModel previousDataModel;

	private GameUITimerDataModel currentTimerDataModel;

	private GameUITimerDataModel previousTimerDataModel;

	private bool gameDataIsDirty = true;

	private bool supportsPreviousGameResults;

	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		this.gameManager.TeamManager.TeamChangeEvent += OnTeamChange;
		this.gameManager.StatsManager.StatsChangeEvent += OnStatChange;
		this.gameManager.ModeManager.ModeChangeEvent += OnModeChange;
		this.gameManager.PresenceSettings.PresenceChangeEvent += OnPresenceChange;
		this.gameManager.StateChangeEvent += OnGameStateChange;
	}

	public void OnStart()
	{
		uiViews = UnityEngine.Object.FindObjectsOfType<GameUIView>();
		for (int i = 0; i < uiViews.Length; i++)
		{
			uiViews[i].JoinLeaveGameButtonPressEvent += OnJoinLeaveGameButtonPressed;
			uiViews[i].StartGameButtonPressEvent += OnStartGameButtonPressed;
			uiViews[i].SwitchTeamButtonPressEvent += OnSwitchTeamButtonPressed;
			uiViews[i].SwitchModeButtonPressEvent += OnSwitchModeButtonPressed;
			uiViews[i].ViewResultsButtonPressEvent += OnViewResultsButtonPressed;
		}
		currentDataModel = CreateUIDataModel();
		previousDataModel = new GameUIDataModel();
		UpdateUIState();
		BroadcastGameUIDataModel();
		currentTimerDataModel = new GameUITimerDataModel();
		previousTimerDataModel = new GameUITimerDataModel();
		UpdateUITimerDataModel();
		BroadcastUITimerDataModel();
	}

	public void OnUpdate()
	{
		UpdateUITimerDataModel();
		BroadcastUITimerDataModel();
		if (gameDataIsDirty)
		{
			UpdateCurrentGameModel();
			BroadcastGameUIDataModel();
			gameDataIsDirty = false;
		}
	}

	public void OnDestroy()
	{
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent -= OnTeamChange;
			gameManager.StatsManager.StatsChangeEvent -= OnStatChange;
			gameManager.ModeManager.ModeChangeEvent -= OnModeChange;
			gameManager.PresenceSettings.PresenceChangeEvent -= OnPresenceChange;
			gameManager.StateChangeEvent -= OnGameStateChange;
		}
		if (uiViews != null)
		{
			for (int i = 0; i < uiViews.Length; i++)
			{
				uiViews[i].JoinLeaveGameButtonPressEvent -= OnJoinLeaveGameButtonPressed;
				uiViews[i].StartGameButtonPressEvent -= OnStartGameButtonPressed;
				uiViews[i].SwitchTeamButtonPressEvent -= OnSwitchTeamButtonPressed;
				uiViews[i].SwitchModeButtonPressEvent -= OnSwitchModeButtonPressed;
				uiViews[i].ViewResultsButtonPressEvent -= OnViewResultsButtonPressed;
			}
		}
	}

	public void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
	}

	public void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
	}

	public void OnPlayerDisconnected(PhotonPlayer player)
	{
	}

	private void OnTeamChange()
	{
		gameDataIsDirty = true;
	}

	private void OnStatChange()
	{
		gameDataIsDirty = true;
	}

	private void OnModeChange()
	{
		gameDataIsDirty = true;
	}

	private void OnGameStateChange(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		UpdateUIState();
		gameDataIsDirty = true;
	}

	private void OnPresenceChange()
	{
		gameDataIsDirty = true;
	}

	private void OnJoinLeaveGameButtonPressed()
	{
		gameManager.LocalPlayerJoinLeaveGame();
	}

	private void OnStartGameButtonPressed()
	{
		gameManager.LocalPlayerStartGame();
	}

	private void OnSwitchTeamButtonPressed()
	{
		gameManager.LocalPlayerSwitchTeam();
	}

	private void OnSwitchModeButtonPressed()
	{
		gameManager.LocalPlayerSwitchMode();
	}

	private void OnViewResultsButtonPressed()
	{
		if (gameManager.CurrentState == GameStates.PRE_GAME)
		{
			if (uiState == GameUIState.RESULTS && gameManager.CurrentPreGameState == PreGameSubStates.WAITING_FOR_PLAYERS)
			{
				uiState = GameUIState.WAITING_FOR_PLAYERS;
			}
			else if (uiState == GameUIState.RESULTS && gameManager.CurrentPreGameState == PreGameSubStates.WAITING_FOR_START_GAME)
			{
				uiState = GameUIState.PRE_GAME;
			}
			else if (uiState == GameUIState.PRE_GAME || uiState == GameUIState.WAITING_FOR_PLAYERS)
			{
				uiState = GameUIState.RESULTS;
			}
			gameDataIsDirty = true;
		}
	}

	private GameUIDataModel CreateUIDataModel()
	{
		GameUIDataModel gameUIDataModel = new GameUIDataModel();
		gameUIDataModel.Name = RecRoomSceneManager.CurrentSceneFriendlyName;
		gameUIDataModel.SupportsScore = gameManager.StatsManager.SupportsScore;
		gameUIDataModel.InviteOnly = PUNNetworkManager.Instance.IsActivityInviteOnly;
		gameUIDataModel.SupportsPreviousGameResults = false;
		gameUIDataModel.SupportsTeamSwitching = gameManager.TeamManager.GetAllTeams().Length > 1;
		gameUIDataModel.SupportsModeSwitching = gameManager.ModeManager.SupportsModeSwitching;
		gameUIDataModel.ModeName = string.Empty;
		gameUIDataModel.WinCondition = string.Empty;
		gameUIDataModel.PresenceString = string.Empty;
		int statsCount = gameManager.StatsManager.GetStatsCount();
		gameUIDataModel.StatNames = new string[statsCount];
		for (int i = 0; i < statsCount; i++)
		{
			gameUIDataModel.StatNames[i] = gameManager.StatsManager.GetPlayerStatName((PlayerStatType)i);
		}
		GameTeam[] allTeams = gameManager.TeamManager.GetAllTeams();
		Array.Sort(allTeams, delegate(GameTeam a, GameTeam b)
		{
			int num4 = (int)a;
			return num4.CompareTo((int)b);
		});
		int num = allTeams.Length;
		gameUIDataModel.TeamModels = new GameUITeamDataModel[num];
		for (int num2 = 0; num2 < num; num2++)
		{
			gameUIDataModel.TeamModels[num2] = new GameUITeamDataModel();
			gameUIDataModel.TeamModels[num2].Active = false;
			gameUIDataModel.TeamModels[num2].IsLocal = false;
			gameUIDataModel.TeamModels[num2].Color = GameTeamSettings.GetTeamColor(allTeams[num2]);
			gameUIDataModel.TeamModels[num2].Score = gameManager.StatsManager.GetScore(allTeams[num2]);
			int teamMaxPlayerCount = gameManager.TeamManager.GetTeamMaxPlayerCount(allTeams[num2]);
			gameUIDataModel.TeamModels[num2].PlayerModels = new GameUIPlayerDataModel[teamMaxPlayerCount];
			for (int num3 = 0; num3 < teamMaxPlayerCount; num3++)
			{
				gameUIDataModel.TeamModels[num2].PlayerModels[num3] = new GameUIPlayerDataModel();
				gameUIDataModel.TeamModels[num2].PlayerModels[num3].Active = false;
				gameUIDataModel.TeamModels[num2].PlayerModels[num3].IsLocal = false;
				gameUIDataModel.TeamModels[num2].PlayerModels[num3].Stats = new int[statsCount];
			}
		}
		gameUIDataModel.LocalPlayer = new GameUILocalPlayerDataModel();
		gameUIDataModel.LocalPlayer.IsSpectator = true;
		gameUIDataModel.LocalPlayer.CanSwitchTeams = false;
		gameUIDataModel.LocalPlayer.CanJoinGame = false;
		gameUIDataModel.LocalPlayer.CanLeaveGame = false;
		return gameUIDataModel;
	}

	private void UpdateCurrentGameModel()
	{
		currentDataModel.SupportsPreviousGameResults = supportsPreviousGameResults;
		currentDataModel.InviteOnly = PUNNetworkManager.Instance.IsActivityInviteOnly;
		GameMode mode = gameManager.ModeManager.GetMode();
		string text = gameManager.ModeManager.GetModeScoreName(mode).ToUpper();
		if (gameManager.ModeManager.GetModeHasScoreWinCondition(mode))
		{
			int modeScoreWinCondition = gameManager.ModeManager.GetModeScoreWinCondition(mode);
			currentDataModel.WinCondition = modeScoreWinCondition + " " + text;
			if (modeScoreWinCondition > 1)
			{
				currentDataModel.WinCondition += "S";
			}
		}
		else
		{
			currentDataModel.WinCondition = "TIMED";
		}
		string text2 = gameManager.ModeManager.GetCurrentModeName().ToUpper();
		if (currentDataModel.InviteOnly)
		{
			if (!string.IsNullOrEmpty(text2))
			{
				text2 += " ";
			}
			text2 += "(INVITE ONLY)";
		}
		currentDataModel.ModeName = text2;
		currentDataModel.PresenceString = gameManager.PresenceSettings.CurrentPresenceString;
		int statsCount = gameManager.StatsManager.GetStatsCount();
		GameTeam[] allTeams = gameManager.TeamManager.GetAllTeams();
		Array.Sort(allTeams, delegate(GameTeam a, GameTeam b)
		{
			int num4 = (int)a;
			return num4.CompareTo((int)b);
		});
		for (int num = 0; num < allTeams.Length; num++)
		{
			currentDataModel.TeamModels[num].IsLocal = false;
			currentDataModel.TeamModels[num].Score = gameManager.StatsManager.GetScore(allTeams[num]);
			PhotonPlayer[] teamPlayersSortedByIndex = gameManager.TeamManager.GetTeamPlayersSortedByIndex(allTeams[num]);
			currentDataModel.TeamModels[num].Active = teamPlayersSortedByIndex.Length > 0;
			int num2;
			for (num2 = 0; num2 < teamPlayersSortedByIndex.Length; num2++)
			{
				if (teamPlayersSortedByIndex[num2] == PhotonNetwork.player)
				{
					currentDataModel.TeamModels[num].PlayerModels[num2].IsLocal = true;
					currentDataModel.TeamModels[num].IsLocal = true;
				}
				else
				{
					currentDataModel.TeamModels[num].PlayerModels[num2].IsLocal = false;
				}
				currentDataModel.TeamModels[num].PlayerModels[num2].Active = true;
				currentDataModel.TeamModels[num].PlayerModels[num2].Name = teamPlayersSortedByIndex[num2].name;
				for (int num3 = 0; num3 < statsCount; num3++)
				{
					currentDataModel.TeamModels[num].PlayerModels[num2].Stats[num3] = gameManager.StatsManager.GetPlayerStat(teamPlayersSortedByIndex[num2], (PlayerStatType)num3);
				}
			}
			for (; num2 < currentDataModel.TeamModels[num].PlayerModels.Length; num2++)
			{
				currentDataModel.TeamModels[num].PlayerModels[num2].Active = false;
			}
		}
		currentDataModel.LocalPlayer.IsSpectator = gameManager.TeamManager.IsPlayerSpectator(PhotonNetwork.player);
		currentDataModel.LocalPlayer.CanSwitchTeams = gameManager.TeamManager.PlayerCanSwitchTeam(PhotonNetwork.player);
		currentDataModel.LocalPlayer.CanLeaveGame = gameManager.TeamManager.PlayerCanLeaveGame(PhotonNetwork.player);
		switch (gameManager.CurrentState)
		{
		case GameStates.PRE_GAME:
			currentDataModel.LocalPlayer.CanJoinGame = gameManager.TeamManager.GetGameVacancy() > 0;
			break;
		case GameStates.GAME_RUNNING:
			currentDataModel.LocalPlayer.CanJoinGame = gameManager.ReadyToJoinInProgress;
			break;
		default:
			currentDataModel.LocalPlayer.CanJoinGame = false;
			break;
		}
	}

	private void UpdateUITimerDataModel()
	{
		if (gameManager.GameTimerManager.SupportsGameTimer)
		{
			currentTimerDataModel.GameDuration = gameManager.GameTimerManager.GameDuration;
			currentTimerDataModel.GameTimeRemaining = gameManager.GameTimerManager.TimeRemaining;
		}
		else
		{
			currentTimerDataModel.GameDuration = 0f;
			currentTimerDataModel.GameTimeRemaining = gameManager.GameTimerManager.TimeElapsed;
		}
		if (gameManager.CurrentPreGameState == PreGameSubStates.GAME_LOADING)
		{
			currentTimerDataModel.GameStateTransitionTimeRemaining = gameManager.LoadingGameTimeRemaining;
		}
		else if (gameManager.CurrentState == GameStates.POST_GAME)
		{
			currentTimerDataModel.GameStateTransitionTimeRemaining = gameManager.PostGameTimeRemaining;
		}
		else
		{
			currentTimerDataModel.GameStateTransitionTimeRemaining = 0f;
		}
	}

	private void BroadcastGameUIDataModel()
	{
		GameUIDataModel dataModel = ((uiState != GameUIState.RESULTS && uiState != GameUIState.RESULTS_LOCKED) ? currentDataModel : previousDataModel);
		for (int i = 0; i < uiViews.Length; i++)
		{
			uiViews[i].SetGameDataModel(uiState, dataModel);
		}
	}

	private void BroadcastUITimerDataModel()
	{
		GameUITimerDataModel timerDataModel = ((uiState != GameUIState.RESULTS) ? currentTimerDataModel : previousTimerDataModel);
		for (int i = 0; i < uiViews.Length; i++)
		{
			uiViews[i].SetTimerDataModel(uiState, timerDataModel);
		}
	}

	private void UpdateUIState()
	{
		switch (gameManager.CurrentState)
		{
		case GameStates.PRE_GAME:
			switch (gameManager.CurrentPreGameState)
			{
			case PreGameSubStates.WAITING_FOR_PLAYERS:
				uiState = GameUIState.WAITING_FOR_PLAYERS;
				break;
			case PreGameSubStates.WAITING_FOR_START_GAME:
				uiState = GameUIState.PRE_GAME;
				break;
			case PreGameSubStates.GAME_LOADING:
				uiState = GameUIState.GAME_STARTING;
				break;
			case PreGameSubStates.GAME_ON:
				uiState = GameUIState.GAME_ON;
				break;
			}
			break;
		case GameStates.GAME_RUNNING:
			uiState = GameUIState.GAME_RUNNING;
			break;
		case GameStates.POST_GAME:
			switch (gameManager.CurrentPostGameState)
			{
			case PostGameSubStates.GAME_OVER:
				uiState = GameUIState.GAME_OVER;
				break;
			case PostGameSubStates.RESULTS:
				uiState = GameUIState.RESULTS_LOCKED;
				GameUIDataModel.DeepCopy(currentDataModel, previousDataModel);
				GameUITimerDataModel.DeepCopy(currentTimerDataModel, previousTimerDataModel);
				supportsPreviousGameResults = true;
				break;
			}
			break;
		}
	}
}
