[Serializable]
public class InvisibleWallVisualConfig : ScriptableObject
{
	public float ImpactDuration = 1f;

	public float MinImpactRadius = 0.1f;

	public float MaxImpactRadius = 1f;

	public float ForceToImpactRadius = 0.12f;

	public AnimationCurve ImpactRadiusGrowthCurve;

	public AnimationCurve ImpactAlphaCurve;
}
public static class InvisibleWallVisualSettings
{
	private static InvisibleWallVisualConfig ConfigAsset = CustomSettingsLoader.LoadConfig<InvisibleWallVisualConfig>();

	private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

	public static float ImpactDuration
	{
		get
		{
			if (ConfigAsset != null)
			{
				return ConfigAsset.ImpactDuration;
			}
			return 0f;
		}
	}

	public static float ConvertImpactVelocityToImpactRadius(Vector3 impactVelocity)
	{
		if (ConfigAsset != null)
		{
			return Mathf.Clamp(impactVelocity.magnitude * ConfigAsset.ForceToImpactRadius, ConfigAsset.MinImpactRadius, ConfigAsset.MaxImpactRadius);
		}
		return 0f;
	}

	public static float EvaluateImpactGrowthCurve(float t)
	{
		if (ConfigAsset != null)
		{
			return ConfigAsset.ImpactRadiusGrowthCurve.Evaluate(t);
		}
		return 0f;
	}

	public static float EvaluateImpactAlphaCurve(float t)
	{
		if (ConfigAsset != null)
		{
			return ConfigAsset.ImpactAlphaCurve.Evaluate(t);
		}
		return 0f;
	}
}
[DisallowMultipleComponent]
public class GameTeleportRestriction : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool spectatorsAllowed = true;

	[SerializeField]
	private bool allTeamsAllowed = true;

	[SerializeField]
	private GameTeam[] allowedTeams;

	[SerializeField]
	private TeleportRegionTagType requiredTag = TeleportRegionTagType.DEFAULT;

	public bool LocalPlayerCanTeleport { get; private set; }

	private void Awake()
	{
		LocalPlayerCanTeleport = true;
	}

	public void UpdateRestrictions(bool isGameRunning, bool localPlayerIsSpectator, GameTeam localPlayerTeam, TeleportRegionTagType playerTag)
	{
		if (!isGameRunning)
		{
			LocalPlayerCanTeleport = true;
			return;
		}
		if (localPlayerIsSpectator)
		{
			LocalPlayerCanTeleport = spectatorsAllowed;
			return;
		}
		if (allTeamsAllowed)
		{
			LocalPlayerCanTeleport = true;
		}
		else
		{
			LocalPlayerCanTeleport = false;
			for (int i = 0; i < allowedTeams.Length; i++)
			{
				if (allowedTeams[i] == localPlayerTeam)
				{
					LocalPlayerCanTeleport = true;
					break;
				}
			}
		}
		LocalPlayerCanTeleport &= requiredTag == TeleportRegionTagType.DEFAULT || requiredTag == playerTag;
	}
}
