[DisallowMultipleComponent]
public class NetworkDataManager : Photon.MonoBehaviour
{
	public static NetworkDataManager Instance;

	private Dictionary<string, Action<object>> networkDataCallbackMap = new Dictionary<string, Action<object>>();

	protected override void Awake()
	{
		base.Awake();
		Instance = this;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Instance == this)
		{
			Instance = null;
		}
	}

	public void RegisterCallback(string key, Action<object> callback)
	{
		if (networkDataCallbackMap.ContainsKey(key))
		{
			Dictionary<string, Action<object>> dictionary;
			string key2;
			(dictionary = networkDataCallbackMap)[key2 = key] = (Action<object>)Delegate.Combine(dictionary[key2], callback);
		}
		else
		{
			networkDataCallbackMap[key] = callback;
		}
	}

	public void UnregisterCallback(string key, Action<object> callback)
	{
		if (networkDataCallbackMap.ContainsKey(key))
		{
			Dictionary<string, Action<object>> dictionary;
			string key2;
			(dictionary = networkDataCallbackMap)[key2 = key] = (Action<object>)Delegate.Remove(dictionary[key2], callback);
			if (networkDataCallbackMap[key] == null)
			{
				networkDataCallbackMap.Remove(key);
			}
		}
	}

	private void OnPhotonCustomRoomPropertiesChanged(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		foreach (string item in propertiesThatChanged.Keys.OfType<string>())
		{
			if (networkDataCallbackMap.TryGetValue(item, out var value))
			{
				value(propertiesThatChanged[item]);
			}
		}
	}
}
public class OccupiableSpawnPoint : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool automaticallyRelease = true;

	[SerializeField]
	private float sphereCheckRadius = 0.25f;

	[SerializeField]
	private Vector3 sphereCheckCenter = Vector3.zero;

	public bool Occupied { get; private set; }

	public event Action<OccupiableSpawnPoint> AutomaticallyReleasedEvent;

	private void Update()
	{
		if (!Occupied || !automaticallyRelease)
		{
			return;
		}
		Vector3 position = base.transform.TransformPoint(sphereCheckCenter);
		if (!Physics.CheckSphere(position, sphereCheckRadius, 226894848, QueryTriggerInteraction.Ignore))
		{
			if (this.AutomaticallyReleasedEvent != null)
			{
				this.AutomaticallyReleasedEvent(this);
			}
			Release();
		}
	}

	public void Occupy()
	{
		Occupied = true;
	}

	public void Release()
	{
		Occupied = false;
	}

	private void OnDrawGizmos()
	{
		if (automaticallyRelease)
		{
			Gizmos.color = ((!Occupied) ? Color.green : Color.red);
			Gizmos.DrawWireSphere(base.transform.TransformPoint(sphereCheckCenter), sphereCheckRadius);
		}
	}
}
[DisallowMultipleComponent]
public class PlayerInteractionRestriction : Photon.MonoBehaviour
{
	[Header("Pre Game State")]
	public bool AllowedInPreGame = true;

	[Header("Playing Game State")]
	public bool AllowSpectators = true;

	public bool AllowAllActiveTeams = true;

	public GameTeam[] AllowedTeams;

	protected GameManager gameManager;

	public bool ForceRestricted { get; set; }

	protected virtual void Start()
	{
		gameManager = RecRoomSceneManager.Instance.GameManager;
	}

	public virtual bool PlayerInteractionAllowed(PhotonPlayer player)
	{
		if (ForceRestricted)
		{
			return false;
		}
		if (gameManager == null)
		{
			return true;
		}
		if (gameManager.CurrentState != GameStates.GAME_RUNNING && AllowedInPreGame)
		{
			return true;
		}
		bool flag = gameManager.TeamManager.IsPlayerSpectator(player);
		if (flag && AllowSpectators)
		{
			return true;
		}
		if (!flag && AllowAllActiveTeams)
		{
			return true;
		}
		if (AllowedTeams != null && AllowedTeams.Length > 0)
		{
			GameTeam playerTeam = gameManager.TeamManager.GetPlayerTeam(player);
			if (playerTeam != GameTeam.INVALID && AllowedTeams.Contains(playerTeam))
			{
				return true;
			}
		}
		return false;
	}
}
public class Powerup : Photon.MonoBehaviour
{
	[SerializeField]
	private Transform visualRoot;

	[SerializeField]
	private float value = 1f;

	[Header("Reset")]
	[SerializeField]
	protected bool automaticallyResets;

	[SerializeField]
	protected float resetDuration = 10f;

	private SynchronizedField<bool> _isEnabled;

	private SynchronizedField<bool> _isAlive;

	protected SynchronizedTimer resetTimer;

	public float PowerupValue => value;

	public bool IsEnabled
	{
		get
		{
			return _isEnabled.Get();
		}
		protected set
		{
			_isEnabled.ForceSet(value);
		}
	}

	public bool IsAlive
	{
		get
		{
			return _isAlive.Get();
		}
		protected set
		{
			_isAlive.ForceSet(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_isEnabled = new SynchronizedField<bool>(this, "IS_ENABLED", defaultValue: true, SetterPermissionMode.MASTER, OnIsEnabledChange);
		_isAlive = new SynchronizedField<bool>(this, "IS_ALIVE", defaultValue: true, SetterPermissionMode.MASTER, OnIsAliveChange);
		resetTimer = new SynchronizedTimer(this, "POWERUP", SetterPermissionMode.MASTER);
	}

	protected virtual void Start()
	{
		OnIsEnabledChange();
		OnIsAliveChange();
	}

	protected virtual void Update()
	{
		if (PhotonNetwork.isMasterClient && automaticallyResets && !IsAlive && resetTimer.TimerOver)
		{
			IsAlive = true;
		}
	}

	private void OnIsEnabledChange()
	{
		base.gameObject.SetActive(IsEnabled);
	}

	private void OnIsAliveChange()
	{
		visualRoot.gameObject.SetActive(IsAlive);
	}

	public void MasterDisable()
	{
		if (PhotonNetwork.isMasterClient)
		{
			IsEnabled = false;
			IsAlive = false;
		}
	}

	public void MasterEnable()
	{
		if (PhotonNetwork.isMasterClient)
		{
			IsEnabled = true;
			IsAlive = true;
		}
	}

	public void MasterOnPickup()
	{
		if (PhotonNetwork.isMasterClient)
		{
			IsAlive = false;
			if (automaticallyResets)
			{
				resetTimer.StartTimer(resetDuration);
			}
		}
	}
}
[DisallowMultipleComponent]
public class RecRoomSceneManager : Photon.MonoBehaviour
{
	[SerializeField]
	private string friendlyName;

	[Header("Scene Settings")]
	[SerializeField]
	private SceneAFKSettings afkSettings;

	[SerializeField]
	private SceneFxManager audioSettings;

	[SerializeField]
	private SceneInteractionSettings interactionSettings;

	[SerializeField]
	private ScenePhysicsSettings physicsSettings;

	[SerializeField]
	private ScenePostEffectSettings postEffectSettings;

	[SerializeField]
	private SceneTeleportSettings sceneTeleportSettings;

	[SerializeField]
	private SceneSpawnManager spawnManager;

	[SerializeField]
	private ScenePresenceSettings presenceSettings;

	private List<IRecRoomSceneComponent> recRoomSceneComponents = new List<IRecRoomSceneComponent>();

	protected bool wasMasterClient;

	private bool isApplicationQuitting;

	private Coroutine changeActivityCoroutine;

	public GameManager GameManager { get; private set; }

	public SceneAFKSettings AFKSettings => afkSettings;

	public SceneFxManager FxManager => audioSettings;

	public SceneInteractionSettings InteractionSettings => interactionSettings;

	public ScenePhysicsSettings PhysicsSettings => physicsSettings;

	public ScenePostEffectSettings PostEffectSettings => postEffectSettings;

	public SceneTeleportSettings SceneTeleportSettings => sceneTeleportSettings;

	public SceneSpawnManager SpawnManager => spawnManager;

	public ScenePresenceSettings PresenceSettings => presenceSettings;

	public static string CurrentSceneFriendlyName => (!(Instance != null) || string.IsNullOrEmpty(Instance.friendlyName)) ? CurrentSceneName : Instance.friendlyName;

	public static string CurrentSceneName => SceneManagerHelper.ActiveSceneName;

	public static bool IsCurrentSceneAValidActivity => Instance != null;

	public static RecRoomSceneManager Instance { get; private set; }

	public static bool IsInitialized => Instance != null;

	protected override void Awake()
	{
		base.Awake();
		if (Instance == null)
		{
			Instance = this;
		}
		GameManager = UnityEngine.Object.FindObjectOfType<GameManager>();
		recRoomSceneComponents.Add(AFKSettings);
		recRoomSceneComponents.Add(FxManager);
		recRoomSceneComponents.Add(InteractionSettings);
		recRoomSceneComponents.Add(PhysicsSettings);
		recRoomSceneComponents.Add(PostEffectSettings);
		recRoomSceneComponents.Add(SceneTeleportSettings);
		recRoomSceneComponents.Add(PresenceSettings);
		recRoomSceneComponents.Add(SpawnManager);
	}

	protected virtual void Start()
	{
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].OnStart(this);
		}
		if (PhotonNetwork.isMasterClient)
		{
			wasMasterClient = true;
			SpawnManager.MasterSpawnNewPlayer(PhotonNetwork.player);
		}
	}

	private void OnApplicationQuit()
	{
		isApplicationQuitting = true;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].OnDestroy();
		}
		if (!isApplicationQuitting)
		{
			if (SingletonMonoBehaviour<TutorialManager>.Instance != null && SingletonMonoBehaviour<TutorialManager>.Instance.IsOOBERunning)
			{
				PhotonNetwork.player.SetCustomProperties("prev_activity", "oobe");
			}
			else
			{
				PhotonNetwork.player.SetCustomProperties("prev_activity", CurrentSceneName);
			}
		}
		StopAllCoroutines();
		if (Instance == this)
		{
			Instance = null;
		}
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.OnRecRoomSceneManagerDestroyed();
		}
	}

	protected virtual void Update()
	{
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].Update();
		}
	}

	public void SwitchActivity(string activity, bool createPrivateRoom)
	{
		changeActivityCoroutine = StartCoroutine(SwitchActivityCoroutine(activity, createPrivateRoom));
	}

	private IEnumerator SwitchActivityCoroutine(string activity, bool createPrivateRoom)
	{
		string[] expectedUsers = null;
		if (Player.LocalPlayer != null && Player.LocalPlayer.PlayerParty.PartySize > 1)
		{
			expectedUsers = Player.LocalPlayer.PlayerParty.GetExpectedPhotonUsers();
		}
		if (PUNNetworkManager.Instance.IsInLockerRoom)
		{
			base.photonView.RPC("RpcPlayerSwitchedActivity", PhotonTargets.Others, Player.LocalPlayer.PlayerName, activity);
		}
		if (Player.LocalPlayer != null)
		{
			yield return Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: true);
		}
		PUNNetworkManager.Instance.SwitchActivity(activity, expectedUsers, createPrivateRoom);
		changeActivityCoroutine = null;
	}

	[PunRPC]
	public void RpcPlayerSwitchedActivity(string playerName, string targetActivity)
	{
		string activityFriendlyName = PUNNetworkManager.Instance.GetActivityFriendlyName(targetActivity);
		if (targetActivity != "lockerroom" && targetActivity != "dormroom" && !string.IsNullOrEmpty(activityFriendlyName))
		{
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, string.Format("{0} went to {1}", playerName.Truncate(12, "..."), activityFriendlyName), 3f);
		}
	}

	public void JoinPlayer(ulong playerId, bool bringParty = true)
	{
		changeActivityCoroutine = StartCoroutine(JoinPlayerCoroutine(playerId, bringParty));
	}

	private IEnumerator JoinPlayerCoroutine(ulong playerId, bool bringParty)
	{
		string playerIdStr = playerId.ToString();
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			if (photonPlayer.userId == playerIdStr)
			{
				yield break;
			}
		}
		string[] expectedUsers = null;
		if (bringParty && Player.LocalPlayer != null && Player.LocalPlayer.PlayerParty.PartySize > 1)
		{
			expectedUsers = Player.LocalPlayer.PlayerParty.GetExpectedPhotonUsers();
		}
		yield return Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: true);
		PUNNetworkManager.Instance.JoinPlayer(playerId, expectedUsers);
		changeActivityCoroutine = null;
	}

	public void JoinRoom(string roomName)
	{
		changeActivityCoroutine = StartCoroutine(JoinRoomCoroutine(roomName));
	}

	private IEnumerator JoinRoomCoroutine(string roomName)
	{
		string[] expectedUsers = null;
		if (Player.LocalPlayer != null && Player.LocalPlayer.PlayerParty.PartySize > 1)
		{
			expectedUsers = Player.LocalPlayer.PlayerParty.GetExpectedPhotonUsers();
		}
		yield return Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: true);
		PUNNetworkManager.Instance.JoinRoom(roomName, expectedUsers);
		changeActivityCoroutine = null;
	}

	[PunRPC]
	protected void RpcSpawnNewPlayer(Vector3 spawnPosition, Quaternion spawnRotation)
	{
		SpawnManager.SpawnNewPlayer(spawnPosition, spawnRotation);
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].SetLocalPlayerSettings();
		}
	}

	public void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (PhotonNetwork.isMasterClient)
		{
			SpawnManager.MasterSpawnNewPlayer(newPlayer);
		}
	}

	public virtual void OnMasterClientSwitched(PhotonPlayer newMasterClient)
	{
		if (!PhotonNetwork.isMasterClient && wasMasterClient)
		{
			StopAllCoroutines();
			wasMasterClient = false;
		}
		else
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			wasMasterClient = true;
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				if (PhotonNetwork.playerList[i].ToPlayer() == null)
				{
					SpawnManager.MasterSpawnNewPlayer(PhotonNetwork.playerList[i]);
				}
			}
		}
	}
}
