[RequireComponent(typeof(PhotonView))]
public abstract class SpawnPoint : Photon.MonoBehaviour
{
	[SerializeField]
	private bool testsForOverlap = true;

	private const float COOLDOWN = 2f;

	private const float PLAYER_OVERLAP_MAX_HEIGHT = 2f;

	public const float PLAYER_OVERLAP_RADIUS = 0.5f;

	[NonSerialized]
	public bool SpawnPointEnabled = true;

	private SynchronizedField<float> _lastUseTime;

	public float LastUseTime
	{
		get
		{
			return _lastUseTime.Get();
		}
		private set
		{
			_lastUseTime.ForceSet(value);
		}
	}

	public float TimeSinceLastUse => (float)PhotonNetwork.time - LastUseTime;

	public bool IsOnCooldown => testsForOverlap && TimeSinceLastUse <= 2f;

	public bool IsOverlappingPlayer => testsForOverlap && Physics.CheckCapsule(base.transform.position, base.transform.position + Vector3.up * 2f, 0.5f, 1053184);

	protected abstract Color GizmoColor { get; }

	protected override void Awake()
	{
		base.Awake();
		_lastUseTime = new SynchronizedField<float>(this, "LAST_USE_TIME", 0f, SetterPermissionMode.MASTER);
	}

	public void MasterUse()
	{
		if (PhotonNetwork.isMasterClient)
		{
			LastUseTime = (float)PhotonNetwork.time;
		}
	}

	protected virtual void OnDrawGizmos()
	{
		Gizmos.color = Color.blue;
		Gizmos.DrawLine(base.transform.position, base.transform.position + base.transform.forward * 1.5f);
		Gizmos.color = GizmoColor;
		Gizmos.DrawSphere(base.transform.position, 0.5f);
	}
}
public class TeleportationPortal : UnityEngine.MonoBehaviour
{
	public Transform Target;

	[Header("Interactions")]
	[SerializeField]
	private bool supportsHandInteraction = true;

	[Header("Target Activity")]
	[SerializeField]
	private bool supportsActivityLoading;

	[SerializeField]
	private string destinationActivity = string.Empty;

	[Tooltip("If the user can teleport with a tool in hand?")]
	public bool CanCarryTools;

	public Renderer HighlightRenderer;

	[SerializeField]
	private int highlightRendererMaterialIndex;

	[SerializeField]
	private Color highlightColor = Color.cyan;

	private Material[] highlightMaterials;

	private Material[] defaultMaterials;

	[HideInInspector]
	public Vector3? TargetPositionOverride;

	[HideInInspector]
	public Quaternion? TargetRotationOverride;

	private bool _highlight;

	public Vector3 DestinationPosition
	{
		get
		{
			if (TargetPositionOverride.HasValue)
			{
				return TargetPositionOverride.Value;
			}
			if (Target != null)
			{
				return Target.transform.position;
			}
			return base.transform.position;
		}
	}

	public Vector3 DestinationForward
	{
		get
		{
			Quaternion quaternion = base.transform.rotation;
			if (TargetRotationOverride.HasValue)
			{
				quaternion = TargetRotationOverride.Value;
			}
			else if (Target != null)
			{
				quaternion = Target.transform.rotation;
			}
			return quaternion * Vector3.forward;
		}
	}

	public virtual bool SupportsPlayerRespawn => false;

	public bool SupportsActivityLoading => supportsActivityLoading;

	public bool SupportsHandInteraction => supportsHandInteraction;

	public string DestinationActivity => destinationActivity;

	public bool Highlight
	{
		get
		{
			return _highlight;
		}
		set
		{
			if (HighlightRenderer != null && _highlight != value)
			{
				_highlight = value;
				HighlightRenderer.materials = ((!_highlight) ? defaultMaterials : highlightMaterials);
			}
		}
	}

	public virtual bool IsValid => base.isActiveAndEnabled && (Target != null || SupportsActivityLoading || SupportsPlayerRespawn || TargetPositionOverride.HasValue);

