[DisallowMultipleComponent]
public class PlayerAnalytics : Photon.MonoBehaviour
{
	private string activityName = "lockerroom";

	private Player thisPlayer;

	private bool joinedEmptyActivityTracking;

	private float joinedEmptyActivityTime;

	private bool isLogActivityEnded;

	private float startTime;

	private void Start()
	{
		thisPlayer = GetComponent<Player>();
		if (base.isLocal)
		{
			int roomPlayerCount = PUNNetworkManager.Instance.GetRoomPlayerCount();
			if (PhotonNetwork.inRoom && roomPlayerCount == 1 && PUNNetworkManager.Instance.AvailableSpaceInRoom > 0)
			{
				joinedEmptyActivityTracking = true;
				joinedEmptyActivityTime = Time.unscaledTime;
				RecnetAnalyticsHelper.CricketStart();
			}
			activityName = RecRoomSceneManager.CurrentSceneName;
			AnalyticsHelper.ActivityLoad(activityName, roomPlayerCount);
			UnityEngine.Debug.Log($"Player joined activity \"{RecRoomSceneManager.CurrentSceneFriendlyName}\" with playerCount {roomPlayerCount}");
			startTime = Time.unscaledTime;
			thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: false, appQuit: false);
			LogActivityEnded();
		}
	}

	private void OnApplicationQuit()
	{
		if (base.isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: false, appQuit: true);
			LogActivityEnded();
		}
	}

	public void OnPhotonPlayerConnected(PhotonPlayer otherPlayer)
	{
		if (base.isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: true, appQuit: false);
		}
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		if (base.isLocal)
		{
			AnalyticsHelper.UserHandGesture(myHand, otherHand, gesture);
		}
	}

	private void ProcessJoinedEmptyActivityEnded(bool anotherPlayerJoined, bool appQuit)
	{
		if (joinedEmptyActivityTracking)
		{
			float num = Time.unscaledTime - joinedEmptyActivityTime;
			AnalyticsHelper.ActivityJoinedEmpty(num, anotherPlayerJoined, appQuit);
			if (!appQuit)
			{
				RecnetAnalyticsHelper.CricketEnd(anotherPlayerJoined, num);
			}
			joinedEmptyActivityTracking = false;
		}
	}

	private void LogActivityEnded()
	{
		if (!isLogActivityEnded)
		{
			AnalyticsHelper.ActivityUnload(activityName, Time.unscaledTime - startTime);
			isLogActivityEnded = true;
		}
	}
}
public static class RecnetAnalyticsHelper
{
	private static bool IsReady => Profiles.LocalProfile != null;

	public static void CricketStart()
	{
		if (IsReady)
		{
			string currentSceneName = RecRoomSceneManager.CurrentSceneName;
			Analytics.SendEvent(currentSceneName, "cricket", "started", null, PhotonNetwork.countOfPlayers, PhotonNetwork.countOfRooms);
		}
	}

	public static void CricketEnd(bool anotherPlayerJoined, float aloneDuration)
	{
		if (IsReady)
		{
			string currentSceneName = RecRoomSceneManager.CurrentSceneName;
			Analytics.SendEvent(currentSceneName, "cricket", (!anotherPlayerJoined) ? "changed activity" : "someone joined", aloneDuration, PhotonNetwork.countOfPlayers, PhotonNetwork.countOfRooms);
		}
	}

	public static void VoteKicked(float userPercent, int userCount, int duration)
	{
		if (IsReady)
		{
			string label = ((!(RecRoomSceneManager.Instance != null) || !(RecRoomSceneManager.Instance.GameManager != null)) ? string.Empty : RecRoomSceneManager.Instance.GameManager.CurrentState.ToString());
			Analytics.SendEvent(RecRoomSceneManager.CurrentSceneName, "VoteKicked", label, userPercent, userCount, duration);
		}
	}

	public static void VoteKickInitiated(Player sourcePlayer, Player targetPlayer)
	{
		if (IsReady)
		{
			Analytics.SendEvent(RecRoomSceneManager.CurrentSceneName, "VoteKickInitiator", sourcePlayer.PlayerName, sourcePlayer.PlayerId, targetPlayer.PlayerId);
		}
	}
}
