public static class SharedMicrophone
{
	private static Dictionary<string, AudioClip> microphones = new Dictionary<string, AudioClip>();

	private static AudioClip nullMicrophone = null;

	public static AudioClip GetMicrophone(string device, int suggestedFrequency)
	{
		AudioClip value = null;
		if (device == null)
		{
			if (nullMicrophone == null)
			{
				nullMicrophone = CreateMicrophone(device, suggestedFrequency);
			}
			value = nullMicrophone;
		}
		else if (!microphones.TryGetValue(device, out value))
		{
			value = CreateMicrophone(device, suggestedFrequency);
			microphones.Add(device, value);
		}
		return value;
	}

	private static AudioClip CreateMicrophone(string device, int suggestedFrequency)
	{
		Microphone.GetDeviceCaps(device, out var minFreq, out var maxFreq);
		int frequency = suggestedFrequency;
		if (suggestedFrequency < minFreq || (maxFreq != 0 && suggestedFrequency > maxFreq))
		{
			frequency = maxFreq;
		}
		return Microphone.Start(device, loop: true, 1, frequency);
	}
}
[DisallowMultipleComponent]
public class ToolAudio : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private RecRoomAudioClip onPickup;

	[SerializeField]
	private RecRoomAudioClip onRelease;

	[SerializeField]
	private RecRoomAudioClip onDrop;

	[SerializeField]
	private RecRoomAudioClip onReset;

	[SerializeField]
	private RecRoomAudioClip onApplyForceLocal;

	[SerializeField]
	private RecRoomAudioClip onApplyForceRemote;

	private float lastApplyForceTime;

	public void OnPickup()
	{
		AudioManager.Play3DSFX(onPickup, base.transform.position);
	}

	public void OnRelease(Vector3 releaseVelocity)
	{
		RecRoomAudioClip clip = ((!(releaseVelocity.magnitude < 0.5f)) ? onRelease : onDrop);
		AudioManager.Play3DSFX(clip, base.transform.position);
	}

	public void OnReset()
	{
		AudioManager.Play3DSFX(onReset, base.transform.position);
	}

	public void OnApplyForce(PhotonPlayer photonPlayer, Vector3 position)
	{
		if (Time.time - lastApplyForceTime > 0.25f)
		{
			lastApplyForceTime = Time.time;
			AudioManager.Play3DSFX((photonPlayer == null || !photonPlayer.isLocal) ? onApplyForceRemote : onApplyForceLocal, position);
		}
	}
}
