public class MessagesMenuController : MenuController
{
	[Serializable]
	private class MessageDetailMenuControllerMapping
	{
		public RecNet.Message.MessageType MessageType;

		public MessageDetailMenuController MenuController;
	}

	[SerializeField]
	private MessageSummaryView messagePanelPrefab;

	[SerializeField]
	private RectTransform messageList;

	[SerializeField]
	private RectTransform noMessagesPanel;

	[SerializeField]
	private List<MessageDetailMenuControllerMapping> messageDetailMenuControllers;

	private List<MessageSummaryView> messagePanels = new List<MessageSummaryView>();

	private MessageDetailMenuController messageDetailMenu;

	public event Action<MessagesMenuController> MessageReceived;

	public override void Initialize(PlayerMenu playerMenu)
	{
		base.Initialize(playerMenu);
		Messages.OnMessageListUpdated += OnMessageListUpdated;
		foreach (MessageDetailMenuControllerMapping messageDetailMenuController in messageDetailMenuControllers)
		{
			messageDetailMenuController.MenuController.Visible = false;
		}
		messagePanelPrefab.gameObject.SetActive(value: false);
		PUNNetworkManager.Instance.PhotonPlayerDisconnected += OnPhotonPlayerDisconnected;
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (base.Owner != null)
		{
			Profiles.OnProfileUpdated += OnProfileUpdated;
			PlayerPresenceManager.OnPlayerPresenceUpdated += OnPlayerPresenceUpdated;
			Images.OnProfileImageUpdated += OnProfileImageUpdated;
		}
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		if (base.Owner != null)
		{
			Profiles.OnProfileUpdated -= OnProfileUpdated;
			PlayerPresenceManager.OnPlayerPresenceUpdated -= OnPlayerPresenceUpdated;
			Images.OnProfileImageUpdated -= OnProfileImageUpdated;
		}
	}

	private void OnDestroy()
	{
		Messages.OnMessageListUpdated -= OnMessageListUpdated;
		PUNNetworkManager.Instance.PhotonPlayerDisconnected -= OnPhotonPlayerDisconnected;
	}

	public override void Refresh()
	{
		base.Refresh();
		if (base.Owner != null)
		{
			RefreshMessageList();
		}
	}

	private void RemoveStaleMessages()
	{
		RecNet.Message[] array = Messages.MessageList.ToArray();
		foreach (RecNet.Message message in array)
		{
			if (message.Type == RecNet.Message.MessageType.VoteToKick)
			{
				if (Player.Find(message.FromPlayerId) == null)
				{
					Messages.DeleteMessage(message.Id);
				}
			}
			else if ((message.Type == RecNet.Message.MessageType.GameInvite || message.Type == RecNet.Message.MessageType.GameInviteDeclined || message.Type == RecNet.Message.MessageType.GameJoinFailed || message.Type == RecNet.Message.MessageType.PartyActivitySwitch) && Player.Find(message.FromPlayerId) != null)
			{
				Messages.DeleteMessage(message.Id);
			}
		}
	}

	private void RefreshMessageList()
	{
		RemoveStaleMessages();
		int count = Messages.MessageList.Count;
		while (count > messagePanels.Count)
		{
			MessageSummaryView messageSummaryView = UnityEngine.Object.Instantiate(messagePanelPrefab);
			messageSummaryView.transform.SetParent(messageList, worldPositionStays: false);
			messageSummaryView.gameObject.SetActive(value: true);
			messageSummaryView.OnSelected += OnMessagePanelSelected;
			messagePanels.Add(messageSummaryView);
		}
		for (int i = 0; i < count; i++)
		{
			messagePanels[i].gameObject.SetActive(value: true);
			messagePanels[i].Message = Messages.MessageList[count - 1 - i];
			RefreshPanel(messagePanels[i]);
		}
		for (int j = count; j < messagePanels.Count; j++)
		{
			messagePanels[j].gameObject.SetActive(value: false);
		}
		noMessagesPanel.gameObject.SetActive(count == 0);
		if (messageDetailMenu != null && messageDetailMenu.Visible && !Messages.MessageList.Any((RecNet.Message m) => m.Id == messageDetailMenu.Message.Id))
		{
			messageDetailMenu.Visible = false;
		}
		if (Messages.MessageList.Count > 0)
		{
			List<ulong> list = Messages.MessageList.Select((RecNet.Message m) => m.FromPlayerId).ToList();
			Profiles.RefreshCachedProfiles(list);
			PlayerPresenceManager.RefreshCachedPlayerPresences(list);
		}
	}

	private void RefreshPanel(MessageSummaryView messagePanel)
	{
		messagePanel.SenderName = Profiles.GetProfileFromCache(messagePanel.Message.FromPlayerId)?.DisplayName;
		messagePanel.Description = GetMessageDescription(messagePanel.Message);
		RefreshPanelSenderImage(messagePanel);
		if (messageDetailMenu != null && messageDetailMenu.Visible && messageDetailMenu.Message.Id == messagePanel.Message.Id)
		{
			messageDetailMenu.SetMessage(messagePanel.Message);
		}
	}

	private string GetMessageDescription(RecNet.Message message)
	{
		switch (message.Type)
		{
		case RecNet.Message.MessageType.GameInvite:
		case RecNet.Message.MessageType.PartyActivitySwitch:
			return "Game Invite";
		case RecNet.Message.MessageType.GameInviteDeclined:
			return "Game Invite Declined";
		case RecNet.Message.MessageType.GameJoinFailed:
		{
			int num = (int)message.Details;
			return (num != 0) ? ("Failed To Join Your Game (+" + num + " party members)") : "Failed To Join Your Game";
		}
		case RecNet.Message.MessageType.FriendInvite:
			return "Friend Invite";
		case RecNet.Message.MessageType.VoteToKick:
			return "Vote to kick?";
		default:
			UnityEngine.Debug.LogError("Unknown message type");
			return "<unknown>";
		}
	}

	private void RefreshPanelSenderImage(MessageSummaryView messagePanel)
	{
		Profile profileFromCache = Profiles.GetProfileFromCache(messagePanel.Message.FromPlayerId);
		Texture2D texture2D = Images.GetProfileImageFromCache(messagePanel.Message.FromPlayerId);
		if (texture2D == null || profileFromCache == null || !profileFromCache.Verified)
		{
			texture2D = Player.LocalPlayer.DefaultProfileImage;
		}
		messagePanel.SenderProfileImage = texture2D;
		if (messageDetailMenu != null && messageDetailMenu.Message.Id == messagePanel.Message.Id)
		{
			messageDetailMenu.RefreshSenderImage();
		}
	}

	private void OnMessageListUpdated(Messages.UpdateType updateType)
	{
		if (base.Owner != null)
		{
			RefreshMessageList();
			if (updateType == Messages.UpdateType.Add && this.MessageReceived != null)
			{
				this.MessageReceived(this);
			}
		}
	}

	private void OnProfileImageUpdated(ulong id, Texture2D image)
	{
		foreach (MessageSummaryView item in GetSummariesForMessagesFromPlayer(id))
		{
			RefreshPanelSenderImage(item);
		}
	}

	private void OnProfileUpdated(ulong id, Profile profile)
	{
		foreach (MessageSummaryView item in GetSummariesForMessagesFromPlayer(id))
		{
			RefreshPanel(item);
		}
	}

	private void OnPlayerPresenceUpdated(ulong id, PlayerPresence playerPresence)
	{
		foreach (MessageSummaryView item in GetSummariesForMessagesFromPlayer(id))
		{
			RefreshPanel(item);
		}
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (!ulong.TryParse(player.userId, out var result))
		{
			return;
		}
		bool flag = false;
		foreach (MessageSummaryView item in GetSummariesForMessagesFromPlayer(result))
		{
			if (item.Message.Type == RecNet.Message.MessageType.VoteToKick)
			{
				if (messageDetailMenu != null && messageDetailMenu.Visible && messageDetailMenu.Message.Id == item.Message.Id)
				{
					messageDetailMenu.CloseMessage();
				}
				messagePanels.Remove(item);
				if (item.Message != null)
				{
					Messages.DeleteMessage(item.Message.Id);
				}
				flag = true;
			}
		}
		if (flag)
		{
			Refresh();
		}
	}

	private IEnumerable<MessageSummaryView> GetSummariesForMessagesFromPlayer(ulong id)
	{
		foreach (MessageSummaryView messagePanel in messagePanels)
		{
			if (!messagePanel.gameObject.activeSelf)
			{
				break;
			}
			if (messagePanel.Message.FromPlayerId == id)
			{
				yield return messagePanel;
			}
		}
	}

	private void OnMessagePanelSelected(long messageId)
	{
		RecNet.Message message = Messages.MessageList.FirstOrDefault((RecNet.Message m) => m.Id == messageId);
		if (message != null)
		{
			ShowMessageDetails(message);
		}
	}

	public void ShowLatestMessage()
	{
		RecNet.Message message = Messages.MessageList.LastOrDefault();
		if (message != null)
		{
			ShowMessageDetails(message);
		}
	}

	private void ShowMessageDetails(RecNet.Message message)
	{
		if (messageDetailMenu != null)
		{
			messageDetailMenu.Visible = false;
		}
		MessageDetailMenuControllerMapping messageDetailMenuControllerMapping = messageDetailMenuControllers.FirstOrDefault((MessageDetailMenuControllerMapping m) => m.MessageType == message.Type);
		if (messageDetailMenuControllerMapping != null)
		{
			messageDetailMenu = messageDetailMenuControllerMapping.MenuController;
			messageDetailMenu.SetMessage(message);
			subMenu = messageDetailMenu;
			messageDetailMenu.Visible = true;
		}
	}
}
public class PanicMenuController : MenuController
{
	[SerializeField]
	private UIPanicPlayerPanel playerPanelPrefab;

	[SerializeField]
	private RectTransform localPlayerList;

	[SerializeField]
	private RectTransform noPeoplePanel;

	private PanicPlayerMenuController playerSpecificMenu;

	private UIPanicPlayerPanel[] localPlayerPanels;

	private bool initialized;

	private void LazyInit()
	{
		if (initialized)
		{
			return;
		}
		playerPanelPrefab.gameObject.SetActive(value: false);
		if (base.Owner != null)
		{
			localPlayerPanels = new UIPanicPlayerPanel[7];
			for (int i = 0; i < localPlayerPanels.Length; i++)
			{
				localPlayerPanels[i] = UnityEngine.Object.Instantiate(playerPanelPrefab);
				localPlayerPanels[i].transform.SetParent(localPlayerList, worldPositionStays: false);
			}
			initialized = true;
		}
		if (subMenu != null)
		{
			playerSpecificMenu = subMenu as PanicPlayerMenuController;
			playerSpecificMenu.PanicMenuController = this;
		}
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (base.Owner != null)
		{
			Images.OnProfileImageUpdated += OnProfileImageUpdated;
		}
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		if (base.Owner != null)
		{
			Images.OnProfileImageUpdated -= OnProfileImageUpdated;
		}
	}

	public override void Refresh()
	{
		base.Refresh();
		if (base.Owner != null)
		{
			LazyInit();
			RefreshLocalSessionPlayers();
		}
	}

	private void RefreshLocalSessionPlayers()
	{
		int num = 0;
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null && num < localPlayerPanels.Length)
			{
				UIPanicPlayerPanel uIPanicPlayerPanel = localPlayerPanels[num];
				num++;
				uIPanicPlayerPanel.gameObject.SetActive(value: true);
				uIPanicPlayerPanel.SetPlayer(player);
				string playerName = player.PlayerName;
				string localPlayerStatus = GetLocalPlayerStatus(player);
				Texture texture = Images.GetProfileImageFromCache(player.PlayerId);
				if (texture == null || !player.PlayerProgression.IsMember)
				{
					texture = Player.LocalPlayer.DefaultProfileImage;
				}
				Color? partyColor = ((!player.PlayerParty.IsInParty) ? ((Color?)null) : player.PlayerParty.PartyColor);
				uIPanicPlayerPanel.PlayerName = playerName;
				uIPanicPlayerPanel.PlayerStatus = localPlayerStatus;
				uIPanicPlayerPanel.PlayerAvatar = texture;
				uIPanicPlayerPanel.PartyColor = partyColor;
				uIPanicPlayerPanel.PlayerLevel = player.PlayerProgression.Level;
				uIPanicPlayerPanel.PlayerIsMember = player.PlayerProgression.IsMember;
				uIPanicPlayerPanel.PlayerDistanceSqrFromLocalPlayer = Player.DistanceSqrBetweenPlayers(Player.LocalPlayer, player);
				if (playerSpecificMenu.Target == player)
				{
					playerSpecificMenu.PlayerName = playerName;
					playerSpecificMenu.PlayerStatus = localPlayerStatus;
					playerSpecificMenu.PlayerAvatar = texture;
					playerSpecificMenu.PartyColor = partyColor;
				}
				if (player.PlayerProgression.IsMember)
				{
					Images.RefreshCachedProfileImage(player.PlayerId);
				}
			}
		}
		for (int j = num; j < localPlayerPanels.Length; j++)
		{
			localPlayerPanels[j].gameObject.SetActive(value: false);
		}
		Array.Sort(localPlayerPanels, (UIPanicPlayerPanel a, UIPanicPlayerPanel b) => a.PlayerDistanceSqrFromLocalPlayer.CompareTo(b.PlayerDistanceSqrFromLocalPlayer));
		for (int num2 = 0; num2 < localPlayerPanels.Length; num2++)
		{
			localPlayerPanels[num2].transform.SetSiblingIndex(num2);
		}
		noPeoplePanel.gameObject.SetActive(num == 0);
	}

	private string GetLocalPlayerStatus(Player player)
	{
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.Append(player.LocalPlayerStatus);
		if (player.PermaGhost)
		{
			stringBuilder.Append(" [GHOSTED]");
		}
		else if (player.Mute)
		{
			stringBuilder.Append(" [MUTED]");
		}
		return stringBuilder.ToString();
	}

	public void ShowPlayerMenu(Player player)
	{
		playerSpecificMenu.InitForPlayer(player);
		playerSpecificMenu.PlayerName = player.PlayerName;
		playerSpecificMenu.PlayerStatus = GetLocalPlayerStatus(player);
		playerSpecificMenu.PlayerAvatar = Images.GetProfileImageFromCache(player.PlayerId);
		playerSpecificMenu.PartyColor = ((!player.PlayerParty.IsInParty) ? ((Color?)null) : player.PlayerParty.PartyColor);
		ShowSubMenu(show: true);
	}

	private void OnProfileImageUpdated(ulong id, Texture2D image)
	{
		if (image == null || !IsPlayerMember(id))
		{
			image = Player.LocalPlayer.DefaultProfileImage;
		}
		if (localPlayerPanels != null)
		{
			for (int i = 0; i < localPlayerPanels.Length; i++)
			{
				if (localPlayerPanels[i].PlayerId == id)
				{
					localPlayerPanels[i].PlayerAvatar = image;
				}
			}
		}
		if (playerSpecificMenu != null && playerSpecificMenu.Target != null && playerSpecificMenu.Target.PlayerId == id)
		{
			playerSpecificMenu.PlayerAvatar = image;
		}
	}

	private bool IsPlayerMember(ulong playerId)
	{
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null && player.PlayerId == playerId)
			{
				return player.PlayerProgression.IsMember;
			}
		}
		return false;
	}
}
