	private void UpdateInputStateForOculus()
	{
		OVRInput.Controller controller = ((hand == HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
		OVRPlugin.Node nodeId = ((hand != HandType.LeftHand) ? OVRPlugin.Node.HandRight : OVRPlugin.Node.HandLeft);
		IsConnected = OVRPlugin.GetNodePresent(nodeId);
		if (!IsConnected)
		{
			IsTracking = false;
		}
		else
		{
			IsTracking = OVRInput.GetControllerPositionTracked(controller) && OVRInput.GetControllerOrientationTracked(controller);
			if (IsTracking)
			{
				OVRPose oVRPose = OVRPlugin.GetNodePose(nodeId, usePhysicsPose: false).ToOVRPose();
				rawControllerTransform.localPosition = oVRPose.position;
				rawControllerTransform.localRotation = oVRPose.orientation;
				if (this.TransformUpdated != null)
				{
					this.TransformUpdated();
				}
			}
		}
		if (IsConnected && OVRManager.hasVrFocus)
		{
			MenuButtonPressed = OVRInput.Get(oculus.MenuButton, controller);
			MenuButtonDown = OVRInput.GetDown(oculus.MenuButton, controller);
			MenuButtonUp = OVRInput.GetUp(oculus.MenuButton, controller);
			TeleportButtonPressed = OVRInput.Get(oculus.TeleportButton, controller);
			TeleportButtonDown = OVRInput.GetDown(oculus.TeleportButton, controller);
			TeleportButtonUp = OVRInput.GetUp(oculus.TeleportButton, controller);
			PushToTalkButtonPressed = OVRInput.Get(oculus.PushToTalkButton, controller);
			PushToTalkButtonDown = OVRInput.GetDown(oculus.PushToTalkButton, controller);
			PushToTalkButtonUp = OVRInput.GetUp(oculus.PushToTalkButton, controller);
			FlyModeModifierButtonPressed = OVRInput.Get(oculus.FlyModeModifierButton, controller);
			FlyModeModifierButtonDown = OVRInput.GetDown(oculus.FlyModeModifierButton, controller);
			FlyModeModifierButtonUp = OVRInput.GetUp(oculus.FlyModeModifierButton, controller);
			TeleportRotateAxis = OVRInput.Get(oculus.RotateAxis, controller);
			TeleportRotateAxisInDeadZone = TeleportRotateAxis.sqrMagnitude <= oculus.RotateAxisDeadzone * oculus.RotateAxisDeadzone;
			oculus.ThumbstickDirectionButtons.Update(TeleportRotateAxis, TeleportRotateAxisInDeadZone);
			RotateRightButtonPressed = oculus.ThumbstickDirectionButtons.GetPressed(AxisButtons.Direction.RIGHT);
			RotateRightButtonDown = oculus.ThumbstickDirectionButtons.GetDown(AxisButtons.Direction.RIGHT);
			RotateRightButtonUp = oculus.ThumbstickDirectionButtons.GetUp(AxisButtons.Direction.RIGHT);
			RotateLeftButtonPressed = oculus.ThumbstickDirectionButtons.GetPressed(AxisButtons.Direction.LEFT);
			RotateLeftButtonDown = oculus.ThumbstickDirectionButtons.GetDown(AxisButtons.Direction.LEFT);
			RotateLeftButtonUp = oculus.ThumbstickDirectionButtons.GetUp(AxisButtons.Direction.LEFT);
			RotateDownButtonPressed = oculus.ThumbstickDirectionButtons.GetPressed(AxisButtons.Direction.DOWN);
			RotateDownButtonDown = oculus.ThumbstickDirectionButtons.GetDown(AxisButtons.Direction.DOWN);
			RotateDownButtonUp = oculus.ThumbstickDirectionButtons.GetUp(AxisButtons.Direction.DOWN);
			PickupAxis = OVRInput.Get(oculus.PickupAxis, controller);
			PickupButtonPressed = OVRInput.Get(oculus.PickupButton, controller);
			PickupButtonDown = OVRInput.GetDown(oculus.PickupButton, controller);
			PickupButtonUp = OVRInput.GetUp(oculus.PickupButton, controller);
			TriggerAxis = OVRInput.Get(oculus.TriggerAxis, controller);
			TriggerButtonPressed = OVRInput.Get(oculus.TriggerButton, controller);
			TriggerButtonDown = OVRInput.GetDown(oculus.TriggerButton, controller);
			TriggerButtonUp = OVRInput.GetUp(oculus.TriggerButton, controller);
			HairPickupButtonPressed = PickupButtonPressed;
			HairPickupButtonDown = PickupButtonDown;
			HairPickupButtonUp = PickupButtonUp;
			HairTriggerButtonPressed = TriggerButtonPressed;
			HairTriggerButtonDown = TriggerButtonDown;
			HairTriggerButtonUp = TriggerButtonUp;
		}
	}

	private void OnNewSteamVrPoses(params object[] args)
	{
		TrackedDevicePose_t[] array = (TrackedDevicePose_t[])args[0];
		ETrackedControllerRole unDeviceType = ((hand == HandType.LeftHand) ? ETrackedControllerRole.LeftHand : ETrackedControllerRole.RightHand);
		steamVrDeviceIndex = (uint)(((int?)OpenVR.System?.GetTrackedDeviceIndexForControllerRole(unDeviceType)) ?? (-1));
		if (steamVrDeviceIndex >= array.Length)
		{
			IsConnected = false;
			IsTracking = false;
			return;
		}
		IsConnected = array[steamVrDeviceIndex].bDeviceIsConnected;
		IsTracking = array[steamVrDeviceIndex].bPoseIsValid;
		if (IsConnected && IsTracking)
		{
			SteamVR_Utils.RigidTransform rigidTransform = new SteamVR_Utils.RigidTransform(array[steamVrDeviceIndex].mDeviceToAbsoluteTracking);
			rawControllerTransform.localPosition = rigidTransform.pos;
			rawControllerTransform.localRotation = rigidTransform.rot;
			if (this.TransformUpdated != null)
			{
				this.TransformUpdated();
			}
		}
	}

	public Coroutine VibrateContinuous(ushort intensity = 1000)
	{
		return StartCoroutine(VibrateContinuousCoroutine(intensity));
	}

	public Coroutine Vibrate(int milliseconds = 1, ushort intensity = 1000)
	{
		return StartCoroutine(VibrateCoroutine(milliseconds, intensity));
	}

	private Coroutine VibrateTouchpad(int milliseconds = 1, ushort intensity = 1000)
	{
		return StartCoroutine(VibrateCoroutine(milliseconds, intensity, useTouchpad: true));
	}

	private IEnumerator VibrateCoroutine(int milliseconds, ushort intensity, bool useTouchpad = false)
	{
		float endTime = Time.unscaledTime + (float)milliseconds / 1000f;
		while (Time.unscaledTime < endTime)
		{
			PulseHaptics(intensity, useTouchpad);
			yield return null;
		}
	}

	private IEnumerator VibrateContinuousCoroutine(ushort intensity, bool useTouchpad = false)
	{
		while (true)
		{
			PulseHaptics(intensity, useTouchpad);
			yield return null;
		}
	}

	private void PulseHaptics(ushort durationMicroseconds, bool useTouchpad)
	{
		switch (CurrentInputMode)
		{
		case InputMode.Debug:
			break;
		case InputMode.SteamVR_Vive:
		case InputMode.SteamVR_Oculus:
			if (IsConnected)
			{
				SteamVR_Controller.Device device = SteamVR_Controller.Input((int)steamVrDeviceIndex);
				if (useTouchpad)
				{
					device.TriggerHapticPulse(durationMicroseconds);
				}
				else
				{
					device.TriggerHapticPulse(durationMicroseconds);
				}
			}
			break;
		case InputMode.Oculus:
			if (IsConnected)
			{
				int num = Mathf.Max(1, durationMicroseconds / 3125);
				if (OculusHapticsClip.Count > num)
				{
					OculusHapticsClip.Reset();
				}
				while (OculusHapticsClip.Count < num)
				{
					OculusHapticsClip.WriteSample(byte.MaxValue);
				}
				OVRHaptics.OVRHapticsChannel oVRHapticsChannel = ((hand != HandType.LeftHand) ? OVRHaptics.RightChannel : OVRHaptics.LeftChannel);
				oVRHapticsChannel.Preempt(OculusHapticsClip);
			}
			break;
		}
	}
}
public class DebugCameraControl : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private KeyCode exitKey = KeyCode.Escape;

	[SerializeField]
	private float yawSpeed = 360f;

	[SerializeField]
	private float pitchSpeed = 180f;

	[SerializeField]
	private float rollSpeed = 180f;

	[SerializeField]
	private float movementSpeed = 6f;

	[SerializeField]
	private float upDownSpeed = 6f;

	private bool GameViewFocused
	{
		get
		{
			return !Cursor.visible;
		}
		set
		{
			Cursor.lockState = (value ? CursorLockMode.Locked : CursorLockMode.None);
			Cursor.visible = !value;
		}
	}

	private void Awake()
	{
		if (false)
		{
			GameViewFocused = false;
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private void Update()
	{
		if (GameViewFocused)
		{
			Vector3 vector = ReadMovementInput();
			Vector3 vector2 = base.transform.right * vector.x + base.transform.forward * vector.z;
			vector2 = Vector3.ProjectOnPlane(Vector3.ClampMagnitude(vector2, 1f), Vector3.up) * movementSpeed;
			vector2 += Vector3.up * vector.y * upDownSpeed;
			base.transform.position += vector2 * Time.deltaTime;
			Vector3 vector3 = ReadLookInput();
			float yAngle = vector3.y * yawSpeed * Time.deltaTime;
			base.transform.Rotate(0f, yAngle, 0f, Space.World);
			float xAngle = (0f - vector3.x) * pitchSpeed * Time.deltaTime;
			base.transform.Rotate(xAngle, 0f, 0f, Space.Self);
			float zAngle = (0f - vector3.z) * rollSpeed * Time.deltaTime;
			base.transform.Rotate(0f, 0f, zAngle, Space.Self);
			if (Input.GetKeyDown(exitKey))
			{
				GameViewFocused = false;
			}
		}
		else if (Input.GetMouseButton(0) || Input.GetMouseButton(1))
		{
			StartCoroutine(DelayedSetGameViewFocused(value: true));
		}
	}

	private IEnumerator DelayedSetGameViewFocused(bool value)
	{
		yield return new WaitForSeconds(0.1f);
		GameViewFocused = value;
	}

	private Vector3 ReadMovementInput()
	{
		return new Vector3(Input.GetAxis("Movement Right"), Input.GetAxis("Movement Up"), Input.GetAxis("Movement Forward"));
	}

	private Vector3 ReadLookInput()
	{
		return new Vector3(Input.GetAxis("Camera Pitch"), Input.GetAxis("Camera Yaw"), 0f);
	}
}
public class FlushOnPostRender : UnityEngine.MonoBehaviour
{
	private static int s_numFlushesThisFrame;

	private static int s_lastFrameCount;

	private void OnPostRender()
	{
		if (OpenVR.Compositor != null)
		{
			Compositor_FrameTiming pTiming = new Compositor_FrameTiming
			{
				m_nSize = (uint)Marshal.SizeOf(typeof(Compositor_FrameTiming))
			};
			OpenVR.Compositor.GetFrameTiming(ref pTiming, 0u);
			if (pTiming.m_nNumFramePresents > 1)
			{
				return;
			}
		}
		if (s_lastFrameCount != Time.frameCount)
		{
			s_lastFrameCount = Time.frameCount;
			s_numFlushesThisFrame = 0;
		}
		if (++s_numFlushesThisFrame <= 3)
		{
			GL.Flush();
		}
	}
}
public class BezierPath
{
	private const int TOTAL_POINTS_PER_BEZIER_CURVE = 4;

	private const int UNIQUE_POINTS_PER_BEZIER_CURVE = 3;

	private const int LENGTH_SEGMENTS = 5;

	private const float LENGTH_SEGMENT_FRACTION = 0.2f;

	private List<Vector3> points;

	private List<float> lengthAtCurve;

	public int CurveCount { get; private set; }

	public float PathLength { get; private set; }

	public BezierPath()
	{
		points = new List<Vector3>();
		lengthAtCurve = new List<float>();
		CurveCount = 0;
		PathLength = 0f;
	}

	public void AddCurve(Vector3 start, Vector3 controlPoint1, Vector3 controlPoint2, Vector3 end)
	{
		if (points.Count == 0)
		{
			points.Add(start);
		}
		else if (Vector3.Distance(start, points[points.Count - 1]) > Mathf.Epsilon)
		{
			UnityEngine.Debug.LogError("Tried to add discontinuity to Bezier Path.");
		}
		AddCurve(controlPoint1, controlPoint2, end);
	}

	public void AddCurve(Vector3 controlPoint1, Vector3 controlPoint2, Vector3 end)
	{
		if (points.Count == 0)
		{
			UnityEngine.Debug.LogError("Tried to add a Bezier Path curve without a starting point.");
		}
		points.Add(controlPoint1);
		points.Add(controlPoint2);
		points.Add(end);
		CurveCount++;
		PathLength += CurveLength(CurveCount - 1);
		lengthAtCurve.Add(PathLength);
	}

	public void Clear()
	{
		points.Clear();
		lengthAtCurve.Clear();
		CurveCount = 0;
		PathLength = 0f;
	}

	public Vector3 EvaluatePath(float t)
	{
		if (CurveCount <= 0)
		{
			return Vector3.zero;
		}
		int num = -1;
		float t2 = 0f;
		float num2 = Mathf.Clamp01(t) * PathLength;
		for (int i = 0; i < CurveCount; i++)
		{
			if (num2 <= lengthAtCurve[i])
			{
				num = i;
				float num3 = ((i != 0) ? lengthAtCurve[i - 1] : 0f);
				float num4 = lengthAtCurve[i] - num3;
				t2 = (num2 - num3) / num4;
				break;
			}
		}
		if (num < 0)
		{
			num = CurveCount - 1;
			t2 = 1f;
		}
		return EvaluateBezierCurve(num, t2);
	}

	public void DrawGizmos()
	{
		for (int i = 0; i < CurveCount; i++)
		{
			DrawGizmosBezierCurve(i);
		}
	}

	private Vector3 EvaluateBezierCurve(int curveIndex, float t)
	{
		Vector3 vector = points[curveIndex * 3];
		Vector3 vector2 = points[curveIndex * 3 + 1];
		Vector3 vector3 = points[curveIndex * 3 + 2];
		Vector3 vector4 = points[curveIndex * 3 + 3];
		float num = 1f - t;
		return vector * num * num * num + vector2 * 3f * num * num * t + vector3 * 3f * num * t * t + vector4 * t * t * t;
	}

	private float CurveLength(int curveIndex)
	{
		float num = 0f;
		float num2 = 0f;
		Vector3 vector = EvaluateBezierCurve(curveIndex, num2);
		for (int i = 0; i < 5; i++)
		{
			num2 += 0.2f;
			Vector3 vector2 = EvaluateBezierCurve(curveIndex, num2);
			num += (vector2 - vector).magnitude;
			vector = vector2;
		}
		return num;
	}

	private void DrawGizmosBezierCurve(int curveIndex)
	{
		Vector3 vector = points[curveIndex * 3];
		Vector3 to = points[curveIndex * 3 + 1];
		Vector3 vector2 = points[curveIndex * 3 + 2];
		Vector3 to2 = points[curveIndex * 3 + 3];
		Gizmos.color = Color.white;
		Gizmos.DrawLine(vector, to);
		Gizmos.DrawLine(vector2, to2);
		Gizmos.color = Color.blue;
		Gizmos.DrawLine(vector, to2);
	}
}
public abstract class AbstractStateMachine
{
	public delegate void OnStateChange(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId);

	public delegate void StateTransition(ushort otherStateId, ushort otherSubStateId);

	public delegate void StateUpdate();

	protected class State
	{
		public StateTransition OnEnter;

		public StateTransition OnExit;

		public StateUpdate OnUpdate;
	}

	public const ushort INVALID_STATE_ID = ushort.MaxValue;

	private Dictionary<uint, State> states = new Dictionary<uint, State>();

	public ushort CurrentStateId { get; private set; }

	public ushort CurrentSubStateId { get; private set; }

	public event OnStateChange StateChangeEvent;

	public AbstractStateMachine()
	{
		CurrentStateId = ushort.MaxValue;
		CurrentSubStateId = ushort.MaxValue;
	}

	private State GetSuperState(ushort superStateId)
	{
		State value = null;
		if (superStateId != ushort.MaxValue)
		{
			states.TryGetValue(GetFullyQualifiedStateId(superStateId, ushort.MaxValue), out value);
		}
		return value;
	}

	private State GetSubState(ushort superStateId, ushort subStateId)
	{
		State value = null;
		if (superStateId != ushort.MaxValue && subStateId != ushort.MaxValue)
		{
			states.TryGetValue(GetFullyQualifiedStateId(superStateId, subStateId), out value);
		}
		return value;
	}

	public void EnterState(ushort nextStateId)
	{
		EnterState(nextStateId, ushort.MaxValue);
	}

	public void EnterState(ushort nextStateId, ushort nextSubStateId)
	{
		EnterState(GetFullyQualifiedStateId(nextStateId, nextSubStateId));
	}

	protected virtual void EnterState(uint nextFullyQualifiedStateId)
	{
		ushort superStateIdFromFullyQualifiedId = GetSuperStateIdFromFullyQualifiedId(nextFullyQualifiedStateId);
		ushort subStateIdFromFullyQualifiedId = GetSubStateIdFromFullyQualifiedId(nextFullyQualifiedStateId);
		bool flag = superStateIdFromFullyQualifiedId != CurrentStateId;
		bool flag2 = subStateIdFromFullyQualifiedId != CurrentSubStateId;
		State subState = GetSubState(CurrentStateId, CurrentSubStateId);
		if ((flag || flag2) && subState != null && subState.OnExit != null)
		{
			subState.OnExit(superStateIdFromFullyQualifiedId, subStateIdFromFullyQualifiedId);
		}
		State superState = GetSuperState(CurrentStateId);
		if (flag && superState != null && superState.OnExit != null)
		{
			superState.OnExit(superStateIdFromFullyQualifiedId, subStateIdFromFullyQualifiedId);
		}
		ushort currentStateId = CurrentStateId;
		ushort currentSubStateId = CurrentSubStateId;
		CurrentStateId = superStateIdFromFullyQualifiedId;
		CurrentSubStateId = subStateIdFromFullyQualifiedId;
		superState = GetSuperState(CurrentStateId);
		if (flag && superState != null && superState.OnEnter != null)
		{
			superState.OnEnter(currentStateId, currentSubStateId);
		}
		subState = GetSubState(CurrentStateId, CurrentSubStateId);
		if ((flag || flag2) && subState != null && subState.OnEnter != null)
		{
			subState.OnEnter(currentStateId, currentSubStateId);
		}
		if (this.StateChangeEvent != null)
		{
			this.StateChangeEvent(superStateIdFromFullyQualifiedId, currentStateId, subStateIdFromFullyQualifiedId, currentSubStateId);
		}
	}

	public void AddState(ushort stateId, StateTransition onEnter, StateTransition onExit, StateUpdate onUpdate)
	{
		AddState(stateId, ushort.MaxValue, onEnter, onExit, onUpdate);
	}

	public void AddState(ushort superStateId, ushort subStateId, StateTransition onEnter, StateTransition onExit, StateUpdate onUpdate)
	{
		AddFullyQualifiedState(GetFullyQualifiedStateId(superStateId, subStateId), onEnter, onExit, onUpdate);
	}

	protected void AddFullyQualifiedState(uint fullyQualifiedStateId, StateTransition onEnter, StateTransition onExit, StateUpdate onUpdate)
	{
		if (!states.ContainsKey(fullyQualifiedStateId))
		{
			states.Add(fullyQualifiedStateId, new State
			{
				OnEnter = onEnter,
				OnExit = onExit,
				OnUpdate = onUpdate
			});
		}
	}

	public void Update()
	{
		State superState = GetSuperState(CurrentStateId);
		if (superState != null && superState.OnUpdate != null)
		{
			superState.OnUpdate();
		}
		State subState = GetSubState(CurrentStateId, CurrentSubStateId);
		if (subState != null && subState.OnUpdate != null)
		{
			subState.OnUpdate();
		}
	}

	protected uint GetFullyQualifiedStateId(ushort superStateId, ushort subStateId)
	{
		return (uint)((superStateId << 16) + subStateId);
	}

	protected ushort GetSuperStateIdFromFullyQualifiedId(uint fullyQualifiedId)
	{
		return (ushort)(fullyQualifiedId >> 16);
	}

	protected ushort GetSubStateIdFromFullyQualifiedId(uint fullyQualifiedId)
	{
		return (ushort)fullyQualifiedId;
	}
}
public class OccupiableSpawnPointPool : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private OccupiableSpawnPoint[] pool;

	private List<OccupiableSpawnPoint> available = new List<OccupiableSpawnPoint>();

	public int Availability => available.Count;

	private void Awake()
	{
		OccupiableSpawnPoint[] array = pool;
		foreach (OccupiableSpawnPoint occupiableSpawnPoint in array)
		{
			occupiableSpawnPoint.AutomaticallyReleasedEvent += Release;
		}
		Reset();
	}

	public OccupiableSpawnPoint AcquireNext()
	{
		if (Availability <= 0)
		{
			return null;
		}
		return AcquireAtIndex(0);
	}

	public OccupiableSpawnPoint AcquireRandom()
	{
		if (Availability <= 0)
		{
			return null;
		}
		return AcquireAtIndex(UnityEngine.Random.Range(0, available.Count));
	}

	public void Release(OccupiableSpawnPoint tf)
	{
		if (!available.Contains(tf))
		{
			tf.Release();
			available.Add(tf);
		}
	}

	public void Reset()
	{
		available.Clear();
		OccupiableSpawnPoint[] array = pool;
		foreach (OccupiableSpawnPoint occupiableSpawnPoint in array)
		{
			available.Add(occupiableSpawnPoint);
			if (occupiableSpawnPoint.Occupied)
			{
				occupiableSpawnPoint.Release();
			}
		}
	}

	private OccupiableSpawnPoint AcquireAtIndex(int index)
	{
		if (index >= available.Count)
		{
			return null;
		}
		OccupiableSpawnPoint occupiableSpawnPoint = available[index];
		available.RemoveAt(index);
		occupiableSpawnPoint.Occupy();
		return occupiableSpawnPoint;
	}
}
