public class StateMachine : AbstractStateMachine
{
	public void Initialize(ushort initialStateId)
	{
		Initialize(initialStateId, ushort.MaxValue);
	}

	public void Initialize(ushort initialStateId, ushort initialSubStateId)
	{
		EnterState(initialStateId, initialSubStateId);
	}
}
public class SynchronizedStateMachine : AbstractStateMachine
{
	private SetterPermissionMode setterPermissionMode = SetterPermissionMode.MASTER;

	private readonly string STATE_ID_KEY = "STATE_ID";

	private SynchronizedField<int> _fullyQualifiedStateId;

	private uint SynchronizedFullyQualifiedStateId
	{
		get
		{
			return (uint)_fullyQualifiedStateId.Get();
		}
		set
		{
			_fullyQualifiedStateId.ForceSet((int)value);
		}
	}

	public SynchronizedStateMachine(string id, SetterPermissionMode setterPermissionMode)
	{
		STATE_ID_KEY = id + "_" + STATE_ID_KEY;
		this.setterPermissionMode = setterPermissionMode;
	}

	public void Initialize(Photon.MonoBehaviour component, ushort defaultStateId)
	{
		Initialize(component, defaultStateId, ushort.MaxValue);
	}

	public void Initialize(Photon.MonoBehaviour component, ushort defaultStateId, ushort defaultSubStateId)
	{
		_fullyQualifiedStateId = new SynchronizedField<int>(component, STATE_ID_KEY, 65535, setterPermissionMode, OnSynchronizedFullyQualifiedStateIdChange);
		if (PhotonNetwork.isMasterClient)
		{
			SynchronizedFullyQualifiedStateId = GetFullyQualifiedStateId(defaultStateId, defaultSubStateId);
		}
		else
		{
			base.EnterState(SynchronizedFullyQualifiedStateId);
		}
	}

	protected override void EnterState(uint nextFullyQualifiedSubStateId)
	{
		SynchronizedFullyQualifiedStateId = nextFullyQualifiedSubStateId;
	}

	private void OnSynchronizedFullyQualifiedStateIdChange()
	{
		base.EnterState(SynchronizedFullyQualifiedStateId);
	}
}
public abstract class TimestampedRollingBuffer<T>
{
	private struct BufferEntry
	{
		public T Value;

		public float Timestamp;
	}

	private static int InvalidIndex = -1;

	private static float InvalidTime = -1f;

	private const int MAX_SIZE = 100;

	private BufferEntry[] array;

	private int head;

	public TimestampedRollingBuffer()
		: this(100)
	{
	}

	public TimestampedRollingBuffer(int size)
	{
		array = new BufferEntry[size];
		Clear();
	}

	public void Add(float time, T value)
	{
		array[head].Timestamp = time;
		array[head].Value = value;
		IncrementHead();
	}

	public void Clear()
	{
		for (int i = 0; i < array.Length; i++)
		{
			array[i].Timestamp = InvalidTime;
		}
		head = 0;
	}

	public bool TryGetAverageValueOverTime(float startTime, float endTime, out T value)
	{
		float num = 0f;
		value = ZeroValue();
		int lhsIndex = InvalidIndex;
		int i;
		for (i = 1; i <= array.Length && array[RollingHeadOffset(i)].Timestamp < startTime; i++)
		{
			lhsIndex = RollingHeadOffset(i);
		}
		int invalidIndex = InvalidIndex;
		for (; i <= array.Length && array[RollingHeadOffset(i)].Timestamp <= endTime; i++)
		{
			invalidIndex = RollingHeadOffset(i);
			value = Sum(value, ValueBetweenEntries(lhsIndex, invalidIndex, startTime));
			num += 1f;
			lhsIndex = invalidIndex;
		}
		if (num > 0f)
		{
			value = Scale(value, 1f / num);
			return true;
		}
		return false;
	}

	public T ValueAtTime(float time)
	{
		int lhsIndex = InvalidIndex;
		int rhsIndex = InvalidIndex;
		for (int i = 1; i <= array.Length; i++)
		{
			int num = RollingHeadOffset(i);
			if (array[num].Timestamp <= time)
			{
				lhsIndex = num;
				continue;
			}
			rhsIndex = num;
			break;
		}
		return ValueBetweenEntries(lhsIndex, rhsIndex, time);
	}

	private int RollingHeadOffset(int headOffset)
	{
		return (head + headOffset) % array.Length;
	}

	private void IncrementHead()
	{
		head = RollingHeadOffset(1);
	}

	private T ValueBetweenEntries(int lhsIndex, int rhsIndex, float desiredTime)
	{
		if (lhsIndex == InvalidIndex && rhsIndex == InvalidIndex)
		{
			return ZeroValue();
		}
		if (lhsIndex == InvalidIndex)
		{
			return array[rhsIndex].Value;
		}
		if (rhsIndex == InvalidIndex)
		{
			return array[lhsIndex].Value;
		}
		float timestamp = array[lhsIndex].Timestamp;
		float timestamp2 = array[rhsIndex].Timestamp;
		float t = (desiredTime - timestamp) / (timestamp2 - timestamp);
		return Interpolate(array[lhsIndex].Value, array[rhsIndex].Value, t);
	}

	protected abstract T ZeroValue();

	protected abstract T Interpolate(T lhs, T rhs, float t);

	protected abstract T Scale(T value, float t);

	protected abstract T Sum(T lhs, T rhs);
}
public class TimestampedRollingBufferVector3 : TimestampedRollingBuffer<Vector3>
{
	protected override Vector3 ZeroValue()
	{
		return Vector3.zero;
	}

	protected override Vector3 Interpolate(Vector3 lhs, Vector3 rhs, float t)
	{
		return Vector3.Lerp(lhs, rhs, t);
	}

	protected override Vector3 Scale(Vector3 value, float t)
	{
		return value * t;
	}

	protected override Vector3 Sum(Vector3 lhs, Vector3 rhs)
	{
		return lhs + rhs;
	}
}
[RequireComponent(typeof(PhotonView))]
public class ToolPool : Photon.MonoBehaviour
{
	[SerializeField]
	protected Tool[] pool;

	[SerializeField]
	private bool forceDropIfNecessary;

	[SerializeField]
	private bool toolsDefaultDisabled = true;

	private SynchronizedField<float>[] lastAcquiredTimestamps;

	public Tool[] Pool => pool;

	protected override void Awake()
	{
		base.Awake();
		for (int i = 0; i < pool.Length; i++)
		{
			pool[i].SpawnedFromPool = true;
		}
		lastAcquiredTimestamps = new SynchronizedField<float>[pool.Length];
		for (int j = 0; j < pool.Length; j++)
		{
			lastAcquiredTimestamps[j] = new SynchronizedField<float>(pool[j], "LastAcquiredTime", 0f, SetterPermissionMode.MASTER);
		}
	}

	protected virtual void Start()
	{
		if (PhotonNetwork.isMasterClient && toolsDefaultDisabled)
		{
			for (int i = 0; i < pool.Length; i++)
			{
				pool[i].IsEnabled = false;
			}
		}
	}

	public Tool Acquire(Vector3 position, Quaternion rotation)
	{
		if (PhotonNetwork.isMasterClient)
		{
			int oldestToolIndex = GetOldestToolIndex((Tool tool2) => !tool2.IsEnabled);
			if (oldestToolIndex == -1)
			{
				oldestToolIndex = GetOldestToolIndex((Tool tool2) => !tool2.IsHeld);
				if (oldestToolIndex != -1)
				{
					Release(pool[oldestToolIndex]);
				}
				else if (forceDropIfNecessary)
				{
					oldestToolIndex = GetOldestToolIndex((Tool tool2) => true);
					pool[oldestToolIndex].HolderId = PhotonPlayer.Invalid;
					pool[oldestToolIndex].IsLocked = false;
					Release(pool[oldestToolIndex]);
				}
			}
			if (oldestToolIndex != -1)
			{
				lastAcquiredTimestamps[oldestToolIndex].ForceSet((float)PhotonNetwork.time);
				Tool tool = pool[oldestToolIndex];
				tool.photonView.TransferOwnership(PhotonNetwork.masterClient);
				tool.transform.position = position;
				tool.transform.rotation = rotation;
				PUNNetworkTransform[] componentsInChildren = tool.GetComponentsInChildren<PUNNetworkTransform>(includeInactive: true);
				foreach (PUNNetworkTransform pUNNetworkTransform in componentsInChildren)
				{
					pUNNetworkTransform.InsertPositionDiscontinuity();
				}
				tool.IsEnabled = true;
				return tool;
			}
		}
		return null;
	}

	public void Release(Tool tool)
	{
		if (PhotonNetwork.isMasterClient && pool.Contains(tool) && tool.IsEnabled)
		{
			tool.photonView.TransferOwnership(PhotonNetwork.masterClient);
			tool.IsEnabled = false;
			tool.transform.position = Vector3.zero;
			tool.transform.rotation = Quaternion.identity;
			PUNNetworkTransform[] componentsInChildren = tool.GetComponentsInChildren<PUNNetworkTransform>(includeInactive: true);
			foreach (PUNNetworkTransform pUNNetworkTransform in componentsInChildren)
			{
				pUNNetworkTransform.InsertPositionDiscontinuity();
			}
		}
	}

	public void MasterDisableAll()
	{
		if (PhotonNetwork.isMasterClient)
		{
			Tool[] array = pool;
			foreach (Tool tool in array)
			{
				Release(tool);
			}
		}
	}

	private int GetOldestToolIndex(Func<Tool, bool> predicate)
	{
		int result = -1;
		float num = float.MaxValue;
		for (int i = 0; i < pool.Length; i++)
		{
			float num2 = lastAcquiredTimestamps[i].Get();
			if (num2 < num && predicate(pool[i]))
			{
				result = i;
				num = num2;
			}
		}
		return result;
	}
}
[RequireComponent(typeof(Rigidbody))]
[RequireComponent(typeof(RigidbodySteering))]
public abstract class Enemy : Photon.MonoBehaviour
{
	public delegate void PlayerHitEventHandler(Weapon weapon, Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, Vector3 impactPoint);

	public delegate void Death(Enemy thisEnemy);

	public delegate void HealthChange(Enemy thisEnemy, int newHealth, int maxHealth);

	[SerializeField]
	private EnemyType enemyType = EnemyType.INVALID;

	[Header("Health")]
	[SerializeField]
	private int maxHealth = 100;

	protected Rigidbody rigidbody;

	protected RigidbodySteering steering;

	protected SynchronizedField<int> _health;

	protected SynchronizedField<bool> _isAlive;

	protected SynchronizedStateMachine behaviorStateMachine;

	protected SynchronizedTimer behaviorTimer;

	public EnemyType EnemyType => enemyType;

	public bool IsAlive
	{
		get
		{
			return _isAlive.Get();
		}
		protected set
		{
			_isAlive.ForceSet(value);
		}
	}

	public int Health
	{
		get
		{
			return _health.Get();
		}
		protected set
		{
			_health.ForceSet(Mathf.Clamp(value, 0, maxHealth));
		}
	}

	public int MaxHealth => maxHealth;

	public event PlayerHitEventHandler PlayerHitEvent;

	public event HealthChange HealthChangeEvent;

	public event Death DeathEvent;

	protected override void Awake()
	{
		base.Awake();
		rigidbody = GetComponent<Rigidbody>();
		steering = GetComponent<RigidbodySteering>();
		_health = new SynchronizedField<int>(this, "HEALTH", maxHealth, SetterPermissionMode.AUTHORITY, OnHealthChanged);
		_isAlive = new SynchronizedField<bool>(this, "IS_ALIVE", defaultValue: true, SetterPermissionMode.AUTHORITY, OnIsAliveChanged);
		behaviorStateMachine = new SynchronizedStateMachine("BEHAVIOR", SetterPermissionMode.AUTHORITY);
		behaviorTimer = new SynchronizedTimer(this, "BEHAVIOR_TIMER", SetterPermissionMode.AUTHORITY);
		EnemyCollider[] componentsInChildren = GetComponentsInChildren<EnemyCollider>(includeInactive: true);
		EnemyCollider[] array = componentsInChildren;
		foreach (EnemyCollider enemyCollider in array)
		{
			enemyCollider.ThisEnemy = this;
		}
	}

	protected virtual void Update()
	{
		behaviorStateMachine.Update();
		behaviorTimer.UpdateCallbacks();
	}

	protected virtual void OnTookDamage(int damage, PhotonPlayer attacker)
	{
	}

	public virtual void AuthorityApplyDamage(int damage, Vector3 collisionForce, Vector3 collisionPosition)
	{
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcOnTookDamage", PhotonTargets.All, base.authority, damage);
			Health -= damage;
			rigidbody.AddForceAtPosition(collisionForce, collisionPosition);
		}
	}

	protected virtual void OnHealthChanged()
	{
		if (this.HealthChangeEvent != null)
		{
			this.HealthChangeEvent(this, Health, maxHealth);
		}
	}

	protected virtual void OnIsAliveChanged()
	{
		if (!IsAlive && this.DeathEvent != null)
		{
			this.DeathEvent(this);
		}
	}

	protected virtual void OnCollisionEnter(Collision collision)
	{
		HandleCollision(collision);
	}

	protected virtual void OnCollisionStay(Collision collision)
	{
		HandleCollision(collision);
	}

	protected virtual void HandleCollision(Collision collision)
	{
		Vector3 point = ((collision.contacts.Length <= 0) ? base.transform.position : collision.contacts[0].point);
		Tool colliderTool = collision.GetColliderTool();
		if (colliderTool != null)
		{
			OnToolCollisionEnter(colliderTool, point, collision);
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null)
		{
			OnPlayerCollisionEnter(colliderPlayer, bodyPart, point, collision);
		}
	}

	protected virtual void OnToolCollisionEnter(Tool hitTool, Vector3 point, Collision collision)
	{
		if (!base.hasAuthority && hitTool.IsHeld && hitTool.isLocal)
		{
			base.photonView.TransferOwnership(hitTool.photonView.ownerId);
		}
	}

	protected virtual void OnPlayerCollisionEnter(Player hitPlayer, Player.BodyPart bodyPart, Vector3 point, Collision collision)
	{
		if (!base.hasAuthority && hitPlayer.isLocal)
		{
			base.photonView.TransferOwnership(hitPlayer.photonView.ownerId);
		}
		switch (bodyPart)
		{
		case Player.BodyPart.LeftHand:
			hitPlayer.LeftHand.Vibrate(50, 1000);
			break;
		case Player.BodyPart.RightHand:
			hitPlayer.RightHand.Vibrate(50, 1000);
			break;
		}
		PlayerHit(null, this, hitPlayer, bodyPart, point);
	}

	protected void PlayerHit(Weapon weapon, Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, Vector3 impactPoint)
	{
		if (this.PlayerHitEvent != null)
		{
			this.PlayerHitEvent(weapon, enemy, hitPlayer, hitBodyPart, impactPoint);
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		Killzone colliderKillzone = collider.GetColliderKillzone();
		if (colliderKillzone != null)
		{
			OnKillzoneTriggerEnter(colliderKillzone);
		}
	}

	protected virtual void OnKillzoneTriggerEnter(Killzone hitKillzone)
	{
		if (base.hasAuthority && IsAlive)
		{
			Health = 0;
			IsAlive = false;
		}
	}

	[PunRPC]
	protected void RpcOnTookDamage(PhotonPlayer damagingPlayer, int damage)
	{
		OnTookDamage(damage, damagingPlayer);
	}
}
