public class ExtrudedMesh
{
	private const int SEGMENT_VERTEX_COUNT = 3;

	private const int SEGMENT_INDEX_COUNT = 18;

	private const float SEGMENT_ANGLE = (float)Math.PI * 2f / 3f;

	private const float MIN_CORNER_ANGLE = 15f;

	private const float MIN_CORNER_DISTANCE = 0.1f;

	private const float MIN_CORNER_DISTANCE_SQR = 0.010000001f;

	private const int CAP_INDEX_COUNT = 18;

	private List<Vector3> vertices;

	private List<Vector3> normals;

	private List<int> indices;

	private int temporaryVertexCount;

	private int temporaryIndexCount;

	public Transform Parent { get; private set; }

	public Mesh Mesh { get; private set; }

	public ExtrudedMesh(Transform parent)
	{
		Parent = parent;
		Mesh = new Mesh();
		Mesh.MarkDynamic();
		vertices = new List<Vector3>();
		normals = new List<Vector3>();
		indices = new List<int>();
	}

	public void Finish()
	{
		vertices = null;
		normals = null;
		indices = null;
	}

	public void AddPermanentControlPointVertices(ControlPoint controlPoint, ControlPoint lastPermanentControlPoint, float radius, bool isEnd = false)
	{
		ClearTemporaryControlPointVertices();
		AddControlPoint(controlPoint, lastPermanentControlPoint, radius, isEnd);
	}

	public void AddTemporaryControlPointVertices(List<ControlPoint> controlPoints, ControlPoint lastPermanentControlPoint, float radius)
	{
		ClearTemporaryControlPointVertices();
		int count = vertices.Count;
		int count2 = indices.Count;
		for (int i = 0; i < controlPoints.Count; i++)
		{
			ControlPoint controlPoint = controlPoints[i];
			ControlPoint controlPoint2 = null;
			controlPoint2 = ((i != 0) ? controlPoints[i - 1] : lastPermanentControlPoint);
			bool isEnd = i == controlPoints.Count - 1;
			AddControlPoint(controlPoint, controlPoint2, radius, isEnd);
		}
		temporaryVertexCount = vertices.Count - count;
		temporaryIndexCount = indices.Count - count2;
	}

	public void CopyChangesToGPU()
	{
		Mesh.Clear();
		Mesh.SetVertices(vertices);
		Mesh.SetNormals(normals);
		Mesh.SetTriangles(indices, 0);
	}

	private void AddControlPoint(ControlPoint controlPoint, ControlPoint previous, float radius, bool isEnd)
	{
		bool flag = false;
		if (previous != null)
		{
			float sqrMagnitude = (controlPoint.Position - previous.Position).sqrMagnitude;
			float num = Vector3.Angle(previous.Tangent, controlPoint.Tangent);
			flag = sqrMagnitude >= 0.010000001f && num >= 15f;
		}
		if (flag)
		{
			ControlPoint controlPoint2 = new ControlPoint(previous);
			controlPoint2.Position = controlPoint.Position - previous.Tangent * 2f * radius;
			ControlPoint controlPoint3 = ControlPoint.Interpolate(previous, controlPoint, 0.5f);
			controlPoint3.Position = controlPoint.Position;
			ControlPoint controlPoint4 = new ControlPoint(controlPoint);
			controlPoint4.Position = controlPoint.Position + controlPoint.Tangent * 2f * radius;
			ControlPoint controlPoint5 = ControlPoint.Interpolate(controlPoint2, controlPoint3, 0.5f);
			ControlPoint controlPoint6 = ControlPoint.Interpolate(controlPoint3, controlPoint4, 0.5f);
			AddNewRingVertices(controlPoint2, radius, isEnd: false);
			AddNewRingVertices(controlPoint5, radius, isEnd: false);
			AddNewRingVertices(controlPoint3, radius, isEnd: false);
			AddNewRingVertices(controlPoint6, radius, isEnd: false);
			AddNewRingVertices(controlPoint4, radius, isEnd: false);
		}
		else
		{
			AddNewRingVertices(controlPoint, radius, isEnd);
		}
	}

	private void AddNewRingVertices(ControlPoint controlPoint, float radius, bool isEnd)
	{
		Vector3 position = Parent.InverseTransformPoint(controlPoint.Position);
		Vector3 right = Parent.InverseTransformVector(controlPoint.Binormal);
		Vector3 up = Parent.InverseTransformVector(controlPoint.Normal);
		Vector3 vector = Parent.InverseTransformVector(controlPoint.Tangent);
		if (vertices.Count == 0)
		{
			AllocateVertices(4);
			SetVertex(0, position, -vector);
			SetRingVertices(1, position, right, up, -vector, radius);
			AllocateIndices(18);
			SetStartCapIndices(0, 1, 0);
			return;
		}
		int num = AllocateVertices(3);
		SetRingVertices(num, position, right, up, vector, radius);
		int indexStartIndex = AllocateIndices(18);
		SetRingIndices(num, indexStartIndex);
		if (isEnd)
		{
			int num2 = AllocateVertices(1);
			SetVertex(num2, position, vector);
			int indexStartIndex2 = AllocateIndices(18);
			SetEndCapIndices(num2, num2 - 3, indexStartIndex2);
		}
	}

	private void ClearTemporaryControlPointVertices()
	{
		FreeVertices(temporaryVertexCount);
		FreeIndices(temporaryIndexCount);
		temporaryVertexCount = 0;
		temporaryIndexCount = 0;
	}

	private void SetVertex(int index, Vector3 position, Vector3 normal)
	{
		vertices[index] = position;
		normals[index] = normal;
	}

	private int AllocateVertices(int vertexCount)
	{
		int count = vertices.Count;
		for (int i = 0; i < vertexCount; i++)
		{
			vertices.Add(Vector3.zero);
		}
		for (int j = 0; j < vertexCount; j++)
		{
			normals.Add(Vector3.zero);
		}
		return count;
	}

	private void FreeVertices(int vertexCount)
	{
		int index = Mathf.Max(0, vertices.Count - vertexCount);
		vertices.RemoveRange(index, vertexCount);
		normals.RemoveRange(index, vertexCount);
	}

	private void SetRingVertices(int ringStartIndex, Vector3 position, Vector3 right, Vector3 up, Vector3 forward, float radius)
	{
		float num = 0f;
		for (int i = 0; i < 3; i++)
		{
			Vector3 vector = position + right * radius * Mathf.Cos(num) + up * radius * Mathf.Sin(num);
			Vector3 normalized = (vector - position).normalized;
			SetVertex(ringStartIndex++, vector, normalized);
			num += (float)Math.PI * 2f / 3f;
		}
	}

	private int AllocateIndices(int indexCount)
	{
		int count = indices.Count;
		for (int i = 0; i < indexCount; i++)
		{
			indices.Add(0);
		}
		return count;
	}

	private void FreeIndices(int indexCount)
	{
		int index = Mathf.Max(0, indices.Count - indexCount);
		indices.RemoveRange(index, indexCount);
	}

	private void SetStartCapIndices(int capIndex, int ringStartIndex, int indexStartIndex)
	{
		for (int i = 0; i < 3; i++)
		{
			int value = ringStartIndex + i;
			int value2 = ringStartIndex + (i + 1) % 3;
			indices[indexStartIndex++] = capIndex;
			indices[indexStartIndex++] = value;
			indices[indexStartIndex++] = value2;
		}
	}

	private void SetEndCapIndices(int capIndex, int ringStartIndex, int indexStartIndex)
	{
		for (int i = 0; i < 3; i++)
		{
			int value = ringStartIndex + i;
			int value2 = ringStartIndex + (i + 1) % 3;
			indices[indexStartIndex++] = value;
			indices[indexStartIndex++] = capIndex;
			indices[indexStartIndex++] = value2;
		}
	}

	private void SetRingIndices(int newRingStartIndex, int indexStartIndex)
	{
		int num = newRingStartIndex - 3;
		for (int i = 0; i < 3; i++)
		{
			int num2 = num + i;
			int num3 = num + (i + 1) % 3;
			int value = num2 + 3;
			int value2 = num3 + 3;
			indices[indexStartIndex++] = num2;
			indices[indexStartIndex++] = value2;
			indices[indexStartIndex++] = num3;
			indices[indexStartIndex++] = value2;
			indices[indexStartIndex++] = num2;
			indices[indexStartIndex++] = value;
		}
	}
}
public class Curve
{
	public Vector3 Position { get; private set; }

	public Quaternion Rotation { get; private set; }

	public List<ControlPoint> ControlPoints { get; private set; }

	public List<ControlPoint> IncompleteControlPoints { get; private set; }

	public bool Finished { get; private set; }

	public ControlPoint LatestControlPoint => (ControlPoints.Count <= 0) ? null : ControlPoints[ControlPoints.Count - 1];

	public ControlPoint PreviousControlPoint => (ControlPoints.Count <= 1) ? null : ControlPoints[ControlPoints.Count - 2];

	public ControlPoint PreviousPreviousControlPoint => (ControlPoints.Count <= 2) ? null : ControlPoints[ControlPoints.Count - 3];

	public ControlPoint LastFinishedControlPoint
	{
		get
		{
			int num = ControlPoints.Count - IncompleteControlPoints.Count - 1;
			if (num < 0)
			{
				return null;
			}
			return ControlPoints[num];
		}
	}

	public Curve(Vector3 position, Quaternion rotation)
	{
		Position = position;
		Rotation = rotation;
		Finished = false;
		ControlPoints = new List<ControlPoint>();
		IncompleteControlPoints = new List<ControlPoint>();
	}

	public void AddControlPoint(Vector3 position)
	{
		if (Finished)
		{
			return;
		}
		ControlPoints.Add(new ControlPoint());
		UpdateLatestControlPoint(position);
		IncompleteControlPoints.Clear();
		for (int i = ControlPoints.Count - 2; i <= ControlPoints.Count - 1; i++)
		{
			if (i >= 0)
			{
				IncompleteControlPoints.Add(ControlPoints[i]);
			}
		}
	}

	public void UpdateLatestControlPoint(Vector3 position)
	{
		if (Finished)
		{
			return;
		}
		ControlPoint latestControlPoint = LatestControlPoint;
		latestControlPoint.Position = position;
		ControlPoint previousControlPoint = PreviousControlPoint;
		if (previousControlPoint == null)
		{
			latestControlPoint.Tangent = Rotation * Vector3.forward;
			latestControlPoint.Normal = Rotation * Vector3.up;
			return;
		}
		Vector3 normalized = (latestControlPoint.Position - previousControlPoint.Position).normalized;
		if (normalized.magnitude >= Mathf.Epsilon)
		{
			previousControlPoint.Tangent = normalized;
		}
		ControlPoint previousPreviousControlPoint = PreviousPreviousControlPoint;
		if (previousPreviousControlPoint != null)
		{
			Vector3 axis = Vector3.Cross(previousPreviousControlPoint.Tangent, previousControlPoint.Tangent);
			if (axis.magnitude <= Mathf.Epsilon)
			{
				previousControlPoint.Normal = previousPreviousControlPoint.Normal;
			}
			else
			{
				axis.Normalize();
				float angle = Vector3.Angle(previousPreviousControlPoint.Tangent, previousControlPoint.Tangent);
				previousControlPoint.Normal = (Quaternion.AngleAxis(angle, axis) * previousPreviousControlPoint.Normal).normalized;
			}
		}
		else
		{
			float num = Mathf.Abs(Vector3.Dot(previousControlPoint.Tangent, previousControlPoint.Normal));
			if (num >= Mathf.Epsilon)
			{
				if (num >= 1f - Mathf.Epsilon)
				{
					previousControlPoint.Normal = Rotation * Vector3.right;
				}
				previousControlPoint.Normal = Vector3.Cross(previousControlPoint.Binormal, previousControlPoint.Tangent).normalized;
			}
		}
		latestControlPoint.Tangent = previousControlPoint.Tangent;
		latestControlPoint.Normal = previousControlPoint.Normal;
	}

	public void Finish()
	{
		Finished = true;
		IncompleteControlPoints.Clear();
	}
}
public class ControlPoint
{
	public Vector3 Position = Vector3.zero;

	public Vector3 Tangent = Vector3.zero;

	public Vector3 Normal = Vector3.zero;

	public Vector3 Binormal => Vector3.Cross(Tangent, Normal).normalized;

	public ControlPoint()
	{
		Position = Vector3.zero;
		Tangent = Vector3.zero;
		Normal = Vector3.zero;
	}

	public ControlPoint(ControlPoint other)
	{
		Position = other.Position;
		Tangent = other.Tangent;
		Normal = other.Normal;
	}

	public static ControlPoint Interpolate(ControlPoint lhs, ControlPoint rhs, float t)
	{
		Quaternion a = Quaternion.LookRotation(lhs.Tangent, lhs.Normal);
		Quaternion b = Quaternion.LookRotation(rhs.Tangent, rhs.Normal);
		Quaternion quaternion = Quaternion.Slerp(a, b, t);
		Vector3 position = Vector3.Lerp(lhs.Position, rhs.Position, t);
		ControlPoint controlPoint = new ControlPoint();
		controlPoint.Position = position;
		controlPoint.Tangent = quaternion * Vector3.forward;
		controlPoint.Normal = quaternion * Vector3.up;
		return controlPoint;
	}

	public static ControlPoint InterpolatePositionOnly(ControlPoint lhs, ControlPoint rhs, float t)
	{
		Vector3 position = Vector3.Lerp(lhs.Position, rhs.Position, t);
		ControlPoint controlPoint = new ControlPoint();
		controlPoint.Position = position;
		controlPoint.Tangent = lhs.Tangent;
		controlPoint.Normal = lhs.Normal;
		return controlPoint;
	}

	public static ControlPoint InterpolateRotationOnly(ControlPoint lhs, ControlPoint rhs, float t)
	{
		Quaternion a = Quaternion.LookRotation(lhs.Tangent, lhs.Normal);
		Quaternion b = Quaternion.LookRotation(rhs.Tangent, rhs.Normal);
		Quaternion quaternion = Quaternion.Slerp(a, b, t);
		ControlPoint controlPoint = new ControlPoint();
		controlPoint.Position = lhs.Position;
		controlPoint.Tangent = quaternion * Vector3.forward;
		controlPoint.Normal = quaternion * Vector3.up;
		return controlPoint;
	}
}
public class Extrusion : Tool
{
	[Header("Extrusion")]
	[SerializeField]
	private Material material;

	[SerializeField]
	private float radius = 0.033f;

	[SerializeField]
	private RecRoomAudioClip loopingExtrusionAudio;

	private bool canExtrudeMeshes = true;

	private List<Curve> curves = new List<Curve>();

	private ExtrudedMesh currentMesh;

	private GameObject currentMeshGameObject;

	private SFXAudioSource extrusionLoopAudioSource;

	private static Transform _extrusionRoot;

	private static Transform extrusionRoot
	{
		get
		{
			if (_extrusionRoot == null)
			{
				GameObject gameObject = new GameObject("Extrusion Root");
				gameObject.transform.SetParent(null, worldPositionStays: false);
				_extrusionRoot = gameObject.transform;
			}
			return _extrusionRoot;
		}
	}

	private Curve CurrentCurve => (curves.Count <= 0) ? null : curves[curves.Count - 1];

	public Transform ExtrusionPoint { get; private set; }

	public bool IsExtrudingMesh => currentMesh != null;

	public override bool OwnershipTransferAllowed => !base.OnlyOwnerCanPickup;

	public event Action ExtrusionFinishedEvent;

	protected override void Awake()
	{
		base.Awake();
		base.transform.SetParent(extrusionRoot, worldPositionStays: true);
		canExtrudeMeshes = true;
		base.OnlyOwnerCanPickup = true;
		base.Rigidbody.isKinematic = true;
		supportsGravityPickup = false;
		supportsOffCenterGravityPickup = false;
		int viewID = (int)base.photonView.instantiationData[0];
		MeshExtruderTool component = PhotonView.Find(viewID).GetComponent<MeshExtruderTool>();
		ExtrusionPoint = component.ExtrusionPoint;
	}

	private void Update()
	{
		UpdatePreviewControlPoint();
	}

	protected override void OnReset(Vector3 position, Quaternion rotation, bool wasEnabled, Vector3 oldPosition, bool wasCleanedUp)
	{
		if (SingletonMonoBehaviour<ToolCleanupManager>.Instance != null)
		{
			SingletonMonoBehaviour<ToolCleanupManager>.Instance.RemoveTool(this);
		}
		if (base.hasAuthority)
		{
			base.Owner.ToolController.ReleaseTool(this);
			SynchronizedField.ClearAllFieldsForPhotonObject(this);
			PhotonNetwork.Destroy(base.gameObject);
		}
	}

	public void MasterStartExtrudingNewMesh()
	{
		if (base.hasAuthority && ExtrusionPoint != null)
		{
			base.photonView.RPC("RpcStartExtrudingNewMesh", PhotonTargets.All, ExtrusionPoint.position, ExtrusionPoint.rotation);
		}
	}

	public void MasterFinishExtrudingCurrentMesh()
	{
		if (base.hasAuthority && ExtrusionPoint != null)
		{
			base.photonView.RPC("RpcFinishExtrudingCurrentMesh", PhotonTargets.All, ExtrusionPoint.position);
		}
	}

	public void MasterFinishExtrusion()
	{
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcFinishExtrusion", PhotonTargets.All);
		}
	}

	public void MasterAddControlPoint()
	{
		if (base.hasAuthority && ExtrusionPoint != null)
		{
			base.photonView.RPC("RpcAddControlPoint", PhotonTargets.All, ExtrusionPoint.position);
		}
	}

	public void UpdatePreviewControlPoint()
	{
		if (IsExtrudingMesh && ExtrusionPoint != null)
		{
			Curve currentCurve = CurrentCurve;
			currentCurve.UpdateLatestControlPoint(ExtrusionPoint.position);
			currentMesh.AddTemporaryControlPointVertices(currentCurve.IncompleteControlPoints, currentCurve.LastFinishedControlPoint, radius);
			currentMesh.CopyChangesToGPU();
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		if (canExtrudeMeshes)
		{
			FinishExtrusion();
		}
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
	}

	private void AddControlPoint(Vector3 position, bool isEnd = false)
	{
		if (!IsExtrudingMesh)
		{
			return;
		}
		Curve currentCurve = CurrentCurve;
		if (currentCurve.ControlPoints.Count == 0)
		{
			currentCurve.AddControlPoint(position);
		}
		else
		{
			currentCurve.UpdateLatestControlPoint(position);
			ControlPoint previousControlPoint = currentCurve.PreviousControlPoint;
			ControlPoint previousPreviousControlPoint = currentCurve.PreviousPreviousControlPoint;
			currentMesh.AddPermanentControlPointVertices(previousControlPoint, previousPreviousControlPoint, radius);
			float num = ((previousPreviousControlPoint != null) ? (previousControlPoint.Position - previousPreviousControlPoint.Position).magnitude : 0f);
			if (!(num <= 2f * radius))
			{
				AddNewCollider(previousControlPoint.Position);
			}
		}
		if (isEnd)
		{
			ControlPoint latestControlPoint = currentCurve.LatestControlPoint;
			currentMesh.AddPermanentControlPointVertices(latestControlPoint, currentCurve.PreviousControlPoint, radius, isEnd: true);
			AddNewCollider(latestControlPoint.Position);
		}
		else
		{
			currentCurve.AddControlPoint(position);
			currentMesh.AddTemporaryControlPointVertices(currentCurve.IncompleteControlPoints, currentCurve.LastFinishedControlPoint, radius);
		}
		currentMesh.CopyChangesToGPU();
	}

	private void AddNewCollider(Vector3 position)
	{
		GameObject gameObject = new GameObject("Collider");
		gameObject.layer = 10;
		gameObject.transform.SetParent(currentMeshGameObject.transform);
		gameObject.transform.position = position;
		gameObject.AddComponent<SphereCollider>().radius = radius;
		AddToolCollider(gameObject.AddComponent<ToolCollider>());
	}

	private void StartExtrudingNewMesh(Vector3 position, Quaternion rotation)
	{
		currentMeshGameObject = new GameObject("Mesh");
		currentMeshGameObject.layer = 10;
		currentMeshGameObject.transform.SetParent(base.transform);
		currentMeshGameObject.transform.position = position;
		currentMeshGameObject.transform.rotation = rotation;
		currentMesh = new ExtrudedMesh(currentMeshGameObject.transform);
		currentMeshGameObject.AddComponent<MeshFilter>().mesh = currentMesh.Mesh;
		MeshRenderer meshRenderer = currentMeshGameObject.AddComponent<MeshRenderer>();
		meshRenderer.material = material;
		base.ToolRenderer.SetupRenderer(meshRenderer);
		StopLoopingExtrusionAudio();
	}

	private void FinishExtrudingCurrentMesh()
	{
		if (IsExtrudingMesh)
		{
			currentMesh.Finish();
			currentMesh = null;
			currentMeshGameObject = null;
		}
		StopLoopingExtrusionAudio();
	}

	private void FinishExtrusion()
	{
		canExtrudeMeshes = false;
		base.OnlyOwnerCanPickup = false;
		base.Rigidbody.isKinematic = false;
		supportsGravityPickup = true;
		supportsOffCenterGravityPickup = true;
		if (SingletonMonoBehaviour<ToolCleanupManager>.Instance != null)
		{
			SingletonMonoBehaviour<ToolCleanupManager>.Instance.AddTool(this);
		}
		if (this.ExtrusionFinishedEvent != null)
		{
			this.ExtrusionFinishedEvent();
		}
		StopLoopingExtrusionAudio();
	}

	private void CreateFromControlPoints()
	{
		int count = curves.Count;
		for (int i = 0; i < count; i++)
		{
			Curve curve = curves[i];
			StartExtrudingNewMesh(curve.Position, curve.Rotation);
			List<ControlPoint> incompleteControlPoints = curve.IncompleteControlPoints;
			int num = curve.ControlPoints.Count - incompleteControlPoints.Count;
			for (int j = 0; j < num; j++)
			{
				ControlPoint controlPoint = curve.ControlPoints[j];
				ControlPoint lastPermanentControlPoint = ((j <= 0) ? null : curve.ControlPoints[j - 1]);
				bool isEnd = curve.Finished && j == num - 1;
				currentMesh.AddPermanentControlPointVertices(controlPoint, lastPermanentControlPoint, radius, isEnd);
				AddNewCollider(curve.ControlPoints[j].Position);
			}
			if (!curve.Finished)
			{
				currentMesh.AddTemporaryControlPointVertices(incompleteControlPoints, curve.LastFinishedControlPoint, radius);
				currentMesh.CopyChangesToGPU();
			}
			else
			{
				currentMesh.CopyChangesToGPU();
				FinishExtrudingCurrentMesh();
			}
		}
		if (!canExtrudeMeshes)
		{
			FinishExtrusion();
		}
	}

	private void StartLoopingExtrusionAudio()
	{
		if (extrusionLoopAudioSource == null)
		{
			extrusionLoopAudioSource = AudioManager.StartLooping3DSFX(loopingExtrusionAudio, ExtrusionPoint);
		}
	}

	private void StopLoopingExtrusionAudio()
	{
		if (extrusionLoopAudioSource != null)
		{
			AudioManager.StopLoopingSFX(extrusionLoopAudioSource);
			extrusionLoopAudioSource = null;
		}
	}

	public static Extrusion CreateNewExtrusion(MeshExtruderTool extruder)
	{
		object[] data = new object[1] { extruder.photonView.viewID };
		return PhotonNetwork.Instantiate("[Extrusion]", extruder.ExtrusionPoint.position, extruder.ExtrusionPoint.rotation, 0, data).GetComponent<Extrusion>();
	}

	[PunRPC]
	public void RpcStartExtrudingNewMesh(Vector3 position, Quaternion rotation)
	{
		curves.Add(new Curve(position, rotation));
		StartExtrudingNewMesh(position, rotation);
		AddControlPoint(position);
		StartLoopingExtrusionAudio();
	}

	[PunRPC]
	public void RpcFinishExtrudingCurrentMesh(Vector3 position)
	{
		AddControlPoint(position, isEnd: true);
		CurrentCurve.Finish();
		FinishExtrudingCurrentMesh();
	}

	[PunRPC]
	public void RpcFinishExtrusion()
	{
		FinishExtrusion();
	}

	[PunRPC]
	public void RpcAddControlPoint(Vector3 position)
	{
		AddControlPoint(position);
	}

	[PunRPC]
	public void RpcCreateFromControlPoints(Vector3[] controlPointPositions, Vector3[] curveInitialPositions, Quaternion[] curveInitialRotations, int[] curveFinalIndices, bool canExtrude)
	{
		curves.Clear();
		int num = 0;
		int num2 = controlPointPositions.Length;
		int num3 = curveFinalIndices.Length;
		for (int i = 0; i < num3; i++)
		{
			Curve curve = new Curve(curveInitialPositions[i], curveInitialRotations[i]);
			int num4 = curveFinalIndices[i];
			bool flag = num4 >= 0;
			int num5 = ((!flag) ? (num2 - 1) : num4);
			while (num <= num5)
			{
				curve.AddControlPoint(controlPointPositions[num++]);
			}
			if (flag)
			{
				curve.Finish();
			}
			curves.Add(curve);
		}
		canExtrudeMeshes = canExtrude;
		CreateFromControlPoints();
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		int count = curves.Count;
		if (!base.hasAuthority || count <= 0)
		{
			return;
		}
		int num = 0;
		Vector3[] array = new Vector3[curves.Count];
		Quaternion[] array2 = new Quaternion[curves.Count];
		int[] array3 = new int[curves.Count];
		for (int i = 0; i < curves.Count; i++)
		{
			num += curves[i].ControlPoints.Count;
			if (curves[i].Finished)
			{
				array3[i] = num - 1;
			}
			else
			{
				array3[i] = -1;
			}
			ref Vector3 reference = ref array[i];
			reference = curves[i].Position;
			ref Quaternion reference2 = ref array2[i];
			reference2 = curves[i].Rotation;
		}
		Vector3[] array4 = new Vector3[num];
		int num2 = 0;
		for (int j = 0; j < curves.Count; j++)
		{
			for (int k = 0; k < curves[j].ControlPoints.Count; k++)
			{
				ref Vector3 reference3 = ref array4[num2];
				reference3 = curves[j].ControlPoints[k].Position;
				num2++;
			}
		}
		base.photonView.RPC("RpcCreateFromControlPoints", newPlayer, array4, array, array2, array3, canExtrudeMeshes);
	}

	protected override void OnPhotonPlayerDisconnected(PhotonPlayer oldPlayer)
	{
		if (base.hasAuthority && base.Owner.PhotonPlayer == oldPlayer)
		{
			if (IsExtrudingMesh)
			{
				RpcFinishExtrudingCurrentMesh(ExtrusionPoint.position);
			}
			RpcFinishExtrusion();
		}
		base.OnPhotonPlayerDisconnected(oldPlayer);
	}
}
public class RegistrationKiosk : Photon.MonoBehaviour
{
