	private Coroutine mainFlowCoroutine;

	private bool submitButtonPressed;

	private float lastTimeKioskStateChanged;

	private SynchronizedField<int> _kioskState;

	private string submittedEmail;

	private string errorMessage = string.Empty;

	private KioskUIState _kioskUIState;

	private SynchronizedField<int> _kioskHolderId;

	private KioskState kioskState
	{
		get
		{
			return (KioskState)_kioskState.Get();
		}
		set
		{
			if (value != (KioskState)_kioskState.Get())
			{
				_kioskState.CompareAndSwapSet((int)value);
			}
		}
	}

	private KioskUIState kioskUIState
	{
		get
		{
			return _kioskUIState;
		}
		set
		{
			if (_kioskUIState != value && value == KioskUIState.SendingEmail)
			{
				AudioManager.Play3DSFX(modemSound, notificationRoot.position);
			}
			_kioskUIState = value;
			UpdateKioskUIState();
		}
	}

	private int KioskHolderId
	{
		get
		{
			return _kioskHolderId.Get();
		}
		set
		{
			_kioskHolderId.CompareAndSwapSet(value);
		}
	}

	public bool IsInUse => KioskHolderId != PhotonPlayer.Invalid;

	public bool IsHolderLocal => KioskHolderId == PhotonNetwork.player.ID;

	protected override void Awake()
	{
		base.Awake();
		selfieCam = UnityEngine.Object.Instantiate(selfieCameraPrefab);
		selfieCam.transform.SetParent(base.transform.parent);
		selfieCam.Resolution = cameraResolution;
		_kioskHolderId = new SynchronizedField<int>(this, "KIOSK_HOLDER", PhotonPlayer.Invalid, SetterPermissionMode.ANYONE, OnKioskHolderChanged);
		_kioskState = new SynchronizedField<int>(this, "KIOSK_STATE", 0, SetterPermissionMode.ANYONE, OnKioskStateChanged);
		All.Add(this);
	}

	private void Start()
	{
		kioskCanvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
		canvas.transform.SetParent(base.transform.parent, worldPositionStays: true);
		ResetFlow();
		UpdateKioskVisual();
	}

	private void Update()
	{
		if (IsHolderLocal && Player.LocalPlayer != null && !Player.LocalPlayer.IsRegistering && Time.time - lastTimeKioskStateChanged > kioskTimeoutSeconds && (Player.LocalPlayer.CurrentFloorPosition - base.transform.position).magnitude > kioskTimeoutPlayerDistance)
		{
			ResetFlow();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (kioskState != KioskState.None)
		{
			ResetFlow();
		}
		if (ViveControllerInput.Instance != null)
		{
			ViveControllerInput.Instance.StandAloneInput = false;
		}
		if (PlatformManager.Instance != null)
		{
			PlatformManager.Instance.IgnoreVRFocus = false;
		}
		All.Remove(this);
	}

	public void KioskMenu_SubmitButton()
	{
		AudioManager.Play3DSFX(buttonPressNext, notificationRoot.position);
		if (!IsInUse)
		{
			KioskHolderId = PhotonNetwork.player.ID;
			foreach (RegistrationKiosk item in All)
			{
				if (item != null && item != this && item.IsHolderLocal)
				{
					item.ResetFlow();
				}
			}
		}
		submitButtonPressed = true;
	}

	public void KioskMenu_CancelButton()
	{
		AudioManager.Play3DSFX(buttonPressCancel, notificationRoot.position);
		if (IsHolderLocal)
		{
			ResetFlow();
		}
	}

	private void ResetFlow()
	{
		StopAllCoroutines();
		mainFlowCoroutine = null;
		if (Player.LocalPlayer != null && Player.LocalPlayer.PlayerUI != null && Player.LocalPlayer.PlayerUI.UIPlayerCamera != null)
		{
			selfieCam.Setup(null);
		}
		if (IsHolderLocal && Player.LocalPlayer != null)
		{
			Player.LocalPlayer.IsRegistering = false;
			if (!Profiles.LocalProfile.Verified && kioskState != KioskState.None)
			{
				AnalyticsHelper.UserRegistrationFlow("canceled", kioskState.ToString());
			}
		}
		ReleaseKioskHolder();
		cameraFlashAnimator.gameObject.SetActive(value: false);
	}

	private IEnumerator RunMainFlow()
	{
		if (!Profiles.LocalProfile.Verified)
		{
			kioskState = KioskState.DownloadingProfile;
			yield return Profiles.DownloadLocalProfile(delegate(string e)
			{
				if (!string.IsNullOrEmpty(e) && IsHolderLocal && kioskState == KioskState.DownloadingProfile)
				{
					ShowNotification("Failed to sync profile for membership!");
					ResetFlow();
				}
			});
		}
		if (!Profiles.LocalProfile.Verified)
		{
			kioskState = KioskState.SignupFlowStart;
			AnalyticsHelper.UserRegistrationFlow("flowStart", string.Empty);
			yield return new WaitForSeconds(0.5f);
			submitButtonPressed = false;
			while (!submitButtonPressed)
			{
				yield return null;
			}
		}
		yield return RunTakeSelfie();
		if (Profiles.LocalProfile.Verified)
		{
			kioskState = KioskState.SelfieUpdated;
			AnalyticsHelper.UserSelfieUpdated();
			yield return new WaitForSeconds(3f);
		}
		else
		{
			kioskState = KioskState.PendingRegistration;
			ShowNotification("Remove headset and check PC!", 10f, ScreenSpaceNotificationManager.NotificationType.Major);
			if (IsHolderLocal)
			{
				Player.LocalPlayer.IsRegistering = true;
			}
			kioskUIState = KioskUIState.EnterEmail;
			while (kioskUIState == KioskUIState.EnterEmail || kioskUIState == KioskUIState.Error)
			{
				yield return null;
				if (kioskUIState != KioskUIState.SendingEmail || string.IsNullOrEmpty(submittedEmail))
				{
					continue;
				}
				if (Profiles.LocalProfile.Verified)
				{
					errorMessage = "You are already a member!";
					kioskUIState = KioskUIState.Error;
					continue;
				}
				yield return Profiles.SendRegistrationEmail(submittedEmail, delegate(string error, string text)
				{
					if (string.IsNullOrEmpty(error))
					{
						kioskUIState = KioskUIState.EmailSent;
					}
					else
					{
						errorMessage = text;
						kioskUIState = KioskUIState.Error;
						AnalyticsHelper.UserRegistrationFlow("failedToSendEmail", string.Empty);
					}
				});
			}
			AnalyticsHelper.UserRegistrationFlow("emailSent", string.Empty);
			kioskState = KioskState.PendingProfileVerification;
			yield return WaitForProfileVerification();
			kioskUIState = KioskUIState.None;
			AnalyticsHelper.UserRegistrationFlow("complete", string.Empty);
			kioskState = KioskState.RegistrationComplete;
			submitButtonPressed = false;
			while (!submitButtonPressed)
			{
				yield return null;
			}
			if (IsHolderLocal)
			{
				Player.LocalPlayer.IsRegistering = false;
			}
			Player.LocalPlayer.PlayerProgression.PlayLevelUpFeedback();
			yield return new WaitForSeconds(2f);
		}
		ResetFlow();
	}

	private IEnumerator WaitForProfileVerification()
	{
		while (!Profiles.LocalProfile.Verified)
		{
			float timer = 15f;
			while (timer > 0f)
			{
				timer -= Time.unscaledDeltaTime;
				yield return null;
			}
			yield return Profiles.DownloadLocalProfile(null);
		}
	}

	private IEnumerator RunTakeSelfie()
	{
		kioskState = KioskState.TakingSelfie;
		selfieCam.Setup(Player.LocalPlayer, selfieCamRenderer);
		selfieCam.FixedPoint = cameraLensTransform;
		selfieCam.transform.position = cameraLensTransform.position;
		selfieCam.gameObject.SetActive(value: true);
		yield return new WaitForSeconds(1f);
		ShowNotification("3");
		AudioManager.Play3DSFX(selfieCountdownBeep, submitButton.transform.position);
		yield return new WaitForSeconds(1.5f);
		ShowNotification("2");
		AudioManager.Play3DSFX(selfieCountdownBeep, submitButton.transform.position);
		yield return new WaitForSeconds(1.5f);
		ShowNotification("1");
		AudioManager.Play3DSFX(selfieCountdownBeep, submitButton.transform.position);
		yield return new WaitForSeconds(1.5f);
		selfieCam.gameObject.SetActive(value: false);
		AudioManager.Play3DSFX(selfieCamShutter, submitButton.transform.position);
		StartCoroutine(ShowCameraFlash());
		kioskState = KioskState.VerifyingSelfie;
		submitButtonPressed = false;
		while (!submitButtonPressed)
		{
			yield return null;
		}
		UpdateKioskVisual();
		yield return RunUploadNewPicture();
	}

	private IEnumerator ShowCameraFlash()
	{
		cameraFlashAnimator.gameObject.SetActive(value: true);
		yield return null;
		float clipDuration = cameraFlashAnimator.GetCurrentAnimatorStateInfo(0).length;
		float t = 0f;
		while (t < clipDuration)
		{
			t += Time.deltaTime;
			yield return null;
		}
		cameraFlashAnimator.gameObject.SetActive(value: false);
	}

	private IEnumerator RunUploadNewPicture()
	{
		RenderTexture oldActive = RenderTexture.active;
		RenderTexture.active = selfieCam.RenderTexture;
		int width = selfieCam.RenderTexture.width;
		int height = selfieCam.RenderTexture.height;
		Texture2D virtualPhoto = new Texture2D(width, height, TextureFormat.RGB24, mipmap: false);
		virtualPhoto.ReadPixels(new Rect(0f, 0f, width, height), 0, 0);
		RenderTexture.active = oldActive;
		Texture2D scaledVirtualPhoto = UnityEngine.Object.Instantiate(virtualPhoto);
		int xDownsizePerSample = (int)((float)width - imageSize.x) / numDownsamples;
		int yDownsizePerSample = (int)((float)height - imageSize.y) / numDownsamples;
		for (int i = 1; i < numDownsamples - 1; i++)
		{
			TextureScale.Bilinear(scaledVirtualPhoto, width - i * xDownsizePerSample, height - i * yDownsizePerSample);
			yield return null;
		}
		TextureScale.Bilinear(scaledVirtualPhoto, (int)imageSize.x, (int)imageSize.y);
		byte[] imageData = scaledVirtualPhoto.EncodeToPNG();
		yield return Images.SetLocalProfileImage(imageData, delegate(string error)
		{
			if (!string.IsNullOrEmpty(error))
			{
				ShowNotification("Failed to update the profile picture!", 3f, ScreenSpaceNotificationManager.NotificationType.Medium);
				UnityEngine.Debug.LogError("Failed to update the profile picture. " + error);
				ResetFlow();
			}
		});
	}

	private void ShowNotification(string message, float duration = 1f, ScreenSpaceNotificationManager.NotificationType type = ScreenSpaceNotificationManager.NotificationType.Minor)
	{
		ScreenSpaceNotificationManager.Instance.Play(type, message, duration);
	}

	private void UpdateKioskVisual()
	{
		submitButtonPressed = false;
		bool flag = true;
		bool flag2 = true;
		string text = "Thanks!";
		Texture texture = selfieCamRenderer.material.mainTexture;
		switch (kioskState)
		{
		case KioskState.None:
		{
			bool verified = Profiles.LocalProfile.Verified;
			text = ((!verified) ? "START" : "Selfie");
			texture = ((!verified) ? signupTexture : updateSelfieTexture);
			flag2 = false;
			break;
		}
		case KioskState.TakingSelfie:
			text = "Smile :)";
			flag = false;
			flag2 = false;
			if (!IsHolderLocal)
			{
				texture = takingSelfieRemoteTexture;
			}
			break;
		case KioskState.VerifyingSelfie:
			text = "Accept?";
			if (!IsHolderLocal)
			{
				texture = takingSelfieRemoteTexture;
			}
			break;
		case KioskState.SelfieUpdated:
			flag = false;
			flag2 = false;
			texture = selfieUpdatedTexture;
			break;
		case KioskState.DownloadingProfile:
			text = "Syncing...";
			texture = signupFlowTexture;
			flag = false;
			break;
		case KioskState.SignupFlowStart:
			text = "Selfie";
			texture = signupFlowTexture;
			flag2 = false;
			break;
		case KioskState.PendingRegistration:
			flag = false;
			flag2 = false;
			text = "Check PC";
			texture = ((!IsHolderLocal) ? remoteCheckPCTexture : checkPCTexture);
			break;
		case KioskState.PendingProfileVerification:
			flag = false;
			flag2 = false;
			text = "Check Email";
			texture = ((!IsHolderLocal) ? remoteCheckPCTexture : checkEmailTexture);
			break;
		case KioskState.RegistrationComplete:
			flag2 = false;
			text = "Done!";
			texture = registrationCompleteTexture;
			break;
		}
		if (selfieCamRenderer.material.mainTexture != texture)
		{
			selfieCamRenderer.material.mainTexture = texture;
		}
		inUseText.gameObject.SetActive(IsInUse && !IsHolderLocal);
		submitButton.gameObject.SetActive(IsHolderLocal || !IsInUse);
		cancelButton.gameObject.SetActive(IsHolderLocal || !IsInUse);
		submitButton.interactable = flag;
		cancelButton.interactable = flag2;
		submitButton.OnDeselect(null);
		cancelButton.OnDeselect(null);
		submitButtonText.color = submitButtonText.color.ChangeAlpha((!flag) ? 0.3f : 1f);
		cancelButtonText.color = submitButtonText.color.ChangeAlpha((!flag2) ? 0.3f : 1f);
		submitButtonText.text = text;
		if (IsHolderLocal)
		{
			UpdateKioskUIState();
		}
		if (IsInUse)
		{
			powerupAmbienceLoopSource.Play();
		}
		else
		{
			powerupAmbienceLoopSource.Stop();
		}
	}

	private void UpdateKioskUIState()
	{
		bool flag = kioskUIState == KioskUIState.EnterEmail || kioskUIState == KioskUIState.Error || kioskUIState == KioskUIState.EmailSent;
		if (ViveControllerInput.Instance != null)
		{
			ViveControllerInput.Instance.StandAloneInput = flag;
		}
		if (PlatformManager.Instance != null)
		{
			PlatformManager.Instance.IgnoreVRFocus = flag;
		}
		canvas.gameObject.SetActive(kioskUIState != KioskUIState.None);
		UpdateEmailSubmitInteractive();
		emailSubmitButton.gameObject.SetActive(kioskUIState == KioskUIState.EnterEmail);
		emailInput.gameObject.SetActive(kioskUIState == KioskUIState.EnterEmail);
		tryAgainButton.gameObject.SetActive(kioskUIState == KioskUIState.Error);
		uiOkButton.gameObject.SetActive(kioskUIState == KioskUIState.EmailSent);
		returnToVRImage.gameObject.SetActive(kioskUIState == KioskUIState.EmailSent);
		uiCancelButton.gameObject.SetActive(kioskUIState != KioskUIState.SendingEmail && kioskUIState != KioskUIState.EmailSent);
		string text = "Please enter the email you'd like to use for membership:";
		switch (kioskUIState)
		{
		case KioskUIState.SendingEmail:
			text = "Sending email, please wait...";
			break;
		case KioskUIState.EmailSent:
			text = $"Please check your email: {submittedEmail}";
			break;
		case KioskUIState.Error:
			text = errorMessage;
			break;
		}
		informationText.text = text;
	}

	private void UpdateEmailSubmitInteractive()
	{
		bool interactable = UnityExtensions.IsValidEmail(emailInput.text);
		emailSubmitButton.interactable = interactable;
	}

	public void Email_InputChanged(string text)
	{
		UpdateEmailSubmitInteractive();
	}

	public void Button_Cancel()
	{
		ResetFlow();
	}

	public void Button_SubmitEmail(string email)
	{
		if (UnityExtensions.IsValidEmail(email))
		{
			submittedEmail = email;
			kioskUIState = KioskUIState.SendingEmail;
		}
	}

	public void Button_TryAgain()
	{
		kioskUIState = KioskUIState.EnterEmail;
	}

	public void Button_HideUI()
	{
		kioskUIState = KioskUIState.None;
	}

	private void OnKioskHolderChanged()
	{
		if (mainFlowCoroutine == null && kioskState == KioskState.None)
		{
			if (IsHolderLocal)
			{
				mainFlowCoroutine = StartCoroutine(RunMainFlow());
			}
			if (IsInUse)
			{
				AudioManager.Play3DSFX(powerupAmbience, notificationRoot.position);
			}
		}
		UpdateKioskVisual();
	}

	private void OnKioskStateChanged()
	{
		lastTimeKioskStateChanged = Time.time;
		AudioManager.Play3DSFX(stateChangeClip, notificationRoot.position);
		UpdateKioskVisual();
	}

	public void ReleaseKioskHolder()
	{
		if (IsHolderLocal || (PhotonNetwork.isMasterClient && PhotonPlayer.Find(KioskHolderId) == null))
		{
			KioskHolderId = PhotonPlayer.Invalid;
			kioskUIState = KioskUIState.None;
			kioskState = KioskState.None;
		}
	}

	protected virtual void OnPhotonPlayerDisconnected(PhotonPlayer oldPlayer)
	{
		if (PhotonNetwork.isMasterClient && KioskHolderId == oldPlayer.ID)
		{
			ResetFlow();
		}
	}
}
public class AxisConstrainedRigidbodyPickup : RigidbodyPickup
{
	public enum AllowedMovement
	{
		All = 2,
		None = 0,
		Positive = 1,
		Negative = -1
	}

	[Header("Movement constraints")]
	public AllowedMovement allowMovementOnX = AllowedMovement.All;

	public AllowedMovement allowMovementOnY = AllowedMovement.All;

	public AllowedMovement allowMovementOnZ = AllowedMovement.All;

	[Header("Rotation constraints")]
	public bool allowRotationOnX = true;

	public bool allowRotationOnY = true;

	public bool allowRotationOnZ = true;

	[Header("Spherical constraints")]
	public bool constrainToSphere;

	public Vector3 sphericalRestrictionCenter;

	public float sphericalRestrictionRadius;

	public override Vector3 TargetRigidbodyPosition
	{
		get
		{
			Vector3 position = base.transform.InverseTransformPoint(base.TargetRigidbodyPosition);
			if (allowMovementOnX != AllowedMovement.All)
			{
				if (allowMovementOnX == AllowedMovement.None)
				{
					position.x = 0f;
				}
				else
				{
					position.x = ((allowMovementOnX != AllowedMovement.Negative) ? Mathf.Max(0f, position.x) : Mathf.Min(0f, position.x));
				}
			}
			if (allowMovementOnY != AllowedMovement.All)
			{
				if (allowMovementOnY == AllowedMovement.None)
				{
					position.y = 0f;
				}
				else
				{
					position.y = ((allowMovementOnY != AllowedMovement.Negative) ? Mathf.Max(0f, position.y) : Mathf.Min(0f, position.y));
				}
			}
			if (allowMovementOnZ != AllowedMovement.All)
			{
				if (allowMovementOnZ == AllowedMovement.None)
				{
					position.z = 0f;
				}
				else
				{
					position.z = ((allowMovementOnZ != AllowedMovement.Negative) ? Mathf.Max(0f, position.z) : Mathf.Min(0f, position.z));
				}
			}
			position = base.transform.TransformPoint(position);
			if (constrainToSphere)
			{
				Vector3 vector = position - sphericalRestrictionCenter;
				if (vector.sqrMagnitude > sphericalRestrictionRadius * sphericalRestrictionRadius)
				{
					position = sphericalRestrictionCenter + vector.normalized * sphericalRestrictionRadius;
				}
			}
			return position;
		}
	}

	public override Quaternion TargetRigidbodyRotation
	{
		get
		{
			Vector3 eulerAngles = base.transform.InverseTransformRotation(base.TargetRigidbodyRotation).eulerAngles;
			if (!allowRotationOnX)
			{
				eulerAngles.x = 0f;
			}
			if (!allowRotationOnY)
			{
				eulerAngles.y = 0f;
			}
			if (!allowRotationOnZ)
			{
				eulerAngles.z = 0f;
			}
			return base.transform.TransformRotation(Quaternion.Euler(eulerAngles));
		}
	}

	public void SetAllConstraints(bool constrain)
	{
		AllowedMovement allowedMovement = ((!constrain) ? AllowedMovement.All : AllowedMovement.None);
		allowMovementOnX = (allowMovementOnY = (allowMovementOnZ = allowedMovement));
		allowRotationOnX = (allowRotationOnY = (allowRotationOnZ = !constrain));
		constrainToSphere = constrain;
	}
}
public class FaceCamera : UnityEngine.MonoBehaviour
{
	private void Update()
	{
		if (SingletonMonoBehaviour<CameraRig>.Instance != null)
		{
			Vector3 vector = base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
			Vector3 normalized = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
			if (normalized != Vector3.zero)
			{
				base.transform.rotation = Quaternion.LookRotation(normalized, Vector3.up);
			}
		}
	}
}
public class FollowBillboard : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Vector3 viewSpaceTargetOffset = new Vector3(0f, 0.2f, 0f);

	public Transform Target;

	public Camera Camera;

	private void Update()
	{
		if (Target != null && Camera != null)
		{
			Vector3 up = Vector3.up;
			Vector3 normalized = Vector3.ProjectOnPlane(Camera.transform.forward, Vector3.up).normalized;
			Vector3 normalized2 = Vector3.Cross(normalized, up).normalized;
			base.transform.position = Target.position + normalized2 * viewSpaceTargetOffset.x + up * viewSpaceTargetOffset.y + normalized * viewSpaceTargetOffset.z;
			base.transform.rotation = Quaternion.LookRotation(normalized, up);
		}
	}
}
[RequireComponent(typeof(Interpolator))]
public class FollowCamera : UnityEngine.MonoBehaviour
{
	public float DistanceFromPlayer = 1f;

	public bool FacePlayer = true;

	public Vector3 PositionOffset = Vector3.zero;

	public Vector3 RotationOffset = Vector3.zero;

	public bool StayAtHeadHeight;

	public float OuterFollowAngle = 45f;

	private Interpolator interpolator;

	private void Awake()
	{
		interpolator = GetComponent<Interpolator>();
	}

	private void OnEnable()
	{
		ForceUpdate();
	}

	private void Update()
	{
		if (!SingletonMonoBehaviour<CameraRig>.IsInitialized)
		{
			return;
		}
		Transform transform = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform;
		if (!(transform != null))
		{
			return;
		}
		Vector3 vector = ((!StayAtHeadHeight) ? transform.forward : Vector3.Cross(transform.right, Vector3.up));
		float num = Vector3.Angle(vector, base.transform.position - transform.position);
		if (num >= OuterFollowAngle)
		{
			interpolator.TargetPosition = transform.position + vector * DistanceFromPlayer + base.transform.rotation * PositionOffset;
			if (FacePlayer)
			{
				interpolator.TargetRotation = Quaternion.LookRotation(transform.position - interpolator.TargetPosition) * Quaternion.Euler(RotationOffset);
			}
		}
	}

	public void ForceUpdate()
	{
		Update();
		interpolator.SnapToTarget();
	}
}
[RequireComponent(typeof(Interpolator))]
public class FollowTarget : UnityEngine.MonoBehaviour
{
	public Transform Target;

	public float DistanceFromTarget = 1f;

	[Tooltip("If the target is farther than this than force update position.")]
	public float SnapDistance = 5f;

	public bool FaceTarget = true;

	public bool FaceTargetXZOnly = true;

	public Vector2 DistanceBoundaries = new Vector2(0.75f, 1.5f);

	public Vector3 PositionOffset = Vector3.zero;

	public Vector3 RotationOffset = Vector3.zero;

	public bool StayAtTargetHeight;

	public float OuterFollowAngle = 35f;

	private Interpolator interpolator;

	private void Awake()
	{
		interpolator = GetComponent<Interpolator>();
	}

	private void OnEnable()
	{
		ForceUpdate();
	}

	private void Update()
	{
		UpdateTransform();
	}

	private void UpdateTransform(bool force = false)
	{
		if (!(Target != null) || !(interpolator != null))
		{
			return;
		}
		Vector3 vector = ((!StayAtTargetHeight) ? Target.forward : Vector3.Cross(Target.right, Vector3.up));
		float num = Vector3.Angle(vector, base.transform.position - Target.position);
		float magnitude = (base.transform.position - Target.position).magnitude;
		bool flag = magnitude < DistanceBoundaries.x || magnitude > DistanceBoundaries.y;
		if (!force && !flag && !(num >= OuterFollowAngle))
		{
			return;
		}
		interpolator.TargetPosition = Target.position + vector * DistanceFromTarget + base.transform.rotation * PositionOffset;
		if (FaceTarget)
		{
			Vector3 forward = Target.position - interpolator.TargetPosition;
			if (FaceTargetXZOnly)
			{
				forward.y = 0f;
			}
			interpolator.TargetRotation = Quaternion.LookRotation(forward) * Quaternion.Euler(RotationOffset);
		}
		if (magnitude > SnapDistance)
		{
			interpolator.SnapToTarget();
		}
	}

	public void ForceUpdate()
	{
		UpdateTransform(force: true);
		interpolator.SnapToTarget();
	}
}
public class Interpolator : UnityEngine.MonoBehaviour
{
	[Header("Movement")]
	public bool UseMovementEaseIn;

	[Tooltip("At what minimum distance should we apply easeIn")]
	public float MovementEaseInDistance = 0.5f;

	[Tooltip("What percent of the original speed easeIn should effect.")]
	[Range(0f, 0.99f)]
	public float MovementEaseInPercent = 0.8f;

	[Tooltip("Meters/second")]
	[SerializeField]
	private float movementSpeed = 2f;

	private bool isAnimatingPosition;

	private Vector3 targetPosition = Vector3.zero;

	[Header("Rotation")]
	[Tooltip("Degrees/second")]
	[SerializeField]
	private float rotationSpeed = 90f;

	private bool isAnimatingRotation;

	private Quaternion targetRotation = Quaternion.identity;

	public bool IsRunning => base.enabled;

	public Vector3 TargetPosition
	{
		get
		{
			if (isAnimatingPosition)
			{
				return targetPosition;
			}
			return base.transform.position;
		}
		set
		{
			targetPosition = value;
			isAnimatingPosition = true;
			base.enabled = true;
		}
	}

	public Quaternion TargetRotation
	{
		get
		{
			if (isAnimatingRotation)
			{
				return targetRotation;
			}
			return base.transform.rotation;
		}
		set
		{
			targetRotation = value;
			isAnimatingRotation = true;
			base.enabled = true;
		}
	}

	private void Update()
	{
		EvaluateMovementFrame();
		EvaluateRotationFrame();
		if (!isAnimatingPosition && !isAnimatingRotation)
		{
			base.enabled = false;
		}
	}

	private void EvaluateMovementFrame()
	{
		if (isAnimatingPosition)
		{
			float num = Time.deltaTime * movementSpeed;
			if (UseMovementEaseIn)
			{
				float num2 = Mathf.Clamp01((targetPosition - base.transform.position).magnitude / MovementEaseInDistance) * MovementEaseInPercent + (1f - MovementEaseInPercent);
				num *= num2;
			}
			base.transform.position = Vector3.MoveTowards(base.transform.position, targetPosition, num);
			float magnitude = (targetPosition - base.transform.position).magnitude;
			if (magnitude < num)
			{
				isAnimatingPosition = false;
				base.transform.position = targetPosition;
			}
		}
	}

	private void EvaluateRotationFrame()
	{
		if (isAnimatingRotation)
		{
			float num = Time.deltaTime * rotationSpeed;
			base.transform.rotation = Quaternion.RotateTowards(base.transform.rotation, targetRotation, num);
			float num2 = Quaternion.Angle(targetRotation, base.transform.rotation);
			if (num2 < num)
			{
				isAnimatingRotation = false;
				base.transform.rotation = targetRotation;
			}
		}
	}

	public void StopInterpolation()
	{
		isAnimatingRotation = false;
		isAnimatingPosition = false;
	}

	public void SnapToTarget()
	{
		base.transform.position = TargetPosition;
		base.transform.rotation = TargetRotation;
		StopInterpolation();
	}
}
public class KinematicRigidbodyPickup : RigidbodyPickup
{
	public override void Release()
	{
		base.Release();
		base.Rigidbody.isKinematic = true;
		base.Rigidbody.ClearVelocity();
	}
}
public class LaserTeleporter : UnityEngine.MonoBehaviour
{
	public enum LaserMode
	{
		ValidTeleportPosition,
		InvalidTeleportPosition,
		InvalidTeleportDirection,
		RestrictedTeleportPosition,
		ValidPortalPosition,
		Cooldown,
		Disabled,
		ValidTeleportPositionWithRotation,
		InvalidPortalPosition,
		ValidLevelLoadPortal
	}

	private enum MovementActionState
	{
		NONE,
		PREPARING,
		RUNNING
	}

	private struct TeleportSelectionData
	{
		public Vector3 Position;

		public Tool HitTool;

		public Vector3 HitToolPosition;

		public Vector3 HitToolNormal;

		public Vector3 HitToolDirection;
	}

	[SerializeField]
	private Transform laserStartPosition;

	[SerializeField]
	private Transform visualRoot;

	[SerializeField]
	private ParabolicPointer parabolicPointer;

	[Header("Visual feedback")]
	[SerializeField]
	private Renderer cooldownRenderer;

	[SerializeField]
	private Transform cooldownVisualCenter;

	[Header("Teleportation")]
	[SerializeField]
	private PlayerTeleportDecal playerTeleportDecalPrefab;

	[Tooltip("We will use this radius in CheckSphere to prevent you from teleporting into other sh.t")]
	[SerializeField]
	private float headCollisionRadius = 0.2f;

	[SerializeField]
	private float toolHitWindow = 0.25f;

	[SerializeField]
	private float teleportRotationMinChargeTime = 0.2f;

	[Header("Continous Rotation")]
	[SerializeField]
	private float continousRotationInputStepSize = 7.5f;

	[SerializeField]
	private float continousRotationOutputStepSize = 22.5f;

	[SerializeField]
	private float continuousRotationInputScalar = 2f;

	[Header("Menu")]
	[SerializeField]
	private LineRenderer menuLaser;

	[Header("Collision")]
	[SerializeField]
	private BoxCollider worldOverlapCollider;

	private PlayerTeleportDecal playerTeleportDecal;

	private GameObject pointer;

	private float lastToolHitSelectionTime;

	private TeleportSelectionData lastToolHitData;

	private float teleportRotationChargeStartTime;

	private bool teleportRotationEnabled;

	private PlayerHand otherHand;

	private MovementActionState _teleportState;

	private MovementActionState currentRotationState;

	private MovementActionState continousRotationState;

	private Vector3 lastContinuousRotationVector = Vector3.zero;

	[NonSerialized]
	public Vector3 TeleportTarget;

	private LaserMode laserMode = LaserMode.Disabled;

	public static float FlightSpeed = 10f;

	public ParabolicPointer ParabolicPointer => parabolicPointer;

	public Vector3 TeleportRotationForward { get; private set; }

	[HideInInspector]
	public Player Player { get; internal set; }

	public PlayerHand Hand { get; internal set; }

	public bool Visible
	{
		get
		{
			return visualRoot.gameObject.activeSelf;
		}
		set
		{
			visualRoot.gameObject.SetActive(value);
		}
	}

	public bool TeleportLaserVisible => Mode != LaserMode.Disabled;

	public bool MenuLaserVisible => menuLaser.enabled;

	private bool ToolHitAvailable => IsWithinToolHitWindow(toolHitWindow);

	private bool ToolHitThisFrame => IsWithinToolHitWindow(2f * Time.deltaTime);

	private bool IsOutOfBounds => Player.IsOutOfBounds || worldOverlapCollider.CheckOverlap(2048, QueryTriggerInteraction.Ignore);

	private MovementActionState teleportState
	{
		get
		{
			return _teleportState;
		}
		set
		{
			if ((_teleportState == MovementActionState.RUNNING && value != MovementActionState.RUNNING) || _teleportState == MovementActionState.RUNNING || value == MovementActionState.RUNNING)
			{
			}
			_teleportState = value;
		}
	}

	public LaserMode Mode
	{
		get
		{
			return laserMode;
		}
		set
		{
			laserMode = value;
			switch (laserMode)
			{
			case LaserMode.Disabled:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Disabled;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
				break;
			case LaserMode.InvalidTeleportPosition:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.FadeOut;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
				break;
			case LaserMode.InvalidTeleportDirection:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Shortened;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
				break;
			case LaserMode.RestrictedTeleportPosition:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Invalid;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.Ground;
				playerTeleportDecal.IsValidPosition = false;
				break;
			case LaserMode.ValidTeleportPosition:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.AvatarAndGround;
				playerTeleportDecal.IsValidPosition = true;
				break;
			case LaserMode.ValidTeleportPositionWithRotation:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.AvatarAndGroundAndArrow;
				playerTeleportDecal.IsValidPosition = true;
				break;
			case LaserMode.ValidPortalPosition:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.AvatarAndGround;
				playerTeleportDecal.IsValidPosition = true;
				break;
			case LaserMode.InvalidPortalPosition:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Invalid;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.Ground;
				playerTeleportDecal.IsValidPosition = false;
				break;
			case LaserMode.Cooldown:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Invisible;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
				break;
			case LaserMode.ValidLevelLoadPortal:
				parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
				playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
				playerTeleportDecal.IsValidPosition = true;
				break;
			}
		}
	}

	private void Awake()
	{
		playerTeleportDecal = UnityEngine.Object.Instantiate(playerTeleportDecalPrefab);
		playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
		parabolicPointer.transform.localPosition = laserStartPosition.localPosition;
		parabolicPointer.LaserTeleporter = this;
		visualRoot.gameObject.SetActive(value: false);
		menuLaser.enabled = false;
	}

	private void Start()
	{
		Player.SetParentPlayerRoot(playerTeleportDecal.transform);
		GameObject obj = base.gameObject;
		obj.name = obj.name + "_" + Hand.Type;
		otherHand = ((Hand.Type != PlayerHand.HandType.Left) ? Player.LeftHand : Player.RightHand);
		parabolicPointer.StraightLaser = false;
	}

	private void OnDestroy()
	{
		if (pointer != null)
		{
			UnityEngine.Object.Destroy(pointer.gameObject);
		}
		if (playerTeleportDecal != null)
		{
			UnityEngine.Object.Destroy(playerTeleportDecal.gameObject);
		}
	}

	private void OnDisable()
	{
		if (pointer != null)
		{
			pointer.gameObject.SetActive(value: false);
		}
		if (playerTeleportDecal != null)
		{
			playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
		}
	}

	private void Update()
	{
		if (Hand != null)
		{
			base.transform.position = Hand.transform.position;
			base.transform.rotation = Hand.transform.rotation;
		}
		else
		{
			UnityEngine.Debug.LogError("Laser teleporter update without Hand should never happen.");
		}
		if (Hand.isLocal)
		{
			UpdateTeleportation();
			UpdateInPlaceRotation();
			UpdateContinuousRotation();
			UpdateMenuLaser();
			UpdateButtonMaterial();
		}
		UpdateDecal();
	}

	private void UpdateTeleportation()
	{
		bool teleportButtonDown = Hand.ControllerIO != null && Hand.ControllerIO.TeleportButtonDown;
		bool teleportButtonPressed = Hand.ControllerIO != null && Hand.ControllerIO.TeleportButtonPressed;
		bool teleportButtonUp = Hand.ControllerIO != null && Hand.ControllerIO.TeleportButtonUp;
		ClearTeleportLaser();
		switch (teleportState)
		{
		case MovementActionState.NONE:
			UpdateTeleportNoneState(teleportButtonDown, teleportButtonPressed, teleportButtonUp);
			break;
		case MovementActionState.RUNNING:
			UpdateTeleportRunningState(teleportButtonDown, teleportButtonPressed, teleportButtonUp);
			break;
		}
	}

	private void UpdateInPlaceRotation()
	{
		if (Hand.PlayerHandRemote.teleportState == MovementActionState.NONE && otherHand.PlayerHandRemote.teleportState == MovementActionState.NONE && Hand.ControllerIO != null)
		{
			if (Hand.ControllerIO.RotateLeftButtonDown)
			{
				Player.PlayerLocomotion.RotateInPlaceLeft();
			}
			else if (Hand.ControllerIO.RotateRightButtonDown)
			{
				Player.PlayerLocomotion.RotateInPlaceRight();
			}
			else if (Hand.ControllerIO.RotateDownButtonDown)
			{
				Player.PlayerLocomotion.RotateInPlace180();
			}
		}
	}

	private void UpdateContinuousRotation()
	{
		bool buttonPressed = Hand.ControllerIO != null && Hand.ControllerIO.PushToTalkButtonPressed && otherHand.ControllerIO != null && otherHand.ControllerIO.PushToTalkButtonPressed;
		UnityEngine.Debug.DrawLine(Player.CurrentFloorPosition, Player.CurrentFloorPosition + lastContinuousRotationVector, Color.green);
		switch (continousRotationState)
		{
		case MovementActionState.NONE:
			UpdateContinousRotationNoneState(buttonPressed);
			break;
		case MovementActionState.RUNNING:
			UpdateContinuousRotationRunningState(buttonPressed);
			break;
		}
	}

	private void UpdateContinousRotationNoneState(bool buttonPressed)
	{
		if (Player.PlayerLocomotion.ContinuousRotationMode != ContinuousRotationMode.DISABLED && otherHand.PlayerHandRemote.continousRotationState == MovementActionState.NONE && Hand.PlayerHandRemote.teleportState == MovementActionState.NONE && otherHand.PlayerHandRemote.teleportState == MovementActionState.NONE && buttonPressed && TryGetContinuousRotationVector(out lastContinuousRotationVector))
		{
			Player.PlayerLocomotion.StartContinuousRotation();
			continousRotationState = MovementActionState.RUNNING;
			UpdateContinuousRotationRunningState(buttonPressed);
		}
	}

	private void UpdateContinuousRotationRunningState(bool buttonPressed)
	{
		if (Player.PlayerLocomotion.ContinuousRotationMode == ContinuousRotationMode.DISABLED || otherHand.PlayerHandRemote.continousRotationState != MovementActionState.NONE || Hand.PlayerHandRemote.teleportState != MovementActionState.NONE || otherHand.PlayerHandRemote.teleportState != MovementActionState.NONE || !buttonPressed || !TryGetContinuousRotationVector(out var continuousRotationVector))
		{
			Player.PlayerLocomotion.StopContinuousRotation();
			continousRotationState = MovementActionState.NONE;
			return;
		}
		float num = lastContinuousRotationVector.AngleSignedVector3(continuousRotationVector);
		if (Player.PlayerLocomotion.ContinuousRotationMode == ContinuousRotationMode.DISCRETE && Mathf.Abs(num) >= continousRotationInputStepSize)
		{
			lastContinuousRotationVector = continuousRotationVector;
			Player.PlayerLocomotion.AddContinuousRotation(continousRotationOutputStepSize * Mathf.Sign(num));
		}
		else if (Player.PlayerLocomotion.ContinuousRotationMode == ContinuousRotationMode.CONTINUOUS)
		{
			Player.PlayerLocomotion.SetContinuousRotation(num * continuousRotationInputScalar);
		}
	}

	private bool TryGetContinuousRotationVector(out Vector3 continuousRotationVector)
	{
		Vector3 vector = Vector3.ProjectOnPlane(Player.RightHand.transform.position - Player.LeftHand.transform.position, Vector3.up);
		if (vector.sqrMagnitude <= 0.01f)
		{
			continuousRotationVector = Vector3.zero;
			return false;
		}
		continuousRotationVector = Vector3.Cross(vector.normalized, Vector3.up);
		continuousRotationVector = Player.transform.InverseTransformDirection(continuousRotationVector).normalized;
		return true;
	}

	private void UpdateTeleportNoneState(bool teleportButtonDown, bool teleportButtonPressed, bool teleportButtonUp)
	{
		if (otherHand.PlayerHandRemote.teleportState == MovementActionState.NONE && teleportButtonDown)
		{
			teleportState = MovementActionState.RUNNING;
			UpdateTeleportRunningState(teleportButtonDown, teleportButtonPressed, teleportButtonUp);
		}
	}

	private void UpdateTeleportRunningState(bool teleportButtonDown, bool teleportButtonPressed, bool teleportButtonUp)
	{
		if (otherHand.PlayerHandRemote.teleportState != MovementActionState.NONE || (!teleportButtonPressed && !teleportButtonUp))
		{
			teleportState = MovementActionState.NONE;
			return;
		}
		Mode = UpdateLaser(parabolicPointer);
		UpdateTeleportRotation();
		if (currentRotationState == MovementActionState.RUNNING && Mode == LaserMode.ValidTeleportPosition)
		{
			Mode = LaserMode.ValidTeleportPositionWithRotation;
		}
		if (teleportButtonUp)
		{
			teleportState = MovementActionState.NONE;
			if (Mode == LaserMode.ValidPortalPosition || Mode == LaserMode.ValidLevelLoadPortal)
			{
				PerformPortalTeleport(parabolicPointer.TeleportationPortal);
			}
			else if (Mode == LaserMode.ValidTeleportPosition)
			{
				PerformTeleport(TeleportTarget, parabolicPointer.HitTool, parabolicPointer.HitToolPosition, parabolicPointer.HitToolNormal);
			}
			else if (Mode == LaserMode.ValidTeleportPositionWithRotation)
			{
				PerformTeleport(TeleportTarget, TeleportRotationForward, parabolicPointer.HitTool, parabolicPointer.HitToolPosition, parabolicPointer.HitToolNormal);
			}
		}
	}

	private void ClearTeleportLaser()
	{
		Mode = LaserMode.Disabled;
		parabolicPointer.ClearParabolicRaycasts();
	}

	private LaserMode UpdateLaser(ParabolicPointer laser)
	{
		if (!Player.PlayerLocomotion.TeleportEnabled || Player.PlayerLocomotion.TeleportSuppressed || Player.PlayerLocomotion.TeleportOnCooldown || IsOutOfBounds)
		{
			return LaserMode.Cooldown;
		}
		if (Vector3.Angle(base.transform.forward, Vector3.up) < Player.PlayerLocomotion.MaxTeleportPitchDegrees)
		{
			return LaserMode.InvalidTeleportDirection;
		}
		laser.PerformParabolicRaycasts(Player.PlayerLocomotion.MaxTeleportDistance, Player.PlayerLocomotion.ChargeAmount);
		if (laser.HitTool != null)
		{
			lastToolHitSelectionTime = Time.time;
			lastToolHitData = new TeleportSelectionData
			{
				Position = laser.FinalParabolaPoint,
				HitTool = laser.HitTool,
				HitToolPosition = laser.HitToolPosition,
				HitToolNormal = laser.HitToolNormal,
				HitToolDirection = (laser.FinalParabolaPoint - base.transform.position).normalized
			};
		}
		if (!laser.HitSomething)
		{
			return LaserMode.InvalidTeleportPosition;
		}
		if (laser.TeleportationPortal != null && laser.TeleportationPortal.IsValid)
		{
			TeleportTarget = laser.TeleportationPortal.DestinationPosition;
			if (laser.TeleportationPortal.SupportsActivityLoading || laser.TeleportationPortal.SupportsPlayerRespawn)
			{
				return LaserMode.ValidLevelLoadPortal;
			}
			if (CheckSafeTeleportPosition(TeleportTarget))
			{
				return LaserMode.ValidPortalPosition;
			}
			return LaserMode.InvalidPortalPosition;
		}
		TeleportTarget = laser.FinalParabolaPoint;
		if (laser.PointOnTeleportRegion && CheckSafeTeleportPosition(laser.FinalParabolaPoint) && (laser.TeleportRestrictions == null || laser.TeleportRestrictions.LocalPlayerCanTeleport))
		{
			return LaserMode.ValidTeleportPosition;
		}
		return LaserMode.RestrictedTeleportPosition;
	}

	private void UpdateTeleportRotation()
	{
		bool rotatingPressed = otherHand.ControllerIO != null && !otherHand.ControllerIO.TeleportRotateAxisInDeadZone;
		switch (currentRotationState)
		{
		case MovementActionState.NONE:
			UpdateTeleportRotationNoneState(rotatingPressed);
			break;
		case MovementActionState.PREPARING:
			UpdateTeleportRotationPrepareState(rotatingPressed);
			break;
		case MovementActionState.RUNNING:
			UpdateTeleportRotationChargingState(rotatingPressed);
			break;
		}
	}

	private void UpdateTeleportRotationNoneState(bool rotatingPressed)
	{
		if (teleportRotationEnabled && rotatingPressed)
		{
			teleportRotationChargeStartTime = Time.time;
			currentRotationState = MovementActionState.PREPARING;
			UpdateTeleportRotationPrepareState(rotatingPressed);
		}
	}

	private void UpdateTeleportRotationPrepareState(bool rotatingPressed)
	{
		if (!rotatingPressed)
		{
			currentRotationState = MovementActionState.NONE;
			UpdateTeleportRotationNoneState(rotatingPressed);
		}
		else if (Time.time - teleportRotationChargeStartTime >= teleportRotationMinChargeTime)
		{
			currentRotationState = MovementActionState.RUNNING;
			UpdateTeleportRotationChargingState(rotatingPressed);
		}
	}

	private void UpdateTeleportRotationChargingState(bool rotatingPressed)
	{
		if (!rotatingPressed)
		{
			currentRotationState = MovementActionState.NONE;
			UpdateTeleportRotationNoneState(rotatingPressed);
		}
		else
		{
			TeleportRotationForward = RotationVectorFromRotationAxis(otherHand.ControllerIO.TeleportRotateAxis);
		}
	}

	private Vector3 RotationVectorFromRotationAxis(Vector2 rotationAxis)
	{
		Vector3 normalized = Vector3.ProjectOnPlane(Player.Head.transform.forward, Vector3.up).normalized;
		Vector3 vector = -Vector3.Cross(normalized, Vector3.up).normalized;
		return normalized * rotationAxis.y + vector * rotationAxis.x;
	}

	private void UpdateMenuLaser()
	{
		if (Mode != LaserMode.Disabled || !Hand.ControllerIO.UIRaycastPosition.HasValue)
		{
			menuLaser.enabled = false;
			return;
		}
		menuLaser.enabled = true;
		Vector3 value = Hand.ControllerIO.UIRaycastPosition.Value;
		menuLaser.SetPosition(0, laserStartPosition.position);
		menuLaser.SetPosition(1, value);
		Color color = menuLaser.material.color;
		color.a = ((!Hand.ControllerIO.UISelectable) ? 0.3f : 0.85f);
		menuLaser.material.color = color;
	}

	private void UpdateDecal()
	{
		if (playerTeleportDecal.VisibilityMode != PlayerTeleportDecal.DecalVisibilityMode.None)
		{
			playerTeleportDecal.UpdateAvatarDecal(Player, TeleportTarget, currentRotationState == MovementActionState.RUNNING, TeleportRotationForward);
			bool flag = Hand.isLocal && ToolHitThisFrame;
			playerTeleportDecal.UpdateToolHitDecal(flag, Player.PlayerLocomotion.ChargeAmount, lastToolHitData.HitToolPosition, lastToolHitData.HitToolNormal);
		}
	}

	public void PerformPortalTeleport(TeleportationPortal portal)
	{
		Player.PlayerLocomotion.TeleportTo(TeleportTarget, hasRotation: false, Vector3.zero, portal, null, Vector3.zero, Vector3.zero);
	}

	public void PerformTeleport(Vector3 position, Tool hitTool, Vector3 hitToolPosition, Vector3 hitToolNormal)
	{
		if (ToolHitAvailable)
		{
			Player.PlayerLocomotion.TeleportTo(lastToolHitData.Position, hasRotation: false, Vector3.zero, null, lastToolHitData.HitTool, lastToolHitData.HitToolPosition, lastToolHitData.HitToolDirection);
		}
		else
		{
			Player.PlayerLocomotion.TeleportTo(position, hasRotation: false, Vector3.zero, null, null, Vector3.zero, Vector3.zero);
		}
		Hand.Vibrate(1, 1000);
	}

	public void PerformTeleport(Vector3 position, Vector3 rotationForward, Tool hitTool, Vector3 hitToolPosition, Vector3 hitToolNormal)
	{
		if (ToolHitAvailable)
		{
			Player.PlayerLocomotion.TeleportTo(lastToolHitData.Position, hasRotation: true, rotationForward, null, lastToolHitData.HitTool, lastToolHitData.HitToolPosition, lastToolHitData.HitToolDirection);
		}
		else
		{
			Player.PlayerLocomotion.TeleportTo(position, hasRotation: true, rotationForward, null, null, Vector3.zero, Vector3.zero);
		}
		Hand.Vibrate(1, 1000);
	}

	private bool IsWithinToolHitWindow(float window)
	{
		return Time.time - lastToolHitSelectionTime < window;
	}

	private bool IsValidTeleportMode(LaserMode mode)
	{
		return mode != LaserMode.Disabled;
	}

	private bool CheckSafeTeleportPosition(Vector3 newPlayerFloorPosition)
	{
		Vector3 position = newPlayerFloorPosition + Player.Head.HeightOffset;
		if (Physics.CheckSphere(position, headCollisionRadius, 3073, QueryTriggerInteraction.Ignore))
		{
			return false;
		}
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null)
			{
				float magnitude = (player.CurrentFloorPosition - newPlayerFloorPosition).magnitude;
				float num = ((!Player.PlayerLocomotion.HasOverrideTeleportBuffer) ? player.PlayerLocomotion.TeleportBufferDistance : Player.PlayerLocomotion.OverrideTeleportBuffer);
				if (magnitude <= num)
				{
					return false;
				}
			}
		}
		return true;
	}

	private void UpdateButtonMaterial()
	{
		float teleportCooldownValue = Player.PlayerLocomotion.TeleportCooldownValue;
		Vector3 vector = visualRoot.InverseTransformPoint(cooldownVisualCenter.position);
		Vector3 vector2 = visualRoot.InverseTransformDirection(cooldownVisualCenter.up);
		Vector3 vector3 = visualRoot.InverseTransformDirection(cooldownVisualCenter.forward);
		Material[] materials = cooldownRenderer.materials;
		foreach (Material material in materials)
		{
			material.SetVector("_PlaneCenterLocal", vector);
			material.SetVector("_PlaneNormalLocal", vector2);
			material.SetVector("_PlaneForwardLocal", vector3);
			material.SetFloat("_Progress", teleportCooldownValue);
		}
	}
}
