public class OculusPlatformManager : PlatformManager
{
	private const float HMD_REFRESH_RATE = 90f;

	public override PlatformType CurrentPlatform => PlatformType.OCULUS;

	public override HardwareType CurrentHardwareType => HardwareType.OCULUS;

	public override bool IgnoreVRFocus
	{
		set
		{
			OVRPlugin.ignoreVrFocus = value;
		}
	}

	public override bool HasVRFocus => OVRManager.hasVrFocus;

	public override IEnumerator Initialize(InitializeCallback callback)
	{
		try
		{
			Oculus.Platform.Core.Initialize();
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
			callback("Failed to initialize Oculus Platform");
			yield break;
		}
		OculusApiCoroutine checkEntitlement = Entitlements.IsUserEntitledToApplication().AsCoroutine();
		yield return checkEntitlement;
		if (checkEntitlement.Result.IsError)
		{
			callback("You do not have permission to play this game");
			yield break;
		}
		OculusApiCoroutine<User> getLoggedInUser = Users.GetLoggedInUser().AsCoroutine();
		yield return getLoggedInUser;
		if (getLoggedInUser.Result.IsError)
		{
			callback("Unable to load Oculus user profile");
			yield break;
		}
		User user = getLoggedInUser.Result.Data;
		base.PlatformProfileId = user.ID;
		base.PlatformProfileName = user.OculusID;
		Player.SetPlatformPlayerId(CurrentPlatform, base.PlatformProfileId);
		UnityEngine.Application.runInBackground = true;
		OVRPlugin.ignoreVrFocus = false;
		Time.fixedDeltaTime = Time.timeScale / 90f;
		callback(null);
	}

	public override void SetRichPresenceStatus(string statusText)
	{
	}
}
public abstract class PlatformManager : UnityEngine.MonoBehaviour
{
	public enum PlatformType
	{
		STEAM,
		OCULUS
	}

	public enum HardwareType
	{
		VIVE,
		OCULUS
	}

	public enum TrackingMode
	{
		DEFAULT,
		ONE_EIGHTY_DEGREE,
		THREE_SIXTY_DEGREE
	}

	public delegate void InitializeCallback(string error);

	private TrackingMode currentTrackingMode;

	private string SAVED_TRACKING_MODE_KEY = "SAVED_TRACKING_MODE";

	public static PlatformManager Instance { get; private set; }

	public ulong PlatformProfileId { get; protected set; }

	public string PlatformProfileName { get; protected set; }

	public byte[] PlatformProfileImage { get; protected set; }

	public TrackingMode CurrentTrackingMode
	{
		get
		{
			if (currentTrackingMode == TrackingMode.DEFAULT)
			{
				return TrackingMode.THREE_SIXTY_DEGREE;
			}
			return currentTrackingMode;
		}
		set
		{
			currentTrackingMode = value;
			if (currentTrackingMode != SavedTrackingMode)
			{
				SavedTrackingMode = currentTrackingMode;
			}
		}
	}

	public abstract PlatformType CurrentPlatform { get; }

	public abstract HardwareType CurrentHardwareType { get; }

	public abstract bool IgnoreVRFocus { set; }

	public abstract bool HasVRFocus { get; }

	private TrackingMode SavedTrackingMode
	{
		get
		{
			return (TrackingMode)PlayerPrefs.GetInt(SAVED_TRACKING_MODE_KEY, 0);
		}
		set
		{
			PlayerPrefs.SetInt(SAVED_TRACKING_MODE_KEY, (int)value);
		}
	}

	protected void Awake()
	{
		if (Instance != null)
		{
			UnityEngine.Debug.LogError("There can only be one PlatformManager!");
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			Instance = this;
			CurrentTrackingMode = SavedTrackingMode;
		}
	}

	public abstract IEnumerator Initialize(InitializeCallback callback);

	public abstract void SetRichPresenceStatus(string statusText);
}
