internal class SteamPlatformManager : PlatformManager
{
	private HardwareType? currentHardwareType;

	public const uint RECROOM_APP_ID = 471710u;

	private bool initialized;

	private Callback<GameRichPresenceJoinRequested_t> gameRichPresenceJoinRequested;

	private SteamAPIWarningMessageHook_t warningMessageHook;

	public override PlatformType CurrentPlatform => PlatformType.STEAM;

	public override bool IgnoreVRFocus
	{
		set
		{
		}
	}

	public override bool HasVRFocus => true;

	public override HardwareType CurrentHardwareType
	{
		get
		{
			if (!currentHardwareType.HasValue)
			{
				currentHardwareType = ((VRDevice.model != null && VRDevice.model.StartsWith("oculus", StringComparison.InvariantCultureIgnoreCase)) ? HardwareType.OCULUS : HardwareType.VIVE);
			}
			return currentHardwareType.Value;
		}
	}

	private static void SteamAPIDebugTextHook(int nSeverity, StringBuilder pchDebugText)
	{
		UnityEngine.Debug.LogWarning(pchDebugText);
	}

	private void OnDestroy()
	{
		if (initialized)
		{
			SteamAPI.Shutdown();
		}
	}

	private void Update()
	{
		if (initialized)
		{
			SteamAPI.RunCallbacks();
		}
	}

	private void OnRecRoomPlayerConnected(Player player)
	{
		if (!player.isLocal && player.Platform == PlatformType.STEAM)
		{
			SteamFriends.SetPlayedWith(new CSteamID(player.PlatformId));
		}
	}

	private bool ShouldRestart()
	{
		if (!Packsize.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Packsize Test returned false, the wrong version of Steamworks.NET is being run in this platform.", this);
			return true;
		}
		if (!DllCheck.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] DllCheck Test returned false, One or more of the Steamworks binaries seems to be the wrong version.", this);
			return true;
		}
		try
		{
			if (SteamAPI.RestartAppIfNecessary(new AppId_t(471710u)))
			{
				return true;
			}
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Could not load [lib]steam_api.dll/so/dylib. It's likely not in the correct location. Refer to the README for more details.\n" + ex, this);
			return true;
		}
		return false;
	}

	public override IEnumerator Initialize(InitializeCallback callback)
	{
		if (ShouldRestart())
		{
			UnityEngine.Application.Quit();
			yield break;
		}
		if (!SteamAPI.Init())
		{
			callback("Failed to initialize Steam Platform");
			yield break;
		}
		initialized = true;
		warningMessageHook = SteamAPIDebugTextHook;
		SteamClient.SetWarningMessageHook(warningMessageHook);
		gameRichPresenceJoinRequested = Callback<GameRichPresenceJoinRequested_t>.Create(OnGameRichPresenceJoinRequested);
		PUNNetworkManager.Instance.OnRecRoomPlayerConnected += OnRecRoomPlayerConnected;
		CSteamID steamID = SteamUser.GetSteamID();
		base.PlatformProfileId = (ulong)steamID;
		base.PlatformProfileName = SteamFriends.GetPersonaName();
		Player.SetPlatformPlayerId(CurrentPlatform, base.PlatformProfileId);
		callback(null);
	}

	public Texture2D LoadAvatarForPlayer(CSteamID steamID)
	{
		int mediumFriendAvatar = SteamFriends.GetMediumFriendAvatar(steamID);
		if (mediumFriendAvatar != 0 && SteamUtils.GetImageSize(mediumFriendAvatar, out var pnWidth, out var pnHeight) && pnWidth != 0 && pnHeight != 0)
		{
			byte[] array = new byte[pnWidth * pnHeight * 4];
			if (SteamUtils.GetImageRGBA(mediumFriendAvatar, array, (int)(pnWidth * pnHeight * 4)))
			{
				uint num = pnWidth * 4;
				byte[] array2 = new byte[num];
				for (uint num2 = 0u; num2 < pnHeight / 2; num2++)
				{
					uint num3 = num2 * num;
					uint num4 = (pnHeight - num2 - 1) * num;
					Array.Copy(array, num3, array2, 0L, num);
					Array.Copy(array, num4, array, num3, num);
					Array.Copy(array2, 0L, array, num4, num);
				}
				Texture2D texture2D = new Texture2D((int)pnWidth, (int)pnHeight, TextureFormat.RGBA32, mipmap: false, linear: true);
				texture2D.LoadRawTextureData(array);
				return texture2D;
			}
		}
		return null;
	}

	public override void SetRichPresenceStatus(string statusText)
	{
		SteamFriends.SetRichPresence("status", statusText);
	}

	private void OnGameRichPresenceJoinRequested(GameRichPresenceJoinRequested_t param)
	{
		PUNNetworkManager.Instance.ProcessRichJoinCommand(param.m_rgchConnect);
	}
}
public class ActivityBounds : UnityEngine.MonoBehaviour
{
	private static List<ActivityBounds> allBounds = new List<ActivityBounds>();

	private OverlapVolume overlapVolume;

	private void Awake()
	{
		overlapVolume = GetComponent<OverlapVolume>();
		allBounds.Add(this);
	}

	private void OnDestroy()
	{
		allBounds.Remove(this);
	}

	private bool ContainsPoint(Vector3 point)
	{
		return overlapVolume.ContainsPoint(point);
	}

	public static bool PointInBounds(Vector3 point)
	{
		if (allBounds.Count == 0)
		{
			return true;
		}
		for (int i = 0; i < allBounds.Count; i++)
		{
			if (allBounds[i].ContainsPoint(point))
			{
				return true;
			}
		}
		return false;
	}
}
public class AvatarColor : UnityEngine.MonoBehaviour
{
	public enum ColorType
	{
		Skin,
		Hair
	}

	public static List<AvatarColor> All = new List<AvatarColor>();

	[Tooltip("Matching guid value from the OutfitManager Color Vault")]
	public string GuidString = string.Empty;

	public ColorType Type = ColorType.Hair;

	private UnityEngine.UI.Image image;

	private Outline outline;

	private bool _selected;

	public Color Color { get; private set; }

	public bool Selected
	{
		get
		{
			return _selected;
		}
		private set
		{
			if (_selected != value)
			{
				_selected = value;
				if (outline != null)
				{
					outline.enabled = _selected;
				}
			}
		}
	}

	private IEnumerator Start()
	{
		ColorVault vault = ((Type != ColorType.Hair) ? OutfitManager.Instance.SkinColorVault : OutfitManager.Instance.HairColorVault);
		ColorVault.ColorToGuid colorToGuid = vault.Find(GuidString);
		if (colorToGuid != null)
		{
			Color = colorToGuid.color;
			image = GetComponent<UnityEngine.UI.Image>();
			if (image != null)
			{
				image.color = Color;
				All.Add(this);
			}
			outline = GetComponent<Outline>();
		}
		else
		{
			UnityEngine.Debug.LogError(string.Concat(this, " has an invalid color guid '", GuidString, ". Check to make sure you have the exact matching guid from the OutfitManager."));
			base.gameObject.SetActive(value: false);
		}
		while (Player.LocalPlayer == null || Player.LocalPlayer.PlayerOutfit == null || Player.LocalPlayer.PlayerOutfit.HairColor == null || Player.LocalPlayer.PlayerOutfit.SkinColor == null)
		{
			yield return null;
		}
		if (image != null && Player.LocalPlayer != null)
		{
			ColorVault.ColorToGuid colorToGuid2 = ((Type != ColorType.Hair) ? Player.LocalPlayer.PlayerOutfit.SkinColor : Player.LocalPlayer.PlayerOutfit.HairColor);
			Selected = colorToGuid2.guidString == GuidString;
		}
	}

	private void OnDestroy()
	{
		if (All != null && image != null)
		{
			All.Remove(this);
		}
	}

	public static void SetSelected(ColorType type, ColorVault.ColorToGuid colorToGuid)
	{
		foreach (AvatarColor item in All)
		{
			if (item.Type == type)
			{
				item.Selected = item.GuidString == colorToGuid.guidString;
			}
		}
	}
}
