public class ClockFace : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Transform secondHand;

	[SerializeField]
	private Transform minuteHand;

	[SerializeField]
	private Transform hourHand;

	private bool HandsActive
	{
		set
		{
			secondHand.gameObject.SetActive(value);
			minuteHand.gameObject.SetActive(value);
			hourHand.gameObject.SetActive(value);
		}
	}

	private void OnEnable()
	{
		HandsActive = true;
	}

	private void OnDisable()
	{
		HandsActive = false;
	}

	private void Update()
	{
		DateTime now = DateTime.Now;
		secondHand.localRotation = GetHandRotation(now.Second, 60);
		minuteHand.localRotation = GetHandRotation(now.Minute, 60);
		hourHand.localRotation = GetHandRotation(now.Hour, 12);
	}

	private Quaternion GetHandRotation(int timeValue, int maxTimeValue)
	{
		float num = Mathf.InverseLerp(0f, maxTimeValue, timeValue % maxTimeValue);
		return Quaternion.Euler(0f, 0f, (0f - num) * 360f);
	}
}
public class ColorVault : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class ColorToGuid
	{
		public string guidString;

		public Color color;
	}

	[Tooltip("Used only for decorative purposes.")]
	public string Label = "My Vault";

	public List<ColorToGuid> Colors;

	private Dictionary<string, ColorToGuid> colorMap = new Dictionary<string, ColorToGuid>();

	private void Awake()
	{
		foreach (ColorToGuid color in Colors)
		{
			if (colorMap.ContainsKey(color.guidString))
			{
				UnityEngine.Debug.LogError(string.Concat(this, " vault has duplicate guid for colors : ", color.guidString));
			}
			else
			{
				colorMap.Add(color.guidString, color);
			}
		}
	}

	public ColorToGuid Find(string guidStr)
	{
		if (colorMap.ContainsKey(guidStr))
		{
			return colorMap[guidStr];
		}
		return null;
	}
}
