	{
		get
		{
			bool flag = Owner != null && Owner.isLocal;
			bool flag2 = outfitTriggerEnabled && (PUNNetworkManager.Instance.IsInDormRoom || triggerEnabledOutsideDormroom);
			return flag && flag2;
		}
	}

	private void Awake()
	{
		if (uiAnchor != null && uiAnchor.childCount > 0)
		{
			UnityEngine.Debug.LogError("UI Anchor shouldn't have a child. Check the prefab");
		}
		Visible = false;
		Selection = new OutfitSelection(this);
		highlightShaderParamId = Shader.PropertyToID("_Highlight");
		SkinnedMeshRenderer.material = DefaultMaterial;
	}

	private void Start()
	{
		Visible = true;
		if (UsesHairColor)
		{
			Owner.PlayerOutfit.HairColorChanged += PlayerOutfit_HairColorChanged;
			if (Owner.PlayerOutfit.HairColor != null)
			{
				PlayerOutfit_HairColorChanged(Owner.PlayerOutfit.HairColor.color);
			}
		}
		if (ShouldCreateTrigger)
		{
			GameObject gameObject = new GameObject();
			outfitTrigger = gameObject.AddComponent<OutfitTrigger>();
			outfitTrigger.SetOutfitOwner(this);
			outfitTrigger.EnabledOutsideChangingRoom = triggerEnabledOutsideDormroom;
			Owner.SetParentPlayerRoot(gameObject.transform);
			if (!PUNNetworkManager.Instance.IsInDormRoom)
			{
				OutfitTool outfitTool = OutfitTool.Find(Owner, Selection, OutfitTool.ToolPurpose.Doffing);
				if (outfitTool == null)
				{
					OutfitManager.Instance.LocalSpawnOutfitTool(Selection, OutfitTool.ToolPurpose.Doffing);
				}
			}
		}
		if ((CurrentBodyPart == Player.BodyPart.LeftHand && !Owner.LeftHand.MeshesVisible) || (CurrentBodyPart == Player.BodyPart.RightHand && !Owner.RightHand.MeshesVisible) || !Owner.IsVisible)
		{
			base.gameObject.SetActive(value: false);
		}
	}

	private void OnDestroy()
	{
		if (UsesHairColor && Owner != null)
		{
			Owner.PlayerOutfit.HairColorChanged -= PlayerOutfit_HairColorChanged;
		}
		if (outfitTrigger != null)
		{
			UnityEngine.Object.Destroy(outfitTrigger.gameObject);
		}
	}

	private void PlayerOutfit_HairColorChanged(Color color)
	{
		if (UsesHairColor)
		{
			SkinnedMeshRenderer.material.color = color;
		}
	}

	public void SetTargetSkinnedMesh(SkinnedMeshRenderer targetRenderer)
	{
		Dictionary<string, Transform> dictionary = new Dictionary<string, Transform>();
		Transform[] bones = targetRenderer.bones;
		foreach (Transform transform in bones)
		{
			dictionary[transform.name] = transform;
		}
		Transform[] bones2 = SkinnedMeshRenderer.bones;
		for (int j = 0; j < bones2.Length; j++)
		{
			string text = bones2[j].name;
			if (!dictionary.TryGetValue(text, out bones2[j]))
			{
				UnityEngine.Debug.LogError("Failed to get bone: " + text + " - can not attach to " + targetRenderer, this);
				return;
			}
		}
		SkinnedMeshRenderer.bones = bones2;
		Transform parent = SkinnedMeshRenderer.rootBone.transform.parent;
		Vector3 localScale = parent.localScale;
		localScale.z = Mathf.Abs(localScale.z) * Mathf.Sign(targetRenderer.transform.lossyScale.z);
		parent.localScale = localScale;
	}

	public void ApplySwatch(AvatarColorSwatch swatch)
	{
		if (Selection != null)
		{
			Selection.colorSwatch = swatch;
		}
		AvatarColorSwatch.Apply(swatch, SkinnedMeshRenderer.material, DefaultMaterial);
	}

	public void ApplyMask(AvatarMask mask)
	{
		if (Selection != null)
		{
			Selection.mask = mask;
		}
		AvatarMask.Apply(mask, SkinnedMeshRenderer.material, DefaultMaterial);
	}

	public void ApplyDecal(AvatarDecal decal)
	{
		if (Selection != null)
		{
			Selection.decal = decal;
		}
		AvatarDecal.Apply(decal, SkinnedMeshRenderer.material, DefaultMaterial);
	}

	public int CompareTo(OutfitItem other)
	{
		int type = (int)Type;
		int num = type.CompareTo((int)other.Type);
		return (num == 0) ? preferredIndex.CompareTo(other.preferredIndex) : num;
	}
}
[Serializable]
public class OutfitSelection : IEquatable<OutfitSelection>
{
	public string name;

	[FormerlySerializedAs("outfit")]
	public OutfitItem outfitItem;

	public AvatarColorSwatch colorSwatch;

	public AvatarMask mask;

	public AvatarDecal decal;

	public bool IsNew { get; set; }

	public string FriendlyName
	{
		get
		{
			string text = outfitItem.name;
			if (mask != null)
			{
				text = text + " " + mask.name;
			}
			if (colorSwatch != null)
			{
				text = text + " " + colorSwatch.name;
			}
			if (decal != null)
			{
				text = text + " " + decal.name;
			}
			return text;
		}
	}

	public int? UnlockedLevel { get; set; }

	public int Level => (!UnlockedLevel.HasValue) ? (outfitItem.Level + ((colorSwatch != null) ? colorSwatch.Level : 0) + ((mask != null) ? mask.Level : 0) + ((decal != null) ? decal.Level : 0)) : UnlockedLevel.Value;

	private OutfitSelection()
	{
	}

	public OutfitSelection(OutfitItem o, AvatarColorSwatch cs = null, AvatarMask m = null, AvatarDecal d = null)
	{
		name = o.name;
		outfitItem = o;
		colorSwatch = cs;
		mask = m;
		decal = d;
		IsNew = false;
	}

	public bool Equals(OutfitSelection other)
	{
		return other != null && other.outfitItem != null && outfitItem != null && outfitItem.Guid == other.outfitItem.Guid && ((colorSwatch == null && other.colorSwatch == null) || (colorSwatch != null && other.colorSwatch != null && colorSwatch.Guid == other.colorSwatch.Guid)) && ((mask == null && other.mask == null) || (mask != null && other.mask != null && mask.Guid == other.mask.Guid)) && ((decal == null && other.decal == null) || (decal != null && other.decal != null && decal.Guid == other.decal.Guid));
	}

	public override bool Equals(object obj)
	{
		return base.Equals(obj as OutfitSelection);
	}

	public override int GetHashCode()
	{
		return ToString().GetHashCode();
	}

	public static bool operator !=(OutfitSelection os1, OutfitSelection os2)
	{
		if (object.ReferenceEquals(os1, null))
		{
			return !object.ReferenceEquals(os2, null);
		}
		return !os1.Equals(os2);
	}

	public static bool operator ==(OutfitSelection os1, OutfitSelection os2)
	{
		if (object.ReferenceEquals(os1, null))
		{
			return object.ReferenceEquals(os2, null);
		}
		return os1.Equals(os2);
	}

	public override string ToString()
	{
		return $"{outfitItem.Guid},{((!(colorSwatch != null)) ? string.Empty : colorSwatch.Guid)},{((!(mask != null)) ? string.Empty : mask.Guid)},{((!(decal != null)) ? string.Empty : decal.Guid)}";
	}

	public static OutfitSelection Parse(string desc)
	{
		if (string.IsNullOrEmpty(desc))
		{
			return null;
		}
		string[] array = desc.Split(',');
		if (array == null || array.Length != 4)
		{
			return null;
		}
		return Parse(array[0], array[1], array[2], array[3]);
	}

	public static OutfitSelection Parse(string o, string cs, string m, string d)
	{
		Guid oGuid = new Guid(o);
		OutfitItem outfitItem = OutfitManager.Instance.OutfitPrefabs.Find((OutfitItem x) => x.Guid == oGuid);
		if (outfitItem != null)
		{
			AvatarColorSwatch cs2 = ((!string.IsNullOrEmpty(cs)) ? AvatarColorSwatch.All.Find((AvatarColorSwatch x) => x.Guid == cs) : null);
			AvatarMask m2 = ((!string.IsNullOrEmpty(m)) ? AvatarMask.All.Find((AvatarMask x) => x.Guid == m) : null);
			AvatarDecal d2 = ((!string.IsNullOrEmpty(d)) ? AvatarDecal.All.Find((AvatarDecal x) => x.Guid == d) : null);
			return new OutfitSelection(outfitItem, cs2, m2, d2);
		}
		return null;
	}
}
[Serializable]
public class OutfitSelectionToBody : IEquatable<OutfitSelectionToBody>
{
	public OutfitSelection selection;

	public Player.BodyPart bodyPart;

	public OutfitSelectionToBody(OutfitSelection s, Player.BodyPart b)
	{
		selection = s;
		bodyPart = b;
	}

	public bool Equals(OutfitSelectionToBody other)
	{
		return selection == other.selection && other.bodyPart == bodyPart;
	}

	public override bool Equals(object obj)
	{
		return base.Equals(obj as OutfitSelectionToBody);
	}

	public override int GetHashCode()
	{
		return ToString().GetHashCode();
	}

	public override string ToString()
	{
		return selection.ToString() + "," + (int)bodyPart;
	}

	public static OutfitSelectionToBody Parse(string serializedStr)
	{
		string[] array = serializedStr.Split(',');
		if (array == null || array.Length != 5)
		{
			return null;
		}
		try
		{
			OutfitSelection outfitSelection = OutfitSelection.Parse(array[0], array[1], array[2], array[3]);
			int b = int.Parse(array[4]);
			if (outfitSelection != null)
			{
				return new OutfitSelectionToBody(outfitSelection, (Player.BodyPart)b);
			}
		}
		catch
		{
			UnityEngine.Debug.LogError("Failed to parse OutfitSelectionToBody with str:" + serializedStr);
		}
		return null;
	}
}
public class OutfitManager : Photon.MonoBehaviour
{
