		Mouth = 20,
		Neck = 100,
		Shirt = 101,
		Belt = 102,
		Pocket = 103,
		TeamJersey = 104,
		Wrist = 200,
		Glove = 201,
		Watch = 202,
		TeamWrist = 203
	}

	public delegate void DownloadUnlockedAvatarItemsCallback(string error);

	[SerializeField]
	private List<OutfitItem> outfitPrefabs = new List<OutfitItem>();

	public Material OutfitGhostMaterial;

	[SerializeField]
