	public ColorVault HairColorVault;

	private Dictionary<OutfitType, List<OutfitSelection>> outfitTypeMap;

	public static OutfitManager Instance { get; private set; }

	public static bool IsInitialized => Instance != null;

	public List<OutfitSelectionToBody> ModeratorOutfits => moderatorOutfits;

	public List<OutfitItem> OutfitPrefabs => outfitPrefabs;

	public List<OutfitSelection> UnlockedOutfitSelections => unlockedOutfitSelections;

