	public event Action<OutfitTool, string> OutfitToolSpawned;

	public event Action<OutfitSelection> OutfitSelectionUnlocked;

	protected override void Awake()
	{
		base.Awake();
		Instance = this;
		InitializeOutfitTypeMap();
	}

	private void InitializeOutfitTypeMap()
	{
		outfitTypeMap = new Dictionary<OutfitType, List<OutfitSelection>>();
		List<IGrouping<OutfitType, OutfitSelection>> list = (from o in unlockedOutfitSelections
			where o != null && o.outfitItem != null
			group o by o.outfitItem.Type into oType
			select (oType)).Distinct().ToList();
		int playerLevel = ((Profiles.LocalProfile == null) ? 1 : Profiles.LocalProfile.Level);
		foreach (IGrouping<OutfitType, OutfitSelection> item in list)
		{
			OutfitType type = item.Key;
			List<OutfitSelection> value = unlockedOutfitSelections.Where((OutfitSelection o) => o != null && o.outfitItem != null && o.outfitItem.Type == type && o.outfitItem.DisplayOnRack && o.Level <= playerLevel).ToList();
			outfitTypeMap.Add(type, value);
		}
	}

	public OutfitItem GetOutfit(string guidString)
	{
		return GetOutfit(new Guid(guidString));
	}

	public OutfitItem GetOutfit(Guid guid)
	{
		foreach (OutfitItem outfitPrefab in outfitPrefabs)
		{
			if (outfitPrefab != null && outfitPrefab.Guid == guid)
			{
				return outfitPrefab;
			}
		}
		return null;
	}

	public List<OutfitSelectionToBody> GetMissingOutfitsFromDefaultSet(List<OutfitSelectionToBody> currentSelection)
	{
		List<OutfitSelectionToBody> list = new List<OutfitSelectionToBody>();
		foreach (OutfitSelectionToBody defaultOutfit in defaultOutfits)
		{
			bool flag = false;
			foreach (OutfitSelectionToBody item in currentSelection)
			{
				if (item.selection.outfitItem.Type == defaultOutfit.selection.outfitItem.Type && item.selection.outfitItem.CurrentBodyPart == defaultOutfit.bodyPart)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				list.Add(defaultOutfit);
			}
		}
		return list;
	}

	public static Player.BodyPart GetMatchingBodyPart(OutfitType outfitType)
	{
		Player.BodyPart result = Player.BodyPart.Head;
		switch (outfitType)
		{
		case OutfitType.Hat:
		case OutfitType.BackHead:
		case OutfitType.Hair:
		case OutfitType.Eye:
		case OutfitType.Mouth:
			result = Player.BodyPart.Head;
			break;
		case OutfitType.Neck:
		case OutfitType.Shirt:
		case OutfitType.Belt:
		case OutfitType.Pocket:
		case OutfitType.TeamJersey:
			result = Player.BodyPart.Torso;
			break;
		case OutfitType.Wrist:
		case OutfitType.Glove:
		case OutfitType.Watch:
		case OutfitType.TeamWrist:
			result = Player.BodyPart.LeftHand;
			break;
		}
		return result;
	}

	public static bool IsTeamOutfit(OutfitType outfitType)
	{
		return outfitType == OutfitType.TeamJersey || outfitType == OutfitType.TeamWrist;
	}

	public static bool IsRequiredOutfitType(OutfitType outfitType)
	{
		return outfitType == OutfitType.Shirt;
	}

	public static bool IsMatchingBodyPart(Player.BodyPart bodyPart, OutfitType outfitType)
	{
		Player.BodyPart matchingBodyPart = GetMatchingBodyPart(outfitType);
		return matchingBodyPart == bodyPart || (matchingBodyPart == Player.BodyPart.LeftHand && bodyPart == Player.BodyPart.RightHand);
	}

	public void RandomizePlayerOutfit()
	{
		if (!(Player.LocalPlayer != null) || !(Player.LocalPlayer.PlayerOutfit != null))
		{
			return;
		}
		List<OutfitSelectionToBody> list = new List<OutfitSelectionToBody>();
		foreach (KeyValuePair<OutfitType, List<OutfitSelection>> item in outfitTypeMap)
		{
			OutfitType key = item.Key;
			List<OutfitSelection> value = item.Value;
			if ((IsRequiredOutfitType(key) || !(UnityEngine.Random.value > ((value.Count < 5) ? 0.3f : 0.6f))) && value.Count > 0)
			{
				OutfitSelection outfitSelection = value.Random();
				Player.BodyPart matchingBodyPart = GetMatchingBodyPart(outfitSelection.outfitItem.Type);
				list.Add(new OutfitSelectionToBody(outfitSelection, matchingBodyPart));
				if (matchingBodyPart == Player.BodyPart.LeftHand && (outfitSelection.outfitItem.Type == OutfitType.Wrist || outfitSelection.outfitItem.Type == OutfitType.Glove))
				{
					list.Add(new OutfitSelectionToBody(outfitSelection, Player.BodyPart.RightHand));
				}
			}
		}
		if (list.Count <= 0)
		{
			return;
		}
		Player.LocalPlayer.PlayerOutfit.UnEquipAll();
		foreach (OutfitSelectionToBody item2 in list)
		{
			Player.LocalPlayer.PlayerOutfit.SetOutfit(item2);
		}
	}

	public ColorVault.ColorToGuid FindHairColor(string hairColorGuid)
	{
		return FindColorFromVault(HairColorVault, hairColorGuid);
	}

	public ColorVault.ColorToGuid FindSkinColor(string skinColorGuid)
	{
		return FindColorFromVault(SkinColorVault, skinColorGuid);
	}

	private ColorVault.ColorToGuid FindColorFromVault(ColorVault vault, string colorGuid)
	{
		ColorVault.ColorToGuid colorToGuid = vault.Find(colorGuid);
		if (colorToGuid == null)
		{
			colorToGuid = vault.Colors.Random();
			if (!string.IsNullOrEmpty(colorGuid))
			{
				UnityEngine.Debug.LogWarning(string.Concat("Outfit Manager FindColor in ", vault, " can't find matching color for the guid ", colorGuid, ". Getting a random one."));
			}
		}
		return colorToGuid;
	}

	public IEnumerator DownloadUnlockedAvatarItems(DownloadUnlockedAvatarItemsCallback callback)
	{
		return Avatars.DowloadUnlockedAvatarItems(delegate(string e, List<OutfitSelection> selections)
		{
			if (selections != null)
			{
				foreach (OutfitSelection selection in selections)
				{
					if (selection != null && !unlockedOutfitSelections.Contains(selection))
					{
						unlockedOutfitSelections.Add(selection);
					}
				}
			}
			if (string.IsNullOrEmpty(e))
			{
				InitializeOutfitTypeMap();
			}
			callback(e);
		});
	}

	public bool AddAvatarItemToUnlockedList(string avatarItemDesc)
	{
		OutfitSelection outfitSelection = OutfitSelection.Parse(avatarItemDesc);
		if (outfitSelection != null && !unlockedOutfitSelections.Contains(outfitSelection))
		{
			unlockedOutfitSelections.Add(outfitSelection);
			InitializeOutfitTypeMap();
			outfitSelection.IsNew = true;
			if (this.OutfitSelectionUnlocked != null)
			{
				this.OutfitSelectionUnlocked(outfitSelection);
			}
			return true;
		}
		return false;
	}

	public OutfitSelection CreateRandomOutfitSelection(int maxLevel)
	{
		OutfitItem randomOutfitItem = GetRandomOutfitItem(maxLevel);
		AvatarMask randomMask = null;
		OutfitItem.OutfitSelectionGroup randomGroup = null;
		GetRandomAvatarMask(randomOutfitItem, out randomMask, out randomGroup, maxLevel);
		if ((bool)randomMask && randomGroup != null)
		{
			AvatarColorSwatch randomAvatarColorSwatch = GetRandomAvatarColorSwatch(randomOutfitItem, randomGroup, randomMask, maxLevel);
			if (randomAvatarColorSwatch != null)
			{
				AvatarDecal randomAvatarDecal = GetRandomAvatarDecal(randomOutfitItem, maxLevel, randomGroup, randomMask, randomAvatarColorSwatch);
				return new OutfitSelection(randomOutfitItem, randomAvatarColorSwatch, randomMask, randomAvatarDecal);
			}
		}
		return new OutfitSelection(randomOutfitItem);
	}

	private OutfitItem GetRandomOutfitItem(int maxLevel)
	{
		IEnumerable<OutfitItem> enumerable = outfitPrefabs.Where((OutfitItem o) => o != null && o.Level <= maxLevel && o.Rarity > 0f && o.DisplayOnRack);
		float num = 0f;
		foreach (OutfitItem item in enumerable)
		{
			num += item.Rarity;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		num = 0f;
		foreach (OutfitItem item2 in enumerable)
		{
			if (num2 >= num && num2 <= num + item2.Rarity)
			{
				return item2;
			}
			num += item2.Rarity;
		}
		UnityEngine.Debug.LogError("Failed to find outfit item. This should never happen.");
		return null;
	}

	private void GetRandomAvatarMask(OutfitItem outfitItem, out AvatarMask randomMask, out OutfitItem.OutfitSelectionGroup randomGroup, int maxLevel)
	{
		randomGroup = null;
		randomMask = null;
		var enumerable = outfitItem.SelectionGroups.Where((OutfitItem.OutfitSelectionGroup g) => g.IsValid).SelectMany((OutfitItem.OutfitSelectionGroup g) => from m in g.masks
			where IsValidAvatarMask(m, outfitItem, g, maxLevel)
			select new
			{
				Group = g,
				Mask = m
			});
		float num = 0f;
		foreach (var item in enumerable)
		{
			num += item.Mask.Rarity;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		num = 0f;
		foreach (var item2 in enumerable)
		{
			if (num2 >= num && num2 <= num + item2.Mask.Rarity)
			{
				randomMask = item2.Mask;
				randomGroup = item2.Group;
				break;
			}
			num += item2.Mask.Rarity;
		}
	}

	private bool IsValidAvatarMask(AvatarMask mask, OutfitItem outfitItem, OutfitItem.OutfitSelectionGroup group, int maxLevel)
	{
		if (outfitItem != null && mask != null && group != null && mask.Rarity > 0f)
		{
			int num = outfitItem.Level + mask.Level;
			foreach (AvatarColorSwatch swatch in group.swatches)
			{
				if (swatch.Rarity > 0f && swatch.Level + num <= maxLevel)
				{
					return true;
				}
			}
		}
		return false;
	}

	private AvatarColorSwatch GetRandomAvatarColorSwatch(OutfitItem outfitItem, OutfitItem.OutfitSelectionGroup group, AvatarMask mask, int maxLevel)
	{
		int currentLevel = outfitItem.Level + mask.Level;
		IEnumerable<AvatarColorSwatch> enumerable = group.swatches.Where((AvatarColorSwatch s) => s.Rarity > 0f && s.Level + currentLevel <= maxLevel);
		float num = 0f;
		foreach (AvatarColorSwatch item in enumerable)
		{
			num += item.Rarity;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		num = 0f;
		foreach (AvatarColorSwatch item2 in enumerable)
		{
			if (num2 >= num && num2 <= num + item2.Rarity)
			{
				return item2;
			}
			num += item2.Rarity;
		}
		return null;
	}

	private AvatarDecal GetRandomAvatarDecal(OutfitItem outfitItem, int maxLevel, OutfitItem.OutfitSelectionGroup group, AvatarMask mask, AvatarColorSwatch swatch)
	{
		int currentLevel = outfitItem.Level + mask.Level + swatch.Level;
		IEnumerable<AvatarDecal> enumerable = group.decals.Where((AvatarDecal d) => d.Rarity > 0f && d.Level + currentLevel <= maxLevel);
		float num = group.noneDecalRarity;
		foreach (AvatarDecal item in enumerable)
		{
			num += item.Rarity;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		if (num2 <= group.noneDecalRarity)
		{
			return null;
		}
		num = group.noneDecalRarity;
		foreach (AvatarDecal item2 in enumerable)
		{
			if (num2 >= num && num2 <= num + item2.Rarity)
			{
				return item2;
			}
			num += item2.Rarity;
		}
		return null;
	}

	private OutfitTool SpawnOutfitTool(PhotonPlayer wearerPhotonPlayer, OutfitSelection selection, int photonViewId, OutfitTool.ToolPurpose purpose, string guid)
	{
		Player player = wearerPhotonPlayer.ToPlayer();
		GameObject gameObject = new GameObject(selection.name + "_OutfitTool");
		gameObject.transform.position = new Vector3(0f, -10000f, 0f);
		player.SetParentPlayerRoot(gameObject.transform);
		SkinnedMeshRenderer skinnedMeshRenderer = selection.outfitItem.SkinnedMeshRenderer;
		GameObject gameObject2 = new GameObject("VisualRoot");
		gameObject2.transform.SetParent(gameObject.transform, worldPositionStays: false);
		gameObject2.transform.localRotation = Quaternion.Euler(-90f, 0f, 0f);
		GameObject gameObject3 = new GameObject("ToolVisual");
		gameObject3.transform.SetParent(gameObject2.transform, worldPositionStays: false);
		MeshRenderer meshRenderer = gameObject3.AddComponent<MeshRenderer>();
		MeshFilter meshFilter = gameObject3.AddComponent<MeshFilter>();
		meshFilter.sharedMesh = skinnedMeshRenderer.sharedMesh;
		meshRenderer.materials = skinnedMeshRenderer.sharedMaterials;
		gameObject2.transform.localPosition = gameObject.transform.position - meshRenderer.bounds.center;
		GameObject gameObject4 = UnityEngine.Object.Instantiate(gameObject3);
		gameObject4.transform.SetParent(gameObject2.transform, worldPositionStays: false);
		gameObject4.gameObject.SetActive(value: false);
		gameObject4.name = "ToolVisual_ghost";
		MeshRenderer component = gameObject4.GetComponent<MeshRenderer>();
		Collider collider = meshRenderer.GetComponent<Collider>();
		if (collider == null)
		{
			collider = meshRenderer.gameObject.AddComponent<BoxCollider>();
		}
		meshRenderer.gameObject.AddComponent<ToolCollider>();
		BoxCollider boxCollider = gameObject4.gameObject.AddComponent<BoxCollider>();
		boxCollider.isTrigger = true;
		gameObject4.gameObject.AddComponent<ToolCollider>();
		if (selection.mask != null)
		{
			AvatarMask.Apply(selection.mask, meshRenderer.material);
		}
		if (selection.decal != null)
		{
			AvatarDecal.Apply(selection.decal, meshRenderer.material);
		}
		if (selection.colorSwatch != null)
		{
			AvatarColorSwatch.Apply(selection.colorSwatch, meshRenderer.material);
		}
		Material[] array = new Material[component.materials.Length];
		for (int i = 0; i < component.materials.Length; i++)
		{
			array[i] = OutfitGhostMaterial;
		}
		component.materials = array;
		Rigidbody rigidbody = gameObject.gameObject.AddComponent<Rigidbody>();
		rigidbody.useGravity = false;
		PhotonView photonView = gameObject.gameObject.AddComponent<PhotonView>();
		photonView.viewID = photonViewId;
		photonView.synchronization = ViewSynchronization.Unreliable;
		PUNNetworkTransform item = gameObject.gameObject.AddComponent<PUNNetworkTransform>();
		if (photonView.ObservedComponents == null)
		{
			photonView.ObservedComponents = new List<UnityEngine.Component>();
		}
		photonView.ObservedComponents.Add(item);
		if (purpose == OutfitTool.ToolPurpose.GiftBox)
		{
			gameObject.gameObject.SetActive(value: false);
			AnimateInOut animateInOut = gameObject.gameObject.AddComponent<AnimateInOut>();
			animateInOut.SuppressAnimation = true;
			gameObject.gameObject.SetActive(value: true);
		}
		OutfitTool outfitTool = gameObject.gameObject.AddComponent<OutfitTool>();
		outfitTool.Wearer = wearerPhotonPlayer;
		outfitTool.OutfitTarget = selection;
		outfitTool.DrawerIndex = 0;
		outfitTool.ToolCollider = collider;
		outfitTool.GhostVisual = component;
		outfitTool.GhostCollider = boxCollider;
		outfitTool.Purpose = purpose;
		if (outfitTool.IsWearerLocal)
		{
			OutfitSelection outfitSelection = UnlockedOutfitSelections.FindLast((OutfitSelection s) => s.Equals(selection));
			if (outfitSelection != null)
			{
				selection.UnlockedLevel = outfitSelection.UnlockedLevel;
				outfitTool.IsNew = outfitSelection.IsNew;
			}
			else
			{
				outfitTool.IsNew = true;
			}
		}
		OutfitToolRenderer component2 = outfitTool.GetComponent<OutfitToolRenderer>();
		component2.SetupRenderer(meshRenderer);
		ScaleAnimationControl scaleAnimationControl = meshRenderer.gameObject.AddComponent<ScaleAnimationControl>();
		scaleAnimationControl.enabled = false;
		scaleAnimationControl.scaleCurve = outfitToolScaleAnimationCurve;
		component2.ScaleControl = scaleAnimationControl;
		outfitTool.gameObject.AddComponent<OutfitToolCleanup>();
		gameObject.gameObject.SetLayerRecursively(Layers.DynamicPhysics);
		outfitTool.CurrentState = OutfitTool.OutfitToolState.Disabled;
		bool flag = player.PlayerOutfit.IsWearing(selection);
		outfitTool.EquipState = ((!flag) ? OutfitTool.PlayerEquipState.NotWearing : OutfitTool.PlayerEquipState.Wearing);
		if (player.isLocal && (outfitTool.IsLevelLocked || outfitTool.IsNew))
		{
			OutfitToolUIControl outfitToolUIControl = UnityEngine.Object.Instantiate(outfitToolUIControlPrefab);
			outfitToolUIControl.SetLockLevel(selection.Level);
			if (selection.outfitItem.uiAnchor != null)
			{
				outfitToolUIControl.Offset = selection.outfitItem.uiAnchor.localPosition;
			}
			else
			{
				outfitToolUIControl.Offset = selection.outfitItem.outfitToolUIControlOffset;
				UnityEngine.Debug.LogWarning("Using deprecated UIControl offset for " + outfitTool.gameObject.name);
			}
			outfitToolUIControl.transform.SetParent(outfitTool.transform);
			outfitTool.OutfitToolUIControl = outfitToolUIControl;
		}
		if (this.OutfitToolSpawned != null)
		{
			this.OutfitToolSpawned(outfitTool, guid);
		}
		return outfitTool;
	}

	public string LocalSpawnOutfitTool(OutfitSelection selection, OutfitTool.ToolPurpose purpose)
	{
		string text = Guid.NewGuid().ToString();
		int num = PhotonNetwork.AllocateViewID();
		base.photonView.RPC("RpcSpawnOutfitTool", PhotonTargets.AllBuffered, PhotonNetwork.player, selection.ToString(), num, purpose, text);
		return text;
	}

	[PunRPC]
	public void RpcSpawnOutfitTool(PhotonPlayer player, string serializedSelection, int viewId, OutfitTool.ToolPurpose purpose, string guid)
	{
		OutfitSelection outfitSelection = OutfitSelection.Parse(serializedSelection);
		if (outfitSelection != null)
		{
			SpawnOutfitTool(player, outfitSelection, viewId, purpose, guid);
		}
		else
		{
			UnityEngine.Debug.LogWarning("RPC SpawnOutfitTool received null selection");
		}
	}
}
public class OutfitToolSpawner : UnityEngine.MonoBehaviour
{
	public OutfitDrawer[] Drawers;

	[Header("UI")]
	public Transform DrawersMenu;

	[Header("Audio")]
	public RecRoomAudioClip openDrawer;

	public RecRoomAudioClip pagingSound;

	private Dictionary<OutfitManager.OutfitType, Dictionary<string, OutfitDrawer>> drawerMap = new Dictionary<OutfitManager.OutfitType, Dictionary<string, OutfitDrawer>>();

	private HashSet<string> pendingSpawns = new HashSet<string>();

	private bool waitingOnSpawns;

	private void Awake()
	{
		Canvas componentInChildren = GetComponentInChildren<Canvas>(includeInactive: true);
		if (componentInChildren != null && ViveControllerInput.Instance != null)
		{
			componentInChildren.worldCamera = ViveControllerInput.Instance.ControllerCamera;
		}
	}

	private IEnumerator Start()
	{
		InitializeDrawerMap();
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		StartCoroutine(RunInitializeOutfitTools());
		Player.LocalPlayer.IsInChangingRoomUpdated += LocalPlayer_IsInChangingRoomUpdated;
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer outfitDrawer in drawers)
		{
			if (outfitDrawer != null)
			{
				outfitDrawer.SelectButton.interactable = true;
				outfitDrawer.PagingSound = pagingSound;
			}
		}
	}

	private void OnDestroy()
	{
		if (OutfitManager.Instance != null)
		{
			OutfitManager.Instance.OutfitToolSpawned -= OutfitManager_ToolSpawned;
			OutfitManager.Instance.OutfitSelectionUnlocked -= OutfitManager_OutfitSelectionUnlocked;
		}
	}

	private void OutfitManager_OutfitSelectionUnlocked(OutfitSelection selection)
	{
		OutfitTool outfitTool = OutfitTool.Find(Player.LocalPlayer, selection, OutfitTool.ToolPurpose.Drawer);
		if (outfitTool == null)
		{
			OutfitManager.Instance.LocalSpawnOutfitTool(selection, OutfitTool.ToolPurpose.Drawer);
		}
	}

	private void LocalPlayer_IsInChangingRoomUpdated(bool inChangingRoom)
	{
		if (inChangingRoom)
		{
			return;
		}
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer outfitDrawer in drawers)
		{
			if (outfitDrawer != null)
			{
				outfitDrawer.IsSelected = false;
			}
		}
	}

	private IEnumerator RunInitializeOutfitTools()
	{
		while (!OutfitManager.IsInitialized || Player.LocalPlayer == null)
		{
			yield return null;
		}
		pendingSpawns.Clear();
		waitingOnSpawns = true;
		OutfitManager.Instance.OutfitToolSpawned += OutfitManager_ToolSpawned;
		OutfitManager.Instance.OutfitSelectionUnlocked += OutfitManager_OutfitSelectionUnlocked;
		foreach (OutfitSelection unlockedOutfitSelection in OutfitManager.Instance.UnlockedOutfitSelections)
		{
			if (unlockedOutfitSelection != null && unlockedOutfitSelection.outfitItem != null && unlockedOutfitSelection.outfitItem.DisplayOnRack)
			{
				string item = OutfitManager.Instance.LocalSpawnOutfitTool(unlockedOutfitSelection, OutfitTool.ToolPurpose.Drawer);
				pendingSpawns.Add(item);
			}
		}
	}

	private void OutfitManager_ToolSpawned(OutfitTool outfitTool, string guid)
	{
		if (pendingSpawns.Contains(guid))
		{
			pendingSpawns.Remove(guid);
		}
		if (outfitTool.Purpose == OutfitTool.ToolPurpose.Drawer)
		{
			OutfitDrawer rack = GetRack(outfitTool.OutfitTarget.outfitItem);
			if (rack != null)
			{
				rack.AddSelection(outfitTool);
				if (!waitingOnSpawns)
				{
					rack.UpdateOutfitPlacement();
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("Null Drawer for outfitTool:" + outfitTool);
			}
		}
		if (waitingOnSpawns && pendingSpawns.Count == 0)
		{
			waitingOnSpawns = false;
			UnityEngine.Debug.Log("Pending spawns complete. Updating all drawers at once");
			StartCoroutine(UpdateAllDrawerPlacements());
		}
	}

	private IEnumerator UpdateAllDrawerPlacements()
	{
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer d in drawers)
		{
			d.UpdateOutfitPlacement();
			yield return null;
		}
	}

	private void InitializeDrawerMap()
	{
		for (int i = 0; i < Drawers.Length; i++)
		{
			if (drawerMap.ContainsKey(Drawers[i].OutfitType))
			{
				Dictionary<string, OutfitDrawer> dictionary = drawerMap[Drawers[i].OutfitType];
				if (string.IsNullOrEmpty(Drawers[i].Name) || dictionary.ContainsKey(Drawers[i].Name))
				{
					Drawers[i].Name = Guid.NewGuid().ToString();
				}
				dictionary.Add(Drawers[i].Name, Drawers[i]);
				continue;
			}
			Dictionary<string, OutfitDrawer> dictionary2 = new Dictionary<string, OutfitDrawer>();
			if (string.IsNullOrEmpty(Drawers[i].Name))
			{
				Drawers[i].Name = Guid.NewGuid().ToString();
			}
			dictionary2.Add(Drawers[i].Name, Drawers[i]);
			drawerMap.Add(Drawers[i].OutfitType, dictionary2);
		}
	}

	private OutfitDrawer GetRack(OutfitItem outfitPrefab)
	{
		if (!drawerMap.ContainsKey(outfitPrefab.Type))
		{
			return null;
		}
		Dictionary<string, OutfitDrawer> dictionary = drawerMap[outfitPrefab.Type];
		if (dictionary.ContainsKey(outfitPrefab.PreferredRackName))
		{
			return dictionary[outfitPrefab.PreferredRackName];
		}
		if (!string.IsNullOrEmpty(outfitPrefab.PreferredRackName))
		{
			OutfitDrawer[] drawers = Drawers;
			foreach (OutfitDrawer outfitDrawer in drawers)
			{
				if (outfitPrefab.PreferredRackName == outfitDrawer.Name)
				{
					return outfitDrawer;
				}
			}
		}
		if (dictionary.Count > 0)
		{
			return dictionary.Values.First();
		}
		return null;
	}

	public void Button_RackSelected(Button button)
	{
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer outfitDrawer in drawers)
		{
			if (outfitDrawer != null && outfitDrawer.SelectButton == button)
			{
				AudioManager.Play3DSFX(openDrawer, base.transform.position);
				outfitDrawer.IsSelected = !outfitDrawer.IsSelected;
				break;
			}
		}
	}
}
public class OutfitToolUIControl : UnityEngine.MonoBehaviour
{
	[Flags]
	public enum ItemProgressionState
	{
		None = 0,
		Locked = 1,
		New = 2
	}

	[Header("Locked Item Controls")]
	[SerializeField]
	private Text lockLevelText;

	[SerializeField]
	private UnityEngine.UI.Image lockIcon;

	[Header("New Item Controls")]
	[SerializeField]
	private GameObject newItemIcon;

	[SerializeField]
	private ItemProgressionState _state;

	public Vector3 Offset { get; set; }

	public ItemProgressionState State
	{
		get
		{
			return _state;
		}
		set
		{
			_state = value;
			lockLevelText.gameObject.SetActive(value: false);
			lockIcon.gameObject.SetActive(value: false);
			newItemIcon.gameObject.SetActive(value: false);
			if ((_state & ItemProgressionState.Locked) == ItemProgressionState.Locked)
			{
				lockLevelText.gameObject.SetActive(value: true);
				lockIcon.gameObject.SetActive(value: true);
			}
			if ((_state & ItemProgressionState.New) == ItemProgressionState.New)
			{
				newItemIcon.gameObject.SetActive(value: true);
			}
		}
	}

	public void SetLockLevel(int level)
	{
		lockLevelText.text = level.ToString();
	}

	private void LateUpdate()
	{
		base.transform.position = base.transform.parent.position + Offset;
	}
}
public class OutfitTrigger : UnityEngine.MonoBehaviour
{
	private BoxCollider boxCollider;

	public OutfitItem OutfitItem { get; private set; }

	public Transform TargetBone { get; set; }

	public bool EnabledOutsideChangingRoom { get; set; }

	public void SetOutfitOwner(OutfitItem outfitItem)
	{
		OutfitItem = outfitItem;
		TargetBone = outfitItem.SkinnedMeshRenderer.bones[0];
		if (boxCollider != null)
		{
			UnityEngine.Object.Destroy(boxCollider);
			boxCollider = null;
		}
		boxCollider = base.gameObject.AddComponent<BoxCollider>();
		boxCollider.size = outfitItem.SkinnedMeshRenderer.bounds.size;
		boxCollider.isTrigger = true;
		boxCollider.tag = "Outfit";
		base.gameObject.layer = 15;
		base.name = outfitItem.name + "_trigger";
	}

	private void LateUpdate()
	{
		if (OutfitItem != null && TargetBone != null && Player.LocalPlayer != null)
		{
			base.transform.position = OutfitItem.SkinnedMeshRenderer.bounds.center;
			base.transform.rotation = TargetBone.rotation;
		}
	}
}
[DisallowMultipleComponent]
public class PlayerOutfit : Photon.MonoBehaviour
{
	public static readonly string PlayerHairColorProperty = "PlayerHairColorProperty";

	public static readonly string PlayerSkinColorProperty = "PlayerSkinColorProperty";

	public static readonly string PlayerOutFitProperty = "PlayerOutFitProperty";

	public bool PersistOutfitSelection = true;

	[SerializeField]
	private SkinnedMeshRenderer face;

	[SerializeField]
	private SkinnedMeshRenderer eyes;

	[SerializeField]
	private SkinnedMeshRenderer mouth;

	[SerializeField]
	private SkinnedMeshRenderer torso;

	[SerializeField]
	private SkinnedMeshRenderer leftHand;

	[SerializeField]
	private SkinnedMeshRenderer rightHand;

	[HideInInspector]
	public Player ThisPlayer;

	private ColorVault.ColorToGuid _hairColor;

	private ColorVault.ColorToGuid _skinColor;

	private Color? _teamIndicator;

	private List<OutfitSelectionToBody> outfitSelections = new List<OutfitSelectionToBody>();

	private PlayerData playerData;

	private bool recnetLocalAvatarDirty;

	private bool snapShotReady;

	private string savedSelectionStr;

	private string savedHairColorGuid = string.Empty;

	private string savedSkinColorGuid = string.Empty;

	public ColorVault.ColorToGuid HairColor
	{
		get
		{
			return _hairColor;
		}
		private set
		{
			_hairColor = value;
			if (base.isLocal)
			{
				AvatarColor.SetSelected(AvatarColor.ColorType.Hair, _hairColor);
				if (ThisPlayer.IsInChangingRoom)
				{
					AnalyticsHelper.AvatarHairColor(_hairColor);
				}
			}
			if (this.HairColorChanged != null)
			{
				this.HairColorChanged(_hairColor.color);
			}
		}
	}

	public ColorVault.ColorToGuid SkinColor
	{
		get
		{
			return _skinColor;
		}
		private set
		{
			_skinColor = value;
			if (base.isLocal)
			{
				AvatarColor.SetSelected(AvatarColor.ColorType.Skin, _skinColor);
				if (ThisPlayer.IsInChangingRoom)
				{
					AnalyticsHelper.AvatarSkinColor(_skinColor);
				}
			}
			face.material.color = _skinColor.color;
			torso.material.color = _skinColor.color;
			leftHand.material.color = _skinColor.color;
			rightHand.material.color = _skinColor.color;
		}
	}

	public Color? TeamIndicator
	{
		get
		{
			return _teamIndicator;
		}
		set
		{
			if (_teamIndicator != value)
			{
				_teamIndicator = value;
				UpdateTeamOutfits();
			}
		}
	}

	public bool TeamOutfitsSupported => RecRoomSceneManager.Instance.GameManager != null && RecRoomSceneManager.Instance.GameManager.TeamManager.SupportsTeamOutfits;

	public event Action<Color> HairColorChanged;

	protected override void Awake()
	{
		base.Awake();
		playerData = GetComponent<PlayerData>();
	}

	private void Start()
	{
		playerData.RegisterCallback(PlayerSkinColorProperty, OnPlayerSkinColorChanged);
		playerData.RegisterCallback(PlayerHairColorProperty, OnPlayerHairColorChanged);
		playerData.RegisterCallback(PlayerOutFitProperty, OnPlayerOutfitChanged);
		if (base.isLocal)
		{
			bool flag = true;
			bool flag2 = true;
			bool flag3 = true;
			if (PersistOutfitSelection)
			{
				string skinColor = Avatars.LocalAvatar.SkinColor;
				if (!string.IsNullOrEmpty(skinColor))
				{
					playerData.SetData(PlayerSkinColorProperty, skinColor);
					flag2 = false;
				}
				string hairColor = Avatars.LocalAvatar.HairColor;
				if (!string.IsNullOrEmpty(hairColor))
				{
					playerData.SetData(PlayerHairColorProperty, hairColor);
					flag3 = false;
				}
				string text = Avatars.LocalAvatar.OutfitSelections;
				if (!string.IsNullOrEmpty(text))
				{
					playerData.SetData(PlayerOutFitProperty, text);
					flag = false;
				}
			}
			if (flag3)
			{
				SetHairColor(OutfitManager.Instance.FindHairColor(string.Empty).guidString);
			}
			if (flag2)
			{
				SetSkinColor(OutfitManager.Instance.FindSkinColor(string.Empty).guidString);
			}
			if (flag)
			{
				OutfitManager.Instance.RandomizePlayerOutfit();
			}
			EquipDefaultOutfitSetForMissing();
			EquipTeamOutfits();
		}
		else
		{
			OnPlayerOutfitChanged(null, null);
			OnPlayerSkinColorChanged(null, null);
			OnPlayerHairColorChanged(null, null);
		}
		ThisPlayer.VisibilityChanged += ThisPlayer_VisibilityChanged;
		ThisPlayer.IsInChangingRoomUpdated += ThisPlayer_IsInChangingRoomUpdated;
	}

	private void Update()
	{
		if (base.isLocal && recnetLocalAvatarDirty)
		{
			recnetLocalAvatarDirty = false;
			Avatars.SaveLocalAvatarSettings();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody outfitSelectionToBody in array)
		{
			if (outfitSelectionToBody != null && outfitSelectionToBody.selection.outfitItem != null)
			{
				UnityEngine.Object.Destroy(outfitSelectionToBody.selection.outfitItem.gameObject);
			}
		}
		outfitSelections.Clear();
		ThisPlayer.VisibilityChanged -= ThisPlayer_VisibilityChanged;
		ThisPlayer.IsInChangingRoomUpdated -= ThisPlayer_IsInChangingRoomUpdated;
	}

	public OutfitSelection GetSelection(Player.BodyPart bodyPart)
	{
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (outfitSelection.bodyPart == bodyPart)
			{
				return outfitSelection.selection;
			}
		}
		return null;
	}

	private void EquipTeamOutfits()
	{
		foreach (OutfitSelectionToBody teamOutfit in OutfitManager.Instance.TeamOutfits)
		{
			SetOutfit(teamOutfit);
		}
	}

	private void ThisPlayer_VisibilityChanged(bool visible)
	{
		if (base.isLocal)
		{
			return;
		}
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			outfitSelection.selection.outfitItem.gameObject.SetActive(visible);
		}
	}

	private void ThisPlayer_IsInChangingRoomUpdated(bool entered)
	{
		if (base.isLocal && entered)
		{
			SnapShotSelection();
		}
	}

	private void OnPlayerSkinColorChanged(PlayerData sender, string key)
	{
		string data = playerData.GetData(PlayerSkinColorProperty, string.Empty);
		ColorVault.ColorToGuid skinColor = OutfitManager.Instance.FindSkinColor(data);
		SkinColor = skinColor;
	}

	private void OnPlayerHairColorChanged(PlayerData sender, string key)
	{
		string data = playerData.GetData(PlayerHairColorProperty, string.Empty);
		ColorVault.ColorToGuid hairColor = OutfitManager.Instance.FindHairColor(data);
		HairColor = hairColor;
	}

	private void OnPlayerOutfitChanged(PlayerData sender, string key)
	{
		string data = playerData.GetData(PlayerOutFitProperty, string.Empty);
		ParseOutfitString(data);
	}

	private void EquipDefaultOutfitSetForMissing()
	{
		List<OutfitSelectionToBody> missingOutfitsFromDefaultSet = OutfitManager.Instance.GetMissingOutfitsFromDefaultSet(outfitSelections);
		foreach (OutfitSelectionToBody item in missingOutfitsFromDefaultSet)
		{
			SetOutfit(item);
		}
	}

	private void UpdateTeamOutfits()
	{
		bool flag = TeamIndicator.HasValue && TeamOutfitsSupported;
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (OutfitManager.IsTeamOutfit(outfitSelection.selection.outfitItem.Type))
			{
				outfitSelection.selection.outfitItem.Enabled = flag;
				if (flag)
				{
					outfitSelection.selection.outfitItem.SkinnedMeshRenderer.material.color = TeamIndicator.Value;
				}
			}
			else
			{
				Player.BodyPart matchingBodyPart = OutfitManager.GetMatchingBodyPart(outfitSelection.selection.outfitItem.Type);
				if (matchingBodyPart.IsHand())
				{
					outfitSelection.selection.outfitItem.Enabled = !flag;
				}
			}
		}
	}

	public string GetOutfitNameList()
	{
		string text = string.Empty;
		for (int i = 0; i < outfitSelections.Count; i++)
		{
			text = text + outfitSelections[i].selection.outfitItem.name + ((i == outfitSelections.Count - 1) ? string.Empty : ",");
		}
		return text;
	}

	public void UnEquipAll()
	{
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody selectionToBody in array)
		{
			UnEquipOutfit(selectionToBody);
		}
	}

	public void ResetOutfitSelectionToDefault()
	{
		UnEquipAll();
		EquipDefaultOutfitSetForMissing();
	}

	public void SetHandVisible(PlayerHand.HandType type, bool isVisible)
	{
		int num;
		switch (type)
		{
		case PlayerHand.HandType.Unknown:
			return;
		case PlayerHand.HandType.Left:
			num = 2;
			break;
		default:
			num = 3;
			break;
		}
		Player.BodyPart bodyPart = (Player.BodyPart)num;
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (outfitSelection.selection.outfitItem.CurrentBodyPart == bodyPart)
			{
				outfitSelection.selection.outfitItem.gameObject.SetActive(isVisible && ThisPlayer.IsVisible);
			}
		}
	}

	public void SetSkinColor(string colorGuid)
	{
		playerData.SetData(PlayerSkinColorProperty, colorGuid);
		if (PersistOutfitSelection)
		{
			Avatars.LocalAvatar.SkinColor = colorGuid;
			recnetLocalAvatarDirty = true;
		}
	}

	public void SetHairColor(string colorGuid)
	{
		playerData.SetData(PlayerHairColorProperty, colorGuid);
		if (PersistOutfitSelection)
		{
			Avatars.LocalAvatar.HairColor = colorGuid;
			recnetLocalAvatarDirty = true;
		}
	}

	public bool SetOutfit(OutfitSelection selection, Player.BodyPart bodyPart, bool playAudio = false)
	{
		return SetOutfit(new OutfitSelectionToBody(selection, bodyPart), playAudio);
	}

	public bool SetOutfit(OutfitSelectionToBody selectionToBody, bool playAudio = false)
	{
		if (outfitSelections.Contains(selectionToBody))
		{
			return false;
		}
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody outfitSelectionToBody in array)
		{
			if (outfitSelectionToBody.selection.outfitItem.Type == selectionToBody.selection.outfitItem.Type && outfitSelectionToBody.selection.outfitItem.CurrentBodyPart == selectionToBody.bodyPart && outfitSelectionToBody.selection != selectionToBody.selection)
			{
				UnEquipOutfit(outfitSelectionToBody);
			}
		}
		string data = SerializeOutfitSelections(selectionToBody);
		playerData.SetData(PlayerOutFitProperty, data);
		if (PersistOutfitSelection && !OutfitManager.IsTeamOutfit(selectionToBody.selection.outfitItem.Type))
		{
			Avatars.LocalAvatar.OutfitSelections = data;
			recnetLocalAvatarDirty = true;
		}
		if (playAudio)
		{
			PlayOutfitAudio(OutfitManager.Instance.EquipSounds, selectionToBody.bodyPart);
		}
		ThisPlayer.PlayerEvents.OutfitEquipped(selectionToBody.bodyPart);
		return true;
	}

	public bool RemoveOutfit(OutfitSelection selection, bool playAudio = false)
	{
		OutfitSelectionToBody outfitSelectionToBody = new OutfitSelectionToBody(selection, selection.outfitItem.CurrentBodyPart);
		if (!outfitSelections.Contains(outfitSelectionToBody))
		{
			return false;
		}
		UnEquipOutfit(outfitSelectionToBody);
		string data = SerializeOutfitSelections();
		playerData.SetData(PlayerOutFitProperty, data);
		if (PersistOutfitSelection)
		{
			Avatars.LocalAvatar.OutfitSelections = data;
			recnetLocalAvatarDirty = true;
		}
		if (playAudio)
		{
			PlayOutfitAudio(OutfitManager.Instance.UnEquipSounds, selection.outfitItem.CurrentBodyPart);
		}
		return true;
	}

	private void PlayOutfitAudio(RecRoomAudioClip[] audioClips, Player.BodyPart bodyPart)
	{
		AudioManager.PlayRandom3DSFX(audioClips, bodyPart switch
		{
			Player.BodyPart.LeftHand => ThisPlayer.LeftHand.transform.position, 
			Player.BodyPart.RightHand => ThisPlayer.RightHand.transform.position, 
			Player.BodyPart.Torso => ThisPlayer.Body.transform.position, 
			_ => ThisPlayer.Head.transform.position, 
		});
	}

	private string SerializeOutfitSelections(OutfitSelectionToBody selectionToBody = null)
	{
		string text = string.Empty;
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			text = text + outfitSelection.ToString() + ";";
		}
		if (selectionToBody != null)
		{
			text += selectionToBody.ToString();
		}
		return text;
	}

	private List<OutfitSelectionToBody> ParseOutfitMapString(string newSelectionsStr)
	{
		List<OutfitSelectionToBody> list = new List<OutfitSelectionToBody>();
		string[] array = newSelectionsStr.Split(';');
		string[] array2 = array;
		foreach (string text in array2)
		{
			if (!string.IsNullOrEmpty(text))
			{
				OutfitSelectionToBody outfitSelectionToBody = OutfitSelectionToBody.Parse(text);
				if (outfitSelectionToBody != null)
				{
					list.Add(outfitSelectionToBody);
				}
				else
				{
					UnityEngine.Debug.LogWarning("PlayerOutfit outfit map parse error. This means we changed a GUID or deleted an item. GUID : " + text);
				}
			}
		}
		return list;
	}

	private void ParseOutfitString(string newMapString)
	{
		List<OutfitSelectionToBody> list = ParseOutfitMapString(newMapString);
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody outfitSelectionToBody in array)
		{
			if (!list.Contains(outfitSelectionToBody))
			{
				UnEquipOutfit(outfitSelectionToBody);
			}
		}
		foreach (OutfitSelectionToBody item in list)
		{
			if (item != null && item.selection != null && item.selection.outfitItem != null && !outfitSelections.Contains(item))
			{
				EquipOutfit(item);
			}
		}
		UpdateTeamOutfits();
	}

	private void UnEquipOutfit(OutfitSelectionToBody selectionToBody)
	{
		ThisPlayer.AnimateInOut.additionalRenderers.Remove(selectionToBody.selection.outfitItem.SkinnedMeshRenderer);
		if (outfitSelections.Contains(selectionToBody))
		{
			outfitSelections.Remove(selectionToBody);
		}
		OutfitTool outfitTool = OutfitTool.Find(ThisPlayer, selectionToBody.selection, OutfitTool.ToolPurpose.Drawer);
		if (outfitTool != null)
		{
			outfitTool.EquipState = OutfitTool.PlayerEquipState.NotWearing;
		}
		if (base.isLocal && ThisPlayer.IsInChangingRoom)
		{
			AnalyticsHelper.AvatarOutfitEquip(selectionToBody, equip: false);
		}
		UnityEngine.Object.Destroy(selectionToBody.selection.outfitItem.gameObject);
	}

	private void EquipOutfit(OutfitSelectionToBody selectionToBody)
	{
		InstantiateNewOutfitPrefab(selectionToBody.selection, selectionToBody.bodyPart);
		OutfitTool outfitTool = OutfitTool.Find(ThisPlayer, selectionToBody.selection, OutfitTool.ToolPurpose.Drawer);
		if (outfitTool != null)
		{
			outfitTool.EquipState = OutfitTool.PlayerEquipState.Wearing;
		}
		outfitTool = OutfitTool.Find(ThisPlayer, selectionToBody.selection, OutfitTool.ToolPurpose.Doffing);
		if (outfitTool != null)
		{
			outfitTool.EquipState = OutfitTool.PlayerEquipState.Wearing;
		}
		if (base.isLocal && ThisPlayer.IsInChangingRoom)
		{
			AnalyticsHelper.AvatarOutfitEquip(selectionToBody, equip: true);
		}
	}

	public OutfitItem InstantiateNewOutfitPrefab(OutfitSelection selection, Player.BodyPart bodyPart, bool ownedByPlayerOutfit = true)
	{
		OutfitItem outfitItem = UnityEngine.Object.Instantiate(selection.outfitItem);
		outfitItem.Type = selection.outfitItem.Type;
		if (selection.decal != null)
		{
			outfitItem.ApplyDecal(selection.decal);
		}
		if (selection.mask != null)
		{
			outfitItem.ApplyMask(selection.mask);
		}
		if (selection.colorSwatch != null)
		{
			outfitItem.ApplySwatch(selection.colorSwatch);
		}
		outfitItem.CurrentBodyPart = bodyPart;
		outfitItem.Owner = ThisPlayer;
		selection.outfitItem = outfitItem;
		OutfitSelectionToBody item = new OutfitSelectionToBody(selection, bodyPart);
		if (ownedByPlayerOutfit)
		{
			outfitSelections.Add(item);
			ThisPlayer.AnimateInOut.additionalRenderers.Add(outfitItem.SkinnedMeshRenderer);
		}
		SetOutfitTarget(outfitItem);
		SetOutFitLayer(outfitItem);
		if (!base.isLocal)
		{
			outfitItem.gameObject.SetActive(ThisPlayer.IsVisible);
		}
		ThisPlayer.SetParentPlayerRoot(outfitItem.transform);
		return outfitItem;
	}

	private void SetOutFitLayer(OutfitItem outfitItem)
	{
		Layers layer = Layers.RemotePlayerPhysics;
		if (base.isLocal)
		{
			layer = ((!outfitItem.CurrentBodyPart.IsHand()) ? Layers.HiddenInFirstPerson : Layers.LocalPlayerPhysics);
		}
		outfitItem.gameObject.SetLayerRecursively(layer);
	}

	private void SetOutfitTarget(OutfitItem newOutfit)
	{
		SkinnedMeshRenderer targetSkinnedMesh = null;
		switch (newOutfit.Type)
		{
		case OutfitManager.OutfitType.Hat:
		case OutfitManager.OutfitType.BackHead:
		case OutfitManager.OutfitType.Hair:
			targetSkinnedMesh = face;
			break;
		case OutfitManager.OutfitType.Eye:
			targetSkinnedMesh = eyes;
			break;
		case OutfitManager.OutfitType.Mouth:
			targetSkinnedMesh = mouth;
			break;
		case OutfitManager.OutfitType.Neck:
		case OutfitManager.OutfitType.Shirt:
		case OutfitManager.OutfitType.Belt:
		case OutfitManager.OutfitType.Pocket:
		case OutfitManager.OutfitType.TeamJersey:
			targetSkinnedMesh = torso;
			break;
		case OutfitManager.OutfitType.Wrist:
		case OutfitManager.OutfitType.Glove:
		case OutfitManager.OutfitType.Watch:
		case OutfitManager.OutfitType.TeamWrist:
			if (newOutfit.CurrentBodyPart == Player.BodyPart.LeftHand)
			{
				targetSkinnedMesh = leftHand;
				break;
			}
			if (newOutfit.CurrentBodyPart == Player.BodyPart.RightHand)
			{
				targetSkinnedMesh = rightHand;
				break;
			}
			UnityEngine.Debug.LogError(string.Concat("An outfit (", newOutfit, ") with hand type is being placed to an incorrect body part. ", newOutfit.CurrentBodyPart));
			break;
		default:
			throw new Exception("PlayerOutfit.SetOutfitTarget can not set target for this outfit " + newOutfit);
		}
		newOutfit.SetTargetSkinnedMesh(targetSkinnedMesh);
	}

	public bool IsWearing(OutfitSelection selection)
	{
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (outfitSelection.selection == selection)
			{
				return true;
			}
		}
		return false;
	}

	public void SnapShotSelection()
	{
		savedHairColorGuid = HairColor.guidString;
		savedSkinColorGuid = SkinColor.guidString;
		savedSelectionStr = SerializeOutfitSelections();
		snapShotReady = true;
	}

	public void RestoreSelection()
	{
		if (snapShotReady)
		{
			SetHairColor(savedHairColorGuid);
			SetSkinColor(savedSkinColorGuid);
			ParseOutfitString(savedSelectionStr);
			recnetLocalAvatarDirty = true;
		}
	}

	public void DebugEquipModeratorOutfits()
	{
		foreach (OutfitSelectionToBody moderatorOutfit in OutfitManager.Instance.ModeratorOutfits)
		{
			SetOutfit(moderatorOutfit);
		}
	}
}
public class ScaleAnimationControl : UnityEngine.MonoBehaviour
{
	public AnimationCurve scaleCurve;

	private Vector3 initialScale = Vector3.one;

	private float lastKeyTime;

	private void OnEnable()
	{
		if (scaleCurve == null || scaleCurve.length < 1)
		{
			base.enabled = false;
			return;
		}
		initialScale = base.transform.localScale;
		lastKeyTime = scaleCurve[scaleCurve.length - 1].time;
		if (lastKeyTime <= 0f)
		{
			base.enabled = false;
		}
	}

	private void OnDisable()
	{
		base.transform.localScale = initialScale;
	}

	private void Update()
	{
		base.transform.localScale = initialScale * scaleCurve.Evaluate(Time.time % lastKeyTime);
	}
}
public class CollisionVibration : UnityEngine.MonoBehaviour
{
	private void OnCollisionEnter(Collision collision)
	{
		PlayerHand playerHand = null;
		Player.BodyPart bodyPart;
		Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
		Tool colliderTool = collision.GetColliderTool();
		if (colliderPlayer != null)
		{
			switch (bodyPart)
			{
			case Player.BodyPart.LeftHand:
				playerHand = colliderPlayer.LeftHand;
				break;
			case Player.BodyPart.RightHand:
				playerHand = colliderPlayer.RightHand;
				break;
			}
		}
		else if (colliderTool != null && colliderTool.IsHeld && colliderTool.Owner != null)
		{
			if (colliderTool.Owner.LeftHand.Tool == colliderTool)
			{
				playerHand = colliderTool.Owner.LeftHand;
			}
			else if (colliderTool.Owner.RightHand.Tool == colliderTool)
			{
				playerHand = colliderTool.Owner.RightHand;
			}
		}
		if (playerHand != null)
		{
			playerHand.Vibrate(50, 1000);
		}
	}
}
public class FaceStretchInteraction : UnityEngine.MonoBehaviour
{
	private static Color visualColor = new Color(0f, 1f, 0.8f, 1f);

	private static float visualScale = 0.05f;

	private static float colliderRadius = 0.025f;

	private static float defaultAlpha = 0.1f;

	private static float highlightAlpha = 0.7f;

	private Renderer visualRenderer;

	private List<PlayerHand> interactingHands = new List<PlayerHand>();

	private void OnTriggerEnter(Collider collider)
	{
		PlayerHand componentInParents = collider.gameObject.GetComponentInParents<PlayerHand>();
		if (componentInParents != null)
		{
			if (interactingHands.Count == 0)
			{
				Color color = visualRenderer.material.color;
				color.a = highlightAlpha;
				visualRenderer.material.color = color;
			}
			if (!interactingHands.Contains(componentInParents))
			{
				interactingHands.Add(componentInParents);
				componentInParents.Vibrate(1, 1000);
			}
		}
	}

	private void OnTriggerExit(Collider collider)
	{
		PlayerHand componentInParents = collider.gameObject.GetComponentInParents<PlayerHand>();
		if (componentInParents != null)
		{
			if (interactingHands.Contains(componentInParents))
			{
				interactingHands.Remove(componentInParents);
			}
			if (interactingHands.Count == 0)
			{
				Color color = visualRenderer.material.color;
				color.a = defaultAlpha;
				visualRenderer.material.color = color;
			}
		}
	}

	private void Awake()
	{
		GameObject gameObject = GameObject.CreatePrimitive(PrimitiveType.Sphere);
		gameObject.transform.SetParent(base.transform, worldPositionStays: false);
		gameObject.transform.localScale = Vector3.one * visualScale;
		UnityEngine.Object.Destroy(gameObject.GetComponent<Collider>());
		SphereCollider sphereCollider = base.gameObject.AddComponent<SphereCollider>();
		sphereCollider.radius = colliderRadius;
		sphereCollider.isTrigger = true;
		visualRenderer = gameObject.GetComponent<Renderer>();
		visualRenderer.material.shader = Shader.Find("Transparent/Diffuse");
		Color color = visualColor;
		color.a = defaultAlpha;
		visualRenderer.material.color = color;
	}

	private void Update()
	{
		foreach (PlayerHand interactingHand in interactingHands)
		{
			if (interactingHand.ControllerIO != null && interactingHand.ControllerIO.TriggerButtonPressed)
			{
				base.transform.position = interactingHand.transform.position;
			}
		}
	}
}
public delegate void PanicToggledEventHandler(object sender);
[RequireComponent(typeof(Collider))]
public class GhostingPulse : UnityEngine.MonoBehaviour
{
	private CapsuleCollider ghostingCollider;

	private Player thisPlayer;

	private float startRadiusScale;

	private float startHeightScale;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip onEnableAudioClip;

	[SerializeField]
	private RecRoomAudioClip activeLoopingAudioClip;

	[Header("Visuals")]
	[SerializeField]
	private FloatValueCurve radiusAnimationCurve;

	[SerializeField]
	private FloatValueCurve heightAnimationCurve;

	[SerializeField]
	private ParticleSystem EMPParticle;

	[SerializeField]
	private FloatValueCurve alphaOverDistanceCurve;

	[SerializeField]
	private Material ghostMaterial;

	[SerializeField]
	private GameObject situationRingPrefab;

	private SFXAudioSource loopingAudioSource;

	private bool _pulseEnabled = true;

	private float activeTime;

	private bool active;

	public Material GhostMaterial => ghostMaterial;

	public bool PulseEnabled
	{
		get
		{
			return _pulseEnabled;
		}
		set
		{
			_pulseEnabled = value;
			if (Active && !_pulseEnabled)
			{
				Active = false;
			}
		}
	}

	public bool Active
	{
		get
		{
			return active;
		}
		set
		{
			if (!PulseEnabled)
			{
				value = false;
			}
			if (!value)
			{
				StopPulseActiveAudio();
			}
			else if (!active)
			{
				PlayPulseActiveAudio();
			}
			activeTime = 0f;
			ghostingCollider.enabled = value;
			SingletonMonoBehaviour<AudioManager>.Instance.VoiceVolumeLowered = value;
			foreach (Transform item in base.transform)
			{
				item.gameObject.SetActive(value);
			}
			bool flag = active;
			active = value;
			if (active != flag && this.PanicToggled != null)
			{
				this.PanicToggled(this);
			}
		}
	}

	public float Radius => ghostingCollider.bounds.extents.x;

	public float MaxRadius => ghostingCollider.radius;

	public event PanicToggledEventHandler PanicToggled;

	private void Awake()
	{
		ghostingCollider = GetComponent<CapsuleCollider>();
		if (ghostingCollider == null)
		{
			UnityEngine.Debug.LogError("Ghosting pulse collider is not a Capsule Collider.");
		}
		thisPlayer = base.gameObject.GetComponentInParents<Player>();
	}

	private void Start()
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(situationRingPrefab, base.transform, worldPositionStays: false);
		gameObject.transform.localScale = Vector3.one;
		gameObject.transform.localPosition = Vector3.zero;
		startRadiusScale = base.transform.localScale.x;
		startHeightScale = base.transform.localScale.z;
		Active = false;
	}

	private void Update()
	{
		if (!Active)
		{
			return;
		}
		base.transform.position = thisPlayer.CurrentFloorPosition;
		base.transform.localPosition = Vector3.zero;
		if (activeTime <= radiusAnimationCurve.Duration)
		{
			float num = startRadiusScale + radiusAnimationCurve.Evaluate(activeTime / radiusAnimationCurve.Duration);
			float z = startHeightScale + heightAnimationCurve.Evaluate(activeTime / heightAnimationCurve.Duration);
			base.transform.localScale = new Vector3(num, num, z);
			if (activeTime + Time.deltaTime > radiusAnimationCurve.Duration && EMPParticle != null)
			{
				EMPParticle.Play();
			}
		}
		activeTime += Time.deltaTime;
	}

	public void TogglePanic()
	{
		Active = !Active;
	}

	public float AlphaForDistance(float distance)
	{
		float t = Mathf.Min(distance / MaxRadius, 1f);
		return alphaOverDistanceCurve.Evaluate(t);
	}

	private void PlayPulseActiveAudio()
	{
		StopPulseActiveAudio();
		AudioManager.Play3DSFX(onEnableAudioClip, thisPlayer.CurrentFloorPosition);
		loopingAudioSource = AudioManager.StartLooping2DSFX(activeLoopingAudioClip);
	}

	private void StopPulseActiveAudio()
	{
		if (loopingAudioSource != null)
		{
			AudioManager.StopLoopingSFX(loopingAudioSource);
			loopingAudioSource = null;
		}
	}
}
public class HeadGestureDetect : UnityEngine.MonoBehaviour
{
	public enum Gesture
	{
		TiltUp,
		TiltDown,
		NodUp,
		NodDown,
		FullNod,
		TurnLeft,
		TurnRight,
		ShakeLeft,
		ShakeRight,
		FullShake,
		LeanLeft,
		LeanRight,
		NodLeft,
		NodRight,
		FullSideNod
	}

	[SerializeField]
	private float nodSensitivity = 10f;

	[SerializeField]
	private float shakeSensitivity = 10f;

	[SerializeField]
	private float leanSensitivity = 10f;

	[SerializeField]
	private float nodNeutralZone = 5f;

	[SerializeField]
	private float shakeNeutralZone = 5f;

	[SerializeField]
	private float leanNeutralZone = 5f;

	[SerializeField]
	private float timeOut = 3f;

	[SerializeField]
	private Transform trackedHead;

	[Tooltip("Enabling this will fire all the different gestures and not just the full gestures.")]
	public bool DetailedDetection;

	private float countdown;

	private float baselineX;

	private float baselineY;

	private float baselineZ;

	private float pitch;

	private float yaw;

	private float roll;

	private float doSomethingTime;

	private bool tiltUp;

	private bool tiltDown;

	private bool nodUp;

	private bool nodDown;

	private bool turnLeft;

	private bool turnRight;

	private bool shakeLeft;

	private bool shakeRight;

	private bool leanLeft;

	private bool leanRight;

	private bool nodLeft;

	private bool nodRight;

	private int nods;

	private int shakes;

	private int sideNods;

	private float pitchAng;

	private float yawAng;

	private float rollAng;

	public event Action<Gesture> GestureDetected;

	private void Start()
	{
		if (trackedHead == null)
		{
			trackedHead = base.transform;
		}
		baselineX = Angle(trackedHead.localEulerAngles.x);
		baselineY = Angle(trackedHead.localEulerAngles.y);
		baselineZ = Angle(trackedHead.localEulerAngles.z);
		doSomethingTime = Time.time;
	}

	private void Update()
	{
		countdown = Time.time - doSomethingTime;
		pitch = Angle(trackedHead.localEulerAngles.x);
		yaw = Angle(trackedHead.localEulerAngles.y);
		roll = Angle(trackedHead.localEulerAngles.z);
		pitchAng = AngleBetween(pitch, baselineX);
		yawAng = AngleBetween(yaw, baselineY);
		rollAng = AngleBetween(roll, baselineZ);
		if (tiltUp && countdown > timeOut)
		{
			tiltUp = false;
			baselineX = pitch;
			return;
		}
		if (tiltDown && countdown > timeOut)
		{
			tiltDown = false;
			baselineX = pitch;
			return;
		}
		if (turnLeft && countdown > timeOut)
		{
			turnLeft = false;
			baselineY = yaw;
			return;
		}
		if (turnRight && countdown > timeOut)
		{
			turnRight = false;
			baselineY = yaw;
			return;
		}
		if (nods > 0 && countdown > timeOut)
		{
			nods = 0;
		}
		if (shakes > 0 && countdown > timeOut)
		{
			shakes = 0;
		}
		if (sideNods > 0 && countdown > timeOut)
		{
			sideNods = 0;
		}
		if (!tiltUp && pitchAng < 0f - nodSensitivity)
		{
			tiltUp = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TiltUp);
			}
		}
		if (tiltUp && pitchAng > nodNeutralZone && countdown < timeOut)
		{
			tiltUp = false;
			nodUp = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodUp);
			}
		}
		if (!tiltDown && pitchAng > nodSensitivity)
		{
			tiltDown = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TiltDown);
			}
		}
		if (tiltDown && pitchAng < nodNeutralZone && countdown < timeOut)
		{
			tiltDown = false;
			doSomethingTime = Time.time;
			nodDown = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodDown);
			}
		}
		if (nodDown && nodUp)
		{
			nods++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullNod);
			}
			doSomethingTime = Time.time;
			nodUp = false;
			nodDown = false;
		}
		if (!turnRight && yawAng > shakeSensitivity)
		{
			turnRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TurnRight);
			}
		}
		if (turnRight && yawAng < shakeNeutralZone && countdown < timeOut)
		{
			turnRight = false;
			shakeRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.ShakeRight);
			}
		}
		if (!turnLeft && yawAng < 0f - shakeSensitivity)
		{
			turnLeft = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TurnLeft);
			}
		}
		if (turnLeft && yawAng > 0f - shakeNeutralZone)
		{
			turnLeft = false;
			doSomethingTime = Time.time;
			shakeLeft = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.ShakeLeft);
			}
		}
		if (shakeLeft && shakeRight)
		{
			shakes++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullShake);
			}
			doSomethingTime = Time.time;
			shakeLeft = false;
			shakeRight = false;
		}
		if (!leanRight && rollAng < 0f - leanSensitivity)
		{
			leanRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.LeanRight);
			}
		}
		if (leanRight && rollAng > leanNeutralZone && countdown < timeOut)
		{
			leanRight = false;
			nodRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodRight);
			}
		}
		if (!leanLeft && rollAng > leanSensitivity)
		{
			leanLeft = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.LeanLeft);
			}
		}
		if (leanLeft && rollAng < leanNeutralZone)
		{
			leanLeft = false;
			doSomethingTime = Time.time;
			nodLeft = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodLeft);
			}
		}
		if (nodLeft && nodRight)
		{
			sideNods++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullSideNod);
			}
			doSomethingTime = Time.time;
			nodLeft = false;
			nodRight = false;
		}
	}

	private float Angle(float a)
	{
		if (a > 180f)
		{
			a -= 360f;
		}
		return a;
	}

	private float AngleBetween(float a, float b)
	{
		float num = a - b;
		if (num > 180f || num < -180f)
		{
			num = 360f - num;
		}
		return num;
	}
}
[DisallowMultipleComponent]
public class NetworkToolController : Photon.MonoBehaviour
{
	private class ToolPickupProperty
	{
		private const string TOOL_PICKUP_PROPERTY = "Tool_Pickup.";

		public Tool tool { get; private set; }

		public Vector3 pickupPosition { get; private set; }

		public Quaternion pickupRotation { get; private set; }

		public int handType { get; private set; }

		public int serverTime { get; private set; }

		public ToolPickupProperty(object[] values)
		{
			tool = Tool.Find((int)values[0]);
			pickupPosition = (Vector3)values[1];
			pickupRotation = (Quaternion)values[2];
			handType = (int)values[3];
			serverTime = (int)values[4];
		}

		public ToolPickupProperty(Tool tool, Vector3 pickupPosition, Quaternion pickupRotation, int handType)
		{
			this.tool = tool;
			this.pickupPosition = pickupPosition;
			this.pickupRotation = pickupRotation;
			this.handType = handType;
			serverTime = PhotonNetwork.ServerTimestamp;
		}

		public object[] GetPhotonProperty()
		{
			return new object[5]
			{
				(!(tool.photonView != null)) ? (-1) : tool.photonView.viewID,
				pickupPosition,
				pickupRotation,
				handType,
				serverTime
			};
		}

		public static ToolPickupProperty GetToolPickup(Player player, PlayerHand.HandType handType)
		{
			string key = "Tool_Pickup." + (int)handType;
			if (player.owner.customProperties.ContainsKey(key))
			{
				return new ToolPickupProperty((object[])player.owner.customProperties[key]);
			}
			return null;
		}

		public static void RemoveProperty(Player player, PlayerHand.HandType handType)
		{
			string text = "Tool_Pickup." + (int)handType;
			if (player.owner.customProperties.ContainsKey(text))
			{
				player.owner.RemoveCustomProperties(text);
			}
		}

		public void SetPropertyForPlayer(Player player)
		{
			string propertyName = "Tool_Pickup." + handType;
			player.photonView.owner.SetCustomProperties(propertyName, GetPhotonProperty());
		}
	}

	private Player thisPlayer;

	protected override void Awake()
	{
		base.Awake();
		thisPlayer = GetComponent<Player>();
		Tool.HolderChanged += OnToolHolderChanged;
		Tool[] array = UnityEngine.Object.FindObjectsOfType<Tool>();
		foreach (Tool tool in array)
		{
			OnToolHolderChanged(tool);
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		Tool.HolderChanged -= OnToolHolderChanged;
	}

	private void Start()
	{
		base.enabled = base.isLocal;
	}

	public void TryPickupToolWithDominantHand(Tool tool)
	{
		int type = (int)thisPlayer.DominantHand.Type;
		TryPickupTool(tool, type);
	}

	public void TryPickupTool(Tool tool, int handTypeId)
	{
		PlayerHand hand = thisPlayer.GetHand(handTypeId);
		hand.GetToolPickupPositionAndRotation(tool, useGravityPickup: true, Vector3.zero, out var handSpacePickupPosition, out var handSpacePickupRotation);
		TryPickupTool(tool, handSpacePickupPosition, handSpacePickupRotation, handTypeId);
	}

	public void TryPickupTool(Tool tool, Vector3 handSpacePickupPosition, Quaternion handSpacePickupRotation, int handTypeId)
	{
		int holderId = tool.HolderId;
		if (holderId != PhotonPlayer.Invalid && (holderId != base.photonView.ownerId || !thisPlayer.CanInteractWithTools))
		{
			return;
		}
		OutfitTool outfitTool = tool as OutfitTool;
		if (!(outfitTool != null) || outfitTool.TryPickupOutfitTool(thisPlayer))
		{
			PlayerHand hand = thisPlayer.GetHand(handTypeId);
			if (hand != null && hand.IsHoldingTool)
			{
				ReleaseTool(hand.Tool);
			}
			ToolPickupProperty toolPickupProperty = new ToolPickupProperty(tool, handSpacePickupPosition, handSpacePickupRotation, handTypeId);
			toolPickupProperty.SetPropertyForPlayer(thisPlayer);
			tool.HolderId = base.photonView.ownerId;
			PickupToolSuccess(tool);
		}
	}

	public void UpdateHeldToolPickupTransform(Tool tool, Vector3 pickupPosition, Quaternion pickupRotation)
	{
		if (thisPlayer.isLocal)
		{
			PlayerHand playerHand = null;
			if (thisPlayer.LeftHand.Tool == tool)
			{
				playerHand = thisPlayer.LeftHand;
			}
			else if (thisPlayer.RightHand.Tool == tool)
			{
				playerHand = thisPlayer.RightHand;
			}
			if (playerHand != null)
			{
				int type = (int)playerHand.Type;
				ToolPickupProperty toolPickupProperty = new ToolPickupProperty(tool, pickupPosition, pickupRotation, type);
				toolPickupProperty.SetPropertyForPlayer(thisPlayer);
				base.photonView.RPC("RpcUpdateHeldToolPickupTransform", PhotonTargets.All, tool.photonView.viewID, pickupPosition, pickupRotation);
			}
		}
	}

	private void OnToolHolderChanged(Tool tool)
	{
		if (!thisPlayer.isLocal)
		{
			return;
		}
		Player player = Player.Find(tool.HolderId);
		PhotonPlayer[] playerList = PhotonNetwork.playerList;
		foreach (PhotonPlayer photonPlayer in playerList)
		{
			Player player2 = photonPlayer.ToPlayer();
			if (player2 != null && player2 != player && (player2.LeftHand.Tool == tool || player2.RightHand.Tool == tool))
			{
				player2.ToolController.ReleaseTool(tool);
			}
		}
		if (player != null && player.CanInteractWithTools)
		{
			player.ToolController.PickupToolSuccess(tool);
		}
	}

	private void PickupToolSuccess(Tool tool)
	{
		ToolPickupProperty toolPickup = ToolPickupProperty.GetToolPickup(thisPlayer, PlayerHand.HandType.Left);
		ToolPickupProperty toolPickup2 = ToolPickupProperty.GetToolPickup(thisPlayer, PlayerHand.HandType.Right);
		ToolPickupProperty toolPickupProperty = null;
		bool flag = toolPickup != null && toolPickup.tool == tool;
		bool flag2 = toolPickup2 != null && toolPickup2.tool == tool;
		if (flag && flag2)
		{
			toolPickupProperty = ((toolPickup.serverTime >= toolPickup2.serverTime) ? toolPickup : toolPickup2);
		}
		else if (flag)
		{
			toolPickupProperty = toolPickup;
		}
		else if (flag2)
		{
			toolPickupProperty = toolPickup2;
		}
		if (toolPickupProperty != null)
		{
			tool.photonView.TransferOwnership(thisPlayer.owner);
			PickupToolSuccessHandPickup(tool, toolPickupProperty.pickupPosition, toolPickupProperty.pickupRotation, thisPlayer.GetHand(toolPickupProperty.handType));
		}
	}

	private void PickupToolSuccessHandPickup(Tool tool, Vector3 pickupPosition, Quaternion pickupRotation, PlayerHand hand)
	{
		PlayerHand otherHand = thisPlayer.GetOtherHand(hand.Type);
		if (otherHand != null && otherHand != hand && otherHand.Tool == tool)
		{
			ReleaseTool(tool, otherHand, ignoreHolderProperty: true);
		}
		if (hand.Tool != tool)
		{
			if (hand.Tool != null)
			{
				ReleaseTool(hand.Tool, hand);
			}
			hand.PickupTool(tool, pickupPosition, pickupRotation);
		}
	}

	public void ReleaseTool(Tool tool)
	{
		if (!(tool == null))
		{
			PlayerHand playerHand = null;
			if (thisPlayer.LeftHand.Tool == tool)
			{
				playerHand = thisPlayer.LeftHand;
			}
			else if (thisPlayer.RightHand.Tool == tool)
			{
				playerHand = thisPlayer.RightHand;
			}
			if (playerHand != null)
			{
				ReleaseTool(tool, playerHand);
			}
		}
	}

	private void ReleaseTool(Tool tool, PlayerHand hand, bool ignoreHolderProperty = false)
	{
		if (!(hand.Tool == tool))
		{
			return;
		}
		hand.ReleaseTool();
		if (base.hasAuthority)
		{
			if (!ignoreHolderProperty && tool.hasAuthority)
			{
				tool.HolderId = PhotonPlayer.Invalid;
			}
			ToolPickupProperty.RemoveProperty(thisPlayer, hand.Type);
		}
	}

	[PunRPC]
	private void RpcUpdateHeldToolPickupTransform(int toolPhotonViewId, Vector3 pickupPosition, Quaternion pickupRotation)
	{
		PhotonView photonView = PhotonView.Find(toolPhotonViewId);
		Tool tool = ((!(photonView != null)) ? null : photonView.GetComponent<Tool>());
		if (tool != null && tool.IsHeld && tool.Owner == thisPlayer)
		{
			tool.UpdatePickupTransform(pickupPosition, pickupRotation);
		}
	}
}
public class OverlapVolume : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Vector3 localSize;

	[SerializeField]
	private Vector3 center;

	private Vector3 localExtents;

	private bool localPlayerInTrigger;

	private Vector3 GlobalSize => Vector3.Scale(base.transform.lossyScale, localSize);

	public event Action LocalPlayerTriggerEnterEvent;

	protected virtual void Awake()
	{
		localExtents = localSize / 2f;
	}

	public bool ContainsPoint(Vector3 point)
	{
		Vector3 vector = base.transform.InverseTransformPoint(point) - center;
		return vector.x < localExtents.x && vector.x > 0f - localExtents.x && vector.y < localExtents.y && vector.y > 0f - localExtents.y && vector.z < localExtents.z && vector.z > 0f - localExtents.z;
	}

	private void FixedUpdate()
	{
		bool flag = localPlayerInTrigger;
		localPlayerInTrigger = Player.LocalPlayer != null && ContainsPoint(Player.LocalPlayer.Head.transform.position);
		if (!flag && localPlayerInTrigger && this.LocalPlayerTriggerEnterEvent != null)
		{
			this.LocalPlayerTriggerEnterEvent();
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		Gizmos.matrix = Matrix4x4.TRS(base.transform.TransformPoint(center), base.transform.rotation, GlobalSize);
		Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
	}
}
public class PersonalBubble : UnityEngine.MonoBehaviour
{
	[Flags]
	public enum BubbleMask
	{
		Hand_Local = 1,
		Hand_Remote = 2,
		Tool = 4
	}

	[Flags]
	public enum ToolMask
	{
		Ball = 1,
		BoxingGlove = 2,
		Bucket = 4,
		Card = 8,
		CardBox = 0x10,
		Clipboard = 0x20,
		Cone = 0x40,
		Dart = 0x80,
		Extrusion = 0x100,
		DiscGolfDisc = 0x200,
		Gun = 0x400,
		HandheldCameraTool = 0x800,
		HelpClipboard = 0x1000,
		LaundryBin = 0x2000,
		MeshExtruderTool = 0x4000,
		OutfitTool = 0x8000,
		PaddleballBall = 0x10000,
		PaddleballPaddle = 0x20000,
		Radio = 0x40000,
		WaterBottle = 0x80000,
		WaterJug = 0x100000
	}

	[SerializeField]
	[EnumFlags]
	private BubbleMask bubbleFlags;

	[SerializeField]
	[EnumFlags]
	private ToolMask excludedTools;

	[Tooltip("How long after leaving this zone we can show your hand back again? In seconds!")]
	[SerializeField]
	private float turnVisibleTimeout = 0.15f;

	[SerializeField]
	private BoxCollider boxCollider;

	private Player thisPlayer;

	private GameManager gameManager;

	private Vector3 boxSize = Vector3.one;

	private const int MAX_RAYCAST_HIT = 256;

	private static Collider[] hits = new Collider[256];

	private Dictionary<Type, ToolMask> toolMaskMap;

	private void Awake()
	{
		thisPlayer = GetComponentInParent<Player>();
		boxSize = boxCollider.size.MultiplyComponents(boxCollider.transform.lossyScale) / 2f;
		InitToolMaskMap();
	}

	private void Start()
	{
		gameManager = RecRoomSceneManager.Instance.GameManager;
		if (PUNNetworkManager.Instance.IsInDormRoom)
		{
			base.enabled = false;
		}
	}

	private void FixedUpdate()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance.PersonalBubble && (gameManager == null || gameManager.CurrentState != GameStates.GAME_RUNNING) && Player.LocalPlayer != null)
		{
			Vector3 center = boxCollider.transform.TransformPoint(boxCollider.center);
			int num = Physics.OverlapBoxNonAlloc(center, boxSize, hits, boxCollider.transform.rotation, 227948032);
			for (int i = 0; i < num; i++)
			{
				CheckCollider(hits[i]);
			}
		}
	}

	private void CheckCollider(Collider col)
	{
		GameObject gameObject = col.gameObject;
		bool flag = IsMaskActive(BubbleMask.Hand_Local);
		bool flag2 = IsMaskActive(BubbleMask.Hand_Remote);
		bool flag3 = IsMaskActive(BubbleMask.Tool);
		if ((flag && gameObject.IsInLayerMask(LayerMasks.LocalPlayerPhysics)) || (flag2 && gameObject.IsInLayerMask(LayerMasks.RemotePlayerPhysics)))
		{
			PlayerCollider component = gameObject.GetComponent<PlayerCollider>();
			if (component != null && component.ThisPlayer != null && component.BodyPart.IsHand())
			{
				bool isLocal = component.ThisPlayer.isLocal;
				if ((isLocal && flag) || (!isLocal && flag2))
				{
					PlayerHand playerHand = ((component.BodyPart != Player.BodyPart.LeftHand) ? component.ThisPlayer.RightHand : component.ThisPlayer.LeftHand);
					playerHand.SetInPersonalBubble(turnVisibleTimeout);
				}
			}
		}
		else if (flag3 && gameObject.IsInLayerMask(LayerMasks.ToolPhysics))
		{
			ToolCollider component2 = gameObject.GetComponent<ToolCollider>();
			if (component2 != null && component2.Tool != null && !IsToolExcluded(component2.Tool))
			{
				bool inPersonalBubble = !thisPlayer.isLocal || IsMaskActive(BubbleMask.Hand_Local);
				component2.Tool.InPersonalBubble = inPersonalBubble;
			}
		}
	}

	private bool IsMaskActive(BubbleMask mask)
	{
		return (mask & bubbleFlags) == mask;
	}

	private bool IsToolExcluded(Tool tool)
	{
		ToolMask toolMask = ToToolMask(tool);
		return toolMask != 0 && (toolMask & excludedTools) == toolMask;
	}

	private ToolMask ToToolMask(Tool tool)
	{
		Type type = tool.GetType();
		ToolMask value = (ToolMask)0;
		toolMaskMap.TryGetValue(type, out value);
		return value;
	}

	private void InitToolMaskMap()
	{
		if (toolMaskMap != null)
		{
			return;
		}
		toolMaskMap = new Dictionary<Type, ToolMask>();
		foreach (ToolMask value in Enum.GetValues(typeof(ToolMask)))
		{
			string typeName = value.ToString();
			Type type = Type.GetType(typeName);
			if (type != null && !toolMaskMap.ContainsKey(type))
			{
				toolMaskMap.Add(type, value);
			}
		}
	}
}
public class PersonalMuteZone : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private BoxCollider boxCollider;

	private Player thisPlayer;

	private Vector3 boxSize = Vector3.one;

	[Tooltip("Delay before mute is active, this is to filter out quick swipe of hand in front of face without meaning to mute.")]
	[SerializeField]
	private float muteDelay = 1f;

	private bool isHandMuted;

	private float inMuteZoneDuration;

	private const int MAX_RAYCAST_HIT = 256;

	private static Collider[] hits = new Collider[256];

	private void Awake()
	{
		thisPlayer = GetComponentInParent<Player>();
		boxSize = boxCollider.size.MultiplyComponents(boxCollider.transform.lossyScale) / 2f;
		base.enabled = thisPlayer.isLocal;
	}

	private void FixedUpdate()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat != VoiceChat.AlwaysOn)
		{
			return;
		}
		bool flag = false;
		Vector3 center = boxCollider.transform.TransformPoint(boxCollider.center);
		int num = Physics.OverlapBoxNonAlloc(center, boxSize, hits, boxCollider.transform.rotation, 1049088);
		for (int i = 0; i < num; i++)
		{
			if (flag)
			{
				break;
			}
			flag |= IsHandInMuteZone(hits[i]);
		}
		if (flag)
		{
			inMuteZoneDuration += Time.deltaTime;
			if (!thisPlayer.Mute && inMuteZoneDuration >= muteDelay)
			{
				isHandMuted = true;
				Player.LocalPlayer.Mute = true;
				ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Muted", 1.5f);
			}
		}
		else
		{
			inMuteZoneDuration = 0f;
			if (isHandMuted)
			{
				Player.LocalPlayer.Mute = false;
				isHandMuted = false;
				ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Unmuted", 1.5f);
			}
		}
	}

	private bool IsHandInMuteZone(Collider col)
	{
		Player.BodyPart bodyPart;
		Player colliderPlayer = col.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && bodyPart.IsHand())
		{
			PlayerHand hand = colliderPlayer.GetHand(bodyPart);
			if (hand != null && hand.IsVisible)
			{
				return true;
			}
		}
		return false;
	}
}
