	public int PlayerIndex
	{
		get
		{
			if (playerIndexDirty)
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					if (PhotonNetwork.playerList[i] == PhotonPlayer)
					{
						playerIndex = i;
						playerIndexDirty = false;
						break;
					}
				}
			}
			return playerIndex;
		}
	}

