	protected override void Awake()
	{
		base.Awake();
		if (ThisPlayer == null)
		{
			ThisPlayer = base.gameObject.GetComponentInParents<Player>();
		}
		GravityPickupFingerOffset = defaultGravityPickupFingerOffset;
		GravityPickupCapsuleLength = defaultGravityPickupCapsuleLength;
		GravityPickupCapsuleRadius = defaultGravityPickupCapsuleRadius;
		GravityPickupSphereRadius = defaultGravityPickupSphereRadius;
		PhysicalPickupSphereRadius = defaultPhysicalPickupSphereRadius;
		NetworkTransform = GetComponent<PUNNetworkTransform>();
		rigidbody = GetComponent<Rigidbody>();
		handColliders = GetComponentsInChildren<PlayerHandCollider>();
		TrackedVelocity = GetComponent<TrackedVelocity>();
		handAnimator = GetComponentInChildren<Animator>();
		Gestures = GetComponent<PlayerHandGestures>();
		PlayerHandRemote = UnityEngine.Object.Instantiate(playerHandRemotePrefab);
		PlayerHandRemote.Player = ThisPlayer;
		PlayerHandRemote.Hand = this;
		ThisPlayer.SetParentPlayerRoot(PlayerHandRemote.transform);
		controllerTrackingProperty = "controllerTrackingProperty_" + Type;
		rigidbodyPickup = GetComponent<PlayerHandRigidbodyPickup>();
		visualRenderers = meshRoot.GetComponentsInChildren<Renderer>();
	}

	private void Start()
	{
		gameManager = RecRoomSceneManager.Instance.GameManager;
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent += OnGameTeamChange;
			gameManager.StateChangeEvent += OnGameStateChanged;
		}
		UpdateVisibility(forceUpdate: true);
	}

	public void PickupTool(Tool tool, Vector3 handSpacePickupPosition, Quaternion handSpacePickupRotation)
	{
		if (this.PickupToolEvent != null)
		{
			this.PickupToolEvent(this, tool);
		}
		MeshesVisible = false;
		PlayerHandCollider[] array = handColliders;
		foreach (PlayerHandCollider playerHandCollider in array)
		{
			playerHandCollider.DisableHandToolCollisions(tool);
		}
		Tool = tool;
		Tool.ToolRenderer.SetVisible(ThisPlayer.IsVisible);
		Tool.Pickup(ThisPlayer, rigidbody, handSpacePickupPosition, handSpacePickupRotation);
		hoveredTool = null;
		if (ThisPlayer.isLocal)
		{
			Vibrate(50, 1000);
		}
	}

	public void ReleaseTool()
	{
		PlayerHandCollider[] array = handColliders;
		foreach (PlayerHandCollider playerHandCollider in array)
		{
			playerHandCollider.ReEnableHandToolCollisions(Tool);
		}
		Vector3 averageLinearVelocity = TrackedVelocity.GetAverageLinearVelocity(preReleaseWindow);
		Vector3 averageAngularVelocity = TrackedVelocity.GetAverageAngularVelocity(preReleaseWindow);
		Tool.Release(ThisPlayer, averageLinearVelocity, averageAngularVelocity);
		Tool = null;
		MeshesVisible = true;
	}

	public void GetToolPickupPositionAndRotation(Tool tool, bool useGravityPickup, Vector3 gravityPickupDirection, out Vector3 handSpacePickupPosition, out Quaternion handSpacePickupRotation)
	{
		if ((useGravityPickup && !tool.SupportsOffCenterGravityPickup) || !tool.SupportsOffCenterPickup)
		{
			tool.GetHandSpacePickupTransform(base.transform, Type, out handSpacePickupPosition, out handSpacePickupRotation);
			return;
		}
		if (useGravityPickup && tool.SupportsOffCenterGravityPickup)
		{
			Vector3 position = base.transform.position + Vector3.ProjectOnPlane(tool.transform.position - base.transform.position, gravityPickupDirection);
			handSpacePickupPosition = base.transform.InverseTransformPoint(position);
		}
		else
		{
			handSpacePickupPosition = base.transform.InverseTransformPoint(tool.transform.position);
		}
		handSpacePickupRotation = base.transform.InverseTransformRotation(tool.transform.rotation);
	}

	public void Vibrate(float duration, float intensity = 1f)
	{
		Vibrate((int)(duration * 1000f), (ushort)(intensity * 1000f));
	}

	public void Vibrate(int milliseconds = 1, ushort intensity = 1000)
	{
		if (ControllerIO != null)
		{
			ControllerIO.Vibrate(milliseconds, intensity);
		}
	}

	private IEnumerator VibrateCoroutine(int milliseconds, ushort intensity)
	{
		float endTime = Time.unscaledTime + (float)milliseconds / 1000f;
		while (Time.unscaledTime < endTime)
		{
			if (ControllerIO != null)
			{
				ControllerIO.Vibrate(intensity, 1000);
			}
			yield return null;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (ControllerIO != null)
		{
			ControllerIO.TransformUpdated -= OnTrackerTransformUpdate;
			ControllerIO.UIInteractionEnabled = true;
		}
		if (PlayerHandRemote != null)
		{
			UnityEngine.Object.Destroy(PlayerHandRemote);
		}
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent -= OnGameTeamChange;
			gameManager.StateChangeEvent -= OnGameStateChanged;
		}
		if (Tool != null)
		{
			ThisPlayer.ToolController.ReleaseTool(Tool);
		}
	}

	private void OnTrackerTransformUpdate()
	{
		rigidbody.MovePosition(ControllerIO.transform.position);
		rigidbody.MoveRotation(ControllerIO.transform.rotation);
	}

	private void FixedUpdate()
	{
		InPersonalBubble = false;
		if (ControllerIO == null)
		{
			return;
		}
		if (Tool == null && !RemoteVisible && isHandTrackingCached && !IsUsingMenu)
		{
			FindClosestOutfitTrigger();
			Tool tool = FindClosestToolInPhysicalPickupRange();
			if (tool != null)
			{
				hoveredToolInPhysicalPickupRange = true;
			}
			else
			{
				tool = FindClosestToolInMagnetPickupRange(out gravityPickupVector);
				hoveredToolInPhysicalPickupRange = false;
			}
			hoveredTool = tool;
		}
		else
		{
			hoveredTool = null;
		}
		FindClosestTeleportationPortal();
	}

	private void Update()
	{
		isHandTrackingCached = IsHandTracking;
		UpdateVisibility();
		if (ControllerIO == null)
		{
			IsHandTracking = false;
			return;
		}
		if (base.isLocal)
		{
			IsHandTracking = ControllerIO.IsTracking;
		}
		UpdateAnimation();
		UpdateTool();
		UpdateRemoteVisibility();
	}

	public void SetInPersonalBubble(float turnVisibleTimeout)
	{
		InPersonalBubble = true;
		inPersonalBubbleTimeout = turnVisibleTimeout;
		lastTimeInPersonalBubble = Time.time;
	}

	private void UpdateVisibility(bool forceUpdate = false)
	{
		bool flag = base.isLocal || ThisPlayer.IsVisible;
		bool flag2 = flag && !InPersonalBubble;
		bool flag3 = flag && RemoteVisible && !InPersonalBubble;
		bool isVisible = IsVisible;
		if (!forceUpdate && wasVisible == isVisible && wasToolVisible == flag2 && flag3 == wasRemoteVisible && isHandTrackingCached == wasHandTracking)
		{
			return;
		}
		Renderer[] array = visualRenderers;
		foreach (Renderer renderer in array)
		{
			renderer.gameObject.SetActive(isVisible);
		}
		PlayerHandCollider[] array2 = handColliders;
		foreach (PlayerHandCollider playerHandCollider in array2)
		{
			if (playerHandCollider != null && !playerHandCollider.IsTrigger)
			{
				playerHandCollider.gameObject.SetActive(isVisible);
			}
		}
		ThisPlayer.PlayerOutfit.SetHandVisible(Type, isVisible);
		if (Tool != null)
		{
			Tool.ToolRenderer.SetVisible(flag2, flag3);
		}
		PlayerHandRemote.Visible = flag3;
		if (!isVisible)
		{
			hoveredTool = null;
		}
		wasVisible = isVisible;
		wasToolVisible = flag2;
		wasRemoteVisible = flag3;
		wasHandTracking = isHandTrackingCached;
	}

	private void UpdateRemoteVisibility()
	{
		if (base.isLocal)
		{
			ControllerIO.UIInteractionEnabled = CanMenuLaserInterract();
			bool flag = PlayerHandRemote.TeleportLaserVisible || PlayerHandRemote.MenuLaserVisible || (ControllerIO.UIInteractionEnabled && ControllerIO.UIRaycastPosition.HasValue);
			if (flag)
			{
				lastRemoteShowTime = Time.time;
			}
			if (flag || (!flag && Time.time - lastRemoteShowTime > 0.01f))
			{
				RemoteVisible = flag;
			}
		}
	}

	private bool CanMenuLaserInterract()
	{
		return !PlayerHandRemote.TeleportLaserVisible && isHandTrackingCached && (((Tool == null || Tool.CanInterractWithUI) && hoveredTool == null) || PlayerHandRemote.MenuLaserVisible);
	}

	private Tool FindClosestToolInPhysicalPickupRange()
	{
		Tool closestTool = null;
		float closestToolDistance = float.MaxValue;
		FindClosestToolInSphere(ref closestTool, ref closestToolDistance, PhysicalPickupSphereRadius, physicalPickup: true);
		return closestTool;
	}

	private Tool FindClosestToolInSphere(ref Tool closestTool, ref float closestToolDistance, float radius, bool physicalPickup)
	{
		int num = Physics.OverlapSphereNonAlloc(handCenter.position, radius, colliderHits, 226894848);
		for (int i = 0; i < num; i++)
		{
			ToolCollider toolCollider = null;
			Tool colliderTool = colliderHits[i].GetColliderTool(out toolCollider);
			if (colliderTool != null)
			{
				colliderTool = colliderTool.GetHighlightedTool(ThisPlayer, toolCollider, physicalPickup, handCenter.position);
				if (colliderTool != null && TryGetDistanceToTool(colliderTool, out var distance) && distance < closestToolDistance)
				{
					closestTool = colliderTool;
					closestToolDistance = distance;
				}
			}
		}
		return closestTool;
	}

	private bool TryGetDistanceToTool(Tool tool, out float distance)
	{
		Vector3 lhs = tool.ColliderBounds.center - handCenter.position;
		distance = lhs.magnitude;
		return Vector3.Dot(lhs, handCenter.right) >= 0f;
	}

	private Tool FindClosestToolInMagnetPickupRange(out Vector3 selectionVector)
	{
		selectionVector = GravityPickupDirection;
		Vector3 origin = GravityPickupOrigin + selectionVector * GravityPickupCapsuleRadius;
		float maxDistance = defaultGravityPickupCapsuleLength - 2f * GravityPickupCapsuleRadius;
		int num = Physics.SphereCastNonAlloc(origin, GravityPickupCapsuleRadius, selectionVector, raycastHits, maxDistance, 226894848);
		float num2 = float.MaxValue;
		float closestToolDistance = float.MaxValue;
		Tool closestTool = null;
		for (int i = 0; i < num; i++)
		{
			ToolCollider toolCollider = null;
			Tool colliderTool = raycastHits[i].collider.GetColliderTool(out toolCollider);
			if (!(colliderTool != null))
			{
				continue;
			}
			colliderTool = colliderTool.GetHighlightedTool(ThisPlayer, toolCollider, physicalPickup: false, GravityPickupOrigin);
			if (colliderTool != null)
			{
				Bounds colliderBounds = colliderTool.ColliderBounds;
				Vector3 center = colliderBounds.center;
				Vector3 vector = GravityPickupOrigin - center;
				Vector3 vector2 = vector - Vector3.Project(vector, selectionVector);
				float magnitude = colliderBounds.extents.magnitude;
				Vector3 vector3 = center + vector2.normalized * magnitude;
				Vector3 lhs = vector3 - GravityPickupOrigin;
				float num3 = Vector3.Dot(lhs, selectionVector);
				if (num3 >= 0f && num3 < num2)
				{
					closestTool = colliderTool;
					closestToolDistance = vector.magnitude;
				}
			}
		}
		FindClosestToolInSphere(ref closestTool, ref closestToolDistance, GravityPickupSphereRadius, physicalPickup: false);
		return closestTool;
	}

	private void FindClosestOutfitTrigger()
	{
		bool flag = false;
		if (SingletonMonoBehaviour<TutorialManager>.Instance.CanRemoveOutfit)
		{
			int num = Physics.RaycastNonAlloc(handCenter.position - handCenter.forward * outfitBackwardPickupRange, handCenter.forward, raycastHits, outfitBackwardPickupRange + outfitForwardPickupRange, 32768);
			if (num != 0)
			{
				raycastHits.SortByDistanceToCenter(num);
				for (int i = 0; i < num; i++)
				{
					OutfitTrigger component = raycastHits[i].collider.GetComponent<OutfitTrigger>();
					if (component != null && component.OutfitItem != null && component.OutfitItem.Owner == ThisPlayer && component.OutfitItem.CurrentBodyPart != (Player.BodyPart)((Type != HandType.Left) ? 3 : 2) && component.OutfitItem.Type != OutfitManager.OutfitType.Shirt && (component.EnabledOutsideChangingRoom || ThisPlayer.IsInChangingRoom))
					{
						TriggeredOutfit = component;
						flag = true;
						break;
					}
				}
			}
		}
		if (!flag)
		{
			TriggeredOutfit = null;
		}
	}

	private void FindClosestTeleportationPortal()
	{
		TeleportationPortal teleportationPortal = null;
		if (IsVisible && Physics.Raycast(handCenter.position - handCenter.forward * outfitBackwardPickupRange, handCenter.forward, out var hitInfo, outfitBackwardPickupRange + outfitForwardPickupRange, 18433, QueryTriggerInteraction.Collide))
		{
			teleportationPortal = hitInfo.collider.GetComponent<TeleportationPortal>();
		}
		if (teleportationPortal != null && teleportationPortal.SupportsHandInteraction)
		{
			TriggeredPortal = teleportationPortal;
		}
		else
		{
			TriggeredPortal = null;
		}
	}

	private void UpdateAnimation()
	{
		if (IsVisible)
		{
			OpenClosedAxis = ControllerIO.PickupAxis;
			if (handAnimator.isActiveAndEnabled)
			{
				handAnimator.SetFloat(openClosedAnimatorId, OpenClosedAxis);
			}
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			RemoteVisible = (bool)stream.ReceiveNext() && ThisPlayer.IsVisible;
			OpenClosedAxis = (float)stream.ReceiveNext();
			if (handAnimator.isActiveAndEnabled)
			{
				handAnimator.SetFloat(openClosedAnimatorId, OpenClosedAxis);
			}
			LaserTeleporter.LaserMode laserMode = (LaserTeleporter.LaserMode)stream.ReceiveNext();
			if (!ThisPlayer.IsVisible)
			{
				PlayerHandRemote.Mode = LaserTeleporter.LaserMode.Disabled;
			}
			else
			{
				PlayerHandRemote.Mode = laserMode;
			}
			if (laserMode != LaserTeleporter.LaserMode.Disabled)
			{
				Vector3 initialTangent = (Vector3)stream.ReceiveNext();
				Vector3 vector = (Vector3)stream.ReceiveNext();
				Vector3 finalPoint = (Vector3)stream.ReceiveNext();
				Vector3 teleportTarget = (Vector3)stream.ReceiveNext();
				Vector3 zero = Vector3.zero;
				Vector3 zero2 = Vector3.zero;
				if ((bool)stream.ReceiveNext())
				{
					zero = (Vector3)stream.ReceiveNext();
					zero2 = (Vector3)stream.ReceiveNext();
					PlayerHandRemote.ParabolicPointer.SetParabolaPointsWithReflection(initialTangent, vector, zero, zero2, finalPoint);
				}
				else
				{
					PlayerHandRemote.ParabolicPointer.SetParabolaPoints(initialTangent, vector, finalPoint);
				}
				PlayerHandRemote.TeleportTarget = teleportTarget;
			}
			return;
		}
		stream.SendNext(RemoteVisible);
		stream.SendNext(OpenClosedAxis);
		stream.SendNext((int)PlayerHandRemote.Mode);
		if (PlayerHandRemote.Mode != LaserTeleporter.LaserMode.Disabled)
		{
			stream.SendNext(PlayerHandRemote.ParabolicPointer.InitialParabolaTangent);
			stream.SendNext(PlayerHandRemote.ParabolicPointer.FinalParabolaTangent);
			stream.SendNext(PlayerHandRemote.ParabolicPointer.FinalParabolaPoint);
			stream.SendNext(PlayerHandRemote.TeleportTarget);
			stream.SendNext(PlayerHandRemote.ParabolicPointer.Reflected);
			if (PlayerHandRemote.ParabolicPointer.Reflected)
			{
				stream.SendNext(PlayerHandRemote.ParabolicPointer.ReflectionPoint);
				stream.SendNext(PlayerHandRemote.ParabolicPointer.ReflectionNormal);
			}
		}
	}

	private void UpdateTool()
	{
		bool flag = ControllerIO.HairPickupButtonDown || (ControllerIO.HairPickupButtonPressed && !ControllerIO.HairPickupButtonDownConsumed && Time.unscaledTime - ControllerIO.HairPickupButtonDownTime <= hairTriggerReactionWindow);
		bool hairPickupButtonDown = ControllerIO.HairPickupButtonDown;
		bool hairPickupButtonUp = ControllerIO.HairPickupButtonUp;
		bool pickupButtonUp = ControllerIO.PickupButtonUp;
		bool menuButtonUp = ControllerIO.MenuButtonUp;
		bool flag2 = ControllerIO.HairTriggerButtonDown || (ControllerIO.HairTriggerButtonPressed && !ControllerIO.HairTriggerButtonDownConsumed && Time.unscaledTime - ControllerIO.HairTriggerButtonDownTime <= hairTriggerReactionWindow);
		bool triggerButtonPressed = ControllerIO.TriggerButtonPressed;
		bool hairTriggerButtonUp = ControllerIO.HairTriggerButtonUp;
		float triggerAxis = ControllerIO.TriggerAxis;
		if (Tool != null)
		{
			if (Tool.IsLocked)
			{
				Tool.InputAmount = triggerAxis;
				if (flag2)
				{
					Tool.OnInputDown();
					ControllerIO.HairTriggerButtonDownConsumed = true;
				}
				if (triggerButtonPressed)
				{
					Tool.OnInputPressed();
				}
				if (hairTriggerButtonUp)
				{
					Tool.OnInputUp();
				}
				if (menuButtonUp && Tool.IsLocked && Tool.CanBeUnlocked)
				{
					Tool.IsLocked = false;
					Vibrate(500, 1000);
					if (!triggerButtonPressed)
					{
						ThisPlayer.ToolController.ReleaseTool(Tool);
					}
				}
			}
			else if (!Tool.IsLocked && menuButtonUp)
			{
				Tool.IsLocked = true;
				Vibrate(500, 1000);
			}
			else if ((!Tool.IsSmartTool && hairPickupButtonUp) || (Tool.IsSmartTool && pickupButtonUp))
			{
				if (Tool.IsSmartTool)
				{
					ControllerIO.HairPickupButtonDownConsumed = true;
				}
				ThisPlayer.ToolController.ReleaseTool(Tool);
			}
		}
		else
		{
			if (!isHandTrackingCached)
			{
				return;
			}
			if (!TryRemoveTriggeredOutfit(hairPickupButtonDown) && hoveredTool != null)
			{
				bool flag3 = hairPickupButtonDown;
				if (hoveredTool.SupportsAssistedCatching)
				{
					flag3 = flag;
				}
				if (flag3)
				{
					TryPickupHoveredTool();
					ControllerIO.HairPickupButtonDownConsumed = true;
				}
			}
			else if (TriggeredPortal != null && hairPickupButtonDown)
			{
				PlayerHandRemote.TeleportTarget = TriggeredPortal.DestinationPosition;
				PlayerHandRemote.PerformPortalTeleport(TriggeredPortal);
			}
		}
	}

	public bool TryRemoveTriggeredOutfit(bool buttonDown)
	{
		Vector3 handSpacePickupPosition = Vector3.zero;
		Quaternion handSpacePickupRotation = Quaternion.identity;
		if (!RemoteVisible && buttonDown && TriggeredOutfit != null)
		{
			OutfitTool.ToolPurpose purpose = OutfitTool.ToolPurpose.Doffing;
			if (ThisPlayer.IsInChangingRoom)
			{
				purpose = OutfitTool.ToolPurpose.Drawer;
			}
			OutfitTool outfitTool = OutfitTool.Find(ThisPlayer, TriggeredOutfit.OutfitItem.Selection, purpose);
			if (outfitTool != null)
			{
				ThisPlayer.PlayerOutfit.RemoveOutfit(TriggeredOutfit.OutfitItem.Selection, playAudio: true);
				outfitTool.DontCollideWithPlayer(1f);
				outfitTool.CurrentState = OutfitTool.OutfitToolState.InHand;
				outfitTool.transform.position = TriggeredOutfit.transform.position;
				outfitTool.transform.localRotation = TriggeredOutfit.transform.rotation;
				GetToolPickupPositionAndRotation(outfitTool, useGravityPickup: true, Vector3.zero, out handSpacePickupPosition, out handSpacePickupRotation);
				ThisPlayer.ToolController.TryPickupTool(outfitTool, handSpacePickupPosition, handSpacePickupRotation, (int)Type);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Null outfitTool in TryRemoveTriggeredOutfit");
			}
			ControllerIO.HairPickupButtonDownConsumed = true;
			return true;
		}
		return false;
	}

	private void TryPickupHoveredTool()
	{
		if (hoveredTool != null && hoveredTool.IsEnabled)
		{
			Vector3 handSpacePickupPosition = Vector3.zero;
			Quaternion handSpacePickupRotation = Quaternion.identity;
			GetToolPickupPositionAndRotation(hoveredTool, !hoveredToolInPhysicalPickupRange, gravityPickupVector, out handSpacePickupPosition, out handSpacePickupRotation);
			ThisPlayer.ToolController.TryPickupTool(hoveredTool, handSpacePickupPosition, handSpacePickupRotation, (int)Type);
		}
		else
		{
			hoveredTool = null;
		}
	}

	private void OnGameStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		if (ThisPlayer != null)
		{
			OnGameTeamChange();
		}
	}

	private void OnGameTeamChange()
	{
		if (ThisPlayer != null && Tool != null)
		{
			if (Tool.PlayerInteractionRestriction != null && !Tool.PlayerInteractionRestriction.PlayerInteractionAllowed(ThisPlayer.PhotonPlayer))
			{
				ReleaseTool();
			}
			else
			{
				Tool.OnOwnerRoleUpdated();
			}
		}
	}

	public static void ConnectHandshake(PlayerHand lhs, PlayerHand rhs)
	{
		if (!(lhs == null) && !(rhs == null))
		{
			GetGestureHandRoles(lhs, rhs, out var masterHand, out var slaveHand);
			if (slaveHand.rigidbodyPickup.Target != masterHand.rigidbody)
			{
				masterHand.handAnimator.SetBool(handshakeAnimatorId, value: true);
				slaveHand.handAnimator.SetBool(handshakeAnimatorId, value: true);
				Vector3 handSpacePickupPosition = masterHand.transform.InverseTransformPoint(masterHand.handshakeConnectionTransform.position);
				Quaternion handSpacePickupRotation = masterHand.transform.InverseTransformRotation(masterHand.handshakeConnectionTransform.rotation);
				slaveHand.rigidbodyPickup.Pickup(masterHand.rigidbody, handSpacePickupPosition, handSpacePickupRotation);
			}
		}
	}

	public static void BreakHandshake(PlayerHand lhs, PlayerHand rhs)
	{
		if (!(lhs == null) && !(rhs == null))
		{
			GetGestureHandRoles(lhs, rhs, out var masterHand, out var slaveHand);
			masterHand.handAnimator.SetBool(handshakeAnimatorId, value: false);
			slaveHand.handAnimator.SetBool(handshakeAnimatorId, value: false);
			slaveHand.rigidbodyPickup.Release();
		}
	}

	public static void ConnectCollisionGesture(PlayerHandGestures.Gesture gesture, PlayerHand lhs, PlayerHand rhs)
	{
		if (lhs == null || rhs == null)
		{
			return;
		}
		GetGestureHandRoles(lhs, rhs, out var masterHand, out var slaveHand);
		if (slaveHand.rigidbodyPickup.Target != masterHand.rigidbody)
		{
			Transform transform = ((gesture != PlayerHandGestures.Gesture.Fistbump) ? masterHand.highFiveConnectionTransform : masterHand.fistbumpConnectionTransform);
			if (transform == null)
			{
				transform = slaveHand.transform;
			}
			Vector3 handSpacePickupPosition = masterHand.transform.InverseTransformPoint(transform.position);
			Quaternion handSpacePickupRotation = masterHand.transform.InverseTransformRotation(slaveHand.transform.rotation);
			slaveHand.rigidbodyPickup.Pickup(masterHand.rigidbody, handSpacePickupPosition, handSpacePickupRotation);
		}
	}

	public static void BreakCollisionGesture(PlayerHandGestures.Gesture gesture, PlayerHand lhs, PlayerHand rhs)
	{
		if (!(lhs == null) && !(rhs == null))
		{
			GetGestureHandRoles(lhs, rhs, out var _, out var slaveHand);
			slaveHand.rigidbodyPickup.Release();
		}
	}

	private static void GetGestureHandRoles(PlayerHand hand1, PlayerHand hand2, out PlayerHand masterHand, out PlayerHand slaveHand)
	{
		if (hand1.isLocal)
		{
			masterHand = hand1;
			slaveHand = hand2;
		}
		else if (hand2.isLocal)
		{
			masterHand = hand2;
			slaveHand = hand1;
		}
		else if (hand1.photonView.viewID < hand2.photonView.viewID)
		{
			masterHand = hand1;
			slaveHand = hand2;
		}
		else
		{
			masterHand = hand2;
			slaveHand = hand1;
		}
	}

	public static PlayerHand Find(int photonViewId)
	{
		PhotonView photonView = PhotonView.Find(photonViewId);
		if (photonView != null)
		{
			return photonView.GetComponent<PlayerHand>();
		}
		return null;
	}

	private void OnDrawGizmos()
	{
		if (UnityEngine.Application.isPlaying)
		{
			Gizmos.color = Color.green;
			float gravityPickupCapsuleRadius = GravityPickupCapsuleRadius;
			float num = GravityPickupCapsuleLength - 2f * gravityPickupCapsuleRadius;
			int num2 = (int)(num / (2f * gravityPickupCapsuleRadius));
			Vector3 gravityPickupDirection = GravityPickupDirection;
			Vector3 vector = num / (float)num2 * gravityPickupDirection;
			Vector3 vector2 = GravityPickupOrigin + gravityPickupDirection * gravityPickupCapsuleRadius;
			for (int i = 0; i < num2; i++)
			{
				Gizmos.DrawWireSphere(vector2 + i * vector, gravityPickupCapsuleRadius);
			}
			Gizmos.DrawWireSphere(vector2 + num * gravityPickupDirection, gravityPickupCapsuleRadius);
		}
	}
}
public class PlayerHandCollider : PlayerCollider
{
	private BoxCollider boxCollider;

	private Tool heldTool;

	private Tool lastReleasedTool;

	private float timeOfLastContactWithReleasedTool;

	private const float TIME_SINCE_LAST_CONTACT_THRESHOLD = 0.1f;

	private const int MAX_RAYCAST_HIT = 256;

	private static Collider[] hits = new Collider[256];

	private void Update()
	{
		if (lastReleasedTool == null || IsTrigger)
		{
			return;
		}
		Vector3 center = base.transform.TransformPoint(boxCollider.center);
		int num = Physics.OverlapBoxNonAlloc(center, 1.05f * boxCollider.size / 2f, hits, base.transform.rotation, 226894848);
		for (int i = 0; i < num; i++)
		{
			Tool colliderTool = hits[i].GetColliderTool();
			if (colliderTool != null && colliderTool == lastReleasedTool)
			{
				timeOfLastContactWithReleasedTool = Time.unscaledTime;
				break;
			}
		}
		if (Time.unscaledTime - timeOfLastContactWithReleasedTool > 0.1f)
		{
			lastReleasedTool = null;
			boxCollider.enabled = true;
		}
	}

	private void Awake()
	{
		boxCollider = GetComponent<BoxCollider>();
	}

	public void DisableHandToolCollisions(Tool tool)
	{
		if (!IsTrigger && !(tool == heldTool) && !(tool == null))
		{
			heldTool = tool;
			lastReleasedTool = null;
			boxCollider.enabled = false;
		}
	}

	public void ReEnableHandToolCollisions(Tool tool)
	{
		if (IsTrigger || (tool != null && tool == heldTool))
		{
			heldTool = null;
			lastReleasedTool = tool;
			timeOfLastContactWithReleasedTool = Time.unscaledTime;
		}
	}
}
[RequireComponent(typeof(PlayerHand))]
public class PlayerHandGestures : Photon.MonoBehaviour
{
	public enum Gesture
	{
		None = -1,
		Highfive,
		Fistbump,
		HandshakeStart,
		HandshakeCancel,
		HandshakeSuccess
	}

	private enum HandshakeState
	{
		None,
		Ready,
		Waiting,
		Running,
		Finished,
		Broken
	}

	private enum CollisionGestureState
	{
		None,
		Colliding,
		Finished
	}

	public enum ThumbsUpState
	{
		None = -1,
		Started,
		Playing
	}

	private enum ShakeState
	{
		None = -1,
		Tracking,
		Playing
	}

	private float lastGestureTime;

	private float gestureCooldown = 1f;

	[Header("Handshake")]
	[SerializeField]
	private float handshakeCooldown = 1f;

	[SerializeField]
	private float sqrHandshakeDistance = 0.1f;

	[SerializeField]
	private float maxHandshakeDistanceFromOriginSqr = 0.0625f;

	private SynchronizedField<int> _gestureConnectedHandId;

	private SynchronizedField<int> _handshakeStateId;

	[SerializeField]
	private float requiredHandshakeHoldDuration = 2f;

	private float handshakeStartTime;

	private float handshakeBreakTime;

	private Vector3 handshakeStartPosition = Vector3.zero;

	[Header("Collision Gestures")]
	[SerializeField]
	private float minFistBumpSpeed = 1f;

	[SerializeField]
	private float fistbumpDuration = 1f;

	[SerializeField]
	private float fistbumpDistanceThreshold = 0.4f;

	[SerializeField]
	private float fistbumpPullbackDistance = 0.01f;

	[SerializeField]
	private float minHighFiveSpeed = 1f;

	[SerializeField]
	private float highFiveDuration = 1f;

	[SerializeField]
	private float highFiveDistanceThreshold = 0.5f;

	[SerializeField]
	private float highFivePullbackDistance = 0.01f;

	private float collisionGestureDuration = 1f;

	private float collisionGestureDistanceThreshold = 0.4f;

	private float collisionGesturePullBackDistance = 0.01f;

	private float collisionGestureStartTime;

	private Vector3 collisionGestureStartPosition = Vector3.zero;

	private Vector3 collisionGestureDirection = Vector3.zero;

	private Gesture currentCollisionGesture = Gesture.None;

	private SynchronizedField<int> _collisionGestureStateId;

	[Header("Thumbs up")]
	[SerializeField]
	private float thumbsUpDelay = 1f;

	private float thumbsUpDelayStart;

	private float thumbsUpAngleThreshold = 0.85f;

	private SynchronizedField<int> _currentThumbsUpState;

	[SerializeField]
	private float minShakeStartSpeed = 1f;

	[SerializeField]
	private float shakeTravelDistance = 0.1f;

	[SerializeField]
	private float shakeTime = 0.7f;

	[SerializeField]
	private float shakeMaxDisplacement = 0.25f;

	private float shakeStartTime;

	private float distanceTraveled;

	private Vector3 shakeStartPosition = Vector3.zero;

	private Vector3 shakePreviousPosition = Vector3.zero;

	private ShakeState currentShakeState = ShakeState.None;

	private static readonly int rpcGestureHandleTimeoutMiliseconds = 600;

	public PlayerHand Hand { get; private set; }

	private PlayerHand gestureConnectedHand
	{
		get
		{
			PhotonView photonView = PhotonView.Find(_gestureConnectedHandId.Get());
			return (!(photonView != null)) ? null : photonView.GetComponent<PlayerHand>();
		}
		set
		{
			_gestureConnectedHandId.ForceSet(value.photonView.viewID);
		}
	}

	private HandshakeState currentHandshakeState
	{
		get
		{
			return (HandshakeState)_handshakeStateId.Get();
		}
		set
		{
			_handshakeStateId.ForceSet((int)value);
		}
	}

	private CollisionGestureState currentCollisionGestureState
	{
		get
		{
			return (CollisionGestureState)_collisionGestureStateId.Get();
		}
		set
		{
			_collisionGestureStateId.ForceSet((int)value);
		}
	}

	private ThumbsUpState CurrentThumbsUpState
	{
		get
		{
			return (ThumbsUpState)_currentThumbsUpState.Get();
		}
		set
		{
			_currentThumbsUpState.ForceSet((int)value);
		}
	}

	public int LastGestureServerTimestamp { get; private set; }

	public Gesture LastGestureType { get; private set; }

	public event Action<PlayerHand, PlayerHand, Gesture> GestureDetected;

	protected override void Awake()
	{
		base.Awake();
		Hand = GetComponent<PlayerHand>();
		_handshakeStateId = new SynchronizedField<int>(this, "HANDSHAKE_STATE", 0, SetterPermissionMode.AUTHORITY, OnHandshakeStateChange);
		_collisionGestureStateId = new SynchronizedField<int>(this, "COL_GESTURE_STATE", 0, SetterPermissionMode.AUTHORITY, OnCollisionGestureStateChange);
		_currentThumbsUpState = new SynchronizedField<int>(this, "THUMBS_UP_STATE", -1, SetterPermissionMode.AUTHORITY, OnThumbsUpStateChange);
		_gestureConnectedHandId = new SynchronizedField<int>(this, "GESTURE_HAND_ID", -1, SetterPermissionMode.AUTHORITY);
	}

	private void Start()
	{
		OnHandshakeStateChange();
	}

	private void FixedUpdate()
	{
		if (base.isLocal)
		{
			UpdateHandshakeState();
			UpdateCollisionGestureState();
			UpdateThumbsUpState();
			UpdateShakeState();
		}
	}

	private void TryEvaluateRemoteHandGesture(PlayerHand otherHand)
	{
		if (Time.time - lastGestureTime < gestureCooldown || !Hand.IsVisible || !otherHand.IsVisible || Hand.ThisPlayer.IsGhostedOrPermaghosted || otherHand.ThisPlayer.IsGhostedOrPermaghosted || currentHandshakeState != HandshakeState.None)
		{
			return;
		}
		Gesture gesture = Gesture.None;
		Vector3 rhs = Hand.TrackedVelocity.RecentLinearVelocity - otherHand.TrackedVelocity.RecentLinearVelocity;
		if (Hand.OpenClosedAxis >= 0.99f && otherHand.OpenClosedAxis >= 0.99f)
		{
			float num = Vector3.Dot(Hand.transform.forward, otherHand.transform.forward);
			float num2 = Mathf.Abs(Vector3.Dot(Hand.FingerDirection, rhs));
			float num3 = Vector3.Dot(Hand.TrackedVelocity.RecentLinearVelocity, Hand.FingerDirection);
			float num4 = Vector3.Dot(otherHand.TrackedVelocity.RecentLinearVelocity, otherHand.FingerDirection);
			if (num < -0.8f && num2 >= minFistBumpSpeed && num3 >= -0.001f && num4 >= -0.001f)
			{
				StartCollisionGesture(Gesture.Fistbump, otherHand);
			}
		}
		else if (Hand.OpenClosedAxis <= 0.01f && otherHand.OpenClosedAxis <= 0.01f)
		{
			float num5 = Vector3.Dot(Hand.PalmDirection, otherHand.PalmDirection);
			if (num5 < -0.8f)
			{
				float num6 = Mathf.Abs(Vector3.Dot(Hand.PalmDirection, rhs));
				float num7 = Vector3.Dot(Hand.TrackedVelocity.RecentLinearVelocity, Hand.PalmDirection);
				float num8 = Vector3.Dot(otherHand.TrackedVelocity.RecentLinearVelocity, otherHand.PalmDirection);
				if (num6 >= minHighFiveSpeed && num7 >= -0.001f && num8 >= -0.001f)
				{
					StartCollisionGesture(Gesture.Highfive, otherHand);
				}
				else
				{
					float num9 = Vector3.Dot(Hand.FingerDirection, otherHand.FingerDirection);
					if (num9 < -0.6f && Hand.Type == otherHand.Type && (otherHand.Gestures.currentHandshakeState == HandshakeState.None || otherHand.Gestures.currentHandshakeState == HandshakeState.Ready))
					{
						StartHandshake(otherHand);
					}
				}
			}
		}
		if (gesture != Gesture.None)
		{
			lastGestureTime = Time.time;
			base.photonView.RPC("RpcHandGestureDetected", PhotonTargets.All, otherHand.photonView.viewID, (int)gesture, PhotonNetwork.ServerTimestamp);
		}
	}

	private void StartHandshake(PlayerHand otherHand)
	{
		gestureConnectedHand = otherHand;
		currentHandshakeState = HandshakeState.Ready;
	}

	private void RequestHandshakeCompletion()
	{
		base.photonView.RPC("RpcAuthorityRequestHandshakeCompletion", base.authority);
	}

	private void OnHandshakeStateChange()
	{
		if (base.isLocal)
		{
			OnEnterHandshakeState();
		}
		UpdateHandshakeFeedback();
	}

	private void UpdateHandshakeState()
	{
		switch (currentHandshakeState)
		{
		case HandshakeState.Ready:
			UpdateHandshakeReadyState();
			break;
		case HandshakeState.Waiting:
			UpdateHandshakeWaitingState();
			break;
		case HandshakeState.Running:
			UpdateHandshakeRunningState();
			break;
		case HandshakeState.Finished:
			UpdateHandshakeFinishedState();
			break;
		case HandshakeState.Broken:
			UpdateHandshakeBrokenState();
			break;
		case HandshakeState.None:
			break;
		}
	}

	private void OnEnterHandshakeState()
	{
		switch (currentHandshakeState)
		{
		case HandshakeState.Running:
			handshakeStartTime = Time.time;
			handshakeStartPosition = Hand.transform.position;
			if (gestureConnectedHand != null)
			{
				base.photonView.RPC("RpcHandGestureDetected", PhotonTargets.All, gestureConnectedHand.photonView.viewID, 2, PhotonNetwork.ServerTimestamp);
			}
			break;
		case HandshakeState.Broken:
			handshakeBreakTime = Time.time;
			if (gestureConnectedHand != null)
			{
				base.photonView.RPC("RpcHandGestureDetected", PhotonTargets.All, gestureConnectedHand.photonView.viewID, 3, PhotonNetwork.ServerTimestamp);
			}
			break;
		}
	}

	private void UpdateHandshakeFeedback()
	{
		if (currentHandshakeState == HandshakeState.Running || currentHandshakeState == HandshakeState.Finished)
		{
			PlayerHand.ConnectHandshake(Hand, gestureConnectedHand);
			return;
		}
		PlayerHand.BreakHandshake(Hand, gestureConnectedHand);
		Hand.HandshakeAnimationEnabled = currentHandshakeState == HandshakeState.Waiting;
	}

	private void UpdateHandshakeReadyState()
	{
		if (!HandsAreWithinHandshakeRange())
		{
			currentHandshakeState = HandshakeState.None;
		}
		else if (LocalHandIsGrippedForHandshake())
		{
			currentHandshakeState = HandshakeState.Waiting;
		}
	}

	private void UpdateHandshakeWaitingState()
	{
		if (!HandsAreWithinHandshakeRange() || !LocalHandIsGrippedForHandshake())
		{
			currentHandshakeState = HandshakeState.None;
		}
		else if (gestureConnectedHand != null && (RemoteHandIsGrippedForHandshake() || gestureConnectedHand.Gestures.currentHandshakeState == HandshakeState.Running))
		{
			currentHandshakeState = HandshakeState.Running;
		}
	}

	private void UpdateHandshakeRunningState()
	{
		if (gestureConnectedHand != null && (gestureConnectedHand.Gestures.currentHandshakeState == HandshakeState.Finished || Time.time - handshakeStartTime >= requiredHandshakeHoldDuration))
		{
			gestureConnectedHand.Gestures.RequestHandshakeCompletion();
			currentHandshakeState = HandshakeState.Finished;
		}
		else if (HandshakeIsBroken() || gestureConnectedHand.Gestures.currentHandshakeState == HandshakeState.Broken)
		{
			currentHandshakeState = HandshakeState.Broken;
		}
	}

	private void UpdateHandshakeFinishedState()
	{
		if (gestureConnectedHand != null && gestureConnectedHand.Gestures.currentHandshakeState == HandshakeState.Broken)
		{
			currentHandshakeState = HandshakeState.Broken;
		}
		else if (HandshakeIsBroken())
		{
			currentHandshakeState = HandshakeState.None;
		}
	}

	private void UpdateHandshakeBrokenState()
	{
		if (Time.time - handshakeBreakTime >= handshakeCooldown)
		{
			currentHandshakeState = HandshakeState.None;
		}
	}

	private bool HandshakeIsBroken()
	{
		return gestureConnectedHand == null || !LocalHandIsGrippedForHandshake() || !HandNearHandshakeOrigin();
	}

	private bool HandsAreWithinHandshakeRange()
	{
		bool result = false;
		if (gestureConnectedHand != null)
		{
			float num = Vector3.Dot(Hand.PalmDirection, gestureConnectedHand.PalmDirection);
			float num2 = Vector3.Dot(Hand.FingerDirection, gestureConnectedHand.FingerDirection);
			float sqrMagnitude = (Hand.transform.position - gestureConnectedHand.transform.position).sqrMagnitude;
			result = (sqrMagnitude <= sqrHandshakeDistance && num <= -0.8f) || num2 <= -0.4f;
		}
		return result;
	}

	private bool HandNearHandshakeOrigin()
	{
		return (Hand.transform.position - handshakeStartPosition).sqrMagnitude <= maxHandshakeDistanceFromOriginSqr;
	}

	private bool LocalHandIsGrippedForHandshake()
	{
		return Hand != null && Hand.OpenClosedAxis > 0.01f;
	}

	private bool RemoteHandIsGrippedForHandshake()
	{
		return gestureConnectedHand != null && gestureConnectedHand.OpenClosedAxis > 0.01f;
	}

	[PunRPC]
	private void RpcAuthorityRequestHandshakeCompletion()
	{
		if (gestureConnectedHand != null && currentHandshakeState != HandshakeState.Broken)
		{
			lastGestureTime = Time.time;
			base.photonView.RPC("RpcHandGestureDetected", PhotonTargets.All, gestureConnectedHand.photonView.viewID, 4, PhotonNetwork.ServerTimestamp);
		}
	}

	private void StartCollisionGesture(Gesture gestureType, PlayerHand otherHand)
	{
		if (currentCollisionGesture == Gesture.None)
		{
			currentCollisionGesture = gestureType;
			gestureConnectedHand = otherHand;
			currentCollisionGestureState = CollisionGestureState.Colliding;
		}
	}

	private void OnCollisionGestureStateChange()
	{
		if (base.isLocal)
		{
			OnEnterCollisionGestureState();
		}
		UpdateCollisionGestureFeedback();
	}

	private void UpdateCollisionGestureState()
	{
		CollisionGestureState collisionGestureState = currentCollisionGestureState;
		if (collisionGestureState == CollisionGestureState.Colliding && (Time.time - collisionGestureStartTime > collisionGestureDuration || !HandNearCollisionGestureOrigin() || !HandInCorrectStateForCollisionGesture()))
		{
			currentCollisionGestureState = CollisionGestureState.Finished;
		}
	}

	private void OnEnterCollisionGestureState()
	{
		switch (currentCollisionGestureState)
		{
		case CollisionGestureState.Colliding:
			collisionGestureStartTime = Time.time;
			collisionGestureStartPosition = Hand.transform.position;
			if (currentCollisionGesture == Gesture.Fistbump)
			{
				collisionGestureDirection = Hand.FingerDirection;
				collisionGestureDuration = fistbumpDuration;
				collisionGestureDistanceThreshold = fistbumpDistanceThreshold;
				collisionGesturePullBackDistance = fistbumpPullbackDistance;
			}
			else
			{
				collisionGestureDirection = Hand.PalmDirection;
				collisionGestureDuration = highFiveDuration;
				collisionGestureDistanceThreshold = highFiveDistanceThreshold;
				collisionGesturePullBackDistance = highFivePullbackDistance;
			}
			if (gestureConnectedHand != null)
			{
				lastGestureTime = Time.time;
				base.photonView.RPC("RpcHandGestureDetected", PhotonTargets.All, gestureConnectedHand.photonView.viewID, (int)currentCollisionGesture, PhotonNetwork.ServerTimestamp);
			}
			break;
		case CollisionGestureState.Finished:
			currentCollisionGesture = Gesture.None;
			currentCollisionGestureState = CollisionGestureState.None;
			break;
		}
	}

	private void UpdateCollisionGestureFeedback()
	{
		if (currentCollisionGestureState == CollisionGestureState.Colliding)
		{
			PlayerHand.ConnectCollisionGesture(currentCollisionGesture, Hand, gestureConnectedHand);
		}
		else
		{
			PlayerHand.BreakCollisionGesture(currentCollisionGesture, Hand, gestureConnectedHand);
		}
	}

	private bool HandNearCollisionGestureOrigin()
	{
		bool flag = (Hand.transform.position - collisionGestureStartPosition).sqrMagnitude <= collisionGestureDistanceThreshold * collisionGestureDistanceThreshold;
		bool flag2 = Vector3.Dot(Hand.transform.position - collisionGestureStartPosition, -collisionGestureDirection) <= collisionGesturePullBackDistance;
		return flag && flag2;
	}

	private bool HandInCorrectStateForCollisionGesture()
	{
		bool result = false;
		switch (currentCollisionGesture)
		{
		case Gesture.Fistbump:
			result = Hand.OpenClosedAxis >= 0.99f;
			break;
		case Gesture.Highfive:
			result = Hand.OpenClosedAxis <= 0.01f;
			break;
		}
		return result;
	}

	private void UpdateThumbsUpState()
	{
		if (!base.isLocal)
		{
			return;
		}
		switch (CurrentThumbsUpState)
		{
		case ThumbsUpState.None:
			if (ThumbsUpStartConditions())
			{
				thumbsUpDelayStart = Time.time;
				CurrentThumbsUpState = ThumbsUpState.Started;
			}
			break;
		case ThumbsUpState.Started:
			if (ThumbsUpStartConditions())
			{
				if (Time.time - thumbsUpDelayStart >= thumbsUpDelay)
				{
					CurrentThumbsUpState = ThumbsUpState.Playing;
				}
			}
			else
			{
				CurrentThumbsUpState = ThumbsUpState.None;
			}
			break;
		case ThumbsUpState.Playing:
			if (ThumbsUpEndConditions())
			{
				thumbsUpDelayStart = 0f;
				CurrentThumbsUpState = ThumbsUpState.None;
			}
			break;
		}
	}

	private void OnThumbsUpStateChange()
	{
		switch (CurrentThumbsUpState)
		{
		case ThumbsUpState.None:
			Hand.ThumbsUpAnimationEnabled = false;
			break;
		case ThumbsUpState.Playing:
			Hand.ThumbsUpAnimationEnabled = true;
			break;
		}
	}

	private bool ThumbsUpStartConditions()
	{
		return currentHandshakeState == HandshakeState.None && currentCollisionGesture == Gesture.None && Hand.OpenClosedAxis >= 0.99f && Mathf.Abs(Vector3.Dot(Hand.ThumbDirection, Vector3.up)) >= thumbsUpAngleThreshold;
	}

	private bool ThumbsUpEndConditions()
	{
		return currentHandshakeState != HandshakeState.None || currentCollisionGesture != Gesture.None || Hand.OpenClosedAxis < 0.99f;
	}

	private void UpdateShakeState()
	{
		switch (currentShakeState)
		{
		case ShakeState.None:
			if (Hand.TrackedVelocity.RecentLinearVelocity.sqrMagnitude >= minShakeStartSpeed * minShakeStartSpeed)
			{
				currentShakeState = ShakeState.Tracking;
				distanceTraveled = 0f;
				shakeStartPosition = Hand.transform.position;
				shakePreviousPosition = shakeStartPosition;
				shakeStartTime = Time.time;
			}
			break;
		case ShakeState.Tracking:
			if (Time.time - shakeStartTime < shakeTime)
			{
				if ((Hand.transform.position - shakeStartPosition).sqrMagnitude < shakeMaxDisplacement * shakeMaxDisplacement)
				{
					distanceTraveled += (Hand.transform.position - shakePreviousPosition).sqrMagnitude;
					shakePreviousPosition = Hand.transform.position;
				}
				else
				{
					currentShakeState = ShakeState.None;
				}
			}
			else if (distanceTraveled >= shakeTravelDistance * shakeTravelDistance)
			{
				currentShakeState = ShakeState.Playing;
			}
			else
			{
				currentShakeState = ShakeState.None;
			}
			break;
		case ShakeState.Playing:
			if (Hand.Tool != null)
			{
				Hand.Tool.OnShake();
			}
			currentShakeState = ShakeState.None;
			break;
		}
	}

	private void OnTriggerEnter(Collider col)
	{
		TriggerAction(col, enter: true);
	}

	private void OnTriggerExit(Collider col)
	{
		TriggerAction(col, enter: false);
	}

	private void TriggerAction(Collider col, bool enter)
	{
		if (!enter || !base.isLocal)
		{
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = col.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && !colliderPlayer.isLocal && bodyPart.IsHand())
		{
			PlayerHand hand = colliderPlayer.GetHand(bodyPart);
			if (hand != null)
			{
				TryEvaluateRemoteHandGesture(hand);
			}
		}
	}

	[PunRPC]
	public void RpcHandGestureDetected(int otherHandViewId, int gesture, int serverTimeMiliseconds)
	{
		PlayerHand playerHand = PlayerHand.Find(otherHandViewId);
		if (playerHand != null)
		{
			if (playerHand.photonView.owner.isLocal)
			{
				playerHand.Gestures.HandleHandGestureDetected(Hand, (Gesture)gesture, serverTimeMiliseconds);
			}
			else
			{
				HandleHandGestureDetected(playerHand, (Gesture)gesture, serverTimeMiliseconds);
			}
		}
	}

	public void HandleHandGestureDetected(PlayerHand otherHand, Gesture gesture, int serverTimeMiliseconds)
	{
		if ((otherHand.Gestures.LastGestureServerTimestamp == 0 || otherHand.Gestures.LastGestureType != gesture || Math.Abs(otherHand.Gestures.LastGestureServerTimestamp - serverTimeMiliseconds) >= rpcGestureHandleTimeoutMiliseconds) && (LastGestureServerTimestamp == 0 || LastGestureType != gesture || Math.Abs(LastGestureServerTimestamp - serverTimeMiliseconds) >= rpcGestureHandleTimeoutMiliseconds))
		{
			LastGestureServerTimestamp = serverTimeMiliseconds;
			LastGestureType = gesture;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Hand, otherHand, gesture);
			}
		}
	}
}
public class PlayerHandRigidbodyPickup : RigidbodyPickup
{
	public override void Pickup(Rigidbody hand, Vector3 handSpacePickupPosition, Quaternion handSpacePickupRotation)
	{
		Release();
		pickupHand = hand;
		localPickupPosition = handSpacePickupPosition;
		localPickupRotation = handSpacePickupRotation;
		if (networkTransform != null)
		{
			networkTransform.SynchronizationEnabled = base.hasAuthority;
		}
		StartAttachToHandCoroutine();
	}

	public override void Release()
	{
		pickupHand = null;
		localPickupPosition = Vector3.zero;
		localPickupRotation = Quaternion.identity;
		if (networkTransform != null)
		{
			networkTransform.SynchronizationEnabled = true;
			if (!base.hasAuthority)
			{
				networkTransform.StartDynamicTimeExtrapolation();
			}
		}
		ClearAttachToHandCoroutine();
	}
}
