	public bool TeleportSuppressed => (thisPlayer.LeftHand != null && thisPlayer.LeftHand.Tool != null && thisPlayer.LeftHand.Tool.SuppressesTeleport) || (thisPlayer.RightHand != null && thisPlayer.RightHand.Tool != null && thisPlayer.RightHand.Tool.SuppressesTeleport);

