	protected override void Awake()
	{
		base.Awake();
		PreparingToTeleport = false;
		TeleportOnCooldown = false;
		TeleportCooldownValue = 0f;
		TeleportEnabled = true;
		JustTeleported = false;
		JustHitToolWithTeleport = false;
		lastTeleportTime = 0f;
		lastTeleportEnabledTime = 0f;
		thisPlayer = GetComponent<Player>();
		childNetworkTransforms = GetComponentsInChildren<PUNNetworkTransform>(includeInactive: true);
		trail = UnityEngine.Object.Instantiate(playerTrailPrefab);
		thisPlayer.SetParentPlayerRoot(trail.transform);
		AddTeleportCooldown(TeleportCooldownType.DEFAULT, 0f);
		PushTeleportMaxDistanceScalar(1f);
		PushMaxToolHitHoldTime(defaultMaxToolHitHoldTime);
		continuousRotationIsRunning = false;
	}

	private void Start()
	{
		if (thisPlayer.isLocal)
		{
			TeleportBuffer = SingletonMonoBehaviour<SettingsManager>.Instance.TeleportBuffer;
			MotionTeleportEnabled = SingletonMonoBehaviour<SettingsManager>.Instance.MotionTeleportEnabled;
			RotateInPlaceEnabled = SingletonMonoBehaviour<SettingsManager>.Instance.RotateInPlaceEnabled;
			RotateInPlaceIncrement = SingletonMonoBehaviour<SettingsManager>.Instance.RotationIncrement;
			ContinuousRotationMode = SingletonMonoBehaviour<SettingsManager>.Instance.ContinuousRotationMode;
		}
	}

	private void FixedUpdate()
	{
		UpdateTeleportCooldown();
	}

	public void Translate(Vector3 velocity)
	{
		TranslateCameraRig(SingletonMonoBehaviour<CameraRig>.Instance.transform.position + velocity * Time.deltaTime, SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation);
	}

	public void Translate(Vector3 rigPosition, Quaternion rigRotation)
	{
		TranslateCameraRig(rigPosition, rigRotation);
	}

	public void TeleportTo(Vector3 destinationPlayerPosition, bool hasRotation, Vector3 rotationForward, TeleportationPortal portal, Tool hitTool, Vector3 hitToolPoint, Vector3 hitToolDirection)
	{
		PreparingToTeleport = false;
		Vector3 currentFloorPosition = thisPlayer.CurrentFloorPosition;
		if (teleportCoroutine != null)
		{
			return;
		}
		if (portal != null)
		{
			if (portal.SupportsActivityLoading && RecRoomSceneManager.Instance != null)
			{
				if (thisPlayer.PlayerParty.PartySize > 1)
				{
					thisPlayer.PlayerUI.Menu.RunSwitchActivity(portal.DestinationActivity, createPrivateRoom: false);
				}
				else
				{
					RecRoomSceneManager.Instance.SwitchActivity(portal.DestinationActivity, createPrivateRoom: false);
				}
				return;
			}
			if (portal.SupportsPlayerRespawn && RecRoomSceneManager.Instance != null && RecRoomSceneManager.Instance.GameManager != null)
			{
				RecRoomSceneManager.Instance.GameManager.SpawnManager.LocalPlayerRequestRespawn(!portal.CanCarryTools);
				return;
			}
			if (!portal.CanCarryTools)
			{
				thisPlayer.ReleaseToolsFromBothHands();
			}
		}
		if (thisPlayer.LeftHand.Tool != null)
		{
			thisPlayer.LeftHand.Tool.OnPlayerTeleport(teleportBlindDuration);
		}
		if (thisPlayer.RightHand.Tool != null)
		{
			thisPlayer.RightHand.Tool.OnPlayerTeleport(teleportBlindDuration);
		}
		teleportCoroutine = StartCoroutine(RunTeleportTo(currentFloorPosition, destinationPlayerPosition, hasRotation, rotationForward, teleportBlindDuration, portal, hitTool, hitToolPoint, hitToolDirection));
		thisPlayer.PlayerAudio.OnTeleport();
		if (thisPlayer.IsVisible)
		{
			base.photonView.RPC("RpcTeleport", PhotonTargets.Others, currentFloorPosition, (!(portal != null)) ? destinationPlayerPosition : portal.transform.position);
		}
		if (thisPlayer.PlayerUI.Menu != null && thisPlayer.PlayerUI.Menu.Visible)
		{
			thisPlayer.PlayerUI.Menu.Visible = false;
		}
		lastTeleportTime = Time.time;
		JustTeleported = true;
		JustHitToolWithTeleport = hitTool != null;
	}

	private void RunRotateTeleport(float rotationAngle, float duration)
	{
		if (rotateTeleportCoroutine != null)
		{
			StopCoroutine(rotateTeleportCoroutine);
			rotateTeleportCoroutine = null;
		}
		rotateTeleportCoroutine = StartCoroutine(RotateTeleportCoroutine(rotationAngle, duration));
	}

	private IEnumerator RotateTeleportCoroutine(float angle, float duration)
	{
		SingletonMonoBehaviour<CameraRig>.Instance.VignetteImageEffect.FadeIn(vignetteRotateFadeInTime);
		Vector3 startingForward = Vector3.ProjectOnPlane(thisPlayer.Head.transform.forward, Vector3.up);
		Quaternion rotation = Quaternion.Euler(0f, angle, 0f);
		for (float timer = 0f; timer <= duration; timer += Time.deltaTime)
		{
			MoveCameraRig(forward: Quaternion.Slerp(Quaternion.identity, rotation, timer / duration) * startingForward, playerFloorPosition: thisPlayer.CurrentFloorPosition, insertDiscontinuity: false);
			yield return null;
		}
		MoveCameraRig(thisPlayer.CurrentFloorPosition, rotation * startingForward, insertDiscontinuity: false);
		SingletonMonoBehaviour<CameraRig>.Instance.VignetteImageEffect.FadeOut(vignetteRotateFadeOutTime);
	}

	public void Rotate(Vector3 playerForward)
	{
		playerForward = Vector3.ProjectOnPlane(playerForward, Vector3.up);
		Quaternion rotation = Quaternion.Euler(0f, SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation).eulerAngles.y, 0f);
		Quaternion rigRotation = Quaternion.LookRotation(playerForward, Vector3.up) * Quaternion.Inverse(rotation);
		Rotate(rigRotation);
	}

	public void Rotate(Quaternion rigRotation)
	{
		TranslateCameraRig(SingletonMonoBehaviour<CameraRig>.Instance.transform.position, rigRotation);
	}

	public void OnTeleportError()
	{
		thisPlayer.PlayerAudio.OnTeleportError();
	}

	public void RotateInPlaceLeft()
	{
		if (TryRotateInPlace(0f - RotateInPlaceAngle, inPlaceRotationSpeed))
		{
			thisPlayer.PlayerAudio.OnInPlaceRotateLeft();
			lastInPlaceRotationDirection = 1f;
		}
	}

	public void RotateInPlaceRight()
	{
		if (TryRotateInPlace(RotateInPlaceAngle, inPlaceRotationSpeed))
		{
			thisPlayer.PlayerAudio.OnInPlaceRotateRight();
			lastInPlaceRotationDirection = -1f;
		}
	}

	public void RotateInPlace180()
	{
		if (TryRotateInPlace(180f * lastInPlaceRotationDirection, inPlaceRotationSpeed))
		{
			thisPlayer.PlayerAudio.OnInPlaceRotate180();
		}
	}

	public void StartContinuousRotation()
	{
		if (!continuousRotationIsRunning)
		{
			initialContinuousRotationForward = Vector3.ProjectOnPlane(thisPlayer.transform.forward, Vector3.up).normalized;
			SingletonMonoBehaviour<CameraRig>.Instance.VignetteImageEffect.FadeIn(vignetteContinuousRotationFadeInTime, continuousRotationVignetteIntensity);
		}
		continuousRotationIsRunning = true;
	}

	public void StopContinuousRotation()
	{
		if (continuousRotationIsRunning)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.VignetteImageEffect.FadeOut(vignetteContinuousRotationFadeOutTime);
		}
		continuousRotationIsRunning = false;
	}

	public void AddContinuousRotation(float deltaAngle)
	{
		if (continuousRotationIsRunning)
		{
			Vector3 normalized = Vector3.ProjectOnPlane(thisPlayer.transform.forward, Vector3.up).normalized;
			MoveCameraRig(thisPlayer.CurrentFloorPosition, Quaternion.Euler(0f, deltaAngle, 0f) * normalized, insertDiscontinuity: false, CoordinateSpace.TRACKING_SPACE);
		}
	}

	public void SetContinuousRotation(float angle)
	{
		if (continuousRotationIsRunning)
		{
			MoveCameraRig(thisPlayer.CurrentFloorPosition, Quaternion.Euler(0f, angle, 0f) * initialContinuousRotationForward, insertDiscontinuity: false, CoordinateSpace.TRACKING_SPACE);
		}
	}

	private bool TryRotateInPlace(float angle, float speed)
	{
		if (continuousRotationIsRunning || (PlatformManager.Instance.CurrentTrackingMode == PlatformManager.TrackingMode.THREE_SIXTY_DEGREE && !RotateInPlaceEnabled))
		{
			return false;
		}
		float duration = Mathf.Abs(angle) / speed;
		bool flag = true;
		flag &= thisPlayer.LeftHand.Tool == null || thisPlayer.LeftHand.Tool.OnPlayerTryingToRotateInPlace(angle, duration);
		flag &= thisPlayer.RightHand.Tool == null || thisPlayer.RightHand.Tool.OnPlayerTryingToRotateInPlace(angle, duration);
		if (flag)
		{
			RunRotateTeleport(angle, duration);
		}
		return flag;
	}

	public void MoveCameraRig(Vector3 playerFloorPosition, bool insertDiscontinuity = true)
	{
		MoveCameraRig(playerFloorPosition, SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.forward, insertDiscontinuity);
	}

	public void MoveCameraRig(Vector3 playerFloorPosition, Vector3 forward, bool insertDiscontinuity = true, CoordinateSpace forwardVectorCoordinateSpace = CoordinateSpace.PLAYER_SPACE)
	{
		forward = Vector3.ProjectOnPlane(forward, Vector3.up);
		Quaternion quaternion = Quaternion.identity;
		switch (forwardVectorCoordinateSpace)
		{
		case CoordinateSpace.PLAYER_SPACE:
		{
			Quaternion rotation = Quaternion.Euler(0f, SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation).eulerAngles.y, 0f);
			quaternion = Quaternion.LookRotation(forward, Vector3.up) * Quaternion.Inverse(rotation);
			break;
		}
		case CoordinateSpace.TRACKING_SPACE:
			quaternion = Quaternion.LookRotation(forward, Vector3.up);
			break;
		}
		Vector3 position = playerFloorPosition - quaternion * SingletonMonoBehaviour<CameraRig>.Instance.CameraFloorOffsetLocalSpace;
		TranslateCameraRig(position, quaternion);
		if (insertDiscontinuity)
		{
			PUNNetworkTransform[] array = childNetworkTransforms;
			foreach (PUNNetworkTransform pUNNetworkTransform in array)
			{
				pUNNetworkTransform.InsertPositionDiscontinuity();
			}
			if (thisPlayer.LeftHand.Tool != null)
			{
				thisPlayer.LeftHand.Tool.SnapToHand();
			}
			if (thisPlayer.RightHand.Tool != null)
			{
				thisPlayer.RightHand.Tool.SnapToHand();
			}
		}
	}

	private void TranslateCameraRig(Vector3 position, Quaternion rotation)
	{
		position = position.ValueOrZeroIfBogus();
		rotation = rotation.ValueOrIdentityIfBogus();
		Vector3 position2 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position);
		Vector3 position3 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(SingletonMonoBehaviour<CameraRig>.Instance.LeftHandControllerIO.transform.position);
		Vector3 position4 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(SingletonMonoBehaviour<CameraRig>.Instance.RightHandControllerIO.transform.position);
		Quaternion rotation2 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation);
		Quaternion rotation3 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.LeftHandControllerIO.transform.rotation);
		Quaternion rotation4 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.RightHandControllerIO.transform.rotation);
		SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation = rotation;
		SingletonMonoBehaviour<CameraRig>.Instance.transform.position = position;
		base.transform.position = position;
		base.transform.rotation = rotation;
		SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.transform.TransformPoint(position2);
		SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.transform.TransformRotation(rotation2);
		thisPlayer.Head.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
		thisPlayer.Head.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation;
		SingletonMonoBehaviour<CameraRig>.Instance.LeftHandControllerIO.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.transform.TransformPoint(position3);
		SingletonMonoBehaviour<CameraRig>.Instance.LeftHandControllerIO.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.transform.TransformRotation(rotation3);
		thisPlayer.LeftHand.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.LeftHandControllerIO.transform.position;
		thisPlayer.LeftHand.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.LeftHandControllerIO.transform.rotation;
		if (thisPlayer.LeftHand.Tool != null)
		{
			thisPlayer.LeftHand.Tool.RigidbodyPickup.InstantaneousUpdate();
		}
		SingletonMonoBehaviour<CameraRig>.Instance.RightHandControllerIO.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.transform.TransformPoint(position4);
		SingletonMonoBehaviour<CameraRig>.Instance.RightHandControllerIO.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.transform.TransformRotation(rotation4);
		thisPlayer.RightHand.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.RightHandControllerIO.transform.position;
		thisPlayer.RightHand.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.RightHandControllerIO.transform.rotation;
		if (thisPlayer.RightHand.Tool != null)
		{
			thisPlayer.RightHand.Tool.RigidbodyPickup.InstantaneousUpdate();
		}
	}

	private float GetChargeAmount(float maxTime)
	{
		return Mathf.Clamp01((Time.time - lastTeleportEnabledTime) / maxTime);
	}

	private void UpdateTeleportCooldown()
	{
		if (TeleportCooldown == 0f)
		{
			TeleportCooldownValue = 1f;
		}
		else
		{
			TeleportCooldownValue = Mathf.Clamp01((Time.time - lastTeleportTime) / TeleportCooldown);
		}
		TeleportOnCooldown = TeleportCooldownValue < 1f;
	}

	public IEnumerator RunTeleportTo(Vector3 sourcePlayerPosition, Vector3 destinationPlayerPosition, bool hasRotation, Vector3 rotationForward, float duration, TeleportationPortal portal, Tool hitTool, Vector3 hitToolPoint, Vector3 hitToolDirection)
	{
		if (portal != null)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.Blind = true;
			CoordinateSpace portalTeleportRotationCoordinateSpace = CoordinateSpace.PLAYER_SPACE;
			if (PlatformManager.Instance.CurrentTrackingMode == PlatformManager.TrackingMode.ONE_EIGHTY_DEGREE)
			{
				portalTeleportRotationCoordinateSpace = CoordinateSpace.TRACKING_SPACE;
			}
			Vector3 newForward = Vector3.ProjectOnPlane((!portal.TargetRotationOverride.HasValue) ? portal.Target.forward : (portal.TargetRotationOverride.Value * Vector3.forward), Vector3.up);
			MoveCameraRig(destinationPlayerPosition, newForward, insertDiscontinuity: true, portalTeleportRotationCoordinateSpace);
			yield return new WaitForSeconds(duration);
			SingletonMonoBehaviour<CameraRig>.Instance.Blind = false;
		}
		else if (!MotionTeleportEnabled || hasRotation)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.Blind = true;
			if (hasRotation)
			{
				MoveCameraRig(destinationPlayerPosition, Vector3.ProjectOnPlane(rotationForward, Vector3.up).normalized);
			}
			else
			{
				MoveCameraRig(destinationPlayerPosition);
			}
			yield return new WaitForSeconds(duration);
			SingletonMonoBehaviour<CameraRig>.Instance.Blind = false;
		}
		else
		{
			SingletonMonoBehaviour<CameraRig>.Instance.VignetteImageEffect.FadeIn(vignetteTeleportFadeInTime);
			for (float timer = 0f; timer <= duration; timer += Time.deltaTime)
			{
				Vector3 currentPlayerPosition = Vector3.Lerp(sourcePlayerPosition, destinationPlayerPosition, Mathf.Clamp01(timer / duration));
				MoveCameraRig(currentPlayerPosition, insertDiscontinuity: false);
				yield return null;
			}
			MoveCameraRig(destinationPlayerPosition);
			SingletonMonoBehaviour<CameraRig>.Instance.VignetteImageEffect.FadeOut(vignetteTeleportFadeOutTime);
		}
		PlayTeleportTrail(sourcePlayerPosition, destinationPlayerPosition);
		if (hitTool != null)
		{
			float num = toolHitForceCurve.Evaluate(ChargeAmount);
			hitTool.ApplyForce(hitToolPoint, hitToolDirection * num, IsMaxToolHitHoldTimeImproved);
		}
		FireTeleportEvent(sourcePlayerPosition, destinationPlayerPosition, portal);
		teleportCoroutine = null;
	}

	[PunRPC]
	public void RpcTeleport(Vector3 sourceFloorPosition, Vector3 destinationFloorPosition)
	{
		if (thisPlayer.IsVisible)
		{
			thisPlayer.PlayerAudio.OnTeleport();
			PlayTeleportTrail(sourceFloorPosition, destinationFloorPosition);
			FireTeleportEvent(sourceFloorPosition, destinationFloorPosition, null);
		}
	}

	private void FireTeleportEvent(Vector3 sourcePosition, Vector3 destinationPosition, TeleportationPortal portal)
	{
		if (this.TeleportEvent != null)
		{
			this.TeleportEvent(thisPlayer, sourcePosition, destinationPosition, portal);
		}
		if (portal != null)
		{
			portal.FirePlayerUseEvent(thisPlayer);
		}
		thisPlayer.PlayerEvents.Teleport();
	}

	private void PlayTeleportTrail(Vector3 sourcePosition, Vector3 destinationPosition)
	{
		GameTeam team = thisPlayer.Team;
		if (team != GameTeam.INVALID)
		{
			trail.Color = GameTeamSettings.GetTeamColor(team);
		}
		trail.PlayTeleportTrail(thisPlayer.Head.HeightOffset, sourcePosition, destinationPosition);
	}

	public void OnPlayerDespawn()
	{
		trail.Clear();
	}
}
public class PlayerModeration : Photon.MonoBehaviour
{
	[Serializable]
	public class VTKPunishmentBucket : IComparable<VTKPunishmentBucket>
	{
		public string name;

		[Tooltip("If you got kicked is equal or below this many times, you deserve this punishment")]
		public int MinOffenseCount;

		[SerializeField]
		private int seconds;

		[Tooltip("If you are a guest you may get different penalties for repeat offense")]
		[SerializeField]
		private float guestMultiplier = 1f;

		[Tooltip("We may change the ease of kicking you out, based on the punishment bucket.")]
		[Range(0.01f, 1f)]
		public float MinVoteToKickPlayerPercentModifier = 1f;

		public int GetDuration(Player player)
		{
			return Mathf.CeilToInt((float)seconds * ((!player.PlayerProgression.IsMember) ? guestMultiplier : 1f));
		}

		public int CompareTo(VTKPunishmentBucket other)
		{
			return MinOffenseCount.CompareTo(other.MinOffenseCount);
		}
	}

	[Range(0f, 1f)]
	[SerializeField]
	private float minVoteToKickPlayerPercent = 0.85f;

	[SerializeField]
	private float minVoteToKickPlayerCount = 4f;

	[SerializeField]
	[EnumFlags]
	private PlayerMenu.NotificationEffectFlag vtkMenuNotificationEffectFlag = (PlayerMenu.NotificationEffectFlag)(-1);

	[SerializeField]
	private List<VTKPunishmentBucket> vtkPunishmentBuckets;

	[Tooltip("How long should we keep the current votes towards a kick? (in seconds)")]
	[SerializeField]
	private float vtkActiveDuration = 30f;

	private float vtkExpireTime;

	private VTKPunishmentBucket currentVTKPunishmentBucket;

	private Dictionary<PhotonPlayer, float> voteToKickMap = new Dictionary<PhotonPlayer, float>();

	private Player thisPlayer;

	public const string VOTE_TO_KICK_COUNT_PREF = "VoteToKickCount";

	private ConfirmationMenuController modVtkConfirmMenu;

	private static float positiveKarmaSeconds;

	private const float PositiveKarmaUpdateInteval = 300f;

	private List<PhotonPlayer> vtkRequestSentPlayers = new List<PhotonPlayer>();

	public float VoteToKickCount
	{
		get
		{
			return thisPlayer.PlayerData.GetData("VoteToKickCount", 0f);
		}
		private set
		{
			thisPlayer.PlayerData.SetData("VoteToKickCount", value);
			if (!(value > 0f) || !((float)PhotonNetwork.playerList.Length > minVoteToKickPlayerCount))
			{
				return;
			}
			float num = value / (float)(PhotonNetwork.playerList.Length - 1);
			if (num >= LocalMinVoteToKickPlayerPercent)
			{
				if (SessionManager.IsDeveloper)
				{
					modVtkConfirmMenu = Player.LocalPlayer.PlayerUI.Menu.ShowConfirmation("Vote to kick?", "You are being vote kicked, do you accept this punishment?", "Kick me :(", "Oh, Hell no!", vtkMenuNotificationEffectFlag, "Vote to kick request!");
					modVtkConfirmMenu.ConfirmAction += OnModVTKConfirmed;
				}
				else
				{
					LocalKickUser(LocalGetUserBlockDuration(), PhotonNetwork.playerList.Length, num, broadcastKick: true);
				}
			}
		}
	}

	private float LocalMinVoteToKickPlayerPercent => minVoteToKickPlayerPercent * currentVTKPunishmentBucket.MinVoteToKickPlayerPercentModifier;

	public bool IsVotedForKick { get; private set; }

	public bool VoteKickHappened { get; set; }

	private void OnModVTKConfirmed(ConfirmationMenuController menuController)
	{
		if (modVtkConfirmMenu != null)
		{
			modVtkConfirmMenu.ConfirmAction -= OnModVTKConfirmed;
			if (Player.LocalPlayer != null && modVtkConfirmMenu.Confirm == true)
			{
				LocalKickUser(LocalGetUserBlockDuration(), PhotonNetwork.playerList.Length, VoteToKickCount / (float)(PhotonNetwork.playerList.Length - 1), broadcastKick: true);
			}
			modVtkConfirmMenu = null;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		thisPlayer = GetComponent<Player>();
	}

	protected void Start()
	{
		VoteToKickCount = 0f;
		LocalCreateVTKPunishmentBucket();
	}

	private void Update()
	{
		if (!base.isLocal)
		{
			return;
		}
		if (!PUNNetworkManager.Instance.IsActivityInviteOnly && PhotonNetwork.playerList.Length > 1)
		{
			positiveKarmaSeconds += Time.unscaledDeltaTime;
			if (positiveKarmaSeconds >= 300f)
			{
				positiveKarmaSeconds -= 300f;
				Profiles.UpdateLocalProfileKarma(300f);
			}
		}
		if (VoteToKickCount > 0f && Time.time > vtkExpireTime)
		{
			LocalResetVTK();
		}
	}

	private void LocalResetVTK()
	{
		if (base.isLocal)
		{
			VoteToKickCount = 0f;
			voteToKickMap.Clear();
			vtkRequestSentPlayers.Clear();
			base.photonView.RPC("RpcModerationBroadcastVTKReset", PhotonTargets.Others);
		}
	}

	private void LocalCreateVTKPunishmentBucket()
	{
		if (!base.isLocal)
		{
			return;
		}
		vtkPunishmentBuckets.Sort();
		int num = -Profiles.LocalProfile.Reputation;
		currentVTKPunishmentBucket = null;
		for (int i = 0; i < vtkPunishmentBuckets.Count; i++)
		{
			if (num <= vtkPunishmentBuckets[i].MinOffenseCount)
			{
				currentVTKPunishmentBucket = vtkPunishmentBuckets[i];
				break;
			}
		}
		if (currentVTKPunishmentBucket == null)
		{
			UnityEngine.Debug.LogWarning("Missing a VTK punishment bucket for reputation : " + num + ". Getting the closest punishment instead.");
			currentVTKPunishmentBucket = vtkPunishmentBuckets.LastItem();
		}
	}

	public void KickPlayer(int duration = 0)
	{
		base.photonView.RPC("RpcModeratorKickPlayer", thisPlayer.PhotonPlayer, duration);
	}

	public void ShowWarningMessage(string title, string subtitle, float duration, float scale)
	{
		base.photonView.RPC("RpcModeratorShowWarning", thisPlayer.PhotonPlayer, title, subtitle, duration, scale);
	}

	[PunRPC]
	public void RpcModeratorShowWarning(string title, string subtitle, float duration, float scale)
	{
		MenuNotification.PlayNext(title, duration, subtitle, followPlayer: true, null, scale);
	}

	[PunRPC]
	public void RpcModeratorKickPlayer(int duration)
	{
		LocalKickUser(duration, PhotonNetwork.playerList.Length, 1f);
	}

	[PunRPC]
	public void RpcModerationVoteToKick(PhotonPlayer otherPlayer, float vote)
	{
		if (!base.isLocal)
		{
			return;
		}
		if (otherPlayer != null && !voteToKickMap.ContainsKey(otherPlayer))
		{
			if (VoteToKickCount == 0f)
			{
				RecnetAnalyticsHelper.VoteKickInitiated(otherPlayer.ToPlayer(), thisPlayer);
			}
			voteToKickMap.Add(otherPlayer, vote);
			VoteToKickCount += vote;
			vtkExpireTime = Time.time + vtkActiveDuration;
			if (SessionManager.IsDeveloper)
			{
				ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You are voted to be kicked by " + otherPlayer.name, 2f);
			}
		}
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer pPlayer in otherPlayers)
		{
			SendVTKRequestMessage(pPlayer);
		}
	}

	private void SendVTKRequestMessage(PhotonPlayer pPlayer)
	{
		if (!vtkRequestSentPlayers.Contains(pPlayer) && !voteToKickMap.ContainsKey(pPlayer))
		{
			vtkRequestSentPlayers.Add(pPlayer);
			Messages.SendVoteToKickRequest(thisPlayer.PlayerId, pPlayer.ToPlayer().PlayerId);
		}
	}

	[PunRPC]
	public void RpcModerationBroadcastKickMessage()
	{
		if (!base.isLocal)
		{
			ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, $"User {thisPlayer.PlayerName} was vote kicked.", 2.5f);
		}
	}

	[PunRPC]
	public void RpcModerationBroadcastVTKReset()
	{
		if (!base.isLocal)
		{
			IsVotedForKick = false;
		}
	}

	private void LocalKickUser(int duration, int userCount, float userPercent, bool broadcastKick = false)
	{
		if (broadcastKick)
		{
			base.photonView.RPC("RpcModerationBroadcastKickMessage", PhotonTargets.Others);
		}
		AnalyticsHelper.ModerationUserKicked(duration);
		RecnetAnalyticsHelper.VoteKicked(userPercent, userCount, duration);
		if (PhotonNetwork.inRoom)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.BlockedRoomName = PhotonNetwork.room.name;
		}
		thisPlayer.ReturnToDormRoom("You got vote kicked.\nPlease refer to the Code of Conduct.");
		if (duration > 0)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.SetUserBlocked(duration);
		}
		SingletonMonoBehaviour<SessionManager>.Instance.NumberOfTimesUserGotKicked++;
		Profiles.UpdateLocalProfileReputation(-1);
	}

	public void VoteToKickPlayer()
	{
		if (!IsVotedForKick)
		{
			bool flag = Player.LocalPlayer.PlayerProgression.Level >= 20 && Profiles.LocalProfile.Reputation >= -1;
			base.photonView.RPC("RpcModerationVoteToKick", thisPlayer.PhotonPlayer, Player.LocalPlayer.PhotonPlayer, (!flag) ? 1f : 2f);
			IsVotedForKick = true;
			AnalyticsHelper.ModerationVoteKicked(thisPlayer, Player.LocalPlayer.PlayerModeration.VoteKickHappened);
			Player.LocalPlayer.PlayerModeration.VoteKickHappened = true;
		}
	}

	private int LocalGetUserBlockDuration()
	{
		return currentVTKPunishmentBucket.GetDuration(thisPlayer);
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (voteToKickMap.ContainsKey(player))
		{
			VoteToKickCount -= voteToKickMap[player];
			voteToKickMap.Remove(player);
		}
	}
}
public class PlayerObjectiveTracker : UnityEngine.MonoBehaviour
{
	private const string OBJECTIVE_DATE_KEY = "OBJECTIVE_DATE";

	private const string OBJECTIVE_PROGRESS_KEY = "OBJECTIVE_PROGRESS";

	private const string OBJECTIVE_COMPLETED_KEY = "OBJECTIVE_COMPLETED";

	private Player thisPlayer;

	private GameManager gameManager;

	private List<ProgressionManager.ObjectiveType> eventBuffer = new List<ProgressionManager.ObjectiveType>();

	private int debugDateIncrement;

	public static event Action AllObjectivesCompleted;

	public static event Action<List<ProgressionManager.ObjectiveType>> EventBufferUpdated;

	public event Action ObjectiveProgressUpdateEvent;

	private void Awake()
	{
		thisPlayer = GetComponent<Player>();
		if (thisPlayer.isLocal)
		{
			thisPlayer.PlayerEvents.GameOverEvent += OnGameOver;
			thisPlayer.PlayerEvents.DodgeballOutEvent += OnDodgeballHit;
			thisPlayer.PlayerEvents.PaddleballScoreEvent += OnPaddleballScore;
			thisPlayer.PlayerEvents.DiscGolfCompletedHoleEvent += OnDiscGolfCompletedHole;
			thisPlayer.PlayerEvents.PaintballFlagCaptureEvent += OnPaintballFlagCapture;
			thisPlayer.PlayerEvents.PaintballHitEvent += OnPaintballHit;
			thisPlayer.PlayerEvents.SoccerGoalEvent += OnSoccerGoal;
		}
	}

	private void Start()
	{
		gameManager = RecRoomSceneManager.Instance.GameManager;
	}

	private void OnDestroy()
	{
		thisPlayer.PlayerEvents.GameOverEvent -= OnGameOver;
		thisPlayer.PlayerEvents.DodgeballOutEvent -= OnDodgeballHit;
		thisPlayer.PlayerEvents.PaddleballScoreEvent -= OnPaddleballScore;
		thisPlayer.PlayerEvents.DiscGolfCompletedHoleEvent -= OnDiscGolfCompletedHole;
		thisPlayer.PlayerEvents.PaintballFlagCaptureEvent -= OnPaintballFlagCapture;
		thisPlayer.PlayerEvents.PaintballHitEvent -= OnPaintballHit;
		thisPlayer.PlayerEvents.SoccerGoalEvent -= OnSoccerGoal;
	}

	public void GetObjectiveDescription(int objectiveIndex, out ProgressionManager.ObjectiveTypeDescription description, out string descriptionText)
	{
		description = null;
		descriptionText = null;
		ProgressionManager.Objective todaysObjective = GetTodaysObjective(objectiveIndex);
		if (todaysObjective != null)
		{
			description = SingletonMonoBehaviour<ProgressionManager>.Instance.GetObjectiveDescription(todaysObjective.ObjectiveType);
			if (description != null)
			{
				descriptionText = string.Format(description.Description, todaysObjective.RequiredScore);
			}
		}
	}

	public bool GetObjectiveProgress(int objectiveIndex, out int progress, out int total)
	{
		ClearStaleProgress();
		bool result = false;
		progress = 0;
		total = 0;
		ProgressionManager.Objective todaysObjective = GetTodaysObjective(objectiveIndex);
		if (todaysObjective != null)
		{
			total = todaysObjective.RequiredScore;
			if (GetCompleted(objectiveIndex))
			{
				result = true;
				progress = total;
			}
			else
			{
				result = false;
				progress = GetProgress(objectiveIndex);
			}
		}
		return result;
	}

	public void CompleteObjective(ProgressionManager.ObjectiveType objective)
	{
		eventBuffer.Clear();
		eventBuffer.Add(objective);
		UpdateObjectiveProgress();
	}

	public bool GetAllObjectivesCompleted()
	{
		ProgressionManager.Objective[] todaysObjectives = GetTodaysObjectives();
		if (todaysObjectives != null)
		{
			for (int i = 0; i < todaysObjectives.Length; i++)
			{
				if (!GetCompleted(i))
				{
					return false;
				}
			}
		}
		return true;
	}

	private void OnGameOver(bool won)
	{
		eventBuffer.Clear();
		if (RecRoomSceneManager.CurrentSceneName == "dodgeball")
		{
			eventBuffer.Add(ProgressionManager.ObjectiveType.DodgeballGames);
			if (won)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.DodgeballWins);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneName == "soccer")
		{
			eventBuffer.Add(ProgressionManager.ObjectiveType.SoccerGames);
			if (won)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.SoccerWins);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneName == "charades")
		{
			eventBuffer.Add(ProgressionManager.ObjectiveType.CharadesGames);
			if (won)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.CharadesWinsPerformer);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneName == "paddleball")
		{
			eventBuffer.Add(ProgressionManager.ObjectiveType.PaddleballGames);
			if (won)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.PaddleballWins);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneFriendlyName.StartsWith("Disc Golf", StringComparison.InvariantCultureIgnoreCase))
		{
			eventBuffer.Add(ProgressionManager.ObjectiveType.DiscGolfGames);
			if (won)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.DiscGolfWins);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneFriendlyName.StartsWith("Paintball", StringComparison.InvariantCultureIgnoreCase) && gameManager != null)
		{
			if (gameManager.ModeManager.GetMode() == GameMode.MODE_1)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballCTFGames);
				if (won)
				{
					eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballCTFWins);
				}
			}
			else
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballTeamBattleGames);
				if (won)
				{
					eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballTeamBattleWins);
				}
			}
			eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballAnyModeGames);
			if (won)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballAnyModeWins);
			}
		}
		UpdateObjectiveProgress();
	}

	private void OnDodgeballHit()
	{
		eventBuffer.Clear();
		eventBuffer.Add(ProgressionManager.ObjectiveType.DodgeballHits);
		UpdateObjectiveProgress();
	}

	private void OnPaddleballScore()
	{
		eventBuffer.Clear();
		eventBuffer.Add(ProgressionManager.ObjectiveType.PaddleballScores);
		UpdateObjectiveProgress();
	}

	private void OnDiscGolfCompletedHole(int score)
	{
		eventBuffer.Clear();
		if (score < 0)
		{
			eventBuffer.Add(ProgressionManager.ObjectiveType.DiscGolfHolesUnderPar);
		}
		UpdateObjectiveProgress();
	}

	private void OnPaintballFlagCapture()
	{
		eventBuffer.Clear();
		eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballFlagCaptures);
		UpdateObjectiveProgress();
	}

	private void OnPaintballHit()
	{
		eventBuffer.Clear();
		eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballAnyModeHits);
		if (gameManager != null)
		{
			if (gameManager.ModeManager.GetMode() == GameMode.MODE_1)
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballCTFHits);
			}
			else
			{
				eventBuffer.Add(ProgressionManager.ObjectiveType.PaintballTeamBattleHits);
			}
		}
		UpdateObjectiveProgress();
	}

	private void OnSoccerGoal()
	{
		eventBuffer.Clear();
		eventBuffer.Add(ProgressionManager.ObjectiveType.SoccerGoals);
		UpdateObjectiveProgress();
	}

	private void UpdateObjectiveProgress()
	{
		ClearStaleProgress();
		if (eventBuffer.Count > 0 && PlayerObjectiveTracker.EventBufferUpdated != null)
		{
			PlayerObjectiveTracker.EventBufferUpdated(eventBuffer);
		}
		if (GetAllObjectivesCompleted())
		{
			return;
		}
		bool flag = false;
		ProgressionManager.Objective[] todaysObjectives = GetTodaysObjectives();
		for (int i = 0; i < todaysObjectives.Length; i++)
		{
			if (GetCompleted(i))
			{
				continue;
			}
			foreach (ProgressionManager.ObjectiveType item in eventBuffer)
			{
				if (todaysObjectives[i].ObjectiveType != item)
				{
					continue;
				}
				AddProgress(i, 1);
				flag = true;
				if (GetProgress(i) >= todaysObjectives[i].RequiredScore)
				{
					CompleteObjective(i);
					if (SingletonMonoBehaviour<TutorialManager>.Instance.IsOOBERunning)
					{
						SingletonMonoBehaviour<ProgressionManager>.Instance.LocalCompleteObjective(todaysObjectives[i].ObjectiveType);
					}
					else
					{
						SingletonMonoBehaviour<ProgressionManager>.Instance.LocalCompleteObjective(GetDailyObjectiveType(i));
					}
				}
			}
		}
		if (this.ObjectiveProgressUpdateEvent != null && flag)
		{
			this.ObjectiveProgressUpdateEvent();
		}
	}

	private ProgressionManager.ObjectiveType GetDailyObjectiveType(int index)
	{
		return index switch
		{
			0 => ProgressionManager.ObjectiveType.DailyObjective1, 
			1 => ProgressionManager.ObjectiveType.DailyObjective2, 
			2 => ProgressionManager.ObjectiveType.DailyObjective3, 
			_ => ProgressionManager.ObjectiveType.Default, 
		};
	}

	private ProgressionManager.Objective GetTodaysObjective(int index)
	{
		ProgressionManager.Objective[] todaysObjectives = GetTodaysObjectives();
		if (todaysObjectives == null || index < 0 || index >= todaysObjectives.Length)
		{
			return null;
		}
		return todaysObjectives[index];
	}

	private ProgressionManager.Objective[] GetTodaysObjectives()
	{
		if (SingletonMonoBehaviour<TutorialManager>.Instance.IsOOBERunning)
		{
			return SingletonMonoBehaviour<TutorialManager>.Instance.OOBEObjectives;
		}
		DateTime today = DateTime.Today;
		return Config.DailyObjectives[(int)today.DayOfWeek];
	}

	public void ClearStaleProgress(bool forciblyClear = false)
	{
		int currentDate = GetCurrentDate();
		int lastRecordedObjectiveDate = GetLastRecordedObjectiveDate();
		if (currentDate != lastRecordedObjectiveDate || forciblyClear)
		{
			SetLastRecordedObjectiveDate(currentDate);
			SetProgress(0, 0);
			SetCompleted(0, completed: false);
			SetProgress(1, 0);
			SetCompleted(1, completed: false);
			SetProgress(2, 0);
			SetCompleted(2, completed: false);
		}
	}

	private int GetCurrentDate()
	{
		return DateTime.Today.DayOfYear;
	}

	private int GetLastRecordedObjectiveDate()
	{
		return RecroomPrefs.GetInt("OBJECTIVE_DATE", 0);
	}

	private void SetLastRecordedObjectiveDate(int date)
	{
		RecroomPrefs.SetInt("OBJECTIVE_DATE", date);
		RecroomPrefs.Save();
	}

	private void AddProgress(int objectiveIndex, int delta)
	{
		int progress = GetProgress(objectiveIndex);
		SetProgress(objectiveIndex, progress + delta);
	}

	private void SetProgress(int objectiveIndex, int value)
	{
		RecroomPrefs.SetInt(GetObjectiveProgressKey(objectiveIndex), value);
		RecroomPrefs.Save();
	}

	private int GetProgress(int objectiveIndex)
	{
		return RecroomPrefs.GetInt(GetObjectiveProgressKey(objectiveIndex), 0);
	}

	private string GetObjectiveProgressKey(int objectiveIndex)
	{
		return "OBJECTIVE_PROGRESS" + objectiveIndex;
	}

	private void CompleteObjective(int objectiveIndex)
	{
		ProgressionManager.Objective todaysObjective = GetTodaysObjective(objectiveIndex);
		SetCompleted(objectiveIndex, completed: true);
		ProgressionManager.ObjectiveTypeDescription objectiveDescription = SingletonMonoBehaviour<ProgressionManager>.Instance.GetObjectiveDescription(todaysObjective.ObjectiveType);
		if (objectiveDescription == null)
		{
			return;
		}
		if (GetAllObjectivesCompleted())
		{
			if (SingletonMonoBehaviour<TutorialManager>.Instance.IsOOBERunning)
			{
				ScreenSpaceNotificationManager.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "Checklist Complete!", 3f, objectiveDescription.NotificationDelay, OnNotificationPlaying);
				SingletonMonoBehaviour<TutorialManager>.Instance.OOBEObjectivesCompleted();
				ClearStaleProgress(forciblyClear: true);
			}
			else
			{
				ScreenSpaceNotificationManager.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "All Daily Challenges Complete!", 3f, objectiveDescription.NotificationDelay, OnNotificationPlaying);
			}
			if (PlayerObjectiveTracker.AllObjectivesCompleted != null)
			{
				PlayerObjectiveTracker.AllObjectivesCompleted();
			}
		}
		else
		{
			string subtitleText = string.Format(objectiveDescription.Description, todaysObjective.RequiredScore);
			if (SingletonMonoBehaviour<TutorialManager>.Instance.IsOOBERunning)
			{
				ScreenSpaceNotificationManager.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "Checklist Item Complete!", subtitleText, 3f, objectiveDescription.NotificationDelay, OnNotificationPlaying);
			}
			else
			{
				ScreenSpaceNotificationManager.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "Daily Challenge Complete!", subtitleText, 3f, objectiveDescription.NotificationDelay, OnNotificationPlaying);
			}
		}
	}

	private void SetCompleted(int objectiveIndex, bool completed)
	{
		RecroomPrefs.SetInt(GetObjectiveCompletedKey(objectiveIndex), completed ? 1 : 0);
		RecroomPrefs.Save();
	}

	private bool GetCompleted(int objectiveIndex)
	{
		return RecroomPrefs.GetInt(GetObjectiveCompletedKey(objectiveIndex), 0) != 0;
	}

	private string GetObjectiveCompletedKey(int objectiveIndex)
	{
		return "OBJECTIVE_COMPLETED" + objectiveIndex;
	}

	private void OnNotificationPlaying()
	{
		thisPlayer.PlayerAudio.OnObjectiveComplete();
	}
}
[DisallowMultipleComponent]
[RequireComponent(typeof(Player))]
public class PlayerParty : Photon.MonoBehaviour
{
	public static readonly string PartyIdProperty = "PlayerPartyID";

	public static readonly string PartyColorIdProperty = "PlayerPartyColorID";

	private float lastTimePartyListUpdated;

	[Tooltip("Update the party membership list periodically.")]
	[SerializeField]
	private float partyListUpdateInterval = 1f;

	[Tooltip("Party indicator band.")]
	public OutfitSelection PartyBandPrefab;

	private OutfitItem partyBandLeft;

	private OutfitItem partyBandRight;

	private List<Player> groupPlayers;

	private Player thisPlayer;

	private bool partyColorDirty = true;

	private Color? _partyColor;

	public List<Player> PartyPlayers => groupPlayers;

	public bool IsInParty => !string.IsNullOrEmpty(CurrentPartyId);

	public int PartySize => IsInParty ? (groupPlayers.Count + 1) : 0;

	public string CurrentPartyId
	{
		get
		{
			return thisPlayer.PlayerData.GetData<string>(PartyIdProperty, null);
		}
		private set
		{
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyId = value;
			}
			if (value != null)
			{
				AnalyticsHelper.PartyJoined(value, PartySize);
			}
			thisPlayer.PlayerData.SetData(PartyIdProperty, value);
			if (value == null)
			{
				CurrentPartyColorId = null;
			}
			else
			{
				UpdatePartyLists(forcePartyChange: true);
				int partySize = PartySize;
				if (partySize < 2)
				{
					AnalyticsHelper.PartyCreatedSelf(value);
				}
				else
				{
					AnalyticsHelper.PartyJoinedSelf(PartySize, value);
				}
				string text = null;
				foreach (Player groupPlayer in groupPlayers)
				{
					text = groupPlayer.PlayerParty.CurrentPartyColorId;
					if (!string.IsNullOrEmpty(text))
					{
						break;
					}
				}
				if (string.IsNullOrEmpty(text))
				{
					text = ((string.IsNullOrEmpty(SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId) || !IsGroupColorIdAvailable(SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId)) ? GetNextAvailableGroupColorId() : SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId);
				}
				CurrentPartyColorId = text;
			}
			partyColorDirty = true;
		}
	}

	public string CurrentPartyColorId
	{
		get
		{
			return thisPlayer.PlayerData.GetData<string>(PartyColorIdProperty, null);
		}
		private set
		{
			thisPlayer.PlayerData.SetData(PartyColorIdProperty, value);
			partyColorDirty = true;
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId = value;
			}
		}
	}

	public Color? PartyColor
	{
		get
		{
			if (partyColorDirty)
			{
				_partyColor = null;
				string currentPartyColorId = CurrentPartyColorId;
				if (!string.IsNullOrEmpty(currentPartyColorId) && PUNNetworkManager.Instance != null)
				{
					ColorVault.ColorToGuid colorToGuid = SingletonMonoBehaviour<SessionManager>.Instance.GroupColorVault.Find(currentPartyColorId);
					if (colorToGuid != null)
					{
						_partyColor = colorToGuid.color;
						partyColorDirty = false;
					}
				}
			}
			return _partyColor;
		}
	}

	public event Action PartyUpdateReceived;

	protected override void Awake()
	{
		base.Awake();
		thisPlayer = GetComponent<Player>();
		groupPlayers = new List<Player>();
	}

	private void Start()
	{
		if (base.isLocal && SingletonMonoBehaviour<SessionManager>.Instance != null)
		{
			CurrentPartyId = SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyId;
			if (IsInParty)
			{
				Invoke("DeferredUpdatePartyColor", 1f);
				Invoke("DeferredUpdatePartyColor", 5f);
			}
			thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
		}
		partyBandRight = thisPlayer.PlayerOutfit.InstantiateNewOutfitPrefab(PartyBandPrefab, Player.BodyPart.RightHand, ownedByPlayerOutfit: false);
		partyBandLeft = thisPlayer.PlayerOutfit.InstantiateNewOutfitPrefab(PartyBandPrefab, Player.BodyPart.LeftHand, ownedByPlayerOutfit: false);
	}

	private void Update()
	{
		UpdateBraceletColor(PlayerHand.HandType.Left);
		UpdateBraceletColor(PlayerHand.HandType.Right);
		if (base.isLocal && Time.time - lastTimePartyListUpdated > partyListUpdateInterval)
		{
			lastTimePartyListUpdated = Time.time;
			UpdatePartyLists();
		}
	}

	private void UpdateBraceletColor(PlayerHand.HandType handType)
	{
		if (handType != PlayerHand.HandType.Unknown && !(thisPlayer == null))
		{
			Color? partyColor = PartyColor;
			PlayerHand playerHand = ((handType != PlayerHand.HandType.Left) ? thisPlayer.RightHand : thisPlayer.LeftHand);
			OutfitItem outfitItem = ((handType != PlayerHand.HandType.Left) ? partyBandRight : partyBandLeft);
			bool flag = partyColor.HasValue && playerHand != null && playerHand.IsVisible;
			outfitItem.gameObject.SetActive(flag);
			if (flag && outfitItem.SkinnedMeshRenderer.material.color != partyColor.Value)
			{
				outfitItem.SkinnedMeshRenderer.material.color = partyColor.Value;
				outfitItem.GetComponent<AnimateInOut>().PlayEffect(animIn: true);
			}
			else if (!IsInParty)
			{
				outfitItem.SkinnedMeshRenderer.material.color = Color.clear;
			}
		}
	}

	public virtual void OnPhotonPlayerPropertiesChanged(object[] playerAndUpdatedProps)
	{
		partyColorDirty = true;
	}

	public virtual void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		UpdatePartyLists(forcePartyChange: true);
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		if (!base.isLocal)
		{
			return;
		}
		switch (gesture)
		{
		case PlayerHandGestures.Gesture.HandshakeSuccess:
		{
			bool flag2 = false;
			bool flag3 = false;
			Relationship relationship = Relationships.RelationshipList.Find((Relationship f) => f.PlayerID == otherHand.ThisPlayer.PlayerId);
			if (relationship != null)
			{
				switch (relationship.Type)
				{
				case Relationship.RelationshipType.Friend:
					flag2 = true;
					break;
				case Relationship.RelationshipType.BlockedLocal:
				case Relationship.RelationshipType.BlockedRemote:
				case Relationship.RelationshipType.BlockedMutual:
					flag3 = true;
					break;
				}
			}
			Vector3 value = Vector3.Lerp(myHand.transform.position, otherHand.transform.position, 0.5f);
			if (flag3)
			{
				MenuNotification.PlayNext("Played Blocked!", 2f, null, followPlayer: false, value, 0.3f);
				break;
			}
			if (flag2)
			{
				MenuNotification.PlayNext("Friends", 2f, null, followPlayer: false, value, 0.3f);
				break;
			}
			Relationships.AddFriend(otherHand.ThisPlayer.PlayerId);
			MenuNotification.PlayNext("Friend Added", 2f, null, followPlayer: false, value, 0.3f);
			break;
		}
		case PlayerHandGestures.Gesture.Fistbump:
		{
			bool flag = false;
			if (otherHand.ThisPlayer.PlayerParty.IsInParty && !IsInParty)
			{
				CurrentPartyId = otherHand.ThisPlayer.PlayerParty.CurrentPartyId;
				UpdatePartyLists();
				flag = true;
			}
			else if (!otherHand.ThisPlayer.PlayerParty.IsInParty && IsInParty)
			{
				flag = true;
			}
			else if (otherHand.ThisPlayer.PlayerParty.IsInParty && IsInParty && otherHand.ThisPlayer.PlayerParty.CurrentPartyId != CurrentPartyId)
			{
				flag = true;
				if (base.photonView.owner.ID > otherHand.ThisPlayer.photonView.owner.ID)
				{
					UpdatePartyLists();
					string currentPartyId = otherHand.ThisPlayer.PlayerParty.CurrentPartyId;
					foreach (Player groupPlayer in groupPlayers)
					{
						groupPlayer.photonView.RPC("RpcAutoJoinParty", groupPlayer.photonView.owner, currentPartyId);
					}
					CurrentPartyId = currentPartyId;
				}
			}
			else if (!otherHand.ThisPlayer.PlayerParty.IsInParty && !IsInParty)
			{
				flag = true;
				if (base.photonView.owner.ID > otherHand.ThisPlayer.photonView.owner.ID)
				{
					CurrentPartyId = Guid.NewGuid().ToString();
					otherHand.ThisPlayer.photonView.RPC("RpcAutoJoinParty", otherHand.ThisPlayer.photonView.owner, CurrentPartyId);
				}
			}
			if (flag)
			{
				MenuNotification.PlayNext("Party Join", 2f, null, followPlayer: false, (myHand.transform.position + otherHand.transform.position) / 2f, 0.3f);
			}
			break;
		}
		}
	}

	[PunRPC]
	public void RpcAutoJoinParty(string partyId)
	{
		CurrentPartyId = partyId;
		UpdatePartyLists();
	}

	private void DeferredUpdatePartyColor()
	{
		PhotonPlayer[] playerList = PhotonNetwork.playerList;
		foreach (PhotonPlayer photonPlayer in playerList)
		{
			Player player = photonPlayer.TagObject as Player;
			if (player != null && player.PlayerParty.IsInParty && player.PlayerParty.CurrentPartyId == CurrentPartyId)
			{
				string currentPartyColorId = player.PlayerParty.CurrentPartyColorId;
				if (!string.IsNullOrEmpty(currentPartyColorId))
				{
					CurrentPartyColorId = currentPartyColorId;
					break;
				}
			}
		}
	}

	public bool CanInvitePlayer(Player player)
	{
		return player != null && !groupPlayers.Contains(player);
	}

	private string GetNextAvailableGroupColorId()
	{
		List<string> list = new List<string>();
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer player in otherPlayers)
		{
			string customPropertyString = player.GetCustomPropertyString(PartyColorIdProperty);
			if (!string.IsNullOrEmpty(customPropertyString) && !list.Contains(customPropertyString))
			{
				list.Add(customPropertyString);
			}
		}
		SingletonMonoBehaviour<SessionManager>.Instance.GroupColorVault.Colors.Shuffle();
		foreach (ColorVault.ColorToGuid color in SingletonMonoBehaviour<SessionManager>.Instance.GroupColorVault.Colors)
		{
			if (!list.Contains(color.guidString))
			{
				return color.guidString;
			}
		}
		UnityEngine.Debug.LogError("Could not find an unused party color, this is madness. Should never happen in a max 8 player game, add colors to PUNNetworkManager ColorVault.");
		return null;
	}

	private bool IsGroupColorIdAvailable(string playerPartyColorId)
	{
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer player in otherPlayers)
		{
			string customPropertyString = player.GetCustomPropertyString(PartyColorIdProperty);
			string customPropertyString2 = player.GetCustomPropertyString(PartyIdProperty);
			if (!string.IsNullOrEmpty(customPropertyString) && playerPartyColorId == customPropertyString && !string.IsNullOrEmpty(customPropertyString2) && customPropertyString2 != CurrentPartyId)
			{
				return false;
			}
		}
		return true;
	}

	public void KickPlayer(Player target)
	{
		if (IsInPartyWith(target))
		{
			target.photonView.RPC("RpcKickedFromParty", target.photonView.owner, CurrentPartyId);
		}
	}

	public string[] GetExpectedPhotonUsers()
	{
		UpdatePartyLists();
		if (groupPlayers.Count > 0)
		{
			string[] array = new string[groupPlayers.Count];
			for (int i = 0; i < groupPlayers.Count; i++)
			{
				array[i] = groupPlayers[i].photonView.owner.userId;
			}
			return array;
		}
		return null;
	}

	[PunRPC]
	public void RpcKickedFromParty(string partyId)
	{
		if (!(partyId != CurrentPartyId))
		{
			LeaveCurrentParty();
		}
	}

	private bool IsValidPartyPlayer(Player player)
	{
		return player != null && player.photonView.owner != base.photonView.owner && IsInParty && player.PlayerParty.CurrentPartyId == CurrentPartyId;
	}

	private void UpdatePartyLists(bool forcePartyChange = false)
	{
		bool flag = false || forcePartyChange;
		if (IsInParty)
		{
			Player[] array = groupPlayers.ToArray();
			foreach (Player player in array)
			{
				if (!IsValidPartyPlayer(player))
				{
					GroupPlayersRemove(player);
					flag = true;
				}
			}
			PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
			foreach (PhotonPlayer photonPlayer in otherPlayers)
			{
				Player player2 = photonPlayer.TagObject as Player;
				if (player2 != null && IsValidPartyPlayer(player2) && !groupPlayers.Contains(player2))
				{
					GroupPlayersAdd(player2);
					flag = true;
				}
			}
		}
		else if (groupPlayers.Count > 0)
		{
			groupPlayers.Clear();
			flag = true;
		}
		if (flag && this.PartyUpdateReceived != null)
		{
			this.PartyUpdateReceived();
		}
	}

	private void GroupPlayersAdd(Player other)
	{
		groupPlayers.Add(other);
		if (base.isLocal)
		{
			AnalyticsHelper.PartyJoinedOther(other, PartySize);
		}
	}

	private void GroupPlayersRemove(Player other)
	{
		groupPlayers.Remove(other);
		if (base.isLocal)
		{
			AnalyticsHelper.PartyLeftOther(other, PartySize);
		}
	}

	public void LeaveCurrentParty()
	{
		if (groupPlayers.Count > 0)
		{
			AnalyticsHelper.PartyLeftSelf(CurrentPartyId);
		}
		AnalyticsHelper.PartyLeft(CurrentPartyId, groupPlayers.Count);
		groupPlayers.Clear();
		CurrentPartyId = null;
	}

	public bool IsInPartyWith(Player player)
	{
		return player != null && IsInParty && groupPlayers.Contains(player);
	}

	[PunRPC]
	public void RpcDebugLeaveRoom()
	{
		if (RecRoomSceneManager.Instance != null)
		{
			RecRoomSceneManager.Instance.SwitchActivity("lockerroom", createPrivateRoom: false);
		}
	}
}
public class PlayerProgression : Photon.MonoBehaviour
{
	[Header("Feedback")]
	[SerializeField]
	private PooledParticle levelUpParticlesPrefab;

	private Player thisPlayer;

	private const string PlayerLevelProperty = "PlayerLevel";

	private const string PlayerMemberProperty = "PlayerMember";

	public int Level
	{
		get
		{
			return thisPlayer.PlayerData.GetData("PlayerLevel", 1);
		}
		private set
		{
			if (thisPlayer.isLocal)
			{
				if (thisPlayer.PlayerData.HasData("PlayerLevel") && value > Level)
				{
					ScreenSpaceNotificationManager.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "You Leveled Up!", 5f, PlayLevelUpFeedback);
					thisPlayer.PlayerEvents.LevelUp(value);
				}
				thisPlayer.PlayerData.SetData("PlayerLevel", value);
			}
		}
	}

	public bool IsMember { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		thisPlayer = GetComponent<Player>();
		thisPlayer.PlayerData.RegisterCallback("PlayerMember", OnPlayerMemberPropertyChanged);
		if (base.isLocal)
		{
			Level = Profiles.LocalProfile.Level;
			Profiles.LocalProfileDownloaded += Profile_LocalProfileDownloaded;
			Profile_LocalProfileDownloaded(Profiles.LocalProfile);
			Profiles.LocalProfileLevelUpdated += Profile_LocalProfileLevelUpdated;
			Profiles.LocalProfileXpUpdated += Profile_LocalProfileXpUpdated;
		}
		else
		{
			OnPlayerMemberPropertyChanged(null, null);
		}
	}

	protected override void OnDestroy()
	{
		if (base.isLocal)
		{
			Profiles.LocalProfileDownloaded -= Profile_LocalProfileDownloaded;
			Profiles.LocalProfileLevelUpdated -= Profile_LocalProfileLevelUpdated;
			Profiles.LocalProfileXpUpdated -= Profile_LocalProfileXpUpdated;
		}
		thisPlayer.PlayerData.UnregisterCallback("PlayerMember", OnPlayerMemberPropertyChanged);
		base.OnDestroy();
	}

	private void Profile_LocalProfileXpUpdated(int currentXp, int deltaXp)
	{
		thisPlayer.PlayerEvents.XPUpdated(currentXp);
	}

	private void Profile_LocalProfileLevelUpdated(int level)
	{
		Level = level;
	}

	private void Profile_LocalProfileDownloaded(Profile profile)
	{
		if (base.isLocal)
		{
			thisPlayer.PlayerData.SetData("PlayerMember", profile?.Verified ?? false);
		}
	}

	private void OnPlayerMemberPropertyChanged(PlayerData sender, string key)
	{
		IsMember = thisPlayer.PlayerData.GetData("PlayerMember", defaultValue: false);
	}

	public void PlayLevelUpFeedback()
	{
		base.photonView.RPC("RpcPlayLevelUpFeedback", PhotonTargets.All);
	}

	[PunRPC]
	public void RpcPlayLevelUpFeedback()
	{
		thisPlayer.PlayerAudio.OnLevelUp();
		PooledParticle pooledParticle = ObjectPool.Instance.Acquire(levelUpParticlesPrefab);
		if (pooledParticle != null)
		{
			pooledParticle.Play();
			PlayerFloorPositionFollowing component = pooledParticle.GetComponent<PlayerFloorPositionFollowing>();
			if (component != null)
			{
				component.TrackedPlayer = thisPlayer;
				return;
			}
			pooledParticle.transform.position = thisPlayer.CurrentFloorPosition;
			pooledParticle.transform.rotation = Quaternion.LookRotation(Vector3.right, Vector3.forward);
		}
	}
}
public class PlayerTeleportDecal : UnityEngine.MonoBehaviour
{
	public enum DecalVisibilityMode
	{
		None,
		Ground,
		AvatarAndGround,
		ToolHit,
		AvatarAndGroundAndArrow
	}

	[Header("Avatar")]
	[SerializeField]
	private Transform head;

	[SerializeField]
	private Transform body;

	[SerializeField]
	private Transform ground;

	[SerializeField]
	private Transform arrow;

	[Header("Tool Hit Visual")]
	[SerializeField]
	private TeleportChargeVisual toolHitVisual;

	[Header("Materials")]
	[SerializeField]
	private Material validMaterial;

	[SerializeField]
	private Material invalidMaterial;

	[HideInInspector]
	public List<Renderer> Renderers = new List<Renderer>();

	private DecalVisibilityMode visibilityMode;

	private bool isValidPosition;

	public DecalVisibilityMode VisibilityMode
	{
		get
		{
			return visibilityMode;
		}
		set
		{
			visibilityMode = value;
			bool active = visibilityMode == DecalVisibilityMode.AvatarAndGround || visibilityMode == DecalVisibilityMode.AvatarAndGroundAndArrow;
			head.gameObject.SetActive(active);
			body.gameObject.SetActive(active);
			bool active2 = visibilityMode == DecalVisibilityMode.Ground || visibilityMode == DecalVisibilityMode.AvatarAndGround || visibilityMode == DecalVisibilityMode.AvatarAndGroundAndArrow;
			ground.gameObject.SetActive(active2);
			bool active3 = visibilityMode == DecalVisibilityMode.ToolHit;
			toolHitVisual.gameObject.SetActive(active3);
			bool active4 = visibilityMode == DecalVisibilityMode.AvatarAndGroundAndArrow;
			arrow.gameObject.SetActive(active4);
		}
	}

	public bool IsValidPosition
	{
		get
		{
			return isValidPosition;
		}
		set
		{
			if (isValidPosition != value)
			{
				isValidPosition = value;
				UpdateMaterials();
			}
		}
	}

	private void Awake()
	{
		Renderers.AddRange(GetComponentsInChildren<Renderer>(includeInactive: true));
		Renderer[] componentsInChildren = arrow.GetComponentsInChildren<Renderer>(includeInactive: true);
		foreach (Renderer item in componentsInChildren)
		{
			Renderers.Remove(item);
		}
		VisibilityMode = DecalVisibilityMode.None;
		UpdateMaterials();
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
	}

	public void UpdateAvatarDecal(Player player, Vector3 groundPoint, bool isRotating, Vector3 rotationForward)
	{
		ground.position = groundPoint;
		arrow.position = groundPoint;
		arrow.rotation = ((!isRotating) ? Quaternion.identity : Quaternion.LookRotation(rotationForward, Vector3.up));
		Quaternion quaternion = Quaternion.identity;
		if (isRotating)
		{
			Vector3 fromDirection = player.transform.forward;
			if (PlatformManager.Instance.CurrentTrackingMode == PlatformManager.TrackingMode.THREE_SIXTY_DEGREE)
			{
				fromDirection = Vector3.ProjectOnPlane(player.Head.transform.forward, Vector3.up).normalized;
			}
			quaternion = Quaternion.FromToRotation(fromDirection, rotationForward);
		}
		head.position = groundPoint + player.Head.HeightOffset;
		head.rotation = player.Head.transform.rotation * quaternion;
		body.position = head.position - player.Body.ToHead;
		body.rotation = player.Body.transform.rotation * quaternion;
	}

	public void UpdateToolHitDecal(bool enabled, float charge, Vector3 toolHitPosition, Vector3 toolHitNormal)
	{
		if (enabled)
		{
			VisibilityMode = DecalVisibilityMode.ToolHit;
			toolHitVisual.Charge = charge;
			toolHitVisual.transform.position = toolHitPosition;
			toolHitVisual.transform.rotation = Quaternion.LookRotation(toolHitNormal, Vector3.up);
		}
	}

	private void UpdateMaterials()
	{
		foreach (Renderer renderer in Renderers)
		{
			renderer.material = ((!IsValidPosition) ? invalidMaterial : validMaterial);
		}
	}
}
public class PlayerTeleportRegionTracker : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private CollisionForwarder headTracker;

	[SerializeField]
	private CollisionForwarder torsoTracker;

	private Transform head;

	private Transform body;

	public Player ThisPlayer { get; private set; }

	private void Awake()
	{
		ThisPlayer = base.gameObject.GetComponentInParents<Player>();
		head = ThisPlayer.Head.transform;
		body = ThisPlayer.Body.transform;
	}

	private void Start()
	{
		headTracker.TriggerEnter += Tracker_TriggerEnter;
		torsoTracker.TriggerEnter += Tracker_TriggerEnter;
		headTracker.TriggerExit += Tracker_TriggerExit;
		torsoTracker.TriggerExit += Tracker_TriggerExit;
	}

	private void FixedUpdate()
	{
		if (head != null)
		{
			headTracker.Rigidbody.MovePosition(head.position);
			headTracker.Rigidbody.MoveRotation(head.rotation);
		}
		if (body != null)
		{
			torsoTracker.Rigidbody.MovePosition(body.position);
			torsoTracker.Rigidbody.MoveRotation(body.rotation);
		}
	}

	private bool CheckAvatarChangingRegion(Collider collider)
	{
		return collider.gameObject.layer == 5 && collider.gameObject.CompareTag("AvatarChangingRegion");
	}

	private void Tracker_TriggerEnter(Collider other)
	{
		if (CheckAvatarChangingRegion(other))
		{
			ThisPlayer.IsInChangingRoom = true;
		}
	}

	private void Tracker_TriggerExit(Collider other)
	{
		if (CheckAvatarChangingRegion(other))
		{
			ThisPlayer.IsInChangingRoom = false;
		}
	}
}
[DisallowMultipleComponent]
public class PlayerUI : Photon.MonoBehaviour
{
	[SerializeField]
	private Transform positionGlow;

	[SerializeField]
	private float positionGlowVisibleDuration = 0.5f;

	[SerializeField]
	private float positionGlowHeightOffset = 1f;

	[SerializeField]
	private Text nameLabelText;

	[SerializeField]
	private Text guestLabelText;

	[SerializeField]
	private Text levelText;

	[SerializeField]
	private UnityEngine.UI.Image levelTextBackground;

	[SerializeField]
	private float nameLabelTextFadeSpeed = 15f;

	[SerializeField]
	private float nameHighlightAlphaMin = 0.15f;

	[SerializeField]
	private float nameHighlightAlphaMax = 0.95f;

	[SerializeField]
	private float nameHighlightOnTeamAlphaMin = 0.85f;

	[SerializeField]
	private float nameHighlightOnTeamAlphaMax = 1f;

	[SerializeField]
	private PlayerMenu menu;

	[SerializeField]
	private ParticleSystem highFiveParticles;

	[SerializeField]
	private ParticleSystem fistBumpParticles;

	[Header("Handshake")]
	[SerializeField]
	private ParticleSystem handshakeChargeParticles;

	[SerializeField]
	private ParticleSystem handshakeSuccessParticles;

	[SerializeField]
	private RecRoomAudioClip handshakeChargeAudio;

	[SerializeField]
	private RecRoomAudioClip handshakeSuccessAudio;

	[SerializeField]
	private UIPlayerCamera uIPlayerCameraPrefab;

	[Range(0.1f, 1f)]
	[SerializeField]
	private float lookAtWristSensitivity = 0.9f;

	[Range(0.1f, 1f)]
	[SerializeField]
	private float menuDismissSensitivity = 0.25f;

	[SerializeField]
	private float requiredGhostButtonPressTime = 1f;

	private Player thisPlayer;

	private GameManager gameManager;

	private SFXAudioSource runningHandshakeAudio;

	private ParticleSystem runningHandshakeParticles;

	private Coroutine handshakeLoopingFeedbackCoroutine;

	private PlayerHand ghostButtonHeldHand;

	private float ghostButtonPressedStartTime;

	private bool _nameVisible;

	private float nameHighlightTargetAlpha = 1f;

	private bool _nameHighlighted;

	private float lastglowVisibleTime;

	private bool _glowVisible;

	public UIPlayerCamera UIPlayerCamera { get; private set; }

	public PlayerMenu Menu => menu;

	public Transform LabelTransform => nameLabelText.rectTransform.parent;

	public bool NameVisible
	{
		get
		{
			return _nameVisible;
		}
		set
		{
			_nameVisible = value;
			nameLabelText.transform.parent.gameObject.SetActive(_nameVisible);
		}
	}

	private bool NameHighlighted
	{
		get
		{
			return _nameHighlighted;
		}
		set
		{
			_nameHighlighted = value;
			if (PlayerTeam == GameTeam.INVALID)
			{
				nameHighlightTargetAlpha = ((!value) ? nameHighlightAlphaMin : nameHighlightAlphaMax);
			}
			else
			{
				nameHighlightTargetAlpha = ((!value) ? nameHighlightOnTeamAlphaMin : nameHighlightOnTeamAlphaMax);
			}
		}
	}

	public bool GlowVisible
	{
		get
		{
			return _glowVisible;
		}
		set
		{
			if (value != _glowVisible)
			{
				bool flag = gameManager == null || gameManager.CurrentState != GameStates.GAME_RUNNING || gameManager.TeamManager.PlayersAreTeammates(PhotonNetwork.player, thisPlayer.PhotonPlayer);
				_glowVisible = value && flag;
				positionGlow.gameObject.SetActive(_glowVisible);
			}
			if (_glowVisible)
			{
				lastglowVisibleTime = Time.time;
			}
		}
	}

	private GameTeam PlayerTeam
	{
		get
		{
			if (thisPlayer == null || gameManager == null || gameManager.CurrentState != GameStates.GAME_RUNNING)
			{
				return GameTeam.INVALID;
			}
			return gameManager.TeamManager.GetPlayerTeam(thisPlayer.PhotonPlayer);
		}
	}

	public bool MenuInteractionAllowed { get; set; }

	private bool ShouldDismissMenu
	{
		get
		{
			bool flag = Menu.AttachedToWrist && (!Menu.MenuAnchorHand.IsVisible || StoppedLookingAtWrist());
			bool flag2 = !Menu.AttachedToWrist && (thisPlayer.LeftHand.ControllerIO.TeleportButtonUp || thisPlayer.RightHand.ControllerIO.TeleportButtonUp || Menu.MenuAnchorHand.ControllerIO.MenuButtonUp);
			return flag || flag2;
		}
	}

	private bool IsGhostButtonDown(PlayerHand hand)
	{
		return SingletonMonoBehaviour<CameraRig>.IsInitialized && hand.ThisPlayer.isLocal && hand.ControllerIO != null && hand.ControllerIO.MenuButtonDown;
	}

	private bool IsGhostButtonPressed(PlayerHand hand)
	{
		return SingletonMonoBehaviour<CameraRig>.IsInitialized && hand.ThisPlayer.isLocal && hand.ControllerIO != null && hand.ControllerIO.MenuButtonPressed;
	}

	private PlayerHand IsLookingAtWrist()
	{
		PlayerHand playerHand = null;
		if (IsLookingAtWrist(thisPlayer.LeftHand))
		{
			playerHand = thisPlayer.LeftHand;
		}
		if (playerHand == null && IsLookingAtWrist(thisPlayer.RightHand))
		{
			playerHand = thisPlayer.RightHand;
		}
		return playerHand;
	}

	private bool IsLookingAtWrist(PlayerHand wrist)
	{
		bool result = false;
		if (wrist != null)
		{
			Vector3 forward = wrist.WatchMenuOrigin.forward;
			Vector3 up = wrist.WatchMenuOrigin.up;
			Vector3 forward2 = thisPlayer.Head.transform.forward;
			Vector3 up2 = thisPlayer.Head.transform.up;
			Vector3 normalized = (wrist.WatchMenuOrigin.position - thisPlayer.Head.transform.position).normalized;
			result = Vector3.Dot(forward2, normalized) > lookAtWristSensitivity && Vector3.Dot(forward, normalized) > lookAtWristSensitivity && Vector3.Dot(up2, up) > lookAtWristSensitivity;
		}
		return result;
	}

	private bool StoppedLookingAtWrist()
	{
		bool result = false;
		if (Menu.MenuAnchorHand != null)
		{
			Vector3 forward = Menu.MenuAnchorHand.WatchMenuOrigin.forward;
			Vector3 forward2 = thisPlayer.Head.transform.forward;
			Vector3 normalized = (Menu.MenuAnchorHand.WatchMenuOrigin.position - thisPlayer.Head.transform.position).normalized;
			result = Vector3.Dot(forward2, normalized) < menuDismissSensitivity || Vector3.Dot(forward, normalized) < menuDismissSensitivity;
		}
		return result;
	}

	[Obsolete("Use the PlayerMenu system")]
	public void HideMenu()
	{
		throw new NotImplementedException();
	}

	protected override void Awake()
	{
		base.Awake();
		thisPlayer = GetComponent<Player>();
		thisPlayer.VisibilityChanged += ThisPlayer_VisibilityChanged;
		NameVisible = false;
		MenuInteractionAllowed = true;
	}

	private void Start()
	{
		if (base.isLocal)
		{
			thisPlayer.PlayerParty.PartyUpdateReceived += PlayerParty_PartyUpdateReceived;
			SingletonMonoBehaviour<CameraRig>.Instance.HeadGestureDetect.GestureDetected += HeadGestureDetect_GestureDetected;
			NameVisible = false;
			UIPlayerCamera = UnityEngine.Object.Instantiate(uIPlayerCameraPrefab);
			thisPlayer.SetParentPlayerRoot(UIPlayerCamera.transform);
		}
		else if (Player.LocalPlayer != null && Player.LocalPlayer.PlayerUI.Menu != null && Player.LocalPlayer.PlayerUI.Menu.Visible)
		{
			Player.LocalPlayer.PlayerUI.Menu.MarkDirty();
		}
		gameManager = RecRoomSceneManager.Instance.GameManager;
		thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
		thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
	}

	private void HeadGestureDetect_GestureDetected(HeadGestureDetect.Gesture gesture)
	{
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		switch (gesture)
		{
		case PlayerHandGestures.Gesture.Highfive:
		{
			Vector3 position2 = (myHand.transform.position + otherHand.transform.position) / 2f;
			thisPlayer.PlayerAudio.OnHighFive(position2);
			if (highFiveParticles != null)
			{
				ParticleSystem particleSystem2 = UnityEngine.Object.Instantiate(highFiveParticles);
				particleSystem2.transform.position = position2;
				particleSystem2.Play();
				UnityEngine.Object.Destroy(particleSystem2.gameObject, particleSystem2.main.duration);
			}
			break;
		}
		case PlayerHandGestures.Gesture.Fistbump:
		{
			Vector3 position = (myHand.transform.position + otherHand.transform.position) / 2f;
			thisPlayer.PlayerAudio.OnFistBump(position);
			if (fistBumpParticles != null)
			{
				ParticleSystem particleSystem = UnityEngine.Object.Instantiate(fistBumpParticles);
				particleSystem.transform.position = position;
				particleSystem.Play();
				UnityEngine.Object.Destroy(particleSystem.gameObject, particleSystem.main.duration);
			}
			break;
		}
		case PlayerHandGestures.Gesture.HandshakeStart:
			StartHandshakeFeedback(myHand, otherHand);
			break;
		case PlayerHandGestures.Gesture.HandshakeCancel:
			StopHandshakeFeedback();
			break;
		case PlayerHandGestures.Gesture.HandshakeSuccess:
			StopHandshakeFeedback();
			PlayHandshakeSuccessParticles(myHand, otherHand);
			break;
		}
		if (base.isLocal)
		{
			myHand.Vibrate(100, 1000);
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (thisPlayer != null)
		{
			thisPlayer.VisibilityChanged -= ThisPlayer_VisibilityChanged;
			if (base.isLocal)
			{
				thisPlayer.PlayerParty.PartyUpdateReceived -= PlayerParty_PartyUpdateReceived;
			}
		}
	}

	private void Update()
	{
		if (base.isLocal && MenuInteractionAllowed)
		{
			UpdateGhostButton();
			if (!Menu.Visible)
			{
				PlayerHand playerHand = IsLookingAtWrist();
				if (playerHand != null && playerHand.IsVisible)
				{
					Menu.ShowMenu(playerHand);
				}
				if (ControllerIO.CurrentInputMode == ControllerIO.InputMode.Debug)
				{
					PlayerHand playerHand2 = null;
					if (thisPlayer.LeftHand.Tool == null && thisPlayer.LeftHand.ControllerIO != null && thisPlayer.LeftHand.ControllerIO.MenuButtonUp)
					{
						playerHand2 = thisPlayer.LeftHand;
					}
					else if (thisPlayer.RightHand.Tool == null && thisPlayer.RightHand.ControllerIO != null && thisPlayer.RightHand.ControllerIO.MenuButtonUp)
					{
						playerHand2 = thisPlayer.RightHand;
					}
					if (playerHand2 != null)
					{
						Menu.ShowMenu(playerHand2);
						Menu.AttachedToWrist = false;
						Menu.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.TransformPoint(0f, -0.1f, 0.7f);
						Menu.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation;
					}
				}
			}
			else if (Menu.MenuAnchorHand != null)
			{
				if (ShouldDismissMenu)
				{
					Menu.ShowMenu(null, show: false);
				}
				else if (Menu.AttachedToWrist && Menu.MenuAnchorHand.ControllerIO.MenuButtonUp)
				{
					Menu.AttachedToWrist = false;
				}
			}
		}
		if (!base.isLocal)
		{
			NameHighlighted = thisPlayer.IsTalking;
			NameVisible = SingletonMonoBehaviour<SettingsManager>.Instance.ShowNames;
			guestLabelText.gameObject.SetActive(!thisPlayer.PlayerProgression.IsMember);
		}
		GameTeam gameTeam = ((!(thisPlayer != null)) ? GameTeam.INVALID : thisPlayer.Team);
		if (NameVisible && base.owner != null)
		{
			if (nameLabelText.text != base.owner.name)
			{
				nameLabelText.text = base.owner.name;
			}
			levelText.text = thisPlayer.PlayerProgression.Level.ToString();
			Color color = Color.white;
			if (gameTeam != GameTeam.INVALID)
			{
				color = GameTeamSettings.GetTeamColor(gameTeam);
			}
			else if (thisPlayer.PlayerParty.PartyColor.HasValue)
			{
				color = thisPlayer.PlayerParty.PartyColor.Value;
			}
			color.a = nameLabelText.color.a;
			if (color.a != nameHighlightTargetAlpha)
			{
				color.a = Mathf.SmoothStep(color.a, nameHighlightTargetAlpha, Time.deltaTime * nameLabelTextFadeSpeed);
			}
			nameLabelText.color = color;
			if (guestLabelText.gameObject.activeSelf)
			{
				guestLabelText.color = color;
			}
			levelText.color = color;
			levelTextBackground.color = color;
		}
		if (gameTeam != GameTeam.INVALID)
		{
			thisPlayer.PlayerOutfit.TeamIndicator = GameTeamSettings.GetTeamColor(gameTeam);
		}
		else
		{
			thisPlayer.PlayerOutfit.TeamIndicator = null;
		}
		if (GlowVisible)
		{
			if (Time.time - lastglowVisibleTime > positionGlowVisibleDuration)
			{
				GlowVisible = false;
				return;
			}
			positionGlow.transform.rotation = Quaternion.LookRotation(Vector3.forward);
			positionGlow.transform.position = thisPlayer.Head.transform.position + Vector3.up * positionGlowHeightOffset;
		}
	}

	private void UpdateGhostButton()
	{
		if (ghostButtonHeldHand == null)
		{
			if (IsGhostButtonDown(thisPlayer.LeftHand))
			{
				ghostButtonHeldHand = thisPlayer.LeftHand;
				ghostButtonPressedStartTime = Time.time;
			}
			else if (IsGhostButtonDown(thisPlayer.RightHand))
			{
				ghostButtonHeldHand = thisPlayer.RightHand;
				ghostButtonPressedStartTime = Time.time;
			}
			return;
		}
		bool flag = Time.time - ghostButtonPressedStartTime >= requiredGhostButtonPressTime;
		if (flag || !IsGhostButtonPressed(ghostButtonHeldHand))
		{
			ghostButtonHeldHand = null;
			if (flag && thisPlayer.GhostModeEnabled)
			{
				thisPlayer.SituationPulse.TogglePanic();
			}
		}
	}

	private void ThisPlayer_VisibilityChanged(bool visible)
	{
		if (Menu != null && Menu.Visible)
		{
			Menu.Visible = false;
		}
	}

	private void PlayerParty_PartyUpdateReceived()
	{
		if (Menu != null && Menu.Visible)
		{
			Menu.MarkDirty();
		}
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (base.isLocal && Menu != null && Menu.Visible)
		{
			Menu.MarkDirty();
		}
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		if (base.isLocal && Menu != null && Menu.Visible)
		{
			Menu.MarkDirty();
		}
	}

	public void BroadcastPlayerMenuVisible(bool visible, PlayerHand anchorHand)
	{
		if (base.isLocal && thisPlayer.IsVisible)
		{
			base.photonView.RPC("RpcPlayerMenuVisible", PhotonTargets.Others, visible, (int)((anchorHand != null) ? anchorHand.Type : PlayerHand.HandType.Left));
		}
	}

	private void StartHandshakeFeedback(PlayerHand thisHand, PlayerHand otherHand)
	{
		StopHandshakeFeedback();
		handshakeLoopingFeedbackCoroutine = StartCoroutine(HandshakeFeedbackCoroutine(thisHand, otherHand));
	}

	private void StopHandshakeFeedback()
	{
		if (runningHandshakeAudio != null)
		{
			runningHandshakeAudio.Stop();
			runningHandshakeAudio = null;
		}
		if (runningHandshakeParticles != null)
		{
			UnityEngine.Object.Destroy(runningHandshakeParticles.gameObject);
		}
		if (handshakeLoopingFeedbackCoroutine != null)
		{
			StopCoroutine(handshakeLoopingFeedbackCoroutine);
		}
	}

	private IEnumerator HandshakeFeedbackCoroutine(PlayerHand thisHand, PlayerHand otherHand)
	{
		runningHandshakeAudio = AudioManager.Play3DSFX(handshakeChargeAudio, Vector3.Lerp(thisHand.transform.position, otherHand.transform.position, 0.5f));
		runningHandshakeParticles = UnityEngine.Object.Instantiate(handshakeChargeParticles);
		runningHandshakeParticles.Play();
		float timer = 0f;
		while (timer < handshakeChargeParticles.main.duration)
		{
			runningHandshakeParticles.transform.position = Vector3.Lerp(thisHand.transform.position, otherHand.transform.position, 0.5f);
			timer += Time.deltaTime;
			yield return null;
		}
		UnityEngine.Object.Destroy(runningHandshakeParticles.gameObject);
		runningHandshakeParticles = null;
	}

	private void PlayHandshakeSuccessParticles(PlayerHand thisHand, PlayerHand otherHand)
	{
		Vector3 vector = Vector3.Lerp(thisHand.transform.position, otherHand.transform.position, 0.5f);
		AudioManager.Play3DSFX(handshakeSuccessAudio, vector);
		if (handshakeSuccessParticles != null)
		{
			ParticleSystem particleSystem = UnityEngine.Object.Instantiate(handshakeSuccessParticles);
			particleSystem.transform.position = vector;
			particleSystem.Play();
			UnityEngine.Object.Destroy(particleSystem.gameObject, particleSystem.main.duration);
		}
	}

	[PunRPC]
	public void RpcPlayerMenuVisible(bool visible, int anchorHandId)
	{
		if (Menu != null)
		{
			Menu.MenuAnchorHand = thisPlayer.GetHand(anchorHandId);
			Menu.Visible = visible && thisPlayer.IsVisible;
		}
	}
}
[RequireComponent(typeof(PlayerUI))]
public class TournamentMonitor : Photon.MonoBehaviour
{
	private class TournamentMatchInfo
	{
		public long MatchId;

		public string RoomName;

		public string YourTeam;

		public string OtherTeam;

		public bool BringParty;

		public static TournamentMatchInfo Parse(string json)
		{
			try
			{
				Dictionary<string, object> dictionary = GAMiniJSON.Json.Deserialize(json) as Dictionary<string, object>;
				TournamentMatchInfo tournamentMatchInfo = new TournamentMatchInfo();
				tournamentMatchInfo.MatchId = (long)dictionary["MatchId"];
				tournamentMatchInfo.RoomName = (string)dictionary["RoomName"];
				tournamentMatchInfo.YourTeam = (string)dictionary["YourTeam"];
				tournamentMatchInfo.OtherTeam = (string)dictionary["OtherTeam"];
				tournamentMatchInfo.BringParty = (bool)dictionary["BringParty"];
				return tournamentMatchInfo;
			}
			catch
			{
				return null;
			}
		}
	}

	[Header("Tournament Settings")]
	[SerializeField]
	private string messageTitle = "VR World Championships";

	[SerializeField]
	private string matchReadyYesButton = "Go Play!";

	[SerializeField]
	private string matchReadyNoButton = "Forfeit";

	[SerializeField]
	[Multiline]
	private string matchReadyMessage = "It's game time!\nYour match is about to start.\n{0} vs {1}";

	[SerializeField]
	[Multiline]
	private string confirmForfeitMessage = "Are you sure you want to forfeit? Your team is counting on you!";

	[SerializeField]
	[Multiline]
	private string missedMatchMessage = "Unfortunately the match you were scheduled to play in has already started without you.";

	[SerializeField]
	private float checkServerInterval = 60f;

	private static TournamentMatchInfo matchInfo;

	private static string forfeitedMatchName;

	private static bool IsMatchAvailable()
	{
		return matchInfo != null && matchInfo.RoomName != forfeitedMatchName && (PhotonNetwork.room == null || PhotonNetwork.room.name != matchInfo.RoomName);
	}

	private void Start()
	{
		if (base.isLocal)
		{
			StartCoroutine(CheckForTournamentMatches());
			StartCoroutine(DisplayTournamentDialogs());
		}
	}

	private IEnumerator CheckForTournamentMatches()
	{
		while (true)
		{
			WWW www = new WWW("http://recroom.azurewebsites.net/api/tournament?player=" + Uri.EscapeDataString(PhotonNetwork.player.name));
			yield return www;
			matchInfo = TournamentMatchInfo.Parse(www.text);
			yield return new WaitForSeconds(checkServerInterval);
		}
	}

	private IEnumerator DisplayTournamentDialogs()
	{
		PlayerMenu playerMenu = GetComponent<PlayerUI>().Menu;
		while (true)
		{
			yield return new WaitUntil(IsMatchAvailable);
			if (matchInfo.BringParty)
			{
				yield return new WaitWhile(() => !playerMenu.Visible && IsMatchAvailable());
			}
			bool? joinGameConfirmed = null;
			if (IsMatchAvailable())
			{
				ConfirmationMenuController confirmationMenu = playerMenu.ShowConfirmation(messageTitle, string.Format(matchReadyMessage, matchInfo.YourTeam, matchInfo.OtherTeam), matchReadyYesButton, matchReadyNoButton);
				yield return new WaitWhile(() => !playerMenu.Visible);
				yield return new WaitWhile(() => playerMenu.Visible && confirmationMenu.Visible && IsMatchAvailable());
				if (confirmationMenu.Confirm == false)
				{
					confirmationMenu = playerMenu.ShowConfirmation(messageTitle, confirmForfeitMessage, matchReadyYesButton, matchReadyNoButton);
					yield return new WaitWhile(() => !playerMenu.Visible);
					yield return new WaitWhile(() => playerMenu.Visible && confirmationMenu.Visible && IsMatchAvailable());
				}
				joinGameConfirmed = confirmationMenu.Confirm;
				confirmationMenu.Visible = false;
			}
			if (!IsMatchAvailable())
			{
				playerMenu.ShowAlertMessage(messageTitle, missedMatchMessage);
				continue;
			}
			playerMenu.Visible = false;
			if (joinGameConfirmed == true)
			{
				if (!matchInfo.BringParty)
				{
					GetComponent<PlayerParty>().LeaveCurrentParty();
				}
				RecRoomSceneManager.Instance.JoinRoom(matchInfo.RoomName);
			}
			else if (joinGameConfirmed == false)
			{
				forfeitedMatchName = matchInfo.RoomName;
				yield return new WWW("http://recroom.azurewebsites.net/api/tournament/forfeit?match=" + matchInfo.MatchId + "&player=" + Uri.EscapeDataString(PhotonNetwork.player.name));
			}
		}
	}
}
public class TrackedVelocity : UnityEngine.MonoBehaviour
{
	private static TrackedVelocity loggedInstance;

	private const float RECENT_TIME = 0.05f;

	[SerializeField]
	private bool useUnscaledTime = true;

	private float previousUpdateTime;

	private Vector3 previousPosition = Vector3.zero;

	private Quaternion previousRotation = Quaternion.identity;

	private TimestampedRollingBufferVector3 linearVelocityHistory;

	private TimestampedRollingBufferVector3 angularVelocityHistory;

	public Action<TrackedVelocity> UpdateEvent;

	private float now => (!useUnscaledTime) ? Time.time : Time.unscaledTime;

	public Vector3 LatestVelocity { get; private set; }

	public Vector3 LatestAngularVelocity { get; private set; }

	public Vector3 LatestDisplacement { get; private set; }

	public Vector3 RecentLinearVelocity => GetAverageLinearVelocity(0.05f);

	public Vector3 RecentAngularVelocity => GetAverageAngularVelocity(0.05f);

	public static event Action<TrackedVelocity> LoggedInstanceUpdateEvent;

	public static void StartLogging(TrackedVelocity instance)
	{
		loggedInstance = instance;
	}

	public static void StopLogging(TrackedVelocity instance)
	{
		if (loggedInstance == instance)
		{
			loggedInstance = null;
		}
	}

	public Vector3 GetAverageLinearVelocity(float timeWindow)
	{
		if (linearVelocityHistory.TryGetAverageValueOverTime(now - timeWindow, now, out var value))
		{
			return value;
		}
		return LatestVelocity;
	}

	public Vector3 GetAverageAngularVelocity(float timeWindow)
	{
		if (angularVelocityHistory.TryGetAverageValueOverTime(now - timeWindow, now, out var value))
		{
			return value;
		}
		return LatestAngularVelocity;
	}

	public void Reset(Vector3 newVelocity, Vector3 newAngularVelocity)
	{
		LatestVelocity = newVelocity;
		LatestAngularVelocity = newAngularVelocity;
		if (linearVelocityHistory == null)
		{
			linearVelocityHistory = new TimestampedRollingBufferVector3();
		}
		if (angularVelocityHistory == null)
		{
			angularVelocityHistory = new TimestampedRollingBufferVector3();
		}
		linearVelocityHistory.Clear();
		angularVelocityHistory.Clear();
		linearVelocityHistory.Add(now, LatestVelocity);
		angularVelocityHistory.Add(now, LatestAngularVelocity);
		previousUpdateTime = now;
		previousPosition = base.transform.position;
		previousRotation = base.transform.rotation;
	}

	public void ClearDisplacement()
	{
		LatestDisplacement = Vector3.zero;
	}

	private void OnEnable()
	{
		Reset(Vector3.zero, Vector3.zero);
	}

	private void LateUpdate()
	{
		float num = now - previousUpdateTime;
		if (num > 0f)
		{
			LatestVelocity = (base.transform.position - previousPosition) / num;
			LatestDisplacement += LatestVelocity * num;
			LatestAngularVelocity = UnityExtensions.AngularVelocityFromTo(previousRotation, base.transform.rotation) / num;
			linearVelocityHistory.Add(now, LatestVelocity);
			angularVelocityHistory.Add(now, LatestAngularVelocity);
			if (UpdateEvent != null)
			{
				UpdateEvent(this);
			}
			if (TrackedVelocity.LoggedInstanceUpdateEvent != null && loggedInstance == this)
			{
				TrackedVelocity.LoggedInstanceUpdateEvent(this);
			}
		}
		previousUpdateTime = now;
		previousPosition = base.transform.position;
		previousRotation = base.transform.rotation;
	}
}
public class VoiceLineControl : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class VoiceLineControlConfig
	{
		public float zTranslationWrapLimit = 0.1f;

		public float zTranslationRate = 0.01f;

		public float jitterFPS = 20f;

		public float TTL = 0.1f;
	}

	private Vector3 initialLocalPosition;

	private Vector3 initialScale;

	private float endOfLife;

	private Vector3 minJitter;

	private Vector3 maxJitter;

	private Vector3 jitterScale;

	private float zTrans;

	[HideInInspector]
	public VoiceLineControlConfig Config;

	private Coroutine jitterCoroutine;

	private void Awake()
	{
		initialLocalPosition = base.transform.localPosition;
		initialScale = base.transform.localScale;
		minJitter = new Vector3(initialScale.x - initialScale.x / 10f, initialScale.y - initialScale.y / 10f, initialScale.z - initialScale.z / 10f);
		maxJitter = new Vector3(initialScale.x + initialScale.x / 10f, initialScale.y + initialScale.y / 10f, initialScale.z + initialScale.z / 10f);
		SetRandomJitterScale();
	}

	private void OnEnable()
	{
		zTrans = 0f;
		base.transform.localPosition = initialLocalPosition;
		base.transform.localScale = initialScale;
		if (jitterCoroutine != null)
		{
			StopCoroutine(jitterCoroutine);
		}
		StartCoroutine(JitterCoroutine());
	}

	private void SetRandomJitterScale()
	{
		float x = UnityEngine.Random.Range(minJitter.x, maxJitter.x);
		float y = UnityEngine.Random.Range(minJitter.y, maxJitter.y);
		float z = UnityEngine.Random.Range(minJitter.z, maxJitter.z);
		jitterScale = new Vector3(x, y, z);
	}

	private IEnumerator JitterCoroutine()
	{
		while (true)
		{
			yield return new WaitForSeconds(1f / Config.jitterFPS);
			SetRandomJitterScale();
		}
	}

	private void Update()
	{
		zTrans += Config.zTranslationRate * Time.deltaTime;
		zTrans %= Config.zTranslationWrapLimit;
		Vector3 localPosition = initialLocalPosition;
		localPosition.z += zTrans;
		base.transform.localPosition = localPosition;
		base.transform.localScale = jitterScale;
		if (Time.time >= endOfLife)
		{
			base.gameObject.SetActive(value: false);
		}
	}

	public void SetLifespan(float endOfLife)
	{
		this.endOfLife = endOfLife;
	}
}
[ExecuteInEditMode]
public class VoiceLinesController : Photon.MonoBehaviour
{
	[Serializable]
	public struct VoiceLineConfig
	{
		public VoiceLineControl lineControl;

		[Range(0f, 1f)]
		public float threshold;
	}

	[SerializeField]
	private Player thisPlayer;

	[SerializeField]
	private Transform voiceLinesAnchor;

	[Tooltip("We run a coroutine to make sure the icon doesn't flicker badly. This is its TTL")]
	[SerializeField]
	private float timeToDisableAnchor = 0.2f;

	[SerializeField]
	private VoiceLineConfig[] voiceLines;

	[SerializeField]
	private VoiceLineControl.VoiceLineControlConfig voiceLineConfig;

	[SerializeField]
	[Range(0f, 20f)]
	private float minVisualizationDistance = 1.5f;

	private bool _isTalking;

	public bool IsTalking
	{
		get
		{
			return _isTalking;
		}
		set
		{
			_isTalking = value;
			if (value && !thisPlayer.isLocal && base.gameObject.activeInHierarchy)
			{
				voiceLinesAnchor.gameObject.SetActive(_isTalking);
				StopAllCoroutines();
				StartCoroutine(StartNewFadeOutRoutine(voiceLinesAnchor.gameObject));
			}
		}
	}

	private IEnumerator StartNewFadeOutRoutine(GameObject obj)
	{
		yield return new WaitForSeconds(timeToDisableAnchor);
		obj.SetActive(value: false);
	}

	protected override void Awake()
	{
		base.Awake();
		VoiceLineConfig[] array = voiceLines;
		for (int i = 0; i < array.Length; i++)
		{
			VoiceLineConfig voiceLineConfig = array[i];
			voiceLineConfig.lineControl.gameObject.SetActive(value: false);
		}
	}

	protected void OnDrawGizmosSelected()
	{
		Color color = Gizmos.color;
		Gizmos.color = Color.grey;
		Gizmos.DrawWireSphere(thisPlayer.Head.transform.position, minVisualizationDistance);
		Gizmos.color = color;
	}

	private void Update()
	{
		Transform transform = Player.LocalPlayer.Head.transform;
		float num = Vector3.Distance(thisPlayer.Head.transform.position, Player.LocalPlayer.Head.transform.position);
		if (num < minVisualizationDistance || !(thisPlayer.AudioMaxForFrame > PhotonVoiceSettings.Instance.VoiceDetectionThreshold))
		{
			return;
		}
		float num2 = Mathf.InverseLerp(PhotonVoiceSettings.Instance.VoiceDetectionThreshold, 1f, thisPlayer.AudioMaxForFrame);
		for (int i = 0; i < voiceLines.Length; i++)
		{
			bool flag = num2 >= voiceLines[i].threshold;
			VoiceLineControl lineControl = voiceLines[i].lineControl;
			if (flag)
			{
				lineControl.gameObject.SetActive(flag);
				lineControl.Config = voiceLineConfig;
				lineControl.SetLifespan(Time.time + voiceLineConfig.TTL);
			}
		}
	}
}
public class VoiceLinesController2D : Photon.MonoBehaviour
{
	[Serializable]
	public struct VoiceLineConfig
	{
		public VoiceLineControl lineControl;

		[Range(0f, 1f)]
		public float threshold;
	}

	[SerializeField]
	private Player thisPlayer;

	[SerializeField]
	private Transform voiceLinesAnchor;

	[Tooltip("We run a coroutine to make sure the icon doesn't flicker badly. This is its TTL")]
	[SerializeField]
	private float timeToDisableAnchor = 0.2f;

	[SerializeField]
	private VoiceLineConfig[] voiceLines;

	[SerializeField]
	private VoiceLineConfig shoutConfig;

	[SerializeField]
	private VoiceLineControl.VoiceLineControlConfig voiceLineConfig;

	[SerializeField]
	[Range(0f, 20f)]
	private float minVisualizationDistance = 1.5f;

	[SerializeField]
	[Range(0f, 180f)]
	private float maxAngleDiff = 45f;

	[SerializeField]
	[Range(0f, 180f)]
	private float offsetAngle = 45f;

	private bool _isTalking;

	public bool IsTalking
	{
		get
		{
			return _isTalking;
		}
		set
		{
			_isTalking = value;
			if (value && !thisPlayer.isLocal && base.gameObject.activeInHierarchy)
			{
				voiceLinesAnchor.gameObject.SetActive(_isTalking);
				StopAllCoroutines();
				StartCoroutine(StartNewFadeOutRoutine(voiceLinesAnchor.gameObject));
			}
		}
	}

	private IEnumerator StartNewFadeOutRoutine(GameObject obj)
	{
		yield return new WaitForSeconds(timeToDisableAnchor);
		obj.SetActive(value: false);
	}

	protected override void Awake()
	{
		base.Awake();
		VoiceLineConfig[] array = voiceLines;
		for (int i = 0; i < array.Length; i++)
		{
			VoiceLineConfig voiceLineConfig = array[i];
			voiceLineConfig.lineControl.gameObject.SetActive(value: false);
		}
	}

	protected void OnDrawGizmosSelected()
	{
		Color color = Gizmos.color;
		Gizmos.color = Color.grey;
		Gizmos.DrawWireSphere(thisPlayer.Head.transform.position, minVisualizationDistance);
		Gizmos.color = color;
	}

	private void Update()
	{
		Transform transform = Player.LocalPlayer.Head.transform;
		float num = Vector3.Distance(thisPlayer.Head.transform.position, Player.LocalPlayer.Head.transform.position);
		if (num < minVisualizationDistance)
		{
			return;
		}
		Vector3 vector = thisPlayer.Head.transform.position - transform.position;
		if (thisPlayer.AudioMaxForFrame > PhotonVoiceSettings.Instance.VoiceDetectionThreshold)
		{
			float num2 = Mathf.InverseLerp(PhotonVoiceSettings.Instance.VoiceDetectionThreshold, 1f, thisPlayer.AudioMaxForFrame);
			if (num2 >= shoutConfig.threshold)
			{
				shoutConfig.lineControl.gameObject.SetActive(value: true);
				shoutConfig.lineControl.Config = voiceLineConfig;
				shoutConfig.lineControl.SetLifespan(Time.time + voiceLineConfig.TTL);
			}
			for (int num3 = voiceLines.Length - 1; num3 >= 0; num3--)
			{
				bool flag = num2 >= voiceLines[num3].threshold;
				VoiceLineControl lineControl = voiceLines[num3].lineControl;
				if (shoutConfig.lineControl.gameObject.activeInHierarchy)
				{
					lineControl.SetLifespan(0f);
				}
				else if (flag)
				{
					lineControl.gameObject.SetActive(flag);
					lineControl.Config = voiceLineConfig;
					lineControl.SetLifespan(Time.time + voiceLineConfig.TTL);
				}
			}
		}
		Vector3 forward = transform.forward;
		float num4 = Vector3.Angle(thisPlayer.Head.transform.right, vector.normalized);
		voiceLinesAnchor.localPosition = new Vector3(0f, 0f, 0.3f);
		float num5 = Mathf.Abs(num4 - 90f);
		if (num5 < maxAngleDiff)
		{
			float y = ((!(num4 < 90f)) ? (0f - offsetAngle) : offsetAngle);
			base.transform.localRotation = Quaternion.Euler(0f, y, 0f);
			voiceLinesAnchor.localPosition = new Vector3(0f, 0f, 0.3f);
		}
		else
		{
			base.transform.localRotation = Quaternion.identity;
		}
	}
}
namespace RecNet
{
	public class Analytics
	{
		private const string ANALYTICS_API = "api/analytics/";

		public static void SendEvent(string category, string action, string label, float? value = null, float? value2 = null, float? value3 = null)
		{
			Event(category, action, label, value, value2, value3, delegate(string e)
			{
				if (!string.IsNullOrEmpty(e))
				{
					UnityEngine.Debug.LogError("Recnet analytics failed to send event. " + e);
				}
			});
		}

		private static IEnumerator Event(string category, string action, string label, float? value, float? value2, float? value3, Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v1/session/event", "api/analytics/");
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("SessionId", Core.SessionId.ToString());
			dictionary.Add("Category", category);
			dictionary.Add("Action", action);
			dictionary.Add("Label", label);
			if (value.HasValue)
			{
				dictionary.Add("Value", value.Value.ToString("F3"));
			}
			if (value2.HasValue)
			{
				dictionary.Add("Value2", value2.Value.ToString("F3"));
			}
			if (value3.HasValue)
			{
				dictionary.Add("Value3", value3.Value.ToString("F3"));
			}
			return Core.Post(requestUri, dictionary, callback);
		}
	}
