public class ChildControlManager : SingletonMonoBehaviour<ChildControlManager>
{
	[Header("On boot height check")]
	[SerializeField]
	private float minHeightMeters = 1.22f;

	[Header("Second screen warning")]
	[SerializeField]
	private float timeBeforeFadeIn = 1f;

	[SerializeField]
	private float fadeInDuration = 0.5f;

	[SerializeField]
	private float visibleDuration = 0.5f;

	[SerializeField]
	private float fadeOutDuration = 0.5f;

	[SerializeField]
	private Canvas warningCanvas;

	[SerializeField]
	private CanvasRenderer warningElement;

	private void Awake()
	{
		SingletonMonoBehaviour<ChildControlManager>.Instance = this;
		if (warningCanvas != null && warningElement != null)
		{
			StartCoroutine(ShowSecondScreenWarning());
		}
	}

	public void Initialize()
	{
		StartCoroutine(RunHandleInitialLogin());
	}

	private IEnumerator ShowSecondScreenWarning()
	{
		warningElement.SetAlpha(0f);
		yield return new WaitForSeconds(timeBeforeFadeIn);
		warningCanvas.gameObject.SetActive(value: true);
		float t = 0f;
		while (t < fadeInDuration)
		{
			warningElement.SetAlpha(t / fadeInDuration);
			t += Time.deltaTime;
			yield return null;
		}
		yield return new WaitForSeconds(visibleDuration);
		t = 0f;
		while (t < fadeOutDuration)
		{
			warningElement.SetAlpha(1f - t / fadeInDuration);
			t += Time.deltaTime;
			yield return null;
		}
		warningCanvas.gameObject.SetActive(value: false);
	}

	private IEnumerator RunHandleInitialLogin()
	{
		while (Player.LocalPlayer == null || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		float playerHeight = Player.LocalPlayer.CurrentFloorHeightFromHead;
		if (!(playerHeight <= minHeightMeters))
		{
		}
	}
}
public class DebugManager : SingletonMonoBehaviour<DebugManager>
{
	public enum RandomName
	{
		Default = -1,
		Girl,
		Honeypot,
		Elven
	}

	[Header("Random name generation")]
	[SerializeField]
	private List<string> normalGirlNames = new List<string> { "CatGirl", "Sunny", "Tiffany", "Princesse", "NerdQueen", "Dreamdance", "Jen112" };

	[SerializeField]
	private List<string> honeypotGirlNames = new List<string> { "Feminista", "Waifu", "Fembot", "QueerGirl", "TransQueen", "Babygirl" };

	[SerializeField]
	private List<string> elvenNames = new List<string>
	{
		"Gaeralagossil", "Dúvengwen", "Dúvenith", "Grogriel", "Nalladis", "Esgarbes", "Sileviel", "Loeniel", "Peniril", "Heriadis",
		"Echuiben", "Gaelben", "Gliror", "Dregor", "Taureth", "Lhingiel", "Helviel", "Hadis", "Bastadis", "Falastor",
		"Duirronir", "Dinalagossion", "Narchon", "Orthellon", "Mallostor", "Eredhon", "Úhaelion", "Amarthon", "Thadhrion", "Nîdhel",
		"Cugiel", "Nûril", "Pedrien", "Leithriel", "Glîndaer", "Lîron", "Uilchon", "Barthion", "Ristedir"
	};

	private void Awake()
	{
		SingletonMonoBehaviour<DebugManager>.Instance = this;
	}

	public void SetRandomName(RandomName type)
	{
		if (type == RandomName.Default)
		{
			PhotonNetwork.player.name = Profiles.LocalProfile.DisplayName;
			ShowDebugMessage("Name: " + PhotonNetwork.player.name);
			return;
		}
		List<string> otherPlayerNames = new List<string>();
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			otherPlayerNames.Add(photonPlayer.name);
		}
		List<string> list = null;
		list = type switch
		{
			RandomName.Girl => normalGirlNames, 
			RandomName.Honeypot => honeypotGirlNames, 
			_ => elvenNames, 
		};
		List<string> list2 = ((otherPlayerNames == null || otherPlayerNames.Count <= 0) ? list : (from d in list
			from o in otherPlayerNames
			where !d.Contains(o)
			select d).ToList());
		if (list2.Count == 0)
		{
			ShowDebugMessage("Failed to get random name");
			return;
		}
		string text = list2.Random();
		ShowDebugMessage("Random name: " + text);
		PhotonNetwork.player.name = text;
	}

	private void ShowDebugMessage(string message)
	{
		MenuNotification.PlayNext(message, 1.5f, null, followPlayer: true, null, 0.5f);
	}
}
public class GiftManager : SingletonMonoBehaviour<GiftManager>
{
	public enum DebugGiftType
	{
		Random,
		Item,
		XP
	}

	public delegate void GiftConsumedCallback(bool successful);

	private const string GIFT_DATE_KEY = "GIFT_DATE";

	private const string GIFT_COUNT_KEY = "GIFT_COUNT";

	[SerializeField]
	[Range(0f, 1f)]
	[Tooltip("After each game you have some chance of getting a gift. This value will halve after each gift.")]
	private float perActivityGiftChance = 0.33f;

	[SerializeField]
	private int giftXP = 100;

	private Avatars.GiftPackage currentGift;

	private Coroutine receiveGiftsCoroutine;

	private GameObject lastGiftBoxObject;

	private bool LocalPlayerCloseToGiftSpawnPosition => Player.LocalPlayer != null && (Player.LocalPlayer.Head.transform.position - Player.LocalPlayer.LastSpawnPosition).magnitude <= 2f;

	public int GiftCountToday
	{
		get
		{
			if (RecroomPrefs.CurrentDay == RecroomPrefs.GetInt("GIFT_DATE", 0))
			{
				return RecroomPrefs.GetInt("GIFT_COUNT", 0);
			}
			return 0;
		}
		private set
		{
			RecroomPrefs.SetInt("GIFT_DATE", RecroomPrefs.CurrentDay);
			RecroomPrefs.SetInt("GIFT_COUNT", value);
			RecroomPrefs.Save();
		}
	}

	protected void Awake()
	{
		SingletonMonoBehaviour<GiftManager>.Instance = this;
	}

	public void Initialize()
	{
		SceneManager.sceneLoaded += SceneManager_sceneLoaded;
		SceneManager.sceneUnloaded += SceneManager_sceneUnloaded;
		PlayerObjectiveTracker.AllObjectivesCompleted += PlayerObjectiveTracker_AllObjectivesCompleted;
		if (float.TryParse(Config.GetConfigSetting("Gift.DropChance"), out var result))
		{
			perActivityGiftChance = result;
		}
		if (int.TryParse(Config.GetConfigSetting("Gift.XP"), out var result2))
		{
			giftXP = result2;
		}
	}

	private void PlayerObjectiveTracker_AllObjectivesCompleted()
	{
		StartCoroutine(RunGenerateGift());
	}

	private void SceneManager_sceneUnloaded(Scene scene)
	{
		StopReceiveGiftsCoroutine();
	}

	public void StartReceiveGiftsCoroutine()
	{
		StopReceiveGiftsCoroutine();
		receiveGiftsCoroutine = StartCoroutine(ReceiveGiftsFromQueue());
	}

	private void StopReceiveGiftsCoroutine()
	{
		if (receiveGiftsCoroutine != null)
		{
			StopCoroutine(receiveGiftsCoroutine);
			receiveGiftsCoroutine = null;
		}
		if (lastGiftBoxObject != null)
		{
			PhotonNetwork.Destroy(lastGiftBoxObject);
		}
	}

	private void SceneManager_sceneLoaded(Scene scene, LoadSceneMode mode)
	{
		if (RecRoomSceneManager.Instance != null && RecRoomSceneManager.Instance.GameManager != null)
		{
			RecRoomSceneManager.Instance.GameManager.StateChangeEvent += GameManager_StateChangeEvent;
		}
		if (PUNNetworkManager.Instance != null && (PUNNetworkManager.Instance.IsInDormRoom || PUNNetworkManager.Instance.IsInLockerRoom))
		{
			StartReceiveGiftsCoroutine();
		}
	}

	private void GameManager_StateChangeEvent(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		GameManager gameManager = RecRoomSceneManager.Instance.GameManager;
		if (!(gameManager != null))
		{
			return;
		}
		if (gameManager.CurrentState == GameStates.POST_GAME)
		{
			if (IsRandomDropGift())
			{
				StartCoroutine(RunGenerateGift());
			}
		}
		else if (gameManager.CurrentState == GameStates.GAME_RUNNING)
		{
			StopReceiveGiftsCoroutine();
		}
	}

	public IEnumerator RunGenerateGift(DebugGiftType giftType = DebugGiftType.Random)
	{
		OutfitSelection selection = null;
		float itemDropChance = 1f - (float)Mathf.Min(GiftCountToday, 3) * 0.25f;
		if (itemDropChance >= UnityEngine.Random.value)
		{
			selection = OutfitManager.Instance.CreateRandomOutfitSelection(Player.LocalPlayer.PlayerProgression.Level + 1);
		}
		else if (Profiles.LocalProfile.XpRequiredToLevelUp <= 0)
		{
			yield break;
		}
		int xp = ((!(selection != null)) ? giftXP : (giftXP / 10));
		Avatars.GiftPackage giftPackage = null;
		yield return Avatars.LocalCreateGiftPackage((!(selection != null)) ? string.Empty : selection.ToString(), xp, delegate(string e, Avatars.GiftPackage gift)
		{
			giftPackage = gift;
		});
		if (giftPackage != null)
		{
			GiftCountToday++;
		}
	}

	private IEnumerator ReceiveGiftsFromQueue()
	{
		while (Player.LocalPlayer == null || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		Vector3 lastSpawnPosition = Player.LocalPlayer.LastSpawnPosition;
		Vector3 giftPosition = lastSpawnPosition + Player.LocalPlayer.LastSpawnRotation * Vector3.forward * 0.6f;
		Quaternion giftRotation = Quaternion.LookRotation(giftPosition - lastSpawnPosition);
		while (Player.LocalPlayer != null && Avatars.GiftPackages.Count > 0 && LocalPlayerCloseToGiftSpawnPosition)
		{
			yield return DequeueGift(giftPosition, giftRotation);
		}
	}

	private IEnumerator DequeueGift(Vector3 boxPosition, Quaternion boxRotation)
	{
		yield return new WaitForSeconds(1f);
		currentGift = Avatars.GiftPackages[0];
		object[] instantiationData = new object[2]
		{
			Player.LocalPlayer.PhotonPlayer,
			GAMiniJSON.Json.Serialize(currentGift.Serialize())
		};
		lastGiftBoxObject = PhotonNetwork.Instantiate("[GiftBox]", boxPosition, boxRotation, 0, instantiationData);
		while (lastGiftBoxObject != null && LocalPlayerCloseToGiftSpawnPosition)
		{
			yield return null;
		}
		if (lastGiftBoxObject != null)
		{
			PhotonNetwork.Destroy(lastGiftBoxObject);
		}
	}

	public IEnumerator RunConsumeGift(Avatars.GiftPackage giftPackage, GiftConsumedCallback callback)
	{
		if (giftPackage != null && !giftPackage.Consumed)
		{
			OutfitSelection selection = OutfitSelection.Parse(giftPackage.AvatarItemDesc);
			string error = string.Empty;
			yield return Avatars.LocalConsumeGiftPackage(giftPackage, (selection != null) ? selection.Level : 0, delegate(string e)
			{
				error = e;
			});
			callback(string.IsNullOrEmpty(error));
			if (!string.IsNullOrEmpty(error))
			{
				UnityEngine.Debug.LogError("Server failed to consume gift " + giftPackage.Id + " : " + error);
			}
			else if (OutfitManager.Instance != null && giftPackage.HasAvatarItem)
			{
				OutfitManager.Instance.AddAvatarItemToUnlockedList(giftPackage.AvatarItemDesc);
			}
		}
		else
		{
			callback(successful: false);
			UnityEngine.Debug.LogError("Unable to consume missing or used gift.");
		}
	}

	private bool IsRandomDropGift()
	{
		float value = perActivityGiftChance / Mathf.Pow(2f, GiftCountToday - 1);
		value = Mathf.Clamp(value, 0.01f, 1f);
		return value >= UnityEngine.Random.value;
	}
}
public class OOBEFlowBase : UnityEngine.MonoBehaviour
{
	protected bool userPickedUpTool;

	protected bool userTeleported;

	protected void PlayerEvents_ToolPickupEvent(Tool tool)
	{
		userPickedUpTool = true;
	}

	protected void PlayerEvents_TeleportEvent()
	{
		userTeleported = true;
	}

	protected IEnumerator RunWaitForPlayerSpawn()
	{
		PhotonNetwork.player.SetCustomProperties("prev_activity", "oobe");
		while (Player.LocalPlayer == null || !Player.LocalPlayer.IsInitialized || !Player.LocalPlayer.HeadActivityDetected)
		{
			yield return null;
		}
	}

	protected IEnumerator RunInterractionFlow(Func<bool> condition, TutorialManager.VOClip instructionVO, TutorialManager.VOClip instructionVO2, TutorialManager.VOClip helpVO, float preHelpVODuration, int maxHelpCount = 10, Transform attentionHelperTransform = null)
	{
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(instructionVO);
		if (instructionVO2 != null)
		{
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(instructionVO2);
		}
		int count = 0;
		while (count++ < maxHelpCount)
		{
			float timer = preHelpVODuration;
			while (!condition() && timer > 0f)
			{
				timer -= Time.deltaTime;
				yield return null;
			}
			if (!condition())
			{
				if (attentionHelperTransform != null)
				{
					SingletonMonoBehaviour<TutorialManager>.Instance.PlayAttentionHelper(attentionHelperTransform.position);
				}
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(helpVO);
			}
			if (condition())
			{
				break;
			}
		}
	}

	protected void VibrateBothHands(Player player)
	{
		if (player.LeftHand != null)
		{
			player.LeftHand.Vibrate(500, 1000);
		}
		if (player.RightHand != null)
		{
			player.RightHand.Vibrate(500, 1000);
		}
	}

	protected IEnumerator RunAnimateInOut(AnimateInOut target, bool enable)
	{
		target.gameObject.SetActive(enable);
		yield return new WaitForSeconds(1f);
	}
}
public class PlayerFollowCameraManager : Photon.MonoBehaviour
{
	[SerializeField]
	private UIPlayerCamera uIPlayerCameraPrefab;

	[SerializeField]
	private Vector2 uiCameraResolutionOverride = new Vector2(320f, 270f);

	[SerializeField]
	private PlayerFollowCameraTV[] screens;

	[SerializeField]
	private Texture emptyTexture;

	private List<UIPlayerCamera> uIPlayerCameras = new List<UIPlayerCamera>();

	private int activeCameraIndex;

	private void Start()
	{
		for (int i = 0; i < screens.Length; i++)
		{
			UIPlayerCamera uIPlayerCamera = UnityEngine.Object.Instantiate(uIPlayerCameraPrefab);
			uIPlayerCamera.Resolution = uiCameraResolutionOverride;
			uIPlayerCameras.Add(uIPlayerCamera);
			screens[i].ClearScreen(emptyTexture);
		}
		Canvas[] componentsInChildren = GetComponentsInChildren<Canvas>(includeInactive: true);
		foreach (Canvas canvas in componentsInChildren)
		{
			canvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
		}
		Invoke("ReAssignCameras", 1f);
		PUNNetworkManager.Instance.OnRecRoomPlayerConnected += PUNNetworkManager_OnRecRoomPlayerConnected;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (PUNNetworkManager.Instance != null)
		{
			PUNNetworkManager.Instance.OnRecRoomPlayerConnected -= PUNNetworkManager_OnRecRoomPlayerConnected;
		}
	}

	private void Update()
	{
		for (int i = 0; i < uIPlayerCameras.Count; i++)
		{
			uIPlayerCameras[i].Camera.gameObject.SetActive(i == activeCameraIndex);
		}
		activeCameraIndex = (activeCameraIndex + 1) % uIPlayerCameras.Count;
	}

	private void ReAssignCameras()
	{
		int i;
		for (i = 0; i < PhotonNetwork.playerList.Length; i++)
		{
			screens[i].SetupCamera(PhotonNetwork.playerList[i].TagObject as Player, uIPlayerCameras[i]);
		}
		for (; i < screens.Length; i++)
		{
			screens[i].ClearScreen(emptyTexture);
		}
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
	}

	private void PUNNetworkManager_OnRecRoomPlayerConnected(Player newPlayer)
	{
		ReAssignCameras();
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		if (base.isActiveAndEnabled)
		{
			ReAssignCameras();
		}
	}
}
