public class ProgressionManager : SingletonMonoBehaviour<ProgressionManager>
{
	public enum ObjectiveType
	{
		Default = -1,
		FirstSessionOfDay = 1,
		DailyObjective1 = 10,
		DailyObjective2 = 11,
		DailyObjective3 = 12,
		OOBE_OpenMenu = 20,
		OOBE_GoToLockerRoom = 21,
		OOBE_GoToActivity = 22,
		CharadesGames = 100,
		CharadesWinsPerformer = 101,
		CharadesWinsGuesser = 102,
		DiscGolfWins = 200,
		DiscGolfGames = 201,
		DiscGolfHolesUnderPar = 202,
		DodgeballWins = 300,
		DodgeballGames = 301,
		DodgeballHits = 302,
		PaddleballGames = 400,
		PaddleballWins = 401,
		PaddleballScores = 402,
		PaintballAnyModeGames = 500,
		PaintballAnyModeWins = 501,
		PaintballAnyModeHits = 502,
		PaintballCTFWins = 600,
		PaintballCTFGames = 601,
		PaintballCTFHits = 602,
		PaintballFlagCaptures = 603,
		PaintballTeamBattleWins = 700,
		PaintballTeamBattleGames = 701,
		PaintballTeamBattleHits = 702,
		SoccerWins = 800,
		SoccerGames = 801,
		SoccerGoals = 802
	}

	[Serializable]
	public class ObjectiveTypeDescription
	{
		public string Name;

		public ObjectiveType ObjectiveType;

		public string Description;

		public string ToolTip;

		public float NotificationDelay;
	}

	[Serializable]
	public class Objective
	{
		public ObjectiveType ObjectiveType = ObjectiveType.Default;

		public int RequiredScore;
	}

	[Serializable]
	public class RangeBucket
	{
		public string Name;

		[Range(0f, 1f)]
		public float Multiplier = 1f;

		public int Max = 100;
	}

	[Header("Objectives")]
	[SerializeField]
	private ObjectiveTypeDescription[] objectiveTypeDescriptions;

	private Dictionary<ObjectiveType, ObjectiveTypeDescription> objectiveDescriptionMap = new Dictionary<ObjectiveType, ObjectiveTypeDescription>();

	private const string DAILY_LOGIN_KEY = "DAILY_LOGIN_DATE";

	public float LocalXPProgression
	{
		get
		{
			int xpRequiredToLevelUp = Profiles.LocalProfile.XpRequiredToLevelUp;
			if (xpRequiredToLevelUp <= 0)
			{
				return 1f;
			}
			return (float)Profiles.LocalProfile.XP / (float)xpRequiredToLevelUp;
		}
	}

	public bool IsFirstDailyLogin
	{
		get
		{
			return RecroomPrefs.CurrentDay != RecroomPrefs.GetInt("DAILY_LOGIN_DATE", 0);
		}
		private set
		{
			RecroomPrefs.SetInt("DAILY_LOGIN_DATE", RecroomPrefs.CurrentDay + (value ? (-1) : 0));
			RecroomPrefs.Save();
		}
	}

	private void Awake()
	{
		SingletonMonoBehaviour<ProgressionManager>.Instance = this;
		PlayerObjectiveTracker.EventBufferUpdated += PlayerObjectiveTracker_EventBufferUpdated;
	}

	public void Initialize()
	{
		ObjectiveTypeDescription[] array = objectiveTypeDescriptions;
		foreach (ObjectiveTypeDescription objectiveTypeDescription in array)
		{
			if (!objectiveDescriptionMap.ContainsKey(objectiveTypeDescription.ObjectiveType))
			{
				objectiveDescriptionMap.Add(objectiveTypeDescription.ObjectiveType, objectiveTypeDescription);
			}
			else
			{
				UnityEngine.Debug.LogError("objectiveTypeDescriptions has duplicate entries for " + objectiveTypeDescription.ObjectiveType);
			}
		}
		StartCoroutine(RunHandleInitialLogin());
	}

	private IEnumerator RunHandleInitialLogin()
	{
		while (Player.LocalPlayer == null || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		if (IsFirstDailyLogin)
		{
			LocalCompleteObjective(ObjectiveType.FirstSessionOfDay);
			IsFirstDailyLogin = false;
			if (SingletonMonoBehaviour<TutorialManager>.Instance != null && TutorialManager.OOBEState == TutorialManager.OOBEFlowState.Complete)
			{
				yield return SingletonMonoBehaviour<GiftManager>.Instance.RunGenerateGift();
			}
		}
		else
		{
			LocalCompleteObjective(ObjectiveType.Default, 1);
		}
		yield return new WaitForSeconds(1f);
		AnalyticsHelper.InitialPlayerLogin(Player.LocalPlayer.CurrentFloorHeightFromHead);
	}

	public void LocalCompleteObjective(ObjectiveType type, int additionalXp = 0)
	{
		if (type != ObjectiveType.Default || additionalXp > 0)
		{
			Profiles.LocalCompleteObjective(type, additionalXp, Player.LocalPlayer.PlayerParty.PartySize > 1);
		}
	}

	public ObjectiveTypeDescription GetObjectiveDescription(ObjectiveType objectiveType)
	{
		objectiveDescriptionMap.TryGetValue(objectiveType, out var value);
		return value;
	}

	private void PlayerObjectiveTracker_EventBufferUpdated(List<ObjectiveType> eventBuffer)
	{
		foreach (ObjectiveType item in eventBuffer)
		{
			ObjectiveTypeDescription objectiveDescription = GetObjectiveDescription(item);
			if (objectiveDescription != null)
			{
				LocalCompleteObjective(objectiveDescription.ObjectiveType);
			}
		}
	}
}
public class RecnetPreferencesMissingException : Exception
{
}
public static class RecroomPrefs
{
	public delegate void DownloadPreferencesCallback(string error);

	public class Preference
	{
		public string value;

		public bool isDirty;

		public Preference(string v, bool d)
		{
			value = v;
			isDirty = d;
		}
	}

	private static bool downloadedFromRecnet = false;

	private static bool savePreferencesToRecnetInProgress = false;

	private static bool saveRequested = false;

	private static Dictionary<string, Preference> preferences = new Dictionary<string, Preference>();

	public static int CurrentDay => DateTime.Today.DayOfYear;

	private static void CheckReady()
	{
		if (!downloadedFromRecnet)
		{
			throw new RecnetPreferencesMissingException();
		}
	}

	public static IEnumerator DowloadLocalPlayerPreferences(DownloadPreferencesCallback callback)
	{
		string error = null;
		yield return Settings.DowloadLocalPlayerSettings(delegate(string e, List<Setting> newPreferences)
		{
			error = e;
			if (string.IsNullOrEmpty(e))
			{
				foreach (Setting newPreference in newPreferences)
				{
					SetPreference(newPreference.Key, newPreference.Value, isDirty: false);
				}
			}
		});
		if (string.IsNullOrEmpty(error))
		{
			downloadedFromRecnet = true;
			string value = PlayerPrefs.GetString("google_analytics_clientid_pref_key");
			if (!string.IsNullOrEmpty(value))
			{
				SetString("google_analytics_clientid_pref_key", value);
			}
			Save();
		}
		callback(error);
	}

	private static IEnumerator RunSavePreferencesToRecnet()
	{
		CheckReady();
		savePreferencesToRecnetInProgress = true;
		bool dirtyFound = false;
		do
		{
			dirtyFound = false;
			string[] preferencesKeys = new string[preferences.Keys.Count];
			preferences.Keys.CopyTo(preferencesKeys, 0);
			saveRequested = false;
			string[] array = preferencesKeys;
			foreach (string key in array)
			{
				Preference original = preferences[key];
				if (!original.isDirty)
				{
					continue;
				}
				string originalValue = original.value;
				yield return Settings.StoreLocalPlayerSetting(new Setting
				{
					Key = key,
					Value = originalValue
				}, delegate(string e)
				{
					if (string.IsNullOrEmpty(e) && original.value == originalValue)
					{
						original.isDirty = false;
					}
				});
				dirtyFound = true;
			}
		}
		while (dirtyFound || saveRequested);
		savePreferencesToRecnetInProgress = false;
	}

	public static void Save()
	{
		saveRequested = true;
		if (!savePreferencesToRecnetInProgress)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.StartCoroutine(RunSavePreferencesToRecnet());
		}
	}

	public static void DeleteKey(string key)
	{
		CheckReady();
		SetPreference(key, null);
	}

	public static bool HasKey(string key)
	{
		CheckReady();
		return preferences.ContainsKey(key);
	}

	public static int GetInt(string key, int defaultValue)
	{
		if (HasKey(key))
		{
			return int.Parse(preferences[key].value);
		}
		return defaultValue;
	}

	public static float GetFloat(string key, float defaultValue)
	{
		if (HasKey(key))
		{
			return float.Parse(preferences[key].value);
		}
		return defaultValue;
	}

	public static string GetString(string key, string defaultValue = "")
	{
		if (HasKey(key))
		{
			return preferences[key].value;
		}
		return defaultValue;
	}

	public static void SetInt(string key, int value)
	{
		CheckReady();
		SetPreference(key, value.ToString());
	}

	public static void SetFloat(string key, float value)
	{
		CheckReady();
		SetPreference(key, value.ToString());
	}

	public static void SetString(string key, string value)
	{
		CheckReady();
		SetPreference(key, value);
	}

	private static void SetPreference(string key, string value, bool isDirty = true)
	{
		if (preferences.ContainsKey(key))
		{
			if (preferences[key].value != value)
			{
				preferences[key].value = value;
				preferences[key].isDirty = isDirty;
			}
		}
		else if (value != null)
		{
			preferences.Add(key, new Preference(value.ToString(), isDirty));
		}
	}
}
