	protected override void Start()
	{
		base.Start();
		UpdateUIText();
	}

	protected override void OnReset(Vector3 position, Quaternion rotation, bool wasEnabled, Vector3 oldPosition, bool wasCleanedUp)
	{
		base.OnReset(position, rotation, wasEnabled, oldPosition, wasCleanedUp);
		SetCollisionLayer(Layers.DynamicPhysicsIgnoreDynamicPhysics);
		base.Rigidbody.isKinematic = true;
	}
}
public class CardBox : Tool
{
	[Header("Card Spawning")]
	[SerializeField]
	private Transform cardSpawnRoot;

	[SerializeField]
	private float cardRespawnDuration = 0.5f;

	[Header("Words")]
	[SerializeField]
	private TextAsset[] wordListAssets;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip dispenseCard;

	private const string DEFAULT_WORD = "RecRoom";

	private Card[] cards;

	private List<string> wordList;

	private int[] wordIndices;

	private SynchronizedField<float> _lastCardDespawnTime;

	private SynchronizedField<bool> _dirty;

	private SynchronizedField<int> _currentCardIndex;

	private SynchronizedField<int> _previousCardIndex;

	private SynchronizedField<int> _wordIndexShuffleSeed;

	private SynchronizedField<int> _currentWordIndicesIndex;

	private SynchronizedField<int> _previousWordIndex;

	private bool dirty
	{
		get
		{
			return _dirty.Get();
		}
		set
		{
			_dirty.ForceSet(value);
		}
	}

	private float lastDirtyTime
	{
		get
		{
			return _lastCardDespawnTime.Get();
		}
		set
		{
			_lastCardDespawnTime.ForceSet(value);
		}
	}

	private int currentCardIndex
	{
		get
		{
			return _currentCardIndex.Get();
		}
		set
		{
			_currentCardIndex.ForceSet(value);
		}
	}

	private int previousCardIndex
	{
		get
		{
			return _previousCardIndex.Get();
		}
		set
		{
			_previousCardIndex.ForceSet(value);
		}
	}

	private Card previousCard => cards[previousCardIndex];

	private Card currentCard => cards[currentCardIndex];

	public string CurrentWord => (wordList.Count <= 0) ? "RecRoom" : wordList[currentWordIndex];

	public string PreviousWord => (wordList.Count <= 0) ? "RecRoom" : wordList[previousWordIndex];

	private int currentWordIndicesIndex
	{
		get
		{
			return _currentWordIndicesIndex.Get();
		}
		set
		{
			_currentWordIndicesIndex.ForceSet(value);
		}
	}

	private int currentWordIndex => wordIndices[currentWordIndicesIndex];

	private int previousWordIndex
	{
		get
		{
			return _previousWordIndex.Get();
		}
		set
		{
			_previousWordIndex.ForceSet(value);
		}
	}

	private int wordIndexShuffleSeed
	{
		get
		{
			return _wordIndexShuffleSeed.Get();
		}
		set
		{
			_wordIndexShuffleSeed.ForceSet(value);
		}
	}

	public void UpdateLocalPlayerCardVisibility(bool localPlayerIsPerformer)
	{
		if (previousCard != null)
		{
			previousCard.WordHidden = !localPlayerIsPerformer;
		}
		if (currentCard != null)
		{
			currentCard.WordHidden = !localPlayerIsPerformer;
		}
	}

	public void MasterClearCards()
	{
		if (PhotonNetwork.isMasterClient)
		{
			currentCardIndex = 1;
			previousCardIndex = 0;
			for (int i = 0; i < cards.Length; i++)
			{
				cards[i].Disable();
			}
			dirty = true;
			lastDirtyTime = (float)PhotonNetwork.time;
		}
	}

	private string[] LoadWordList(TextAsset wordListAsset)
	{
		return wordListAsset.text.Split(new string[2] { "\r\n", "\n" }, StringSplitOptions.RemoveEmptyEntries);
	}

	private void IncrementWordIndices()
	{
		previousWordIndex = currentWordIndex;
		if (currentWordIndicesIndex + 1 >= wordIndices.Length)
		{
			wordIndexShuffleSeed = (int)DateTime.Now.Ticks;
			currentWordIndicesIndex = 0;
		}
		else
		{
			currentWordIndicesIndex++;
		}
	}

	private void ShuffleWordIndices()
	{
		int num = wordIndices.Length;
		for (int i = 0; i < num; i++)
		{
			wordIndices[i] = i;
		}
		UnityExtensions.ShuffleArray(wordIndices, wordIndexShuffleSeed);
	}

	private void OnWordIndexShuffleSeedChanges()
	{
		ShuffleWordIndices();
	}

	private void CreateWordList()
	{
		wordList = new List<string>();
		for (int i = 0; i < wordListAssets.Length; i++)
		{
			wordList.AddRange(LoadWordList(wordListAssets[i]));
		}
		wordIndices = new int[wordList.Count];
	}

	protected override void Awake()
	{
		base.Awake();
		_dirty = new SynchronizedField<bool>(this, "DIRTY", defaultValue: true, SetterPermissionMode.ANYONE);
		_lastCardDespawnTime = new SynchronizedField<float>(this, "LAST_CARD_DESPAWN_TIME", -1f, SetterPermissionMode.ANYONE);
		_currentCardIndex = new SynchronizedField<int>(this, "CURRENT_CARD_INDEX", 0, SetterPermissionMode.ANYONE);
		_previousCardIndex = new SynchronizedField<int>(this, "PREVIOUS_CARD_INDEX", 0, SetterPermissionMode.ANYONE);
		_wordIndexShuffleSeed = new SynchronizedField<int>(this, "WORD_SHUFFLE_SEED", 12345, SetterPermissionMode.MASTER, OnWordIndexShuffleSeedChanges);
		_currentWordIndicesIndex = new SynchronizedField<int>(this, "CURRENT_WORD_INDICES_INDEX", 0, SetterPermissionMode.MASTER);
		_previousWordIndex = new SynchronizedField<int>(this, "PREVIOUS_WORD_INDEX", 0, SetterPermissionMode.MASTER);
		CreateWordList();
		if (PhotonNetwork.isMasterClient)
		{
			wordIndexShuffleSeed = (int)DateTime.Now.Ticks;
		}
		ShuffleWordIndices();
		cards = UnityEngine.Object.FindObjectsOfType<Card>();
		for (int i = 0; i < cards.Length; i++)
		{
			cards[i].PickupEvent += OnToolPickup;
			cards[i].ResetEvent += OnToolReset;
		}
		if (PhotonNetwork.isMasterClient && cards.Length <= 1)
		{
			UnityEngine.Debug.LogError("Not enough cards in the scene to double buffer cards.");
		}
	}

	protected override void Start()
	{
		base.Start();
		MasterClearCards();
	}

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		if (PhotonNetwork.isMasterClient && dirty && (float)PhotonNetwork.time - lastDirtyTime >= cardRespawnDuration)
		{
			int num = currentCardIndex;
			currentCardIndex = previousCardIndex;
			previousCardIndex = num;
			currentCard.MasterResetToDefault(cardSpawnRoot.position, cardSpawnRoot.rotation);
			IncrementWordIndices();
			currentCard.Word = CurrentWord;
			dirty = false;
		}
	}

	private void OnToolPickup(Tool tool)
	{
		Card component = tool.GetComponent<Card>();
		if (tool.hasAuthority && component != null)
		{
			base.photonView.RPC("RpcMasterRequestCardPickup", PhotonTargets.MasterClient, component.photonView.viewID);
		}
	}

	private void OnToolReset(Tool tool, Vector3 position, Quaternion rotation)
	{
		Card component = tool.GetComponent<Card>();
		if (component != null)
		{
			tool.RigidbodyPickup.Pickup(base.Rigidbody, base.transform.InverseTransformPoint(position), base.transform.InverseTransformRotation(rotation));
		}
	}

	private void MasterRequestCardPickup(Card card)
	{
		if (PhotonNetwork.isMasterClient && card == currentCard)
		{
			previousCard.Disable();
			if (!dirty)
			{
				dirty = true;
				lastDirtyTime = (float)PhotonNetwork.time;
			}
			base.photonView.RPC("RpcOnCardPickup", PhotonTargets.All);
		}
	}

	[PunRPC]
	private void RpcMasterRequestCardPickup(int cardPhotonViewId)
	{
		PhotonView photonView = PhotonView.Find(cardPhotonViewId);
		Card card = ((!(photonView != null)) ? null : photonView.GetComponent<Card>());
		if (card != null)
		{
			MasterRequestCardPickup(card);
		}
	}

	[PunRPC]
	private void RpcOnCardPickup()
	{
		AudioManager.Play3DSFX(dispenseCard, base.transform);
	}
}
public struct CastColliderHit
{
	public Rigidbody Rigidbody;

	public Collider Collider;

	public Vector3 Point;

	public float Distance;

	public Vector3 Normal;

	public Vector3 CastColliderNormal;

	public Collider CastCollider;
}
public abstract class CastCollider
{
	protected Collider collider;

	protected Rigidbody rigidbody;

	private Vector3 positionRigidbodySpace;

	private Quaternion rotationRigidbodySpace;

	private const int MAX_RAYCAST_HITS = 256;

	private static RaycastHit[] hits = new RaycastHit[256];

	public CastCollider(Rigidbody rigidbody, Collider collider, Vector3 colliderCenter)
	{
		this.rigidbody = rigidbody;
		this.collider = collider;
		Vector3 position = this.collider.transform.TransformPoint(colliderCenter);
		positionRigidbodySpace = this.rigidbody.transform.InverseTransformPoint(position);
		rotationRigidbodySpace = this.rigidbody.transform.InverseTransformRotation(collider.transform.rotation);
	}

	public int Cast(Vector3 initialPosition, Quaternion orientation, Vector3 direction, float distance, int layerMask, CastColliderHit[] results)
	{
		int num = 0;
		initialPosition = Matrix4x4.TRS(initialPosition, orientation, rigidbody.transform.lossyScale).MultiplyPoint(positionRigidbodySpace);
		orientation *= rotationRigidbodySpace;
		if (collider.gameObject.activeSelf && collider.enabled)
		{
			int num2 = CastNoAlloc(initialPosition, orientation, direction, distance, layerMask, hits);
			for (int i = 0; i < num2; i++)
			{
				if (num >= results.Length)
				{
					break;
				}
				if (hits[i].collider.enabled && hits[i].collider.gameObject.activeSelf && (!(hits[i].point.magnitude < Mathf.Epsilon) || !(hits[i].distance < Mathf.Epsilon)))
				{
					results[num].Rigidbody = hits[i].rigidbody;
					results[num].Collider = hits[i].collider;
					results[num].Point = hits[i].point;
					results[num].Distance = hits[i].distance;
					results[num].Normal = hits[i].normal;
					results[num].CastColliderNormal = GetColliderNormal(initialPosition, orientation, initialPosition + direction * hits[i].distance);
					results[num].CastCollider = collider;
					num++;
				}
			}
		}
		return num;
	}

	protected abstract int CastNoAlloc(Vector3 origin, Quaternion orientation, Vector3 direction, float distance, int layerMask, RaycastHit[] results);

	protected abstract Vector3 GetColliderNormal(Vector3 origin, Quaternion orientation, Vector3 collisionPoint);
}
[DisallowMultipleComponent]
[RequireComponent(typeof(Rigidbody))]
public class CastCollisionRigidbody : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float castDuration = 0.05f;

	private Rigidbody rigidbody;

	private List<CastCollider> castColliders = new List<CastCollider>();

	private List<CastColliderHit> latestHits = new List<CastColliderHit>();

	private const int MAX_RAYCAST_HITS = 256;

	private static CastColliderHit[] hits = new CastColliderHit[256];

	public Rigidbody Rigidbody => rigidbody;

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
		BoxCollider[] componentsInChildren = GetComponentsInChildren<BoxCollider>();
		foreach (BoxCollider boxCollider in componentsInChildren)
		{
			castColliders.Add(new BoxCastCollider(rigidbody, boxCollider, boxCollider.center));
		}
		SphereCollider[] componentsInChildren2 = GetComponentsInChildren<SphereCollider>();
		foreach (SphereCollider sphereCollider in componentsInChildren2)
		{
			castColliders.Add(new SphereCastCollider(rigidbody, sphereCollider, sphereCollider.center));
		}
	}

	public bool Cast(Vector3 initialPosition, Quaternion initialRotation, Vector3 direction, float distance, int layerMask, out CastColliderHit closestHit)
	{
		RunCast(initialPosition, initialRotation, direction, distance, layerMask);
		bool flag = false;
		int index = -1;
		float num = float.MaxValue;
		for (int i = 0; i < latestHits.Count; i++)
		{
			if (latestHits[i].Distance < num)
			{
				flag = true;
				index = i;
				num = latestHits[i].Distance;
			}
		}
		closestHit = ((!flag) ? default(CastColliderHit) : latestHits[index]);
		return flag;
	}

	public void CastToCollide(Vector3 initialPosition, Vector3 targetPosition, Quaternion targetRotation, Vector3 velocity, int layerMask)
	{
		if (!rigidbody.gameObject.activeSelf)
		{
			return;
		}
		Vector3 normalized = velocity.normalized;
		float num = 2f * castDuration * velocity.magnitude;
		initialPosition -= normalized * num / 2f;
		RunCast(initialPosition, targetRotation, normalized, num, layerMask);
		foreach (CastColliderHit latestHit in latestHits)
		{
			latestHit.Rigidbody.AddForceAtPosition(Vector3.Project(velocity, latestHit.CastColliderNormal), latestHit.Point, ForceMode.VelocityChange);
		}
	}

	private void RunCast(Vector3 initialPosition, Quaternion initialRotation, Vector3 direction, float distance, int layerMask)
	{
		latestHits.Clear();
		foreach (CastCollider castCollider in castColliders)
		{
			int num = castCollider.Cast(initialPosition, initialRotation, direction, distance, layerMask, hits);
			int i;
			for (i = 0; i < num; i++)
			{
				int num2 = -1;
				num2 = ((!(hits[i].Rigidbody != null)) ? latestHits.FindIndex((CastColliderHit x) => x.Collider == hits[i].Collider) : latestHits.FindIndex((CastColliderHit x) => x.Rigidbody == hits[i].Rigidbody));
				if (num2 < 0)
				{
					latestHits.Add(hits[i]);
				}
				else if (latestHits[num2].Distance < hits[i].Distance)
				{
					latestHits[num2] = hits[i];
				}
			}
		}
	}
}
