	[Header("Surface Config")]
	[SerializeField]
	private DrawingSurfaceType drawingSurfaceType;

	[Header("Coordinate Mapping")]
	[SerializeField]
	private Transform drawingRectMin;

	[SerializeField]
	private Transform drawingRectMax;

	private Rect drawingBounds = default(Rect);

	[Header("Rendering")]
	[SerializeField]
	private Renderer surfaceRenderer;

	[SerializeField]
	private int resolution = 512;

	[SerializeField]
	private AntiAliasing antiAliasing = AntiAliasing.EIGHT;

	private RenderTexture renderTexture;

	private CommandBuffer commandBuffer;

	[Header("Texture Serialization")]
	[SerializeField]
	private int xChunks = 8;

	[SerializeField]
	private int yChunks = 8;

	private bool modified;

	private Texture2D incomingTex;

	private List<DrawingToolBase> drawingTools = new List<DrawingToolBase>();

	private Dictionary<int, byte[]> encodedChunks = new Dictionary<int, byte[]>();

	[Header("RPC Staggering")]
	[SerializeField]
	private RandomWaitTimeConfig staggerWaitTime = new RandomWaitTimeConfig
	{
		initialWait = 2f,
		randomMin = 0f,
		randomMax = 3f
	};

	[SerializeField]
	private RandomWaitTimeConfig perChunkWaitTime = new RandomWaitTimeConfig
	{
		initialWait = 0.1f,
		randomMin = 0f,
		randomMax = 0.1f
	};

	public float WHRation => surfaceRenderer.transform.localScale.x / surfaceRenderer.transform.localScale.y;

	public int PhotonId => base.photonView.viewID;

	public Vector3 Normal => base.transform.forward;

	public void MarkModified()
	{
		modified = true;
		encodedChunks.Clear();
	}

	protected override void Awake()
	{
		if (surfaceRenderer == null)
		{
			throw new Exception("I need a surface renderer to not crash!");
		}
		base.Awake();
		renderTexture = new RenderTexture(resolution, resolution, 0, RenderTextureFormat.ARGB32);
		renderTexture.antiAliasing = (int)antiAliasing;
		Texture texture = surfaceRenderer.material.GetTexture("_DrawingTex");
		Graphics.Blit(texture, renderTexture);
		surfaceRenderer.material.SetTexture("_DrawingTex", renderTexture);
		if (drawingRectMin != null && drawingRectMax != null)
		{
			drawingBounds = Rect.MinMaxRect(drawingRectMax.localPosition.x, drawingRectMin.localPosition.y, drawingRectMin.localPosition.x, drawingRectMax.localPosition.y);
			return;
		}
		throw new Exception("Drawing Bounds need to be set for DrawingSurface to work!");
	}

	private void Start()
	{
		RebuildCommandBuffer();
	}

	private void RebuildCommandBuffer()
	{
		if (commandBuffer != null)
		{
			Camera.main.RemoveCommandBuffer(CameraEvent.AfterEverything, commandBuffer);
			commandBuffer = null;
		}
		if (drawingTools.Count <= 0)
		{
			return;
		}
		commandBuffer = new CommandBuffer();
		commandBuffer.name = "Draw Mesh";
		commandBuffer.SetRenderTarget(renderTexture);
		foreach (DrawingToolBase drawingTool in drawingTools)
		{
			commandBuffer.DrawRenderer(drawingTool.DrawingRenderer, drawingTool.Material);
		}
		Camera.main.AddCommandBuffer(CameraEvent.AfterEverything, commandBuffer);
	}

	public void AddDrawingTool(DrawingToolBase drawingTool)
	{
		drawingTools.Add(drawingTool);
		RebuildCommandBuffer();
	}

	public void RemoveDrawingTool(DrawingToolBase drawingTool)
	{
		drawingTools.Remove(drawingTool);
		RebuildCommandBuffer();
	}

	private void OnDrawGizmos()
	{
		if (drawingRectMin != null && drawingRectMax != null)
		{
			Gizmos.color = Color.red.WithAlpha(0.5f);
			Gizmos.DrawLine(drawingRectMin.position, drawingRectMax.position);
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		RenderTexture.active = null;
	}

	public float DistanceToPlane(Vector3 worldPos)
	{
		return base.transform.InverseTransformPoint(worldPos).z;
	}

	public bool IsOverPlane(Vector3 position, out Vector2 onPlanePos, out float distanceToPlane)
	{
		Vector3 vector = base.transform.InverseTransformPoint(position);
		distanceToPlane = vector.z;
		vector.z = 0f;
		onPlanePos = vector;
		return drawingBounds.Contains(vector);
	}

	public Vector2 WorldToNormalizedBoardPos(Vector3 worldPos)
	{
		return NormalizedBoardSpace(WorldToBoardSpace(worldPos));
	}

	public Vector3 OnDrawingPlane(Vector3 worldPos)
	{
		Vector3 vector = worldPos - drawingRectMin.position;
		Vector3 vector2 = Vector3.Project(vector, Normal);
		return worldPos - vector2;
	}

	public Vector3 WorldToBoardSpace(Vector3 worldPos)
	{
		Vector3 position = OnDrawingPlane(worldPos);
		return base.transform.InverseTransformPoint(position);
	}

	public Vector2 NormalizedBoardSpace(Vector2 localPos)
	{
		Vector2 point = localPos * -1f;
		Vector2 vector = Rect.PointToNormalized(drawingBounds, point);
		return vector * 2f - new Vector2(1f, 1f);
	}

	public void OnSurfaceTriggerEnter(Collider other)
	{
		if (other.CompareTag("BrushTool"))
		{
			DrawingToolBase componentInParent = other.GetComponentInParent<DrawingToolBase>();
			if (componentInParent != null && (componentInParent.DrawingSurfaceType & drawingSurfaceType) != DrawingSurfaceType.None)
			{
				componentInParent.CurrentSurface = this;
				AddDrawingTool(componentInParent);
			}
		}
	}

	public void OnSurfaceTriggerExit(Collider other)
	{
		if (other.CompareTag("BrushTool"))
		{
			DrawingToolBase componentInParent = other.GetComponentInParent<DrawingToolBase>();
			if (componentInParent != null && (componentInParent.DrawingSurfaceType & drawingSurfaceType) != DrawingSurfaceType.None)
			{
				RemoveDrawingTool(componentInParent);
				componentInParent.CurrentSurface = null;
			}
		}
	}

	public void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (PhotonNetwork.isMasterClient && modified)
		{
			StartCoroutine(SendTextureRoutine(newPlayer));
		}
	}

	private static int IntKey(ushort x, ushort y)
	{
		return (x << 16) | y;
	}

	private IEnumerator SendTextureRoutine(PhotonPlayer newPlayer)
	{
		yield return new WaitForSecondsRealtime(staggerWaitTime.GetTime());
		int xWidth = resolution / xChunks;
		int yHeight = resolution / yChunks;
		Texture2D tex = new Texture2D(xWidth, yHeight);
		int totalBytes = 0;
		for (ushort x = 0; x < xChunks; x++)
		{
			for (ushort y = 0; y < yChunks; y++)
			{
				int key = IntKey(x, y);
				if (!encodedChunks.TryGetValue(key, out var bytes))
				{
					RenderTexture active = RenderTexture.active;
					RenderTexture.active = renderTexture;
					tex.ReadPixels(new Rect(x * xWidth, y * yHeight, xWidth, yHeight), 0, 0);
					tex.Apply();
					RenderTexture.active = active;
					bytes = tex.EncodeToPNG();
					encodedChunks[key] = bytes;
				}
				totalBytes += bytes.Length;
				bool lastChunk = x == xChunks - 1 && y == yChunks - 1;
				base.photonView.RPC("RpcSetTexture", newPlayer, (int)x, (int)y, bytes, lastChunk);
				yield return new WaitForSecondsRealtime(perChunkWaitTime.GetTime());
			}
		}
		UnityEngine.Object.Destroy(tex);
		UnityEngine.Debug.Log($"Texture of size {totalBytes}b sent");
	}

	[PunRPC]
	private void RpcSetTexture(int x, int y, byte[] bytes, bool lastChunk)
	{
		if (incomingTex == null)
		{
			incomingTex = new Texture2D(resolution, resolution);
		}
		int num = resolution / xChunks;
		int num2 = resolution / yChunks;
		Texture2D texture2D = new Texture2D(num, num2);
		texture2D.LoadImage(bytes);
		incomingTex.SetPixels(x * num, (yChunks - 1 - y) * num2, num, num2, texture2D.GetPixels());
		incomingTex.Apply();
		if (lastChunk)
		{
			Graphics.Blit(incomingTex, renderTexture);
			UnityEngine.Object.Destroy(incomingTex);
			UnityEngine.Object.Destroy(texture2D);
			incomingTex = null;
		}
	}
}
public abstract class DrawingToolBase : Tool
{
	[Header("Brush Properties")]
	[SerializeField]
	private DrawingSurface.DrawingSurfaceType _drawingSurfaceType;

	[SerializeField]
	private Transform _brushTip;

	[SerializeField]
	protected float maxDrawingOffset = 0.1f;

	[SerializeField]
	protected float minControlPointDistance = 0.001f;

	[SerializeField]
	private AnimationCurve vibrationCurve = AnimationCurve.Linear(0f, 1f, 1f, 1f);

	[SerializeField]
	private float minVelocityForVibrate = 0.001f;

	[SerializeField]
	private Material _material;

	private Vector2 lastPosition = Vector2.zero;

	private Vector2 planePos = Vector2.zero;

	private Vector2 normalizedPlanePos = Vector2.zero;

	protected float distanceToPlane = float.MaxValue;

	private TimestampedRollingBufferVector3 velocityBuffer = new TimestampedRollingBufferVector3();

	private bool _isDrawing;

	private GameObject drawingObject;

	private MeshFilter drawingMeshFilter;

	protected Mesh drawingMesh;

	private float timeSinceLastPulse = float.MaxValue;

	private float pulseInterval;

	[SerializeField]
	private float soundVelocityThreshold;

	[SerializeField]
	private RecRoomAudioClip brushDownClip;

	[SerializeField]
	private RecRoomAudioClip brushLoopClip;

	private SFXAudioSource loopingSource;

	public DrawingSurface CurrentSurface { get; set; }

	public DrawingSurface.DrawingSurfaceType DrawingSurfaceType => _drawingSurfaceType;

	public Transform BrushTip => _brushTip;

	public Material Material => _material;

	public Vector2 Velocity { get; private set; }

	public Vector2 OnPlanePos => planePos;

	public Vector2 NormalizedPlanePos => normalizedPlanePos;

	public bool IsDrawing
	{
		get
		{
			return _isDrawing;
		}
		set
		{
			if (_isDrawing != value)
			{
				_isDrawing = value;
				if (_isDrawing)
				{
					PenDown();
				}
				else
				{
					PenUp();
				}
			}
		}
	}

	public MeshRenderer DrawingRenderer { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		drawingMesh = new Mesh();
		drawingObject = new GameObject(base.gameObject.name + "_Drawing");
		drawingMeshFilter = drawingObject.AddComponent<MeshFilter>();
		drawingMeshFilter.mesh = drawingMesh;
		DrawingRenderer = drawingObject.AddComponent<MeshRenderer>();
		DrawingRenderer.shadowCastingMode = ShadowCastingMode.Off;
		DrawingRenderer.receiveShadows = false;
		DrawingRenderer.motionVectorGenerationMode = MotionVectorGenerationMode.ForceNoMotion;
		DrawingRenderer.materials = new Material[0];
		DrawingRenderer.lightProbeUsage = LightProbeUsage.Off;
		DrawingRenderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
		drawingObject.transform.SetParent(base.transform);
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.red.WithAlpha(0.5f);
		Gizmos.DrawRay(base.transform.position, base.transform.up * 0.25f);
		Gizmos.color = Color.blue.WithAlpha(0.5f);
		Gizmos.DrawRay(base.transform.position, base.transform.forward * 0.25f);
	}

	protected virtual void Update()
	{
		bool isDrawing = false;
		if (CurrentSurface != null && CurrentSurface.IsOverPlane(BrushTip.transform.position, out planePos, out distanceToPlane))
		{
			normalizedPlanePos = CurrentSurface.NormalizedBoardSpace(planePos);
			if (distanceToPlane < maxDrawingOffset)
			{
				Vector2 vector = planePos - lastPosition;
				velocityBuffer.Add(Time.time, vector);
				Vector3 value = vector;
				if (velocityBuffer.TryGetAverageValueOverTime(Time.time - 0.1f, Time.time, out value))
				{
					Velocity = value;
				}
				lastPosition = planePos;
				isDrawing = true;
				AuthorityAddControlPoint(CurrentSurface);
			}
		}
		IsDrawing = isDrawing;
		VibrationUpdate();
		SoundUpdate();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		UnityEngine.Object.Destroy(drawingObject);
	}

	protected abstract void AuthorityAddControlPoint(DrawingSurface currentSurface);

	protected abstract void AuthorityFinishStroke();

	private void VibrationUpdate()
	{
		if (!(base.Owner != null) || !base.Owner.isLocal || !IsDrawing)
		{
			return;
		}
		pulseInterval = ((!(Velocity.magnitude > minVelocityForVibrate)) ? float.MaxValue : vibrationCurve.Evaluate(Velocity.magnitude));
		if (timeSinceLastPulse >= pulseInterval)
		{
			if (base.HolderHand != null && base.HolderHand.ControllerIO != null)
			{
				base.HolderHand.ControllerIO.Vibrate(1, 500);
			}
			timeSinceLastPulse = 0f;
		}
		timeSinceLastPulse += Time.deltaTime;
	}

	public void PenDown()
	{
		if (brushDownClip != null)
		{
			AudioManager.Play3DSFX(brushDownClip, base.transform);
		}
		if (base.Owner.isLocal && base.HolderHand != null && base.HolderHand.ControllerIO != null)
		{
			base.HolderHand.ControllerIO.Vibrate(1, 1000);
		}
	}

	public void PenUp()
	{
		if (base.Owner.isLocal && base.HolderHand != null && base.HolderHand.ControllerIO != null)
		{
			base.HolderHand.ControllerIO.Vibrate(1, 1000);
		}
	}

	protected virtual void SoundUpdate()
	{
		if (brushLoopClip == null || !(brushLoopClip.audioClip != null))
		{
			return;
		}
		if (IsDrawing && Velocity.magnitude > soundVelocityThreshold)
		{
			if (loopingSource == null)
			{
				loopingSource = AudioManager.Play3DSFX(brushLoopClip, base.transform);
				loopingSource.Loop();
			}
		}
		else if (loopingSource != null)
		{
			loopingSource.Stop();
			loopingSource = null;
		}
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		PenUp();
	}
}
public abstract class DrawingToolBase<ControlPointType> : DrawingToolBase where ControlPointType : class, IDrawingControlPoint
{
	public class Stroke
	{
		public readonly int SurfaceId;

		public readonly List<ControlPointType> controlPoints = new List<ControlPointType>();

		public Stroke(int surfaceId, ControlPointType startPoint)
		{
			SurfaceId = surfaceId;
			controlPoints.Add(startPoint);
		}
	}

	protected Stroke currentStroke;

	protected ControlPointType lastControlPoint;

	protected List<Vector3> vertices = new List<Vector3>();

	protected List<Vector2> uvs = new List<Vector2>();

	protected List<int> tris = new List<int>();

	private bool meshDirty;

	protected override void Update()
	{
		base.Update();
		if (!base.IsDrawing && currentStroke != null)
		{
			AuthorityFinishStroke();
		}
		if (meshDirty)
		{
			CleanAndUpdateMesh();
		}
	}

	protected abstract Stroke CreateNewStroke(DrawingSurface drawingSurface, ControlPointType firstControlPoint);

	protected abstract ControlPointType CreateNewControlPoint();

	public void StartStroke(int surfaceId, ControlPointType firstPoint)
	{
		DrawingSurface component = PhotonView.Find(surfaceId).GetComponent<DrawingSurface>();
		StartStroke(component, firstPoint);
	}

	private void StartStroke(DrawingSurface surface, ControlPointType firstPoint)
	{
		base.CurrentSurface = surface;
		base.CurrentSurface.MarkModified();
		currentStroke = CreateNewStroke(base.CurrentSurface, firstPoint);
		MarkDirty();
	}

	public void FinishStroke()
	{
		ClearMesh();
		currentStroke = null;
		lastControlPoint = (ControlPointType)null;
	}

	private void MarkDirty()
	{
		meshDirty = true;
		if (base.CurrentSurface != null)
		{
			base.CurrentSurface.MarkModified();
		}
	}

	public void AddControlPoint(DrawingSurface surface, ControlPointType newCP)
	{
		if (currentStroke == null)
		{
			StartStroke(surface, newCP);
		}
		else
		{
			currentStroke.controlPoints.Add(newCP);
			lastControlPoint = newCP;
		}
		MarkDirty();
	}

	private void CleanAndUpdateMesh()
	{
		ClearMesh();
		if (!UpdateMesh())
		{
		}
	}

	protected abstract bool UpdateMesh();

	private void ClearMesh()
	{
		vertices.Clear();
		uvs.Clear();
		tris.Clear();
		if (drawingMesh != null)
		{
			drawingMesh.Clear();
		}
		meshDirty = false;
	}

	protected override void AuthorityAddControlPoint(DrawingSurface surface)
	{
		if (base.hasAuthority && (lastControlPoint == null || Vector2.Distance(base.NormalizedPlanePos, lastControlPoint.Position) > minControlPointDistance))
		{
			ControlPointType val = CreateNewControlPoint();
			base.photonView.RPC("RpcAddControlPoint", PhotonTargets.All, surface.photonView.viewID, val);
		}
	}

	protected override void AuthorityFinishStroke()
	{
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcFinishStroke", PhotonTargets.All);
		}
	}

	[PunRPC]
	public void RpcAddControlPoint(int surfaceId, ControlPointType controlPoint)
	{
		DrawingSurface component = PhotonView.Find(surfaceId).GetComponent<DrawingSurface>();
		AddControlPoint(component, controlPoint);
	}

	[PunRPC]
	public void RpcFinishStroke()
	{
		FinishStroke();
	}
}
public class DrawingToolRigidbodyPickup : RigidbodyPickup
{
	[SerializeField]
	private bool forceRotationNearSurface;

	[SerializeField]
	private AnimationCurve nearSurfaceRotationCurve = AnimationCurve.Linear(0f, 1f, 1f, 0f);

	public DrawingToolBase drawingTool;

	public override Quaternion TargetRigidbodyRotation
	{
		get
		{
			if (forceRotationNearSurface && drawingTool.CurrentSurface != null)
			{
				Quaternion targetRigidbodyRotation = base.TargetRigidbodyRotation;
				Vector3 fromDirection = targetRigidbodyRotation * Vector3.up;
				Vector3 normal = drawingTool.CurrentSurface.Normal;
				Quaternion quaternion = Quaternion.FromToRotation(fromDirection, normal);
				float time = drawingTool.CurrentSurface.DistanceToPlane(drawingTool.BrushTip.transform.position);
				float t = nearSurfaceRotationCurve.Evaluate(time);
				return Quaternion.Lerp(targetRigidbodyRotation, quaternion * targetRigidbodyRotation, t);
			}
			return base.TargetRigidbodyRotation;
		}
	}

	public override Vector3 TargetRigidbodyPosition
	{
		get
		{
			Vector3 targetRigidbodyPosition = base.TargetRigidbodyPosition;
			if (drawingTool.CurrentSurface != null && drawingTool.CurrentSurface.IsOverPlane(targetRigidbodyPosition, out var onPlanePos, out var distanceToPlane) && distanceToPlane < 0f)
			{
				return drawingTool.CurrentSurface.transform.TransformPoint(onPlanePos);
			}
			return targetRigidbodyPosition;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		drawingTool = GetComponent<DrawingToolBase>();
	}
}
public class EraserDrawingTool : DrawingToolBase<EraserDrawingTool.ControlPoint>
{
	public class ControlPoint : IDrawingControlPoint
	{
		public Vector3 center = Vector3.zero;

		public Vector3 tr = Vector3.zero;

		public Vector3 tl = Vector3.zero;

		public Vector3 bl = Vector3.zero;

		public Vector3 br = Vector3.zero;

		private Vector3[] allPoints;

		private int[] indices = new int[4] { 0, 1, 2, 3 };

		private Vector3 surfaceNormal;

		private const int byteSize = 40;

		public static readonly byte[] memVector2 = new byte[40];

		public Vector2 Position => center;

		public Vector2 Tangent
		{
			get
			{
				return Vector2.one;
			}
			set
			{
			}
		}

		public ControlPoint()
		{
		}

		public ControlPoint(Vector3 center, Vector3 tr, Vector3 tl, Vector3 bl, Vector3 br, Vector3 surfaceNormal)
		{
			this.center = center;
			this.tr = tr;
			this.tl = tl;
			this.bl = bl;
			this.br = br;
			this.surfaceNormal = surfaceNormal;
			allPoints = new Vector3[4] { tr, tl, bl, br };
		}

		public void AddVertsAndUVs(List<Vector3> verts, List<Vector2> uvs)
		{
			verts.Add(tr);
			verts.Add(tl);
			verts.Add(bl);
			verts.Add(br);
			Vector2 item = Vector3.one;
			uvs.Add(item);
			item.x = 0f;
			uvs.Add(item);
			item.y = 0f;
			uvs.Add(item);
			item.x = 1f;
			uvs.Add(item);
		}

		public void AddTris(List<int> tris, int startIndex)
		{
			tris.Add(startIndex);
			tris.Add(startIndex + 2);
			tris.Add(startIndex + 1);
			tris.Add(startIndex);
			tris.Add(startIndex + 3);
			tris.Add(startIndex + 2);
		}

		public void AddInitialQuad(List<Vector3> verts, List<Vector2> uvs, List<int> tris)
		{
			AddVertsAndUVs(verts, uvs);
			AddTris(tris, 0);
		}

		public List<int> EdgeVerts(ControlPoint other, bool trailing = false)
		{
			List<int> list = new List<int>(indices);
			float[] xDist = new float[4];
			float[] yDist = new float[4];
			Vector3 vector = other.center - center;
			Vector3 vector2 = Vector3.Lerp(center, other.center, 0.5f);
			Vector3 normalized = vector.normalized;
			Vector3 onNormal = Vector3.Cross(normalized, surfaceNormal);
			for (int i = 0; i < allPoints.Length; i++)
			{
				Vector3 vector3 = Vector3.Project(allPoints[i] - vector2, onNormal);
				UnityEngine.Debug.DrawRay(allPoints[i], vector3, Color.cyan);
				float num = Mathf.Sign(Vector3.Cross(normalized, vector3).y);
				xDist[i] = vector3.magnitude * num;
				Vector3 vector4 = Vector3.Project(vector2 - allPoints[i], normalized);
				UnityEngine.Debug.DrawRay(allPoints[i], vector4 * 0.5f, Color.magenta);
				yDist[i] = vector4.magnitude;
			}
			list.Sort((int a, int b) => yDist[a].CompareTo(yDist[b]));
			List<int> range = list.GetRange(0, 3);
			range.Sort((int a, int b) => trailing ? xDist[a].CompareTo(xDist[b]) : xDist[b].CompareTo(xDist[a]));
			int num2 = 1;
			foreach (int item in range)
			{
				UnityEngine.Debug.DrawRay(allPoints[item], Vector3.up * 0.25f * num2++, Color.blue);
			}
			return range;
		}

		public static short Serialize(StreamBuffer outStream, object customobject)
		{
			ControlPoint controlPoint = (ControlPoint)customobject;
			lock (memVector2)
			{
				byte[] array = memVector2;
				int targetOffset = 0;
				Protocol.Serialize(controlPoint.center.x, array, ref targetOffset);
				Protocol.Serialize(controlPoint.center.y, array, ref targetOffset);
				Protocol.Serialize(controlPoint.tr.x, array, ref targetOffset);
				Protocol.Serialize(controlPoint.tr.y, array, ref targetOffset);
				Protocol.Serialize(controlPoint.tl.x, array, ref targetOffset);
				Protocol.Serialize(controlPoint.tl.y, array, ref targetOffset);
				Protocol.Serialize(controlPoint.bl.x, array, ref targetOffset);
				Protocol.Serialize(controlPoint.bl.y, array, ref targetOffset);
				Protocol.Serialize(controlPoint.br.x, array, ref targetOffset);
				Protocol.Serialize(controlPoint.br.y, array, ref targetOffset);
				outStream.Write(array, 0, 40);
			}
			return 40;
		}

		public static object Deserialize(StreamBuffer inStream, short length)
		{
			ControlPoint controlPoint = new ControlPoint();
			lock (memVector2)
			{
				inStream.Read(memVector2, 0, 40);
				int offset = 0;
				Protocol.Deserialize(out controlPoint.center.x, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.center.y, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.tr.x, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.tr.y, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.tl.x, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.tl.y, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.bl.x, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.bl.y, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.br.x, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.br.y, memVector2, ref offset);
				return controlPoint;
			}
		}
	}

	public Transform TR;

	public Transform TL;

	public Transform BL;

	public Transform BR;

	protected override Stroke CreateNewStroke(DrawingSurface drawingSurface, ControlPoint firstControlPoint)
	{
		lastControlPoint = firstControlPoint;
		return new Stroke(drawingSurface.PhotonId, firstControlPoint);
	}

	protected override ControlPoint CreateNewControlPoint()
	{
		Vector2 vector = base.CurrentSurface.WorldToNormalizedBoardPos(base.transform.position);
		Vector2 vector2 = base.CurrentSurface.WorldToNormalizedBoardPos(TL.transform.position);
		Vector2 vector3 = base.CurrentSurface.WorldToNormalizedBoardPos(TR.transform.position);
		Vector2 vector4 = base.CurrentSurface.WorldToNormalizedBoardPos(BR.transform.position);
		Vector2 vector5 = base.CurrentSurface.WorldToNormalizedBoardPos(BL.transform.position);
		return new ControlPoint(vector, vector3, vector2, vector5, vector4, base.CurrentSurface.Normal);
	}

	protected override bool UpdateMesh()
	{
		vertices.Clear();
		uvs.Clear();
		tris.Clear();
		for (int i = 0; i < currentStroke.controlPoints.Count; i++)
		{
			ControlPoint controlPoint = currentStroke.controlPoints[i];
			if (i == 0)
			{
				controlPoint.AddInitialQuad(vertices, uvs, tris);
				continue;
			}
			controlPoint.AddVertsAndUVs(vertices, uvs);
			ControlPoint controlPoint2 = currentStroke.controlPoints[i - 1];
			List<int> list = controlPoint2.EdgeVerts(controlPoint, trailing: true);
			List<int> list2 = controlPoint.EdgeVerts(controlPoint2);
			int num = (i - 1) * 4;
			int num2 = i * 4;
			tris.Add(num2 + list[1]);
			tris.Add(num + list2[0]);
			tris.Add(num2 + list[0]);
			tris.Add(num + list2[1]);
			tris.Add(num + list2[0]);
			tris.Add(num2 + list[1]);
			tris.Add(num2 + list[2]);
			tris.Add(num + list2[1]);
			tris.Add(num2 + list[1]);
			tris.Add(num + list2[2]);
			tris.Add(num + list2[1]);
			tris.Add(num2 + list[2]);
			controlPoint.AddTris(tris, num);
		}
		drawingMesh.vertices = vertices.ToArray();
		drawingMesh.uv = uvs.ToArray();
		drawingMesh.triangles = tris.ToArray();
		return true;
	}
}
public interface IDrawingControlPoint
{
	Vector2 Position { get; }
}
public class WhiteboardPenDrawingTool : DrawingToolBase<WhiteboardPenDrawingTool.ControlPoint>
{
	public class ControlPoint : IDrawingControlPoint
	{
		public Vector2 Position;

		public Vector2 Tangent;

		public float StrokeRadius = 0.01f;

		private static Vector3 Normal = Vector3.forward;

		private const int byteSize = 20;

		public static readonly byte[] memVector2 = new byte[20];

		Vector2 IDrawingControlPoint.Position => Position;

		public Vector2 Binormal => Vector3.Cross(Tangent, Normal).normalized;

		public ControlPoint()
		{
			Position = Vector2.zero;
			Tangent = Vector2.zero;
		}

		public ControlPoint(Vector2 position, Vector2 tangent, float strokeRadius)
		{
			Position = position;
			Tangent = tangent;
			StrokeRadius = strokeRadius;
		}

		public ControlPoint(ControlPoint other)
		{
			Position = other.Position;
			Tangent = other.Tangent;
			StrokeRadius = other.StrokeRadius;
		}

		public static ControlPoint Interpolate(ControlPoint lhs, ControlPoint rhs, float t)
		{
			Quaternion a = Quaternion.LookRotation(lhs.Tangent, Normal);
			Quaternion b = Quaternion.LookRotation(rhs.Tangent, Normal);
			Quaternion quaternion = Quaternion.Slerp(a, b, t);
			Vector3 vector = Vector3.Lerp(lhs.Position, rhs.Position, t);
			return new ControlPoint(vector, quaternion * Vector3.forward, lhs.StrokeRadius);
		}

		public override string ToString()
		{
			return Position.ToString();
		}

		public static short Serialize(StreamBuffer outStream, object customobject)
		{
			ControlPoint controlPoint = (ControlPoint)customobject;
			lock (memVector2)
			{
				byte[] array = memVector2;
				int targetOffset = 0;
				Protocol.Serialize(controlPoint.Position.x, array, ref targetOffset);
				Protocol.Serialize(controlPoint.Position.y, array, ref targetOffset);
				Protocol.Serialize(controlPoint.Tangent.x, array, ref targetOffset);
				Protocol.Serialize(controlPoint.Tangent.y, array, ref targetOffset);
				Protocol.Serialize(controlPoint.StrokeRadius, array, ref targetOffset);
				outStream.Write(array, 0, 20);
			}
			return 20;
		}

		public static object Deserialize(StreamBuffer inStream, short length)
		{
			ControlPoint controlPoint = new ControlPoint();
			lock (memVector2)
			{
				inStream.Read(memVector2, 0, 20);
				int offset = 0;
				Protocol.Deserialize(out controlPoint.Position.x, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.Position.y, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.Tangent.x, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.Tangent.y, memVector2, ref offset);
				Protocol.Deserialize(out controlPoint.StrokeRadius, memVector2, ref offset);
				return controlPoint;
			}
		}
	}

	[SerializeField]
	private AnimationCurve radiusCurve;

	[SerializeField]
	private float _strokeRadius = 0.005f;

	protected float StrokeRadius
	{
		get
		{
			if (base.CurrentSurface != null)
			{
				if (distanceToPlane < 0f)
				{
					return _strokeRadius;
				}
				return radiusCurve.Evaluate(distanceToPlane) * _strokeRadius;
			}
			return _strokeRadius;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (radiusCurve == null)
		{
			radiusCurve = AnimationCurve.Linear(0f, StrokeRadius, 0.1f, StrokeRadius);
		}
	}

	protected override Stroke CreateNewStroke(DrawingSurface drawingSurface, ControlPoint firstControlPoint)
	{
		lastControlPoint = firstControlPoint;
		return new Stroke(drawingSurface.PhotonId, firstControlPoint);
	}

	protected override ControlPoint CreateNewControlPoint()
	{
		ControlPoint controlPoint = new ControlPoint(base.NormalizedPlanePos, Vector2.zero, StrokeRadius);
		if (lastControlPoint != null)
		{
			controlPoint.Tangent = (controlPoint.Position - lastControlPoint.Position).normalized;
		}
		float num = Vector3.Angle(controlPoint.Tangent, base.CurrentSurface.transform.up);
		float t = 1f - (Mathf.Cos(2f * num * ((float)Math.PI / 180f)) + 1f) / 2f;
		float strokeRadius = StrokeRadius * Mathf.Lerp(1f, base.CurrentSurface.WHRation, t);
		controlPoint.StrokeRadius = strokeRadius;
		return controlPoint;
	}

	protected override bool UpdateMesh()
	{
		int num = currentStroke.controlPoints.Count;
		if (num == 1)
		{
			ControlPoint controlPoint = currentStroke.controlPoints[0];
			ControlPoint controlPoint2 = new ControlPoint(controlPoint);
			controlPoint2.Position.x -= controlPoint.StrokeRadius / 2f;
			ControlPoint controlPoint3 = new ControlPoint(controlPoint);
			controlPoint3.Position.x += controlPoint.StrokeRadius / 2f;
			controlPoint2.Tangent = (controlPoint3.Position - controlPoint2.Position).normalized;
			controlPoint3.Tangent = -controlPoint2.Tangent;
			AddVertsForControlPoint(controlPoint2);
			AddVertsForControlPoint(controlPoint3);
			num = 2;
		}
		else
		{
			for (int i = 0; i < currentStroke.controlPoints.Count; i++)
			{
				AddVertsForControlPoint(currentStroke.controlPoints[i]);
			}
		}
		int num2 = Mathf.Max(0, num - 1);
		for (int j = 0; j < num2; j++)
		{
			int num3 = j * 2;
			tris.Add(num3);
			tris.Add(num3 + 2);
			tris.Add(num3 + 1);
			tris.Add(num3 + 2);
			tris.Add(num3 + 3);
			tris.Add(num3 + 1);
		}
		drawingMesh.vertices = vertices.ToArray();
		drawingMesh.uv = uvs.ToArray();
		drawingMesh.triangles = tris.ToArray();
		return num2 > 0;
	}

	private void AddVertsForControlPoint(ControlPoint controlPoint, float t = 0f)
	{
		Vector2 vector = controlPoint.Position + controlPoint.Binormal * controlPoint.StrokeRadius;
		Vector2 vector2 = controlPoint.Position + controlPoint.Binormal * (0f - controlPoint.StrokeRadius);
		vertices.Add(vector);
		vertices.Add(vector2);
		Vector2 zero = Vector2.zero;
		zero.x = 1f - t;
		zero.y = 1f;
		uvs.Add(zero);
		zero.y = 0f;
		uvs.Add(zero);
	}
}
public class FlagTool : Tool
{
	public delegate void FlagAtGoal(FlagTool thisFlag, Player capturePlayer);

	public delegate void FlagRelease(FlagTool thisFlag, Player dropPlayer);

	public delegate void FlagPickup(FlagTool thisFlag, Player pickupPlayer);

	public delegate void FlagReset(FlagTool thisFlag);

	[Header("Team")]
	[SerializeField]
	private GameTeam team = GameTeam.INVALID;

	[Header("Beam")]
	[SerializeField]
	private Renderer beamRenderer;

	private SynchronizedField<bool> _atHomeGoal;

	private SynchronizedField<bool> _atEnemyGoal;

	private FlagToolRenderer flagToolRenderer;

	private List<FlagGoal> homeGoals = new List<FlagGoal>();

	private List<FlagGoal> enemyGoals = new List<FlagGoal>();

	public FlagAtGoal FlagAtGoalEvent;

	public FlagRelease FlagReleaseEvent;

	public FlagPickup FlagPickupEvent;

	public FlagReset FlagResetEvent;

	public bool AtHomeGoal
	{
		get
		{
			return _atHomeGoal.Get();
		}
		private set
		{
			_atHomeGoal.ForceSet(value);
		}
	}

	public bool AtEnemyGoal
	{
		get
		{
			return _atEnemyGoal.Get();
		}
		private set
		{
			_atEnemyGoal.ForceSet(value);
		}
	}

	public GameTeam Team => team;

	public Color Color
	{
		set
		{
			flagToolRenderer.AccentColor = value;
			float a = beamRenderer.material.color.a;
			value.a = a;
			beamRenderer.material.color = value;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		flagToolRenderer = GetComponent<FlagToolRenderer>();
		_atHomeGoal = new SynchronizedField<bool>(this, "AT_HOME_GOAL", defaultValue: false, SetterPermissionMode.AUTHORITY);
		_atEnemyGoal = new SynchronizedField<bool>(this, "AT_ENEMY_GOAL", defaultValue: false, SetterPermissionMode.AUTHORITY);
		FlagGoal[] array = UnityEngine.Object.FindObjectsOfType<FlagGoal>();
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].Team == team)
			{
				homeGoals.Add(array[i]);
			}
			else
			{
				enemyGoals.Add(array[i]);
			}
		}
	}

	protected override void Start()
	{
		base.Start();
		Color = GameTeamSettings.GetTeamColor(team);
		base.Rigidbody.isKinematic = true;
	}

	protected override void OnDisable()
	{
		if (base.hasAuthority)
		{
			AtEnemyGoal = false;
			AtHomeGoal = false;
		}
		base.OnDisable();
	}

	private void Update()
	{
		beamRenderer.enabled = true;
		Vector3 position;
		if (base.IsHeld && base.Owner != null)
		{
			if (base.Owner == Player.LocalPlayer)
			{
				beamRenderer.enabled = false;
			}
			position = base.Owner.CurrentFloorPosition;
		}
		else if (!TryGetBeamPosition(out position))
		{
			position = base.transform.position;
		}
		beamRenderer.transform.position = position;
		beamRenderer.transform.rotation = Quaternion.LookRotation(Vector3.up);
		if (!base.hasAuthority)
		{
			return;
		}
		bool atEnemyGoal = AtEnemyGoal;
		bool flag = IsAtGoal(enemyGoals);
		if (flag != atEnemyGoal)
		{
			AtEnemyGoal = flag;
			if (flag && FlagAtGoalEvent != null)
			{
				FlagAtGoalEvent(this, base.Owner);
			}
		}
		bool atHomeGoal = AtHomeGoal;
		bool flag2 = IsAtGoal(homeGoals);
		if (atHomeGoal != flag2)
		{
			AtHomeGoal = flag2;
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
		if (base.hasAuthority && FlagPickupEvent != null)
		{
			FlagPickupEvent(this, player);
		}
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		if (base.hasAuthority && FlagReleaseEvent != null)
		{
			FlagReleaseEvent(this, player);
		}
	}

	protected override void OnReset(Vector3 position, Quaternion rotation, bool wasEnabled, Vector3 oldPosition, bool wasCleanedUp)
	{
		base.OnReset(position, rotation, wasEnabled, oldPosition, wasCleanedUp);
		base.Rigidbody.isKinematic = true;
		if (wasCleanedUp && FlagResetEvent != null)
		{
			FlagResetEvent(this);
		}
	}

	private bool IsAtGoal(List<FlagGoal> goals)
	{
		bool result = false;
		for (int i = 0; i < goals.Count; i++)
		{
			if (Vector3.ProjectOnPlane(goals[i].transform.position - base.transform.position, Vector3.up).sqrMagnitude <= goals[i].Radius * goals[i].Radius)
			{
				result = true;
				break;
			}
		}
		return result;
	}

	private bool TryGetBeamPosition(out Vector3 position)
	{
		if (Physics.Raycast(base.transform.position + Vector3.up * 0.1f, -Vector3.up, out var hitInfo, float.MaxValue, 2048, QueryTriggerInteraction.Ignore))
		{
			position = hitInfo.point;
			return true;
		}
		position = Vector3.zero;
		return false;
	}
}
public class GiftBox : Photon.MonoBehaviour
{
	public enum GiftBoxState
	{
		Closed,
		Opening,
		Open,
		Failed
	}

	public enum GiftBoxContents
	{
		Unspecified = -1,
		XP,
		RepeatItem,
		NewItem
	}

	[SerializeField]
	private PooledParticle xpBoxOpenedParticlePrefab;

	[SerializeField]
	private PooledParticle itemBoxOpenedParticlePrefab;

	[SerializeField]
	private Transform boxOpenedParticleRoot;

	[SerializeField]
	private Transform toolAnchor;

	[SerializeField]
	private Text xpText;

	[SerializeField]
	private Text nameTagText;

	[SerializeField]
	private float remotePlayerXpBonusDistance = 7f;

	[SerializeField]
	private Animator boxAnimator;

	[SerializeField]
	private Animator toolAnchorAnimator;

	[SerializeField]
	private float timeBeforeDerez = 2f;

	[SerializeField]
	private RecRoomAudioClip boxAppearAudio;

	[Tooltip("XP box | Already owned item | New item")]
	[SerializeField]
	private RecRoomAudioClip[] boxOpenAudio = new RecRoomAudioClip[3];

	private Avatars.GiftPackage giftPackage;

	private TearStripTab tearStrip;

	private PhotonPlayer giftOwner;

	private OutfitTool giftTool;

	private SynchronizedField<int> _boxState;

	private SynchronizedField<int> _boxContents;

	public Transform ToolAnchor => toolAnchor;

	public bool IsOwnerLocal => giftOwner != null && giftOwner.isLocal;

	public OutfitSelection OutfitSelection { get; private set; }

	public GiftBoxState BoxState
	{
		get
		{
			return (GiftBoxState)_boxState.Get();
		}
		private set
		{
			_boxState.ForceSet((int)value);
		}
	}

	public GiftBoxContents BoxContents
	{
		get
		{
			return (GiftBoxContents)_boxContents.Get();
		}
		private set
		{
			_boxContents.ForceSet((int)value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_boxState = new SynchronizedField<int>(this, "GIFTBOX_STATE", 0, SetterPermissionMode.AUTHORITY, OnBoxStateChanged);
		_boxContents = new SynchronizedField<int>(this, "GIFTBOX_CONTENTS", -1, SetterPermissionMode.AUTHORITY);
		object[] instantiationData = base.photonView.instantiationData;
		giftOwner = (PhotonPlayer)instantiationData[0];
		string json = (string)instantiationData[1];
		try
		{
			Dictionary<string, object> dict = GAMiniJSON.Json.Deserialize(json) as Dictionary<string, object>;
			giftPackage = new Avatars.GiftPackage();
			giftPackage.Deserialize(dict);
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
			giftPackage = null;
		}
		if (giftPackage != null)
		{
			OutfitSelection = OutfitSelection.Parse(giftPackage.AvatarItemDesc);
			if (IsOwnerLocal)
			{
				if (OutfitSelection != null)
				{
					OutfitManager.Instance.LocalSpawnOutfitTool(OutfitSelection, OutfitTool.ToolPurpose.GiftBox);
					BoxContents = (OutfitManager.Instance.UnlockedOutfitSelections.Contains(OutfitSelection) ? GiftBoxContents.RepeatItem : GiftBoxContents.NewItem);
				}
				else
				{
					BoxContents = GiftBoxContents.XP;
				}
			}
		}
		tearStrip = GetComponentInChildren<TearStripTab>();
		if (tearStrip != null)
		{
			tearStrip.TornOff += OnStripTornOff;
		}
		BoxState = GiftBoxState.Closed;
		if (xpText != null)
		{
			xpText.text = string.Empty;
		}
		if (nameTagText != null)
		{
			nameTagText.text = giftOwner.name.Truncate(16, "...");
		}
	}

	private void Start()
	{
		if (boxOpenAudio != null)
		{
			AudioManager.Play3DSFX(boxAppearAudio, base.transform);
		}
	}

	protected override void OnDestroy()
	{
		if (tearStrip != null)
		{
			tearStrip.TornOff -= OnStripTornOff;
		}
		if (giftTool != null && giftTool.IsWearerLocal)
		{
			giftTool.PickupAttemptEvent -= OnOutfitToolPickupAttempt;
		}
		base.OnDestroy();
	}

	private void OnBoxStateChanged()
	{
		boxAnimator.SetInteger("State", (int)BoxState);
		switch (BoxState)
		{
		case GiftBoxState.Opening:
			if (IsOwnerLocal)
			{
				StartCoroutine(RunOpenBox());
			}
			if (nameTagText != null)
			{
				nameTagText.enabled = false;
			}
			break;
		case GiftBoxState.Open:
		case GiftBoxState.Failed:
			if (BoxState == GiftBoxState.Open)
			{
				ApplyGiftPackageXp();
			}
			toolAnchorAnimator.SetTrigger("Spawn");
			giftTool = OutfitTool.Find(giftOwner, OutfitSelection, OutfitTool.ToolPurpose.GiftBox);
			if (giftTool != null)
			{
				giftTool.Box = this;
				giftTool.OnlyOwnerCanPickup = true;
				giftTool.CurrentState = OutfitTool.OutfitToolState.InOpenBox;
				if (IsOwnerLocal)
				{
					giftTool.PickupAttemptEvent += OnOutfitToolPickupAttempt;
				}
			}
			else
			{
				if (xpText != null && giftPackage != null)
				{
					xpText.text = giftPackage.Xp + " XP";
					xpText.canvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
				}
				if (IsOwnerLocal)
				{
					StartCoroutine(DismissBox());
				}
			}
			PlayBoxOpenEffects();
			break;
		case GiftBoxState.Closed:
			break;
		}
	}

	private void ApplyGiftPackageXp()
	{
		if (giftPackage != null && giftPackage.Xp > 0 && Player.LocalPlayer != null && (IsOwnerLocal || (Player.LocalPlayer.CurrentFloorPosition - base.transform.position).magnitude <= remotePlayerXpBonusDistance))
		{
			int additionalXp = Mathf.CeilToInt((float)giftPackage.Xp * ((!IsOwnerLocal) ? 0.1f : 1f));
			SingletonMonoBehaviour<ProgressionManager>.Instance.LocalCompleteObjective(ProgressionManager.ObjectiveType.Default, additionalXp);
		}
	}

	private void OnStripTornOff(TearStripTab tearStrip)
	{
		BoxState = GiftBoxState.Opening;
		if (tearStrip != null)
		{
			tearStrip.TornOff -= OnStripTornOff;
		}
	}

	private void OnOutfitToolPickupAttempt(OutfitTool tool)
	{
		if (IsOwnerLocal)
		{
			tool.OnlyOwnerCanPickup = false;
			toolAnchorAnimator.enabled = false;
			StartCoroutine(DismissBox());
		}
	}

	private IEnumerator RunOpenBox()
	{
		yield return SingletonMonoBehaviour<GiftManager>.Instance.RunConsumeGift(giftPackage, delegate(bool successful)
		{
			if (successful)
			{
				BoxState = GiftBoxState.Open;
			}
			else
			{
				BoxState = GiftBoxState.Failed;
			}
		});
	}

	private void PlayBoxOpenEffects()
	{
		PooledParticle pooledParticle = null;
		if ((BoxContents == GiftBoxContents.NewItem || BoxContents == GiftBoxContents.RepeatItem) && itemBoxOpenedParticlePrefab != null)
		{
			pooledParticle = ObjectPool.Instance.Acquire(itemBoxOpenedParticlePrefab);
		}
		else if (BoxContents == GiftBoxContents.XP)
		{
			pooledParticle = ObjectPool.Instance.Acquire(xpBoxOpenedParticlePrefab);
		}
		if (pooledParticle != null)
		{
			pooledParticle.transform.position = boxOpenedParticleRoot.position;
			pooledParticle.transform.rotation = boxOpenedParticleRoot.rotation;
			pooledParticle.Play();
		}
		if (BoxContents != GiftBoxContents.Unspecified)
		{
			RecRoomAudioClip recRoomAudioClip = boxOpenAudio[(int)BoxContents];
			if (recRoomAudioClip != null)
			{
				AudioManager.Play2DSFX(recRoomAudioClip);
			}
		}
	}

	private IEnumerator DismissBox()
	{
		yield return new WaitForSeconds(timeBeforeDerez);
		PhotonNetwork.Destroy(base.gameObject);
	}
}
public abstract class GroupSearch : UnityEngine.MonoBehaviour
{
	private Collider[] overlapTestColliders;

	protected virtual void Awake()
	{
		overlapTestColliders = new Collider[10];
	}

	public ToolGroup FindGroup(GroupableTool thisGroupableTool = null, ToolGroup thisGroup = null)
	{
		ToolGroup result = null;
		int num = UpdateOverlapTest(testTriggers: false);
		for (int i = 0; i < num; i++)
		{
			Tool colliderTool = overlapTestColliders[i].GetColliderTool();
			ToolGroup toolGroup = ((!(colliderTool != null)) ? null : colliderTool.GetComponent<ToolGroup>());
			if (toolGroup != null && toolGroup != thisGroup && toolGroup.Size > 0 && (thisGroupableTool == null || toolGroup.CanAddTool(thisGroupableTool)) && (thisGroup == null || toolGroup.CanAddGroup(thisGroup)))
			{
				result = toolGroup;
				break;
			}
		}
		return result;
	}

	public GroupableTool FindGroupableTool(GroupableTool thisGroupableTool = null)
	{
		GroupableTool result = null;
		int num = UpdateOverlapTest(testTriggers: true);
		for (int i = 0; i < num; i++)
		{
			Tool colliderTool = overlapTestColliders[i].GetColliderTool();
			GroupableTool groupableTool = ((!(colliderTool != null)) ? null : colliderTool.GetComponent<GroupableTool>());
			if (groupableTool != null && groupableTool != thisGroupableTool && !groupableTool.IsInGroup && (thisGroupableTool == null || groupableTool.CanAddTool(thisGroupableTool)))
			{
				result = groupableTool;
				break;
			}
		}
		return result;
	}

	protected abstract void GetOverlapGeometry(out Vector3 center, out Vector3 size);

	protected int UpdateOverlapTest(bool testTriggers)
	{
		GetOverlapGeometry(out var center, out var size);
		center = base.transform.TransformPoint(center);
		size = base.transform.lossyScale.MultiplyComponents(size);
		return Physics.OverlapBoxNonAlloc(center, size / 2f, overlapTestColliders, base.transform.rotation, 226894848, (!testTriggers) ? QueryTriggerInteraction.Ignore : QueryTriggerInteraction.Collide);
	}

	private void OnDrawGizmos()
	{
		GetOverlapGeometry(out var center, out var size);
		Gizmos.color = Color.red;
		Matrix4x4 matrix = Matrix4x4.TRS(base.transform.TransformPoint(center), base.transform.rotation, base.transform.lossyScale.MultiplyComponents(size));
		Gizmos.matrix = matrix;
		Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
		Gizmos.matrix = Matrix4x4.identity;
	}
}
