public abstract class GroupableTool : Tool
{
	[Header("Groupable Tool")]
	[SerializeField]
	private GameObject frontGroupAddHighlightVisual;

	[SerializeField]
	private GameObject backGroupAddHighlightVisual;

	[SerializeField]
	protected GroupSearch defaultSearchCollider;

	[SerializeField]
	protected GroupSearch heldSearchCollider;

	private SynchronizedField<int> _thisGroupId;

	[NonSerialized]
	public ToolGroup Group;

	private GroupableTool[] newGroupInitialTools;

	private GroupableTool _hoveredGroupableTool;

	private ToolGroup _hoveredGroup;

	public ToolGroup ThisGroup
	{
		get
		{
			PhotonView photonView = PhotonView.Find(_thisGroupId.Get());
			return (!(photonView != null)) ? null : photonView.GetComponent<ToolGroup>();
		}
		set
		{
			int newValue = ((!(value != null)) ? (-1) : value.photonView.viewID);
			_thisGroupId.ForceSet(newValue);
		}
	}

	public Vector3 GroupLocalPosition { get; protected set; }

	public Quaternion GroupLocalRotation { get; protected set; }

	public Vector3 ColliderLocalPosition { get; protected set; }

	public Quaternion ColliderLocalRotation { get; protected set; }

	public Bounds LocalBoundingBox { get; private set; }

	public bool IsInGroup => Group != null;

	protected GroupableTool hoveredGroupableTool
	{
		get
		{
			return _hoveredGroupableTool;
		}
		set
		{
			if (!(_hoveredGroupableTool == value))
			{
				if (_hoveredGroupableTool != null)
				{
					_hoveredGroupableTool.DisplayAddToolHighlight(null);
				}
				_hoveredGroupableTool = value;
				if (_hoveredGroupableTool != null)
				{
					_hoveredGroupableTool.DisplayAddToolHighlight(this);
				}
			}
		}
	}

	protected ToolGroup hoveredGroup
	{
		get
		{
			return _hoveredGroup;
		}
		set
		{
			if (!(_hoveredGroup == value))
			{
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddToolHighlight(null);
				}
				_hoveredGroup = value;
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddToolHighlight(this);
				}
			}
		}
	}

	public bool FrontAddHighlightEnabled
	{
		get
		{
			return frontGroupAddHighlightVisual != null && frontGroupAddHighlightVisual.activeSelf;
		}
		set
		{
			if (frontGroupAddHighlightVisual != null)
			{
				frontGroupAddHighlightVisual.SetActive(value);
			}
		}
	}

	public bool BackAddHighlightEnabled
	{
		get
		{
			return backGroupAddHighlightVisual != null && backGroupAddHighlightVisual.activeSelf;
		}
		set
		{
			if (backGroupAddHighlightVisual != null)
			{
				backGroupAddHighlightVisual.SetActive(value);
			}
		}
	}

	protected GroupSearch SearchCollider => (!base.IsHeld || !(heldSearchCollider != null)) ? defaultSearchCollider : heldSearchCollider;

	protected abstract string GroupPrefabName { get; }

	protected override void Awake()
	{
		base.Awake();
		GroupLocalPosition = Vector3.zero;
		GroupLocalRotation = Quaternion.identity;
		DisplayAddToolHighlight(null);
	}

	protected override void Start()
	{
		base.Start();
		Quaternion rotation = base.transform.rotation;
		base.transform.rotation = Quaternion.identity;
		Bounds colliderBounds = base.ColliderBounds;
		LocalBoundingBox = new Bounds(base.transform.InverseTransformPoint(colliderBounds.center), colliderBounds.size);
		base.transform.rotation = rotation;
		base.RigidbodyPickup.ReachedHand += OnReachedHand;
	}

	public virtual bool CanAddTool(GroupableTool tool)
	{
		return true;
	}

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		UpdateHover();
		if (!base.IsHeld && (FrontAddHighlightEnabled || BackAddHighlightEnabled))
		{
			FrontAddHighlightEnabled = false;
			BackAddHighlightEnabled = false;
		}
	}

	public void UpdateGroupLayout(Vector3 localPosition, Quaternion localRotation, Vector3 colliderLocalPosition, Quaternion colliderLocalRotation)
	{
		if (IsInGroup)
		{
			GroupLocalPosition = localPosition;
			GroupLocalRotation = localRotation;
			ColliderLocalPosition = colliderLocalPosition;
			ColliderLocalRotation = colliderLocalRotation;
			base.RigidbodyPickup.Pickup(Group.Rigidbody, GroupLocalPosition, GroupLocalRotation);
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		if (IsInGroup)
		{
			if (!Group.hasAuthority && player.isLocal)
			{
				Group.photonView.TransferOwnership(PhotonNetwork.player);
			}
			ToolGroup toolGroup = Group;
			Group.AuthorityRemoveTool(this);
			if (toolGroup.Size == 0)
			{
				toolGroup.AuthorityDestroy();
			}
		}
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
	}

	private void OnReachedHand()
	{
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		if (IsInGroup && !player.isLocal)
		{
			UpdateGroupLayout(GroupLocalPosition, GroupLocalRotation, ColliderLocalPosition, ColliderLocalRotation);
		}
		TryAddToHoveredGroup();
	}

	private void UpdateHover()
	{
		if (IsInGroup || !base.hasAuthority)
		{
			hoveredGroupableTool = null;
			hoveredGroup = null;
			return;
		}
		hoveredGroupableTool = SearchCollider.FindGroupableTool(this);
		if (hoveredGroupableTool != null)
		{
			hoveredGroup = null;
		}
		else
		{
			hoveredGroup = SearchCollider.FindGroup(this);
		}
	}

	protected void TryAddToHoveredGroup()
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (hoveredGroup != null)
		{
			if (!hoveredGroup.hasAuthority)
			{
				hoveredGroup.photonView.TransferOwnership(PhotonNetwork.player);
			}
			hoveredGroup.AuthorityAddTool(this);
			hoveredGroup = null;
		}
		else if (hoveredGroupableTool != null)
		{
			ToolGroup toolGroup = hoveredGroupableTool.CreateNewGroup();
			if (hoveredGroupableTool.hoveredGroupableTool == this)
			{
				hoveredGroupableTool.hoveredGroupableTool = null;
			}
			toolGroup.AuthorityAddTool(hoveredGroupableTool);
			toolGroup.AuthorityAddTool(this);
			hoveredGroupableTool = null;
		}
	}

	private void InitializeNewGroup(ToolGroup newGroup)
	{
		if (newGroupInitialTools != null && newGroupInitialTools.Length > 0)
		{
			for (int i = 0; i < newGroupInitialTools.Length; i++)
			{
				newGroupInitialTools[i].hoveredGroupableTool = null;
			}
			newGroup.AuthorityAddTools(newGroupInitialTools);
		}
	}

	public ToolGroup CreateNewGroup()
	{
		if (PhotonNetwork.isMasterClient)
		{
			return MasterCreateNewGroup();
		}
		RequestMasterCreateNewGroup();
		return AuthorityCreateTemporaryGroup();
	}

	private void RequestMasterCreateNewGroup()
	{
		base.photonView.RPC("RpcMasterCreateNewGroup", PhotonTargets.MasterClient, PhotonNetwork.player);
	}

	private ToolGroup MasterCreateNewGroup()
	{
		ToolGroup result = null;
		if (PhotonNetwork.isMasterClient)
		{
			result = PhotonNetwork.InstantiateSceneObject(GroupPrefabName, base.transform.position, base.transform.rotation, 0, null).GetComponent<ToolGroup>();
		}
		return result;
	}

	private ToolGroup AuthorityCreateTemporaryGroup()
	{
		return PhotonNetwork.Instantiate(GroupPrefabName, base.transform.position, base.transform.rotation, 0, null).GetComponent<ToolGroup>();
	}

	private void OnMasterGroupCreation(ToolGroup newGroup)
	{
		if (!newGroup.hasAuthority)
		{
			newGroup.photonView.TransferOwnership(PhotonNetwork.player);
		}
		if (!IsInGroup || (Group.IsHeld && !Group.Owner.isLocal))
		{
			newGroup.AuthorityDestroy();
			return;
		}
		ToolGroup toolGroup = Group;
		newGroup.AuthorityClone(toolGroup);
		toolGroup.AuthorityDestroy();
	}

	public virtual void DisplayAddToolHighlight(GroupableTool toolToAdd)
	{
		FrontAddHighlightEnabled = toolToAdd != null;
		BackAddHighlightEnabled = false;
	}

	protected override void OnDestroy()
	{
		if (IsInGroup && Group.hasAuthority)
		{
			Group.AuthorityRemoveTool(this);
		}
		base.RigidbodyPickup.ReachedHand -= OnReachedHand;
		base.OnDestroy();
	}

	public override void OnHoverStart(bool physicalHover)
	{
		base.OnHoverStart(physicalHover);
		if (IsInGroup)
		{
			Group.OnToolInGroupHoverStart(this, physicalHover);
		}
	}

	public override void OnHoverEnd()
	{
		if (IsInGroup)
		{
			base.ToolRenderer.Mode = Group.ToolRenderer.Mode;
			Group.OnToolInGroupHoverEnd(this);
		}
		else
		{
			base.OnHoverEnd();
		}
	}

	public override Tool GetHighlightedTool(Player player, ToolCollider collider, bool physicalPickup, Vector3 pickupPosition)
	{
		if (IsInGroup)
		{
			GroupableTool highlightedToolInGroup = Group.GetHighlightedToolInGroup(this, player, physicalPickup, pickupPosition);
			if (highlightedToolInGroup != null)
			{
				return highlightedToolInGroup.GetBaseHighlightedTool(player, collider, physicalPickup, pickupPosition);
			}
			return Group.GetHighlightedTool(player, collider, physicalPickup, pickupPosition);
		}
		return base.GetHighlightedTool(player, collider, physicalPickup, pickupPosition);
	}

	private Tool GetBaseHighlightedTool(Player player, ToolCollider collider, bool physicalPickup, Vector3 pickupPosition)
	{
		return base.GetHighlightedTool(player, collider, physicalPickup, pickupPosition);
	}

	[PunRPC]
	protected void RpcMasterCreateNewGroup(PhotonPlayer requester)
	{
		if (PhotonNetwork.isMasterClient && requester != null)
		{
			ToolGroup toolGroup = MasterCreateNewGroup();
			if (toolGroup != null)
			{
				base.photonView.RPC("RpcOnMasterGroupCreation", requester, toolGroup.photonView.viewID);
			}
		}
	}

	[PunRPC]
	protected void RpcOnMasterGroupCreation(int toolGroupPhotonViewId)
	{
		PhotonView photonView = PhotonView.Find(toolGroupPhotonViewId);
		ToolGroup toolGroup = ((!(photonView != null)) ? null : photonView.GetComponent<ToolGroup>());
		if (toolGroup != null)
		{
			OnMasterGroupCreation(toolGroup);
		}
	}
}
public class HandheldCameraRemoteTool : Tool
{
	private enum DollyMode
	{
		Stationary,
		Linear,
		Orbit
	}

	[Header("Camera Remote Settings")]
	[SerializeField]
	private HandheldCameraTool camera;

	[SerializeField]
	private DollyMode mode;

	[SerializeField]
	private float dollyTime;

	[SerializeField]
	private Transform startPosition;

	[Tooltip("Only valid for linear dolly mode")]
	[SerializeField]
	private Transform endPosition;

	[Tooltip("Only valid for orbit dolly mode")]
	[SerializeField]
	private Transform orbitCenter;

	private bool initialized;

	private bool recording;

	private void Update()
	{
		if (!initialized)
		{
			initialized = true;
			if (SingletonMonoBehaviour<ToolCleanupManager>.Instance != null)
			{
				SingletonMonoBehaviour<ToolCleanupManager>.Instance.RemoveTool(camera);
			}
			camera.Rigidbody.isKinematic = true;
			camera.RemoteControl = true;
			camera.OpenScreen(open: true);
		}
		if (base.hasAuthority)
		{
			ComputeCameraView(Time.time, out var position, out var rotation);
			camera.transform.position = position;
			camera.transform.rotation = rotation;
		}
	}

	private void ComputeCameraView(float elapsedTime, out Vector3 position, out Quaternion rotation)
	{
		position = startPosition.position;
		rotation = startPosition.rotation;
		float num = elapsedTime / dollyTime;
		switch (mode)
		{
		case DollyMode.Linear:
			if (!(endPosition != null))
			{
				break;
			}
			if (num > 1f)
			{
				int num2 = Mathf.FloorToInt(num);
				num -= (float)num2;
				if (num2 % 2 == 1)
				{
					num = 1f - num;
				}
			}
			position = Vector3.Lerp(startPosition.position, endPosition.position, num);
			rotation = Quaternion.Slerp(startPosition.rotation, endPosition.rotation, num);
			break;
		case DollyMode.Orbit:
			if (orbitCenter != null)
			{
				Quaternion quaternion = Quaternion.AngleAxis(360f * num, Vector3.up);
				Vector3 vector = orbitCenter.InverseTransformPoint(startPosition.position);
				Quaternion quaternion2 = orbitCenter.InverseTransformRotation(startPosition.rotation);
				position = orbitCenter.TransformPoint(quaternion * vector);
				rotation = orbitCenter.TransformRotation(quaternion * quaternion2);
			}
			break;
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
		camera.photonView.TransferOwnership(player.PhotonPlayer);
	}

	public override void OnInputDown()
	{
		base.OnInputDown();
		if (base.hasAuthority)
		{
			if (!recording)
			{
				recording = true;
				VRSettings.renderScale = 0.5f;
				camera.StartCapturing();
			}
			else
			{
				recording = false;
				VRSettings.renderScale = 1f;
				camera.FinishCapturing();
			}
		}
	}
}
public class HandheldCameraTool : Tool
{
	[Header("Camera")]
	[SerializeField]
	private Camera camera;

	[SerializeField]
	private Transform lensTransform;

	[SerializeField]
	private Vector2 lowResolution = new Vector2(320f, 180f);

	[SerializeField]
	private Vector2 highResolution = new Vector2(640f, 360f);

	[SerializeField]
	private bool hideOwner = true;

	[Header("Screens")]
	[SerializeField]
	private Renderer[] screenRenderers;

	[SerializeField]
	private Renderer externalScreenRenderer;

	[SerializeField]
	private Material screenRenderMaterial;

	[SerializeField]
	private Material defaultScreenMaterial;

	[Header("Smoothing")]
	[SerializeField]
	private float positionSmoothingTime = 0.25f;

	[Header("Capture Feedback")]
	[SerializeField]
	private GameObject recordingFeedback;

	[SerializeField]
	private Slider recordingProgressFeedback;

	[SerializeField]
	private GameObject exportingFeedback;

	[SerializeField]
	private Text savedFeedback;

	private RenderTexture renderTexture;

	private Vector3 velocity = Vector3.zero;

	private Vector3 rotationVelocity = Vector3.zero;

	private bool? usingHighResolution;

	private float aspect = 1f;

	private VideoCapture videoCapture;

	private Material screenRenderMaterialCopy;

	private Animator animator;

	private static readonly int triggerId = Animator.StringToHash("Trigger");

	private static readonly int screenAnimationId = Animator.StringToHash("ScreenOpen");

	private float triggerAmount;

	private bool screenOpen;

	[NonSerialized]
	public bool RemoteControl;

	protected override void Awake()
	{
		base.Awake();
		aspect = lowResolution.x / lowResolution.y;
		videoCapture = GetComponent<VideoCapture>();
		if (videoCapture != null)
		{
			videoCapture.RecordingCamera = camera;
			videoCapture.CaptureStartedEvent += OnCaptureStarted;
			videoCapture.ExportStartedEvent += OnExportStarted;
			videoCapture.ExportFinishedEvent += OnExportFinished;
		}
		exportingFeedback.SetActive(value: false);
		recordingFeedback.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		savedFeedback.gameObject.SetActive(value: false);
		screenRenderMaterialCopy = new Material(screenRenderMaterial);
		animator = GetComponentInChildren<Animator>();
	}

	protected override void Start()
	{
		base.Start();
		camera.aspect = aspect;
		TonemappingColorGrading.LUTSettings lut = Camera.main.GetComponent<TonemappingColorGrading>().lut;
		camera.GetComponent<TonemappingColorGrading>().lut = lut;
		camera.gameObject.name = base.gameObject.name + "_Camera";
		camera.transform.SetParent(null, worldPositionStays: true);
		SwitchTextureResolution(useHighResolution: false);
		if (externalScreenRenderer != null)
		{
			externalScreenRenderer.material = screenRenderMaterialCopy;
		}
		OpenScreen(open: false);
	}

	private void SwitchTextureResolution(bool useHighResolution)
	{
		if (!usingHighResolution.HasValue || usingHighResolution.Value != useHighResolution)
		{
			usingHighResolution = useHighResolution;
			Vector2 vector = ((!useHighResolution) ? lowResolution : highResolution);
			renderTexture = new RenderTexture((int)vector.x, (int)vector.y, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			if (camera != null)
			{
				camera.targetTexture = renderTexture;
			}
			screenRenderMaterialCopy.mainTexture = renderTexture;
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
		if (hideOwner && player == Player.LocalPlayer)
		{
			camera.cullingMask &= -257;
		}
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		if (hideOwner && player == Player.LocalPlayer)
		{
			camera.cullingMask |= 256;
		}
		if (base.hasAuthority)
		{
			FinishCapturing();
			OpenScreen(open: false);
		}
	}

	public override void OnInputDown()
	{
		if (base.hasAuthority)
		{
			StartCapturing();
		}
	}

	public override void OnInputUp()
	{
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	protected override void OnLock()
	{
		OpenScreen(open: true);
	}

	protected override void OnUnlock()
	{
		OpenScreen(open: false);
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (videoCapture != null)
		{
			videoCapture.CaptureStartedEvent -= OnCaptureStarted;
			videoCapture.ExportStartedEvent -= OnExportStarted;
			videoCapture.ExportFinishedEvent -= OnExportFinished;
		}
		if (renderTexture != null)
		{
			UnityEngine.Object.Destroy(renderTexture);
		}
		if (camera != null)
		{
			UnityEngine.Object.Destroy(camera.gameObject);
		}
	}

	protected override void OnPhotonPlayerDisconnected(PhotonPlayer oldPlayer)
	{
		if (base.hasAuthority && (base.Owner == null || base.Owner.PhotonPlayer == oldPlayer))
		{
			FinishCapturing();
		}
		base.OnPhotonPlayerDisconnected(oldPlayer);
	}

	private void Update()
	{
		if (!RemoteControl)
		{
			camera.transform.position = Vector3.SmoothDamp(camera.transform.position, lensTransform.position, ref velocity, positionSmoothingTime);
			camera.transform.rotation = UnityExtensions.SmoothDamp(camera.transform.rotation, lensTransform.rotation, ref rotationVelocity, positionSmoothingTime);
		}
		else
		{
			camera.transform.position = lensTransform.position;
			camera.transform.rotation = lensTransform.rotation;
		}
		if (base.hasAuthority)
		{
			SetTrigger(InputAmount);
			UpdateCapture();
		}
	}

	private void OnRenderImage(RenderTexture src, RenderTexture dest)
	{
		Graphics.Blit(renderTexture, dest);
	}

	public void StartCapturing()
	{
		SwitchTextureResolution(useHighResolution: true);
		if (videoCapture != null && !videoCapture.IsCapturing)
		{
			videoCapture.StartCapture();
		}
	}

	public void FinishCapturing()
	{
		if (videoCapture != null && videoCapture.IsCapturing)
		{
			videoCapture.FinishCapture();
		}
		SwitchTextureResolution(useHighResolution: false);
	}

	private void UpdateCapture()
	{
		if (!(videoCapture != null) || !videoCapture.IsCapturing)
		{
			return;
		}
		if (!RemoteControl && !base.IsHeld)
		{
			FinishCapturing();
			OpenScreen(open: false);
			return;
		}
		float num = videoCapture.UpdateFrame(renderTexture);
		recordingProgressFeedback.value = num;
		if (num >= 1f)
		{
			FinishCapturing();
		}
	}

	private void OnCaptureStarted()
	{
		recordingFeedback.gameObject.SetActive(value: true);
		recordingProgressFeedback.gameObject.SetActive(value: true);
	}

	private void OnExportStarted()
	{
		recordingFeedback.gameObject.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		exportingFeedback.SetActive(value: true);
	}

	private void OnExportFinished(string filename)
	{
		exportingFeedback.SetActive(value: false);
		StartCoroutine(DisplayFileSaveFeedbackCoroutine(filename));
	}

	private IEnumerator DisplayFileSaveFeedbackCoroutine(string filename)
	{
		filename = Path.GetFileName(filename);
		savedFeedback.gameObject.SetActive(value: true);
		savedFeedback.text = filename + " Saved!";
		yield return new WaitForSeconds(2f);
		savedFeedback.gameObject.SetActive(value: false);
	}

	public void OpenScreen(bool open)
	{
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetBool(screenAnimationId, open);
		}
		if (externalScreenRenderer == null)
		{
			camera.enabled = open;
		}
		if (screenOpen != open)
		{
			screenOpen = open;
			Renderer[] array = screenRenderers;
			foreach (Renderer renderer in array)
			{
				renderer.material = ((!open) ? defaultScreenMaterial : screenRenderMaterialCopy);
			}
		}
	}

	private void SetTrigger(float trigger)
	{
		triggerAmount = trigger;
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetFloat(triggerId, triggerAmount);
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			float trigger = (float)stream.ReceiveNext();
			SetTrigger(trigger);
			bool open = (bool)stream.ReceiveNext();
			OpenScreen(open);
		}
		else
		{
			stream.SendNext(triggerAmount);
			stream.SendNext(screenOpen);
		}
	}
}
