	public bool SupportsPhysicalPickup => supportsPhysicalPickup;

	public bool SupportsOffCenterPickup => supportsOffCenterPickup;

	public bool SupportsTeleportHits => supportsTeleportHits;

	public bool OnlyOwnerCanPickup { get; set; }

	public TrackedVelocity TrackedVelocity { get; protected set; }

