	private void UpdateDynamicKinematicCollision()
	{
		previousPreviousVelocity = previousVelocity;
		previousVelocity = ((!Rigidbody.isKinematic) ? Rigidbody.velocity : Vector3.zero);
		if (lastDynamicKinematicRigidbody == null)
		{
			return;
		}
		if (dynamicKinematicCollisionThisFrame)
		{
			dynamicKinematicCollisionThisFrame = false;
			lastDynamicKinematicCollisionTime = Time.unscaledTime;
			Rigidbody.velocity = dynamicKinematicCollisionVelocity;
			Rigidbody.angularVelocity = dynamicKinematicCollisionAngularVelocity;
		}
		foreach (ToolCollider collider in Colliders)
		{
			if (collider.IsOverlapping(lastDynamicKinematicRigidbody))
			{
				lastDynamicKinematicCollisionTime = Time.unscaledTime;
				break;
			}
		}
		if (Time.unscaledTime - lastDynamicKinematicCollisionTime > 0.25f)
		{
			DisableDynamicKinematicCollisions(disable: false);
			lastDynamicKinematicRigidbody = null;
		}
	}

	private void OnDynamicKinematicCollision(Rigidbody dynamicKinematicRigidbody, Collision collision)
	{
		if (dynamicKinematicCollisionsEnabled && !(lastDynamicKinematicRigidbody != null) && !(collision.impulse.magnitude <= Mathf.Epsilon))
		{
			CalculateDynamicKinematicCollisionPhysics(dynamicKinematicRigidbody, collision, out dynamicKinematicCollisionVelocity, out dynamicKinematicCollisionAngularVelocity);
			dynamicKinematicCollisionThisFrame = true;
			lastDynamicKinematicRigidbody = dynamicKinematicRigidbody;
			DisableDynamicKinematicCollisions(disable: true);
		}
	}

	private void CalculateDynamicKinematicCollisionPhysics(Rigidbody dynamicKinematicRigidbody, Collision collision, out Vector3 linearVelocity, out Vector3 angularVelocity)
	{
		float mass = Rigidbody.mass;
		Vector3 vector = previousPreviousVelocity;
		Vector3 vector2 = mass * vector;
		float mass2 = dynamicKinematicRigidbody.mass;
		TrackedVelocity component = dynamicKinematicRigidbody.GetComponent<TrackedVelocity>();
		Vector3 recentLinearVelocity = component.RecentLinearVelocity;
		Vector3 vector3 = mass2 * recentLinearVelocity;
		Vector3 vector4 = recentLinearVelocity - vector;
		RecRoomCollider component2 = collision.collider.GetComponent<RecRoomCollider>();
		Vector3 collisionNormal = component2.GetCollisionNormal(collision);
		float kinematicBounciness = component2.KinematicBounciness;
		linearVelocity = collisionNormal * ((vector2 + vector3 + mass2 * kinematicBounciness * vector4) / (mass + mass2)).magnitude;
		Vector3 rhs = Vector3.ProjectOnPlane(recentLinearVelocity, collisionNormal);
		Vector3 normalized = Vector3.Cross(-collisionNormal, rhs).normalized;
		angularVelocity = normalized * rhs.magnitude * spin * ((float)Math.PI / 180f);
	}

	private void DisableDynamicKinematicCollisions(bool disable)
	{
		if (disable)
		{
			SetCollisionLayerLocalOnly(Layers.DynamicPhysicsIgnoreDynamicPhysics);
		}
		else
		{
			SetCollisionLayerLocalOnly(Layers.DynamicPhysics);
		}
	}

	public static Tool Find(int viewId)
	{
		PhotonView photonView = PhotonView.Find(viewId);
		return (!(photonView == null)) ? photonView.GetComponent<Tool>() : null;
	}
}
[RequireComponent(typeof(Tool))]
public class ToolCleanup : Photon.MonoBehaviour
{
	[Tooltip("Whether or not this tool should be excluded from cleanup")]
	public bool ExcludeFromCleanup;

	[Tooltip("Min distance from original spawn position before a tool is considered eligible for cleanup")]
	public float MinDisplacementBeforeCleanup = 0.1f;

	[Tooltip("Min distance from the closest player before a tool is considered eligible for cleanup")]
	public float MinPlayerDistanceBeforeCleanup = 3f;

	[Tooltip("Delay before eligible tools are cleaned up")]
	public float DelayUntilCleanup = 15f;

	[Tooltip("Whether to try and check if this object moved or rotated only after its rigidbody has come to rest")]
	public bool TestRigidbody;

	[Header("Rotation")]
	[Tooltip("Whether to cleanup this tool after a rotation has occured")]
	public bool TestRotation;

	[Tooltip("How many degrees this object must have rotated in order to be considered rotated")]
	public float MinRotationAngleBeforeCleanup = 30f;

	private Tool tool;

	private Vector3 originalPosition;

	private Quaternion originalRotation;

	private bool isResetting;

	private bool hasMoved;

	private float resetTimerStart;

	private bool HasTranslated => (!TestRigidbody || tool.Rigidbody.IsSleeping()) && Vector3.Distance(base.transform.position, originalPosition) > MinDisplacementBeforeCleanup;

	private bool HasRotated => (!TestRigidbody || tool.Rigidbody.IsSleeping()) && Quaternion.Angle(originalRotation, base.transform.rotation) >= MinRotationAngleBeforeCleanup;

	private bool IsCloseToAnyPlayer => MinPlayerDistanceBeforeCleanup > 0f && Player.IsCloseToAnyPlayer(base.transform.position, MinPlayerDistanceBeforeCleanup);

	protected override void Awake()
	{
		base.Awake();
		tool = GetComponent<Tool>();
		tool.ResetEvent += OnReset;
		OnReset(tool, base.transform.position, base.transform.rotation);
	}

	private void OnReset(Tool tool, Vector3 position, Quaternion rotation)
	{
		ResetCleanupOriginalPosition(position, rotation);
	}

	public void ResetCleanupOriginalPosition(Vector3 position, Quaternion rotation)
	{
		isResetting = false;
		hasMoved = false;
		originalPosition = position;
		originalRotation = rotation;
	}

	public void CheckCleanup()
	{
		if (!isResetting && !(tool == null))
		{
			if (!hasMoved || !base.hasAuthority || !base.gameObject.activeSelf)
			{
				hasMoved = HasTranslated || HasRotated;
				resetTimerStart = Time.time;
			}
			else if (tool.IsHeld || !base.enabled || IsCloseToAnyPlayer)
			{
				resetTimerStart = Time.time;
			}
			else if (resetTimerStart + DelayUntilCleanup < Time.time)
			{
				isResetting = true;
				tool.AuthorityResetToDefault(originalPosition, originalRotation, wasCleanedUp: true);
			}
		}
	}
}
[DisallowMultipleComponent]
public class ToolCleanupManager : SingletonMonoBehaviour<ToolCleanupManager>
{
	[SerializeField]
	[Tooltip("Min distance from original spawn position before a tool is considered eligible for cleanup")]
	private float minDisplacementBeforeCleanup = 0.1f;

	[SerializeField]
	[Tooltip("Min distance from the closest player before a tool is considered eligible for cleanup")]
	private float minPlayerDistanceBeforeCleanup = 3f;

	[SerializeField]
	[Tooltip("Delay before eligible tools are cleaned up")]
	private float delayUntilCleanup = 15f;

	[SerializeField]
	[Tooltip("Tools that should be excluded from cleanup")]
	private Tool[] excludedTools;

	private int index;

	private List<ToolCleanup> tools;

	private void Awake()
	{
		SingletonMonoBehaviour<ToolCleanupManager>.Instance = this;
		tools = new List<ToolCleanup>();
	}

	private void Start()
	{
		if (excludedTools == null)
		{
			excludedTools = new Tool[0];
		}
		GameObject[] rootGameObjects = SceneManager.GetActiveScene().GetRootGameObjects();
		foreach (GameObject gameObject in rootGameObjects)
		{
			Tool[] componentsInChildren = gameObject.GetComponentsInChildren<Tool>(includeInactive: true);
			foreach (Tool tool in componentsInChildren)
			{
				AddToolHelper(tool);
			}
		}
		if (tools.Count == 0)
		{
			base.enabled = false;
		}
	}

	private void Update()
	{
		if (tools != null && tools.Count != 0)
		{
			index %= tools.Count;
			if (tools[index] == null || tools[index].gameObject == null)
			{
				tools.RemoveAt(index);
				index %= tools.Count;
			}
			else
			{
				tools[index].CheckCleanup();
				index = (index + 1) % tools.Count;
			}
		}
	}

	public ToolCleanup AddTool(Tool tool)
	{
		return AddToolHelper(tool);
	}

	public void RemoveTool(Tool tool)
	{
		ToolCleanup cleanup = tool.GetComponent<ToolCleanup>();
		if (cleanup == null)
		{
			return;
		}
		int num = tools.FindIndex((ToolCleanup c) => c == cleanup);
		if (num < 0)
		{
			return;
		}
		tools.RemoveAt(num);
		if (tools.Count == 0)
		{
			index = 0;
			return;
		}
		if (num < index)
		{
			index--;
		}
		index %= tools.Count;
	}

	private ToolCleanup AddToolHelper(Tool tool)
	{
		if (!excludedTools.Contains(tool))
		{
			ToolCleanup toolCleanup = tool.GetComponent<ToolCleanup>();
			if (toolCleanup == null)
			{
				toolCleanup = tool.gameObject.AddComponent<ToolCleanup>();
				toolCleanup.MinDisplacementBeforeCleanup = minDisplacementBeforeCleanup;
				toolCleanup.MinPlayerDistanceBeforeCleanup = minPlayerDistanceBeforeCleanup;
				toolCleanup.DelayUntilCleanup = delayUntilCleanup;
			}
			if (!toolCleanup.ExcludeFromCleanup)
			{
				tools.Add(toolCleanup);
				return toolCleanup;
			}
		}
		return null;
	}
}
public class ToolCollider : RecRoomCollider
{
	[HideInInspector]
	public Tool Tool;
}
public abstract class ToolGroup : Tool
{
	protected List<GroupableTool> tools = new List<GroupableTool>();

	protected BoxCollider groupBoxCollider;

	protected Bounds groupBounds = default(Bounds);

	[SerializeField]
	protected GroupSearchCustomGeometry defaultSearchCollider;

	[SerializeField]
	protected GroupSearchCustomGeometry heldSearchCollider;

	private Coroutine delayedRemoveUpdateCoroutine;

	protected static readonly Vector3[] CornerMasks = new Vector3[8]
	{
		new Vector3(1f, 1f, -1f),
		new Vector3(1f, -1f, -1f),
		new Vector3(-1f, 1f, -1f),
		new Vector3(-1f, -1f, -1f),
		new Vector3(1f, 1f, 1f),
		new Vector3(1f, -1f, 1f),
		new Vector3(-1f, 1f, 1f),
		new Vector3(-1f, -1f, 1f)
	};

	private ToolGroup _hoveredGroup;

	[SerializeField]
	private float removeMinDistance = 0.05f;

	protected GroupSearchCustomGeometry SearchCollider => (!base.IsHeld || !(heldSearchCollider != null)) ? defaultSearchCollider : heldSearchCollider;

	public int Size => tools.Count;

	public bool GroupToolRenderersAreVisible
	{
		get
		{
			for (int i = 0; i < tools.Count; i++)
			{
				if (tools[i].ToolRenderer.Visible)
				{
					return true;
				}
			}
			return false;
		}
	}

	protected ToolGroup hoveredGroup
	{
		get
		{
			return _hoveredGroup;
		}
		set
		{
			if (!(_hoveredGroup == value))
			{
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddGroupHighlight(null);
				}
				_hoveredGroup = value;
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddGroupHighlight(this);
				}
			}
		}
	}

	protected bool DelayedUpdateCoroutineIsRunning => delayedRemoveUpdateCoroutine != null;

	private bool DefaultAddHighlightEnabled
	{
		set
		{
			for (int i = 0; i < tools.Count; i++)
			{
				bool frontAddHighlightEnabled = i == tools.Count - 1 && value;
				tools[i].FrontAddHighlightEnabled = frontAddHighlightEnabled;
				tools[i].BackAddHighlightEnabled = false;
			}
		}
	}

	protected override void Awake()
	{
		base.Awake();
		groupBoxCollider = GetComponentInChildren<BoxCollider>();
		DisplayAddToolHighlight(null);
		DisplayAddGroupHighlight(null);
	}

	public void AuthorityDestroy()
	{
		if (base.hasAuthority)
		{
			PhotonNetwork.Destroy(base.gameObject);
		}
	}

	public void AuthorityAddTools(GroupableTool[] tools)
	{
		if (base.hasAuthority && tools != null && tools.Length > 0 && CanAddTool(tools[0]))
		{
			Vector3[] array = new Vector3[tools.Length];
			Quaternion[] array2 = new Quaternion[tools.Length];
			for (int i = 0; i < tools.Length; i++)
			{
				ref Vector3 reference = ref array[i];
				reference = base.transform.InverseTransformPoint(tools[i].transform.position);
				ref Quaternion reference2 = ref array2[i];
				reference2 = base.transform.InverseTransformRotation(tools[i].transform.rotation);
			}
			AuthorityAddTools(tools, array, array2);
		}
	}

	public void AuthorityAddTools(GroupableTool[] tools, Vector3[] localPositions, Quaternion[] localRotations)
	{
		if (base.hasAuthority && tools != null && localPositions != null && localRotations != null && tools.Length > 0 && tools.Length == localPositions.Length && tools.Length == localRotations.Length && CanAddTool(tools[0]))
		{
			int[] array = new int[tools.Length];
			for (int i = 0; i < tools.Length; i++)
			{
				array[i] = tools[i].photonView.viewID;
			}
			int desiredNewToolIndex = GetDesiredNewToolIndex(tools[0], localPositions[0], localRotations[0]);
			base.photonView.RPC("RpcAddTools", PhotonTargets.All, array, localPositions, localRotations, desiredNewToolIndex);
		}
	}

	public void AuthorityAddTool(GroupableTool tool)
	{
		Vector3 localPosition = base.transform.InverseTransformPoint(tool.transform.position);
		Quaternion localRotation = base.transform.InverseTransformRotation(tool.transform.rotation);
		AuthorityAddTool(tool, localPosition, localRotation);
	}

	public void AuthorityAddTool(GroupableTool tool, Vector3 localPosition, Quaternion localRotation)
	{
		if (base.hasAuthority && ((tool != null) & CanAddTool(tool)))
		{
			int desiredNewToolIndex = GetDesiredNewToolIndex(tool, localPosition, localRotation);
			base.photonView.RPC("RpcAddTool", PhotonTargets.All, tool.photonView.viewID, localPosition, localRotation, desiredNewToolIndex);
		}
	}

	public void AuthorityAddGroup(ToolGroup group)
	{
		if (base.hasAuthority && group != null && group.hasAuthority && CanAddGroup(group))
		{
			GroupableTool[] array = group.tools.ToArray();
			group.AuthorityClearTools();
			AuthorityAddTools(array);
		}
	}

	public void AuthorityRemoveTool(GroupableTool tool)
	{
		if (base.hasAuthority && tool != null)
		{
			base.photonView.RPC("RpcRemoveTool", PhotonTargets.All, tool.photonView.viewID);
		}
	}

	public void AuthorityClearTools()
	{
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcClearTools", PhotonTargets.All);
		}
	}

	public void AuthorityReorderTools(int[] toolPhotonViewIds)
	{
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcReorderTools", PhotonTargets.All, toolPhotonViewIds);
		}
	}

	private void AddTool(GroupableTool tool, Vector3 localPosition, Quaternion localRotation, int desiredIndex, bool applyChangesToEntireGroup = true)
	{
		if (tool != this && !tools.Contains(tool))
		{
			OnAddTool(tool);
			if (base.hasAuthority && Size == 0 && tool.IsHeld && tool.Owner.isLocal)
			{
				Player player = tool.Owner;
				PlayerHand playerHand = ((!(player.LeftHand.Tool == tool)) ? player.RightHand : player.LeftHand);
				bool isLocked = tool.IsLocked;
				player.ToolController.ReleaseTool(tool);
				player.ToolController.TryPickupTool(this, tool.LastTargetSpacePickupPosition, tool.LastTargetSpacePickupRotation, (int)playerHand.Type);
				base.IsLocked = isLocked;
			}
			if (desiredIndex >= 0 && desiredIndex < tools.Count)
			{
				tools.Insert(desiredIndex, tool);
			}
			else
			{
				tools.Add(tool);
			}
			tool.Group = this;
			tool.UpdateGroupLayout(localPosition, localRotation, localPosition, localRotation);
			for (int i = 0; i < tool.Colliders.Count; i++)
			{
				tool.Colliders[i].ThisCollider.isTrigger = true;
			}
			if (applyChangesToEntireGroup)
			{
				UpdateGroupLayout();
				UpdateGroupCollider();
			}
			tool.ToolRenderer.Mode = base.ToolRenderer.Mode;
		}
	}

	protected void StartDelayedUpdateOnRemove(GroupableTool removedTool)
	{
		StopDelayedUpdateOnRemove();
		delayedRemoveUpdateCoroutine = StartCoroutine(DelayedUpdateGroupOnRemove(removedTool));
	}

	protected void StopDelayedUpdateOnRemove()
	{
		if (DelayedUpdateCoroutineIsRunning)
		{
			StopCoroutine(delayedRemoveUpdateCoroutine);
			delayedRemoveUpdateCoroutine = null;
		}
	}

	private IEnumerator DelayedUpdateGroupOnRemove(GroupableTool removedTool)
	{
		while (!((removedTool.transform.position - base.transform.position).sqrMagnitude > removeMinDistance * removeMinDistance))
		{
			yield return null;
		}
		UpdateGroupLayout();
		UpdateGroupCollider();
		delayedRemoveUpdateCoroutine = null;
	}

	private void RemoveTool(GroupableTool tool, bool removingSingleTool = true)
	{
		if (!(tool.Group == this) || !tools.Contains(tool))
		{
			return;
		}
		tools.Remove(tool);
		tool.Group = null;
		tool.RigidbodyPickup.Release();
		for (int i = 0; i < tool.Colliders.Count; i++)
		{
			tool.Colliders[i].ThisCollider.isTrigger = tool.Colliders[i].IsTriggerByDefault;
		}
		OnRemoveTool(tool);
		if (removingSingleTool)
		{
			StartCoroutine(DelayedUpdateGroupOnRemove(tool));
			if (base.hasAuthority && Size == 0 && base.IsHeld && base.Owner.isLocal)
			{
				base.Owner.ToolController.ReleaseTool(this);
			}
		}
	}

	private void ClearTools()
	{
		while (tools.Count > 0)
		{
			RemoveTool(tools[0], removingSingleTool: false);
		}
	}

	private void ReorderTools(int[] photonViewIds)
	{
		for (int i = 0; i < photonViewIds.Length; i++)
		{
			PhotonView photonView = PhotonView.Find(photonViewIds[i]);
			if (photonView != null)
			{
				GroupableTool component = photonView.GetComponent<GroupableTool>();
				if (component != null)
				{
					tools[i] = component;
				}
			}
		}
		UpdateGroupLayout();
		UpdateGroupCollider();
	}

	protected virtual void OnAddTool(GroupableTool tool)
	{
	}

	protected virtual void OnRemoveTool(GroupableTool tool)
	{
	}

	protected virtual int GetDesiredNewToolIndex(GroupableTool newTool, Vector3 localPosition, Quaternion localRotation)
	{
		return -1;
	}

	public virtual bool CanAddTool(GroupableTool tool)
	{
		return true;
	}

	public virtual bool CanAddGroup(ToolGroup group)
	{
		return true;
	}

	public void AuthorityClone(ToolGroup oldGroup)
	{
		if (base.hasAuthority)
		{
			if (!base.IsHeld && oldGroup.IsHeld && oldGroup.Owner.isLocal)
			{
				Player player = oldGroup.Owner;
				PlayerHand playerHand = ((!(player.LeftHand.Tool == oldGroup)) ? player.RightHand : player.LeftHand);
				player.ToolController.ReleaseTool(oldGroup);
				player.ToolController.TryPickupTool(this, oldGroup.LastTargetSpacePickupPosition, oldGroup.LastTargetSpacePickupRotation, (int)playerHand.Type);
			}
			base.transform.position = oldGroup.transform.position;
			base.transform.rotation = oldGroup.transform.rotation;
			AuthorityAddGroup(oldGroup);
			OnCloned(oldGroup);
		}
	}

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		UpdateHover();
	}

	protected void UpdateHover()
	{
		if (!base.hasAuthority)
		{
			hoveredGroup = null;
		}
		else
		{
			hoveredGroup = SearchCollider.FindGroup(null, this);
		}
	}

	protected void TryAddToHoveredGroup()
	{
		if (base.hasAuthority && hoveredGroup != null)
		{
			if (!hoveredGroup.hasAuthority)
			{
				hoveredGroup.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (hoveredGroup.hoveredGroup == this)
			{
				hoveredGroup.hoveredGroup = null;
			}
			hoveredGroup.AuthorityAddGroup(this);
			hoveredGroup = null;
			AuthorityDestroy();
		}
	}

	protected virtual void OnCloned(ToolGroup oldGroup)
	{
	}

	public virtual void DisplayAddToolHighlight(GroupableTool toolToAdd)
	{
		DefaultAddHighlightEnabled = toolToAdd != null;
	}

	public virtual void DisplayAddGroupHighlight(ToolGroup groupToAdd)
	{
		DefaultAddHighlightEnabled = groupToAdd != null;
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		TryAddToHoveredGroup();
	}

	public virtual GroupableTool GetHighlightedToolInGroup(GroupableTool tool, Player player, bool physicalPickup, Vector3 pickupPosition)
	{
		return null;
	}

	public override Tool GetHighlightedTool(Player player, ToolCollider toolCollider, bool physicalPickup, Vector3 pickupPosition)
	{
		if (!player.CanInteractWithTools)
		{
			return null;
		}
		if (toolCollider.Tool == this)
		{
			return null;
		}
		if (base.IsHeld && (base.Owner != player || !physicalPickup))
		{
			return null;
		}
		if (base.OnlyOwnerCanPickup && base.Owner != player)
		{
			return null;
		}
		if (!physicalPickup && !SupportsAssistedCatching)
		{
			return null;
		}
		if (!GroupToolRenderersAreVisible)
		{
			return null;
		}
		if (base.IsLocked)
		{
			return null;
		}
		if (base.PlayerInteractionRestriction != null && !base.PlayerInteractionRestriction.PlayerInteractionAllowed(player.PhotonPlayer))
		{
			return null;
		}
		return ((!physicalPickup || !base.SupportsPhysicalPickup) && (physicalPickup || (!base.SupportsGravityPickup && !base.SupportsOffCenterGravityPickup))) ? null : this;
	}

	public virtual void OnToolInGroupHoverStart(GroupableTool tool, bool physicalHover)
	{
	}

	public virtual void OnToolInGroupHoverEnd(GroupableTool tool)
	{
	}

	protected override void OnIsLockedChanged()
	{
		base.OnIsLockedChanged();
		ApplyToolRendererModeToGroup();
	}

	public override void OnHoverStart(bool physicalHover)
	{
		base.OnHoverStart(physicalHover);
		ApplyToolRendererModeToGroup();
	}

	public override void OnHoverEnd()
	{
		base.OnHoverEnd();
		ApplyToolRendererModeToGroup();
	}

	private void ApplyToolRendererModeToGroup()
	{
		if (Size > 0)
		{
			for (int i = 0; i < tools.Count; i++)
			{
				tools[i].ToolRenderer.Mode = base.ToolRenderer.Mode;
			}
		}
	}

	protected virtual void UpdateGroupLayout()
	{
	}

	protected void UpdateGroupCollider()
	{
		if (!(groupBoxCollider != null))
		{
			return;
		}
		groupBounds.center = Vector3.zero;
		groupBounds.size = Vector3.zero;
		for (int i = 0; i < tools.Count; i++)
		{
			Vector3 vector = tools[i].LocalBoundingBox.center.TransformToWorldSpace(tools[i].ColliderLocalPosition, tools[i].ColliderLocalRotation);
			for (int j = 0; j < CornerMasks.Length; j++)
			{
				Vector3 vector2 = Vector3.Scale(tools[i].LocalBoundingBox.extents, CornerMasks[j]).TransformToWorldSpace(Vector3.zero, tools[i].ColliderLocalRotation);
				groupBounds.Encapsulate(vector + vector2);
			}
		}
		groupBoxCollider.center = groupBounds.center;
		groupBoxCollider.size = groupBounds.size;
		SearchCollider.Center = groupBoxCollider.center;
		SearchCollider.Size = groupBoxCollider.size;
	}

	[PunRPC]
	protected void RpcAddTool(int toolPhotonViewId, Vector3 localPosition, Quaternion localRotation, int desiredIndex)
	{
		PhotonView photonView = PhotonView.Find(toolPhotonViewId);
		if (photonView != null)
		{
			GroupableTool component = photonView.GetComponent<GroupableTool>();
			if (component != null && component != this)
			{
				AddTool(component, localPosition, localRotation, desiredIndex);
			}
		}
	}

	[PunRPC]
	protected void RpcAddTools(int[] toolPhotonViewIds, Vector3[] localPositions, Quaternion[] localRotations, int desiredStartingIndex)
	{
		for (int i = 0; i < toolPhotonViewIds.Length; i++)
		{
			PhotonView photonView = PhotonView.Find(toolPhotonViewIds[i]);
			if (photonView != null)
			{
				GroupableTool component = photonView.GetComponent<GroupableTool>();
				if (component != null && component != this)
				{
					AddTool(component, localPositions[i], localRotations[i], desiredStartingIndex + i, applyChangesToEntireGroup: false);
				}
			}
		}
		UpdateGroupLayout();
		UpdateGroupCollider();
	}

	[PunRPC]
	protected void RpcRemoveTool(int toolPhotonViewId)
	{
		PhotonView photonView = PhotonView.Find(toolPhotonViewId);
		if (photonView != null)
		{
			GroupableTool component = photonView.GetComponent<GroupableTool>();
			if (component != null && component != this)
			{
				RemoveTool(component);
			}
		}
	}

	[PunRPC]
	protected void RpcClearTools()
	{
		ClearTools();
	}

	[PunRPC]
	protected void RpcInitializeGroup(int[] toolPhotonViewIds, Vector3[] toolLocalPositions, Quaternion[] toolLocalRotations)
	{
		RpcAddTools(toolPhotonViewIds, toolLocalPositions, toolLocalRotations, -1);
	}

	[PunRPC]
	protected void RpcReorderTools(int[] toolPhotonViewIds)
	{
		ReorderTools(toolPhotonViewIds);
	}

	protected virtual void OnPhotonPlayerConnected(PhotonPlayer otherPlayer)
	{
		if (base.hasAuthority)
		{
			int[] array = new int[tools.Count];
			Vector3[] array2 = new Vector3[tools.Count];
			Quaternion[] array3 = new Quaternion[tools.Count];
			for (int i = 0; i < tools.Count; i++)
			{
				array[i] = tools[i].photonView.viewID;
				ref Vector3 reference = ref array2[i];
				reference = tools[i].GroupLocalPosition;
				ref Quaternion reference2 = ref array3[i];
				reference2 = tools[i].GroupLocalRotation;
			}
			base.photonView.RPC("RpcInitializeGroup", otherPlayer, array, array2, array3);
		}
	}

	protected void TransferOwnership(PhotonPlayer newOwner)
	{
		foreach (GroupableTool tool in tools)
		{
			tool.photonView.TransferOwnership(newOwner);
		}
		base.photonView.TransferOwnership(newOwner);
	}
}
public static class ToolJointConstructor
{
	private const bool linearLocked = true;

	private const float linearLimit = 0f;

	private const float linearLimitBounciness = 0f;

	private const float linearLimitContactDistance = 0f;

	private const float linearSpring = 20f;

	private const float linearSpringDamper = 0.25f;

	private const bool angularLocked = false;

	private const float angularLimit = 0f;

	private const float angularLimitBounciness = 0f;

	private const float angularLimitContactDistance = 0f;

	private const float angularSpring = 20f;

	private const float angularSpringDamper = 0.25f;

	public static Joint AddConfigurableJoint(GameObject jointGameObject)
	{
		ConfigurableJoint configurableJoint = jointGameObject.AddComponent<ConfigurableJoint>();
		configurableJoint.xMotion = ConfigurableJointMotion.Locked;
		configurableJoint.yMotion = ConfigurableJointMotion.Locked;
		configurableJoint.zMotion = ConfigurableJointMotion.Locked;
		configurableJoint.linearLimit = new SoftJointLimit
		{
			limit = 0f,
			bounciness = 0f,
			contactDistance = 0f
		};
		configurableJoint.linearLimitSpring = new SoftJointLimitSpring
		{
			spring = 20f,
			damper = 0.25f
		};
		configurableJoint.angularXMotion = ConfigurableJointMotion.Limited;
		configurableJoint.angularYMotion = ConfigurableJointMotion.Limited;
		configurableJoint.angularZMotion = ConfigurableJointMotion.Limited;
		SoftJointLimit softJointLimit = new SoftJointLimit
		{
			limit = 0f,
			bounciness = 0f,
			contactDistance = 0f
		};
		configurableJoint.lowAngularXLimit = softJointLimit;
		configurableJoint.highAngularXLimit = softJointLimit;
		configurableJoint.angularYLimit = softJointLimit;
		configurableJoint.angularZLimit = softJointLimit;
		SoftJointLimitSpring softJointLimitSpring = new SoftJointLimitSpring
		{
			spring = 20f,
			damper = 0.25f
		};
		configurableJoint.angularXLimitSpring = softJointLimitSpring;
		configurableJoint.angularYZLimitSpring = softJointLimitSpring;
		return configurableJoint;
	}
}
[RequireComponent(typeof(Tool))]
public class ToolPlayerAttractor : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool enabledOnReset = true;

	[SerializeField]
	private bool enableOnPoolSpawn;

	private Tool thisTool;

	private PulsingBeam pulsingBeam;

	private void Awake()
	{
		pulsingBeam = GetComponentInChildren<PulsingBeam>(includeInactive: true);
		if (pulsingBeam == null)
		{
			UnityEngine.Debug.LogError("ToolPlayerAttactor missing required pulsing beam.");
			return;
		}
		thisTool = GetComponent<Tool>();
		thisTool.PickupEvent += OnThisToolPickup;
		thisTool.ResetEvent += OnThisToolReset;
	}

	private void Start()
	{
		pulsingBeam.gameObject.SetActive(enableOnPoolSpawn || !thisTool.SpawnedFromPool);
	}

	private void OnDestroy()
	{
		thisTool.PickupEvent -= OnThisToolPickup;
		thisTool.ResetEvent -= OnThisToolReset;
	}

	private void OnThisToolPickup(Tool tool)
	{
		pulsingBeam.gameObject.SetActive(value: false);
	}

	private void OnThisToolReset(Tool tool, Vector3 position, Quaternion rotation)
	{
		if (enabledOnReset)
		{
			pulsingBeam.gameObject.SetActive(enableOnPoolSpawn || !thisTool.SpawnedFromPool);
		}
	}
}
[Serializable]
public struct ModelMaterial
{
	public Renderer Renderer;

	public int MaterialIndex;
}
[DisallowMultipleComponent]
public class ToolRenderer : UnityEngine.MonoBehaviour
{
	public enum HighlightMode
	{
		None,
		Physical,
		Magnet,
		SmartTool,
		Locked
	}

	protected static readonly Color noHighlightColor = new Color(0f, 0f, 0f, 0f);

	protected static readonly Color physicalPickupHighlightColor = new Color(0.75f, 0.25f, 0.25f, 1f);

	protected static readonly Color magnetPickupHighlightColor = new Color(0.5f, 0.5f, 0.5f, 1f);

	protected static readonly Color smartToolPickupHighlightColor = new Color(0f, 0.2f, 0.7f, 1f);

	protected static readonly Color lockedToolPickupHighlightColor = new Color(0.36f, 0.75f, 0f, 1f);

	[SerializeField]
	protected bool visibleWhileRemoteVisible;

	[SerializeField]
	protected List<Renderer> ignoredRenderers = new List<Renderer>();

	[SerializeField]
	protected Transform[] ignoredRendererRoots;

	[Header("Accent Renderers")]
	[SerializeField]
	protected bool useTeamColorAsAccentColor = true;

	[SerializeField]
	protected ModelMaterial[] accentRenderers;

	[SerializeField]
	protected Color defaultAccentColor;

	[Header("Highlight")]
	[SerializeField]
	protected bool supportsLockedHightlight = true;

	protected Tool thisTool;

	protected Color color = Color.white;

	protected HighlightMode mode;

	protected static int emissionColorId;

	protected Color accentColor;

	protected Dictionary<Renderer, Material> defaultMaterials;

	protected bool ghosted;

	public Color AccentColor
	{
		get
		{
			return accentColor;
		}
		set
		{
			accentColor = value;
			if (accentRenderers != null)
			{
				ModelMaterial[] array = accentRenderers;
				for (int i = 0; i < array.Length; i++)
				{
					ModelMaterial modelMaterial = array[i];
					modelMaterial.Renderer.materials[modelMaterial.MaterialIndex].color = accentColor;
				}
			}
			if (this.AccentColorUpdateEvent != null)
			{
				this.AccentColorUpdateEvent();
			}
		}
	}

	public Color Color
	{
		set
		{
			color = value;
			ForAllMaterialsInAllRenderers(delegate(Material mat)
			{
				mat.color = color;
			});
		}
	}

	public virtual HighlightMode Mode
	{
		get
		{
			return mode;
		}
		set
		{
			if (mode != value)
			{
				mode = value;
				Color highlightColor = magnetPickupHighlightColor;
				if (mode == HighlightMode.Physical)
				{
					highlightColor = physicalPickupHighlightColor;
				}
				else if (mode == HighlightMode.Magnet)
				{
					highlightColor = magnetPickupHighlightColor;
				}
				else if (mode == HighlightMode.SmartTool)
				{
					highlightColor = smartToolPickupHighlightColor;
				}
				else if (mode == HighlightMode.Locked && supportsLockedHightlight)
				{
					highlightColor = lockedToolPickupHighlightColor;
				}
				else
				{
					highlightColor = noHighlightColor;
				}
				ForAllMaterialsInAllRenderers(delegate(Material mat)
				{
					mat.SetColor(emissionColorId, highlightColor);
				});
			}
		}
	}

	public List<Renderer> Renderers { get; private set; }

	public Bounds Bounds
	{
		get
		{
			UnityExtensions.GetCombinedRendererBounds(Renderers, out var bounds);
			return bounds;
		}
	}

	public bool Visible
	{
		get
		{
			return Renderers != null && Renderers[0].enabled && Renderers[0].gameObject.activeSelf;
		}
		private set
		{
			if (Renderers == null)
			{
				return;
			}
			foreach (Renderer renderer in Renderers)
			{
				renderer.enabled = value;
			}
			foreach (Renderer ignoredRenderer in ignoredRenderers)
			{
				ignoredRenderer.enabled = value;
			}
			if (this.VisibleChangeEvent != null)
			{
				this.VisibleChangeEvent();
			}
		}
	}

	public event Action AccentColorUpdateEvent;

	public event Action VisibleChangeEvent;

	public void SetVisible(bool toolVisible, bool remoteVisible = false)
	{
		Visible = toolVisible && (visibleWhileRemoteVisible || !remoteVisible);
	}

	protected virtual void Awake()
	{
		InitializeRenderer();
		ResetAccentColor();
	}

	protected virtual void Start()
	{
		thisTool = GetComponent<Tool>();
		thisTool.PickupEvent += OnPickup;
		thisTool.ResetEvent += OnReset;
		thisTool.OwnerRoleUpdateEvent += OnOwnerRoleUpdated;
		AddInstantiatedIgnoredRenderers();
	}

	protected virtual void Update()
	{
		UpdateGhostedVisuals();
	}

	protected virtual void OnDestroy()
	{
		if (thisTool != null)
		{
			thisTool.PickupEvent -= OnPickup;
			thisTool.ResetEvent -= OnReset;
		}
	}

	public void ResetAccentColor()
	{
		AccentColor = defaultAccentColor;
	}

	private void InitializeRenderer()
	{
		Renderer[] componentsInChildren = GetComponentsInChildren<Renderer>(includeInactive: true);
		defaultMaterials = new Dictionary<Renderer, Material>();
		Renderer[] array = componentsInChildren;
		foreach (Renderer renderer in array)
		{
			if (!ignoredRenderers.Contains(renderer))
			{
				AddRenderer(renderer);
			}
			if (renderer as ParticleSystemRenderer == null)
			{
				defaultMaterials.Add(renderer, renderer.material);
			}
		}
	}

	private void AddInstantiatedIgnoredRenderers()
	{
		if (ignoredRendererRoots == null || ignoredRendererRoots.Length <= 0)
		{
			return;
		}
		List<Renderer> list = new List<Renderer>();
		for (int i = 0; i < ignoredRendererRoots.Length; i++)
		{
			list.AddRange(ignoredRendererRoots[i].GetComponentsInChildren<Renderer>());
		}
		List<int> list2 = new List<int>();
		for (int j = 0; j < Renderers.Count; j++)
		{
			if (list.Contains(Renderers[j]))
			{
				list2.Add(j);
			}
		}
		for (int k = 0; k < list2.Count; k++)
		{
			Renderers.RemoveAt(list2[k]);
		}
		ignoredRenderers.AddRange(list);
	}

	private void AddRenderer(Renderer renderer, Material highlightMaterialOverride = null)
	{
		if (Renderers == null)
		{
			Renderers = new List<Renderer>();
			emissionColorId = Shader.PropertyToID("_EmissionColor");
		}
		Material[] materials = renderer.materials;
		foreach (Material material in materials)
		{
			material.EnableKeyword("_EMISSION");
		}
		if (!Renderers.Contains(renderer))
		{
			Renderers.Add(renderer);
		}
	}

	public void SetupRenderer(Renderer newMeshRenderer, Material highlightMaterialOverride = null)
	{
		AddRenderer(newMeshRenderer, highlightMaterialOverride);
	}

	protected void ForAllMaterialsInAllRenderers(Action<Material> matAction)
	{
		ForAllMaterialsInRenderers(Renderers, matAction);
	}

	protected void ForAllMaterialsInRenderers(List<Renderer> renderers, Action<Material> matAction)
	{
		if (renderers == null)
		{
			return;
		}
		foreach (Renderer renderer in renderers)
		{
			Material[] materials = renderer.materials;
			foreach (Material obj in materials)
			{
				matAction(obj);
			}
		}
	}

	protected void OnPickup(Tool tool)
	{
		UpdateTeamAccentColor();
	}

	protected void OnReset(Tool tool, Vector3 position, Quaternion rotation)
	{
		if (useTeamColorAsAccentColor)
		{
			ResetAccentColor();
		}
	}

	protected void OnOwnerRoleUpdated(Tool tool)
	{
		UpdateTeamAccentColor();
	}

	public void UpdateTeamAccentColor()
	{
		if (useTeamColorAsAccentColor)
		{
			GameTeam gameTeam = ((!(thisTool.Owner != null)) ? GameTeam.INVALID : thisTool.Owner.Team);
			if (gameTeam != GameTeam.INVALID)
			{
				AccentColor = GameTeamSettings.GetTeamColor(gameTeam);
			}
			else
			{
				ResetAccentColor();
			}
		}
	}

	protected virtual void UpdateGhostedVisuals()
	{
		if (!ghosted)
		{
			if (!(Player.LocalPlayer != null) || !Player.LocalPlayer.SituationPulse.Active || !((Player.LocalPlayer.CurrentFloorPosition - base.transform.position).sqrMagnitude < Player.LocalPlayer.SituationPulse.Radius * Player.LocalPlayer.SituationPulse.Radius))
			{
				return;
			}
			foreach (Renderer key in defaultMaterials.Keys)
			{
				key.material = Player.LocalPlayer.SituationPulse.GhostMaterial;
			}
			ghosted = true;
		}
		else
		{
			if (!(Player.LocalPlayer != null) || (Player.LocalPlayer.SituationPulse.Active && !((Player.LocalPlayer.CurrentFloorPosition - base.transform.position).sqrMagnitude >= Player.LocalPlayer.SituationPulse.Radius * Player.LocalPlayer.SituationPulse.Radius)))
			{
				return;
			}
			foreach (Renderer key2 in defaultMaterials.Keys)
			{
				key2.material = defaultMaterials[key2];
			}
			ghosted = false;
		}
	}
}
public class ToolTrail : UnityEngine.MonoBehaviour
{
	[Header("Held Trails")]
	[SerializeField]
	private bool visibleWhileHeld = true;

	[SerializeField]
	private float heldTime = 2f;

	[Header("Release Trails")]
	[SerializeField]
	private bool visibleUponRelease = true;

	[SerializeField]
	private float releaseTime = 2f;

	[SerializeField]
	private bool fadeOutUponRelease;

	[SerializeField]
	private float releaseFadeOutDuration = 1f;

	[Header("Force Applied Trails")]
	[SerializeField]
	private bool visibleAfterForceApplied = true;

	[SerializeField]
	private float forceAppliedTime = 2f;

	[SerializeField]
	private bool fadeOutAfterForceApplied = true;

	[SerializeField]
	private float forceAppliedFadeOutDuration = 1f;

	private Tool thisTool;

	private TrailRenderer trailRenderer;

	private Coroutine releaseFadeCoroutine;

	private void Awake()
	{
		thisTool = GetComponentInParent<Tool>();
		thisTool.ReleaseEvent += OnRelease;
		thisTool.PickupEvent += OnPickup;
		thisTool.ForceApplied += OnForceApplied;
		trailRenderer = GetComponent<TrailRenderer>();
	}

	private void OnDisable()
	{
		StopReleaseFadeCoroutine();
	}

	private void OnDestroy()
	{
		thisTool.ReleaseEvent -= OnRelease;
		thisTool.PickupEvent -= OnPickup;
		thisTool.ForceApplied -= OnForceApplied;
	}

	private void OnRelease(Tool tool)
	{
		if (!visibleUponRelease)
		{
			trailRenderer.time = 0f;
			return;
		}
		trailRenderer.time = releaseTime;
		if (fadeOutUponRelease)
		{
			StartReleaseFadeCoroutine(releaseFadeOutDuration, releaseTime);
		}
	}

	private void OnPickup(Tool tool)
	{
		StopReleaseFadeCoroutine();
		if (!visibleWhileHeld)
		{
			trailRenderer.time = 0f;
		}
		else
		{
			trailRenderer.time = heldTime;
		}
	}

	private void OnForceApplied(Player hitPlayer, Tool tool, Vector3 position, Vector3 force)
	{
		StopReleaseFadeCoroutine();
		if (!visibleAfterForceApplied)
		{
			trailRenderer.time = 0f;
			return;
		}
		trailRenderer.time = forceAppliedTime;
		if (fadeOutAfterForceApplied)
		{
			StartReleaseFadeCoroutine(forceAppliedFadeOutDuration, forceAppliedTime);
		}
	}

	private void StartReleaseFadeCoroutine(float duration, float maxTime)
	{
		StopReleaseFadeCoroutine();
		if (thisTool != null && thisTool.gameObject.activeSelf)
		{
			releaseFadeCoroutine = StartCoroutine(ReleaseFadeCoroutine(duration, maxTime));
		}
	}

	private void StopReleaseFadeCoroutine()
	{
		if (releaseFadeCoroutine != null)
		{
			StopCoroutine(releaseFadeCoroutine);
			releaseFadeCoroutine = null;
		}
	}

	private IEnumerator ReleaseFadeCoroutine(float duration, float maxTime)
	{
		float timeRemaining = duration;
		while (timeRemaining >= 0f)
		{
			yield return null;
			timeRemaining -= Time.deltaTime;
			float t = timeRemaining / duration;
			trailRenderer.time = maxTime * t;
		}
		trailRenderer.time = 0f;
		releaseFadeCoroutine = null;
	}
}
