public class Billboard : UnityEngine.MonoBehaviour
{
	private enum LockMode
	{
		None,
		ParentUp,
		GlobalUp
	}

	[SerializeField]
	private Vector3 localForward = Vector3.forward;

	[SerializeField]
	private Vector3 localUp = Vector3.up;

	[SerializeField]
	private Vector3 parentUp = Vector3.up;

	[SerializeField]
	[Tooltip("None: No lock. Billboard directly to camera\nParent up: Local up aligned to parent up\nGlobal up: Local up aligned to global up")]
	private LockMode lockMode;

	private void OnWillRenderObject()
	{
		Vector3 vector = (base.transform.position - Camera.current.transform.position).normalized;
		Vector3 vector2 = Vector3.up;
		if (base.transform.parent != null)
		{
			vector = base.transform.parent.InverseTransformDirection(vector);
			vector2 = base.transform.parent.InverseTransformDirection(vector2);
		}
		switch (lockMode)
		{
		case LockMode.ParentUp:
			vector2 = parentUp;
			vector = Vector3.ProjectOnPlane(vector, vector2);
			break;
		case LockMode.GlobalUp:
			vector = Vector3.ProjectOnPlane(vector, vector2);
			break;
		}
		base.transform.localRotation = Quaternion.LookRotation(vector, vector2) * Quaternion.Inverse(Quaternion.LookRotation(localForward, localUp));
	}
}
public class BootSequence : UnityEngine.MonoBehaviour
{
	private string error;

	private bool success => string.IsNullOrEmpty(error);

	private void InitializeCallback(string error)
	{
		this.error = error;
	}

	private IEnumerator Start()
	{
		GameObject[] rootGameObjects = SceneManager.GetActiveScene().GetRootGameObjects();
		foreach (GameObject target in rootGameObjects)
		{
			UnityEngine.Object.DontDestroyOnLoad(target);
		}
		if (!CheckForVRDevice())
		{
			SceneManager.LoadScene("vr_device_required");
			yield break;
		}
		yield return LoadSplashScreen();
		PhotonNetwork.SendMonoMessageTargetType = typeof(Photon.MonoBehaviour);
		if (success)
		{
			yield return RecNet.Core.TestConnection(InitializeCallback);
		}
		if (success)
		{
			yield return PlatformManager.Instance.Initialize(InitializeCallback);
		}
		if (success)
		{
			LogPlatformInfo();
		}
		if (success)
		{
			yield return Profiles.DownloadLocalProfile(InitializeCallback);
		}
		if (success)
		{
			yield return AnalyticsHelper.OnPlatformAndProfileInitialized();
			LogProfileInfo();
		}
		if (success)
		{
			yield return Config.DownloadConfigSettings(InitializeCallback);
		}
		if (success)
		{
			yield return RecNet.Core.InitializePushNotificationChannel(InitializeCallback);
		}
		if (success)
		{
			Images.RefreshCachedProfileImage(Profiles.LocalProfile.Id);
		}
		if (success)
		{
			yield return Avatars.DownloadLocalAvatar(InitializeCallback);
		}
		if (success)
		{
			yield return RecroomPrefs.DowloadLocalPlayerPreferences(InitializeCallback);
		}
		if (success)
		{
			yield return OutfitManager.Instance.DownloadUnlockedAvatarItems(InitializeCallback);
		}
		if (success)
		{
			yield return Avatars.DowloadGiftPackages(InitializeCallback);
		}
		if (success)
		{
			yield return PUNNetworkManager.Instance.Initialize(InitializeCallback);
		}
		if (success)
		{
			yield return SingletonMonoBehaviour<SplashScreenManager>.Instance.WaitForMinimumSplashDuration();
			InitializeCoreSystems();
			yield return LoadInitialScene();
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			UnityEngine.Debug.LogError(error);
			SingletonMonoBehaviour<SplashScreenManager>.Instance.ShowErrorMessage(error);
		}
	}

	private void LogPlatformInfo()
	{
		string format = "Platform Info:\r\n    Platform: {0}\r\n    Hardware: {1}\r\n    Platform Profile Name: {2}\r\n    Platform Tracking Mode: {3}";
		string message = string.Format(format, PlatformManager.Instance.CurrentPlatform, PlatformManager.Instance.CurrentHardwareType, PlatformManager.Instance.PlatformProfileName, PlatformManager.Instance.CurrentTrackingMode);
		UnityEngine.Debug.Log(message);
	}

	private void LogProfileInfo()
	{
		string format = "Profile Info:\r\n    Profile ID: {0}\r\n    Profile DisplayName: {1}";
		Profile localProfile = Profiles.LocalProfile;
		string message = string.Format(format, localProfile.Id, localProfile.DisplayName);
		UnityEngine.Debug.Log(message);
	}

	private void InitializeCoreSystems()
	{
		SingletonMonoBehaviour<PlayerInputManager>.Instance.Initialize();
		SingletonMonoBehaviour<SettingsManager>.Instance.Initialize();
		SingletonMonoBehaviour<TutorialManager>.Instance.Initialize();
		SingletonMonoBehaviour<AudioManager>.Instance.Initialize();
		SingletonMonoBehaviour<GiftManager>.Instance.Initialize();
		if (SessionManager.IsDeveloper)
		{
			GoogleAnalytics.Client.UpdateHeaders();
		}
		SingletonMonoBehaviour<ProgressionManager>.Instance.Initialize();
		SingletonMonoBehaviour<ChildControlManager>.Instance.Initialize();
		AACCompilerCrashWorkAround();
	}

	private void AACCompilerCrashWorkAround()
	{
		string path = Path.Combine(UnityEngine.Application.temporaryCachePath, "libfaac-win64.dll");
		bool flag = File.Exists(path);
		string path2 = Path.Combine(UnityEngine.Application.dataPath, "FAAC_SelfBuild");
		bool flag2 = Directory.Exists(path2);
		if (!flag && flag2)
		{
			UnityEngine.Debug.LogError("Detected failed previous FAAC build. Automatically disabling video cameras.");
			SingletonMonoBehaviour<SettingsManager>.Instance.H264Plugin = false;
			try
			{
				Directory.Delete(path2, recursive: true);
			}
			catch
			{
			}
		}
	}

	private bool CheckForVRDevice()
	{
		return VRDevice.isPresent;
	}

	private IEnumerator LoadSplashScreen()
	{
		SceneManager.LoadScene("splash_screen");
		yield return null;
		Vector3 headRot = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation.eulerAngles;
		SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation = Quaternion.Euler(0f, 0f - headRot.y, 0f);
		Vector3 headPos = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
		SingletonMonoBehaviour<CameraRig>.Instance.transform.position = new Vector3(0f - headPos.x, 0f, 0f - headPos.z);
		yield return CameraFade.Instance.Fade(fadeIn: true, prepForLevelSwitch: false, suppressEffect: true, 1f);
	}

	private IEnumerator LoadInitialScene()
	{
		yield return CameraFade.Instance.Fade(fadeIn: false, prepForLevelSwitch: true, suppressEffect: true, 1f);
		PhotonNetwork.player.SetCustomProperties("prev_activity", "boot");
		ulong? playerToJoin = PUNNetworkManager.Instance.CheckCommandLineArgsForRichPresenceJoin();
		string initialScene = "dormroom";
		if (playerToJoin.HasValue)
		{
			PUNNetworkManager.Instance.JoinPlayer(playerToJoin.Value);
		}
		else
		{
			PUNNetworkManager.Instance.SwitchActivity(initialScene);
		}
	}
}
public class ButtonCollider : UnityEngine.MonoBehaviour
{
	public Button Button;

	public float consequtiveClickInterval = 1f;

	private float lastTriggerEnterTime;

	private void OnTriggerEnter(Collider collider)
	{
		if (!Button.IsInteractable() || !(Time.time - lastTriggerEnterTime > consequtiveClickInterval))
		{
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && bodyPart.IsHand())
		{
			PlayerHand playerHand = ((bodyPart != Player.BodyPart.LeftHand) ? colliderPlayer.RightHand : colliderPlayer.LeftHand);
			Button.Select();
			if (playerHand != null && playerHand.IsVisible)
			{
				lastTriggerEnterTime = Time.time;
				Button.onClick.Invoke();
			}
		}
	}
}
public class ControllerButtonLabels : UnityEngine.MonoBehaviour
{
	public enum ButtonType
	{
		Touchpad,
		Menu,
		Trigger
	}

	[Serializable]
	private struct ButtonLabel
	{
		public ButtonType ButtonType;

		public string AttachPointName;

		public string Text;

		public Vector3 LocalPosition;

		public Vector3 RotationEuler;

		public float LocalScale;
	}

	[SerializeField]
	private Label buttonLabelPrefab;

	[SerializeField]
	private Color buttonColor = new Color(0.6f, 0.6f, 0.6f);

	[SerializeField]
	private ButtonLabel[] buttonLabels;

	private Dictionary<ButtonType, Label> buttonLabelMap = new Dictionary<ButtonType, Label>();

	private void Awake()
	{
		SteamVR_Utils.Event.Listen("render_model_loaded", OnRenderModelLoaded);
		ButtonLabel[] array = buttonLabels;
		for (int i = 0; i < array.Length; i++)
		{
			ButtonLabel buttonLabel = array[i];
			Label label = UnityEngine.Object.Instantiate(buttonLabelPrefab);
			label.transform.SetParent(base.transform);
			label.Text = buttonLabel.Text;
			label.ButtonColor = buttonColor;
			label.gameObject.SetActive(value: false);
			buttonLabelMap.Add(buttonLabel.ButtonType, label);
		}
	}

	private void OnDestroy()
	{
		SteamVR_Utils.Event.Remove("render_model_loaded", OnRenderModelLoaded);
	}

	public void SetButtonLabelVisibility(ButtonType button, bool visible)
	{
		Label value = null;
		if (buttonLabelMap.TryGetValue(button, out value))
		{
			value.Visible = visible;
		}
	}

	private void OnRenderModelLoaded(params object[] args)
	{
		if (((SteamVR_RenderModel)args[0]).gameObject != base.gameObject)
		{
			return;
		}
		ButtonLabel[] array = buttonLabels;
		for (int i = 0; i < array.Length; i++)
		{
			ButtonLabel buttonLabel = array[i];
			Label value = null;
			if (!buttonLabelMap.TryGetValue(buttonLabel.ButtonType, out value))
			{
				continue;
			}
			Transform transform = base.transform.Find(buttonLabel.AttachPointName);
			if (transform != null)
			{
				value.ButtonRenderer = transform.gameObject.GetComponent<Renderer>();
				transform = transform.Find("attach");
				if (transform != null)
				{
					value.transform.SetParent(transform, worldPositionStays: false);
					value.transform.localRotation = Quaternion.Euler(buttonLabel.RotationEuler);
					value.transform.localPosition = buttonLabel.LocalPosition;
					value.transform.localScale.Scale(new Vector3(buttonLabel.LocalScale, buttonLabel.LocalScale, 1f));
					value.gameObject.SetActive(value: true);
				}
			}
		}
	}
}
