public class PlayerSubMenuPanic : PlayerSubMenu
{
	private ThrobbingUIElement buttonThrobber;

	protected override void Awake()
	{
		base.Awake();
		buttonThrobber = GetComponentInChildren<ThrobbingUIElement>();
	}

	protected virtual void Start()
	{
		base.PlayerMenu.ThisPlayer.SituationPulse.PanicToggled += OnPanicToggled;
	}

	public override void Refresh()
	{
		base.Refresh();
		if (buttonThrobber != null)
		{
			buttonThrobber.Active = base.PlayerMenu.ThisPlayer.SituationPulse.Active;
		}
	}

	public void Button_Panic()
	{
		base.PlayerMenu.ThisPlayer.SituationPulse.TogglePanic();
	}

	private void OnPanicToggled(object sender)
	{
		if (buttonThrobber != null)
		{
			buttonThrobber.Active = base.PlayerMenu.ThisPlayer.SituationPulse.Active;
		}
		if (base.PlayerMenu.ThisPlayer.SituationPulse.Active)
		{
			base.Selected = true;
			if (!base.PlayerMenu.Visible)
			{
				base.PlayerMenu.PlayIncomingNotificationFeedback((PlayerMenu.NotificationEffectFlag)(-1), "You entered ghost mode");
			}
		}
		else if (base.Selected)
		{
			base.PlayerMenu.ShowDefaultTab();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		base.PlayerMenu.ThisPlayer.SituationPulse.PanicToggled -= OnPanicToggled;
	}
}
public class ProfileMenuController : MenuController
{
	[SerializeField]
	private PlayerProfileView profileView;

	[SerializeField]
	private Button leavePartyButton;

	[SerializeField]
	private DailyObjectiveView[] dailyObjectiveViews;

	[SerializeField]
	private GameObject allObjectivesCompleteImage;

	[SerializeField]
	private Text dailyObjectivesHeader;

	[SerializeField]
	private string dailyObjectivesHeaderDaily = "Daily Challenges:";

	[SerializeField]
	private string dailyObjectivesHeaderOOBE = "Intro Checklist:";

	private bool initialized;

	private void LazyInit()
	{
		if (!initialized && base.Owner != null)
		{
			initialized = true;
			base.Owner.ObjectiveTracker.ObjectiveProgressUpdateEvent += Refresh;
			Images.OnProfileImageUpdated += OnProfileImageUpdated;
		}
	}

	private void OnDestroy()
	{
		if (initialized && base.Owner != null)
		{
			base.Owner.ObjectiveTracker.ObjectiveProgressUpdateEvent -= Refresh;
			Images.OnProfileImageUpdated -= OnProfileImageUpdated;
		}
	}

	public override void Refresh()
	{
		base.Refresh();
		if (base.Owner != null)
		{
			LazyInit();
			RefreshLocalPlayer();
			RefreshDailyObjectives();
		}
	}

	private void RefreshLocalPlayer()
	{
		profileView.Refresh(Player.LocalPlayer);
		RefreshLeavePartyButton(Player.LocalPlayer);
	}

	private void RefreshLeavePartyButton(Player player)
	{
		leavePartyButton.gameObject.SetActive(player != null && player.PlayerParty.IsInParty);
	}

	public void LeaveParty()
	{
		Player localPlayer = Player.LocalPlayer;
		if (!(localPlayer == null))
		{
			localPlayer.PlayerParty.LeaveCurrentParty();
			Refresh();
		}
	}

	private void RefreshDailyObjectives()
	{
		Player localPlayer = Player.LocalPlayer;
		if (localPlayer == null)
		{
			return;
		}
		dailyObjectivesHeader.text = ((!SingletonMonoBehaviour<TutorialManager>.Instance.IsOOBERunning) ? dailyObjectivesHeaderDaily : dailyObjectivesHeaderOOBE);
		allObjectivesCompleteImage.gameObject.SetActive(localPlayer.ObjectiveTracker.GetAllObjectivesCompleted());
		for (int i = 0; i < dailyObjectiveViews.Length; i++)
		{
			localPlayer.ObjectiveTracker.GetObjectiveDescription(i, out var description, out var descriptionText);
			if (description != null)
			{
				int progress;
				int total;
				bool objectiveProgress = localPlayer.ObjectiveTracker.GetObjectiveProgress(i, out progress, out total);
				dailyObjectiveViews[i].UpdateProgress(progress, total, objectiveProgress, descriptionText, description.ToolTip);
			}
		}
	}

	private void OnProfileImageUpdated(ulong id, Texture2D image)
	{
		if (id == Player.LocalPlayer.PlayerId)
		{
			profileView.RefreshPlayerIcon(Player.LocalPlayer);
		}
	}
}
public class GameScoreboardBodyView : GameScoreboardElementView
{
	[Header("Team Rows")]
	[SerializeField]
	private GameScoreboardTeamRowView teamRowPrefab;

	[SerializeField]
	private int maxTeamRowCount = 8;

	private GameScoreboardTeamRowView[] teamRows;

	private ElementColors _colors;

	public override ElementColors Colors
	{
		get
		{
			return _colors;
		}
		set
		{
			_colors = value;
			for (int i = 0; i < teamRows.Length; i++)
			{
				teamRows[i].Colors = _colors;
			}
		}
	}

	public void SetGameModel(GameUIState state, GameUIDataModel model)
	{
		int i;
		for (i = 0; i < model.TeamModels.Length && i < teamRows.Length; i++)
		{
			teamRows[i].gameObject.SetActive(value: true);
			ElementColors colors = Colors;
			colors.BackgroundColor = model.TeamModels[i].Color;
			teamRows[i].Colors = colors;
			teamRows[i].SetTeamModel(state, model.TeamModels[i], model.SupportsScore);
		}
		for (; i < teamRows.Length; i++)
		{
			teamRows[i].gameObject.SetActive(value: false);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		teamRows = new GameScoreboardTeamRowView[maxTeamRowCount];
		for (int i = 0; i < maxTeamRowCount; i++)
		{
			teamRows[i] = UnityEngine.Object.Instantiate(teamRowPrefab);
			teamRows[i].transform.SetParent(base.transform, worldPositionStays: false);
			teamRows[i].gameObject.SetActive(value: false);
		}
	}
}
public class GameScoreboardElementView : UnityEngine.MonoBehaviour
{
	public struct ElementColors
	{
		public Color TextColor;

		public Color BackgroundColor;

		public float DefaultBackgroundAlpha;

		public float HighlightBackgroundAlpha;
	}

	[SerializeField]
	protected UnityEngine.UI.Image[] backgroundImages;

	protected Text[] allText;

	public virtual ElementColors Colors { get; set; }

	protected virtual void Awake()
	{
		allText = GetComponentsInChildren<Text>();
	}

	protected void ApplyColors(bool useHighlightAlpha)
	{
		Color backgroundColor = Colors.BackgroundColor;
		backgroundColor.a = ((!useHighlightAlpha) ? Colors.DefaultBackgroundAlpha : Colors.HighlightBackgroundAlpha);
		if (backgroundImages != null)
		{
			for (int i = 0; i < backgroundImages.Length; i++)
			{
				backgroundImages[i].color = backgroundColor;
			}
		}
		for (int j = 0; j < allText.Length; j++)
		{
			allText[j].color = Colors.TextColor;
		}
	}
}
public class GameScoreboardFooterView : GameScoreboardElementView
{
	[Serializable]
	private struct ButtonColumnView
	{
		public GameObject ButtonColumn;

		public Button Button;

		public Text ButtonText;
	}

	[Header("Text")]
	[SerializeField]
	private GameObject configRow;

	[SerializeField]
	private Text configText;

	[Header("Buttons")]
	[SerializeField]
	private GameObject buttonRow;

	[SerializeField]
	private ButtonColumnView joinGameButtonColumn;

	[SerializeField]
	private ButtonColumnView startGameButtonColumn;

	[SerializeField]
	private ButtonColumnView switchTeamButtonColumn;

	[SerializeField]
	private ButtonColumnView switchModeButtonColumn;

	[SerializeField]
	private ButtonColumnView viewResultsButtonColumn;

	private const string JOIN_TEXT = "JOIN";

	private const string LEAVE_TEXT = "SPECTATE";

	private const string NEXT_TEXT = "NEXT";

	private const string RESULTS_TEXT = "RESULTS";

	public void SetGameModel(GameUIState state, GameUIDataModel model)
	{
		switch (state)
		{
		case GameUIState.WAITING_FOR_PLAYERS:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: true);
			viewResultsButtonColumn.ButtonColumn.SetActive(model.SupportsPreviousGameResults);
			viewResultsButtonColumn.Button.interactable = true;
			viewResultsButtonColumn.ButtonText.text = "RESULTS";
			joinGameButtonColumn.ButtonColumn.SetActive(value: false);
			startGameButtonColumn.ButtonColumn.SetActive(value: true);
			startGameButtonColumn.Button.interactable = false;
			switchTeamButtonColumn.ButtonColumn.SetActive(model.SupportsTeamSwitching);
			switchTeamButtonColumn.Button.interactable = model.LocalPlayer.CanSwitchTeams;
			switchModeButtonColumn.ButtonColumn.SetActive(model.SupportsModeSwitching);
			break;
		case GameUIState.PRE_GAME:
			configRow.SetActive(value: false);
			configText.text = model.ModeName;
			buttonRow.SetActive(value: true);
			viewResultsButtonColumn.ButtonColumn.SetActive(model.SupportsPreviousGameResults);
			viewResultsButtonColumn.Button.interactable = true;
			viewResultsButtonColumn.ButtonText.text = "RESULTS";
			if (model.LocalPlayer.IsSpectator)
			{
				startGameButtonColumn.ButtonColumn.SetActive(value: false);
				switchTeamButtonColumn.ButtonColumn.SetActive(value: false);
				switchModeButtonColumn.ButtonColumn.SetActive(value: false);
				joinGameButtonColumn.ButtonColumn.SetActive(value: true);
				joinGameButtonColumn.Button.interactable = model.LocalPlayer.CanJoinGame;
				joinGameButtonColumn.ButtonText.text = "JOIN";
			}
			else
			{
				buttonRow.SetActive(value: true);
				joinGameButtonColumn.ButtonColumn.SetActive(model.LocalPlayer.CanLeaveGame);
				joinGameButtonColumn.Button.interactable = true;
				joinGameButtonColumn.ButtonText.text = "SPECTATE";
				startGameButtonColumn.ButtonColumn.SetActive(value: true);
				startGameButtonColumn.Button.interactable = true;
				switchTeamButtonColumn.ButtonColumn.SetActive(model.SupportsTeamSwitching);
				switchTeamButtonColumn.Button.interactable = model.LocalPlayer.CanSwitchTeams;
				switchModeButtonColumn.ButtonColumn.SetActive(model.SupportsModeSwitching);
			}
			break;
		case GameUIState.GAME_STARTING:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: false);
			break;
		case GameUIState.GAME_ON:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: false);
			break;
		case GameUIState.GAME_RUNNING:
			if (model.LocalPlayer.IsSpectator)
			{
				configRow.SetActive(value: false);
				buttonRow.SetActive(value: true);
				startGameButtonColumn.ButtonColumn.SetActive(value: false);
				switchTeamButtonColumn.ButtonColumn.SetActive(value: false);
				switchModeButtonColumn.ButtonColumn.SetActive(value: false);
				joinGameButtonColumn.ButtonColumn.SetActive(value: true);
				joinGameButtonColumn.Button.interactable = model.LocalPlayer.CanJoinGame;
			}
			else
			{
				bool flag = string.IsNullOrEmpty(model.PresenceString);
				configRow.SetActive(!flag);
				if (!flag)
				{
					configText.text = model.PresenceString.ToUpper();
				}
				buttonRow.SetActive(value: false);
			}
			break;
		case GameUIState.GAME_OVER:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: false);
			break;
		case GameUIState.RESULTS_LOCKED:
		case GameUIState.RESULTS:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: true);
			joinGameButtonColumn.ButtonColumn.SetActive(value: false);
			startGameButtonColumn.ButtonColumn.SetActive(value: false);
			switchTeamButtonColumn.ButtonColumn.SetActive(value: false);
			switchModeButtonColumn.ButtonColumn.SetActive(value: false);
			viewResultsButtonColumn.ButtonColumn.SetActive(state != GameUIState.RESULTS_LOCKED);
			viewResultsButtonColumn.Button.interactable = true;
			viewResultsButtonColumn.ButtonText.text = "NEXT";
			break;
		}
		ApplyColors(useHighlightAlpha: false);
	}
}
