public class ObjectPool : UnityEngine.MonoBehaviour
{
	public class ObjectPoolEntry
	{
		public GameObject Prefab;

		[NonSerialized]
		public List<GameObject> Objects;

		public ObjectPoolEntry(GameObject prefab)
		{
			Prefab = prefab;
			Objects = new List<GameObject>();
		}
	}

	private Dictionary<string, ObjectPoolEntry> pools;

	private static ObjectPool _instance;

	private static GameObject _singleton;

	public static ObjectPool Instance
	{
		get
		{
			if (_instance == null)
			{
				_singleton = new GameObject();
				_instance = _singleton.AddComponent<ObjectPool>();
				_singleton.name = "[ObjectPool]";
			}
			return _instance;
		}
	}

	private void Awake()
	{
		if (base.gameObject != _singleton)
		{
			UnityEngine.Object.DestroyImmediate(base.gameObject);
		}
		else
		{
			pools = new Dictionary<string, ObjectPoolEntry>();
		}
	}

	private GameObject InstantiateNewObject(GameObject prefab)
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(prefab);
		gameObject.name = prefab.name;
		gameObject.transform.parent = base.transform;
		return gameObject;
	}

	private ObjectPoolEntry FindOrCreatePool<T>(T newPrefab)
	{
		UnityEngine.MonoBehaviour monoBehaviour = newPrefab as UnityEngine.MonoBehaviour;
		if (monoBehaviour != null)
		{
			ObjectPoolEntry objectPoolEntry = FindPool(monoBehaviour.name);
			if (objectPoolEntry == null)
			{
				objectPoolEntry = new ObjectPoolEntry(monoBehaviour.gameObject);
				pools.Add(monoBehaviour.name, objectPoolEntry);
			}
			return objectPoolEntry;
		}
		return null;
	}

	private ObjectPoolEntry FindPool(string name)
	{
		pools.TryGetValue(name, out var value);
		return value;
	}

	public T Acquire<T>(T prefab)
	{
		ObjectPoolEntry objectPoolEntry = FindOrCreatePool(prefab);
		if (objectPoolEntry != null)
		{
			while (objectPoolEntry.Objects.Count > 0)
			{
				GameObject gameObject = objectPoolEntry.Objects[0];
				objectPoolEntry.Objects.RemoveAt(0);
				if (gameObject != null)
				{
					gameObject.SetActive(value: true);
					return gameObject.GetComponent<T>();
				}
				UnityEngine.Debug.LogError("ObjectPool '" + objectPoolEntry.Prefab.name + "' contains a null entry!");
			}
			if (objectPoolEntry.Prefab != null)
			{
				return InstantiateNewObject(objectPoolEntry.Prefab).GetComponent<T>();
			}
			UnityEngine.Debug.LogError("ObjectPool '" + objectPoolEntry.Prefab.name + "' contains a null Prefab reference!");
		}
		return default(T);
	}

	public bool Release(UnityEngine.MonoBehaviour obj)
	{
		ObjectPoolEntry objectPoolEntry = FindPool(obj.gameObject.name);
		if (objectPoolEntry != null)
		{
			if (!obj.gameObject.activeSelf)
			{
				UnityEngine.Debug.LogWarningFormat("ObjectPool is attemting to double release {0}", obj.name);
				return false;
			}
			obj.gameObject.SetActive(value: false);
			objectPoolEntry.Objects.Add(obj.gameObject);
			obj.transform.parent = base.transform;
			return true;
		}
		UnityEngine.Object.Destroy(obj);
		return false;
	}
}
public class PerformanceCounters : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class HistogramData
	{
		public string name;

		public Vector2 bounds;

		public bool InBounds(float value)
		{
			return bounds.WithinBounds(value);
		}
	}

	[SerializeField]
	private float updateInterval = 1f;

	[SerializeField]
	private float fpsLogInterval = 120f;

	[SerializeField]
	private float rttLogInterval = 120f;

	[SerializeField]
	[Tooltip("Round trip time to Photon Servers")]
	private HistogramData[] rttHistograms;

	[SerializeField]
	private HistogramData[] fpsHistograms;

	private int frameCount;

	private float nextUpdate;

	private float nextRttLogTime;

	private float nextFpsLogTime;

	private float accumulatedFPS;

	private float accumulatedPing;

	public float FPS { get; private set; }

	public float RountTripTime { get; private set; }

	private void Start()
	{
		Reset();
		SceneManager.sceneLoaded += SceneManager_sceneLoaded;
	}

	private void Update()
	{
		frameCount++;
		accumulatedFPS += Time.timeScale / Time.deltaTime;
		accumulatedPing += PhotonNetwork.GetPing();
		if (Time.time > nextUpdate && frameCount > 0)
		{
			FPS = accumulatedFPS / (float)frameCount;
			RountTripTime = accumulatedPing / (float)frameCount;
			accumulatedPing = 0f;
			accumulatedFPS = 0f;
			nextUpdate = Time.time + updateInterval;
			frameCount = 0;
			if (Time.time > nextRttLogTime)
			{
				AnalyticsHelper.ActivityServerRoundTripTime(RountTripTime, GetHistogramLabel(RountTripTime, rttHistograms));
				nextRttLogTime = Time.time + rttLogInterval;
			}
			if (Time.time > nextFpsLogTime)
			{
				AnalyticsHelper.ActivityFrameRate(FPS, GetHistogramLabel(FPS, fpsHistograms));
				nextFpsLogTime = Time.time + fpsLogInterval;
			}
		}
	}

	private void SceneManager_sceneLoaded(Scene arg0, LoadSceneMode arg1)
	{
		Reset();
	}

	private void Reset()
	{
		FPS = 0f;
		RountTripTime = 0f;
		frameCount = 0;
		accumulatedPing = 0f;
		accumulatedFPS = 0f;
		nextUpdate = Time.time + updateInterval;
		nextRttLogTime = Time.time + rttLogInterval;
		nextFpsLogTime = Time.time + fpsLogInterval;
	}

	private string GetHistogramLabel(float value, HistogramData[] histograms)
	{
		for (int i = 0; i < histograms.Length; i++)
		{
			if (histograms[i].InBounds(value))
			{
				return histograms[i].name;
			}
		}
		return string.Empty;
	}
}
public class PooledParticle : UnityEngine.MonoBehaviour
{
	private float maxDuration;

	public ParticleSystem PrimaryParticleSystem { get; private set; }

	public ParticleSystem[] AllParticleSystems { get; private set; }

	private void Awake()
	{
		PrimaryParticleSystem = GetComponent<ParticleSystem>();
		ParticleSystem.MainModule main = PrimaryParticleSystem.main;
		main.playOnAwake = false;
		AllParticleSystems = GetComponentsInChildren<ParticleSystem>(includeInactive: true);
		maxDuration = 0f;
		ParticleSystem[] allParticleSystems = AllParticleSystems;
		foreach (ParticleSystem particleSystem in allParticleSystems)
		{
			maxDuration = Mathf.Max(maxDuration, particleSystem.main.duration + particleSystem.main.startLifetime.constantMax);
		}
	}

	private void DeferredHide()
	{
		ObjectPool.Instance.Release(this);
	}

	public void Play()
	{
		PrimaryParticleSystem.Play();
		Invoke("DeferredHide", maxDuration);
	}
}
