public abstract class SynchronizedField
{
	public static void ClearAllFieldsForPlayer(PhotonPlayer player)
	{
		string prefix = FormatPlayerKey(player, string.Empty);
		ClearAllFieldsForPrefix(prefix);
	}

	public static void ClearAllFieldsForPhotonObject(Photon.MonoBehaviour component)
	{
		string prefix = FormatPhotonObjectKey(component, string.Empty);
		ClearAllFieldsForPrefix(prefix);
	}

	public static void ClearAllFieldsForMissingPlayers()
	{
		if (PhotonNetwork.room == null)
		{
			return;
		}
		HashSet<string> hashSet = new HashSet<string>();
		PhotonPlayer[] playerList = PhotonNetwork.playerList;
		foreach (PhotonPlayer photonPlayer in playerList)
		{
			hashSet.Add(photonPlayer.ID.ToString());
		}
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		int length = "PLAYER".Length;
		foreach (string key in PhotonNetwork.room.customProperties.Keys)
		{
			if (!key.StartsWith("PLAYER"))
			{
				continue;
			}
			string[] array = key.Split('.');
			if (array.Length <= 1 || array[0].Length <= length)
			{
				continue;
			}
			try
			{
				string item = array[0].Substring(length);
				if (!hashSet.Contains(item))
				{
					hashtable.Add(key, null);
				}
			}
			catch
			{
			}
		}
		if (hashtable.Count > 0)
		{
			PhotonNetwork.room.SetCustomProperties(hashtable);
		}
	}

	protected static string FormatPlayerKey(PhotonPlayer player, string key)
	{
		return $"PLAYER{player.ID}.{key}";
	}

	protected static string FormatPhotonObjectKey(Photon.MonoBehaviour component, string key)
	{
		return $"{component.photonView.viewID}.{key}";
	}

	protected static void ClearAllFieldsForPrefix(string prefix)
	{
		if (PhotonNetwork.room == null)
		{
			return;
		}
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		foreach (string key in PhotonNetwork.room.customProperties.Keys)
		{
			if (key.StartsWith(prefix))
			{
				hashtable.Add(key, null);
			}
		}
		if (hashtable.Count > 0)
		{
			PhotonNetwork.room.SetCustomProperties(hashtable);
		}
	}
}
public class SynchronizedField<T> : SynchronizedField
{
	private readonly Photon.MonoBehaviour component;

	private readonly string key;

	private readonly T defaultValue;

	private readonly SetterPermissionMode permissionMode;

	private readonly Action callback;

	private T cachedValue;

	public bool HasValue { get; private set; }

	public SynchronizedField(PhotonPlayer player, string key, T defaultValue, SetterPermissionMode permissionMode, Action callback = null)
		: this(SynchronizedField.FormatPlayerKey(player, key), defaultValue, permissionMode, callback)
	{
	}

	public SynchronizedField(Photon.MonoBehaviour component, string key, T defaultValue, SetterPermissionMode permissionMode, Action callback = null)
		: this(SynchronizedField.FormatPhotonObjectKey(component, key), defaultValue, permissionMode, callback)
	{
		this.component = component;
	}

	private SynchronizedField(string key, T defaultValue, SetterPermissionMode permissionMode, Action callback)
	{
		this.key = key;
		this.defaultValue = defaultValue;
		this.permissionMode = permissionMode;
		this.callback = callback;
		HasValue = PhotonNetwork.room != null && PhotonNetwork.room.customProperties.ContainsKey(key) && PhotonNetwork.room.customProperties[key] != null;
		cachedValue = ((!HasValue) ? defaultValue : ((T)PhotonNetwork.room.customProperties[key]));
		NetworkDataManager.Instance.RegisterCallback(key, OnValueChange);
	}

	~SynchronizedField()
	{
		if (NetworkDataManager.Instance != null)
		{
			NetworkDataManager.Instance.UnregisterCallback(key, OnValueChange);
		}
	}

	public T Get()
	{
		return cachedValue;
	}

	public void ForceSet(T newValue)
	{
		if (!HasPermissionToSet() || PhotonNetwork.room == null)
		{
			return;
		}
		if (HasValue)
		{
			ref T reference = ref cachedValue;
			object obj = newValue;
			if (reference.Equals(obj))
			{
				return;
			}
		}
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		hashtable.Add(key, newValue);
		ExitGames.Client.Photon.Hashtable propertiesToSet = hashtable;
		PhotonNetwork.room.SetCustomProperties(propertiesToSet);
	}

	public void CompareAndSwapSet(T newValue)
	{
		if (!HasValue)
		{
			ForceSet(newValue);
		}
		else if (HasPermissionToSet() && PhotonNetwork.room != null)
		{
			ref T reference = ref cachedValue;
			object obj = newValue;
			if (!reference.Equals(obj))
			{
				ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
				hashtable.Add(key, newValue);
				ExitGames.Client.Photon.Hashtable propertiesToSet = hashtable;
				hashtable = new ExitGames.Client.Photon.Hashtable();
				hashtable.Add(key, cachedValue);
				ExitGames.Client.Photon.Hashtable expectedValues = hashtable;
				PhotonNetwork.room.SetCustomProperties(propertiesToSet, expectedValues);
				UpdateCachedValue(newValue);
			}
		}
	}

	public void Clear()
	{
		if (PhotonNetwork.room != null && HasValue)
		{
			ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
			hashtable.Add(key, null);
			ExitGames.Client.Photon.Hashtable propertiesToSet = hashtable;
			PhotonNetwork.room.SetCustomProperties(propertiesToSet);
			cachedValue = defaultValue;
			HasValue = false;
		}
	}

	private bool HasPermissionToSet()
	{
		bool isMasterClient = PhotonNetwork.isMasterClient;
		bool flag = component != null && component.hasAuthority;
		return permissionMode == SetterPermissionMode.ANYONE || (permissionMode == SetterPermissionMode.MASTER && isMasterClient) || (permissionMode == SetterPermissionMode.AUTHORITY && flag) || (permissionMode == SetterPermissionMode.MASTER_OR_AUTHORITY && (isMasterClient || flag));
	}

	private void OnValueChange(object value)
	{
		UpdateCachedValue(value);
		if (callback != null)
		{
			callback();
		}
	}

	private void UpdateCachedValue(object value)
	{
		if (value == null)
		{
			HasValue = false;
			cachedValue = defaultValue;
		}
		else
		{
			HasValue = true;
			cachedValue = (T)value;
		}
	}
}
public class SynchronizedTimer : Timer
{
	protected SynchronizedField<float> SynchronizedStartTime;

	protected SynchronizedField<float> SynchronizedEndTime;

	protected SynchronizedField<float> SynchronizedPausedTimeElapsed;

	protected SynchronizedField<float> SynchronizedPausedTimeRemaining;

	protected SynchronizedField<bool> SynchronizedIsPaused;

	public override float StartTime
	{
		get
		{
			return SynchronizedStartTime.Get();
		}
		protected set
		{
			SynchronizedStartTime.ForceSet(value);
		}
	}

	public override float EndTime
	{
		get
		{
			return SynchronizedEndTime.Get();
		}
		protected set
		{
			SynchronizedEndTime.ForceSet(value);
		}
	}

	public override float PausedTimeElapsed
	{
		get
		{
			return SynchronizedPausedTimeElapsed.Get();
		}
		protected set
		{
			SynchronizedPausedTimeElapsed.ForceSet(value);
		}
	}

	public override float PausedTimeRemaining
	{
		get
		{
			return SynchronizedPausedTimeRemaining.Get();
		}
		protected set
		{
			SynchronizedPausedTimeRemaining.ForceSet(value);
		}
	}

	public override bool IsPaused
	{
		get
		{
			return SynchronizedIsPaused.Get();
		}
		protected set
		{
			SynchronizedIsPaused.ForceSet(value);
		}
	}

	public event Action StartTimerEvent;

	public SynchronizedTimer(Photon.MonoBehaviour component, string id, SetterPermissionMode permissionMode)
	{
		SynchronizedStartTime = new SynchronizedField<float>(component, GetKey(id, "TIMER_START_TIME"), 0f, permissionMode, OnStartTimeChange);
		SynchronizedEndTime = new SynchronizedField<float>(component, GetKey(id, "TIMER_END_TIME"), 0f, permissionMode);
		SynchronizedPausedTimeElapsed = new SynchronizedField<float>(component, GetKey(id, "TIMER_PAUSED_TIME_ELAPSED"), 0f, permissionMode);
		SynchronizedPausedTimeRemaining = new SynchronizedField<float>(component, GetKey(id, "TIMER_PAUSED_TIME_REMAINING"), 0f, permissionMode);
		SynchronizedIsPaused = new SynchronizedField<bool>(component, GetKey(id, "TIMER_IS_PAUSED"), defaultValue: false, permissionMode);
	}

	private string GetKey(string id, string subkey)
	{
		return id + "_" + subkey;
	}

	private void OnStartTimeChange()
	{
		if (this.StartTimerEvent != null)
		{
			this.StartTimerEvent();
		}
	}
}
public class TextureScale
{
	public class ThreadData
	{
		public int start;

		public int end;

		public ThreadData(int s, int e)
		{
			start = s;
			end = e;
		}
	}

	private enum Method
	{
		Point,
		Bilinear,
		Average
	}

	private static Color[] texColors;

	private static Color[] newColors;

	private static int w;

	private static float ratioX;

	private static float ratioY;

	private static int w2;

	private static int finishCount;

	private static Mutex mutex;

	public static void Point(Texture2D tex, int newWidth, int newHeight)
	{
		ThreadedScale(tex, newWidth, newHeight, Method.Point);
	}

	public static void Bilinear(Texture2D tex, int newWidth, int newHeight)
	{
		ThreadedScale(tex, newWidth, newHeight, Method.Bilinear);
	}

	public static void Average(Texture2D tex, int newWidth, int newHeight)
	{
		ThreadedScale(tex, newWidth, newHeight, Method.Average);
	}

	private static void ThreadedScale(Texture2D tex, int newWidth, int newHeight, Method method)
	{
		texColors = tex.GetPixels();
		newColors = new Color[newWidth * newHeight];
		switch (method)
		{
		case Method.Point:
			ratioX = (float)tex.width / (float)newWidth;
			ratioY = (float)tex.height / (float)newHeight;
			break;
		case Method.Bilinear:
			ratioX = 1f / ((float)newWidth / (float)(tex.width - 1));
			ratioY = 1f / ((float)newHeight / (float)(tex.height - 1));
			break;
		default:
			ratioX = (float)tex.width / (float)newWidth;
			ratioY = (float)tex.height / (float)newHeight;
			break;
		}
		w = tex.width;
		w2 = newWidth;
		int num = Mathf.Min(SystemInfo.processorCount, newHeight);
		int num2 = newHeight / num;
		finishCount = 0;
		if (mutex == null)
		{
			mutex = new Mutex(initiallyOwned: false);
		}
		if (num > 1)
		{
			int num3 = 0;
			ThreadData parameter;
			for (num3 = 0; num3 < num - 1; num3++)
			{
				parameter = new ThreadData(num2 * num3, num2 * (num3 + 1));
				Thread thread = new Thread(method switch
				{
					Method.Point => PointScale, 
					Method.Bilinear => BilinearScale, 
					_ => AverageScale, 
				});
				thread.Start(parameter);
			}
			parameter = new ThreadData(num2 * num3, newHeight);
			switch (method)
			{
			case Method.Point:
				PointScale(parameter);
				break;
			case Method.Bilinear:
				BilinearScale(parameter);
				break;
			default:
				AverageScale(parameter);
				break;
			}
			while (finishCount < num)
			{
				Thread.Sleep(1);
			}
		}
		else
		{
			ThreadData obj = new ThreadData(0, newHeight);
			switch (method)
			{
			case Method.Point:
				PointScale(obj);
				break;
			case Method.Bilinear:
				BilinearScale(obj);
				break;
			default:
				AverageScale(obj);
				break;
			}
		}
		tex.Resize(newWidth, newHeight);
		tex.SetPixels(newColors);
		tex.Apply();
	}

	public static void BilinearScale(object obj)
	{
		ThreadData threadData = (ThreadData)obj;
		for (int i = threadData.start; i < threadData.end; i++)
		{
			int num = (int)Mathf.Floor((float)i * ratioY);
			int num2 = num * w;
			int num3 = (num + 1) * w;
			int num4 = i * w2;
			for (int j = 0; j < w2; j++)
			{
				int num5 = (int)Mathf.Floor((float)j * ratioX);
				float value = (float)j * ratioX - (float)num5;
				ref Color reference = ref newColors[num4 + j];
				reference = ColorLerpUnclamped(ColorLerpUnclamped(texColors[num2 + num5], texColors[num2 + num5 + 1], value), ColorLerpUnclamped(texColors[num3 + num5], texColors[num3 + num5 + 1], value), (float)i * ratioY - (float)num);
			}
		}
		mutex.WaitOne();
		finishCount++;
		mutex.ReleaseMutex();
	}

	public static void PointScale(object obj)
	{
		ThreadData threadData = (ThreadData)obj;
		for (int i = threadData.start; i < threadData.end; i++)
		{
			int num = (int)(ratioY * (float)i) * w;
			int num2 = i * w2;
			for (int j = 0; j < w2; j++)
			{
				ref Color reference = ref newColors[num2 + j];
				reference = texColors[(int)((float)num + ratioX * (float)j)];
			}
		}
		mutex.WaitOne();
		finishCount++;
		mutex.ReleaseMutex();
	}

	private static Color GridAverage(int x, int y, float ratioX, float ratioY)
	{
		float num = 0f;
		float num2 = 0f;
		float num3 = 0f;
		float num4 = 0f;
		int num5 = 0;
		int num6 = (int)(0f - ratioX) / 2;
		int num7 = (int)(0f - ratioY) / 2;
		int num8 = (int)ratioX / 2;
		int num9 = (int)ratioY / 2;
		for (int i = num6; i <= num8; i++)
		{
			for (int j = num7; j <= num9; j++)
			{
				int num10 = y + j + (int)(ratioX * (float)(x + i));
				if (num10 >= 0 && num10 < texColors.Length)
				{
					num += texColors[num10].r;
					num2 += texColors[num10].g;
					num3 += texColors[num10].b;
					num4 += texColors[num10].a;
					num5++;
				}
			}
		}
		num /= (float)num5;
		num2 /= (float)num5;
		num3 /= (float)num5;
		num4 /= (float)num5;
		return new Color(num, num2, num3, num4);
	}

	public static void AverageScale(object obj)
	{
		ThreadData threadData = (ThreadData)obj;
		for (int i = threadData.start; i < threadData.end; i++)
		{
			int y = (int)(ratioY * (float)i) * w;
			int num = i * w2;
			for (int j = 0; j < w2; j++)
			{
				ref Color reference = ref newColors[num + j];
				reference = GridAverage(j, y, ratioX, ratioY);
			}
		}
		mutex.WaitOne();
		finishCount++;
		mutex.ReleaseMutex();
	}

	private static Color ColorLerpUnclamped(Color c1, Color c2, float value)
	{
		return new Color(c1.r + (c2.r - c1.r) * value, c1.g + (c2.g - c1.g) * value, c1.b + (c2.b - c1.b) * value, c1.a + (c2.a - c1.a) * value);
	}
}
public class Timer
{
	public delegate void Callback();

	private struct TimerCallback
	{
		public Callback Callback;

		public float TimeRemaining;

		public float TimeElapsed;

		public bool IsRecurring;

		public float RecurringDelay;
	}

	private List<TimerCallback> timerCallbacks = new List<TimerCallback>();

	private List<int> callbackRemoveIndices = new List<int>();

	public virtual float StartTime { get; protected set; }

	public virtual float EndTime { get; protected set; }

	public virtual float PausedTimeElapsed { get; protected set; }

	public virtual float PausedTimeRemaining { get; protected set; }

	public virtual bool IsPaused { get; protected set; }

	public float TimeElapsed => (!IsPaused) ? Mathf.Clamp((float)PhotonNetwork.time - StartTime, 0f, float.MaxValue) : PausedTimeElapsed;

	public float TimeRemaining => (!IsPaused) ? Mathf.Clamp(EndTime - (float)PhotonNetwork.time, 0f, float.MaxValue) : PausedTimeRemaining;

	public bool TimerOver => TimeRemaining <= 0f;

	public void StartTimer(float maxRunningTime)
	{
		ClearCallbacks();
		float num = (StartTime = (float)PhotonNetwork.time);
		EndTime = num + maxRunningTime;
		IsPaused = false;
	}

	public void StartTimerWithoutMaxRunningTime()
	{
		float maxRunningTime = float.MaxValue - (float)PhotonNetwork.time;
		StartTimer(maxRunningTime);
	}

	public void Pause()
	{
		if (!IsPaused)
		{
			PausedTimeElapsed = TimeElapsed;
			PausedTimeRemaining = TimeRemaining;
			IsPaused = true;
		}
	}

	public void Resume()
	{
		if (IsPaused)
		{
			float num = (StartTime = (float)PhotonNetwork.time);
			EndTime = num + PausedTimeRemaining;
			IsPaused = false;
		}
	}

	public void UpdateCallbacks()
	{
		callbackRemoveIndices.Clear();
		float timeElapsed = TimeElapsed;
		float num = timeElapsed + 1f;
		float timeRemaining = TimeRemaining;
		float num2 = timeRemaining + 1f;
		for (int i = 0; i < timerCallbacks.Count; i++)
		{
			if ((timeElapsed <= timerCallbacks[i].TimeElapsed && num > timerCallbacks[i].TimeElapsed) || (timeRemaining <= timerCallbacks[i].TimeRemaining && num2 > timerCallbacks[i].TimeRemaining))
			{
				timerCallbacks[i].Callback();
				if (timerCallbacks[i].IsRecurring)
				{
					TimerCallback value = timerCallbacks[i];
					value.TimeRemaining -= value.RecurringDelay;
					value.TimeElapsed += value.RecurringDelay;
					timerCallbacks[i] = value;
				}
				else
				{
					callbackRemoveIndices.Add(i);
				}
			}
		}
		for (int num3 = callbackRemoveIndices.Count - 1; num3 >= 0; num3--)
		{
			timerCallbacks.RemoveAt(callbackRemoveIndices[num3]);
		}
	}

	public void ClearCallbacks()
	{
		timerCallbacks.Clear();
	}

	public void AddTimeElapsedCallback(float timeElapsed, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = 2.1474836E+09f,
			TimeElapsed = timeElapsed,
			IsRecurring = false,
			RecurringDelay = 0f
		});
	}

	public void AddTimeElapsedCallback(float timeElapsed, float recurringDelay, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = 2.1474836E+09f,
			TimeElapsed = timeElapsed,
			IsRecurring = true,
			RecurringDelay = recurringDelay
		});
	}

	public void AddTimeRemainingCallback(float timeRemaining, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = timeRemaining,
			TimeElapsed = 2.1474836E+09f,
			IsRecurring = false,
			RecurringDelay = 0f
		});
	}

	public void AddTimeRemainingCallback(float timeRemaining, float recurringDelay, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = timeRemaining,
			TimeElapsed = 2.1474836E+09f,
			IsRecurring = true,
			RecurringDelay = recurringDelay
		});
	}
}
public static class UnityExtensions
{
	public static float SmallNumber = 0.0001f;

	public static float SmallDegree = 1f;

	public static void SetLayerRecursively(this GameObject gameObject, Layers layer)
	{
		gameObject.layer = (int)layer;
		foreach (Transform item in gameObject.transform)
		{
			item.gameObject.SetLayerRecursively(layer);
		}
	}

	public static void ReplaceLayerRecursively(this GameObject gameObject, Layers currentLayer, Layers desiredLayer)
	{
		if (gameObject.layer == (int)currentLayer)
		{
			gameObject.layer = (int)desiredLayer;
		}
		foreach (Transform item in gameObject.transform)
		{
			item.gameObject.ReplaceLayerRecursively(currentLayer, desiredLayer);
		}
	}

	public static bool IsInLayerMask(this GameObject gameObject, LayerMasks layerMask)
	{
		return ((uint)(1 << gameObject.layer) & (uint)layerMask) != 0;
	}

	public static T GetComponentInParents<T>(this GameObject gameObject) where T : UnityEngine.Component
	{
		Transform transform = gameObject.transform;
		while (transform != null)
		{
			T component = transform.GetComponent<T>();
			if (component != null)
			{
				return component;
			}
			transform = transform.parent;
		}
		return (T)null;
	}

	public static Color WithAlpha(this Color color, float alpha)
	{
		return new Color(color.r, color.g, color.b, alpha);
	}

	public static int AsLayerMask(this Layers layer)
	{
		return 1 << (int)layer;
	}

	public static void HideLayer(this Camera cam, Layers layer)
	{
		cam.HideLayerMask(layer.AsLayerMask());
	}

	public static void ShowLayer(this Camera cam, Layers layer)
	{
		cam.ShowLayerMask(layer.AsLayerMask());
	}

	public static void HideLayerMask(this Camera cam, int layerMask)
	{
		cam.cullingMask &= ~layerMask;
	}

	public static void ShowLayerMask(this Camera cam, int layerMask)
	{
		cam.cullingMask |= layerMask;
	}

	public static void SetKeywordEnabled(this Material mat, string keyword, bool enabled)
	{
		if (enabled)
		{
			mat.EnableKeyword(keyword);
		}
		else
		{
			mat.DisableKeyword(keyword);
		}
	}

	public static AnimationCurve DefaultAnimationCurve()
	{
		return AnimationCurve.Linear(0f, 0f, 1f, 1f);
	}

	public static void ClearVelocity(this Rigidbody rb)
	{
		rb.velocity = Vector3.zero;
		rb.angularVelocity = Vector3.zero;
	}

	public static Vector3 ProjectVectorToPlane(Vector3 source, Plane plane)
	{
		return source - Vector3.Dot(source, plane.normal) * plane.normal;
	}

	public static Quaternion FromToRotation(Quaternion from, Quaternion to)
	{
		return to * Quaternion.Inverse(from);
	}

	public static Quaternion QuaternionFromAngularVelocity(Vector3 angularVelocity)
	{
		return Quaternion.AngleAxis(angularVelocity.magnitude * 57.29578f, angularVelocity.normalized);
	}

	public static Vector3 AngularVelocityFromTo(Quaternion from, Quaternion to)
	{
		FromToRotation(from, to).ToAngleAxis(out var angle, out var axis);
		if (angle > 180f)
		{
			angle -= 360f;
		}
		return angle * axis * ((float)Math.PI / 180f);
	}

	public static Vector3 TransformToWorldSpace(this Vector3 v, Vector3 localSpaceOrigin, Vector3 localSpaceRight, Vector3 localSpaceUp, Vector3 localSpaceForward)
	{
		return localSpaceOrigin + v.x * localSpaceRight + v.y * localSpaceUp + v.z * localSpaceForward;
	}

	public static Vector3 TransformToWorldSpace(this Vector3 v, Vector3 localSpaceOrigin, Quaternion localSpaceRotation)
	{
		return localSpaceOrigin + localSpaceRotation * v;
	}

	public static Quaternion InverseTransformRotation(this Transform transform, Quaternion rotation)
	{
		return Quaternion.Inverse(transform.rotation) * rotation;
	}

	public static Quaternion TransformRotation(this Transform transform, Quaternion rotation)
	{
		return transform.rotation * rotation;
	}

	public static Quaternion TransformRotation(this Quaternion parent, Quaternion rotation)
	{
		return parent * rotation;
	}

	public static void SetCustomProperties<T>(this Room room, string propertyName, T newPropertyValue, T expectedValues)
	{
		if (room != null)
		{
			ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
			hashtable.Add(propertyName, newPropertyValue);
			ExitGames.Client.Photon.Hashtable hashtable2 = new ExitGames.Client.Photon.Hashtable();
			hashtable2.Add(propertyName, expectedValues);
			room.SetCustomProperties(hashtable, hashtable2);
		}
	}

	public static void SetCustomProperties<T>(this Room room, string propertyName, T newPropertyValue)
	{
		if (room != null)
		{
			ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
			hashtable.Add(propertyName, newPropertyValue);
			room.SetCustomProperties(hashtable);
		}
	}

	public static string GetCustomPropertyString(this PhotonPlayer player, string propertyName)
	{
		if (player != null && player.customProperties.ContainsKey(propertyName))
		{
			return player.customProperties[propertyName] as string;
		}
		return null;
