	public static void ShuffleArray<T>(T[] array, int randomSeed)
	{
		int num = array.Length;
		UnityEngine.Random.InitState(randomSeed);
		while (num > 1)
		{
			int num2 = UnityEngine.Random.Range(0, num--);
			T val = array[num];
			array[num] = array[num2];
			array[num2] = val;
		}
	}

