public class AnimateInOut : UnityEngine.MonoBehaviour
{
	[Header("Prefab")]
	[SerializeField]
	private ParticleSystem effectPrefab;

	[Header("Bounds")]
	[SerializeField]
	private Collider boundingCollider;

	[Header("Timing")]
	[SerializeField]
	private float animInStartOffset = 0.2f;

	[SerializeField]
	private float animOutStartOffset = 0.2f;

	[Header("Effect Support")]
	[SerializeField]
	private bool supportsAnimateIn = true;

	[SerializeField]
	private bool supportsAnimateOut = true;

	public bool SuppressAnimation;

	private ParticleSystem latestEffect;

	private bool updatePositionWhilePlaying = true;

	private List<Renderer> renderers;

	public List<Renderer> ignoredRenderers = new List<Renderer>();

	public List<Renderer> additionalRenderers = new List<Renderer>();

	private void Awake()
	{
		SceneManager.sceneUnloaded += OnSceneUnloaded;
	}

	private void OnEnable()
	{
		if (!SuppressAnimation && !AnimateInOutManager.SuppressAnimations && supportsAnimateIn)
		{
			PlayEffect(animIn: true);
		}
	}

	private void OnDisable()
	{
		if (!SuppressAnimation && !AnimateInOutManager.SuppressAnimations && supportsAnimateOut)
		{
			PlayEffect(animIn: false);
		}
	}

	private void Update()
	{
		if ((bool)latestEffect && latestEffect.isPlaying && updatePositionWhilePlaying)
		{
			UpdateEffectPosition(base.transform.position);
		}
	}

	public void PlayEffect(bool animIn, Vector3? position = null)
	{
		if (AnimateInOutManager.Instance != null)
		{
			if (effectPrefab == null)
			{
				effectPrefab = AnimateInOutManager.Instance.DefaultEffectPrefab;
			}
			latestEffect = UnityEngine.Object.Instantiate(effectPrefab);
			latestEffect.transform.parent = AnimateInOutManager.Instance.transform;
			UpdateEffectPosition((!position.HasValue) ? base.transform.position : position.Value);
			latestEffect.Simulate((!animIn) ? animOutStartOffset : animInStartOffset);
			latestEffect.Play();
			updatePositionWhilePlaying = animIn && !position.HasValue;
		}
	}

	public void StopEffect()
	{
		if ((bool)latestEffect)
		{
			UnityEngine.Object.Destroy(latestEffect.gameObject);
			latestEffect = null;
		}
	}

	private void UpdateEffectPosition(Vector3 position)
	{
		if (GetEffectBounds(out var bounds))
		{
			latestEffect.transform.position = bounds.center - base.transform.position + position;
			ParticleSystem.ShapeModule shape = latestEffect.shape;
			shape.box = bounds.size * 1.3f;
			float num = Mathf.Max(bounds.size.x, bounds.size.y, bounds.size.z);
			ParticleSystem.MainModule main = latestEffect.main;
			main.startSize = num * 0.3f;
		}
		else
		{
			latestEffect.transform.position = position;
		}
	}

	private bool GetEffectBounds(out Bounds bounds)
	{
		if (boundingCollider != null)
		{
			bounds = boundingCollider.bounds;
			return true;
		}
		if (renderers == null)
		{
			renderers = GetComponentsInChildren<Renderer>().ToList();
			renderers.RemoveAll((Renderer r) => ignoredRenderers.Contains(r));
			renderers.RemoveAll((Renderer r) => r.gameObject.GetComponent<ImpactDecal>() != null);
		}
		return UnityExtensions.GetCombinedRendererBounds(renderers, out bounds);
	}

	private void OnSceneUnloaded(Scene scene)
	{
		SceneManager.sceneUnloaded -= OnSceneUnloaded;
		if (latestEffect != null)
		{
			UnityEngine.Object.DestroyImmediate(latestEffect.gameObject);
		}
	}
}
public class AnimateInOutManager : UnityEngine.MonoBehaviour
{
	public ParticleSystem DefaultEffectPrefab;

	public static bool SuppressAnimations = true;

	public static AnimateInOutManager Instance { get; private set; }

	private void Awake()
	{
		Instance = this;
		SceneManager.sceneUnloaded += SceneManager_sceneUnloaded;
	}

	private void OnApplicationQuit()
	{
		SuppressAnimations = true;
	}

	private void SceneManager_sceneUnloaded(Scene scene)
	{
		SuppressAnimations = true;
		for (int i = 0; i < base.transform.childCount; i++)
		{
			UnityEngine.Object.Destroy(base.transform.GetChild(i).gameObject);
		}
	}
}
[RequireComponent(typeof(ParticleSystem))]
public class AutoDestroyParticleSystem : UnityEngine.MonoBehaviour
{
	private ParticleSystem effect;

	private void Awake()
	{
		effect = GetComponent<ParticleSystem>();
	}

	private void Update()
	{
		if (!effect || !effect.isPlaying)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}
}
public class BobbingMotion : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float scaleBobAmount;

	[SerializeField]
	private float scaleBobSpeed;

	private float bobHeight;

	private void Awake()
	{
		scaleBobSpeed += UnityEngine.Random.Range(-0.2f, 0.2f);
	}

	private void FixedUpdate()
	{
		bobHeight = Mathf.Sin(Time.time * scaleBobSpeed) * scaleBobAmount;
		base.transform.localPosition = new Vector3(0f, bobHeight, 0f);
	}
}
public class CameraFade : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float fadeOutDelay = 0.4f;

	[SerializeField]
	private float fadeInDelay = 0.4f;

	[SerializeField]
	private float fadeOutDuration = 1f;

	[SerializeField]
	private float fadeInDuration = 0.25f;

	[SerializeField]
	private AnimateInOut effect;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip RezOutAudio;

	[SerializeField]
	private RecRoomAudioClip RezInAudio;

	private FadeImageEffect fadeEffect;

	private Coroutine fadeCoroutine;

	public static CameraFade Instance { get; private set; }

	public float TotalFadeInDuration => fadeInDelay + fadeInDuration;

	public float TotalFadeOutDuration => fadeOutDelay + fadeOutDuration;

	public bool IsFading => fadeCoroutine != null;

	private void Awake()
	{
		Instance = this;
		fadeEffect = GetComponentInChildren<FadeImageEffect>();
	}

	public Coroutine Fade(bool fadeIn, bool prepForLevelSwitch = false, bool suppressEffect = false, float overrideDuration = 0f)
	{
		if (fadeCoroutine != null)
		{
			StopCoroutine(fadeCoroutine);
		}
		fadeCoroutine = StartCoroutine(FadeCoroutine(fadeIn, prepForLevelSwitch, suppressEffect, overrideDuration));
		return fadeCoroutine;
	}

	private IEnumerator FadeCoroutine(bool fadeIn, bool prepForLevelSwitch, bool suppressEffect, float overrideDuration)
	{
		if (!suppressEffect)
		{
			AnimateInOutManager.SuppressAnimations = false;
			effect.StopEffect();
			effect.PlayEffect(fadeIn);
			if (RezInAudio.audioClip != null && RezOutAudio.audioClip != null)
			{
				AudioManager.Play2DSFX((!fadeIn) ? RezOutAudio : RezInAudio);
			}
		}
		if (fadeIn)
		{
			if (OpenVR.Compositor != null)
			{
				OpenVR.Compositor.SuspendRendering(bSuspend: false);
			}
			yield return new WaitForSeconds(fadeInDelay);
			if (OpenVR.Compositor != null)
			{
				OpenVR.Compositor.FadeToColor(0.05f, 0f, 0f, 0f, 0f, bBackground: false);
			}
			yield return fadeEffect.FadeIn((overrideDuration != 0f) ? overrideDuration : fadeInDuration);
		}
		else
		{
			if (!suppressEffect)
			{
				yield return new WaitForSeconds(fadeOutDelay);
			}
			yield return fadeEffect.FadeOut((overrideDuration != 0f) ? overrideDuration : fadeOutDuration);
			if (prepForLevelSwitch && OpenVR.Compositor != null)
			{
				OpenVR.Compositor.FadeToColor(0.05f, 0f, 0f, 0f, 1f, bBackground: false);
				OpenVR.Compositor.SuspendRendering(bSuspend: true);
			}
		}
		fadeCoroutine = null;
	}
}
public class CollisionParticles : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class ParticlesToLayer
	{
		public string Name;

		public ParticleSystem ParticleSystemPrefab;

		public LayerMask Layers;

		public string Tag = string.Empty;

		[Tooltip("Per particle cooldown to limit the number of consequtive plays. Set it to the particle duration")]
		public float InstanceLimitDuration;

		private ParticleSystem particleSystemInstance;

		public float LastInstanceTime { get; set; }

		public ParticleSystem GetParticleSystem()
		{
			if (particleSystemInstance == null)
			{
				particleSystemInstance = UnityEngine.Object.Instantiate(ParticleSystemPrefab);
			}
			return particleSystemInstance;
		}

		public bool CanPlay(GameObject go, LayerMask layerMask)
		{
			if (Time.time - LastInstanceTime > InstanceLimitDuration && (Layers.value & (int)layerMask) == (int)layerMask && (string.IsNullOrEmpty(Tag) || go.CompareTag(Tag)))
			{
				LastInstanceTime = Time.time;
				return true;
			}
			return false;
		}
	}

	private Tool thisTool;

	[SerializeField]
	private ParticlesToLayer[] particleMappings;

	private void Awake()
	{
		thisTool = GetComponent<Tool>();
	}

	private void OnDestroy()
	{
		ParticlesToLayer[] array = particleMappings;
		foreach (ParticlesToLayer particlesToLayer in array)
		{
			ParticleSystem particleSystem = particlesToLayer.GetParticleSystem();
			if (particleSystem != null)
			{
				particleSystem.Stop();
				UnityEngine.Object.Destroy(particleSystem.gameObject);
			}
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (thisTool != null && thisTool.IsHeld)
		{
			return;
		}
		int num = 1 << collision.gameObject.layer;
		ParticlesToLayer[] array = particleMappings;
		foreach (ParticlesToLayer particlesToLayer in array)
		{
			if (particlesToLayer.CanPlay(collision.gameObject, num))
			{
				ParticleSystem particleSystem = particlesToLayer.GetParticleSystem();
				if (particleSystem != null)
				{
					particleSystem.Stop();
					UnityEngine.Debug.Log("OnCollision enter" + collision);
					particleSystem.transform.position = base.transform.position;
					particleSystem.Play();
				}
				break;
			}
		}
	}
}
public abstract class CustomTrail<T> : UnityEngine.MonoBehaviour where T : Renderer
{
	[Header("Visuals")]
	[SerializeField]
	protected Material[] materials;

	[SerializeField]
	private bool castShadows;

	[SerializeField]
	private bool receiveShadows;

	[Header("Layout")]
	[SerializeField]
	protected float lifetime = 5f;

	[SerializeField]
	protected Vector2 alphas = new Vector2(0f, 1f);

	[SerializeField]
	protected Vector2 widths = new Vector2(0.2f, 0.8f);

	[SerializeField]
	protected float minSpacing = 0.01f;

	[Header("End Caps")]
	[SerializeField]
	protected bool displayStartCap;

	[SerializeField]
	protected Renderer startCap;

	[SerializeField]
	protected bool displayEndCap;

	[SerializeField]
	protected Renderer endCap;

	protected static int ParticleMaterialColorId = -1;

	protected float fadeAlpha = 1f;

	protected float widthScale = 1f;

	protected float minSpacingSqr;

	protected bool lineDirty = true;

	protected T[] renderers;

	protected List<float> pointTimeStamps = new List<float>();

	protected List<Vector3> points = new List<Vector3>();

	protected List<Vector3> tangents = new List<Vector3>();

	protected List<float> segmentLengths = new List<float>();

	public abstract Color Color { get; set; }

	public abstract Vector2 Widths { get; set; }

	public bool Running => points.Count > 0;

	public float Length
	{
		get
		{
			float num = 0f;
			for (int i = 0; i < segmentLengths.Count; i++)
			{
				num += segmentLengths[i];
			}
			return num;
		}
	}

	protected bool RenderersEnabled
	{
		set
		{
			if (renderers != null)
			{
				for (int i = 0; i < renderers.Length; i++)
				{
					renderers[i].enabled = value;
				}
			}
			if (startCap != null)
			{
				startCap.enabled = value;
			}
			if (endCap != null)
			{
				endCap.enabled = value;
			}
		}
	}

	protected abstract void ApplyPoints();

	public virtual void Clear()
	{
		pointTimeStamps.Clear();
		points.Clear();
		tangents.Clear();
		segmentLengths.Clear();
		lineDirty = true;
		UpdateLine();
	}

	protected virtual void Awake()
	{
		ParticleMaterialColorId = Shader.PropertyToID("_TintColor");
		minSpacingSqr = minSpacing * minSpacing;
		if (materials == null || materials.Length == 0)
		{
			UnityEngine.Debug.LogError("Trail on " + base.gameObject.name + " is missing materials.");
			return;
		}
		renderers = new T[materials.Length];
		T[] componentsInChildren = GetComponentsInChildren<T>(includeInactive: true);
		int i;
		for (i = 0; i < renderers.Length && i < componentsInChildren.Length; i++)
		{
			renderers[i] = componentsInChildren[i];
		}
		GameObject gameObject = base.gameObject;
		for (; i < renderers.Length; i++)
		{
			if (i > 0)
			{
				gameObject = new GameObject(materials[i].name);
				gameObject.transform.SetParent(base.transform, worldPositionStays: false);
			}
			renderers[i] = gameObject.AddComponent<T>();
		}
		for (; i < componentsInChildren.Length; i++)
		{
			UnityEngine.Object.Destroy(componentsInChildren[i]);
		}
		for (i = 0; i < renderers.Length; i++)
		{
			ref readonly T reference = ref renderers[i];
			Material sharedMaterial = materials[i];
			reference.sharedMaterial = sharedMaterial;
			ref readonly T reference2 = ref renderers[i];
			int shadowCastingMode = (castShadows ? 1 : 0);
			reference2.shadowCastingMode = (ShadowCastingMode)shadowCastingMode;
			ref readonly T reference3 = ref renderers[i];
			bool num = receiveShadows;
			reference3.receiveShadows = num;
		}
		Widths = widths;
		Color = Color.white;
	}

	protected virtual void OnEnable()
	{
		RenderersEnabled = true;
		Clear();
	}

	protected virtual void OnDisable()
	{
		RenderersEnabled = false;
		Clear();
	}

	protected virtual void Update()
	{
		UpdateLine();
	}

	protected void UpdateLine()
	{
		float num = Time.time - lifetime;
		int i;
		for (i = 0; i < pointTimeStamps.Count && pointTimeStamps[i] <= num; i++)
		{
		}
		if (i > 0)
		{
			pointTimeStamps.RemoveRange(0, i);
			points.RemoveRange(0, i);
			tangents.RemoveRange(0, i);
			if (i + 1 < segmentLengths.Count)
			{
				segmentLengths[i + 1] = 0f;
			}
			segmentLengths.RemoveRange(0, i);
			lineDirty = true;
		}
		if (lineDirty)
		{
			ApplyPoints();
			lineDirty = false;
		}
		if (points.Count < 2)
		{
			RenderersEnabled = false;
		}
		else if (points.Count > 1)
		{
			if (displayStartCap && startCap != null)
			{
				startCap.transform.position = points[0];
				Vector3 normalized = (points[0] - points[1]).normalized;
				startCap.transform.rotation = Quaternion.LookRotation(normalized);
			}
			if (displayEndCap && endCap != null)
			{
				endCap.transform.position = points[points.Count - 1];
				Vector3 normalized2 = (points[points.Count - 2] - points[points.Count - 1]).normalized;
				endCap.transform.rotation = Quaternion.LookRotation(normalized2);
			}
		}
	}

	protected virtual void AddNewPosition(Vector3 newPosition, Vector3 newTangent, float addTime)
	{
		if (points.Count > 0)
		{
			segmentLengths.Add((newPosition - points[points.Count - 1]).magnitude);
		}
		else
		{
			segmentLengths.Add(0f);
		}
		points.Add(newPosition);
		tangents.Add(newTangent);
		pointTimeStamps.Add(addTime);
		lineDirty = true;
		RenderersEnabled = true;
	}

	protected void UpdatePoint(int index, Vector3 newPosition, Vector3 newTangent)
	{
		if (index < points.Count)
		{
			points[index] = newPosition;
			tangents[index] = newTangent;
			if (index > 0)
			{
				segmentLengths[index] = (points[index] - points[index - 1]).magnitude;
			}
			if (index + 1 < points.Count)
			{
				segmentLengths[index + 1] = (points[index + 1] - points[index]).magnitude;
			}
		}
	}
}
[RequireComponent(typeof(Camera))]
public class DesaturateEffect : UnityEngine.MonoBehaviour
{
	public enum Mode
	{
		FullScreen,
		PartialScreen,
		TargetedToOverlayUI
	}

	[SerializeField]
	private Shader desaturateEffectShader;

	[SerializeField]
	private Mode mode;

	[Header("PartialScreen Mode Config")]
	[SerializeField]
	private Vector2 partialScreenBottomLeft = new Vector2(0f, 0.2f);

	[SerializeField]
	private Vector2 partialScreenTopRight = new Vector2(1f, 0.4f);

	[SerializeField]
	[Range(0f, 1f)]
	private float partialScreenEdgeFade = 0.02f;

	[Header("TargetedToOverlayUI Mode Config")]
	[SerializeField]
	private int maskTextureSize = 256;

	[SerializeField]
	private int expandIterations = 4;

	[SerializeField]
	private int blurIterations = 2;

	[Header("Desaturation Config")]
	[SerializeField]
	[Range(0f, 1f)]
	private float maxDesaturation = 1f;

	[SerializeField]
	[Range(0f, 1f)]
	private float desaturatedBlackLevel;

	[SerializeField]
	[Range(0f, 1f)]
	private float desaturatedWhiteLevel = 1f;

	private Camera camera;

	private Camera desaturateMaskGenerator;

	private RenderTexture desaturateMaskTexture;

	private Material desaturateMaterial;

	private float currentDesaturation;

	private static int SampleOffsetPropId;

	private static int RegionParamsPropId;

	private static int ScreenEdgeFadePropId;

	private static int DesaturationAmountPropId;

	private static int ColorMappingParamsPropId;

	private static int DesaturationMaskPropId;

	public float DesaturationLevel
	{
		get
		{
			return currentDesaturation;
		}
		set
		{
			currentDesaturation = value;
			base.enabled = currentDesaturation > 0f || mode == Mode.TargetedToOverlayUI;
		}
	}

	public Mode CurrentMode
	{
		get
		{
			return mode;
		}
		set
		{
			mode = value;
			base.enabled = currentDesaturation > 0f || mode == Mode.TargetedToOverlayUI;
		}
	}

	private void Awake()
	{
		SampleOffsetPropId = Shader.PropertyToID("_SampleOffset");
		RegionParamsPropId = Shader.PropertyToID("_RegionParams");
		ScreenEdgeFadePropId = Shader.PropertyToID("_ScreenEdgeFade");
		DesaturationAmountPropId = Shader.PropertyToID("_DesaturationAmount");
		ColorMappingParamsPropId = Shader.PropertyToID("_ColorMappingParams");
		DesaturationMaskPropId = Shader.PropertyToID("_DesaturationMask");
		camera = GetComponent<Camera>();
		int num = maskTextureSize;
		int height = maskTextureSize;
		if (camera.stereoEnabled)
		{
			num *= 2;
		}
		desaturateMaskTexture = new RenderTexture(num, height, 0);
		GameObject gameObject = new GameObject("DesatMaskGenerator", typeof(Camera));
		desaturateMaskGenerator = gameObject.GetComponent<Camera>();
		desaturateMaskGenerator.transform.parent = base.transform;
		desaturateMaskGenerator.cullingMask = 4194304;
		desaturateMaskGenerator.clearFlags = CameraClearFlags.Color;
		desaturateMaskGenerator.backgroundColor = Color.clear;
		desaturateMaskGenerator.targetTexture = desaturateMaskTexture;
		desaturateMaskGenerator.enabled = false;
		desaturateMaterial = new Material(desaturateEffectShader);
	}

	private void OnPreRender()
	{
		if (mode == Mode.TargetedToOverlayUI)
		{
			GenerateDesatMask();
		}
	}

	private void GenerateDesatMask()
	{
		if (camera.stereoEnabled)
		{
			desaturateMaskGenerator.worldToCameraMatrix = camera.GetStereoViewMatrix(Camera.StereoscopicEye.Left);
			desaturateMaskGenerator.projectionMatrix = camera.GetStereoProjectionMatrix(Camera.StereoscopicEye.Left);
			desaturateMaskGenerator.rect = new Rect(0f, 0f, 0.5f, 1f);
			desaturateMaskGenerator.Render();
			desaturateMaskGenerator.worldToCameraMatrix = camera.GetStereoViewMatrix(Camera.StereoscopicEye.Right);
			desaturateMaskGenerator.projectionMatrix = camera.GetStereoProjectionMatrix(Camera.StereoscopicEye.Right);
			desaturateMaskGenerator.rect = new Rect(0.5f, 0f, 0.5f, 1f);
			desaturateMaskGenerator.Render();
		}
		else
		{
			desaturateMaskGenerator.worldToCameraMatrix = camera.worldToCameraMatrix;
			desaturateMaskGenerator.projectionMatrix = camera.projectionMatrix;
			desaturateMaskGenerator.rect = new Rect(0f, 0f, 1f, 1f);
			desaturateMaskGenerator.Render();
		}
		int width = desaturateMaskTexture.width / 4;
		int height = desaturateMaskTexture.height / 4;
		RenderTexture renderTexture = RenderTexture.GetTemporary(width, height, 0);
		desaturateMaterial.EnableKeyword("COMBINE_MAX");
		desaturateMaterial.SetFloat(SampleOffsetPropId, 0.5f);
		Graphics.Blit(desaturateMaskTexture, renderTexture, desaturateMaterial, 0);
		desaturateMaterial.SetFloat(SampleOffsetPropId, 1f);
		for (int i = 0; i < expandIterations; i++)
		{
			RenderTexture temporary = RenderTexture.GetTemporary(width, height, 0);
			Graphics.Blit(renderTexture, temporary, desaturateMaterial, 0);
			RenderTexture.ReleaseTemporary(renderTexture);
			renderTexture = temporary;
		}
		desaturateMaterial.DisableKeyword("COMBINE_MAX");
		for (int j = 0; j < blurIterations; j++)
		{
			desaturateMaterial.SetFloat(SampleOffsetPropId, 0.5f + (float)j * 0.6f);
			RenderTexture temporary2 = RenderTexture.GetTemporary(width, height, 0);
			Graphics.Blit(renderTexture, temporary2, desaturateMaterial, 0);
			RenderTexture.ReleaseTemporary(renderTexture);
			renderTexture = temporary2;
		}
		Graphics.Blit(renderTexture, desaturateMaskTexture);
		RenderTexture.ReleaseTemporary(renderTexture);
	}

	private void OnRenderImage(RenderTexture source, RenderTexture destination)
	{
		desaturateMaterial.SetKeywordEnabled("FULL_SCREEN_DESATURATION", mode == Mode.FullScreen);
		desaturateMaterial.SetKeywordEnabled("PARTIAL_SCREEN_DESATURATION", mode == Mode.PartialScreen);
		desaturateMaterial.SetKeywordEnabled("USE_DESATURATION_MASK", mode == Mode.TargetedToOverlayUI);
		desaturateMaterial.SetVector(ColorMappingParamsPropId, new Vector4(desaturatedWhiteLevel - desaturatedBlackLevel, desaturatedBlackLevel, maxDesaturation, 0f));
		if (mode == Mode.TargetedToOverlayUI)
		{
			desaturateMaterial.SetTexture(DesaturationMaskPropId, desaturateMaskTexture);
		}
		else
		{
			desaturateMaterial.SetVector(RegionParamsPropId, new Vector4(partialScreenBottomLeft.x, partialScreenBottomLeft.y, partialScreenTopRight.x, partialScreenTopRight.y));
			desaturateMaterial.SetFloat(ScreenEdgeFadePropId, partialScreenEdgeFade);
			desaturateMaterial.SetFloat(DesaturationAmountPropId, currentDesaturation);
		}
		Graphics.Blit(source, destination);
	}
}
public class DynamicMeshTrail : CustomTrail<MeshRenderer>
{
	private MeshFilter[] meshFilters;

	private List<Vector3> vertices = new List<Vector3>();

	private List<Color> vertexColors = new List<Color>();

	private List<Vector2> uvs = new List<Vector2>();

	private List<int> indices = new List<int>();

	private Mesh[] doubleBufferedMeshes;

	private int meshIndex;

	private Color color;

	private Vector2 _widths;

	private Mesh Mesh => doubleBufferedMeshes[meshIndex];

	public override Color Color
	{
		get
		{
			return color;
		}
		set
		{
			color = value;
		}
	}

	public override Vector2 Widths
	{
		get
		{
			return _widths;
		}
		set
		{
			_widths = value;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		doubleBufferedMeshes = new Mesh[2];
		for (int i = 0; i < doubleBufferedMeshes.Length; i++)
		{
			doubleBufferedMeshes[i] = new Mesh();
			doubleBufferedMeshes[i].MarkDynamic();
		}
		if (renderers != null)
		{
			meshFilters = new MeshFilter[renderers.Length];
			for (int j = 0; j < renderers.Length; j++)
			{
				meshFilters[j] = renderers[j].gameObject.AddComponent<MeshFilter>();
				meshFilters[j].mesh = Mesh;
			}
		}
	}

	protected override void ApplyPoints()
	{
		if (meshFilters != null)
		{
			meshIndex = (meshIndex + 1) % doubleBufferedMeshes.Length;
			vertices.Clear();
			uvs.Clear();
			vertexColors.Clear();
			indices.Clear();
			Color a = color;
			a.a = alphas[0] * fadeAlpha;
			Color b = color;
			b.a = alphas[1] * fadeAlpha;
			float num = Widths[0] * widthScale;
			float num2 = Widths[1] * widthScale;
			Vector2 zero = Vector2.zero;
			for (int i = 0; i < points.Count; i++)
			{
				float num3 = Mathf.InverseLerp(pointTimeStamps[i] + lifetime, pointTimeStamps[i], Time.time);
				float num4 = Mathf.Lerp(num, num2, num3) * 0.5f;
				vertices.Add(base.transform.InverseTransformPoint(points[i] + tangents[i] * num4));
				vertices.Add(base.transform.InverseTransformPoint(points[i] - tangents[i] * num4));
				Color item = Color.Lerp(a, b, num3);
				vertexColors.Add(item);
				vertexColors.Add(item);
				zero.x = 1f - num3;
				zero.y = 1f;
				uvs.Add(zero);
				zero.y = 0f;
				uvs.Add(zero);
			}
			int num5 = Mathf.Max(0, points.Count - 1);
			for (int j = 0; j < num5; j++)
			{
				int num6 = j * 2;
				indices.Add(num6);
				indices.Add(num6 + 2);
				indices.Add(num6 + 1);
				indices.Add(num6 + 2);
				indices.Add(num6 + 3);
				indices.Add(num6 + 1);
			}
			Mesh.Clear(keepVertexLayout: true);
			Mesh.vertices = vertices.ToArray();
			Mesh.colors = vertexColors.ToArray();
			Mesh.uv = uvs.ToArray();
			Mesh.triangles = indices.ToArray();
			for (int k = 0; k < meshFilters.Length; k++)
			{
				meshFilters[k].mesh = Mesh;
			}
			if (displayStartCap && startCap != null)
			{
				startCap.material.color = a;
				float num7 = num / 2f / startCap.transform.lossyScale.x;
				startCap.transform.localScale *= num7;
			}
			if (displayEndCap && endCap != null)
			{
				endCap.material.SetColor(CustomTrail<MeshRenderer>.ParticleMaterialColorId, b);
				float num8 = num2 / 2f / endCap.transform.lossyScale.x;
				endCap.transform.localScale *= num8;
			}
		}
	}
}
public class FadeImageEffect : UnityEngine.MonoBehaviour
{
	private PostEffectsMaterial postEffects;

	private float _fade;

	private bool _blind;

	private bool _fading;

	public float Fade
	{
		get
		{
			return _fade;
		}
		set
		{
			_fade = value;
			UpdateMaterial();
		}
	}

	public bool Blind
	{
		get
		{
			return _blind;
		}
		set
		{
			_blind = value;
			UpdateMaterial();
		}
	}

	private bool Fading
	{
		get
		{
			return _fading;
		}
		set
		{
			_fading = value;
			UpdateMaterial();
		}
	}

	private void Awake()
	{
		postEffects = GetComponentInChildren<PostEffectsMaterial>();
	}

	private void UpdateMaterial()
	{
		float fade = ((!Blind) ? Fade : 0f);
		postEffects.Fade = fade;
	}

	public Coroutine FadeIn(float duration)
	{
		Fading = true;
		StopAllCoroutines();
		return StartCoroutine(FadeCoroutine(fadeIn: true, duration));
	}

	public Coroutine FadeOut(float duration)
	{
		Fading = true;
		StopAllCoroutines();
		return StartCoroutine(FadeCoroutine(fadeIn: false, duration));
	}

	private IEnumerator FadeCoroutine(bool fadeIn, float duration)
	{
		float initialFade = ((!fadeIn) ? 1f : 0f);
		float finalFade = ((!fadeIn) ? 0f : 1f);
		float timer = 0f;
		while (timer < duration)
		{
			float t = timer / duration;
			Fade = Mathf.Lerp(initialFade, finalFade, t);
			timer += Time.deltaTime;
			yield return null;
		}
		Fade = finalFade;
		Fading = false;
	}
}
public class LineRendererTrail : CustomTrail<LineRenderer>
{
	private Color _color = Color.white;

	private Vector2 _widths;

	public override Color Color
	{
		get
		{
			return _color;
		}
		set
		{
			_color = value;
			if (renderers != null)
			{
				Color color = value;
				color.a = alphas.x * fadeAlpha;
				Color color2 = value;
				color2.a = alphas.y * fadeAlpha;
				for (int i = 0; i < renderers.Length; i++)
				{
					renderers[i].startColor = color;
					renderers[i].endColor = color2;
				}
				if (displayStartCap && startCap != null)
				{
					startCap.material.SetColor(CustomTrail<LineRenderer>.ParticleMaterialColorId, color);
				}
				if (displayEndCap && endCap != null)
				{
					endCap.material.SetColor(CustomTrail<LineRenderer>.ParticleMaterialColorId, color2);
				}
			}
		}
	}

	public override Vector2 Widths
	{
		get
		{
			return _widths;
		}
		set
		{
			_widths = value;
			for (int i = 0; i < renderers.Length; i++)
			{
				renderers[i].startWidth = _widths[0] * widthScale;
				renderers[i].endWidth = _widths[1] * widthScale;
			}
			if (displayStartCap && startCap != null)
			{
				float num = _widths[0] * widthScale / 2f / startCap.transform.lossyScale.x;
				startCap.transform.localScale *= num;
			}
			if (displayEndCap && endCap != null)
			{
				float num2 = _widths[1] * widthScale / 2f / endCap.transform.lossyScale.x;
				endCap.transform.localScale *= num2;
			}
		}
	}

	protected override void ApplyPoints()
	{
		if (renderers != null)
		{
			Vector2 mainTextureScale = new Vector2(base.Length, 1f);
			for (int i = 0; i < renderers.Length; i++)
			{
				renderers[i].numPositions = points.Count;
				renderers[i].SetPositions(points.ToArray());
				renderers[i].material.mainTextureScale = mainTextureScale;
			}
		}
	}
}
