public class PlayerTrail : LineRendererTrail
{
	[SerializeField]
	[Tooltip("Rate that trail will fade from tip to head.  In units of m/s.")]
	private float fadeOutRate = 10f;

	public void PlayTeleportTrail(Vector3 playerHeadOffset, Vector3 startPlayerPosition, Vector3 endPlayerPosition)
	{
		Clear();
		Vector3 vector = endPlayerPosition - startPlayerPosition;
		float magnitude = vector.magnitude;
		if (!(magnitude <= Mathf.Epsilon))
		{
			Vector3 vector2 = vector / magnitude;
			int num = Mathf.RoundToInt(magnitude / minSpacing);
			float num2 = magnitude / (float)num;
			float num3 = magnitude / fadeOutRate;
			float num4 = num3 / (float)num;
			playerHeadOffset -= Vector3.up * widths.y / 2f;
			startPlayerPosition += playerHeadOffset;
			endPlayerPosition += playerHeadOffset;
			for (int i = 0; i < num; i++)
			{
				AddNewPosition(startPlayerPosition + vector2 * i * num2, Vector3.up, Time.time + (float)i * num4);
			}
		}
	}
}
public class PostEffectsMaterial : UnityEngine.MonoBehaviour
{
	private int vignetteRadiusId;

	private int vignetteSoftnessId;

	private int gradientId;

	private int fadeId;

	private Renderer renderer;

	[NonSerialized]
	public Camera Camera;

	private float _vignetteIntensity;

	private float _vignetteSoftness;

	private Vector4 _gradient = new Vector4(0f, 1f, 1f, 1f);

	private float _fade = 1f;

	public float VignetteIntensity
	{
		get
		{
			return _vignetteIntensity;
		}
		set
		{
			_vignetteIntensity = value;
			renderer.material.SetFloat(vignetteRadiusId, 1f - _vignetteIntensity);
		}
	}

	public float VignetteSoftness
	{
		get
		{
			return _vignetteSoftness;
		}
		set
		{
			_vignetteSoftness = value;
			renderer.material.SetFloat(vignetteSoftnessId, _vignetteSoftness);
		}
	}

	public float Fade
	{
		get
		{
			return _fade;
		}
		set
		{
			_fade = value;
			renderer.material.SetFloat(fadeId, _fade);
		}
	}

	public void SetGradient(float startTexCoord, float endTexCoord, float startFade, float endFade)
	{
		_gradient.x = startTexCoord;
		_gradient.y = endTexCoord;
		_gradient.z = startFade;
		_gradient.w = endFade;
		renderer.material.SetVector(gradientId, _gradient);
	}

	private void Awake()
	{
		renderer = GetComponent<Renderer>();
		renderer.enabled = false;
		vignetteRadiusId = Shader.PropertyToID("_VignetteRadius");
		vignetteSoftnessId = Shader.PropertyToID("_VignetteSoftness");
		gradientId = Shader.PropertyToID("_GradientVector");
		fadeId = Shader.PropertyToID("_Fade");
		SetGradient(0f, 1f, 1f, 1f);
		VignetteIntensity = 0f;
		Fade = 0f;
	}

	private void Start()
	{
		if (Camera == null)
		{
			UnityEngine.Debug.LogError("PostEffectsMaterial missing reference to a camera.");
		}
		float num = 2f * Mathf.Tan(Camera.fieldOfView * 0.5f * ((float)Math.PI / 180f));
		float num2 = num * Camera.aspect;
		float num3 = Mathf.Sqrt(num * num + num2 * num2);
		float num4 = ((!(Camera.aspect > 1f)) ? (num3 / num2) : (num3 / num));
		num *= num4;
		num2 *= num4;
		base.transform.localScale = new Vector3(num2, num, 1f);
		CommandBuffer commandBuffer = new CommandBuffer();
		commandBuffer.name = "Draw Post Effect Quad";
		commandBuffer.DrawRenderer(renderer, renderer.material);
		Camera.AddCommandBuffer(CameraEvent.AfterImageEffects, commandBuffer);
	}

	private void LateUpdate()
	{
		if (Camera != null)
		{
			base.transform.rotation = Quaternion.LookRotation(Camera.transform.forward, Vector3.up);
		}
	}
}
public class PulsingBeam : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool gravityAligned;

	[SerializeField]
	private float scalePulseAmount;

	[SerializeField]
	private float scalePulseSpeed;

	private float startingScale;

	private void Awake()
	{
		startingScale = base.transform.localScale.x;
		scalePulseSpeed += UnityEngine.Random.Range(-0.2f, 0.2f);
	}

	private void FixedUpdate()
	{
		if (gravityAligned)
		{
			base.transform.rotation = Quaternion.LookRotation(Vector3.forward, Vector3.up);
		}
		Vector3 localScale = base.transform.localScale;
		localScale.z = (localScale.x = startingScale + Mathf.Sin(Time.time * scalePulseSpeed) * scalePulseAmount);
		base.transform.localScale = localScale;
	}
}
